-- ----------------------------
-- Table structure for active_combats
-- ----------------------------
DROP TABLE IF EXISTS `active_combats`;
CREATE TABLE `active_combats`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL COMMENT '参战角色ID',
  `target_id` int NOT NULL COMMENT '目标ID',
  `target_type` enum('npc','player','yaoguai') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'npc' COMMENT '目标类型',
  `target_current_hp` int NULL DEFAULT 0 COMMENT '目标当前血量（共享）',
  `target_max_hp` int NULL DEFAULT 0 COMMENT '目标最大血量',
  `is_friendly` tinyint(1) NULL DEFAULT 0 COMMENT '是否切磋模式',
  `combo_count` int NULL DEFAULT 0 COMMENT '连击计数',
  `started_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `combat_system` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '战斗所属系统(pantaohui/wuzhuangyuan)',
  `rank_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '神位等级',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_char`(`char_id` ASC) USING BTREE,
  INDEX `idx_target`(`target_id` ASC, `target_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 783 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '活跃战斗状态表' ROW_FORMAT = DYNAMIC;

