-- ----------------------------
-- Table structure for apprentice_requests
-- ----------------------------
DROP TABLE IF EXISTS `apprentice_requests`;
CREATE TABLE `apprentice_requests`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `from_character_id` int UNSIGNED NOT NULL COMMENT '请求者（弟子）角色ID',
  `to_character_id` int UNSIGNED NOT NULL COMMENT '目标师父ID（可为NPC）',
  `to_is_npc` tinyint(1) NULL DEFAULT 0 COMMENT '目标是否为NPC（1:NPC 0:玩家）',
  `sect_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '门派名称',
  `status` enum('pending','accepted','rejected','expired') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT '请求状态',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '请求创建时间',
  `resolved_at` datetime NULL DEFAULT NULL COMMENT '请求处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_from`(`from_character_id` ASC) USING BTREE,
  INDEX `idx_to`(`to_character_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  CONSTRAINT `fk_apprentice_requests_from_character_id` FOREIGN KEY (`from_character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_apprentice_requests_to_character_id` FOREIGN KEY (`to_character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拜师请求表' ROW_FORMAT = DYNAMIC;

