-- ----------------------------
DROP TABLE IF EXISTS `baihuling_mazes`;
CREATE TABLE `baihuling_mazes`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `maze_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '迷宫唯一标识',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `maze_type` enum('main','small') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '迷宫类型：main=主迷宫, small=小迷宫',
  `dimensions` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '迷宫维度，格式：i,j,k',
  `layout` json NOT NULL COMMENT '迷宫布局数据（三维数组）',
  `exit_room` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出口房间坐标，格式：i,j,k',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `expires_at` timestamp NULL DEFAULT NULL COMMENT '过期时间（NULL表示未设置）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_maze_id`(`maze_id` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_expires`(`expires_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '白虎岭迷宫会话表' ROW_FORMAT = DYNAMIC;

