  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `maze_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '迷宫ID',
  `current_room` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前房间坐标，格式：i,j,k',
  `collected_shelizi` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已收集的舍利子数量',
  `visited_rooms` json NULL COMMENT '已访问的房间列表（JSON数组）',
