  `quest_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `target_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标ID（NPC或物品）',
  `target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标名称',
  `object_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标物品名称',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'pending' COMMENT '状态：pending(进行中), done(完成目标), completed(已领奖), expired(已过期), abandoned(已放弃), active(取经护送)',
  `daoxing_require` int NULL DEFAULT 0 COMMENT '所需道行',
  `reward_daoxing` bigint NOT NULL DEFAULT 0,
  `reward_potential` bigint NULL DEFAULT 0 COMMENT '奖励潜能',
  `reward_silver` bigint NULL DEFAULT 0 COMMENT '奖励白银',
  `color_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '颜色祥云代码',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` timestamp NULL DEFAULT NULL,
  `quest_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '任务标识',
  `npc_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '任务发布NPC标识',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '任务开始时间',
  `complete_time` timestamp NULL DEFAULT NULL COMMENT '任务完成时间',
  `expires_at` timestamp NULL DEFAULT NULL COMMENT '任务过期时间',
  `current_stage` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '当前阶段',
  `next_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '下一位置',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_type`(`char_id` ASC, `quest_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_char_type_status`(`char_id` ASC, `quest_type` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_quest_char` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '角色任务表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_quests
-- ----------------------------

-- ----------------------------
-- Table structure for character_skill_map
-- ----------------------------
DROP TABLE IF EXISTS `character_skill_map`;
CREATE TABLE `character_skill_map`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `skill_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '技能类型（如 sword, blade, unarmed, dodge, parry, force 等）',
  `mapped_skill` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '映射的技能ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_char_skill_type`(`char_id` ASC, `skill_type` ASC) USING BTREE,
  CONSTRAINT `character_skill_map_ibfk_1` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 59 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '角色技能映射表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_skill_map
-- ----------------------------

-- ----------------------------
-- Table structure for character_skills
-- ----------------------------
DROP TABLE IF EXISTS `character_skills`;
CREATE TABLE `character_skills`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `skill_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '技能ID',
  `level` int NULL DEFAULT 1 COMMENT '技能等级',
  `exp` int NULL DEFAULT 0 COMMENT '技能经验',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_char_skill`(`char_id` ASC, `skill_id` ASC) USING BTREE,
  CONSTRAINT `character_skills_ibfk_1` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 196 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '角色技能表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_skills
-- ----------------------------

-- ----------------------------
-- Table structure for character_teams
-- ----------------------------
DROP TABLE IF EXISTS `character_teams`;
CREATE TABLE `character_teams`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `leader_id` int UNSIGNED NOT NULL COMMENT '队长角色ID',
  `member_id` int UNSIGNED NOT NULL COMMENT '成员角色ID（队长自己也是成员）',
  `status` enum('invited','joined') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'invited' COMMENT '状态：invited=已邀请待接受，joined=已加入',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_leader_member`(`leader_id` ASC, `member_id` ASC) USING BTREE,
  INDEX `idx_leader_id`(`leader_id` ASC) USING BTREE,
  INDEX `idx_member_id`(`member_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '组队系统表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_teams
-- ----------------------------

-- ----------------------------
-- Table structure for character_temp
-- ----------------------------
DROP TABLE IF EXISTS `character_temp`;
CREATE TABLE `character_temp`  (
  `char_id` int UNSIGNED NOT NULL,
  `temp_key` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `temp_value` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  PRIMARY KEY (`char_id`, `temp_key`) USING BTREE,
  CONSTRAINT `character_temp_ibfk_1` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_temp
-- ----------------------------

-- ----------------------------
-- Table structure for character_temp_states
-- ----------------------------
DROP TABLE IF EXISTS `character_temp_states`;
CREATE TABLE `character_temp_states`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'State ID',
  `char_id` int UNSIGNED NOT NULL COMMENT 'Character ID',
  `state_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'State key (e.g., suanming/paid, suanming/asked)',
  `state_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'State value (can be JSON for complex data)',
  `expire_time` timestamp NULL DEFAULT NULL COMMENT 'Expiration time (NULL = permanent until cleared)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Created time',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_char_state`(`char_id` ASC, `state_key` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 668 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Character Temporary States' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_temp_states
-- ----------------------------

-- ----------------------------
-- Table structure for character_transforms
-- ----------------------------
DROP TABLE IF EXISTS `character_transforms`;
CREATE TABLE `character_transforms`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `character_id` int UNSIGNED NOT NULL,
  `target_id` int UNSIGNED NOT NULL,
  `target_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_data` json NOT NULL,
  `start_time` int NOT NULL,
  `d_mana` float NOT NULL,
  `original_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `character_id`(`character_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of character_transforms
-- ----------------------------

-- ----------------------------
-- Table structure for characters
-- ----------------------------
DROP TABLE IF EXISTS `characters`;
CREATE TABLE `characters`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '角色ID',
  `profession` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '职业类别',
  `obstacle_qujing` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取经障碍状态:ren=取经人',
  `user_id` int UNSIGNED NOT NULL COMMENT '用户ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '角色名',
  `race` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'human' COMMENT '种族',
  `family_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '门派名称',
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'male' COMMENT '性别',
  `level` int NULL DEFAULT 1 COMMENT '等级',
  `max_gin` int NULL DEFAULT 100 COMMENT '最大精气',
  `gin` int NULL DEFAULT 100 COMMENT '当前精气',
  `max_kee` int NULL DEFAULT 100 COMMENT '最大气血',
  `kee` int NULL DEFAULT 100 COMMENT '当前气血',
  `max_sen` int NULL DEFAULT 100 COMMENT '最大神气',
  `sen` int NULL DEFAULT 100 COMMENT '当前神气',
  `str` int NULL DEFAULT 10 COMMENT '力量',
  `int` int NULL DEFAULT 10 COMMENT '悟性',
  `con` int NULL DEFAULT 10 COMMENT '根骨',
  `dex` int NULL DEFAULT 10 COMMENT '身法',
  `cor` int NULL DEFAULT 20 COMMENT '胆识',
  `cps` int NULL DEFAULT 20 COMMENT '定力',
  `per` int NULL DEFAULT 20 COMMENT '容貌',
  `spi` int NULL DEFAULT 10 COMMENT '灵性',
  `kar` int NULL DEFAULT 20 COMMENT '福缘',
  `force_factor` int NULL DEFAULT 0 COMMENT '内力系数（影响str和cps）',
  `bellicosity` int NULL DEFAULT 0 COMMENT '杀气（影响cor）',
  `last_fainted_from` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `donation` int NULL DEFAULT 0 COMMENT '捐献金额（影响kar）',
  `gift_modify` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '天赋修正 {\"str\":0,\"int\":0,\"con\":0,...}',
  `combat_exp` int NULL DEFAULT 0 COMMENT ' combat 经验',
  `potential` int NULL DEFAULT 99 COMMENT '潜能',
  `learned_points` int NULL DEFAULT 0,
  `daoxing` bigint NOT NULL DEFAULT 0,
  `deliver_food_time` datetime NULL DEFAULT NULL COMMENT '送饭时间',
  `qianziwen_time` datetime NULL DEFAULT NULL COMMENT '千字文时间',
  `daodejing_time` datetime NULL DEFAULT NULL COMMENT '道德经时间',
  `last_salary_time` datetime NULL DEFAULT NULL COMMENT '上次领俸银时间',
  `experience` int NULL DEFAULT 0 COMMENT '总经验',
  `force` int NULL DEFAULT 0 COMMENT '内力',
  `max_force` int NULL DEFAULT 0 COMMENT '最大内力',
  `maximum_force` int NULL DEFAULT NULL COMMENT '存储的最大内力基数',
  `atman` int NULL DEFAULT 0 COMMENT '灵力',
  `max_atman` int NULL DEFAULT 0 COMMENT '最大灵力',
  `mana` int NULL DEFAULT 0 COMMENT '法力',
  `max_mana` int NULL DEFAULT 0 COMMENT '最大法力',
  `maximum_mana` int NULL DEFAULT NULL COMMENT '存储的最大法力基数（用于技能升级）',
  `skills_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '技能数据 {\"skills\":{},\"learned\":{},\"skill_map\":{}}',
  `current_area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'changan' COMMENT '当前区域',
  `current_room` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'changan_center' COMMENT '当前房间',
  `following_id` int NULL DEFAULT NULL,
  `gold` int NULL DEFAULT 0 COMMENT '金币',
  `silver` int NULL DEFAULT 0 COMMENT '银币',
  `copper` int NULL DEFAULT 100 COMMENT '铜币',
  `online` tinyint(1) NULL DEFAULT 0 COMMENT '是否在线',
  `last_save` timestamp NULL DEFAULT NULL COMMENT '最后保存时间',
  `balance` int NULL DEFAULT 0 COMMENT '钱庄存款（铜钱）',
  `family` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所属门派key（对应config/sects.php中的key）',
  `master_id` int UNSIGNED NULL DEFAULT NULL COMMENT '师父角色ID',
  `master_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '师父名称',
  `generation` int NOT NULL DEFAULT 0 COMMENT '师徒代数（第几代弟子）',
  `family_enter_time` datetime NULL DEFAULT NULL COMMENT '入门时间',
  `family_privs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '门派权限JSON',
  `betrayal_count` int NOT NULL DEFAULT 0 COMMENT '背叛次数',
  `age` int NOT NULL DEFAULT 14 COMMENT '角色年龄（岁）',
  `mud_age` bigint NOT NULL DEFAULT 0 COMMENT '游戏中度过的总秒数',
  `age_modify` bigint NOT NULL DEFAULT 0 COMMENT '年龄修正秒数',
  `last_age_set` int NOT NULL DEFAULT 0 COMMENT '最后一次计算年龄的时间戳',
  `display_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '玩家选择显示的头衔',
  `added_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '自定义称号',
  `rank_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '自定义称呼',
  `food` int NOT NULL DEFAULT 0 COMMENT '当前食物值',
  `max_food` int NOT NULL DEFAULT 200 COMMENT '最大食物值',
  `water` int NOT NULL DEFAULT 0 COMMENT '当前饮水值',
  `max_water` int NOT NULL DEFAULT 200 COMMENT '最大饮水值',
  `last_sleep` int NULL DEFAULT 0,
  `sleep_state` tinyint(1) NULL DEFAULT 0,
  `sleep_end_time` int NULL DEFAULT 0,
  `eff_sen` int NULL DEFAULT 0,
  `eff_kee` int NULL DEFAULT 0,
  `couple_id` int NULL DEFAULT NULL,
  `couple_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `kee_mark` int NULL DEFAULT 0 COMMENT '杀气值',
  `max_carry_weight` int NULL DEFAULT 205 COMMENT '最大负重',
  `dntg_quest_stage` int NULL DEFAULT 0,
  `obstacle_no_qujing` tinyint NULL DEFAULT 0 COMMENT '是否禁止取经(借天魔茧后)',
  `last_ask_fabao` int NULL DEFAULT 0 COMMENT '上次借法宝时间',
  `official_rank` int NULL DEFAULT 0 COMMENT '官阶',
  `married` tinyint(1) NULL DEFAULT 0,
  `married_at` datetime NULL DEFAULT NULL,
  `unconscious_state` tinyint(1) NULL DEFAULT 0,
  `unconscious_end_time` int NULL DEFAULT 0,
  `daze_state` tinyint(1) NULL DEFAULT 0,
  `daze_end_time` int NULL DEFAULT 0,
  `near_death_time` int NULL DEFAULT 0 COMMENT '濒死时间戳，二次受伤触发死亡',
  `moral_value` int NULL DEFAULT 0 COMMENT '品德值',
  `quest_reward` int NULL DEFAULT 0 COMMENT '开封任务累计品德值(用于赴京请赏)',
  `skill_points` int NULL DEFAULT 0 COMMENT '技能点',
  `talent_points` int NULL DEFAULT 0 COMMENT '天赋点',
  `is_ghost` tinyint(1) NULL DEFAULT 0 COMMENT '鬼魂标记：0=正常, 1=鬼魂（死亡后无法离开地府）',
  `hell_enter_time` int NULL DEFAULT 0 COMMENT '进入地府的时间戳（用于穿墙冷却）',
  `obstacle/no_qujing` tinyint(1) NULL DEFAULT 0 COMMENT '是否禁止取经',
  `obstacle/qujing` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取经状态',
  `is_ai_player` tinyint(1) NULL DEFAULT 0 COMMENT '是否为AI玩家：0=否, 1=是',
  `ai_last_action` int NULL DEFAULT 0 COMMENT 'AI玩家最后动作时间戳',
  `ai_paused` tinyint(1) NULL DEFAULT 0,
  `training_state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `training_end_time` int UNSIGNED NULL DEFAULT 0,
  `poem_answered` int NOT NULL DEFAULT 0 COMMENT '诗社答对总次数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_obstacle_qujing`(`obstacle_qujing` ASC) USING BTREE,
  CONSTRAINT `characters_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 47 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏角色表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of characters
-- ----------------------------

-- ----------------------------
-- Table structure for combat
-- ----------------------------
DROP TABLE IF EXISTS `combat`;
CREATE TABLE `combat`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '战斗ID',
  `attacker_id` int UNSIGNED NOT NULL COMMENT '攻击者角色ID',
  `target_id` int UNSIGNED NOT NULL COMMENT '目标角色/NPC ID',
  `target_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'npc' COMMENT '目标类型: npc, player',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'active' COMMENT '战斗状态: active, ended, fled',
  `start_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '战斗开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '战斗结束时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_attacker`(`attacker_id` ASC) USING BTREE,
  INDEX `idx_target`(`target_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '战斗状态表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of combat
-- ----------------------------

-- ----------------------------
-- Table structure for combat_log
-- ----------------------------
DROP TABLE IF EXISTS `combat_log`;
CREATE TABLE `combat_log`  (
  `id` bigint UNSIGNED NOT NULL COMMENT '日志ID',
  `combat_id` int UNSIGNED NOT NULL COMMENT '战斗ID',
  `action_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '动作类型: attack, damage, flee, kill',
  `actor_id` int UNSIGNED NOT NULL COMMENT '执行者ID',
  `target_id` int UNSIGNED NULL DEFAULT NULL COMMENT '目标ID',
  `damage` int NULL DEFAULT 0 COMMENT '伤害值',
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '战斗消息',
  `timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间戳'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '战斗历史记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of combat_log
-- ----------------------------

-- ----------------------------
-- Table structure for combat_records
-- ----------------------------
DROP TABLE IF EXISTS `combat_records`;
CREATE TABLE `combat_records`  (
  `id` int NOT NULL,
  `challenger_id` int NOT NULL COMMENT '挑战者角色ID',
  `defender_id` int NOT NULL COMMENT '防守者角色ID',
  `winner_id` int NOT NULL COMMENT '胜利者角色ID',
  `bonus_points` int NULL DEFAULT 0 COMMENT '获胜获得的积分',
  `combat_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '比武时间',
  `rounds` int NULL DEFAULT 0 COMMENT '回合数',
  `challenger_hp_left` int NULL DEFAULT 0 COMMENT '挑战者剩余血量',
  `defender_hp_left` int NULL DEFAULT 0 COMMENT '防守者剩余血量'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '比武记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of combat_records
-- ----------------------------

-- ----------------------------
-- Table structure for combat_stats
-- ----------------------------
DROP TABLE IF EXISTS `combat_stats`;
CREATE TABLE `combat_stats`  (
  `char_id` int NOT NULL COMMENT '角色ID',
  `total_fights` int NULL DEFAULT 0 COMMENT '总比武次数',
  `wins` int NULL DEFAULT 0 COMMENT '胜利次数',
  `losses` int NULL DEFAULT 0 COMMENT '失败次数',
  `draws` int NULL DEFAULT 0 COMMENT '平局次数',
  `last_fight_time` datetime NULL DEFAULT NULL COMMENT '最后比武时间',
  `rating` int NULL DEFAULT 1000 COMMENT '积分/段位分',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '比武统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of combat_stats
-- ----------------------------

-- ----------------------------
-- Table structure for combat_vs_stats
-- ----------------------------
DROP TABLE IF EXISTS `combat_vs_stats`;
CREATE TABLE `combat_vs_stats`  (
  `id` int NOT NULL,
  `winner_id` int NOT NULL COMMENT '获胜者角色ID',
  `loser_id` int NOT NULL COMMENT '失败者角色ID',
  `bonus` int NULL DEFAULT 0 COMMENT '从该对手获得的总积分',
  `fight_count` int NULL DEFAULT 0 COMMENT '与该对手的战斗次数',
  `last_fight_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后战斗时间'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '对战统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of combat_vs_stats
-- ----------------------------

-- ----------------------------
-- Table structure for command_routes
-- ----------------------------
DROP TABLE IF EXISTS `command_routes`;
CREATE TABLE `command_routes`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `command` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `method` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'ActionRouter private static method name',
  `category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '分类标签: basic/combat/movement/item/sect/fabao/tongtian/etc',
  `description` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '命令描述',
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_command`(`command` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 182 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'ActionRouter命令路由映射表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of command_routes
-- ----------------------------

-- ----------------------------
-- Table structure for config
-- ----------------------------
DROP TABLE IF EXISTS `config`;
CREATE TABLE `config`  (
  `id` int UNSIGNED NOT NULL,
  `config_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '配置键',
  `config_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '配置值',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '配置说明',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'string' COMMENT '值类型: string, int, float, json'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of config
-- ----------------------------

-- ----------------------------
-- Table structure for container_items
-- ----------------------------
DROP TABLE IF EXISTS `container_items`;
CREATE TABLE `container_items`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `container_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'character_inventory' COMMENT '容器类型',
  `container_id` int UNSIGNED NOT NULL COMMENT '容器ID',
  `item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品ID',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '物品分类',
  `quantity` int NULL DEFAULT 1 COMMENT '数量',
  `enchantments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '附魔JSON',
  `liquid_remaining` int NULL DEFAULT NULL COMMENT '液体剩余量',
  `liquid_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '液体类型',
  `liquid_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '液体名称',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_container`(`container_type` ASC, `container_id` ASC) USING BTREE,
  INDEX `idx_item`(`item_id` ASC, `category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '容器物品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of container_items
-- ----------------------------

-- ----------------------------
-- Table structure for corpse_items
-- ----------------------------
DROP TABLE IF EXISTS `corpse_items`;
CREATE TABLE `corpse_items`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `corpse_id` int NOT NULL COMMENT '尸体ID',
  `item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品ID',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品名称',
  `quantity` int NOT NULL DEFAULT 1 COMMENT '数量',
  `item_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物品类型',
  `equipment_slot` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '装备槽',
  `is_equipped` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否曾被装备',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_corpse`(`corpse_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 684 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '尸体物品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of corpse_items
-- ----------------------------

-- ----------------------------
-- Table structure for corpses
-- ----------------------------
DROP TABLE IF EXISTS `corpses`;
CREATE TABLE `corpses`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `owner_type` enum('npc','player') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '尸体所有者类型',
  `owner_id` int NOT NULL COMMENT '所有者ID',
  `owner_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所有者名称',
  `room_area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所在区域',
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所在房间',
  `killer_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '击杀者名称',
  `killer_id` int NULL DEFAULT NULL COMMENT '击杀者ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '生成时间',
  `decay_time` datetime NOT NULL COMMENT '腐烂时间',
  `looted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已被搜刮',
  `carried` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已被背起',
  `carried_by` int NULL DEFAULT NULL COMMENT '被谁携带（玩家ID）',
  `decay_phase` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_room`(`room_area` ASC, `room_id` ASC) USING BTREE,
  INDEX `idx_owner`(`owner_type` ASC, `owner_id` ASC) USING BTREE,
  INDEX `idx_decay`(`decay_time` ASC) USING BTREE,
  INDEX `idx_carried_by`(`carried_by` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 261 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '尸体表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of corpses
-- ----------------------------

-- ----------------------------
-- Table structure for court_cases
-- ----------------------------
DROP TABLE IF EXISTS `court_cases`;
CREATE TABLE `court_cases`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `defendant_id` int UNSIGNED NOT NULL COMMENT '被告用户ID',
  `judge_id` int UNSIGNED NOT NULL COMMENT '审判官用户ID',
  `charge` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '罪名',
  `evidence` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '证据',
  `verdict` tinyint NULL DEFAULT NULL COMMENT '判决: 1-无罪释放 2-警告 3-监禁 4-封禁',
  `sentence_days` int NULL DEFAULT NULL COMMENT '刑期（天）',
  `sentence_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '判决说明',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 1-待审 2-审理中 3-已判决 4-已执行',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `judged_at` datetime NULL DEFAULT NULL,
  `executed_at` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_defendant`(`defendant_id` ASC) USING BTREE,
  INDEX `idx_judge`(`judge_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '审判记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of court_cases
-- ----------------------------

-- ----------------------------
-- Table structure for court_suspects
-- ----------------------------
DROP TABLE IF EXISTS `court_suspects`;
CREATE TABLE `court_suspects`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED NOT NULL COMMENT '用户ID',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `arrested_by` int UNSIGNED NOT NULL COMMENT '逮捕者用户ID',
  `arrest_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '逮捕时间',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '逮捕原因',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 1-待审 2-审理中 3-已释放 4-已判决',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '嫌疑人列表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of court_suspects
-- ----------------------------

-- ----------------------------
-- Table structure for deposit_storage
-- ----------------------------
DROP TABLE IF EXISTS `deposit_storage`;
CREATE TABLE `deposit_storage`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `item_id` int UNSIGNED NOT NULL COMMENT '物品ID（character_inventory表的id）',
  `item_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '物品数据JSON',
  `mark` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '记号',
  `expire_time` int UNSIGNED NOT NULL COMMENT '过期时间（Unix时间戳）',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '寄存物品存储表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of deposit_storage
-- ----------------------------

-- ----------------------------
-- Table structure for douji_bets
-- ----------------------------
DROP TABLE IF EXISTS `douji_bets`;
CREATE TABLE `douji_bets`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL,
  `char_id` int NOT NULL,
  `bet_kind` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'hg/lw',
  `bet_amount` int NOT NULL DEFAULT 0,
  `is_settled` tinyint(1) NOT NULL DEFAULT 0,
  `is_win` tinyint(1) NULL DEFAULT NULL,
  `win_amount` int NOT NULL DEFAULT 0,
  `commission` int NOT NULL DEFAULT 0,
  `coin_after` int NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE,
  INDEX `idx_settled`(`is_settled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '斗鸡房下注记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of douji_bets
-- ----------------------------

-- ----------------------------
-- Table structure for douji_rounds
-- ----------------------------
DROP TABLE IF EXISTS `douji_rounds`;
CREATE TABLE `douji_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0=空闲 1=押注中 2=斗鸡中 3=已结算',
  `hg_init_hp` int NULL DEFAULT NULL COMMENT '红冠鸡初始HP',
  `lw_init_hp` int NULL DEFAULT NULL COMMENT '绿尾鸡初始HP',
  `fight_frames` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '斗鸡所有帧HP JSON [[hg_hp,lw_hp],...]',
  `winner` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '获胜鸡代码 hg/lw/null(双败)',
  `betting_start` datetime NULL DEFAULT NULL,
  `fight_start` datetime NULL DEFAULT NULL COMMENT '斗鸡阶段开始时间',
  `settle_time` datetime NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '斗鸡房轮次状态机' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of douji_rounds
-- ----------------------------

-- ----------------------------
-- Table structure for dudaxiao_history
-- ----------------------------
DROP TABLE IF EXISTS `dudaxiao_history`;
CREATE TABLE `dudaxiao_history`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL,
  `bet_amount` int NOT NULL DEFAULT 0 COMMENT '下注金额(黄金)',
  `bet_choice` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '大/小',
  `dice_result` int NOT NULL COMMENT '骰子点数',
  `is_win` tinyint(1) NOT NULL DEFAULT 0,
  `win_amount` int NOT NULL DEFAULT 0,
  `commission` int NOT NULL DEFAULT 0,
  `gold_after` int NOT NULL DEFAULT 0 COMMENT '结算后黄金余额',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_created`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 310 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '赌大小下注历史' ROW_FORMAT = DYNAMIC;

