-- Records of exam_questions
-- ----------------------------

-- ----------------------------
-- Table structure for fabao_trap_state
-- ----------------------------
DROP TABLE IF EXISTS `fabao_trap_state`;
CREATE TABLE `fabao_trap_state`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `victim_id` int UNSIGNED NOT NULL COMMENT '被困者角色ID',
  `trapper_id` int UNSIGNED NOT NULL COMMENT '施法者角色ID',
  `fabao_item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '法宝item_id',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `trap_type` enum('trap','bind') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '困人/束缚',
  `trapped_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `release_at` timestamp NOT NULL COMMENT '预计释放时间',
  `saved_gin` int NULL DEFAULT 0,
  `saved_kee` int NULL DEFAULT 0,
  `saved_sen` int NULL DEFAULT 0,
  `saved_eff_gin` int NULL DEFAULT 0,
  `saved_eff_kee` int NULL DEFAULT 0,
  `saved_eff_sen` int NULL DEFAULT 0,
  `original_room_area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '被困前所在区域',
  `original_room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '被困前所在房间',
  `is_released` tinyint(1) NULL DEFAULT 0 COMMENT '是否已释放',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_victim`(`victim_id` ASC) USING BTREE,
  INDEX `idx_trapper`(`trapper_id` ASC) USING BTREE,
  INDEX `idx_release`(`release_at` ASC, `is_released` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '法宝困人状态表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of fabao_trap_state
-- ----------------------------

-- ----------------------------
-- Table structure for fight_requests
-- ----------------------------
DROP TABLE IF EXISTS `fight_requests`;
CREATE TABLE `fight_requests`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `from_character_id` int UNSIGNED NOT NULL COMMENT '发起者角色ID',
  `to_character_id` int UNSIGNED NOT NULL COMMENT '目标角色ID',
  `status` enum('pending','accepted','rejected','expired','cancelled','completed') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '请求创建时间',
  `resolved_at` datetime NULL DEFAULT NULL COMMENT '请求处理时间',
  `expires_at` datetime NULL DEFAULT NULL COMMENT '请求过期时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_from`(`from_character_id` ASC) USING BTREE,
  INDEX `idx_to`(`to_character_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '切磋请求表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of fight_requests
-- ----------------------------

-- ----------------------------
-- Table structure for fixed_objects
-- ----------------------------
DROP TABLE IF EXISTS `fixed_objects`;
CREATE TABLE `fixed_objects`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属房间ID (如: city/center)',
  `object_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品标识 (如: city/center_obj_table)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '物品名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '物品描述',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'fixed' COMMENT '物品类型',
  `sort_order` int NULL DEFAULT 0 COMMENT '显示顺序',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1543 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '房间固定物品表（从rooms迁移）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of fixed_objects
-- ----------------------------

-- ----------------------------
-- Table structure for friends
-- ----------------------------
DROP TABLE IF EXISTS `friends`;
CREATE TABLE `friends`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `from_character_id` int UNSIGNED NOT NULL COMMENT '发起请求的角色ID',
  `to_character_id` int UNSIGNED NOT NULL COMMENT '接收请求的角色ID',
  `status` enum('pending','accepted','rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT '状态: pending-待处理, accepted-已接受, rejected-已拒绝',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `resolved_at` timestamp NULL DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_from`(`from_character_id` ASC) USING BTREE,
  INDEX `idx_to`(`to_character_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  CONSTRAINT `fk_friends_from` FOREIGN KEY (`from_character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_friends_to` FOREIGN KEY (`to_character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '好友关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of friends
-- ----------------------------

-- ----------------------------
-- Table structure for guest_room_config
-- ----------------------------
DROP TABLE IF EXISTS `guest_room_config`;
CREATE TABLE `guest_room_config`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED NOT NULL COMMENT '用户ID',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `enter_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '进入时间',
  `release_time` datetime NULL DEFAULT NULL COMMENT '释放时间',
  `release_by` int UNSIGNED NULL DEFAULT NULL COMMENT '释放者用户ID',
  `days` int NOT NULL DEFAULT 2 COMMENT '关押天数',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原因',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态: 1-等待审核 2-已释放 3-已过期',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '欢迎室配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of guest_room_config
-- ----------------------------

-- ----------------------------
-- Table structure for gutou_bets
-- ----------------------------
DROP TABLE IF EXISTS `gutou_bets`;
CREATE TABLE `gutou_bets`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL,
  `char_id` int NOT NULL,
  `bet_kind` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'tc/sd/qx/sx',
  `bet_amount` int NOT NULL DEFAULT 0,
  `is_settled` tinyint(1) NOT NULL DEFAULT 0,
  `is_win` tinyint(1) NULL DEFAULT NULL,
  `win_amount` int NOT NULL DEFAULT 0,
  `commission` int NOT NULL DEFAULT 0,
  `coin_after` int NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE,
  INDEX `idx_settled`(`is_settled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '骨骰房下注记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of gutou_bets
