-- ----------------------------
-- Table structure for gutou_rounds
-- ----------------------------
DROP TABLE IF EXISTS `gutou_rounds`;
CREATE TABLE `gutou_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0=空闲 1=押注中 2=开骰中 3=已结算',
  `big_dice` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '头彩预告骰号 JSON [big0,big1]',
  `res_dice` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '实际开出骰号 JSON [res0,res1]',
  `winner` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '中奖类型 tc/sd/qx/sx/null(空盘)',
  `betting_start` datetime NULL DEFAULT NULL,
  `reveal_start` datetime NULL DEFAULT NULL COMMENT '开骰阶段开始时间',
  `settle_time` datetime NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '骨骰房轮次状态机' ROW_FORMAT = DYNAMIC;

