-- ----------------------------
-- Table structure for items
-- ----------------------------
DROP TABLE IF EXISTS `items`;
CREATE TABLE `items`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品名称',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'common' COMMENT '物品类型: weapon, armor, food, medicine, treasure, material',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '物品描述',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '物品分类（区域）',
  `unit` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '个' COMMENT '单位: 个、件、把、张',
  `weight` int NULL DEFAULT 0 COMMENT '重量',
  `value` int NULL DEFAULT 0 COMMENT '价值(铜钱)',
  `level` int NULL DEFAULT 1 COMMENT '等级要求',
  `armor_value` int NULL DEFAULT 0 COMMENT '防御值',
  `weapon_damage` int NULL DEFAULT 0 COMMENT '武器伤害',
  `weapon_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `material` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '材质',
  `quality` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'normal' COMMENT '品质: poor, normal, good, excellent, legendary',
  `effects` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '效果JSON',
  `no_drop` tinyint(1) NULL DEFAULT 0 COMMENT '是否不可丢弃',
  `no_sell` tinyint(1) NULL DEFAULT 0 COMMENT '是否不可出售',
  `no_store` tinyint(1) NULL DEFAULT 0 COMMENT '是否不可存放',
  `bind_on_pickup` tinyint(1) NULL DEFAULT 0 COMMENT '拾取绑定',
  `stackable` tinyint(1) NULL DEFAULT 0 COMMENT '是否可堆叠',
  `max_stack` int NULL DEFAULT 1 COMMENT '最大堆叠数',
  `food_value` int NOT NULL DEFAULT 0 COMMENT '食物恢复值（吃后恢复的食物点数）',
  `water_value` int NOT NULL DEFAULT 0 COMMENT '饮水恢复值（喝后恢复的饮水点数）',
  `armor_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '装备部位',
  `flag` int NULL DEFAULT 0 COMMENT '物品标志位',
  `female_only` tinyint(1) NULL DEFAULT 0 COMMENT '是否仅限女性',
  `no_wield` tinyint(1) NULL DEFAULT 0 COMMENT '是否不可装备武器',
  `str_bonus` int NULL DEFAULT 0 COMMENT '力量加成',
  `con_bonus` int NULL DEFAULT 0 COMMENT '体质加成',
  `dex_bonus` int NULL DEFAULT 0 COMMENT '敏捷加成',
  `int_bonus` int NULL DEFAULT 0 COMMENT '智力加成',
  `spi_bonus` int NULL DEFAULT 0 COMMENT '精神加成',
  `dodge_bonus` int NULL DEFAULT 0 COMMENT '闪避加成',
  `parry_bonus` int NULL DEFAULT 0 COMMENT '招架加成',
  `sen_heal` int NOT NULL DEFAULT 0 COMMENT '精神恢复值',
  `kee_heal` int NOT NULL DEFAULT 0 COMMENT '气血恢复值',
  `mana_heal` int NOT NULL DEFAULT 0 COMMENT '内力恢复值',
  `gin_heal` int NOT NULL DEFAULT 0,
  `force_heal` int NOT NULL DEFAULT 0,
  `fabao` tinyint(1) NULL DEFAULT 0 COMMENT '是否为法宝',
  `qi_defense` int NULL DEFAULT 0 COMMENT '气防御值',
  `shen_defense` int NULL DEFAULT 0 COMMENT '神防御值',
  `trap_type` enum('none','trap','bind') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'none' COMMENT '法宝攻击类型',
  `trap_ratio` int NULL DEFAULT 50 COMMENT '困人后属性保留比例',
  `max_durability` int NULL DEFAULT 100 COMMENT '最大耐用度',
  `is_real` tinyint(1) NULL DEFAULT 1 COMMENT '真/假法宝',
  `series_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `fake_item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '对应假法宝ID',
  `max_liquid` int NULL DEFAULT 0 COMMENT '?????????????0=?????',
  `drunk_apply` int NULL DEFAULT 0 COMMENT '酒醉值，喝酒时增加的酒醉程度',
  `is_container` tinyint(1) NULL DEFAULT 0 COMMENT '是否为容器',
  `max_items` int NULL DEFAULT 10 COMMENT '容器最大物品数量',
  `max_encumbrance` int NULL DEFAULT 0 COMMENT '容器最大负重',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_item_category`(`item_id` ASC, `category` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11712 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏物品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of items
-- ----------------------------

