DROP TABLE IF EXISTS `kaifeng_npc_config`;
CREATE TABLE `kaifeng_npc_config`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `npc_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
