  `to_char_id` int UNSIGNED NULL DEFAULT NULL COMMENT '接收者角色ID（NULL表示广播）',
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息内容',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息类型: say, chat, emote, tell, party, guild',
