-- ----------------------------
-- Table structure for mieyao_yaoguai
-- ----------------------------
DROP TABLE IF EXISTS `mieyao_yaoguai`;
CREATE TABLE `mieyao_yaoguai`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `npc_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `npc_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `daoxing` int NULL DEFAULT 0,
  `combat_exp` int NULL DEFAULT 0,
  `max_kee` int NULL DEFAULT 100,
  `max_sen` int NULL DEFAULT 100,
  `current_kee` int NULL DEFAULT 100,
  `current_sen` int NULL DEFAULT 100,
  `exp_reward` int NULL DEFAULT 0,
  `pot_reward` int NULL DEFAULT 0,
  `daoxing_reward` int NULL DEFAULT 0,
  `area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `room_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `owner_id` int NOT NULL,
  `monster_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'normal',
  `face` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '妖怪容貌描述',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` timestamp NULL DEFAULT NULL,
  `is_killed` tinyint(1) NULL DEFAULT 0,
  `killed_at` timestamp NULL DEFAULT NULL,
  `other_kee` int NULL DEFAULT 0,
  `other_sen` int NULL DEFAULT 0,
  `skills_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '妖怪技能列表JSON',
  `skill_mappings_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '技能映射JSON',
  `cast_spells_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '法术列表JSON',
  `exert_funcs_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内功列表JSON',
  `perform_actions_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '绝招列表JSON',
  `weapon_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '武器信息JSON',
  `cast_chance` int NULL DEFAULT 10 COMMENT '施法概率(%)',
  `monster_type_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '妖怪门派类型',
  `is_heaven` tinyint(1) NULL DEFAULT 0 COMMENT '是否天廷版妖怪',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_owner`(`owner_id` ASC) USING BTREE,
  INDEX `idx_room`(`area` ASC, `room_id` ASC) USING BTREE,
  INDEX `idx_expired`(`expires_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 133 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

