  `npc_id` int UNSIGNED NOT NULL COMMENT 'NPC ID',
  `item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品ID',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `equip_slot` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '装备部位: weapon, armor, head等',
  `worn` tinyint(1) NULL DEFAULT 1 COMMENT '是否已穿戴',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_npc`(`npc_id` ASC) USING BTREE,
  CONSTRAINT `npc_equipment_ibfk_1` FOREIGN KEY (`npc_id`) REFERENCES `npcs` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 3052 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'NPC装备表' ROW_FORMAT = DYNAMIC;

