  `npc_id` int UNSIGNED NOT NULL COMMENT 'NPC ID',
  `base_skill` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '基础技能名',
  `mapped_skill` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '映射招式名',
