) ENGINE = InnoDB AUTO_INCREMENT = 3368 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'NPC技能映射表' ROW_FORMAT = DYNAMIC;

