-- ----------------------------
-- Table structure for npcs
-- ----------------------------
DROP TABLE IF EXISTS `npcs`;
CREATE TABLE `npcs`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'NPC ID',
  `npc_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'NPC标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'NPC名称',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'NPC称号',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'NPC描述',
  `is_master` tinyint(1) NOT NULL DEFAULT 0 COMMENT '?????????NPC',
  `sect_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '???????ey',
  `master_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '??????',
  `apprentice_conditions` json NULL COMMENT '??????JSON',
  `rejection_messages` json NULL COMMENT '??????JSON',
  `inquiry` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '对话查询配置(JSON格式)',
  `chat_msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'Random chat messages (JSON array format)',
  `room_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '房间消息（NPC在房间中显示的话）',
  `actions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '特殊动作配置JSON',
  `race` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'human' COMMENT '种族: human, demon, god, monster',
  `class` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '职业分类: xian(神仙), bonze(和尚), taoist(道士), general(将军), scholar(书生), merchant(商人), beggar(乞丐), yaomo(妖魔), beast(兽类)',
  `family_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '门派名称',
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'male' COMMENT '性别: male, female, unknown',
  `age` int NULL DEFAULT 0 COMMENT '年龄',
  `attitude` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'friendly' COMMENT '态度: friendly, aggressive, cooperative',
  `max_gin` int NULL DEFAULT 100 COMMENT '最大精气',
  `gin` int NULL DEFAULT 100 COMMENT '当前精气',
  `max_kee` int NULL DEFAULT 100 COMMENT '最大气血',
  `kee` int NULL DEFAULT 100 COMMENT '当前气血',
  `max_sen` int NULL DEFAULT 100 COMMENT '最大神气',
  `sen` int NULL DEFAULT 100 COMMENT '当前神气',
  `str` int NULL DEFAULT 10 COMMENT '力量',
  `int` int NULL DEFAULT 10 COMMENT '悟性',
  `con` int NULL DEFAULT 10 COMMENT '根骨',
  `dex` int NULL DEFAULT 10 COMMENT '身法',
  `cor` int NULL DEFAULT 10 COMMENT '胆识',
  `cps` int NULL DEFAULT 10 COMMENT '福缘',
  `per` int NULL DEFAULT 10 COMMENT '容貌',
  `combat_exp` int NULL DEFAULT 0 COMMENT ' combat 经验',
  `daoxing` bigint NOT NULL DEFAULT 0,
  `eff_dx` int NULL DEFAULT 0 COMMENT '有效道行（用于奖励计算）',
  `nkgain` int NULL DEFAULT 0 COMMENT '基础奖励值（用于奖励计算）',
  `no_nk_reward` tinyint(1) NULL DEFAULT 0 COMMENT '是否无击杀奖励',
  `force` int NULL DEFAULT 0 COMMENT '内力',
  `max_force` int NULL DEFAULT 0 COMMENT '最大内力',
  `force_factor` int NULL DEFAULT 0 COMMENT '内力系数',
  `atman` int NULL DEFAULT 0 COMMENT '灵力',
  `max_atman` int NULL DEFAULT 0 COMMENT '最大灵力',
  `mana` int NULL DEFAULT 0 COMMENT '法力',
  `max_mana` int NULL DEFAULT 0 COMMENT '最大法力',
  `gold` int NULL DEFAULT 0 COMMENT '金币',
  `silver` int NULL DEFAULT 0 COMMENT '银币',
  `copper` int NULL DEFAULT 0 COMMENT '铜币',
  `aggressive` tinyint(1) NULL DEFAULT 0 COMMENT '是否主动攻击',
  `can_talk` tinyint(1) NULL DEFAULT 1 COMMENT '是否可以对话',
  `merchant` tinyint(1) NULL DEFAULT 0 COMMENT '是否为商人',
  `drop_items` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '掉落物品JSON',
  `spawn_area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '生成区域',
  `spawn_room` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '生成房间',
  `current_room` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前房间',
  `shop_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商店类型：hockshop/bank/vendor',
  `chat_chance` int NULL DEFAULT 0 COMMENT '??????(0-100)',
  `chat_chance_combat` int NULL DEFAULT 0 COMMENT '???????(0-100)',
  `chat_msg_combat` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '????????(JSON??)',
  `bellicosity` int NULL DEFAULT 0 COMMENT '????',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT '????',
  `last_chat_time` timestamp NULL DEFAULT NULL COMMENT '??????',
  `ride_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '骑乘消息（如\"骑上马\"）',
  `ride_dodge` int NULL DEFAULT 0 COMMENT '骑乘时增加的闪避值',
  `ride_need_train` tinyint(1) NULL DEFAULT 0 COMMENT '是否需要训练（专属坐骑）',
  `ride_female_only` tinyint(1) NULL DEFAULT 0 COMMENT '是否仅限女性骑乘',
  `ride_owner_id` int UNSIGNED NULL DEFAULT NULL COMMENT '专属坐骑所有者角色ID',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_npc_id`(`npc_id` ASC) USING BTREE,
  INDEX `idx_ride_dodge`(`ride_dodge` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2740 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏NPC表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of npcs
