-- ----------------------------
-- Table structure for obstacled
-- ----------------------------
DROP TABLE IF EXISTS `obstacled`;
CREATE TABLE `obstacled`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `haved_qujingren` tinyint NULL DEFAULT 0 COMMENT '是否已有取经人',
  `choose_qjr` tinyint NULL DEFAULT 0 COMMENT '是否在选择期',
  `this_qj_time` int NULL DEFAULT 0 COMMENT '上次产生取经人时间',
  `number` int NULL DEFAULT 0 COMMENT '参选人数',
  `min_time` int NULL DEFAULT 0 COMMENT '最短时间',
  `guan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'yingchou' COMMENT '当前关卡',
  `husong` int NULL DEFAULT NULL COMMENT '护送者ID',
  `current_qujingren_id` int NULL DEFAULT NULL COMMENT '当前取经人角色ID',
  `obstacle_fail` tinyint NULL DEFAULT 0 COMMENT '是否取经失败',
  `last_jie_id` int NULL DEFAULT NULL COMMENT '最后借天魔茧的玩家ID',
  `last_env` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最后环境',
  `open_door` tinyint NULL DEFAULT 0 COMMENT '门是否打开',
  `where_qujingren` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '取经人当前位置',
  `cated_id` int NULL DEFAULT NULL COMMENT '吃到取经人的玩家ID',
  `this_qj_time_counter` int NULL DEFAULT 0 COMMENT '取经次数',
  `qujing_times` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'JSON格式，记录各玩家失败次数',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '取经精灵全局状态表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of obstacled
-- ----------------------------

-- ----------------------------
-- Table structure for pantaohui_applications
