CREATE TABLE `pantaohui_applications`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `char_id` int NOT NULL COMMENT '申请人角色ID',
  `char_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人角色名',
  `rank_level` enum('sun','moon','metal','wood','water','fire','earth') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请的神位',
  `status` enum('pending','approved','rejected','completed') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT '申请状态',
  `apply_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
  `approve_time` datetime NULL DEFAULT NULL COMMENT '批准时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '蟠桃会申请表' ROW_FORMAT = DYNAMIC;

