-- Records of pantaohui_applications
-- ----------------------------

-- ----------------------------
-- Table structure for pantaohui_avatars
-- ----------------------------
DROP TABLE IF EXISTS `pantaohui_avatars`;
CREATE TABLE `pantaohui_avatars`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rank_level` enum('sun','moon','metal','wood','water','fire','earth') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属神位',
  `char_id` int NULL DEFAULT NULL COMMENT '玩家角色ID',
  `char_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '玩家角色名',
  `npc_id` int NULL DEFAULT NULL COMMENT '替身NPC的数据库ID',
  `npc_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '替身NPC名称',
  `room_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所在大殿',
  `status` enum('active','defeated','inactive') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `defeated_at` datetime NULL DEFAULT NULL COMMENT '被击败时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rank_level`(`rank_level` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '蟠桃会替身表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pantaohui_avatars
-- ----------------------------

-- ----------------------------
-- Table structure for pantaohui_ranks
-- ----------------------------
DROP TABLE IF EXISTS `pantaohui_ranks`;
CREATE TABLE `pantaohui_ranks`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rank_level` enum('sun','moon','metal','wood','water','fire','earth') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '七曜神位：日/月/金/木/水/火/土',
  `char_id` int NULL DEFAULT NULL COMMENT '玩家角色ID',
  `char_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '玩家角色名',
  `daoxing` bigint NOT NULL DEFAULT 0 COMMENT '玩家道行',
  `avatar_npc_id` int NULL DEFAULT NULL COMMENT '替身NPC ID',
  `status` enum('occupied','vacant','challenging') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'occupied' COMMENT '状态',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上榜时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rank_level`(`rank_level` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '蟠桃会封神榜' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pantaohui_ranks
-- ----------------------------

-- ----------------------------
-- Table structure for pig_game_rankings
-- ----------------------------
DROP TABLE IF EXISTS `pig_game_rankings`;
CREATE TABLE `pig_game_rankings`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int UNSIGNED NOT NULL,
  `total_games` int NOT NULL DEFAULT 0,
  `wins` int NOT NULL DEFAULT 0,
  `elo_rating` int NOT NULL DEFAULT 1000,
  `last_played_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_char_id`(`char_id` ASC) USING BTREE,
  CONSTRAINT `pig_game_rankings_ibfk_1` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拱猪游戏排行' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pig_game_rankings
-- ----------------------------

-- ----------------------------
-- Table structure for pig_game_records
-- ----------------------------
DROP TABLE IF EXISTS `pig_game_records`;
CREATE TABLE `pig_game_records`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int UNSIGNED NOT NULL,
  `players` json NOT NULL COMMENT '玩家信息(含AI)',
  `scores` json NOT NULL COMMENT '本局得分',
  `result` enum('win','lose') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `elo_change` int NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  CONSTRAINT `pig_game_records_ibfk_1` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拱猪游戏记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of pig_game_records
-- ----------------------------

-- ----------------------------
-- Table structure for piggy_bets
-- ----------------------------
DROP TABLE IF EXISTS `piggy_bets`;
CREATE TABLE `piggy_bets`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL,
  `char_id` int NOT NULL COMMENT '角色ID(0=NPC)',
  `char_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `seat` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'east/north/west/south',
  `is_npc` tinyint(1) NOT NULL DEFAULT 0,
  `hand_score` int NOT NULL DEFAULT 0 COMMENT '本手牌得分',
  `is_pighead` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否得猪头',
  `collected_cards` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '收的牌(JSON)',
  `sold_cards` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '卖出的牌(JSON)',
  `rank_before` int NOT NULL DEFAULT 100,
  `rank_after` int NOT NULL DEFAULT 100,
  `coin_change` int NOT NULL DEFAULT 0 COMMENT '铜钱变化',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拱猪房参与记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of piggy_bets
-- ----------------------------

-- ----------------------------
-- Table structure for piggy_rankings
-- ----------------------------
DROP TABLE IF EXISTS `piggy_rankings`;
CREATE TABLE `piggy_rankings`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL,
  `char_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `rank_points` int NOT NULL DEFAULT 100 COMMENT '等级分',
  `hands_played` int NOT NULL DEFAULT 0 COMMENT '手数',
  `heads_received` int NOT NULL DEFAULT 0 COMMENT '猪头数',
  `heads_given` int NOT NULL DEFAULT 0 COMMENT '给他人猪头数',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_rank`(`rank_points` DESC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拱猪排行榜' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of piggy_rankings
-- ----------------------------

-- ----------------------------
-- Table structure for piggy_rounds
-- ----------------------------
DROP TABLE IF EXISTS `piggy_rounds`;
CREATE TABLE `piggy_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `room_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'city/piggy_n' COMMENT '房间ID',
  `game_mode` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'normal' COMMENT 'normal=普通 partner=搭档',
  `status` int NOT NULL DEFAULT 0 COMMENT '0=等人 1=等发牌 2=等卖牌 3=出牌 4=算分',
  `status_changed_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `seats` json NULL COMMENT '四个座位信息',
  `game_state` json NULL COMMENT '完整游戏状态(手牌/桌面/卖牌等)',
  `scoring` json NULL COMMENT '积分信息',
  `pig_owner` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `full_collector` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `result_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '本局结果摘要',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拱猪房轮次' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of piggy_rounds
-- ----------------------------

-- ----------------------------
-- Table structure for player_homes
-- ----------------------------
DROP TABLE IF EXISTS `player_homes`;
CREATE TABLE `player_homes`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `owner_id` int NOT NULL,
  `spouse_id` int NULL DEFAULT NULL,
  `room_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '小家',
  `room_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `bed_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '一张温馨的小床',
  `bed_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `max_items` int NULL DEFAULT 20,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_owner`(`owner_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of player_homes
-- ----------------------------

-- ----------------------------
-- Table structure for poem_answers
-- ----------------------------
DROP TABLE IF EXISTS `poem_answers`;
CREATE TABLE `poem_answers`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL,
  `char_id` int NOT NULL,
  `char_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `answer_text` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `is_correct` tinyint(1) NOT NULL DEFAULT 0,
  `reward_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'daoxing/potential/literate',
  `reward_amount` int NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '诗社答题记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of poem_answers
-- ----------------------------

-- ----------------------------
-- Table structure for poem_rounds
-- ----------------------------
DROP TABLE IF EXISTS `poem_rounds`;
CREATE TABLE `poem_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `poem_id` int NOT NULL COMMENT '诗词ID',
  `poem_author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '作者(冗余)',
  `poem_title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '诗题(冗余)',
  `poem_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '完整诗词JSON(冗余)',
  `line_index` int NOT NULL COMMENT '选中行索引',
  `first_part` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '上句',
  `second_part` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '下句',
  `answer` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '正确答案(去空格逗号)',
  `scrambled` varchar(400) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '打乱后的题目',
  `is_answered` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已答对',
  `answered_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '答对者姓名',
  `is_current` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=当前题 0=上一题',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_current`(`is_current` ASC) USING BTREE,
  INDEX `idx_poem`(`poem_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 179 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '诗社猜诗轮次' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of poem_rounds
-- ----------------------------

-- ----------------------------
-- Table structure for poems
-- ----------------------------
DROP TABLE IF EXISTS `poems`;
CREATE TABLE `poems`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '作者',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '诗题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '诗句JSON数组',
  `line_count` int NOT NULL DEFAULT 0 COMMENT '诗句行数',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 320 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '乐府诗社诗词库' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of poems
-- ----------------------------

-- ----------------------------
-- Table structure for position_fees
-- ----------------------------
DROP TABLE IF EXISTS `position_fees`;
CREATE TABLE `position_fees`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '角色ID',
  `stock_id` int NOT NULL,
  `position_type` enum('long','short') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `position_value` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `fee_amount` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `fee_rate` decimal(10, 6) NOT NULL DEFAULT 0.000100,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_created`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '持仓手续费记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of position_fees
-- ----------------------------

-- ----------------------------
-- Table structure for positions
-- ----------------------------
DROP TABLE IF EXISTS `positions`;
CREATE TABLE `positions`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '角色ID',
  `stock_id` int NOT NULL,
  `type` enum('long','short') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'long',
  `quantity` int NOT NULL DEFAULT 0,
  `avg_price` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_stock_type`(`user_id` ASC, `stock_id` ASC, `type` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '股票持仓' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of positions
-- ----------------------------

-- ----------------------------
-- Table structure for posts
-- ----------------------------
DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `board_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `author` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `author_id` int UNSIGNED NULL DEFAULT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `post_number` int NOT NULL,
  `post_time` int UNSIGNED NOT NULL,
  `reply_to` int UNSIGNED NULL DEFAULT NULL,
  `view_count` int NULL DEFAULT 0,
  `is_pinned` tinyint(1) NULL DEFAULT 0,
  `is_locked` tinyint(1) NULL DEFAULT 0,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_board_id`(`board_id` ASC) USING BTREE,
  INDEX `idx_post_number`(`board_id` ASC, `post_number` ASC) USING BTREE,
  INDEX `idx_author`(`author` ASC) USING BTREE,
  INDEX `idx_post_time`(`post_time` ASC) USING BTREE,
  INDEX `idx_reply_to`(`reply_to` ASC) USING BTREE,
  INDEX `idx_board_post_num`(`board_id` ASC, `post_number` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10854 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of posts
-- ----------------------------

-- ----------------------------
-- Table structure for quest_cache
-- ----------------------------
DROP TABLE IF EXISTS `quest_cache`;
CREATE TABLE `quest_cache`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `char_id` int UNSIGNED NOT NULL,
  `quest_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quest_index` int NOT NULL,
  `cached_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_type_index`(`char_id` ASC, `quest_type` ASC, `quest_index` ASC) USING BTREE,
  CONSTRAINT `fk_quest_cache_char` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '任务缓存表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quest_cache
-- ----------------------------

-- ----------------------------
-- Table structure for quest_definitions
-- ----------------------------
DROP TABLE IF EXISTS `quest_definitions`;
CREATE TABLE `quest_definitions`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `quest_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `daoxing_range` int NOT NULL COMMENT '道行范围',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `target_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `object_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `amount` int NULL DEFAULT 1,
  `reward_daoxing` int NULL DEFAULT NULL,
  `reward_potential` int NULL DEFAULT NULL,
  `reward_silver` int NULL DEFAULT NULL,
  `color_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_type_daoxing`(`quest_type` ASC, `daoxing_range` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1261 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '任务定义表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quest_definitions
-- ----------------------------

-- ----------------------------
-- Table structure for quest_stats
-- ----------------------------
DROP TABLE IF EXISTS `quest_stats`;
CREATE TABLE `quest_stats`  (
  `char_id` int UNSIGNED NOT NULL,
  `total_quests` int NULL DEFAULT 0 COMMENT '总完成任务数',
  `kill_times` int NULL DEFAULT 0 COMMENT '杀怪任务次数',
  `give_times` int NULL DEFAULT 0 COMMENT '给予任务次数',
  `ask_times` int NULL DEFAULT 0 COMMENT '询问任务次数',
  `weapon_times` int NULL DEFAULT 0 COMMENT '武器任务次数',
  `armor_times` int NULL DEFAULT 0 COMMENT '盔甲任务次数',
  `cloth_times` int NULL DEFAULT 0 COMMENT '衣服任务次数',
  `food_times` int NULL DEFAULT 0 COMMENT '食物任务次数',
  `kill_reward` int NULL DEFAULT 0 COMMENT '杀怪任务总奖励',
  `give_reward` int NULL DEFAULT 0 COMMENT '给予任务总奖励',
  `ask_reward` int NULL DEFAULT 0 COMMENT '询问任务总奖励',
  `weapon_reward` int NULL DEFAULT 0 COMMENT '武器任务总奖励',
  `armor_reward` int NULL DEFAULT 0 COMMENT '盔甲任务总奖励',
  `cloth_reward` int NULL DEFAULT 0 COMMENT '衣服任务总奖励',
  `food_reward` int NULL DEFAULT 0 COMMENT '食物任务总奖励',
  `total_daoxing_gained` bigint NOT NULL DEFAULT 0,
  `total_potential_gained` int NULL DEFAULT 0 COMMENT '总获得潜能',
  `total_silver_gained` int NULL DEFAULT 0 COMMENT '总获得白银',
  `quest_colors` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '颜色祥云数据（JSON）',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `wearing_times` int NULL DEFAULT 0 COMMENT '穿戴任务次数',
  `wearing_reward` int NULL DEFAULT 0 COMMENT '穿戴任务总奖励',
  `misc_times` int NULL DEFAULT 0 COMMENT '杂项任务次数',
  `misc_reward` int NULL DEFAULT 0 COMMENT '杂项任务总奖励',
  PRIMARY KEY (`char_id`) USING BTREE,
  CONSTRAINT `fk_quest_stats_char` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '任务统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quest_stats
-- ----------------------------

-- ----------------------------
-- Table structure for quests
-- ----------------------------
DROP TABLE IF EXISTS `quests`;
CREATE TABLE `quests`  (
  `id` int UNSIGNED NOT NULL COMMENT '任务ID',
  `quest_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '任务描述',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'main' COMMENT '任务类型: main, side, daily, event',
  `level_required` int NULL DEFAULT 1 COMMENT '等级要求',
  `objectives` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '任务目标JSON',
  `reward_exp` int NULL DEFAULT 0 COMMENT '经验奖励',
  `reward_potential` int NULL DEFAULT 0 COMMENT '潜能奖励',
  `reward_money` int NULL DEFAULT 0 COMMENT '金钱奖励',
  `reward_items` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '物品奖励JSON',
  `start_npc` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '起始NPC',
  `end_npc` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '结束NPC'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏任务表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of quests
-- ----------------------------

-- ----------------------------
-- Table structure for qujing_applicants
-- ----------------------------
DROP TABLE IF EXISTS `qujing_applicants`;
CREATE TABLE `qujing_applicants`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL COMMENT '参选玩家ID',
  `char_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '参选玩家名称',
  `apply_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '参选时间',
  `sequence` int NOT NULL COMMENT '参选顺序',
  `fail_count` int NULL DEFAULT 0 COMMENT '失败次数',
  `apply_date` date NULL DEFAULT NULL COMMENT '参选日期',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `daoxing` int NULL DEFAULT 0 COMMENT '道行',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'pending' COMMENT '状态: pending/winner/loser',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_apply_date`(`apply_date` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '取经护送参选者表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of qujing_applicants
-- ----------------------------

-- ----------------------------
-- Table structure for qujing_failures
-- ----------------------------
DROP TABLE IF EXISTS `qujing_failures`;
CREATE TABLE `qujing_failures`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL COMMENT '玩家ID',
  `fail_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '失败时间',
  `quest_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '失败的关卡ID',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_fail_time`(`fail_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '取经失败记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of qujing_failures
-- ----------------------------

-- ----------------------------
-- Table structure for qujing_history
-- ----------------------------
DROP TABLE IF EXISTS `qujing_history`;
CREATE TABLE `qujing_history`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL COMMENT '玩家ID',
  `quest_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关卡ID',
  `complete_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '完成时间',
  `reward` int NULL DEFAULT 0 COMMENT '奖励道行',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_quest_id`(`quest_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '取经完成历史表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of qujing_history
-- ----------------------------

-- ----------------------------
-- Table structure for qujing_quests
-- ----------------------------
DROP TABLE IF EXISTS `qujing_quests`;
CREATE TABLE `qujing_quests`  (
  `id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关卡ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关卡名称',
  `min_daoxing` int NOT NULL COMMENT '最低道行要求',
  `init_room` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '初始房间',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '关卡描述',
  `quest_steps` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `npc_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `success_msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '成功消息',
  `time_limit` int NULL DEFAULT 3600 COMMENT '时间限制(秒)',
  `reward` int NULL DEFAULT 0 COMMENT '奖励道行',
  `boss_npc_id` int NULL DEFAULT NULL COMMENT 'Boss NPC ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `important_items` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `weapons` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `food` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `other_items` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `quest_order` int NULL DEFAULT 0 COMMENT '关卡顺序',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '完整内容（原始文本）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '取经关卡定义表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of qujing_quests
-- ----------------------------

-- ----------------------------
-- Table structure for qujingren_configs
-- ----------------------------
DROP TABLE IF EXISTS `qujingren_configs`;
CREATE TABLE `qujingren_configs`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `npc_id` int NOT NULL COMMENT 'NPC ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '陈玄奘' COMMENT '取经人名称',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '三藏法师' COMMENT '称谓',
  `current_quest` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'yingchou' COMMENT '当前关卡',
  `escort_id` int NULL DEFAULT NULL COMMENT '护送者ID',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'waiting' COMMENT '状态: waiting/active/captured/defeated',
  `captured_time` timestamp NULL DEFAULT NULL COMMENT '被捕获时间',
  `rescue_deadline` timestamp NULL DEFAULT NULL COMMENT '救援截止时间',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_npc_id`(`npc_id` ASC) USING BTREE,
  INDEX `idx_state`(`state` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '取经人NPC配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of qujingren_configs
-- ----------------------------

-- ----------------------------
-- Table structure for recharge_logs
-- ----------------------------
DROP TABLE IF EXISTS `recharge_logs`;
CREATE TABLE `recharge_logs`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `package_id` int NOT NULL DEFAULT 0 COMMENT '套餐ID',
  `package_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '套餐名称',
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '充值金额（元）',
  `silver_money` int NOT NULL DEFAULT 0 COMMENT '获得银票数量',
  `gold_bonus` int NOT NULL DEFAULT 0 COMMENT '赠送黄金数量',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT '充值状态：pending/success/failed',
  `recharge_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '充值时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_recharge_time`(`recharge_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '充值记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of recharge_logs
-- ----------------------------

-- ----------------------------
-- Table structure for redeem_codes
-- ----------------------------
DROP TABLE IF EXISTS `redeem_codes`;
CREATE TABLE `redeem_codes`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '兑换码',
  `type` enum('item','exp','potential','gold','silver','custom') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'item' COMMENT '奖励类型',
  `reward_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '奖励数据（JSON格式）',
  `max_uses` int NOT NULL DEFAULT 1 COMMENT '最大使用次数（0为无限）',
  `used_count` int NOT NULL DEFAULT 0 COMMENT '已使用次数',
  `expire_at` datetime NULL DEFAULT NULL COMMENT '过期时间（NULL为永不过期）',
  `is_active` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `unique_code`(`code` ASC) USING BTREE,
  INDEX `idx_active`(`is_active` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '兑换码表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of redeem_codes
-- ----------------------------

-- ----------------------------
-- Table structure for redeem_logs
-- ----------------------------
DROP TABLE IF EXISTS `redeem_logs`;
CREATE TABLE `redeem_logs`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL COMMENT '角色ID',
  `code_id` int NOT NULL COMMENT '兑换码ID',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '兑换码',
  `reward_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '奖励类型',
  `reward_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '奖励描述',
  `redeemed_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_code_id`(`code_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '兑换记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of redeem_logs
-- ----------------------------

-- ----------------------------
-- Table structure for room_actions
-- ----------------------------
DROP TABLE IF EXISTS `room_actions`;
CREATE TABLE `room_actions`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '动作ID',
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '房间完整路径 (如: changan/eside5)',
  `action_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '动作名称 (如: 挖蚯蚓, 垂钓)',
  `action_cmd` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '触发动作命令 (如: wa qiuyin, diao)',
  `action_type` enum('special','movement','commerce','npc_task','link') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'special' COMMENT '动作类型: special=特殊动作, movement=移动, commerce=商业(存取款/买卖), npc_task=NPC任务, link=外链跳转',
  `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '动作描述',
  `sort_order` int NULL DEFAULT 0 COMMENT '显示顺序',
  `enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `handler_class` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Handler class name (optional)',
  `config` json NULL COMMENT 'Extra config parameters (JSON format)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_room_id`(`room_id` ASC) USING BTREE,
  INDEX `idx_action_type`(`action_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 155 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '房间特殊动作表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_actions
-- ----------------------------

-- ----------------------------
-- Table structure for room_default_items
-- ----------------------------
DROP TABLE IF EXISTS `room_default_items`;
CREATE TABLE `room_default_items`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `room_id` int UNSIGNED NOT NULL COMMENT '房间ID',
  `item_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '物品ID',
  `quantity` int NOT NULL DEFAULT 1 COMMENT '默认数量',
  `respawn_minutes` int NOT NULL DEFAULT 60 COMMENT '刷新间隔(分钟)',
  `last_respawn` datetime NULL DEFAULT NULL COMMENT '上次刷新时间',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_room_id`(`room_id` ASC) USING BTREE,
  INDEX `idx_item_id`(`item_id` ASC) USING BTREE,
  INDEX `idx_last_respawn`(`last_respawn` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '房间默认物品配置 - 对应LPC的set(objects)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_default_items
-- ----------------------------

-- ----------------------------
-- Table structure for room_exits
-- ----------------------------
DROP TABLE IF EXISTS `room_exits`;
CREATE TABLE `room_exits`  (
  `id` int UNSIGNED NOT NULL,
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '房间标识 (area/room)',
  `direction` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '方向',
  `target_area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '目标区域',
  `target_room` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '目标房间',
  `door_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '门名称(如:石门、南天门)',
  `door_closed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '门是否关闭(0=开,1=关)'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '房间出口原始数据表(LPC导入)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_exits
-- ----------------------------

-- ----------------------------
-- Table structure for room_item_descs
-- ----------------------------
DROP TABLE IF EXISTS `room_item_descs`;
CREATE TABLE `room_item_descs`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '房间ID (如 dntg/hgs/bank)',
  `item_key` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品关键词 (如 paizi)',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品显示名称 (如 小牌子)',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '查看时的描述文本',
  `enabled` tinyint(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_room_item`(`room_id` ASC, `item_key` ASC) USING BTREE,
  INDEX `idx_room_id`(`room_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '房间物品描述表(LPC item_desc)' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_item_descs
-- ----------------------------

-- ----------------------------
-- Table structure for room_items
-- ----------------------------
DROP TABLE IF EXISTS `room_items`;
CREATE TABLE `room_items`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `room_id` int UNSIGNED NOT NULL COMMENT '房间ID',
  `item_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '物品名称（可从items获取）',
  `item_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品标识',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `quantity` int NOT NULL DEFAULT 1 COMMENT '数量',
  `dropped_at` datetime NULL DEFAULT NULL COMMENT '丢弃时间',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '物品描述（可从items获取）',
  `enchantments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `liquid_remaining` int NULL DEFAULT 0,
  `liquid_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `liquid_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_room`(`room_id` ASC) USING BTREE,
  CONSTRAINT `room_items_ibfk_1` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 383 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '房间固定物品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_items
-- ----------------------------

-- ----------------------------
-- Table structure for room_resources
-- ----------------------------
DROP TABLE IF EXISTS `room_resources`;
CREATE TABLE `room_resources`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Resource ID',
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Room ID (e.g., changan/eside5)',
  `resource_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'worm' COMMENT 'Resource type (worm, herb, etc.)',
  `resource_count` int UNSIGNED NOT NULL DEFAULT 10 COMMENT 'Current resource count',
  `target_count` int UNSIGNED NOT NULL DEFAULT 10 COMMENT 'Target count after regeneration',
  `max_count` int UNSIGNED NOT NULL DEFAULT 10 COMMENT 'Maximum resource count',
  `last_harvest_time` timestamp NULL DEFAULT NULL COMMENT 'Last harvest time',
  `regenerate_time` timestamp NULL DEFAULT NULL COMMENT 'Time when resource will be fully regenerated',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT 'Is active',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Updated time',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_room_id`(`room_id` ASC) USING BTREE,
  INDEX `idx_resource_type`(`resource_type` ASC) USING BTREE,
  INDEX `idx_regenerate_time`(`regenerate_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Room Resources for Digging/Harvesting' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_resources
-- ----------------------------

-- ----------------------------
-- Table structure for room_states
-- ----------------------------
DROP TABLE IF EXISTS `room_states`;
CREATE TABLE `room_states`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `room_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `state_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `room_path`(`room_path` ASC, `state_key` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of room_states
-- ----------------------------

-- ----------------------------
-- Table structure for rooms
-- ----------------------------
DROP TABLE IF EXISTS `rooms`;
CREATE TABLE `rooms`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '房间ID',
  `area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '区域名称 (如: changan, moon)',
  `room_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '房间标识 (文件名)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '房间短描述/名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '房间长描述',
  `outdoors` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'normal' COMMENT '房间类型: normal, shop, home, dungeon',
  `light` tinyint NULL DEFAULT 1 COMMENT '亮度: 0-黑暗, 1-明亮',
  `no_fight` tinyint(1) NULL DEFAULT 0 COMMENT '是否禁止战斗',
  `no_magic` tinyint(1) NULL DEFAULT 0 COMMENT '是否禁止法术',
  `sleep_room` tinyint(1) NULL DEFAULT 0 COMMENT '是否为睡眠房间',
  `water_room` tinyint(1) NULL DEFAULT 0 COMMENT '是否为水下房间',
  `special_events` json NULL COMMENT '????????? (JSON???)',
  `if_bed` tinyint(1) NULL DEFAULT 0,
  `has_water_source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '??????(NULL=?? water=???, spring=???, alcohol=??',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_area_room`(`area` ASC, `room_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4147 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏地图房间表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of rooms
-- ----------------------------

-- ----------------------------
-- Table structure for saigui_bets
-- ----------------------------
DROP TABLE IF EXISTS `saigui_bets`;
CREATE TABLE `saigui_bets`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL,
  `char_id` int NOT NULL,
  `bet_kind` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'cs/qn/bl',
  `bet_amount` int NOT NULL DEFAULT 0,
  `is_settled` tinyint(1) NOT NULL DEFAULT 0,
  `is_win` tinyint(1) NULL DEFAULT NULL,
  `win_amount` int NOT NULL DEFAULT 0,
  `commission` int NOT NULL DEFAULT 0,
  `coin_after` int NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE,
  INDEX `idx_settled`(`is_settled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '赛龟房下注记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of saigui_bets
-- ----------------------------

-- ----------------------------
-- Table structure for saigui_rounds
-- ----------------------------
DROP TABLE IF EXISTS `saigui_rounds`;
CREATE TABLE `saigui_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0=空闲 1=押注中 2=赛跑中 3=已结算',
  `positions` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '三龟当前格数 JSON [0,0,0]',
  `race_frames` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '赛跑所有帧位置JSON',
  `final_positions` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最终格数 JSON',
  `winner` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '获胜龟代码 cs/qn/bl/null(无赢家)',
  `winner_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '无赢家原因',
  `betting_start` datetime NULL DEFAULT NULL,
  `race_start` datetime NULL DEFAULT NULL,
  `last_tick` datetime NULL DEFAULT NULL COMMENT '上次赛跑tick时间',
  `settle_time` datetime NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '赛龟房轮次状态机' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of saigui_rounds
-- ----------------------------

-- ----------------------------
-- Table structure for sanhua_bounties
-- ----------------------------
DROP TABLE IF EXISTS `sanhua_bounties`;
CREATE TABLE `sanhua_bounties`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `target_id` int UNSIGNED NOT NULL COMMENT '被悬赏玩家ID',
  `target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '被悬赏玩家名称',
  `target_id_str` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '被悬赏玩家ID字符串（用于兼容）',
  `amount` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '赏金总额（两黄金）',
  `last_add_time` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '上次追加赏金的时间戳',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `target_id`(`target_id` ASC) USING BTREE,
  INDEX `target_id_str`(`target_id_str` ASC) USING BTREE,
  INDEX `amount`(`amount` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '三花堂悬赏列表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sanhua_bounties
-- ----------------------------

-- ----------------------------
-- Table structure for sanhua_bounty_logs
-- ----------------------------
DROP TABLE IF EXISTS `sanhua_bounty_logs`;
CREATE TABLE `sanhua_bounty_logs`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '类型：add/claim/expire',
  `target_id` int UNSIGNED NOT NULL COMMENT '被悬赏玩家ID',
  `target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '被悬赏玩家名称',
  `sponsor_id` int UNSIGNED NULL DEFAULT NULL COMMENT '悬赏者ID',
  `sponsor_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '悬赏者名称',
  `amount` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '金额（两黄金）',
  `claimer_id` int UNSIGNED NULL DEFAULT NULL COMMENT '领取赏金者ID',
  `claimer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '领取赏金者名称',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `type`(`type` ASC) USING BTREE,
  INDEX `target_id`(`target_id` ASC) USING BTREE,
  INDEX `sponsor_id`(`sponsor_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '三花堂悬赏日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sanhua_bounty_logs
-- ----------------------------

-- ----------------------------
-- Table structure for sect_members
-- ----------------------------
DROP TABLE IF EXISTS `sect_members`;
CREATE TABLE `sect_members`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `character_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `sect_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '门派名称',
  `sect_rank` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '外门弟子' COMMENT '门派等级',
  `join_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  `is_active` tinyint(1) NULL DEFAULT 1 COMMENT '是否有效（1:有效 0:已离开）',
  `contribution` int NULL DEFAULT 0 COMMENT '门派贡献度',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_character`(`character_id` ASC) USING BTREE,
  INDEX `idx_sect`(`sect_name` ASC) USING BTREE,
  INDEX `idx_active`(`is_active` ASC) USING BTREE,
  CONSTRAINT `fk_sect_members_character_id` FOREIGN KEY (`character_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '门派成员表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sect_members
-- ----------------------------

-- ----------------------------
-- Table structure for shaizi_bets
-- ----------------------------
DROP TABLE IF EXISTS `shaizi_bets`;
CREATE TABLE `shaizi_bets`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL,
  `char_id` int NOT NULL COMMENT '角色ID(0=NPC)',
  `char_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `bet_amount` int NOT NULL DEFAULT 0 COMMENT '下注金额(铜钱)',
  `is_dealer` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否庄家',
  `point1` int NULL DEFAULT NULL COMMENT '骰子1',
  `point2` int NULL DEFAULT NULL COMMENT '骰子2',
  `point` int NULL DEFAULT NULL COMMENT '点数(100+面值=对子, 模10=散点)',
  `point_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '点数名称',
  `is_win` tinyint(1) NULL DEFAULT NULL COMMENT '是否赢(庄家为NULL)',
  `win_amount` int NOT NULL DEFAULT 0 COMMENT '赢取金额',
  `roll_order` int NOT NULL DEFAULT 0 COMMENT '掷骰顺序',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '骰子房下注记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of shaizi_bets
-- ----------------------------

-- ----------------------------
-- Table structure for shaizi_rounds
-- ----------------------------
DROP TABLE IF EXISTS `shaizi_rounds`;
CREATE TABLE `shaizi_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `dealer_char_id` int NOT NULL DEFAULT 0 COMMENT '庄家角色ID(0=NPC)',
  `dealer_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '庄家名称',
  `dealer_deposit` int NOT NULL DEFAULT 0 COMMENT '庄家保证金(铜钱)',
  `max_bet` int NOT NULL DEFAULT 2000 COMMENT '赌注上限(铜钱)',
  `total_bet` int NOT NULL DEFAULT 0 COMMENT '总下注额(铜钱)',
  `dealer_bet` int NOT NULL DEFAULT 0 COMMENT '庄家下注额',
  `status` int NOT NULL DEFAULT 0 COMMENT '0=等待庄家 1=下注中 2=掷骰中 3=已结算',
  `status_changed_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `roll_results` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '掷骰结果JSON(动画用)',
  `dealer_point1` int NULL DEFAULT NULL COMMENT '庄家骰子1',
  `dealer_point2` int NULL DEFAULT NULL COMMENT '庄家骰子2',
  `dealer_point` int NULL DEFAULT NULL COMMENT '庄家点数',
  `dealer_point_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '庄家点数名称',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '骰子房轮次' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of shaizi_rounds
-- ----------------------------

-- ----------------------------
-- Table structure for shop_items
-- ----------------------------
DROP TABLE IF EXISTS `shop_items`;
CREATE TABLE `shop_items`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `shop_id` int UNSIGNED NOT NULL COMMENT '商店ID',
  `item_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物品ID',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `price` int NULL DEFAULT 0 COMMENT '售价',
  `stock` int NULL DEFAULT -1 COMMENT '库存 (-1表示无限)',
  `sold_at` datetime NULL DEFAULT NULL COMMENT '玩家出售物品入库时间，3天后自动清除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_shop_item`(`shop_id` ASC, `item_id` ASC, `category` ASC) USING BTREE,
  CONSTRAINT `fk_shop_npc` FOREIGN KEY (`shop_id`) REFERENCES `npcs` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1525 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商店商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of shop_items
-- ----------------------------

-- ----------------------------
-- Table structure for shop_refresh
-- ----------------------------
DROP TABLE IF EXISTS `shop_refresh`;
CREATE TABLE `shop_refresh`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `shop_id` int NOT NULL,
  `is_bookstore` tinyint(1) NOT NULL DEFAULT 0,
  `max_books` int NOT NULL DEFAULT 30,
  `book_count` int NOT NULL DEFAULT 0,
  `last_refresh_time` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `shop_id`(`shop_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '书店库存限制表' ROW_FORMAT = DYNAMIC;

