-- ----------------------------
-- Table structure for skill_actions
-- ----------------------------
DROP TABLE IF EXISTS `skill_actions`;
CREATE TABLE `skill_actions`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `skill_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `action_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `action_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `min_level` int NULL DEFAULT 0,
  `action_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `dodge_mod` int NULL DEFAULT 0,
  `parry_mod` int NULL DEFAULT 0,
  `damage` int NULL DEFAULT 0,
  `damage_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `parry_msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `parry_power` int NULL DEFAULT 0,
  `force_cost` int NULL DEFAULT 0,
  `mana_cost` int NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_skill_id`(`skill_id` ASC) USING BTREE,
  CONSTRAINT `fk_skill_id` FOREIGN KEY (`skill_id`) REFERENCES `skills` (`skill_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 10011 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of skill_actions
-- ----------------------------

-- ----------------------------
-- Table structure for skills
-- ----------------------------
DROP TABLE IF EXISTS `skills`;
CREATE TABLE `skills`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `skill_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '技能标识',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '技能名称',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'martial' COMMENT '技能类型: martial, magic, force, dodge, parry',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `school` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '技能描述',
  `max_level` int NULL DEFAULT 100 COMMENT '最大等级',
  `level_required` int NULL DEFAULT 1 COMMENT '等级要求',
  `daoxing_required` int NULL DEFAULT 0 COMMENT '道行要求',
  `combat_exp_required` int NULL DEFAULT 0 COMMENT ' combat 经验要求',
  `prerequisite_skills` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '前置技能JSON',
  `effects` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '技能效果JSON',
  `formula` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '计算公式',
  `base_dodge` int NULL DEFAULT 0,
  `base_parry` int NULL DEFAULT 0,
  `base_damage` int NULL DEFAULT 0,
  `damage_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `valid_learn` json NULL,
  `practice_config` json NULL,
  `valid_enable` json NULL,
  `level_desc` json NULL,
  `exp_factor` float NULL DEFAULT 1,
  `source_file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_skill_id`(`skill_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 233 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏技能表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of skills
-- ----------------------------

-- ----------------------------
-- Table structure for sleep_invitations
-- ----------------------------
DROP TABLE IF EXISTS `sleep_invitations`;
CREATE TABLE `sleep_invitations`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `from_char_id` int UNSIGNED NOT NULL COMMENT '发起邀请的角色ID',
  `to_char_id` int UNSIGNED NOT NULL COMMENT '被邀请的角色ID',
  `status` enum('pending','accepted','rejected','expired') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'pending' COMMENT '邀请状态',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `expire_at` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `resolved_at` datetime NULL DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_to_char`(`to_char_id` ASC) USING BTREE,
  INDEX `idx_from_char`(`from_char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_expire_at`(`expire_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '双人睡眠邀请表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sleep_invitations
-- ----------------------------

-- ----------------------------
-- Table structure for stocks
-- ----------------------------
DROP TABLE IF EXISTS `stocks`;
CREATE TABLE `stocks`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `symbol` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `price` decimal(10, 2) NOT NULL DEFAULT 100.00,
  `previous_price` decimal(10, 2) NOT NULL DEFAULT 100.00,
  `volatility` decimal(5, 4) NOT NULL DEFAULT 0.0200,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `symbol`(`symbol` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '股票信息' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of stocks
-- ----------------------------

-- ----------------------------
-- Table structure for tianmojian_borrows
-- ----------------------------
DROP TABLE IF EXISTS `tianmojian_borrows`;
CREATE TABLE `tianmojian_borrows`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `char_id` int NOT NULL COMMENT '借用者ID',
  `borrow_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '借用时间',
  `return_deadline` timestamp NULL DEFAULT NULL COMMENT '归还截止时间',
  `is_returned` tinyint NULL DEFAULT 0 COMMENT '是否已归还',
  `return_time` timestamp NULL DEFAULT NULL COMMENT '归还时间',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_is_returned`(`is_returned` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '天魔茧借用记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tianmojian_borrows
-- ----------------------------

