-- Table structure for tianwang_teleport
-- ----------------------------
DROP TABLE IF EXISTS `tianwang_teleport`;
CREATE TABLE `tianwang_teleport`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `char_id` int UNSIGNED NOT NULL,
  `area` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `room_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `room_name` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '',
  `saved_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE
