-- Records of tianwang_teleport
-- ----------------------------

-- ----------------------------
-- Table structure for trades
-- ----------------------------
DROP TABLE IF EXISTS `trades`;
CREATE TABLE `trades`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '交易ID',
  `char_id` int UNSIGNED NOT NULL COMMENT '角色ID',
  `pair` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交易对，如 BTC, ETH',
  `direction` enum('up','down') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方向：up=买涨，down=买跌',
  `amount` int NOT NULL COMMENT '下注金额',
  `interval_minutes` int NOT NULL COMMENT '时间周期（分钟）',
  `open_price` decimal(15, 4) NULL DEFAULT NULL COMMENT '开仓价格',
  `close_price` decimal(15, 4) NULL DEFAULT NULL COMMENT '平仓价格',
  `expire_time` datetime NOT NULL COMMENT '到期时间',
  `status` enum('pending','win','lose') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '状态：pending=待结算，win=盈利，lose=亏损',
  `profit` int NULL DEFAULT 0 COMMENT '利润，正数为盈利，负数为亏损',
  `settled_at` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_expire_time`(`expire_time` ASC) USING BTREE,
  INDEX `idx_char_status`(`char_id` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_trades_char_id` FOREIGN KEY (`char_id`) REFERENCES `characters` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '加密货币交易记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of trades
-- ----------------------------

-- ----------------------------
-- Table structure for transactions
-- ----------------------------
DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '角色ID',
  `stock_id` int NOT NULL,
  `type` enum('buy','sell','short','cover') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `quantity` int NOT NULL DEFAULT 0,
  `price` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `profit_loss` decimal(10, 2) NULL DEFAULT 0.00,
  `fee` decimal(10, 2) NOT NULL DEFAULT 0.00,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_created`(`created_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '股票交易记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of transactions
-- ----------------------------

-- ----------------------------
-- Table structure for user_blocks
-- ----------------------------
DROP TABLE IF EXISTS `user_blocks`;
CREATE TABLE `user_blocks`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int UNSIGNED NOT NULL,
  `block_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'chat/pk/trade/move',
  `blocked_by` int UNSIGNED NOT NULL,
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_block`(`user_id` ASC, `block_type` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '功能级封禁表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_blocks
-- ----------------------------

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户名',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '密码(加密)',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '手机号',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态: 0-禁用, 1-正常, 2-封禁',
  `vip_level` int NULL DEFAULT 0 COMMENT 'VIP等级',
  `register_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `last_login` timestamp NULL DEFAULT NULL COMMENT '最后登录时间',
  `last_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '最后登录IP',
  `wizard_level` int NULL DEFAULT 0 COMMENT '巫师等级: 0-普通玩家, 1-巫师, 2-管理员',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '游戏用户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of users
-- ----------------------------

-- ----------------------------
-- Table structure for variables
-- ----------------------------
DROP TABLE IF EXISTS `variables`;
CREATE TABLE `variables`  (
  `var_key` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `value` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`var_key`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '游戏变量存储表，用于存储各种临时游戏状态和配置' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of variables
-- ----------------------------

-- ----------------------------
-- Table structure for wuzhuangyuan_avatars
-- ----------------------------
DROP TABLE IF EXISTS `wuzhuangyuan_avatars`;
CREATE TABLE `wuzhuangyuan_avatars`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rank_level` enum('gold','silver','copper','iron','tin') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属榜次',
  `rank_position` int NOT NULL COMMENT '排名',
  `char_id` int NOT NULL COMMENT '玩家角色ID',
  `char_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '玩家角色名',
  `npc_id` int NOT NULL COMMENT '替身NPC的数据库ID',
  `npc_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '替身NPC名称',
  `status` enum('active','defeated','inactive') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `defeated_at` datetime NULL DEFAULT NULL COMMENT '被击败时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rank_avatar`(`rank_level` ASC, `rank_position` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '武状元替身表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wuzhuangyuan_avatars
-- ----------------------------

-- ----------------------------
-- Table structure for wuzhuangyuan_ranks
-- ----------------------------
DROP TABLE IF EXISTS `wuzhuangyuan_ranks`;
CREATE TABLE `wuzhuangyuan_ranks`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rank_level` enum('gold','silver','copper','iron','tin') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '榜次级别：金/银/铜/铁/锡',
  `rank_position` int NOT NULL COMMENT '排名：1=状元/榜眼/探花，2=榜眼/第二名，3=探花/第三名',
  `char_id` int NULL DEFAULT NULL COMMENT '玩家角色ID',
  `char_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '玩家角色名',
  `daoxing` bigint NOT NULL DEFAULT 0 COMMENT '玩家道行',
  `avatar_npc_id` int NULL DEFAULT NULL COMMENT '替身NPC ID',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上榜时间',
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_rank_position`(`rank_level` ASC, `rank_position` ASC) USING BTREE,
  INDEX `idx_char_id`(`char_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '武状元排榜表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wuzhuangyuan_ranks
-- ----------------------------

