-- ----------------------------
-- Table structure for yaqian_bets
-- ----------------------------
DROP TABLE IF EXISTS `yaqian_bets`;
CREATE TABLE `yaqian_bets`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `round_id` int NOT NULL COMMENT '所属轮次ID',
  `char_id` int NOT NULL COMMENT '角色ID',
  `bet_kind` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '押签种类 dqq/dkq/xqq/xkq/qq/kq',
  `bet_amount` int NOT NULL DEFAULT 0 COMMENT '下注金额(铜钱)',
  `is_settled` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已结算',
  `is_win` tinyint(1) NULL DEFAULT NULL COMMENT '是否中奖',
  `win_amount` int NOT NULL DEFAULT 0 COMMENT '赔付总额(含本金)',
  `commission` int NOT NULL DEFAULT 0 COMMENT '手续费',
  `coin_after` int NULL DEFAULT NULL COMMENT '结算后铜钱余额',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_round`(`round_id` ASC) USING BTREE,
  INDEX `idx_char`(`char_id` ASC) USING BTREE,
  INDEX `idx_settled`(`is_settled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '押签房下注记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yaqian_bets
-- ----------------------------

-- ----------------------------
-- Table structure for yaqian_rounds
-- ----------------------------
DROP TABLE IF EXISTS `yaqian_rounds`;
CREATE TABLE `yaqian_rounds`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0=空闲 1=押注中 2=开奖中 3=已结算',
  `signs` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '5签结果，0=坤签 1=乾签',
  `win_kind` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '中奖种类 dqq/dkq/xqq/xkq/qq/kq',
  `betting_start` datetime NULL DEFAULT NULL COMMENT '押注阶段开始时间',
  `draw_start` datetime NULL DEFAULT NULL COMMENT '开奖阶段开始时间',
  `settle_time` datetime NULL DEFAULT NULL COMMENT '结算时间',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '押签房轮次状态机' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of yaqian_rounds
-- ----------------------------

