INSERT INTO `emotes` VALUES (1, 'smile', '微笑', 'snowcat', '$N不知道想到了什么高兴的事，一个人不住地傻笑。', '$P觉得这世间的一切都那么美好，禁不住露出了微笑。', '$N愉快地微笑着。', '$P愉快地微笑着。', '$P对着$n愉快地微笑着。', '$N愉快地对着$p微笑着。', '$N愉快地对着$n微笑着。', 1, 0, '2026-06-27 19:54:51');
INSERT INTO `emotes` VALUES (2, 'laugh', '', 'cglaem', '$N想了半天也没明白自己哪里就好笑了。', '$P想了半天也没明白自己哪里就好笑了。', '$N似乎恍然大悟，捧腹大笑起来。', '$P似乎恍然大悟，捧腹大笑起来。', '$P看着$n，捧腹大笑起来。', '$N看着$p，捧腹大笑起来。', '$N看着$n，捧腹大笑起来。', 1, 0, '2026-08-05 06:26:46');
INSERT INTO `emotes` VALUES (3, 'cry', '', 'mon', '$N想到伤心处，忍不住放声大哭。', '$P忍不住放声大哭。哇呜．．．', '$N想到伤心处，忍不住放声大哭。', '$P忍不住放声大哭。哇呜．．．', '$P趴在$n的肩膀上伤心地哭了起来。', '$N趴在$p的肩膀上伤心地哭了起来。', '$N趴在$n的肩膀上伤心地哭了起来。', 1, 0, '2026-08-05 06:26:44');
INSERT INTO `emotes` VALUES (4, 'hug', '', 'mon', '$N轻轻地拥着自己，似乎有点孤独的样子。', '$P轻轻地拥着自己，显露出孤寂的表情。', '$N很愉快地想要拥抱所有的东西。', '$P觉得世界真是美好，每样东西都值得$P拥抱。', '$P轻轻地拥着$n。', '$N轻轻地拥着$p。', '$N轻轻地拥着$n。', 1, 0, '2026-08-05 06:26:42');
INSERT INTO `emotes` VALUES (5, 'kiss', '', 'snowcat', '$N大叫：你再碰我一下，我宰了你！', '$P大叫：你再碰我一下，我宰了你！', '$N向空中打了个飞吻。', '$P向空中打了个飞吻。', '$P轻轻地亲了$n一下，好深情呦．．．', '$N轻轻地亲了$p一下，好深情呦．．．', '$N轻轻地亲了$n一下，好深情呦．．．', 1, 0, '2026-08-05 06:26:41');
INSERT INTO `emotes` VALUES (6, 'bow', '鞠躬', 'bula', '$N拱手作揖，很有礼貌地致敬！说：在下$N！请多指教！', '$P拱手作揖，很有礼貌地致敬！', '$N弯下身深深一鞠躬！', '$P弯下身鞠躬！', '$P拱手作揖，很有礼貌地致敬！', '$N拱手作揖，很有礼貌地对$p说：在下$N！请多指教！', '$N拱手作揖，很有礼貌地对$n说：在下$N！请多指教！', 1, 0, '2026-08-05 06:26:15');
INSERT INTO `emotes` VALUES (7, 'wave', '', 'snowcat', '$N着急地挥着手，想要解释清楚？', '$P着急地挥着手，想要解释清楚。', '$N挥了挥手。', '$P挥挥手。', '$P对着$n挥了挥手。', '$N对着$p挥了挥手。', '$N对着$n挥了挥手。', 1, 0, '2026-08-05 06:26:41');
INSERT INTO `emotes` VALUES (8, 'nod', '', 'snowcat', '$N对着镜子点了点头。', '$P对着镜子点了点头。', '$N点了点头。', '$P点了点头。', '$P对着$n点了点头。', '$N对着$p点了点头。', '$N对着$n点了点头。', 1, 0, '2026-08-05 06:26:40');
INSERT INTO `emotes` VALUES (9, 'shake', '', 'snowcat', '$N对着自己摇了摇头。', '$P对着自己摇了摇头。', '$N摇了摇头。', '$P摇了摇头。', '$P对着$n摇了摇头。', '$N对着$p摇了摇头。', '$N对着$n摇了摇头。', 1, 0, '2026-08-05 06:26:38');
INSERT INTO `emotes` VALUES (10, 'angry', '', 'mon', '$N脸上青一块紫一块！好像非常生气！', '$P脸上青一块紫一块！好像非常生气！', '$N小嘴翘得老高，满脸的不高兴。', '$P作出生气的表情！', '$P很生气地看着$n。', '$N很生气地看着$p。', '$N很生气地看着$n。', 1, 0, '2026-08-05 06:26:38');
INSERT INTO `emotes` VALUES (11, 'shy', '', 'joy', '$N不好意思地转过脸道：\"大庭广众之下，哎呀，真丢人！\"', '$P不好意思地转过脸道：\"大庭广众之下，哎呀，真丢人！\"', '$N转过脸道：\"大庭广众之下，真丢人！\"', '$P转过脸道：\"大庭广众之下，真丢人！\"', '$P看了看$n，转过脸道：\"大庭广众之下，哎呀，多丢人呢！\"', '$N看了看你，转过脸道：\"大庭广众之下，哎呀，多丢人呢！\"', '$N看了看$n，转过脸道：\"大庭广众之下，哎呀，多丢人呢！\"', 1, 0, '2026-08-05 06:26:36');
INSERT INTO `emotes` VALUES (12, 'qmarry', '', 'pickle', '$N伤心极了：“没人愿嫁给我，看来只有自己嫁自己了。”\r', '$P伤心极了：“没人愿嫁给我，看来只有自己嫁自己了。”\r', '$N幽幽地说道：“谁愿嫁给我呢？”\r', '$P幽幽地说道：“谁愿嫁给我呢？”\r', '$P向$n勇敢地跪了下来：“你愿意嫁给我吗？”－－真是勇气可嘉啊！\r', '$N向$p勇敢地跪了下来：“你愿意嫁给我吗？”－－真是勇气可嘉啊！\r', '$N向$n勇敢地跪了下来：“你愿意嫁给我吗？”－－真是勇气可嘉啊！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (13, 'greet', '', 'mon', '$N跟自己打招呼，有这种人？\r', '$P跟自己打招呼，好久不见？！？\r', '$N愉快地向在场的所有人打招呼。\r', '$P愉快地向在场的所有人打招呼。\r', '$P愉快地跟$n打招呼。\r', '$N愉快地跟$p打招呼。\r', '$N跟$n打招呼。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (14, '?', '疑惑', 'snowcat', '$N一脸的迷茫，不知道周围发生了什么事。\r', '$P对自己的举动感到疑惑。\r', '$N的脸上露出疑惑的表情。\r', '$P的脸上露出疑惑的表情。\r', '$P很疑惑地看着$n。\r', '$N用很疑惑的眼神看着$p。\r', '$N很疑惑地看着$n。\r', 1, 0, '2026-05-23 03:59:12');
INSERT INTO `emotes` VALUES (15, 'idiot', '', 'bula', '$N使劲敲了敲自己脑门，想道：我什么时候起这么蠢了？\r', '$P直觉得奇怪：我怎么会这么蠢呢？\r', '$N看起来一脸痴呆的样子。\r', '$P突然觉得自己从没像现在这么愚蠢过。\r', '$P无情地耻笑$n的愚蠢。\r', '$N无情地耻笑$p的痴呆。\r', '$N毫不留情地耻笑$n的愚昧。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (16, 'shicha', '视察', 'ajax', '$N向着欢迎$P的人群频频招手：同志们辛苦了！\r', '你向着欢迎你的人群频频招手：同志们辛苦了！\r', '$N一边视察，一边不住口的夸赞：搞的不错嘛，啊，搞的不错嘛！\r', '你一边视察，一边不住口的夸赞：搞的不错嘛，啊，搞的不错嘛！\r', '你严肃认真的对$n敬了个礼：“为人民服务！”\r', '$N严肃认真的对你敬了个礼：“为人民服务！”\r', '$N严肃认真的对$n敬了个礼：“为人民服务！”\r', 1, 0, '2026-05-23 04:01:19');
INSERT INTO `emotes` VALUES (17, 'waiting', '', 'cglaem', '$N说道：$s去去就来，咱们接着再聊。\r', '$P说道：别走，我们等会ㄦ再聊。\r', '$N喃喃自语道：海枯石烂，天荒地老，我都在这里等着你。。。  \r', '$P对自己说：海枯石烂，天荒地老，我都会等下去的。 \r', '$P深情地对$n说道：一年三百六十五天，一天二十四小时，每分每秒我都在这里等着你。。。  \r', '$N深情地对$p说道：一年三百六十五天，一天二十四小时，每分每秒我都在这里等着你。。。  \r', '$N深情地对$n说道：一年三百六十五天，一天二十四小时，每分每秒我都在这里等着你。。。  \r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (18, 'ya', '得意', 'weiqi', '$N似乎很得意的沾沾自喜！\r', '$P似乎很得意的样子！\r', '$N得意地打了个响指：哈哈！\r', '$P得意地打了个响指：哈哈！\r', '$P冲着$n得意地打了个响指：哈哈！\r', '$N冲着$p得意地打了个响指：哈哈！\r', '$N冲着$n得意地打了个响指：哈哈！\r', 1, 0, '2026-05-23 04:03:03');
INSERT INTO `emotes` VALUES (19, 'grin2', '', 'bula', '$N嘿嘿一笑：王大，法大，不如$s的拳头大，山后的猕猴桃都归$s了，不服的上来比划比划！\r', '$P对自己说：脸黑皮厚才有猕猴桃吃，关键时刻，岂可让步！\r', '$N正色道：公道自在人心，尔等是非之徒，跳梁小丑，终会有报！！！\r', '$P感叹道：天下好人还是多！\r', '$P对$n大喊：“都是你害我，要是我二表弟在，我也不怕你！”\r', '$N对$p大喊：“别以为我怕你，要是我二表弟在，叫你吃不了兜着走！！”\r', '$N冲着$n大喊：“你这是讥讽我生不逢辰、命运太糟么？好，$s今后若有三长两短，头痛发烧、腰酸足麻、喷嚏咳嗽，一切惟你是问。”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (20, 'escape', '', 'cglaem', '$N自言自语道：我还是三十六计。。。走为上。\r', '$P自言自语道：我还是三十六计。。。走为上。\r', '$N脚底抹油，一声不吭地溜了。\r', '$P脚底抹油，一声不吭地溜了。\r', '$P对$n附耳道：好汉不吃眼前亏，还是赶紧溜吧。\r', '$N对$p附耳道：好汉不吃眼前亏，还是赶紧溜吧。\r', '$N对$n附耳道：好汉不吃眼前亏，还是赶紧溜吧。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (21, 'nobeauty', '', 'dream', '$N豪迈地说道：大丈夫何患无妻。\r', '$P疼痛难忍，心道：“原来女子都是害人精，美丽的会害人，难看的也一样叫我吃苦。”\r', '$N突然想母亲的话，冲口而出：“我妈妈跟我说，越是美貌的女子，良心越坏，越会骗人，叫我要加意小心提防。”\r', '$P突然想母亲的话，冲口而出：“我妈妈跟我说，越是美貌的女子，良心越坏，越会骗人，叫我要加意小心提防。”\r', '$P疼痛难忍，心道：“原来女子都是害人精，美丽的会害人，难看的$n也一样叫我吃苦。”\r', '$N静静的看着$p，慢慢的说道：“女子都是害人精，难看的也一样，我要加意小心提防。”\r', '$N静静的看着$n，隔了良久，慢慢的说道：“我妈妈跟我说，越是美貌的女子，良心越坏，越会骗人，叫我要加意小心提防。”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (22, 'hammer', '', 'pickle', '$N举起好大好大的铁锤，不小心砸到自己的脚上。 :(\r', '$P举起好大好大的铁锤想去敲人，却不小心砸到自己的脚上。 :(\r', '$N举起好大好大的铁锤，到处寻找目标。\r', '$P举起好大好大的铁锤，到处寻找目标。\r', '$P举起好大好大的铁锤往$n头上用力一敲！*** 『 锵！』 ***  ( 500000000 Pt).\r', '$N举起好大好大的铁锤！哇！\r　　　　　　　　　　　　　　　　　　　　 *****************.\r　　　　　　　　　　　　　　　　　　　　 *               *.\r往你头上用力一敲！　　　　　　　　　　　 *  500000000 Pt *.\r　　　　　　　　　　　　　　　　　　　　 *               *.\r*** 『 锵 ！』 ***                       *****************.\r　　　　　　　　　　　　　　　　　　　　　　　　| |.\r　　　　　　　　　　　　　　　　　　　　　　　　| |.\r你看到好多好多美丽的蝴蝶飞来飞去！　　　　　　　| |.\r　　　　　　　　　　　　　　　　　　　　　　　　|_|.\r\r', '$N举起好大好大的铁锤往$n头上用力一敲！*** 『 锵！』 *** $n表情呆滞！从他的眼神你彷佛看到．．． **** 5000000000 Pt ****\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (23, 'wave2', '', 'cglaem', '$N伸出食指，往里勾了勾：喂！你，过来！\r', '$P伸出食指，往里勾了勾：喂！你，过来！\r', '$N跳起来拼命地招动双手，也不知道是在叫谁。\r', '$P跳起来拼命地招动双手，也不知道是在叫谁。\r', '$P冲着$n伸出食指，往里勾了勾：喂！你，过来！\r', '$N冲着$p伸出食指，往里勾了勾：喂！你，过来！\r', '$N冲着$n伸出食指，往里勾了勾：喂！你，过来！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (24, 'notell', '', 'bula', '$N神秘兮兮地笑了笑，道：“天机不可泄露！”\r', '$P神秘兮兮地笑了笑，道：“天机不可泄露！”\r', '$N不置可否地道：“难说！”\r', '$P不置可否地道：“难说！”\r', '$P白了$n一眼，道：就算$s知道也不会告诉你的。\r', '$N瞪了你一眼，道：就算$s知道也不会告诉你的。\r', '$N白了$n一眼，道：就算$s知道也不会告诉你的。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (25, 'nip', '', 'snowcat', '$N两眼瞪圆，鸭子一般伸长脖子，双手将自己一把死死掐住。\r', '$P两眼瞪圆，鸭子一般伸长脖子，双手将自己一把死死掐住。\r', '$N劈胸抓住自己的衣领，伸长脖子狂喊：$s要掐人啦！！！\r', '$P劈胸抓住自己的衣领，伸长脖子狂喊：$s要掐人啦！！！\r', '$P上前劈胸将$n一把抓住，两眼瞪圆，呲牙咧嘴地将$n往死里掐。\r', '$N上前劈胸将$p一把抓住，两眼瞪圆，呲牙咧嘴地将$p往死里掐。\r', '$N上前劈胸将$n一把抓住，两眼瞪圆，呲牙咧嘴地将$n往死里掐。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (26, 'nosorry', '', 'mon', '$N咬了咬牙，狠狠地说道：“大丈夫一人做事一人当！事情我已经做下了，要杀要剐随你们来，要我道歉，没门儿！”\r', '你咬了咬牙，狠狠地说道：“大丈夫一人做事一人当！事情我已经做下了，要杀要剐随你们来，要我道歉，没门儿！”\r', '$N理直气壮地说：“我没有干对不起任何人的事！”\r', '你理直气壮地说：“我没有干对不起任何人的事！”\r', '你皱了皱眉，对$n说道：“事已经做下了，还道歉怎地？难道别人真的会因为这两句对不起而原谅你吗？”\r', '$N皱了皱眉，对你说道：“事已经做下了，还道歉怎地？难道别人真的会因为这两句对不起而原谅你吗？”\r', '$N皱了皱眉，对$n说道：“事已经做下了，还道歉怎地？难道别人真的会因为这两句对不起而原谅你吗？”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (27, 'wink', '眨眼', 'mon', '$N眨眨眼！一对会说话的眼睛闪闪动人！\r', '$P眨眨眼！\r', '$N眨眨眼！一对会说话的眼睛闪闪动人！\r', '$P眨眨眼！\r', '$P用迷人的眼眸对$n眨了眨眼！\r', '$N用迷人的眼眸对$p眨了眨眼！\r', '$N用迷人的眼眸对$n眨了眨眼！\r', 1, 0, '2026-05-23 04:03:42');
INSERT INTO `emotes` VALUES (28, 'norose', '', 'crab', '$N鼻子里冷冷地哼了一声，“这些蔫蔫的玫瑰，谁希罕！”\r', '你鼻子里冷冷地哼了一声，“这些蔫蔫的玫瑰，谁希罕！”\r', '$N鼻子里冷冷地哼了一声，“$s爱吃，爱玩，就是不爱这些花，少来这套！”\r', '你鼻子里冷冷地哼了一声，“$s爱吃，爱玩，就是不爱这些花，少来这套！”\r', '你朝$n冷笑一声，“谁希罕你这些玫瑰，$s没情绪，少来这套！”\r', '$N朝你冷笑一声，“谁希罕你这些玫瑰，$s没情绪，少来这套！”\r', '$N朝$n冷笑一声，“谁希罕你这些玫瑰，$s没情绪，少来这套！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (29, 'chan', '馋', 'mon', '$N馋得直流口水。\r', '$P馋得直流口水。\r', '$N馋的口水都流出来了。\r', '$P馋的口水都流出来了。\r', '$P两眼紧紧盯着$n，馋得直流口水。\r', '$N两眼紧紧盯着$p，馋得直流口水。\r', '$N两眼紧紧盯着$n，馋得直流口水。\r', 1, 0, '2026-05-23 04:03:26');
INSERT INTO `emotes` VALUES (30, 'recall', '', 'cold', '$N看着大家有说有笑，转而向隅，竭力想回忆起些什么。\r', '$P看着大家有说有笑，转而向隅，竭力想回忆起些什么。\r', '$N想起昔日亲密的伙伴。\r', '$P想起昔日亲密的伙伴。\r', '$P望着窗外细雨淅淅，想起昔日在村头泥潭里和$n捉泥鳅的情形，不由得双眼朦胧。\r', '$N望着窗外细雨淅淅，想起昔日在村头泥潭里和你捉泥鳅的情形，不由得双眼朦胧。\r', '$N望着窗外细雨淅淅，想起昔日在村头泥潭里和$n捉泥鳅的情形，不由得双眼朦胧。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (31, 'ok', '好吧', 'snowcat', '$N自言自语地说：“好吧！”\r', '$P自言自语地说：“好吧！”\r', '$N歪头想了会，说道：好吧！\r', '$P歪头想了会，说道：好吧！    \r', '$P对$n痛快地说道：“好吧！”\r', '$N对$p痛快地说道：“好吧！”\r', '$N对$n痛快地说道：“好吧！”\r', 1, 0, '2026-05-23 04:05:04');
INSERT INTO `emotes` VALUES (32, 'noshame', '', 'xlb', '$N挺了挺胸，神气地说：$s我最厉害，你们没一个是我的对手。\r', '你挺了挺胸，神气地说：$s我最厉害，你们没一个是我的对手。\r', '$N挺了挺胸，神气地说：$s我最厉害，你们没一个是我的对手。\r', '你挺了挺胸，神气地说：$s我最厉害，你们没一个是我的对手。\r', '你挺了挺胸，神气地对$n说：那当然啦。\r', '$N挺了挺胸，神气地对你说：那当然啦。\r', '$N挺了挺胸，神气地对$n说：那当然啦。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (33, 'beg', '', 'april', '$N篷头垢面，鼻涕邋塌地跪在地上，手拿半截砖头照自己胸脯上狠狠地拍着，嘴里大喊：“行好吧老爷太太～～”\r', '$P篷头垢面，鼻涕邋塌地跪在地上，手拿半截砖头照自己胸脯上狠狠地拍着，嘴里大喊：“行好吧老爷太太～～”\r', '$N披头散发地跪在地上，捣蒜一样地向众人磕头说：“各位大爷大娘，赏两文酒钱吧！”\r', '$P披头散发地跪在地上，捣蒜一样地向众人磕头说：“各位大爷大娘，赏两文酒钱吧！”\r', '$P抱住$n的两腿，一把鼻涕一把泪地说：“这位$R，您行行好，救救俺这没钱的$c吧！”\r', '$N抱住$p的两腿，一把鼻涕一把泪地说：“这位$R，您行行好，救救俺这没钱的$c吧！”\r', '$N抱住$n的两腿，一把鼻涕一把泪地说：“这位$R，您行行好，救救俺这没钱的$c吧！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (34, 'great', '', 'pickle', '$N忽然老泪纵横地说：好，好，好，$s说好就是好！\r', '$P乐癫癫地说：好，好，好，$s说好就是好！\r', '$N热泪盈眶地说：好，好，好！\r', '$P癫癫地说：好，好，好！\r', '$P泣不成声地抱着$n说：好你个$r真有出息哇！$s总算盼到了这一天呐！\r', '$N泣不成声地抱着$p说：好你个$r真有出息哇！$s总算盼到了这一天呐！\r', '$N泣不成声地抱着$n说：好你个$r真有出息哇！$s总算盼到了这一天呐！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (35, 'nolove', '', 'cold', '$N满脸尴尬，身子往後一缩：我头光服异怎相陪。。。\r', '$P满脸尴尬，身子往後一缩：我头光服异怎相陪。。。\r', '$N劝告大家：色字头上一把刀，此物最是害人不浅。\r', '$P劝告大家：色字头上一把刀，此物最是害人不浅。\r', '$P幽幽地看了一眼$n：我枕剩衾闲何不睡？\r', '$N幽幽地看了$p一眼：我枕剩衾闲何不睡？\r', '$N幽幽地看了$n一眼：我枕剩衾闲何不睡？\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (36, 'u&me', '', 'snowcat', '$N仰天狂笑道：我也没指望你们这帮俗人能识得我$N！\r', '$P仰天狂笑道：我也没指望你们这帮俗人能识得我$N！\r', '$N仰天狂笑道：难道这天底下就没人识得我$N么？！\r', '$P仰天狂笑道：难道这天底下就没人识得我$N么？！\r', '$P豪情万丈地说道：知我者，$n也！\r', '$N豪情万丈地说道：知我者，$n也！\r', '$N豪情万丈地说道：知我者，$n也！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (37, 'wow', '佩服', 'bula', '$N对自己佩服的五体投地，一付等着别人拍马屁的模样。\r', '$P对自己佩服极了，恨不能拜自己为师。\r', '“哇赛”，$N吃惊的叫了起来。\r', '“哇赛”，$P吃惊的叫了起来。\r', '“哇赛”，$P对着$n吃惊的叫了起来，一付不能相信的样子。\r', '“哇赛”，$N对着$p吃惊的叫了起来，好象要拍你马屁的样子。\r', '“哇赛”，$N对着$n吃惊的叫了起来，一付不能相信的样子。\r', 1, 0, '2026-06-27 20:13:45');
INSERT INTO `emotes` VALUES (38, 'poke', '', 'dream', '“啊～啊嗤～～”$N擤了擤鼻子，“干嘛呀？行了，行了，别捅了，啊～啊嗤～～”\r', '“啊～啊嗤～～”$P擤了擤鼻子，“干嘛呀？行了，行了，别捅了，啊～啊嗤～～”\r', '$N挥舞着一根桂树枝左捅捅，右捅捅：喂，都醒醒，$S来了。\r', '$P挥舞着一根桂树枝左捅捅，右捅捅：喂，都醒醒，$S来了。\r', '$P用一根桂树枝捅了捅$n的鼻子：喂，醒醒，$S来了。\r', '$N用一根桂树枝捅了捅$p的鼻子：喂，醒醒，$S来了。\r', '$N用一根桂树枝捅了捅$n的鼻子：喂，醒醒，$S来了。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (39, 'agree', '', 'mon', '$N对於自己的看法感到非常有成就感。\r', '$P完全同意$P自己的看法。\r', '$N完全同意。\r', '$P完全同意。\r', '$P完全同意$n的看法。\r', '$N完全同意$p的看法。\r', '$N完全同意$n的看法。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (40, 'mailto2', '', 'ajax', '$N痴痴的望着门外飘落的雪花，自言自语道：他怎么还不给我回信呢．．．\r', '你痴痴的望着门外飘落的雪花，自言自语道：他怎么还不给我回信呢．．．\r', '$N把写好的情书封进信封，自言自语道：寄给谁好呢？\r', '你把写好的情书封进信封，自言自语道：寄给谁好呢？\r', '你对着$n无限凄婉的唱道：谁看了我给你写的信，谁把它丢在风里~~~~\r', '$N对着你无限凄婉的唱道：谁看了我给你写的信，谁把它丢在风里~~~~\r', '$N对着$n无限凄婉的唱道：谁看了我给你写的信，谁把它丢在风里~~~~\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (41, 'poor', '', 'pickle', '$N喊道：“凭什么我就不如别人？大家都是俩肩膀顶个脑袋！我除了目不识丁、手无缚鸡之力、衣来伸手饭来张口之外，又有哪点跟别人不同了？”\r', '你看到别人的富贵，自己的贫穷，感到万般不平。\r', '$N捏着一把钱，一把鼻涕一把泪地嚎道：“我王老五从来没见过这么多的钱哪！好不容易到手，又要我交出去，真是要了我的老命啦！”\r', '$P这一生中从来没有过过好日子，想着想着就哭了起来。\r', '$P觉得自己这么穷，只有$P吃$n才是天经地义的。\r', '$N小心翼翼地护住腰包，反过来打$p的主意了。快溜吧！\r', '$N赶紧挡住腰包，对$n求饶道：“$R您可千万别搞错了，$S穷得响叮当呀！这腰包看起来鼓鼓的，其实里面可都是树叶子呀！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (42, 'fear', '', 'mon', '$N得意地笑了起来：哈哈，怕了吧！\r', '$P得意地笑了起来：哈哈，怕了吧！\r', '$N面露怯色，好象在害怕什麽。\r', '$P突然觉得莫名的恐惧！\r', '$P被$n吓坏了。\r', '$N被$p吓坏了。\r', '$N被$n吓坏了。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (43, 'nomatch', '', 'cold', '$N浴朝阳，饮晨曦，傲然而立，仰天长啸：“普天之下，茫茫苍穹，谁与争锋？”\r', '$P浴朝阳，饮晨曦，傲然而立，仰天长啸：“普天之下，茫茫苍穹，谁与争锋？”\r', '$N迎风傲立船首，望滚滚江水东逝，仰天长啸：“古往今来多英杰，中游击橹几轮回？”\r', '$P迎风傲立船首，望滚滚江水东逝，仰天长啸：“古往今来多英杰，中游击橹几轮回？”\r', '$P射出两道冷漠的目光，凝视了$n片刻，缓缓地背转身，飘然离去。$n半响才回过神，不寒而颤。\r', '$N射出两道冷漠的目光，凝视了你片刻，缓缓地背转身，飘然离去。你半响才回过神，不寒而颤。\r', '$N射出两道冷漠的目光，凝视了$n片刻，缓缓地背转身，飘然离去。$n半响才回过神，不寒而颤。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (44, 'applaud', '', 'cglaem', '$N拍手叫好！\r', '$P拍手叫好！\r', '$N鼓掌喝采！\r', '$P鼓掌喝采！\r', '$P对着$n拍手叫好！\r', '$N对着$p拍手叫好！\r', '$N对着$n拍手叫好！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (45, 'saosao', '', 'dream', '$N羞得无地自容，“我怎么荏地不知羞耻了呢？”\r', '你羞得无地自容，“我怎么荏地不知羞耻了呢？”\r', '$N凛然道，“嫂嫂休要荏地不知羞耻！$s的眼里认得是嫂嫂，$s的拳头不认得是嫂嫂！”\r', '你凛然道，“嫂嫂休要荏地不知羞耻！$s的眼里认得是嫂嫂，$s的拳头不认得是嫂嫂！”\r', '你对着$n凛然道，“嫂嫂休要荏地不知羞耻！$s的眼里认得是嫂嫂，$s的拳头不认得是嫂嫂！”\r', '$N对着你凛然道，“嫂嫂休要荏地不知羞耻！$s的眼里认得是嫂嫂，$s的拳头不认得是嫂嫂！”\r', '$N对着$n凛然道，“嫂嫂休要荏地不知羞耻！$s的眼里认得是嫂嫂，$s的拳头不认得是嫂嫂！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (46, 'ah', '', 'bula', '$N突然张大了嘴，象是被一个饺子烫了。\r', '$P惊讶地张大了嘴说不出话来！\r', '$N惊讶地“啊”了一声。\r', '$P惊讶地“啊”了一声。\r', '$P对着$n惊讶地“啊”了一声。\r', '$N对着$p惊讶地“啊”了一声。\r', '$N对着$n惊讶地“啊”了一声。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (47, 'spear', '', 'xlb', '$N手执丈八蛇矛哇呀呀怪叫：“哪个上来与$s大战三百合！”\r', '$P手执丈八蛇矛哇呀呀怪叫：“哪个上来与$s大战三百合！”\r', '$N一面拼命练功，一面给自己打气：“临阵磨枪，不快也光！”\r', '$P一面拼命练功，一面给自己打气：“临阵磨枪，不快也光！”\r', '大将军$P八面威风，手执丈八蛇矛，对$n大喝一声：“$r，来将通名！”\r', '大将军$N八面威风，手执丈八蛇矛，对$n大喝一声：“$r，来将通名！”\r', '大将军$N八面威风，手执丈八蛇矛，对$n大喝一声：“$r，来将通名！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (48, 'help2', '', 'pickle', '$N没好气地抄起话筒：今天我们家不开饭！\r', '$P现在一听电话响就过敏：蹭饭的又来了。。。\r', '$N自言自语道：今儿个不知该到谁家蹭饭去了。。。\r', '$P自言自语道：今儿个不知该到谁家蹭饭去了。。。\r', '又没钱开饭了，$P决定给$n打个电话。\r', '叮~~~$p的电话响了：喂？有人吗？是$s$N啊！\r', '叮~~~$n的电话响了：喂？有人吗？是$s$N啊！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (49, 'wink2', '', 'cglaem', '$N的一对小眼睛看起来还怪有神的...（⊙^⊙）\r', '$P的一对小眼睛看起来还怪有神的...（⊙^⊙）\r', '$N拼命地眨巴着一对老鼠眼。\r', '$P的一对小眼睛看起来还怪有神的。\r', '$P的一对小眼睛对着$n挤了挤。\r', '$N冲$p挤了挤$P的一对老鼠眼。\r', '$N冲着$n挤了挤$P的一对老鼠眼....（^_*）\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (50, 'lovelook', '', 'cglaem', '$N看着镜中的自己，害羞地笑了起来。 \r', '$P看着镜中的自己，害羞地笑了起来。 \r', '$N两只眼睛扫来扫去，不知道在寻摸些甚麽。 \r', '$P看着大街上走来走去的姑娘们，眼都花了。 \r', '$P痴呆呆地看着眼前的$n，只希望时光就此停留。 \r', '$N痴呆呆地看着$p?只希望时光就此停留。 \r', '$N痴呆呆地看着$n，只希望时光就此停留。 \r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (51, 'rascal', '', 'dream', '$N嘴角一撇，狞笑道：“我是流氓，我怕谁？！”\r', '$P嘴角一撇，狞笑道：“我是流氓，我怕谁？！”\r', '$N叹道：如今天下大乱，流氓横行，连$S见了他们也要躲着走。\r', '$P叹道：如今天下大乱，流氓横行，连$S见了他们也要躲着走。\r', '$P对着$n大叫：“$n，你这个臭流氓！”\r', '$N对着$p大叫：“$n，你这个臭流氓！”\r', '$N对着$n大叫：“$n，你这个臭流氓！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (52, 'ybrother', '', 'cold', '$N拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，轻声低叹：“给谁呢？我要有个弟弟该多好呀！”\r', '$P拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，想起了天真可爱的弟弟。\r', '$N拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，笑眯眯地打招呼：“弟弟们，排排坐，吃豆豆！”\r', '$P拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，笑眯眯地打招呼：“弟弟们，排排坐，吃豆豆！”\r', '$P拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，笑眯眯地跟$n打招呼：“$n弟弟好呀！吃糖吗？”\r', '$N拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，笑眯眯地跟$p打招呼：“$n弟弟好呀！吃糖吗？”\r', '$N拿着一大包Ｍ＆Ｍ＇ｓ巧克力豆，笑眯眯地跟$n打招呼：“$n弟弟好呀！吃糖吗？”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (53, 'waggle', '', 'rep', '$N向$P自己摇摇食指，「小朋友，这样不可以喔！」\r', '$P向$P自己摇摇食指，「小朋友，这样不可以喔！」\r', '你们不可以对$N这样喔！\r', '你们不可以对$N这样喔！\r', '$P向$n摇摇食指，「小朋友，这样不可以喔！」\r', '$N向$p摇摇食指，「小朋友，这样不可以喔！」\r', '$N向$n摇摇食指，「小朋友，这样不可以喔！」\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (54, 'huogai', '', 'cglaem', '$N一脸倒霉相：我是自作自受。。。\r', '$P一脸倒霉相：我是自作自受。。。\r', '$N在一旁偷偷直乐，幸灾乐祸地想道：活该。\r', '$P在一旁偷偷直乐，幸灾乐祸地想道：活该。\r', '$P看着$n偷偷直乐，幸灾乐祸地想道：活该。\r', '$N看着$p偷偷直乐，幸灾乐祸地想道：活该。\r', '$N看着$n偷偷直乐，幸灾乐祸地想道：活该。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (55, 'sister', '', 'xlb', '$N不停地偷笑：这么多好姐妹，眼都看花了。\r', '$P暗暗叹了口气：这么多好姐妹，就没有一个人喜欢我？ \r', '$N抱拳团团一转，贼忒兮兮地说道：各位姐妹们，一向可好？\r', '$P抱拳团团一转，彬彬有礼地说道：各位姐妹们，一向可好？\r', '$P对$n笑道：$n妹妹好。\r', '$N贼忒兮兮地对$p笑道：$n妹妹好。 \r', '$N贼忒兮兮地对$n笑道：$n妹妹好。 \r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (56, 'hmm', '', 'dream', '$N「嗯」的一声，一副欲言又止的样子。\r', '$P「嗯」的一声，一副欲言又止的样子。\r', '$N「嗯」的一声，一副欲言又止的样子。\r', '$P「嗯」的一声，一副欲言又止的样子。\r', '$P对着$n「嗯」的一声，似乎有什么话要说。\r', '$N对着$p「嗯」的一声，似乎有什么话要说。\r', '$N对着$n「嗯」的一声，似乎有什么话要说。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (57, 'knowing', '', 'joy', '$N独自黯然地轻拨琴弦，阵阵美妙的音流从指间划出，高山依依，流水淙淙．．．．．．\r', '$P独自黯然地轻拨琴弦，阵阵美妙的音流从指间划出，高山依依，流水淙淙．．．．．．\r', '$N轻拨琴弦，划出一节美妙的音流，只觉高山依依，流水淙淙．．．．．．\r', '$P轻拨琴弦，划出一节美妙的音流，只觉高山依依，流水淙淙．．．．．．\r', '$P含笑地对$n点点头，抚琴挑指相和，乐声飘出，流水淙淙，高山依依．．．．．．\r', '$N含笑地对你点点头，抚琴挑指相和，乐声飘出，流水淙淙，高山依依．．．．．．\r', '$N含笑地对$n点点头，抚琴挑指相和，乐声飘出，流水淙淙，高山依依．．．．．．\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (58, 'shutup', '', 'cglaem', '$N摇了摇头：说不得，不能说...\r', '$P摇了摇头：说不得，不能说...\r', '$N突然尖叫一声：闭嘴！\r', '$P突然尖叫一声：闭嘴！\r', '$P恶狠狠地威胁道：$n，你个$r！给我闭嘴！\r', '$N恶狠狠地对你说：$n，你个$r！给我闭嘴！\r', '$N恶狠狠地威胁道：$n，你个$r！给我闭嘴！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (59, 'gongxi', '', 'cglaem', '$N哈哈大笑：同喜！同喜！\r', '$P哈哈大笑：同喜！同喜！\r', '$N春风满面，一拱手道：各位，$S下面要宣布一件大喜事！\r', '$P得意以极，要向大家宣布一件大喜事。\r', '$P向$n道喜。\r', '$N一拱手，笑嬉嬉地对$p道：恭喜！恭喜！\r', '$N一拱手，笑嬉嬉地对$n道：恭喜！恭喜！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (60, 'addoil', '加油', 'cglaem', '$N不停地给自己打气：加油！加油！再加油！\r', '$P不停地给自己打气：加油！加油！再加油！\r', '$N望空高喊：加油！加油！\r', '$P望空高喊：加油！！\r', '$P对$n高喊：加油！加油！\r', '$N对$p高喊：加油！加油！\r', '$N对$n高喊：加油！加油！\r', 1, 0, '2026-05-23 04:09:11');
INSERT INTO `emotes` VALUES (61, ':(', '', 'dream', '$N看着镜中日益消瘦的脸庞自怨自艾，“唉，$N，你好命苦！”\r', '$P看着镜中日益消瘦的脸庞自怨自艾，“唉，$N，你好命苦！”\r', '$N露出一丝难过的神色。\r', '$P露出一丝难过的神色。\r', '$P看着$n，难过得要哭了。\r', '$N看着你，难过得要哭了。\r', '$N看着$n，难过得要哭了。。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (62, 'damn', '', 'snowcat', '$N两眼发愣四肢颤抖一咬牙一跺脚：$s今儿真是活见鬼了！\r', '$P两眼发愣四肢颤抖一咬牙一跺脚：$s今儿真是活见鬼了！\r', '$N两眼发愣四肢颤抖一咬牙一跺脚：今儿真是活见鬼了！\r', '$P两眼发愣四肢颤抖一咬牙一跺脚：今儿真是活见鬼了！\r', '$P斜眼一瞥死盯着$n：我说$r哇，今儿您可真是走路撞楣子吃饭噎沙子总算是活见鬼了！\r', '$N斜眼一瞥死盯着$p：我说$r哇，今儿您可真是走路撞楣子吃饭噎沙子总算是活见鬼了！\r', '$N斜眼一瞥死盯着$n：我说$r哇，今儿您可真是走路撞楣子吃饭噎沙子总算是活见鬼了！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (63, 'eat2', '', 'mon', '$N哈哈笑道：“$s是千金贵体，你前世几生修到，竟能拿$s的肠胃作棺材，拿$s的肚皮作坟墓，福禄深厚，运气当真不坏呀！”\r', '$P打了个饱嗝，心满意足地翘起了二郎腿。\r', '$N拍着胸脯道：“天上飞的，俺就没吃过蚊子。地上跑的，俺就没吃过蚂蚁。两条腿的俺就没吃过人，四条腿的俺就没吃过板凳！”\r', '$P腹中空空，四处寻摸着看有什么能吃的。\r', '$P最是懒惰，真希望$n能杀了$p自己，洗剥切割，煮熟了端上来。\r', '$N围着$p打转，拿着本菜谱比划着$p身上各个部位。\r', '$N对$n骂道：“你这个蠢货！为什么不能自己宰杀自己，再将自己烧成一大碗红烧$n，双手恭恭敬敬地端上来？！$s想起来就有气！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (64, 'admire', '', 'cglaem', '$N暗自得意：果然是千穿万穿，马屁不穿。\r', '$P暗自得意：果然是千穿万穿，马屁不穿。\r', '$N面带谄笑，点头哈腰地对大家说道：各位大名$S心仪已久，幸会！幸会！\r', '$P面带谄笑，点头哈腰地对大家说道：各位大名$S心仪已久，幸会！幸会！\r', '$P面带谄笑，毕恭毕敬地对$n道：高！实在是高！\r', '$N面带谄笑，毕恭毕敬地对$p道：高！实在是高！\r', '$N面带谄笑，毕恭毕敬地对$n道：高！实在是高！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (65, 'pat', '', 'snowcat', '$N轻轻地拍拍自己的头，不知道有什么问题。\r', '$P轻轻地拍拍自己的头。\r', '$N拍了拍自己的头。\r', '$P拍了拍自己的头。\r', '$P轻轻地拍拍$n的头。\r', '$N轻轻地拍$p的头。\r', '$N轻轻地拍拍$n的头。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (66, 'nocheck', '', 'ajax', '$N取出一张写有＂国家一级保护动物＂的字条，绑在自己的额头上，劝大家说：＂看着我打喷嚏，你们不伤心么？＂\r', '又有人打我的主意了，当咱是那大使馆么？！\r', '$N小声嘀咕道：＂这么多人打喷嚏，难道说又闹开流感了？＂\r', '别查了好么？\r', '你可不乐意谁打你的主意噢。\r', '$N跳着小脚对着$n哭骂道：＂我说是谁害得俺打喷嚏，原来是$n你啊，不怕俺一喷嚏把你崩死么？＂\r', '$N一个喷嚏打过，大怒道：＂又是那$n使法儿作的怪！不怕$s我一个喷嚏，崩死了他！＂\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (67, 'follow', '', 'snowcat', '$N长叹一声：看来只有我自己瞎混了！没人怜，没人爱的．．．\r', '$P长叹一声：看来只有我自己瞎混了！\r', '$N向东迈了几步，又转向南几步．叹了口气，怔怔地出神．．．\r', '$P迷迷糊糊地不知该望哪走，在原地直打转．．． \r', NULL, NULL, '$N对着$n拍着胸脯说：只要你嫁给我，你叫我做什么我就做什么！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (68, 'noescape', '', 'woodhead', '$N不停地给自己打气：坚持就是胜利。。。\r', '$P不停地对自己说：坚持就是胜利。。。\r', '$N阴阴一笑：嘿嘿，跑得了和尚跑不了庙。看你能跑到哪里去！\r', '$P阴阴一笑：嘿嘿，跑得了和尚跑不了庙。看你能跑到哪里去！\r', '$P对着$n大喝一声：$r，哪里逃！\r', '$N对着$p大喝一声：$r，哪里逃！\r', '$N对着$n大喝一声：$r，哪里逃！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (69, 'brother', '', 'cglaem', '$N撇了撇嘴，眼含泪水：没有人记得$S$N了~~~\r', '$P撇了撇嘴，眼含泪水：没有人记得$S$N了~~~\r', '$N娇滴滴地跟大家打了个招呼：各位大哥，还记得$N吗？\r', '$P娇滴滴地跟大家打了个招呼：各位大哥，还记得$N吗？\r', '$P娇滴滴地跟$n打了个招呼。\r', '$N娇滴滴地跟$p打了个招呼：$n哥哥好呀~~\r', '$N娇滴滴地跟$n打了个招呼：$n哥哥好呀~~\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (70, 'giggle', '', 'snowcat', '$N咯咯地笑了起来，不知道在笑什么。\r', '$P突然觉得好笑，而咯咯地笑了起来。\r', '$N发出一串母鸡下蛋般的笑声。\r', '$P发出一串母鸡下蛋般的笑声。\r', '$P对着$n咯咯地笑着。\r', '$N对着$p咯咯地笑着。\r', '$N对着$n咯咯地笑了起来。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (71, 'theme', '', 'cglaem', '$N拿起麦克风，冒着飞来的西红柿和鸡蛋走上台说道：各位，$s今天兴致高，下面给大家演唱一首西游记主题歌！\r', '$P拿起麦克风，冒着飞来的西红柿和鸡蛋走上台说道：各位，$s今天兴致高，下面给大家演唱一首西游记主题歌！\r', '$N操着五音不全的嗓子干嚎道：你挑着担~~我牵着马~~\r', '$P操着五音不全的嗓子干嚎道：你挑着担~~我牵着马~~\r', '$P嘶哑着嗓子对$n唱道：你挑着担~~我牵着马~~\r', '$N嘶哑着嗓子对$p唱道：你挑着担~~我牵着马~~\r', '$N嘶哑着嗓子对$n唱道：你挑着担~~我牵着马~~\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (72, 'mailto', '', 'ajax', '$N拿出一个写着＂无底洞厨房鼹鼠精叔叔收＂的特大邮包，准备装人。\r', '你拿出一个写着＂无底洞厨房鼹鼠精叔叔收＂的特大邮包，准备装人。\r', '$N准备寄邮政特快专递。\r', '你准备寄邮政特快专递。\r', '你将一枚五十元的邮票贴在$n的身上，义愤填膺地对千里眼说：「给我寄往无底洞厨房！」\r', '$N将一枚五十元的邮票贴在你的身上，义愤填膺地对千里眼说：「给我寄往无底洞厨房！」\r', '$N将一枚五十元的邮票贴在$n的身上，义愤填膺地对千里眼说：「给我寄往无底洞厨房！」\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (73, 'hehe', '', 'weiqi', '$N「嘿嘿嘿．．．．」地奸笑了几声，一副莫测高深的样子。\r', '$P「嘿嘿嘿．．．．」地奸笑了几声，一副莫测高深的样子。\r', '$N「嘿嘿嘿．．．．」地奸笑了几声。\r', '$P「嘿嘿嘿．．．．」地奸笑了几声。\r', '$P一面用锐利的目光盯着$n，一面「嘿嘿嘿．．．．」地奸笑着。\r', '$N一面用锐利的目光盯着$p，一面「嘿嘿嘿．．．．」地奸笑着。\r', '$N一面用锐利的目光盯着$n，一面对着$p「嘿嘿嘿．．．．」地奸笑着。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (74, 'crab', '', 'dream', '$N得意地指着自己的鼻子说：$s是属螃蟹的，天生喜欢这么走路，怎么着？\r', '$P得意地指着自己的鼻子说：$s是属螃蟹的，天生喜欢这么走路，怎么着？\r', NULL, NULL, '$P对$n惊到：我原以为只有螃蟹才这么走路，没想到$R也喜欢横行，失敬失敬！\r', '$N对$p惊到：我原以为只有螃蟹才这么走路，没想到$R也喜欢横行，失敬失敬！\r', '$N对$n惊到：我原以为只有螃蟹才这么走路，没想到$R也喜欢横行，失敬失敬！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (75, 'mygod', '', 'pickle', '$N目瞪口呆地嚷道：“天呐，我都干了些什么？！”\r', '$P目瞪口呆地嚷道：“天呐，我都干了些什么？！”\r', '$N大声惊呼：“天呐，怎么会是这样！”\r', '$P大声惊呼：“天呐，怎么会是这样！”\r', '$P对着$n大声惊呼：“天呐，瞧瞧你都干了些什么？！”\r', '$N对着$p大声惊呼：“天呐，瞧瞧你都干了些什么？！”\r', '$N对着$n大声惊呼：“天呐，瞧瞧你都干了些什么？！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (76, 'disagree', '', 'cglaem', '$N不好意思地笑道：大家别听我胡说八道。\r', '$P不好意思地笑道：大家别听我胡说八道。 \r', '$N嘀咕道：谁又在胡说八道？ \r', '$P嘀咕道：谁又在胡说八道？ \r', '$P对$n说道：你又胡说八道了？ \r', '$N对$p道：你这个$r又在胡说八道！ \r', '$N对$n高声骂道：你这个$r又在胡说八道！ \r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (77, 'courage', '', 'pickle', '$N不停的劝自己：这事儿撑死胆大的饿死胆小的，还是做个饱死鬼吧！\r', '$P不停的劝自己：这事儿撑死胆大的饿死胆小的，还是做个饱死鬼吧！\r', '$N突然尖叫了一声：大胆！！\r', '$P突然尖叫了一声：大胆！！\r', '$P对$n断喝一声：大胆！你这个$r不要命了，敢和$s做对！\r', '$N对$p断喝一声：大胆！你这个$r不要命了，敢和$s作对！\r', '$N对$n断喝一声：大胆！你这个$r不要命了，敢和$s作对！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (78, 'blush', '', 'mon', '$N低下头，害羞地脸红了起来！\r', '$P低下头，害羞地脸红了起来！\r', '一朵红云飞上了$N的面颊．．．\r', '$P羞得满面通红！\r', '$P伸手刮着$n的鼻子说：羞羞脸！\r', '$N伸手刮着$p的鼻子说：羞羞脸！\r', '$N伸手刮着$n的鼻子说：羞羞脸！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (79, 'spank', '', 'snowcat', '$N拿手拍了拍肚皮，一副心满意足的样子。\r', '$P拍了拍肚皮，一副心满意足的样子。\r', '$N拿手拍了拍肚皮，一副心满意足的样子。\r', '$P拍了拍肚皮，一副心满意足的样子。\r', '$P用力拍着$n的背，一副「好小子！干的好」的表情。\r', '$N用力拍着$p的背，一副「好小子！干的好」的表情。\r', '$N用力拍着$n的背，一副「好小子！干的好」的表情。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (80, 'flower', '', 'bula', '$N唱到：人家的姑娘有花戴，俺家钱少不能买，扯来一把狗尾巴草，俺$N自个戴起来。。。。\r', '$P唱到：人家的姑娘有花戴，俺家钱少不能买，扯来一把狗尾巴草，俺$N自个戴起来。。。。\r', '$N把一根狗尾巴草轻轻插到鬓边，“嘿嘿”地傻笑了几声。\r', '$P把一根狗尾巴草轻轻插到鬓边，“嘿嘿”地傻笑了几声。\r', '$P对着$n唱到：人家的姑娘有花戴，俺家钱少不能买，扯来一把狗尾巴草，给俺$n戴起来。。。。\r', '$N对着$p唱到：人家的姑娘有花戴，俺家钱少不能买，扯来一把狗尾巴草，我来给你戴起来。。。\r', '$N对着$n唱到：人家的姑娘有花戴，俺家钱少不能买，扯来一把狗尾巴草，给俺$n戴起来。。。。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (81, 'jealous', '', 'pickle', '$N语重心长地说道：“吃不到的葡萄是酸的！这句话果然有道理呀！”\r', '$P下定决心，要发奋图强，把别人都比下去。\r', '$N浑身发热，满脸通红，眼睛射出了贪婪的目光。\r', '$P想：要是我也那么有本事就好了。:(\r', '$P非常羡慕$n，希望自己有$p一半好就满足了。\r', '$N觉得$p会乐极生悲，正等着$p倒霉呢。\r', '$N盯着$n，恨恨地说道：“哼，有什么了不起的？我。。我。。我我我。。。我昨天梦里比你威风得多了！”\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (82, 'help!', '', 'pickle', '$N满脸严肃地说道：男儿当自强！可是您还是帮帮我吧！\r', '“天助自助者”，你这样告诉自己。\r', '$N大叫：救命啊！救命啊！\r', '$P大叫：救命啊！救命啊！\r', '$P对$n大叫：救命哪！救救我啊！\r', '$N对$p大叫：救命哪！救救我啊！\r', '$N对$n大叫：救命哪！救救我啊！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (83, 'nopat', '', 'snowcat', '$N高声叫道：谁也别拍我，当心把$S惹恼了，有你们好看的！\r', '$P高声叫道：谁也别拍我，当心把$S惹恼了，有你们好看的！\r', '$N不高兴地撇了撇嘴：别总拍来拍去，当心越拍越傻！\r', '$P不高兴地撇了撇嘴：别总拍来拍去，当心越拍越傻！\r', '$P冲着$n直嚷嚷：你拍什么拍，手痒痒就拍自个儿胸脯去！\r', '$N冲着$p直嚷嚷：你拍什么拍，手痒痒就拍自个儿胸脯去！\r', '$N冲着$n直嚷嚷：你拍什么拍，手痒痒就拍自个儿胸脯去！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (84, 'fool', '', 'bula', '请大家注意$N这个大白痴。。。真是天上少有。。。人间仅存的活宝。。。不看可惜。。。\r', '哇！！！大白痴呀！！！世界大奇迹呀！！！去撞墙自杀吧。。。\r', '$N像白痴一样呆呆地傻笑着。。。:-0~~~\r', '$P露出像白痴般的笑容。。。:-0~~~\r', '$P对$n莫名其妙的傻笑着。。。:-0~~~\r', '$N对$p露出像白痴一样的笑容。。。:-0~~~哇！口水滴到$p的衣服上了。。。\r', '$N对$n不断地傻笑着。。。:-0~~~口水四溅。。。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (85, 'holdon', '', 'pickle', '$N说道：乖乖不得了了，$S的老板来了，没功夫聊了。回见！\r', '$P的老板来了，得赶紧溜了。\r', '$N说道：众位仙翁仙女，小可有事，去去就来。大家千万别走。\r', '$P去去就回，让大家稍等一下。\r', '$P让$n稍等片刻，$P去去就回。\r', '$N让$p稍等片刻，$P去去就回。\r', '$N对$n道：$R稍安毋躁，$S去去就来。咱回头聊！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (86, 'noeat', '', 'mon', '$N已经吃得太多了，再吃就撑死了。\r', '$P已经吃得太多了，再吃就撑死了。\r', '$N无可奈何地叫道：吃，吃，吃！就知道吃！\r', '$P叫道：吃，吃，吃！就知道吃！\r', '$P对$n说道：已经胖得象猪了，还在吃．．．\r', '$N对$p说道：已经胖得象猪了，还在吃．．．\r', '$N对$n说道：已经胖得象猪了，还在吃．．．\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (87, 'back', '', 'bula', '$N对热烈欢迎的群众伟大同志般的一挥手，满脸的严肃掩悉不了狂喜的心情：“$s又回来了！”\r', '$P对热烈欢迎的群众伟大同志般的一挥手，满脸的严肃掩悉不了狂喜的心情：“俺又回来了！”\r', '$N摆了个不丁不卯步，运足了气一声断喝：$s又回来了！\r', '$P摆了个不丁不卯步，运足了气嚷到：俺胡汉三又回来了！\r', '$P对着$n一声断喝：$r你给我回来。\r', '$N对着$p喝到：$r你哪里跑，还不给我回来！\r', '$N对着$n喝到：$r你哪里跑，再不回来$s可不客气了！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (88, 'tender', '', 'bula', '$N对大家唱：「我很丑！可是我很温柔………」\r', '$P对自己唱：「我很丑！可是我很温柔………」\r', '$N露出温柔亲切的表情！\r', '$P露出温柔亲切的表情！\r', '$P恳切地给予$n温暖同情的眼神！\r', '$N恳切地给予$p温暖同情的眼神！\r', '$N恳切地给予$n温暖同情的眼神！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (89, 'tickle', '', 'cglaem', '$N伸出指头在自己胳肢窝下搔了几下，只笑得花枝乱颤。\r', '$P伸出指头在自己胳肢窝下搔了几下，只笑得花枝乱颤。\r', '$N手指头动了动，好象痒得很难受。\r', '$P觉得手指有点痒。\r', '$P伸出指头在$n胳肢窝下搔了几下，只见$n笑得直不起腰来，大叫饶命。\r', '$N伸出指头在$p胳肢窝下搔了几下，只见$p笑得直不起腰来，大叫饶命。\r', '$N伸出指头在$n胳肢窝下搔了几下，只见$n笑得直不起腰来，大喊饶命。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (90, 'heng', '', 'bula', '$N哼了一声，对自己很不满意。\r', '$P哼了一声，对自己很不满意。\r', '$N哼了一声。\r', '$P哼了一声。\r', '$P看都不看$n一眼，哼了一声，高高的把头扬了起来……不理你……\r', '$N看都不看$p一眼，哼了一声，高高的把头扬了起来……不理你……\r', '$N看都不看$n一眼，哼了一声，高高的把头扬了起来……不理你……\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (91, 'over', '', 'snowcat', '$N撕心裂胆地叫道：好，好，完蛋了，$s真是彻底完蛋了！\r', '$P撕心裂胆地狂喊一声：完蛋了，$s真是彻底完蛋了！\r', '$N撕心裂胆地狂喊一声：完蛋了，今儿真是完蛋了！\r', '$P痛心疾首地说：完了！完蛋了！\r', '$P皱着眉头，指着$n说：嘿嘿$r，你今儿老鸡婆子抱大窝－－彻底完蛋了！\r', '$N皱着眉头，指着$p说：嘿嘿$r，你今儿老鸡婆子抱大窝－－彻底完蛋了！\r', '$N皱着眉头，指着$n说：嘿嘿$r，你今儿老鸡婆子抱大窝－－彻底完蛋了！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (92, 'nocurse', '', 'bula', '$N打了自己一耳光，不好意思地说道：真是对不起，$S一时失言，大家多多包涵。\r', '你深深后悔刚才一时失言，忙向大家道歉。\r', '$N嘀咕道：谁呀？嘴怎么这么脏？多久没刷牙了？\r', '你掏出一支牙刷，道：唉，好久没用了。。。\r', '你恶狠狠地威胁$n道：你个$r！再骂人我就不客气了！\r', '$N劝你道：别动怒，别动怒！\r', '$N掏出一把鞋刷子，揪住了$n的头发，边刷边教训道：说话干净点儿！没的让人看不起！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (93, 'face', '', 'snowcat', '$N顽皮地做了个鬼脸。\r', '$P顽皮地做了个鬼脸。\r', '$N顽皮地做了个鬼脸。\r', '$P顽皮地做了个鬼脸。\r', '$P顽皮地对$n做了个鬼脸。\r', '$N顽皮地对$p做了个鬼脸(^_*)。\r', '$N顽皮地对$n做了个鬼脸。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (94, 'pout', '生气', 'snowcat', '$N小嘴翘得老高，满脸的不高兴。\r', '$P小嘴翘得老高，满脸的不高兴。\r', '$N不高兴地翘起嘴来。\r', '$P不高兴地翘起嘴来。\r', '$P翘起小嘴来对着$n撒娇。\r', '$N翘起小嘴来对着$p撒娇。\r', '$N翘起小嘴来对着$n撒娇。\r', 1, 0, '2026-05-23 04:15:35');
INSERT INTO `emotes` VALUES (95, 'pig', '', 'bula', '$N自言自语道：唉，也没人来拱猪，只好自己拱自己了。。。\r', '$P自言自语道：唉，也没人来拱猪，只好自己拱自己了。。。\r', '$N扯开嗓门大声嚷道：喂～～～瞧一瞧来看一看哟！上好的猪头肉，一文钱一斤！\r', '$P喊道：喂～～～瞧一瞧来看一看哟！上好的猪头肉，一文钱一斤！\r', '$P眉开眼笑地招呼$n道：哎哟，好久不见了，来来来，吃个猪，吃个猪！\r', '$N眉开眼笑地招呼$p道：哎哟，好久不见了，来来来，吃个猪，吃个猪！\r', '$N眉开眼笑地招呼$n道：哎哟，好久不见了，来来来，吃个猪，吃个猪！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (96, 'sorry2', '', 'bula', '$N嘴里嘟囔道：俺不过能吃能睡爱偷懒，怎么这么多人找俺的麻烦。\r', '$P心里暗想：俺不过能吃能睡爱偷懒，怎么这么多人找俺的麻烦。\r', '$N抱拳团团一躬，说道：各位，$S才疏学浅，不懂规矩，若有得罪之处，还请多多包涵。\r', '$P抱拳团团一躬，说道：各位，$S才疏学浅，不懂规矩，若有得罪之处，还请多多包涵。\r', '$P对着$n深深一躬，说道：$S有眼不识泰山，$R您宰相肚里能撑船，可别跟$S一般见识啊！\r', '$N朝你深深一躬，说道：$S有眼不识泰山，$R您宰相肚里能撑船，可别跟$S一般见识啊！\r', '$N对着$n深深一躬，说道：$S有眼不识泰山，$R您宰相肚里能撑船，可别跟$S一般见识啊！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (97, 'zisha', '', 'bula', '$N报怨道：唉！自杀真是费劲！俺想上吊，又怕憋得慌；想跳河，怕水凉；抹脖子怕疼；摸电门麻的厉害；想吃毒药没地方儿买；想撞车又怕给司机叔叔添麻烦。刚才俺一狠心，吃了二斤包子，可是咋没死了呢？？\r', '$P心想：我该怎么自杀才好呢？\r', '$N义愤填膺地喊道：气死我了！气死我了！你们再不给$s补偿，$s不活了！\r', '$P实在活不下去了，想自杀算了，一了百了……\r', '$P对$n道：太棒了！你死了我就耳根清静了！\r', '$N擦着鼻涕，对$p挥手道：你去吧！再也别回来啦！\r', '$N擦着鼻涕，对$n挥手道：你去吧！再也别回来啦！\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (98, 'beep', '', 'mon', '$N的闹钟响了！～～～BEEP！\r', '$P的闹钟响了！\r', '$N弄出一阵刺耳的声响～～～～～BEEP！\r', '$P弄出一阵刺耳的声响～～～～～\r', '「BEEP！」，$P好像要找$n．．．\r', '「BEEP！」，$N好像要找$n．．．\r', '「BEEP！」，$N好像要找$n．．．\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (99, 'die', '', 'snowcat', '$N爬进一口大棺材里，神情漠然地躺下，象是等待着什么．．．\r', '$P爬进一口大棺材里躺下，心想：最好再也别醒，一了百了。\r', '$N蹬了蹬腿，张嘴想说什么，一口气没上来，死了。\r', '$P从没有感觉象现在这么好．．．\r', '$P很酷地掏出一把枪，「碰！」一枪把$n给毙了。\r', '$N很酷地掏出一把枪，「碰！」$p看见子弹朝你飞来，闪不掉了！$p死了。\r', '$N很酷地掏出一把枪，「碰！」的一声，$n死了。\r', 1, 0, '2026-05-16 08:19:02');
INSERT INTO `emotes` VALUES (100, 'sing2', '', 'mon', '$N拿起麦克风，冒着飞来的西红柿和鸡蛋走上台说道：各位，$s今天兴致高，下面给大家演唱一首西游记主题歌！\r', '$P拿起麦克风，冒着飞来的西红柿和鸡蛋走上台说道：各位，$s今天兴致高，下面给大家演唱一首西游记主题歌！\r', '$N操着五音不全的嗓子干嚎道：我们都是神精病，成天都在泥潭里滚．．～\r', '$P操着五音不全的嗓子干嚎道：我们都是神精病，成天都在泥潭里滚．．～\r', '$P对$n唱道：$r静心好好练，别怕网慢学功夫难。只要天天在这里混，发呆也能学会变．．．\r', '$N对$p唱道：$r静心好好练，别怕网慢学功夫难。只要天天在这里混，发呆也能学会变．．．\r', '$N对$n唱道：$r静心好好练，别怕网慢学功夫难。只要天天在这里混，发呆也能学会变．．．\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (101, 'buddha', '', 'weiqi', '在这一瞬间，$N觉得自己的形象简直是无比高大。\r', '在这一瞬间，$P觉得自己的形象当真是无比高大。\r', '在这一瞬间，$N觉得自己的形象简直是无比高大。\r', '在这一瞬间，$P觉得自己的形象当真是无比高大。\r', '在这一瞬间，$P觉得$n的形象简直是无比高大。\r', '在这一瞬间，$N觉得$p的形象简直是无比高大。\r', '在这一瞬间，$N觉得$n的形象简直是无比高大。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (102, 'point', '', 'mon', '$N指着自己。\r', '$P指着自己。\r', '$N伸手凌空一指，差点儿戳在自己身上。\r', '指谁？\r', '$P指着$n。\r', '$N指着$p。\r', '$N指着$n。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (103, 'sneer', '', 'dream', '$N「哼」地冷笑一声。\r', '$P「哼」地冷笑一声。\r', '$N「哼」地冷笑一声。\r', '$P「哼」地冷笑一声。\r', '$P对着$n「哼」地冷笑一声。\r', '$N对着$p「哼」地冷笑一声。\r', '$N对着$n「哼」地冷笑一声。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (104, 'divorce', '', 'cglaem', '$N跳了起来：你要敢离我就抹脖子！\r', '$P跳了起来：离就离，有什么了不起的。。。\r', '$N大声嚷道：离就离，有什么了不起的。。。\r', '$P大声嚷道：我要离婚！\r', '$P气急败坏地对$n说：我要跟你离婚！\r', '$N气急败坏地对$p说：你要敢离我就抹脖子！\r', '$N气急败坏地对$n说：我要跟你离婚！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (105, 'gaoyao', '', 'ajax', '$N昂首站在十字街头，断喝一声：谁买我的大力丸！\r', '你昂首站在十字街头，断喝一声：谁买我的大力丸！\r', '$N提着小竹篮，背着小扁担，沿街叫卖：“祖传仙药，包治百病，一帖就灵！”\r', '你提着小竹篮，背着小扁担，沿街叫卖：“祖传仙药，包治百病，一帖就灵！”\r', '你从篮子里掏出一贴皱皱巴巴的膏药：往$n背上一拍：大喝一声：药到病除！好了！\r', '$N从篮子里掏出一贴皱皱巴巴的膏药：往你背上一拍：大喝一声：药到病除！好了！\r', '$N从篮子里掏出一贴皱皱巴巴的膏药：往$n背上一拍：大喝一声：药到病除！好了！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (106, 'snicker', '', 'bula', '$N一个人躲在旁边偷偷地笑。\r', '$P一个人躲在旁边偷偷地笑。\r', '$N躲在一旁偷偷地笑。\r', '$P在旁边偷偷地笑。\r', NULL, NULL, NULL, 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (107, 'slogan', '', 'cglaem', '$N正气凛然地道：反动派你不打他就不倒！\r', '$P正气凛然地道：反动派你不打他就不倒！\r', '$N高举右拳，咬牙切齿地高呼：“打倒某某某！”\r', '$P高举右拳，咬牙切齿地高呼：“打倒某某某！”\r', '$P高举右拳，咬牙切齿地高呼：“打倒$n！”\r', '$N高举右拳，对着你咬牙切齿地高呼：“打倒$n！”\r', '$N高举右拳，咬牙切齿地高呼：“打倒$n！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (108, 'sweat', '擦汗', 'tnn', '$N擦擦额头上的汗水。\r', '$P擦擦额头上的汗水。\r', '$N擦擦额头上的汗水。\r', '$P擦擦额头上的汗水。\r', '$P替$n擦擦汗。\r', '$N替$p擦擦汗。\r', '$N替$n擦擦汗。\r', 1, 0, '2026-05-23 04:14:39');
INSERT INTO `emotes` VALUES (109, 'lag', '', 'bula', '$N挥动双手惨叫道「哇！我变慢了．．．天啊．．．天啊．．．」\r', '$P慢慢地挥动双手．．．哇．．．怎么这么慢！\r', '$N挥动双手惨叫道「哇！我变慢了．．．天啊．．．天啊．．．」\r', '$P慢慢地挥动双手．．．哇．．．怎么这么慢！\r', '$P慢慢地挥动双手．．．哇．．．怎么这么慢！\r', '$N挥动双手惨叫道「哇！我变慢了．．．天啊．．．天啊．．．」\r', '$N挥动双手惨叫道「哇！我变慢了．．．天啊．．．天啊．．．」\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (110, 'snowball', '', 'bula', NULL, NULL, '$N玩弄著手上的猕猴桃，不怀好意的盯着周围的人。\r', '$P玩弄著手上的猕猴桃。\r', '$P向$n丢猕猴桃。\r', '$N的猕猴桃「啪！」的一声打中$p，你的脑门上被砸出一个小臌包。\r', '$N的猕猴桃「啪！」的一声砸中$n。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (111, 'wake', '', 'snowcat', '$N气得高声叫骂：哪个王八蛋把我弄醒了！刚梦到。。。\r', '$P气得高声叫骂：哪个王八蛋把我弄醒了！刚梦到。。。\r', '$N揉揉眼睛，清醒了过来。\r', '$P揉揉眼睛，清醒了过来。\r', '$P摇着$n试着把$p叫醒。大声在$p耳边大叫：「 猪！起来了！」\r', '$N猛力摇着$p，$p听到一些很刺耳的声音！\r', '$N摇着$n试着把$p叫醒。大声在$p耳边大叫：「 猪！起来了！」\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (112, 'wind', '', 'cold', '$N诡魅地一笑，一个转身潇洒地挥甩出飘带，刹那间，乌云滚滚而来，狂风怒吼，$N哈哈大笑地乘风而去。\r', '$P诡魅地一笑，一个转身潇洒地挥甩出飘带，刹那间，乌云滚滚而来，狂风怒吼，你哈哈大笑地乘风而去。\r', '$N诡魅地一笑，优雅地挥甩出飘带，刹那间，狂风大作，尘土飞扬。\r', '$P诡魅地一笑，优雅地挥甩出飘带，刹那间，狂风大作，尘土飞扬。\r', '$P诡魅地一笑，一个转身潇洒地朝$n挥甩出飘带，刹那间，乌云滚滚而来，狂风怒吼，猛然见$n已被风卷起，消失得无影无踪。\r', '$N诡魅地一笑，一个转身潇洒地朝你挥甩出飘带，刹那间，乌云滚滚而来，狂风怒吼，猛然间你惊觉自己已被风卷起，心中甚是惊恐。\r', '$N诡魅地一笑，一个转身潇洒地朝$n挥甩出飘带，刹那间，乌云滚滚而来，狂风怒吼，猛然见$n已被风卷起，消失得无影无踪。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (113, 'same', '', 'bula', '$N拱手笑道：过奖，过奖！\r', '$P拱手笑道：过奖，过奖！\r', '$N拱手笑道：哪里，哪里！\r', '$P拱手笑道：哪里，哪里！\r', '$P哈哈大笑，对$n一拱手道：$R过奖了，$S才疏学浅，实不敢当啊！\r', '$N哈哈大笑，对$p一拱手道：$R过奖了，$S才疏学浅，实不敢当啊！\r', '$N哈哈大笑，对$n一拱手道：$R过奖了，$S才疏学浅，实不敢当啊！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (114, 'smirk', '', 'bula', '$N发出一阵傻笑，不知道想到什么了。\r', '$P发出一阵傻笑，不知道想到什么了。\r', '$N发出一阵傻笑。\r', '$P发出一阵傻笑。\r', '$P对着$n发出一阵傻笑。\r', '$N对着$p发出一阵傻笑。\r', '$N对着$n发出一阵傻笑。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (115, 'forehead', '', 'snowcat', '$N小心翼翼地揭下脑门上的小红旗，说道：哈哈，将来有了孩子，我就有的夸了！\r', '$P委屈地大喊：你们冤枉好人！我早就过十八了！说罢，竟流下眼泪。\r', '$N在一面小旗上写道：“未满十八，请多关照！”写毕，不怀好意地晃着小旗，似乎在找目标。\r', '$P从兜里掏出一面摸了浆糊的小红旗，在手中挥舞着。\r', '$P在$n脑门上贴了一面小红旗，上书：“未满十八，请多关照！”\r', '$N在$p脑门上贴了一面小红旗，上书：“未满十八，请多关照！”\r', '$N在$n脑门上贴了一面小红旗，上书：“未满十八，请多关照！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (116, 'calm', '', 'cold', '$N拧着自个儿的衣角，紧抿着嘴巴，暗暗告诫自己：“平静些，不能生气，我才不要生气呢！”\r', '$P拧着自个儿的衣角，紧抿着嘴巴，暗暗告诫自己：“平静些，不能生气，我才不要生气呢！”\r', '$N伸出手想揪住点什么，四下看看，无可奈何地说：“好姐妹，好兄弟，都平静些，好吗？”\r', '$P伸出手想揪住点什么，四下看看，无可奈何地说：“好姐妹，好兄弟，都平静些，好吗？”\r', '$P揪了揪$n的衣袖，带着迷人的微笑望着$n，抿了抿双唇娇嗔着：“好$n，别生气啊？！”\r', '$N揪了揪你的衣袖，带着迷人的微笑望着你，抿了抿双唇娇嗔着：“好$n，别生气啊？！”\r', '$N揪了揪$n的衣袖，带着迷人的微笑望着$n，抿了抿双唇娇嗔着：“好$n，别生气啊？！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (117, 'sing', '', 'xlb', '$N快乐地唱起了歌来！「 啦 ．．～  」\r', '$P拉起五音不全的喉咙哼起歌来！「 啦 ．．～ 」\r', '$N快乐地唱起了歌来！「 啦 ．．～ 」\r', '$P拉起五音不全的喉咙哼起歌来！「 啦 ．．～ 」\r', '$P对$n唱起歌来！\r', '$N对$p含情脉脉地唱起歌来！ 「啊．．～」\r', '$N对$n含情脉脉地唱起歌来！ 「啊．．～」\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (118, ':D', '', 'cglaem', '$N笑得嘴都合不起来了。\r', '$P笑得嘴都合不起来了。\r', '$N笑得嘴都合不起来了。 \r', '$P笑得嘴都合不起来了。\r', '$P拍着$n的肩膀，笑得嘴都合不起来了。\r', '$N拍着$p的肩膀，笑得嘴都合不起来了。\r', '$N拍着$n的肩膀，笑得嘴都合不起来了。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (119, 'admire1', '', 'mon', '$N自嘲道：$S修道多年，一事无成，妙领天机是说不上的，预知祸福也就马马虎虎了。\r', '$P自嘲道：$S修道多年，一事无成，妙领天机是说不上的，预知祸福也就马马虎虎了。\r', '$N惊讶地啊！了一声：各位运筹键盘之上，决胜泥潭之中，那个那个．．．世人难及，世人难及呀！\r', '$P惊讶地啊！了一声：各位运筹键盘之上，决胜泥潭之中，那个那个．．．世人难及，世人难及呀！\r', '$P对$n赞道：$R运筹于什么什么之中，决算于什么什么之外，那个那个．．．世人难及，世人难及呀！\r', '$N对$p赞道：$R运筹于什么什么之中，决算于什么什么之外，那个那个．．．世人难及，世人难及呀！\r', '$N对$n赞道：$R运筹于什么什么之中，决算于什么什么之外，那个那个．．．世人难及，世人难及呀！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (120, 'ambition', '', 'cold', '$N极目远眺，见易水潇潇，低声吟道：“路漫漫兮，其修远兮，吾愿上下而求索！”\r', '$P极目远眺，见易水潇潇，低声吟道：“路漫漫兮，其修远兮，吾愿上下而求索！”\r', '$N独立险峰，望残阳如血，慨叹道：“燕雀安知鸿鹄之志？！”\r', '$P独立险峰，望残阳如血，慨叹道：“燕雀安知鸿鹄之志？！”\r', '$P对$n微晗首，钦佩地道：“$R目光远大，壮志凌云，乃叱咤风云之士！”\r', '$N对你微晗首，钦佩地道：“$R目光远大，壮志凌云，乃叱咤风云之士！”\r', '$N对$n微晗首，钦佩地道：“$R目光远大，壮志凌云，乃叱咤风云之士！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (121, 'stare', '', 'cglaem', '$N两眼发直，口角流涎，大概是中邪了。\r', '$P两眼发直，口角流涎，大概是中邪了。\r', '$N两眼发直，口角流涎，大概是中邪了。\r', '$P两眼发直，口角流涎，大概是中邪了。\r', '$P直勾勾地盯着$n，不由得骨软筋麻，便好似雪狮子向火，不觉的都化去也。\r', '$N直勾勾地盯着$p，忍不住口角流涎，心头撞鹿，一时间骨软筋麻。便好似雪狮子向火，不觉的都化去也。\r', '$N直勾勾地盯着$n，忍不住口角流涎，心头撞鹿，一时间骨软筋麻。便好似雪狮子向火，不觉的都化去也。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (122, 'oh', '', 'bula', '哎呀，$N原来是酱子的呀！\r', '你说道：“哎呀，怎么会酱子呢？”\r', '$N说道：“噢，原来如彼。”\r', '你说道：“噢，原来如彼。”\r', '你对$n说：“噢，原来如彼。”\r', '$N对你说：“噢，原来如彼。”\r', '$N对$n说：“噢，原来如彼。”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (123, 'life', '', 'snowcat', '$N拍打着自己的脑袋，扬天狂呼道 ：男子汉大丈夫，一生于世，纵不能开疆辟野，闯一番天下，最少也要杀人放火，图一个痛快！\r', '$P霍然领悟，，扬天狂呼道 ：男子汉大丈夫，一生于世，纵不能开疆辟野，闯一番天下，最少也要杀人放火，图一个痛快！\r', '$N象是着了魔一样，转来转去像个没头苍蝇，嘴里嘀咕着些谁也听不懂的话。\r', '$P用力拍打着自己的脑袋，口中念念有词的踱来踱去 ：我活着道底是为了什么？\r', '$P拉住$n的袖子，两眼茫然无光地问道：你知道生命的真理么？\r', '$N拉住你的袖子，两眼茫然无光地问道：你知道生命的真理么？\r', '$N拉住$n的袖子，两眼茫然无光地问道：你知道生命的真理么？\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (124, 'handshake', '', 'cglaem', '$N伸出手去转了一圈，又尴尴地缩了回来。\r', '想握自己的手？\r', '$N和在场的每一个人握手。\r', '$P和在场的每一个人握手。\r', '$P很高兴地跟$n握手。\r', '$N很高兴地跟$p握手，送张签名照吧？\r', '$N很高兴地跟$n握手：偶像，送张签名照吧，外加唇印？\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (125, 'fearless', '', 'xlb', '$N碰了下桌子，小声说：“东风。。吹，战鼓。。擂。。，算我怕你成不成？”\r', '你碰了下桌子，小声说：“东风。。吹，战鼓。。擂。。，算我怕你成不成？”\r', '$N一拍桌子，大喊：＂东风吹，战鼓擂，这世界到底谁怕谁？！！！＂\r', '你一拍桌子，大喊：＂东风吹，战鼓擂，这世界到底谁怕谁？！！！＂\r', '你一拍桌子，指着$n大喊：＂东风吹，战鼓擂，这世界到底谁怕谁？！！！＂\r', '$N一拍桌子，指着你大喊：＂东风吹，战鼓擂，这世界到底谁怕谁？！！！＂\r', '$N一拍桌子，指着$n大喊：＂东风吹，战鼓擂，这世界到底谁怕谁？！！！＂\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (126, 'zzz', '', 'bula', '$N往墙角一躺，震天动地的呼噜声就响了起来。\r', '$P往墙角一躺就睡着了，迷迷糊糊好象感到地震了。。。\r', '$N揉揉双眼，一副想睡觉的样子。\r', '$P揉了揉双眼，打了个呵欠。。。\r', '$P在地下美滋滋地睡着了，好象梦到$n了。\r', '$N在地下美滋滋地睡着了，一边打呼噜还一边迷迷糊糊地说：$n，你真漂亮。\r', '$N在地下美滋滋地睡着，一边打呼噜还一边迷迷糊糊地说：$n，你真漂亮。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (127, 'u&me2', '', 'pickle', '$N一阵朗笑，吟道：天生我才必有用，千金散尽还复来！\r', '你发现泥潭中竟无一知己，不由得一阵惆怅。\r', '$N长叹一声，道：古来圣贤皆寂寞，惟有饮者留其名！来，再来一杯！\r', '你觉得天下无人识得你的才能，甚是失望。\r', '你好不容易找到了$n这个知己，希望与$p同醉。\r', '$N想把你灌醉，看来居心不良。\r', '$N一阵朗笑，吟道：$n，$R，将进酒，杯莫停。与君歌一曲，请君为我倾耳听！说罢，竟然纵喉高歌起来。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (128, 'dinner', '', 'pickle', '$N摇摇头，叹道：唉！人心不古啊！满世界的流氓全都改行当作家了，就为这一顿晚饭，值得嘛？\r', '$P气愤愤地嘀咕道：真是可恨！这帮人居然把我的生意给抢了。现在冤谁去呀？\r', '$N掏出一张作协会员证，别在胸前道：有请作家吃饭的没有？$s吃的也不多，两碗红烧狗肉，一袋子桂花酒就齐了！\r', '$P想道：今天怎么才能骗顿晚饭吃呢？\r', '$P准备了丰盛的晚饭，诚请$n同享。\r', '$N对$p说道：今儿个晚上过来吃吧！四菜一汤！\r', '$N拍了拍$n的肩膀，兴冲冲地嚷道：今儿个晚上就过来吃吧！$s亲自下厨，给你做两样$s最拿手的－－蛋炒饭和饭炒蛋！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (129, 'norumor', '', 'pickle', '$N一边鼓掌一边助兴道：是谁在造谣？真是说到$s心坎去了！太棒了！\r', '$P义愤填膺地喊道：是谁？是哪个缺德的在造谣？\r', '$N打开窗户，泼下一盆洗脚水，不想浇了某人一头，忙道：哎哟，真是对不住！早知道您老躲这儿造谣，我就倒马桶了。\r', '$P左顾右盼，就是不知是谁在造谣。:(\r', '$P客客气气地对$n道：是不是你在造谣？如果是的话请你别再折腾了。\r', '$N恶狠狠地威胁$p：$r你给我住嘴！否则$sＰＵＲＧＥ了你！\r', '$N的眼光从在场每个人身上扫过，然后停在$n脸上，问道：$r，是不是你在造谣！？看来又想喝$s的洗脚水了！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (130, 'bored', '', 'snowcat', '$N打了自己一巴掌，还是觉得很无聊。\r', '$P打了自己一巴掌，还是觉得很无聊。\r', '$N一副无精打采的模样。\r', '$P觉得整个人懒懒的，提不起精神来。\r', '$P对着$n摆出一副懒得理$p的表情。\r', '$N脸臭臭的，一副懒得理$p的模样。\r', '$N对着$n摆着一张臭脸，一副懒得理$p的模样。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (131, 'drink2', '', 'mon', '$N醉薰薰地又拿起一杯，叹道：月既不解饮，影徒随我身。\r', '$P醉薰薰地又拿起一杯，道：月既不解饮，影徒随我身。\r', '$N晃了晃酒瓶，笑道：我这人没别的毛病，就是好点这个。\r', '$P晃了晃酒瓶，道：今天可不能再喝了。\r', '$P拍了拍$n的肩膀，兴致勃勃地说道：$r，咱们喝一杯去！\r', '$N拍了拍$p的肩膀，兴致勃勃地说道：$r，咱们喝一杯去！\r', '$N拍了拍$n的肩膀，兴致勃勃地说道：$r，咱们喝一杯去！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (132, 'speech', '', 'bula', '$N对着话筒，展开稿纸念道：“兔子们，虾米们，不要酱瓜，咸菜真是太贵啦！”\r', '$P对着话筒，展开稿纸念道：“同志们，乡民们，不要讲话，现在正式开会了！”\r', '$N喊道：哎，兔子们静一静，静一静，下面俺来捡个狗屎！\r', '$P对着人群喊道：大家静一静，静一静，下面俺来讲个故事！\r', '$P噼噼啪啪鼓了一通掌，站起来说道：现在请$n乡长讲话发言！\r', '$N对着你噼噼啪啪鼓了一通掌，站起来说道：咸菜请$n香肠酱瓜放盐！\r', '$N噼噼啪啪鼓了一通掌，站起来说道：咸菜请$n香肠酱瓜放盐！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (133, 'sigh', '', 'pickle', '$N觉得万念俱灰，难过地叹了口气。\r', '$P觉得万念俱灰，不由得叹了口气。\r', '$N「唉」的一声叹了口气。\r', '$P叹了口气。\r', '$P对着$n叹了口气。\r', '$N对着$p叹了口气，不知道哪里不对了。\r', '$N对着$n叹了口气。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (134, 'young', '', 'ajax', '$N无精打彩的说道：“我们已经老了，无所谓了，你们还年轻，来日方长！”\r', '你无精打彩的说道：“我们已经老了，无所谓了，你们还年轻，来日方长！”\r', '$N无可奈何地叹道：“现在的年轻人呀！”\r', '你无可奈何地叹道：“现在的年轻人呀！”\r', '你拍着$n的头，欣慰的说道：“这个小同志很可爱嘛！”\r', '$N拍着你的头，欣慰的说道：“这个小同志很可爱嘛！”\r', '$N拍着$n的头，欣慰的说道：“这个小同志很可爱嘛！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (135, 'support', '', 'cold', '$N抱拳诚恳地道：“请大家支持我！”\r', '$P抱拳诚恳地道：“请大家支持我！”\r', '$N环视了一下四周，抱拳诚恳地道：“请诸位多多支持！”\r', '$P环视了一下四周，抱拳诚恳地道：“请诸位多多支持！”\r', '$P挤出人群，大声道：“我，我支持$n！！！”\r', '$N挤出人群，大声道：“我，我支持$n！！！”\r', '$N挤出人群，大声道：“我，我支持$n！！！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (136, 'yawn', '', 'bula', '$N打了一个哈欠，嘴角流下一串哈啦子。:)~~~\r', ' $P打了一个哈欠，嘴角流下一串哈啦子。\r', '$N打了一个哈欠。\r', '$P打了一个哈欠。\r', '$P对着$n打了个大哈欠。\r', '$N对着你打了个大哈欠。\r', '$N对着$n打了个哈欠。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (137, 'slap', '耳光', 'pickle', '$N打了自己几巴掌。嗯，大概吃药时间到了。\r', '$P用力地打了自己几个巴掌。\r', '$N一巴掌打在空气里。\r', '$P要打谁？\r', '$P狠狠掴了$n几个大耳光。\r', '$N狠狠掴了$p几个大耳光，打得$p“满天全金条，要抓没半条”。\r', '$N狠狠掴了$n几个大耳光，打得$n眼冒金星。\r', 1, 0, '2026-05-23 04:17:30');
INSERT INTO `emotes` VALUES (138, 'touch', '', 'snowcat', '$N轻轻地摸着自己的脸, 嘀嘀咕咕：“我真这么可爱？！”\r', '$P轻轻地摸着自己的脸, 嘀嘀咕咕：“我真这么可爱？！”\r', '$N粘粘地说道：“我好喜欢你们哦．．．”\r', '$P粘粘地说道：“我好喜欢你们哦．．．”\r', '$P轻轻地摸着$n的脸，无限深情地说：“我好喜欢你哦．．．”\r', '$N轻轻地摸着$p的脸，无限深情地说：“我好喜欢你哦．．．”\r', '$N轻轻地摸着$n的脸，无限深情地说：“我好喜欢你哦．．．”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (139, 'ugly', '', 'pickle', '$N哈哈大笑，说道：$s是英而不俊，虽然丑陋异常，却是英气勃勃，可称英丑。\r', '$P哈哈大笑，说道：$s是英而不俊，虽然丑陋异常，却是英气勃勃，可称英丑。\r', '$N开始有点怀疑自己是不是猪八戒的本家了。\r', '$P长得三尺多高，四尺多宽，五尺多厚，眼如绿豆，口若血盆，端的是豪气逼人。\r', '$P对$n拍手唱道：矮冬瓜，滚皮球，踢一脚，溜三溜；踢两脚。。。唉呀不好。。。$n要杀了$P！\r', '$N对$p拍手唱道：矮冬瓜，滚皮球，踢一脚，溜三溜；踢两脚。。。\r', '$N对$n拍手唱道：矮冬瓜，滚皮球，踢一脚，溜三溜；踢两脚。。。救命啊～～～$n要杀人灭口！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (140, 'inn', '', 'pickle', '$N看起来十分忧郁。\r', '$P感到闷闷不乐。\r', '$N十分委曲地流下泪来。\r', '$P感到十分委曲。\r', '$P无辜地望着$n。\r', '$N的眼中充满泪水，无辜地望着$p。\r', '$N的眼中充满泪水，无辜地望着$n。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (141, 'zap', '', 'bula', '$N从天上召来一道闪电，「轰！」的一声打到自己身上。\r', '$P从天上召来一道闪电，把自己化为灰烬。\r', '$N站在法台，披头散发大声喊到：风来，电来，雨来。。。\r', 'Zap 谁？\r', '$P从天上召来一道闪电，把$n化为灰烬。\r', '$N从天上召来一道闪电朝$p打来，毁了！$p变成一堆灰烬。\r', '$N从天上召来一道闪电把$n化为一堆灰烬。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (142, 'wawa', '', 'ajax', '$N决定从小努力挖泥。\r', '你决定从小努力挖泥。\r', '$N小声嘀咕道：哪来的这些小娃娃，乳臭未干，也来跟我斗？\r', '你小声嘀咕道：哪来的这些小娃娃，乳臭未干，也来跟我斗？\r', '你拍着$n的头，语重心长的说道：挖泥巴要从娃娃抓起！\r', '$N拍着你的头，语重心长的说道：挖泥巴要从娃娃抓起！\r', '$N拍着$n的头，语重心长的说道：挖泥巴要从娃娃抓起！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (143, 'goodbye', '', 'weiqi', '$N长叹一声道：一曲离歌泪千行，不知何日再逢君。我这就去了，大家多保重。\r', '$P长叹一声道：一曲离歌泪千行，不知何日再逢君。我这就去了，大家多保重。\r', '$N跟大家挥手道别。\r', '$P跟大家挥手道别。\r', '$P拎着个桂花酒袋对$n道：劝君更尽一袋酒，离潭此去无故人。\r', '$N拎着个桂花酒袋对$p道：劝君更尽一袋酒，离潭此去无故人。\r', '$N拎着个桂花酒袋对$n道：劝君更尽一袋酒，离潭此去无故人。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (144, 'hny', '', 'bula', '$N笑呵呵地一拱手，道：各位，新年好，$S给您道喜了！\r', '$P笑呵呵地一拱手：各位，新年好，$S给您道喜了！\r', '$N笑呵呵地一拱手：各位，新年好，恭喜发财！\r', '$P笑呵呵地说道：各位，新年好，恭喜发财！\r', '$P对着$n笑呵呵地一拱手：新年好，恭喜发财！\r', '$N对着$p笑呵呵地一拱手：新年好，恭喜发财！\r', '$N对着$n笑呵呵地一拱手：新年好，恭喜发财！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (145, 'boring', '', 'cold', '$N满怀愁绪，一遍一遍地往湖里扔着石子．．．，喃喃自语：“无聊，真无聊！”\r', '$P满怀愁绪，一遍一遍地往湖里扔着石子．．．，喃喃自语：“无聊，真无聊！”.\r', '$N痴呆呆地盯着湖面，一遍一遍地扔着石子．．．．．．\r', '$P呆呆地盯着湖面，一遍一遍地扔着石子．．．．．．\r', '$P对$n说：“无聊吧？”，说着递给$n一把石子：“一起扔吧？”。\r', '$N同情地对$p说：“无聊吧？”，说着递给$p一把石子：“一起扔吧？”。\r', '$N同情地对$n说：“无聊吧？”，说着递给$n一把石子：“一起扔吧？”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (146, 'trip', '', 'cglaem', '$N一脚踩上西瓜皮，来了个特技大表演。好~~~臀先着地！\r', '$P一脚踩上西瓜皮，来了个特技大表演。\r', '$N拿着一块西瓜皮，不怀好意地踱来踱去。\r', '$P拿着一块西瓜皮，不怀好意地踱来踱去。\r', '$P在$n脚底下偷偷地放了块西瓜皮，美滋滋地看着$p踩上去。\r', '$N在$p脚底下偷偷地放了块西瓜皮，美滋滋地看着$p踩上去。\r', '$N在$n脚底下偷偷地放了块西瓜皮，美滋滋地看着$p踩上去。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (147, 'nofear', '', 'pickle', '$N不停地安慰自己：塞翁失马，安知非福？加上上星期在暖气上磕出来的疤，头上就凑足仨旋儿了！\r', '你仔细摸了摸头发，不禁暗自嘀咕道：咦？旋儿呢？怎么在要打架的节骨眼儿上找不到了？\r', '$N大声吆喝道：一旋儿横，二旋儿愣，三旋儿打架不要命！$s头上仨旋儿正，看谁有胆儿跟我横？！\r', '你大声安慰众人道：别怕！怕什么？天塌下来有$s头上的仨旋儿顶着！\r', '你鼓舞$n道：$r，胆子放大！头上这仨旋儿难道是白长的么？\r', '$N失望地对你长叹一声，道：看来你生来就不是打架的料，费了老鼻子劲儿才勉强长出一个旋儿来。\r', '$N对$n吆喝道：怕什么？没听人说么？一旋儿横，二旋儿愣，三旋儿打架不要命。$r你头上油光锃亮、寸草不生的，比别人仨旋儿加一起还大，还怕什么？\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (148, 'jump', '', 'cglaem', '$N象皮球似的在地上弹了几下。\r', '$P象皮球似的在地上弹了几下。\r', '$N高兴地跳起老高，在空中停了好一会才掉下来。\r', '$P高兴地跳了起来。\r', '$P高兴地跳进了$n的怀里。\r', '$N高兴地跳进了$p的怀里。$P好沉哪！\r', '$N高兴地跳进了$n的怀里！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (149, 'flip', '', 'pickle', '$N湿淋淋地从水中爬出来，心道：这条大江，至少也得有三米多宽，一米多深，而且又不臭－－我总算不是在条阴沟里翻的船。\r', '你左右看看，发现没人看见你翻船，不由出了一口长气。\r', '$N苦口婆心地劝道：大家都是闯过大风大浪的人了，可别一个疏忽，在阴沟里翻了船！\r', '你就怕在阴沟里翻了船，干什么都是小心翼翼的。\r', '你对$n道：你喜欢吃刀削面还是馄饨？我立刻去给你做。\r', '$N恶狠狠地对你喊道：你是想被$s一刀一刀切了，还是自己乖乖的跳下水去？\r', '$N站在船头，手拿明晃晃的钢刀，对$n恶狠狠地说道：$r，你是想吃刀削面还是想吃馄饨？快说！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (150, 'lazy', '', 'cglaem', '$N伸了个懒腰，嘟咙道：我这人说不定真的很懒。\r', '$P伸了个懒腰，嘟咙道：我这人说不定真的很懒。\r', '$N懒洋洋地活动了一下手脚。\r', '$P懒洋洋地活动了一下手脚。\r', '$P对着$n恨声道：真是个懒鬼！\r', '$N对着$p恨声道：真是个懒鬼！\r', '$N对着$n恨声道：真是个懒鬼！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (151, 'sob', '', 'cold', '$N抱着头放声大哭，动山河泣鬼神，边哭边嚎：“你们欺负我！你们欺负我！”\r', '$P抱着头放声大哭，动山河泣鬼神，边哭边嚎：“你们欺负我！你们欺负我！”\r', '$N一脸涨红，道：“难道我就是那么低三下四之人，任你这么欺侮的麽！？”说到这里不禁气极而泣。\r\r', '$P一脸涨红，道：“难道我就是那么低三下四之人，任你这么欺侮的麽！？”说到这里不禁气极而泣。\r', '$P突然小嘴一扁，放声大哭起来，边哭边对$n道：“你欺负我！你欺负我！”\r', '$N突然小嘴一扁，放声大哭起来，边哭边对你道：“你欺负我！你欺负我！”\r', '$N突然小嘴一扁，放声大哭起来，边哭边对$n道：“你欺负我！你欺负我！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (152, 'date', '', 'cglaem', '$N看着一对对情人走来走去，不由得一阵委屈。\r', '$P看着一对对情人走来走去，不由得一阵委屈。\r', '$N开始考虑今天晚上该约谁。\r', '$P开始考虑今天晚上该约谁。\r', '$P大大方方地对$n说：今晚有空吗？我请你吃饭。\r', '$N期期艾艾地对$p说：今晚有空吗？我。。。\r', '$N大声宣布：我要开始跟$n约会了！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (153, 'love', '', 'cglaem', '$N长叹一声：酒醒寒夜时，独徘黄昏处。年少伤心事，只恐无人知。\r', '$P长叹一声：酒醒寒夜时，独徘黄昏处。年少伤心事，只恐无人知。\r', '$N长叹一声：问世间，情是何物，直叫人生死相许。\r', '$P长叹一声：问世间，情是何物，直叫人生死相许。\r', '$P搂着$n，在$p的耳边悄声道：相思知何日，此夜难为情。\r', '$N搂着$p，在$p的耳边悄声道：相思知何日，此夜难为情。\r', '$N搂着$n，在$p的耳边说起了悄悄话。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (154, 'dunno', '', 'snowcat', '$N说道：我不知道我在说什么．．．\r', '$P说道：我不知道我在说什么．．．\r', '$N摇摇头说道：我不知道．．．\r', '$P摇摇头说道：我不知道．．．\r', '$P问$n：你说什么我不懂耶．．．\r', '$N问$p：你说什么我不懂耶．．．\r', '$N问$n：你说什么我不懂耶．．．\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (155, 'touchy', '', 'cglaem', '$N唏嘘不已：真的，我不是一个多愁善感的人。。。\r', '$P似乎有些不能自已。\r', '$N感动得热泪盈眶。\r', '$P感动极了。\r', '$P被$n深深地感动了。\r', '$N被$p深深地感动了：真的，我不是一个多愁善感的人。。。\r', '$N看着$n，激动得泣不成声：真的，我不是一个多愁善感的人。。。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (156, 'shysmile', '', 'joy', '$N悄然地自个儿腼腆地笑了笑。\r', '$P悄然地自个儿腼腆地笑了笑。\r', '$N腼腆地笑了笑。\r', '$P腼腆地笑了笑。\r', '$P对着$n腼腆地笑了笑。\r', '$N对你腼腆地笑了笑。\r', '$N对$n腼腆地笑了笑。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (157, 'welcome', '欢迎', 'cglaem', '$N作了个四方揖，抓耳挠腮地笑道：$S新入道途，大家多多指教。。。\r', '$P作了个四方揖，抓耳挠腮地笑道：$S新入道途，大家多多指教。。。\r', '$N抓着几颗猕猴桃，翻了个筋斗，嘴里吱吱吱地一阵乱叫~~\r', '$P抓着几颗猕猴桃，翻了个筋斗，高声叫道：欢迎，欢迎，热烈欢迎！\r', '$P翻了几个筋斗，手中的猕猴桃啪！地一声砸中$n，叫道：欢迎，欢迎，热烈欢迎！\r', '$N翻了几个筋斗，手中的猕猴桃啪！地一声砸中$p，叫道：欢迎，欢迎，热烈欢迎！\r', '$N翻了几个筋斗，手中的猕猴桃啪！地一声砸中$n，叫道：欢迎，欢迎，热烈欢迎！\r', 1, 0, '2026-05-23 04:14:20');
INSERT INTO `emotes` VALUES (158, ':)', '', 'yyzz', '$N笑了笑。\r', '$P笑了笑。\r', '$N笑了笑。\r', '$P笑了笑。\r', '$P对$n笑了笑。\r', '$N对$p笑了笑。\r', '$N对$n笑了笑。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (159, 'nogig', '', 'cglaem', '$N不停地对自己说：我不能咯咯，不能~~咯咯咯咯咯咯咯咯~~ \r', '$P不停地对自己说：我不能咯咯，不能~~咯咯咯咯咯咯咯咯~~\r', '$N捂住耳朵惨叫道：天啦，人人都在下蛋~~ \r', '$P捂住耳朵惨叫道：天啦，人人都在下蛋~~ \r', '$P捂着耳朵对$n说：求求你，别再咯咯了，再咯咯我都要下蛋了:(\r', '$N捂着耳朵对$p说：求求你，别再咯咯了，再咯咯我都要下蛋了:( \r', '$N捂着耳朵对$n说：求求你，别再咯咯了，再咯咯我都要下蛋了:(\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (160, 'nokill', '', 'snowcat', '$N脸上露出淡淡的哀愁：东西南北，日月星辰，这天上地下难道就没有一块无争无杀的净土么？\r', '$P脸上露出淡淡的哀愁：东西南北，日月星辰，这天上地下难道就没有一块无争无杀的净土么？\r', '$N很严肃地说道：善有善报，恶有恶报，不是不报，是时候未到。\r', '$P很严肃地说道：善有善报，恶有恶报，不是不报，是时候未到。\r', '$P对$n劝道：因果循环，报应不爽，$R还是得饶人处且饶人吧。\r', '$N对$p劝道：因果循环，报应不爽，$R还是得饶人处且饶人吧。\r', '$N对$n劝道：因果循环，报应不爽，$R还是得饶人处且饶人吧。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (161, 'shameless', '', 'snowcat', '$N洋洋自得地说道：“我的脸皮就是厚。你们想学我还不肯教呢！”\r', '$P觉得自己的厚脸皮得来不易，大家都该向$P学习。\r', '$N的脸皮在西游记中也算是数一数二的厚了。听了别人的耻笑，脸上都不带红一红的。\r', '$P对自己的无耻感到非常光荣，不停地向大家炫耀。\r', '$P毫不留情地耻笑$n的无耻，但$p显然毫不惭愧。\r', '$N对$p的无耻感到非常羡慕，希望$p能够收$P为徒。\r', '$N对$n说道：“阁下听了这样的话，居然脸不红，心不跳，真是功力深厚！不知在下这等条件，可否学到您本领的万一？”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (162, 'sigh2', '', 'ajax', '$N无可奈何地叹道：“这年头！”\r', '你无可奈何地叹道：“这年头！”\r', '$N叹道：“这年头！”\r', '你叹道：“这年头！”\r', '你对着$n长叹道：“这年头！”\r', '$N对着你长叹道：“这年头！”\r', '$N对着$n长叹道：“这年头！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (163, 'know', '', 'weiqi', '$N气愤地说：“现在净有人冒充跟我熟，其实压根没见过──社会上有些人就爱乱传我！”\r', '$P气愤地说：“现在净有人冒充跟我熟，其实压根没见过──社会上有些人就爱乱传我！”\r', '$N大大咧咧地坐在破藤椅上，一把一把往後捋他那头毛泽东式的长发，“都以为$N不定多享受呢，其实……其实我还是个普通人。”\r\r', '$P大大咧咧地坐在破藤椅上，一把一把往後捋你那头毛泽东式的长发，“都以为$N不定多享受呢，其实……其实我还是个普通人。”\r', '$P恍然大悟地对$n说：“像您这样的大人物，难得的就是寂寞吧？”\r', '$N恍然大悟地对$p说：“像您这样的大人物，难得的就是寂寞吧？”\r', '$N恍然大悟地对$n说：“像您这样的大人物，难得的就是寂寞吧？”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (164, 'idle', '', 'mon', '$N怔怔地对着自己发起呆来。\r', '$P怔怔地对着自己发起呆来。\r', '$N一屁股坐在地上发起呆来。\r', '$P一屁股坐在地上发起呆来。\r', '$P拍拍$n的肩膀：嗨，$r，一起发呆吧。\r', '$N拍拍$p的肩膀：嗨，$r，一起发呆吧。\r', '$N拍拍$n的肩膀：嗨，$r，一起发呆吧。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (165, 'hi', '请了', 'cglaem', '$N双手抱拳，作了个揖道：各位仙长，还记得$N吗？\r', '$P双手抱拳，作了个揖道：各位仙长，还记得$N吗？\r', '$N双手抱拳，作了个揖道：各位仙长请了！\r', '$P双手抱拳，作了个揖道：各位仙长请了！\r', '$P双手抱拳，对$n作了个揖道：这位$R请了！\r', '$N双手抱拳，对$p作了个揖道：这位$R请了！\r', '$N双手抱拳，对$n作了个揖道：这位$R请了！\r', 1, 0, '2026-05-23 04:08:56');
INSERT INTO `emotes` VALUES (166, 'goaway', '', 'cglaem', '$N无可奈何地说：惹不起还躲不起吗。。。\r', '$P无可奈何地说：惹不起还躲不起吗。。。\r', '$N满脸的不耐烦：别理我，烦着呢！\r', '$P满脸的不耐烦：别理我，烦着呢！\r', '$P看着$n，满脸的不耐烦：离我远点！\r', '$N看着$p，满脸的不耐烦：离我远点！\r', '$N看着$n，满脸的不耐烦：离我远点！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (167, 'snow', '', 'ajax', '$N一人独自站在雪中，忘情的唱道：北风那个吹~~，雪花那个飘~~\r', '你一人独自站在雪中，忘情的唱道：北风那个吹~~，雪花那个飘~~\r', '天空中飘着雪花，$N心中思绪万千。\r', '天空中飘着雪花，你心中思绪万千。\r', '望着雪中$n逐渐远去的影子，你再也忍不住心中悲伤，呜呜痛哭起来。\r', '望着雪中你逐渐远去的影子，$N再也忍不住心中悲伤，呜呜痛哭起来。\r', '望着雪中$n逐渐远去的影子，$N再也忍不住心中悲伤，呜呜痛哭起来。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (168, 'pain', '', 'pickle', '$N觉得一丝隐隐的痛从心底泛上来。\r', '$P觉得一丝隐隐的痛从心底泛上来。\r', '$N痛得吱哇乱叫。\r', '$P痛得吱哇乱叫。\r', '$P对$n说道：为什么要打我？你知不知道会很痛的耶！\r', '$N对$p说道：为什么要打我？你知不知道会很痛的耶！\r', '$N对$n说道：为什么要打我？你知不知道会很痛的耶！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (169, 'byebye', '再会', 'weiqi', '$N起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$P起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$N起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$P起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$P望空作了个揖，对$n嘱咐道：此去西天路遥，$R一路保重！\r', '$N对$p作了个揖道：此去西天路遥，$R一路保重！\r', '$N望空作了个揖，对$n嘱咐道：此去西天路遥，$R一路保重！\r', 1, 0, '2026-05-23 04:10:56');
INSERT INTO `emotes` VALUES (170, 'woman', '', 'opal', '$N指着自己的鼻子说：＂本姑娘就是傻得可爱么．＂\r', '你觉得自己好妩媚动人呦．\r', '$N故作东施状，好恶心噢！\r', '女人啊．．．\r', '$N深沉地对$n道：＂作女人难，作名女人更难－－－作像这样的女人，那就难上加难！＂\r\r', '$N深切地对你说：＂你是个百分之百的女人喔！＂\r', '$N深切地对$n说道：＂作女人难，作名女人更难－－－作像你这样的女人，那就更是难上加难！＂\r\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (171, ':P', '', 'bula', '$N吐了吐舌头。 \r', '$P吐了吐舌头。 \r', '$N惊讶得吐出了舌头。\r', '$P惊讶地吐出舌头。\r', '$P冲着$n吐了吐舌头。\r', '$N冲着$p吐了吐舌头。   \r', '$N冲着$n吐了吐舌头。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (172, 'dance', '', 'snowcat', '$N抱着一张凳子，在那里转来转去。\r', '$P抱着一张凳子，专心一意地苦练舞技。\r', '$N高兴得手舞足蹈！\r', '$P高兴地跳起舞来！\r', '$P拉起$n的小手跳起舞来！快乐地旋转！\r', '$N拉起$p的小手跳起舞来！兴奋得快晕倒了。\r', '$N拉起$n的小手跳起舞来！俩人好陶醉的样子！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (173, 'maoli', '', 'snowcat', '$N将指节咔地一捏，伸手在自己的歪脑门上敲了一个双响脆毛栗子。\r', '$P将指节咔地一捏，伸手在自己的歪脑门上敲了一个双响脆毛栗子。\r', '$N潇洒地将指节捏得咔咔做响。\r', '$P将指节捏得咔咔做响。\r', '$P将指节咔地一捏，伸手在$n的歪脑门上敲了一个双响脆毛栗子。\r', '$N将指节咔地一捏，伸手在$p的歪脑门上敲了一个双响脆毛栗子。\r', '$N将指节咔地一捏，伸手在$n的歪脑门上敲了一个双响脆毛栗子。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (174, 'pure', '', 'snowcat', '$N看起来一脸天真．．．好可爱耶～～～\r', '$P作出天真状。\r', '$N看起来一脸天真。\r', '$P觉得自己还很不成熟。\r', '$P天真地望着$n。\r', '$N用大大的眼睛，天真地望着$p．．．．(@_@)。\r', '$N用大大的眼睛，天真地望着$n．．．．(@_@)。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (175, 'pig2', '', 'bula', '$N自言自语道：俗话说的好：顺手牵羊，反手牵猪！吃羊肉惹一身羊膻气，这花雕茯苓猪我可着实吃了不少。\r', '$P自言自语道：俗话说的好：顺手牵羊，反手牵猪！吃羊肉惹一身羊膻气，这花雕茯苓猪我可着实吃了不少。\r', '$N大声吆喝道：小号祖传秘方饲养的花雕茯苓猪，大补！快来尝啊！\r', '$P大声吆喝道：小号祖传秘方饲养的花雕茯苓猪，大补！快来尝啊！\r', '$P对$n吆喝道：瞧你这瘦骨伶仃的，成天吃什么羊啊！来跟我拱猪吧，保你把花雕茯苓猪吃个饱！\r', '$N对$p吆喝道：瞧你这瘦骨伶仃的，成天吃什么羊啊！来跟我拱猪吧，保你把花雕茯苓猪吃个饱！\r', '$N对$n吆喝道：瞧你这瘦骨伶仃的，成天吃什么羊啊！来跟我拱猪吧，保你把花雕茯苓猪吃个饱！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (176, 'haha', '', 'dream', '$N哈哈大笑了几声。\r', '你哈哈大笑了几声。\r', '$N哈哈大笑了几声。\r', '你哈哈大笑了几声。\r', '你对$n哈哈大笑了几声。\r', '$N对你哈哈大笑了几声。\r', '$N对$n哈哈大笑了几声。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (177, 'miss', '', 'cold', '$N揉了揉略觉痒痒的鼻子，微微哽咽地道：“你别跟我说你想我！”\r', '$P揉了揉略觉痒痒的鼻子，微微哽咽地道：“你别跟我说你想我！”\r', '$N一边摇着折扇，一边抑扬顿挫地吟道：“为伊消得人憔悴！”\r', '$P一边摇着折扇，一边抑扬顿挫地吟道：“为伊消得人憔悴！”\r', '$P出神地望着$n，轻轻地低叹一声道：“为伊消得人憔悴！”\r', '$N出神地望着你，轻轻地低叹一声道：“为伊消得人憔悴！”\r', '$N出神地望着$n，轻轻地低叹一声道：“为伊消得人憔悴！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (178, 'bigsis', '', 'bula', '$N满脸的委屈：我姐姐呢？去哪儿了？：（\r', '$P满脸的委屈：我姐姐呢？去哪儿了？：（\r', '$N两眼放出奇异的光彩，嘴里嘟嘟囔囔，见人就叫：姐姐，姐姐！\r', '$P两眼放出奇异的光彩，嘴里嘟嘟囔囔，见人就叫：姐姐，姐姐！\r', '$P满脸欣喜加严肃地向$n敬个礼：姐姐好！\r', '$N满脸欣喜加严肃地向$p敬个礼：姐姐好！\r', '$N满脸欣喜加严肃地向$n敬个礼：姐姐好！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (179, 'pain2', '', 'pickle', '$N眉花眼笑地想：人都说打是疼，骂是爱，人家会不会，这个这个。。。\r', '$P低下头去，但忍不住心下窃喜，念道：打是疼，骂是爱，想急了上脚踹。\r', '$N得意洋洋地说道：我当然知道你痛啦！不痛我干嘛打你？\r', '$P结结巴巴地道歉：实在是对不住，我下次再也不敢打了。\r', '$P挠了挠头，问$n道：$R刚才是不是帮我挠痒痒来着？真是多谢了！\r', '$N气势汹汹地教训$p道：你这人是怎么搞的？幸亏我身子骨硬，别人挨你这么一下子，还不得立马进医院急诊室去？！\r', '$N掸了掸屁股上的尘土，对$n道：你这人怎么这么小的劲？这一下子还不够给我挠痒痒的呢！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (180, 'peerless', '', 'joy', '$N苦涩地笑了一笑，叹道：“寂寞高手，只求一败！”\r', '$P淡淡地道：“我．．．我等了三十年，仍无敌手？！”\r', '$N仰天长叹一声，说道：“如今人才凋零，青黄不接，一代不如一代！！”\r', '$P仰天长叹一声，说道：“如今人才凋零，青黄不接，一代不如一代！！”\r', '$P对着$n冷笑道：“你算老几？竟然想与我过招！”\r', '$N对着你冷笑道：“你？你算老几？竟然想与我过招！”\r', '$N对着$n冷笑道：“你？你算老几？竟然想与我过招！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (181, 'comfort', '', 'rep', '$N安慰自己说：没关系！\r', '$P安慰自己说：没关系！\r', '$N露出关爱的眼神：没关系！\r', '$P露出关爱的眼神：没关系！\r', '$P安慰$n。\r', '$N安慰$p。\r', '$N安慰$n：别难过了。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (182, 'faint', '', 'cglaem', '$N口吐白沫，昏倒在地上。\r', '$P昏倒了。\r', '$N口吐白沫，昏倒在地上。\r', '$P昏倒了。\r', '$P昏倒了，倒在$n的怀里。\r', '$N突然昏倒在$p的怀抱中。\r', '$N突然昏倒在$n的怀中。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (183, 'curtain', '', 'crab', '$N一边卷着竹帘一边想，今天用竹帘打谁的头好呢？\r', '$P一边卷着竹帘一边想，今天用竹帘打谁的头好呢？\r', '$N慢慢地卷着竹帘，似乎在想着无限心事。\r', '$P慢慢地卷着竹帘，似乎在想着无限心事。\r', '$P怔怔地看着$n，一个不小心，竹帘掉了下去，斜斜地打在$n头上。\r', '$N怔怔地看着你，一个不小心，竹帘掉了下去，斜斜地打在你头上。\r', '$N怔怔地看着$n，一个不小心，竹帘掉了下去，斜斜地打在$n头上。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (184, 'beauty', '', 'cglaem', '$N轻轻地笑了一声，低声唱道：含羞问檀郎，花强妾貌强？\r', '$P轻轻地笑了一声，低声唱道：含羞问檀郎，花强妾貌强？ \r', '$N摇头晃脑地吟道：窈窕淑女，君子好逑。\r', '$P摇头晃脑地吟道：所谓伊人，在水一方。 \r', '$P看着$n长叹一声道：当真是回头一笑百媚生，泥潭粉黛无颜色。 \r', '$N看着$p长叹一声道：当真是回头一笑百媚生，泥潭粉黛无颜色。 \r', '$N看着$n长叹一声道：当真是回头一笑百媚生，泥潭粉黛无颜色。 \r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (185, 'consider', '', 'snowcat', NULL, NULL, '$N开始认真考虑这个问题。\r', '$P开始认真考虑。\r', '$P开始认真考虑杀死$n的可能性。\r', '$N不怀好意地绕着$p打转, 嘴巴里不知在嘀咕些什么。\r', '$N不怀好意地绕着$n打转，嘴巴里不知在嘀咕些什么。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (186, 'bug', '', 'weiqi', '$N暗自奸笑：让我来搞点小破坏。。。\r', '$P暗自奸笑：让我来搞点小破坏。。。\r', '$N大声叫了起来：哎呀，不得了啦！又出毛病了！\r', '$P大声叫了起来：哎呀，好象不对头！\r', '$P对着$n大喝一声：好你个$r，想搞破坏！\r', '$N对着$p大喝一声：好你个$r，想搞破坏！\r', '$N对着$n大喝一声：好你个$r，想搞破坏！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (187, 'endbula', '', 'bula', '$N似喜似忧：“弹起我心爱的土琵琶，我也是那香喷喷的炸蚂蚱！”\r', '$P无可奈何：“弹起我心爱的土琵琶，我也是那香喷喷的炸蚂蚱！”\r', '$N无限欢欣：“弹起我心爱的土琵琶，吃着那香喷喷的炸蚂蚱！”\r', '$P无限欢欣：“弹起我心爱的土琵琶，吃着那香喷喷的炸蚂蚱！”\r', '$P喜出望外：“弹起我心爱的土琵琶，就吃$n这香喷喷的炸蚂蚱！”\r', '$N满脸狡诈：“弹起我心爱的土琵琶，就吃你这香喷喷的炸蚂蚱！”\r', '$N满脸狡诈：“弹起我心爱的土琵琶，就吃$n这香喷喷的炸蚂蚱！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (188, 'loser', '', 'pickle', '$N高声吟道：“技不如人兮，脸上无光！再练十年兮，又输精光！不如罢休兮，吃尽当光！”\r', '你得意洋洋地吹道：哼！$s不愿跟你们一般见识，让着你们的！\r', '$N拍手笑道：“胜败乃兵家常事，$s是漫不在乎的！”说罢扬长而去。\r', '你技不如人，羞愧万分，恨不得立刻死了才好。\r', '你看$n打败了，不停地出言讽刺。\r', '$N安慰你道：“别怕，君子报仇，十年不晚！$R现在技不如人，正当发愤图强，以图将来挣回这个面子！”\r', '$N对$n一抱拳，赞道：“$R胜固欣然败亦喜，果然是得了斗道三昧，令人好生相敬！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (189, 'scowl', '', 'snowcat', '$N对自己挤眉弄眼！\r', '$P对自己挤眉弄眼！\r', '$N皱起眉来！好像踌躇什么！\r', '$P皱起眉来！\r', '$P对$n作横眉竖目状！\r', '$N对$p作横眉竖目状！\r', '$N对$n作横眉竖目状！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (190, 'thank', '感谢', 'mon', '$N对自己道谢。\r', '你由衷地感谢自己。\r', '$N对所有在场的人鞠躬道谢！\r', '你对在场的所有人鞠躬道谢！\r', '你由衷地向$n道谢。\r', '$N向你道谢。\r', '$N由衷地感谢$n。\r', 1, 0, '2026-05-23 04:12:30');
INSERT INTO `emotes` VALUES (191, 'hit', '打', 'pickle', '$N嘿嘿嘿地笑了几声：就你那枣核也似的拳头，也来打我？\r', '$P嘿嘿嘿地笑了几声：就你那枣核也似的拳头，也来打我？\r', '$N举起拳头，仔细地看了看。\r', '打谁？\r', '你一拳打在$n的肚皮上，正中红心，爽啊！\r', '$N一拳打在$p的肚皮上。好痛喔！\r', '$N一拳打在$n的肚皮上。\r', 1, 0, '2026-05-23 04:16:44');
INSERT INTO `emotes` VALUES (192, 'sleepy', '', 'bula', '$N在睡梦中甜蜜地笑着，口水流了一枕头。\r', '$P抱着自己的肩头入睡。\r', '$N倒在地上睡着了。\r', '$P揉揉眼、打个哈欠，立刻躺倒在地上了。\r', '$P躺在$n的怀里睡着了。\r', '$N躺在$p的怀里睡着了。\r', '$N躺在$n的怀里睡着了。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (193, 'hurry', '', 'snowcat', '$N嘟嘟咙咙道：唉真是的。。。皇帝不急太监急。\r', '$P嘟嘟咙咙道：唉真是的。。。皇帝不急太监急。\r', '$N急得象热锅上的蚂蚁，不耐烦地吼道：快点！快点！怎么比猪还慢？！\r', '$P急得象热锅上的蚂蚁，不耐烦地吼道：快点！快点！怎么比猪还慢？！\r', '$P不耐烦地对$n吼道：有话就说，有屁快放！\r', '$N不耐烦地对$p吼道：有话就说，有屁快放！\r', '$N不耐烦地对$n吼道：有话就说，有屁快放！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (194, 'duh', '', 'snowcat', '$N用力地拍了一下自己的脑袋，大声地说：「对呀！我怎么没想到？！」\r', '$P用力地拍了一下自己的脑袋，大声地说：「对呀！我怎么没想到？！」\r', '$N用力地拍了一下自己的脑袋，很吃惊地叫了一声。\r', '$P用力地拍了一下自己的脑袋，很吃惊地叫了一声。\r', NULL, NULL, NULL, 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (195, 'baobao', '', 'bula', '$N撇着嘴，委屈得都要哭了：你们对宝宝一点也不好~~~\r', '$P撇着嘴，觉得很委屈。\r', '$N歪着头，天真地对大家说：我真的是个乖宝宝吗？\r', '$P觉得自己就是乖。\r', '$P拍了拍$n的头：宝宝听话，一会ㄦ给你买人参果。\r', '$N拍了拍$p的头道：宝宝听话，一会ㄦ给你买人参果。\r', '$N拍了拍$n的头道：宝宝听话，一会ㄦ给你买人参果。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (196, 'zaocao', '', 'xlb', '$N开开心心地开始做早操。\r', '你开开心心地开始做早操。\r', '$N揉了揉眼睛，高兴的做起了早操。\r      ●       ●）     ●      ●）   ＼●／    ＼●\r    ＜┃＞   （┃     （┃）   （）     ┃┃      （ ＞ \r     ／＼     ／ ）    （＼    ／ ）   ／  ＼     ／＼\r  ==左三圈，右三圈，脖子扭扭，屁股扭扭，大家一起来做运动==\r\r', '你揉了揉眼睛，高兴的做起了早操。\r      ●       ●）     ●      ●）   ＼●／    ＼●\r    ＜┃＞   （┃     （┃）   （）     ┃┃      （ ＞ \r     ／＼     ／ ）    （＼    ／ ）   ／  ＼     ／＼\r  ==左三圈，右三圈，脖子扭扭，屁股扭扭，大家一起来做运动==\r\r', '你对$n喊道：“来，快来跟我一起做运动！”\r', '$N对$p喊道：“来，快来跟我一起做运动！”\r', '$N对$n喊道：“来，快来跟我一起做运动！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (197, 'cat', '', 'snowcat', '$N咪声咪气地叫了声：喵\r', '$P咪声咪气地叫了声：喵\r', '$N叫了声：喵\r', '$P叫了声：喵\r', '$P像只小猫般地依偎在$n的怀里撒娇。\r', '$N像只小猫般地依偎在$p的怀里撒娇。     　\r　\r    (\"`-\'\'-/\").___..--\'\'\"`-._\r     `6_ 6  )   `-.  (  *  ).`-.__.`)\r     (_Y_.)\'  ._   )  `._ `. ``-..-\'\r   _..`--\'_..-_/  /--\'_.\' ,\'\r  (il).-\'\'  (li).\'  ((!.-\'    喵呜．．．\r　\r\r', '$N像只小猫般地依偎在$n的怀里撒娇。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (198, 'shrug', '', 'snowcat', '$N无奈地耸耸肩。\r', '$P无奈地耸耸肩。\r', '$N无奈地耸耸肩。\r', '$P无奈地耸耸肩。\r', '$P很无奈地对$n耸耸肩。\r', '$N很无奈地对$p耸耸肩。\r', '$N看着$n，很无奈地耸耸肩。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (199, 'praise', '', 'pickle', '$N嘿嘿一笑：想跟我斗？再去修个三五百年吧。\r', '$P嘿嘿一笑：想跟我斗？再去修个三五百年吧。\r', '$N一拱手：果然是道行不浅，法力高强！佩服，佩服！\r', '$P一拱手：果然是道行不浅，法力高强！佩服，佩服！\r', '$P对$n一拱手道：$R果然是道行不浅，法力高强！$S五体投地。\r', '$N对$p一拱手道：$R果然是道行不浅，法力高强！$S佩服得五体投地。\r', '$N对$n一拱手道：$R果然是道行不浅，法力高强！$S佩服得五体投地。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (200, 'visit', '', 'bula', '$N粗声粗气地喊道：嘿，哥们儿姐们儿老少爷们儿！哪位手头宽裕的赏$S俩钱儿！\r', '$P需要帮助，又不好意思开口，急出一头大汗。\r', '$N双手抱拳团团一转：各位，有道是：在家靠父母，出门靠朋友。$S初到宝地，人生地不熟，还请各位关照则个！\r', '$P抱拳道：$S新来贵地，囊中羞涩。哪位有钱的随便赏俩，没钱的指点一二，就是$S天大的造化了。\r', '$P不耐烦地对$n吼道：这年头是人人顾自己，谁有空帮你呀？\r', '$N客客气气地对你说道：我是这里的地头蛇了，你有什么问题尽管问我好了！\r', '$N对$n作了一揖道：$S在这里颇有些年月了，$R需要点什么不妨来问我。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (201, 'hate', '', 'snowcat', '$N恨恨地说：都给我走着瞧！\r', '$P恨恨地说：都给我走着瞧！\r', '$N目露凶光，恶狠狠地盯着周围的人。\r', '$P一阵恶意涌上心头，看着谁都不顺眼。\r', '$P对$n阴阴地笑着：阎王叫你三更死，$S不敢留你过五更。\r', '$N对著$p恶狠狠地喊道：阎王叫你三更死，$c不敢留你过五更。去吧，去吧，眼睛一闭，万事皆空。\r', '$N对$n阴阴地笑着：人各有命，岂能强求！阎王叫你三更死，不敢留你过五更。$S也是无可奈何，你认命吧！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (202, 'joythank', '', 'sgzl', '$N连忙回礼道：四海之内，皆兄弟也！$S也不过是举手之劳嘛。\r', '你连忙说道：区区小事，举手之劳，何足挂齿！\r', '$N抱拳团团一转，道：众位今天给我的帮助，我是不能一一补报了，只好转世投胎，等来生为众位做牛做马了。\r', '你觉得这个泥潭中大家对你的帮助太大了，不知如何回报才好。\r', '你对$n点头哈腰地道谢：$R雪中送炭，$S刻骨难忘！\r', '$N对你点头哈腰地道谢：$R雪中送炭，$S刻骨难忘！\r', '$N对$n抱拳道：$R对$S的帮助胜过雪里送炭，$S今生是无法报答了。只好来世投胎，为您做牛做马，以报您恩情之万一。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (203, 'sorry', '', 'bula', '$N双手一张，委屈地说：“我什么也没干呀。”\r', '$P双手一张，委屈地说：“我什么也没干呀。”\r', '$N很不好意思地向大家行礼致歉。\r', '$P很不好意思地向大家行礼致歉。\r', '$P很不好意思地向$n行礼致歉。\r', '$N很不好意思地向$p行礼致歉。\r', '$N很不好意思地向$n行礼致歉。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (204, 'forgive', '', 'sgzl', '$N仰天长叹：“天作孽，尚可恕，自作孽，不可活！”\r', '$P仰天长叹：“天作孽，尚可恕，自作孽，不可活！”\r', '$N一把鼻涕一把泪的哭道：“各位英雄好汉，看在我八十老母和未满月的孩子的份上，就饶我这一次吧！”\r', '$P一把鼻涕一把泪的哭道：“各位英雄好汉，看在我八十老母和未满月的孩子的份上，就饶我这一次吧！”\r', '$P对着$n一把鼻涕一把泪的哭道：“这位$R，我上有八十老母，下有未满月的孩子，您就饶了我这$c这一次吧！”\r', '$N对着$p一把鼻涕一把泪的哭道：“这位$R，我上有八十老母，下有未满月的孩子，您就饶了我这$c这一次吧！”\r', '$N对着$n一把鼻涕一把泪的哭道：“这位$R，我上有八十老母，下有未满月的孩子，您就饶了我这$c这一次吧！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (205, 'push', '', 'xlb', '$N哼哼叽叽地说，我比猪还慢，要么大伙拱我算了。\r', '你哼哼叽叽地说，我比猪还慢，要么大伙拱我算了。\r', '$N不耐烦地哼叽，那是谁，怎么比猪还慢啊？要么大伙拱你算了。\r', '你不耐烦地哼叽，那是谁，怎么比猪还慢啊？要么大伙拱你算了。\r', '你不耐烦地对$n哼叽，你怎么比猪还慢啊？要么大伙拱你算了。\r', '$N不耐烦地对你哼叽，你怎么比猪还慢啊？要么大伙拱你算了。\r', '$N不耐烦地对$n哼叽，你怎么比猪还慢啊？要么大伙拱你算了。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (206, 'lag2', '', 'bula', '$N惊叫道：啊！我的机器刚又显示东西了，就来了十多个屏幕！谁这么多废话呀！\r', '$P束手无策地围着计算机乱转，真恨不得一脚踢过去。\r', '$N气急败坏，破口大骂：“慢死$s啦！！！你这台死计算机！$s花了这么多钱买你，难道就是等着被你气死吗？！？”\r', '$P快要慢死了。气得不住骂自己的计算机。\r', '$P向$n道歉，希望$p能原谅$P因机器慢而没有及时回答$p。\r', '$N向$p道歉，希望$p能原谅$P因机器慢而没有及时回答$P。\r', '$N对$n道：抱歉抱歉，不是我不理你，实在是我的速度太慢了。:(\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (207, 'dream', '', 'cglaem', '$N梦见自己嫁给了。。。\r', '$P梦见自己嫁给了．．．忘了谁了。\r', '$N又开始想入非非了。。。\r', '$P又开始想入非非了。。。\r', '$P开始梦想什么时候能够嫁给$n．．．，好幸福耶!\r', '$N开始梦想什么时候能够嫁给$p．．．，兴奋得满脸通红。\r', '$N开始梦想什么时候能够嫁给$n．．．，兴奋得满脸通红。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (208, 'rose', '', 'crab', NULL, NULL, '$N拎着一把带刺的玫瑰，不怀好意地到处寻找目标。\r', '你捧起一把玫瑰，“送给谁好呢？”\r', '你拎起一把玫瑰，劈头盖脑地朝$n摔了过去。\r', '$N拎起一把玫瑰，劈头盖脑地朝你摔了过来。\r', '$N拎起一把玫瑰，劈头盖脑地朝$n摔了过去。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (209, 'grin', '', 'snowcat', '$N神情古怪地露出个邪恶的笑容，该不会是想做什么坏事吧。\r', '$P突然觉得自己开始像个坏蛋了，忍不住露出邪恶的笑容。\r', '$N脸上露出邪恶的笑容，不知道哪里想歪了。\r', '$P脸上露出邪恶的笑容。\r', '$P邪恶地对着$n笑着，大家瞎子吃馄饨—心里有数。\r', '$N邪恶地对着$p笑着，大家瞎子吃馄饨—心里有数。\r', '$N和$n正邪恶地笑着，八成同时想到什么坏事头上。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (210, 'hoho', '', 'snowcat', '$N憨憨地咧着两片厚嘴唇「呵呵」了几声，露出满嘴的豁口板牙。\r', '$P憨憨地咧着两片厚嘴唇「呵呵」了几声，露出满嘴的豁口板牙。\r', '$N憨憨地咧着两片厚嘴唇「呵呵」了几声。\r', '$P憨憨地咧着两片厚嘴唇「呵呵」了几声。\r', '$P对着$n露出满嘴的豁口板牙，憨憨地咧着两片厚嘴唇「呵呵」了几声。\r', '$N对着$p露出满嘴的豁口板牙，憨憨地咧着两片厚嘴唇「呵呵」了几声。\r', '$N对着$n露出满嘴的豁口板牙，憨憨地咧着两片厚嘴唇「呵呵」了几声。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (211, 'enjoy', '', 'joy', '$N兴高采烈地不断对自己说：“他人怎知其中奥妙？”\r', '$P兴高采烈地不断对自己说：“他人怎知其中奥妙？”\r', '$N挥舞双臂欢呼：“太棒了！”\r', '$P挥舞双臂欢呼：“太棒了！”\r', '$P目不转睛地盯着$n，过了一会眨了眨眼道：“天上掉下的$R？”\r', '$N目不转睛地盯着你，过了一会眨了眨眼道：“哪掉下来一个$R？”\r', '$N目不转睛地盯着$n，过了一会眨了眨眼道：“哪掉下来一个$R？”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (212, 'bye', '', 'weiqi', '$N起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$P起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$N起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$P起个云头，将身一纵跳在半空，一拱手道：$s这就去也！\r', '$P望空作了个揖，对$n嘱咐道：此去西天路遥，$R一路保重！\r', '$N对$p作了个揖道：此去西天路遥，$R一路保重！\r', '$N望空作了个揖，对$n嘱咐道：此去西天路遥，$R一路保重！\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (213, 'whylook', '', 'snowcat', '$N气冲冲地嚷道：你说，你说，为什么盯着我看？\r', '$P气冲冲地嚷道：你说，你说，为什么盯着我的脚看？ \r', '$N羞红了脸啐道：你知道什么叫好看？ \r', '$P哼了一声道：你这种又蠢又笨的人也知道什么叫好看？ \r', '$P对$n低声嘀咕道：小人该死，小人见$R一双脚生得好看。。。 \r', '$N对$p低声嘀咕道：小人该死，小人见$R一双脚生得好看。。。 \r', '$N对$n嘀咕道：小人该死，小人见$R生得好看。。。 \r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (214, 'bigman', '', 'dream', '$N负手而立，凝望远山。只觉得天下英雄舍我其谁。\r', '$P负手而立，凝望远山。只觉得天下英雄舍我其谁。\r', '$N纵声长吟道：江山如此多娇，引无数英雄竞折腰。\r', '$P纵声长吟道：江山如此多娇，引无数英雄竞折腰。\r', '$P对$n一拱手道：原来$R竟是志在天下。$S五体投地。\r', '$N对$p一拱手道：原来$R竟是志在天下。$S五体投地。\r', '$N对$n一拱手道：原来$R竟是志在天下。$S五体投地。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (215, 'seduce', '', 'cglaem', '$N似乎有些想入非非了。 \r', '$P似乎有些想入非非了。 \r', '$N俏脸生春，妙目含情，只看得大家心慌意乱。 \r', '$P想诱惑谁？ \r', '$P俏脸生春，妙目含情，盯着$n看个不停。 \r', '$N俏脸生春，妙目含情，正盯着$p看个不停。 \r', '$N俏脸生春，妙目含情，正盯着$n看个不停。 \r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (216, 'end', '', 'mon', '$N扯着嘶哑的喉咙，放声悲歌：“西边的太阳就要落山了，我$N的末日就要来到！”：（\r', '$P扯着嘶哑的喉咙，放声悲歌：“西边的太阳就要落山了，我$N的末日就要来到！”：（\r', '$N扯着嘶哑的喉咙，放声高唱：“西边的太阳就要落山了，鬼子的末日就要来到！”\r', '$P扯着嘶哑的喉咙，放声高唱：“西边的太阳就要落山了，鬼子的末日就要来到！”\r', '$P扯着嘶哑的喉咙，高唱凯歌：“西边的太阳就要落山了，$n的末日就要来到！”\r', '$N扯着嘶哑的喉咙，放声高唱凯歌：“西边的太阳就要落山了，$n的末日就要来到！”\r', '$N扯着嘶哑的喉咙，放声高唱凯歌：“西边的太阳就要落山了，$n的末日就要来到！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (217, 'caidao', '', 'xlb', '$N挥舞着手中的菜刀，嘴里叫着：“不想活了，$s不活了！！！”\r', '你挥舞着手中的菜刀，嘴里叫着：“不想活了，$s不活了！！！”\r', '$N抽出一把血淋淋的菜刀握在手中，口中嘟囔着：“砍！砍！我砍砍砍！”\r', '你抽出一把血淋淋的菜刀握在手中，口中嘟囔着：“砍！砍！我砍砍砍！”\r', '你挥舞着手里的菜刀，在$n家门口高声叫骂：“$r，你有种给我出来！！！！！”\r', '$N挥舞着手里的菜刀，在你家门口高声叫骂：“$r，你有种给我出来！！！！！”\r', '$N挥舞着手里的菜刀，在$n家门口高声叫骂：“$r，你有种给我出来！！！！！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (218, 'puke', '倒胃', 'bula', '$N突然觉得胃一阵抽筋，哇啦哇啦地吐了满地。\r', '$P突然觉得胃一阵抽筋，哇啦哇啦地吐了满地。\r', '$N脸上忽然一阵青一阵白，唏哩哗啦地吐了满地。\r', '$P突然觉得胃一阵抽筋，哇啦哇啦地吐了满地。\r', '$P觉得一阵恶心，哇啦哇啦地吐了$n满身。\r', '$p看到$N脸色有点不对劲，突然哗啦哗啦地吐了$p满身。\r', '$N突然脸上一阵青一阵白，唏哩哗啦地吐了$n满身。\r', 1, 0, '2026-05-23 04:06:40');
INSERT INTO `emotes` VALUES (219, 'papaya', '', 'snowcat', '$N狠狠地捶了自己一下：我怎么就不开窍呢？\r', '$P狠狠地捶了自己一下：我怎么就不开窍呢？\r', '$N觉得自己简直是笨到家了。\r', '$P觉得自己真笨。\r', '$P对$n说道：你，你，你怎么就不开窍呢？\r', '$N对$p说道：你，你，你怎么就不开窍呢？\r', '$N对$n说道：你，你，你怎么就不开窍呢？\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (220, 'xixi', '', 'mon', '$N「嘻嘻嘻」地笑起来，大概想到了什么好事。\r', '$P「嘻嘻嘻」地笑起来，大概想到了什么好事。\r', '$N「嘻嘻嘻」地笑出了声。\r', '$P「嘻嘻嘻」地笑出了声。\r', '$P冲着$n「嘻嘻嘻」地笑了几声。\r', '$N冲着$p「嘻嘻嘻」地笑了几声。\r', '$N冲着$n「嘻嘻嘻」地笑了几声。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (221, 'kick', '飞踢', 'bula', '$N狠狠踢了自己一脚。\r', '$P狠狠踢了自己一脚。\r', '$N飞起一脚，似乎在踢苍蝇。\r', '$P对着空气踢了一脚。\r', '$P对着$n一脚踢了过去。\r', '$N飞起一脚，正好踢中$p的屁股！\r', '$N飞起一脚，正好踢中$n的屁股！\r', 1, 0, '2026-05-23 04:07:11');
INSERT INTO `emotes` VALUES (222, 'nolook', '', 'cold', '$N的脸上泛起了红晕，双手捂住眼睛不住地娇笑道：“人家羞死了嘛，羞，羞，羞！你还要看？！不许看．．．．．．”\r', '$P的脸上泛起了红晕，双手捂住眼睛不住地娇笑道：“人家羞死了嘛，羞，羞，羞！你还要看？！不许看．．．．．．”\r', '$N羞得满脸通红，双手捂住眼睛，笑嗔道：“不许看，不许看．．．．．．”\r', '$P羞得满脸通红，双手捂住眼睛，笑嗔道：“不许看，不许看．．．．．．”\r', '$P抬手挡住脸，从指缝间偷窥着$n，假装一本正经地道：“说不看就不看！”\r', '$N抬手挡住脸，从指缝间偷窥着你，假装一本正经地道：“说不看就不看！”\r', '$N抬手挡住脸，从指缝间偷窥着$n，假装一本正经地道：“说不看就不看！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (223, 'bite', '', 'pickle', '$N狠狠地咬了咬自己的指头。\r', '$P狠狠地咬了咬自己的指头。\r', '$N磨了磨牙。\r', '$P磨了磨牙。\r', '$P真想狠狠地咬$n一口。\r', '$N真想狠狠地咬$p一口。\r', '$N想狠狠地咬$n一口。\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (224, 'mud', '', 'cold', '$N狂喜地拼命往自己身上抹泥巴，左一下，右一把，忽然腿一蹬手一伸，淹没顶了。\r', '$P发疯地往自己身上抹泥巴，自我感觉良好！嘿，你没救了！\r', '$N猛然大声惊叫：“好大一个泥潭！”，欣喜若狂连蹦带跑地往里跳．．．．\r', '$P猛然发现好大一个泥潭，欣喜若狂！\r', '$P假慈悲地拼命帮$n往身上抹泥巴，奸笑着：“快淹没了！”\r', '$N很殷勤地拼命帮你往身上抹泥巴，左一下，右一把，呵呵地笑：“感觉不错吧！”\r', '$N很殷勤地拼命帮$n往身上抹泥巴，左一下，右一把，呵呵地假笑：“$n，感觉不错吧！”\r', 1, 0, '2026-05-16 08:19:09');
INSERT INTO `emotes` VALUES (225, 'rich', '', 'pickle', '$N捏着一把钱叹道：“唉，想花都花不出去，还一天到晚涨利息。这不是叫人把钱砸手里吗？”\r', '$P捏着钱，沾沾自喜地想：这些置房子，这些娶老婆。。。\r', '$N捏着一把钱，激动地说道：“我王老五从来没见过这么多的钱哪！今天晚上我请全村人到我家吃肉！”\r', '$P这一生中，从没见过这么多的钱，捏着钱的手激动的颤抖起来。\r', '$P觉得$n的腰包沉甸甸的，大概能揩出点油来吧。\r', '$N不怀好意地盯着$p的腰包，拿出了一本餐馆指南。大事不妙，快溜吧！\r', '$N拍着$n的肩膀说道：哥们儿，出去搓一顿！你出钱，我请客！\r', 1, 0, '2026-05-16 08:19:09');
