INSERT INTO `fixed_objects` VALUES (604, 'sea/obj/longzhu1', 'sea/obj/longzhu1', 'longzhu1', '一颗斗大圆润的珍珠，传说只有得道的真龙才会有。\n内有光影游动，似乎触摸(touch)之下会发出异彩。\n这颗龙珠似乎上有八宫之相，也许能合并(combine)其它的龙珠。\n', 'normal', 0);
