INSERT INTO `fixed_objects` VALUES (1056, '', 'obj/book/makeupbook', 'makeupbook', '一把香气扑鼻的檀香扇，扇面上密密麻麻写满了一笔娟秀的蝇头小楷。', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1057, '', 'obj/book/mihou-book', 'mihou-book', '薄薄的一本小册子，封面上歪歪斜斜地地写着“猕猴手记”。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1058, '', 'obj/book/misc', 'misc', '一本破旧不堪的小册子。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1059, '', 'obj/book/nowords', 'nowords', '一本脏兮兮的小册子。上面划着一些象是蚯蚓爬出来的图案。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1060, '', 'obj/book/parrybook2', 'parrybook2', '少林僧人在唐初战争中立下了不少战功，也有不少阵亡。\n战乱中，不少少林的武功密笈也因此流失在外。这本拆招\n秘诀听说是尉迟恭所救的一位少林高僧赠给他的。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1061, '', 'obj/book/parry_book', 'parry_book', '一个小册子，划了些小人比武的招式．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1062, '', 'obj/book/poem', 'poem', '这本书大概有两三百页，蓝底白字的封面上龙飞凤舞地写着“太白自选集”。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1063, '', 'obj/book/qian', 'qian', '一本薄薄的小册子．\n天地玄黄，宇宙洪荒．日月盈昃，星辰列张．\n．．．．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1064, '', 'obj/book/quanjing', 'quanjing', '一本薄薄的的小册子，画了些手法。\n旁注小字：范青平惠存\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1065, '', 'obj/book/sample_basic', 'sample_basic', '这是一本基本剑法的图解，书角已经有些残破了。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1066, '', 'obj/book/sample_high', 'sample_high', '少林僧人在唐初战争中立下了不少战功，也有不少阵亡。\n战乱中，不少少林的武功密笈也因此流失在外。这本拆招\n秘诀听说是尉迟恭所救的一位少林高僧赠给他的。\n', 'normal', 0);
