INSERT INTO `fixed_objects` VALUES (1504, '', 'obj/weapon/sword/xijian', 'xijian', '这是一把又细又长的剑，轻飘飘的像是女孩子家的玩意。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1505, '', 'obj/weapon/sword/yudi', 'yudi', '一根碧玉制就的笛子，绿莹莹地甚是精致。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1506, '', 'obj/weapon/sword/zhujian', 'zhujian', '这是一柄三尺来长，精工制成的青竹剑，虽不致命，却可伤人。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1507, '', 'obj/weapon/sword/zijinxiao', 'zijinxiao', '韩湘子的紫金箫，听说是用南海紫竹林里的一株神竹做的。。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1508, '', 'obj/weapon/throwing/dart', 'dart', '飞镖是一种十分常见的暗器，而毒镖却只有一个人有．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1509, '', 'obj/weapon/throwing/dujili', 'dujili', '铁打的蒺黎锋利无比，刃上闪现绿色，显是喂了毒药。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1510, '', 'obj/weapon/throwing/kongqueling', 'kongqueling', '几支孔雀身上的羽毛，在阳光的照射下闪着奇异的色彩。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1511, '', 'obj/weapon/throwing/kouzi', 'kouzi', '一枚小铜扣', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1512, '', 'obj/weapon/throwing/shi', 'shi', '一块大石头。', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1513, '', 'obj/weapon/throwing/smallshi', 'smallshi', '一块小石头。', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1514, '', 'obj/weapon/throwing/stone', 'stone', '飞璜石是一种十分常见的暗器。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1515, '', 'obj/weapon/throwing/xiuzhen', 'xiuzhen', '一把细小的绣花针，闪着点点寒芒。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1516, '', 'obj/weapon/throwing/yinzhen', 'yinzhen', '一把细小的绣花针，闪着点点寒芒。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1517, '', 'obj/weapon/whip/fuchen', 'fuchen', '这是一柄拂尘，做工精细，本来只是抹灰驱蝇的工具\n后来成立道士手里的道具，就渐渐失去原来的作用了。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1518, '', 'obj/weapon/whip/jueqingwhip', 'jueqingwhip', '一条蓝色的长带，细看由无数细如毛发的长丝聚成，虽轻若无物，却无孔不入。\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1519, '', 'obj/weapon/whip/longsuo', 'longsuo', '一条长约六尺，青红龙筋缠成的长鞭，乃是地藏王菩萨的兵器，不畏刀枪之利，水火不侵．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1520, '', 'obj/weapon/whip/pibian', 'pibian', '一条长长的皮鞭，上面沾满了血．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1521, '', 'obj/weapon/whip/tielian', 'tielian', '一条长长的铁链，上面沾满了血．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1522, '', 'obj/weapon/whip/whip', 'whip', '一条长长的皮鞭，上面沾满了血．\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1523, '', 'obj/weapon/whip/wuchou', 'wuchou', '一条长长的彩绸，是用于舞蹈的道具\n', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1535, 'dntg/hgs/zhaiyuan', 'dntg/hgs/obj/daguo', '大锅', '一口大铁锅，里面煮着热气腾腾的斋饭。', 'container', 1);
INSERT INTO `fixed_objects` VALUES (1536, 'dntg/hgs/zhaiyuan', 'dntg/hgs/obj/chahu', '茶壶', '几个普通的茶壶，里面装着清茶。', 'container', 2);
INSERT INTO `fixed_objects` VALUES (1537, 'dntg/hgs/zhaiyuan', 'dntg/hgs/obj/muzhuo', '木桌', '几张简朴的木桌，上面摆了些碗筷。', 'furniture', 3);
INSERT INTO `fixed_objects` VALUES (1538, 'dntg/hgs/center', 'dntg/hgs/obj/qigan', '旗杆(qigan)', '一根紫桐木做的旗杆，高有数丈。', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1539, 'nanhai/tingjing', 'nanhai/obj/tingjing-shitou', '石头', '这块石头状似两只并卧的海龟，静静地趴在海滩上。据说东海龙王敖广曾派二海龟去偷听观音念经，并要它们记下经文，好用来给水族讲解。不料，二龟光顾听经，全神贯注下竟错过了返回大海的时间，遂变为石头。', 'normal', 0);
INSERT INTO `fixed_objects` VALUES (1540, 'dntg/hgs/tiebanqiao', 'shi jie', '石碣', '桥下有一块石碣，上面刻着花果山福地水帘洞洞天。', 'fixed', 1);
INSERT INTO `fixed_objects` VALUES (1542, 'dntg/hgs/cave', 'shi jie', '石碣', '洞口有一块石碣，上面刻着花果山福地水帘洞洞天。', 'fixed', 1);
