INSERT INTO `items` VALUES (10484, 'letter-wudidong', '密函', 'misc', '致君访道之士：    君得吾之密函，乃与本门有缘。望君能持此骷髅，替吾寻出本门细作，报之于吾。此贼偷吾刀法秘笈一本，乃本洞镇洞至宝。吾得此细作，自将其碎尸万段，食其心，饮其髓，方解吾心头之恨。事成之日，君将秘笈为信物还吾，吾必收汝为徒，为洞中二代弟子。那时传汝长生不老之无上心法，以振吾无底洞雄风！千万千万。\\t \\t \\t \\t陷空山无底洞开山祖师玉鼠仙子。		   ', 'qujing', '封', 20, 0, 1, NULL, NULL, NULL, NULL, 'normal', NULL, 0, 0, 0, 0, 0, 1, 0, 0, NULL, NULL, 0, 0, 0, 0, 0, 0, 0, NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'none', 50, 100, 1, NULL, NULL, 0, 0, 0, 10, 0);
