INSERT INTO `items` VALUES (11711, 'bailongma_token', '白龙马令牌', 'mount_token', '一枚晶莹剔透的龙形令牌，使用后可以召唤白龙马成为你的专属坐骑。白龙马乃是西海玉龙三太子所化，脚力非凡，还能增加闪避。', 'obj', '枚', 10, 50000, 1, 0, 0, NULL, '', 'rare', NULL, 0, 0, 0, 0, 0, 1, 0, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 10, 0, 0, 0, 0, 0, 0, 0, 0, 0, 'none', 50, 100, 1, NULL, NULL, 0, 0, 0, 10, 0);
