INSERT INTO `message_queue` VALUES (47590, 19, '【闪避】 你早有防备，轻轻一侧身，辟尘大王便扑了个空。 辟尘大王灵巧地闪开了你的还击！', 'combat', 1, NULL, '2026-08-16 09:00:50', NULL);
INSERT INTO `message_queue` VALUES (47591, 19, '辟尘大王目光紧锁你的动作，全神戒备。 你心头一凛，紧守门户，不敢贸然出击。', 'combat', 1, NULL, '2026-08-16 09:00:55', NULL);
INSERT INTO `message_queue` VALUES (47592, 19, '<span style=\"color:#FF00FF;font-weight:bold\">\n辟尘大王倒在地上，现出原形为一头犀牛！</span>\n<span style=\"color:#FFFF00;font-weight:bold\">那犀牛精化作一阵风，一溜烟逃走了！</span>', 'combat', 1, NULL, '2026-08-16 09:00:58', NULL);
INSERT INTO `message_queue` VALUES (47593, 19, '<span style=\"color:#00FF00;font-weight:bold\">府令出现在你面前，向你拱手道：</span>\n<span style=\"color:#FFFF00;font-weight:bold\">\"多谢测试员aaa除灭犀牛精，解了金平府灯会之难！\n青龙山三大王已除，百姓从此安居乐业！\"</span>', 'self_event', 1, NULL, '2026-08-16 09:00:58', NULL);
INSERT INTO `message_queue` VALUES (47594, 19, '<span style=\"color:#00FF00;font-weight:bold\">【金平府】<span style=\"color:#FFFF00;font-weight:bold\">测试员aaa降服犀牛精，顺利闯过西行又一关！</span>', 'system', 1, NULL, '2026-08-16 09:00:58', NULL);
INSERT INTO `message_queue` VALUES (47595, 19, '测试员aaa浅浅一笑，一招「自在飞花轻似梦」若有若无地拍向辟尘大王的要害\n\n你浅浅一笑，一招「自在飞花轻似梦」若有若无地拍向辟尘大王的腹部。结果只听见「砰」地一声巨响，辟尘大王像一捆稻草般飞了出去。 你击败了 辟尘大王！ 获得 240点道行！\n\n你的道行：新入道途\n\n 获得 480 点实战经验！\n\n你的实战经验：马马虎虎\n\n消耗内力 1 点，法力 1 点。', 'self_event', 1, NULL, '2026-08-16 09:00:58', NULL);
INSERT INTO `message_queue` VALUES (47596, 19, '<span style=\"color:#FFFF00;font-weight:bold\">测试员aaa手一指，召来一朵云彩，高高兴兴地坐了上去，</span>\n<span style=\"color:#FFFF00;font-weight:bold\">再吹一声口哨，随之往上冉冉地升起。。。</span>', 'self_event', 1, NULL, '2026-08-16 09:01:33', NULL);
INSERT INTO `message_queue` VALUES (47597, 19, '<span style=\"color:#00FFFF;font-weight:bold\">白云轻散，测试员aaa如仙子般轻盈落下。\n只见白云轻散，测试员aaa如仙子般轻盈落下，衣袂飘飘。</span>', 'self_event', 1, NULL, '2026-08-16 09:01:33', NULL);
INSERT INTO `message_queue` VALUES (47598, 19, '玄奘说道：说到朱紫国，国王因射伤孔雀而相思成疾，需赛太岁金毛犼的破解。\n施主若能助我通过此关，必有重谢。', 'self_event', 1, NULL, '2026-08-16 09:01:53', NULL);
INSERT INTO `message_queue` VALUES (47599, 19, '<span style=\"color:#00FF00;font-weight:bold\">玄奘</span>：<span style=\"color:#00FFFF\">唐僧喃喃自语：不知何时才能得证大道。</span>', 'npc_chat', 1, NULL, '2026-08-16 09:02:07', NULL);
INSERT INTO `message_queue` VALUES (47600, 19, '现在是西游时间：夏天，黄昏，卯时（15时3分）', 'room', 0, 0, '2026-08-16 09:03:03', NULL);
INSERT INTO `message_queue` VALUES (47601, 19, '现在是西游时间：夏天，黄昏，卯时（15时4分）', 'room', 0, 0, '2026-08-16 09:03:04', NULL);
INSERT INTO `message_queue` VALUES (47602, 19, '你向张果老打听有关『general』的消息。\n<span style=\"color:#00FFFF;font-weight:bold\">张果老耸了耸肩，很抱歉地说：无可奉告。</span>', 'npc_dialog', 1, NULL, '2026-08-16 09:03:09', NULL);
INSERT INTO `message_queue` VALUES (47603, 19, '<span style=\"color:#FFFF00;font-weight:bold\">测试员aaa手一指，召来一朵云彩，高高兴兴地坐了上去，</span>\n<span style=\"color:#FFFF00;font-weight:bold\">再吹一声口哨，随之往上冉冉地升起。。。</span>', 'self_event', 1, NULL, '2026-08-16 09:03:14', NULL);
INSERT INTO `message_queue` VALUES (47604, 19, '<span style=\"color:#00FFFF;font-weight:bold\">白云轻散，测试员aaa如仙子般轻盈落下。\n只见白云轻散，测试员aaa如仙子般轻盈落下，衣袂飘飘。</span>', 'self_event', 1, NULL, '2026-08-16 09:03:14', NULL);
INSERT INTO `message_queue` VALUES (47605, 19, '小公主想了一会儿，说道：对不起，你问的事我实在没有印象。', 'self_event', 1, NULL, '2026-08-16 10:21:35', NULL);
INSERT INTO `message_queue` VALUES (47606, 19, '小公主想了一会儿，说道：对不起，你问的事我实在没有印象。', 'self_event', 1, NULL, '2026-08-16 10:21:37', NULL);
INSERT INTO `message_queue` VALUES (47607, 19, '小公主说：是个国宝，我有但不轻易给人，也有人在后宫找到过。', 'self_event', 1, NULL, '2026-08-16 10:21:39', NULL);
INSERT INTO `message_queue` VALUES (47608, 19, '小公主说：唉，也只有她偶尔能说得动我。', 'self_event', 1, NULL, '2026-08-16 10:21:43', NULL);
INSERT INTO `message_queue` VALUES (47609, 19, '小公主说：没有听说公主我一直想寻个王子结婚吗？', 'self_event', 1, NULL, '2026-08-16 10:21:45', NULL);
