INSERT INTO `npcs` VALUES (1, 'demogorgon', '鬼面魔', '', '一个身不足五尺，瘦瘦干干，满身黄毛的猢狲。', 0, NULL, NULL, NULL, NULL, NULL, '[\"demogorgon四下打量了一番。\",\"demogorgon沉思片刻，若有所悟。\",\"demogorgon叹道：天道苍茫，修行无尽啊。\",\"demogorgon喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '野兽', 'xian', '', 'male', 43, 'peaceful', 5000, 100, 5000, 100, 5000, 100, 100, 10, 10, 10, 100, 100, 10, 5000000, 5000000, 0, 0, 0, 5000, 5000, 100, 9999, 9999, 5000, 5000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 7, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (3, 'dragonn', '五爪金龙', NULL, '一只满身金甲的五爪金龙。', 0, NULL, NULL, NULL, NULL, NULL, '[\"dragonn四下打量了一番。\",\"dragonn沉思片刻，若有所悟。\"]', NULL, NULL, '野兽', NULL, NULL, 'male', 100, 'peaceful', 100, 100, 2000, 2000, 2000, 2000, 40, 10, 40, 10, 10, 10, 10, 1400000, 1000000, 0, 500, 0, 1500, 1000, 50, 100, 100, 1500, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/dragon', 'qujing/dragon', NULL, 5, 0, NULL, 0, 1, '2026-08-07 22:30:07', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (4, 'garrison', '县城官兵', '', '这是个正在执行公务的县城官兵，虽然和许多武林人物比起来，官兵', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', 'warrior', '', 'male', 30, 'heroism', 100, 100, 100, 100, 100, 100, 27, 10, 10, 10, 26, 25, 10, 100000, 100, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 20, 1, NULL, NULL, 0, 0, 0, NULL);
