INSERT INTO `npcs` VALUES (8, 'hell_guard', '酆都鬼使', '', '这是一位来自阴界的守护神，专门担任护法之责。', 0, NULL, NULL, NULL, NULL, NULL, '[\"hell_guard握紧了手中的兵器。\",\"hell_guard警惕地环顾四周。\"]', NULL, NULL, '人类', 'warrior', '', 'male', 50, 'heroism', 1000, 100, 1000, 100, 1000, 100, 40, 10, 10, 10, 100, 100, 10, 100000, 100000, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 8, 17, '[\"hell_guard吼道：看招！\",\"hell_guard大喝：纳命来！\"]', 20, 1, NULL, NULL, 0, 0, 0, NULL);
