INSERT INTO `npcs` VALUES (11, 'mind_beast', '观想兽', '', '这是一只由修道人的杂念绮思所化的观想兽，会缠住人的魂魄。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', '', '', 'male', 12, 'peaceful', 600, 100, 600, 100, 900, 100, 48, 10, 10, 10, 52, 22, 10, 100, 100, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (12, 'mind_bug', '观想□', '', '这是一只由修道人的杂念绮思所化的观想□，会缠住人的魂魄。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', '', '', 'male', 50, 'peaceful', 250, 100, 140, 100, 600, 100, 24, 10, 10, 10, 26, 100, 10, 100, 100, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (13, 'qinbing', '亲兵', '建王府', '一个彪形大汉，看身上衣服大概是建府的亲兵，乃是高祖第三子李元吉的近身护卫。他除了保护李元吉外似乎还管发散钱财吃喝。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"问什么问？长着眼睛不会看哪？\",\"here\":\"这儿就是醉星楼！造的可比对面那破房子强得多啦！\",\"rumors\":\" 听说有人想来拆房子，哼！\",\"食物\":\"如果是良民，可以领些包子去。\",\"钱财\":\"如果是良民，可以领些银子去。\",\"拆房子\":\"哼，除非把老子打发了，否则谁也别想来这儿撒野！\"}', '[\"鬼兵握紧了手中的兵器。\",\"鬼兵警惕地环顾四周。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 25, 'friendly', 100, 100, 300, 300, 200, 200, 10, 10, 10, 10, 10, 10, 10, 80000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'jjf', 'jjf/zuixing', 'jjf/zuixing', NULL, 0, 0, '[\"鬼兵吼道：看招！\",\"鬼兵大喝：纳命来！\"]', 20, 1, '2026-06-16 06:11:58', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (14, 'skeleton', '骷髅兵', '', '一具被人用咒语控制着的骷髅。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"名字？什么名字？我早就不记得了。\",\"here\":\"这里？这里是个破洞。要不是那个混帐绿毛老鼠叫我看着，我早出去吃人肉，享清福了！\",\"rumors\":\"嘿嘿，我都在这里睡这么多年了，还能知道点什么？\",\"人肉\":\"唉。能吃上点人肉就好了。\"}', '[\"骷髅道：唉，也不知在这里睡了多久了。\",\"骷髅道：都忘了人肉是什么味儿了。\"]', NULL, NULL, '人类', 'youling', '', 'male', 40, 'heroism', 300, 100, 300, 100, 300, 100, 30, 10, 10, 10, 100, 100, 10, 50000, 50000, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 1, 23, '[\"骷髅兵吼道：看招！\",\"骷髅兵大喝：纳命来！\"]', 20, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (15, 'xiaotian-quan', '哮天犬', '', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', 'xian', '', 'male', 30, 'heroism', 100, 100, 1000, 100, 1000, 100, 30, 10, 10, 10, 100, 100, 10, 1500000, 100, 0, 0, 0, 800, 800, 100, 100, 100, 800, 800, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 20, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (16, 'zhenshen', '真身', '', '', 0, NULL, NULL, NULL, NULL, NULL, '[\"真身四下打量了一番。\",\"真身沉思片刻，若有所悟。\"]', NULL, NULL, '人类', '', '', 'male', 65, 'friendly', 100, 100, 100, 100, 100, 100, 30, 10, 10, 10, 100, 100, 10, 1000, 1000, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 8, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (17, 'zombie', '僵尸', '', '这是一具被人用符咒控制的僵尸，从它苍白的脸上看不出任何喜怒哀乐。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', '', '', 'male', 30, 'peaceful', 100, 100, 500, 100, 500, 100, 25, 10, 10, 10, 30, 100, 10, 100, 100, 0, 0, 0, 200, 200, 100, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (26, 'jingwei', '精卫', NULL, '一只可爱的小小鸟，白喙赤足，色彩斑斓，相传是炎帝的小女儿。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"我是炎帝的女儿，叫女娃，在东海游泳时淹死了，就化成现在的样子。\",\"here\":\"这里就是淹死我的东海(sea)，我一定要把它填(fill)平！\",\"填海\":[\"callable\",\"jingwei_fill_sea\"]}', '[\"精卫四下打量了一番。\",\"精卫沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 5, 'friendly', 100, 100, 400, 400, 400, 400, 10, 10, 10, 10, 40, 30, 999, 3000, 3000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'changan', 'changan/eastseashore', 'changan/eastseashore', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:14:38', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (27, 'lusheng', '卢生', NULL, '一个很会做梦的书生。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 25, 'peaceful', 100, 100, 500, 500, 300, 300, 10, 10, 10, 10, 10, 10, 27, 100, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'changan', 'changan/wside3', 'changan/wside3', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (28, 'qianmian', '千面怪', NULL, '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 30, 'heroism', 1000, 1000, 1000, 1000, 1000, 1000, 40, 25, 10, 10, 25, 25, 10, 0, 0, 0, 0, 0, 0, 1000, 0, 100, 100, 0, 0, 5, 0, 0, 0, 1, 0, NULL, 'changan', 'changan/qianmian', 'changan/qianmian', NULL, 3, 3, NULL, 20, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (30, 'shouchen', '袁守诚', '算命先生', '能知天地理，善晓鬼神情．长安城里没有不认识他的。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"小道姓袁名守诚．．．嘿嘿，在这长安一带还算小有薄名。\",\"here\":\"你没来过长安？这地方可是天下第一繁华所在。\",\"人参果\":[\"callable\",\"suan_rsg\"],\"rsg\":[\"callable\",\"suan_rsg\"],\"福缘\":[\"callable\",\"suan_fuyuan\"],\"fuyuan\":[\"callable\",\"suan_fuyuan\"],\"算命\":[\"callable\",\"suanming\"],\"算卦\":[\"callable\",\"suanming\"],\"suanming\":[\"callable\",\"suanming\"]}', '[\"袁守诚晃了晃手上的桂花酒袋笑道：我这人没别的毛病，就是好点这个。\",\"袁守诚上上下下打量了你几眼。\",\"袁守诚皱了皱眉，一副欲言又止的样子。\",\"袁守诚神秘兮兮地四面张望了一下，在你耳边悄声道：客官最近没觉得哪儿不得劲？\"]', NULL, '[{\"action_name\":\"赠送天书\",\"type\":\"accept_object\",\"accepted_items\":[\"guihua-jiudai\"],\"response_message\":\"袁守诚接过桂花酒袋，微微一笑，说道：这位施主跟小道投缘！这里我也有一点小意思，请笑纳。\",\"reward_item\":\"nowords\",\"set_temp\":{\"received_wine\":1}},{\"action_name\":\"算命付费\",\"type\":\"accept_object\",\"accepted_items\":[\"golden_carp\"],\"response_message\":\"袁守诚满面堆欢：多谢施主，在下正需要这个，有什么问题您尽管问！\",\"set_temp\":{\"suanming\\/paid\":1}}]', 'human', 'taoist', NULL, 'male', 55, 'peaceful', 300, 300, 350, 350, 300, 300, 10, 10, 10, 10, 10, 10, 15, 8000, 80000, 0, 0, 0, 0, 0, 0, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/caotang', 'city/caotang', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:35:21', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (32, 'whitexiu', '白衣秀士', '', '一位风流书生．不过他面色看起来怪怪的，好像有满腹心事。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"关你屁事！\",\"here\":\"长着眼睛你不会看啊。\",\"袁守诚\":\"江湖骗子。只有你们这帮傻瓜才信他。\",\"算命先生\":\"江湖骗子。只有你们这帮傻瓜才信他。\"}', NULL, NULL, NULL, '人类', '', '', 'male', 217, 'peaceful', 100, 100, 1000, 100, 100, 100, 100, 10, 10, 10, 100, 100, 10, 5000, 100, 0, 0, 0, 150, 300, 0, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (33, 'aluoben', '阿罗本', '波斯僧人', NULL, 0, NULL, NULL, NULL, NULL, '{\"here\":\"大唐景教寺\\\",\"name\":\"阿罗本\\\"}', '[\"阿罗本四下打量了一番。\",\"阿罗本沉思片刻，若有所悟。\",\"阿罗本叹道：天道苍茫，修行无尽啊。\",\"阿罗本喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 54, 'peaceful', 300, 300, 800, 800, 400, 400, 25, 10, 10, 10, 10, 10, 25, 100000, 200000, 0, 0, 0, 300, 300, 10, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/aluoben', 'city/aluoben', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (34, 'biaotou', '镖头', NULL, '镖局中的镖头，长的膀大腰圆，看起来很有力气的样子。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 29, 'heroism', 100, 100, 500, 500, 100, 100, 30, 10, 30, 10, 10, 10, 10, 35000, 0, 0, 0, 0, 100, 100, 5, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/biaotou', 'city/biaotou', NULL, 0, 0, NULL, 20, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (36, 'bing1', '小兵', NULL, '这些兵士都是秦叔宝，程咬金等从部下中挑出来的精锐。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 22, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 10000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/bing1', 'city/bing1', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (37, 'bookseller', '孔方兄', '书店老板', '孔秀才入京赶考落第，盘缠用尽，无法还乡，不得已在长安开一家书店。传说他曾遇异人，学得一些防身之术。', 0, NULL, NULL, NULL, NULL, NULL, '[\"孔方兄四下打量了一番。\",\"孔方兄沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 37, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 25, 40000, 20000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/bookstore', 'city/bookstore', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:14:38', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (38, 'boss', '老害虫', '喜福会老板娘', NULL, 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下便是这里的老板。\",\"here\":\"这里是喜福会，城中大户人家结婚都要来这里摆喜宴哩。\",\"宴\":[\"callable\",\"ask_party\"],\"喜宴\":[\"callable\",\"ask_party\"],\"席\":[\"callable\",\"ask_party\"],\"酒席\":[\"callable\",\"ask_party\"],\"party\":[\"callable\",\"ask_party\"],\"money\":[\"callable\",\"ask_money\"],\"价钱\":[\"callable\",\"ask_party\"],\"价格\":[\"callable\",\"ask_party\"],\"费用\":[\"callable\",\"ask_party\"]}', '[\"老害虫四下打量了一番。\",\"老害虫沉思片刻，若有所悟。\"]', NULL, '[{\"type\":\"party_start\",\"action_name\":\"开始喜宴\",\"action_cmd\":\"start_party\"},{\"type\":\"party_serve\",\"action_name\":\"上菜\",\"action_cmd\":\"serve\"},{\"type\":\"party_finish\",\"action_name\":\"结束喜宴\",\"action_cmd\":\"finish\"}]', 'human', NULL, NULL, 'female', 32, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 20, 0, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/xifuhui', 'city/xifuhui', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:14:38', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (39, 'bossdachang', '朱老板', '长安巨贾', '朱老板原名猪大肠，当年是长安城两大流氓“左捣乱，右猪肠”之一。有次被捣乱痛扁后卧床不起，百无聊赖之际读史解闷。读到刘邦周处等人的故事时，悚然有悟。从此奋发读书，潜心习武，文不成武不就后，毅然下海从商，终于成就了今天的局面。发迹改名朱大常，身穿绸袍，俨然衣冠中人。', 0, NULL, NULL, NULL, NULL, NULL, '[\"朱老板对着你喝道：本大爷看你实在很不顺眼，去死吧。\",\"朱老板用一种异样的眼神扫视着在场的每一个人。\",\"朱老板说道：母鸡，给我一只蛋。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 44, 'friendly', 100, 100, 800, 800, 200, 200, 10, 10, 10, 10, 10, 10, 18, 50000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 1, 0, 0, 0, 1, 0, NULL, 'city', 'city/jicundian', 'city/jicundian', NULL, 3, 0, NULL, 0, 1, '2026-08-07 22:31:19', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (42, 'dai', '戴文重', '驿站当家', '驿站里的当家，长的圆圆胖胖的。', 0, NULL, NULL, NULL, NULL, '{\"发信\":[\"callable\",\"send_mail\"],\"收信\":[\"callable\",\"receive_mail\"],\"信件\":[\"callable\",\"receive_mail\"],\"信\":[\"callable\",\"receive_mail\"],\"mail\":\"您讲的是外国话吧？我听不懂耶~~~~~~~~\"}', '[\"戴文重四下打量了一番。\",\"戴文重沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 42, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 40000, 20000, 0, 0, 0, 300, 300, 5, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/dai', 'city/dai', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:07:20', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (43, 'daozhang', '五福道长', NULL, NULL, 0, NULL, NULL, NULL, NULL, '{\"name\":\"贫道雾渊，本观主持就是贫道。\",\"here\":\"贫道粗通医术，要治病(cure)也许贫道可以试试看。\",\"cure\":[\"callable\",\"test_player\"],\"治病\":[\"callable\",\"test_player\"]}', '[\"雾渊真人叹到：难难难，道最玄，莫把金丹作等闲．\"]', NULL, NULL, 'human', NULL, NULL, 'male', 40, 'friendly', 300, 300, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 25, 50000, 100000, 0, 0, 0, 0, 400, 10, 100, 100, 0, 400, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'qujing', 'qujing/chechi/dianmen', 'qujing/chechi/dianmen', NULL, 0, 0, '[\"light\",\"thunder\"]', 0, 1, '2026-06-16 06:10:12', NULL, 0, 0, 0, NULL);
