INSERT INTO `npcs` VALUES (47, 'duguoyin', '杜过瘾', '赌场老板', '这老头看起来一脸悠闲，时不时抬头看看四个桌子上的赌客。', 0, NULL, NULL, NULL, NULL, NULL, '[\"杜过瘾四下打量了一番。\",\"杜过瘾沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 52, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 25, 40000, 20000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/duguoyin', 'city/duguoyin', 'vendor', 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (48, 'eryi', '二姨太', NULL, '金家的二姨太太，见你看她，对你抛了个媚眼．', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'female', 22, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 22, 1000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/xiemao', 'city/xiemao', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (49, 'faming', '法明长老', '主持', '法明长老是化生寺的主持，神色庄重，举止间自有一番威仪。听说他有一身武艺，也能呼风唤雨，却不传授于寺里的和尚。', 0, NULL, NULL, NULL, NULL, NULL, '[\"法明长老四下打量了一番。\",\"法明长老沉思片刻，若有所悟。\",\"法明长老叹道：天道苍茫，修行无尽啊。\",\"法明长老喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'bonze', NULL, 'male', 55, 'friendly', 100, 100, 900, 900, 600, 600, 10, 10, 10, 10, 10, 10, 23, 200000, 300000, 90000, 300, 0, 500, 500, 40, 100, 100, 900, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/fangzhang', 'city/fangzhang', NULL, 0, 30, '[\"bighammer\"]', 10, 1, '2026-06-16 05:37:54', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (50, 'fan', '范青屏', '拳盖三省', '范老拳师壮年时也是响当当的英雄，现在虽老了，手脚利落却不输当年．', 0, NULL, NULL, NULL, NULL, NULL, '[\"范青屏四下打量了一番。\",\"范青屏沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 72, 'friendly', 100, 100, 800, 800, 700, 700, 10, 10, 10, 10, 10, 10, 10, 100000, 50000, 0, 0, 0, 300, 300, 15, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/wuguanzhong', 'city/wuguanzhong', NULL, 1, 0, NULL, 0, 1, '2026-07-11 01:46:05', NULL, 0, 0, 0, NULL);
