INSERT INTO `npcs` VALUES (55, 'girla', '花钿', '小伴娘', '一个漂亮的小伴娘。', 0, NULL, NULL, NULL, NULL, NULL, '[\"花钿拿起玉笛，轻声吹出几音。\",\"花钿对你微微一笑。\",\"花钿随乐轻歌慢舞起来。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 18, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 500, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/girla', 'city/girla', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:40:13', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (56, 'girlb', '香玉', '小伴娘', '一个漂亮的小伴娘。', 0, NULL, NULL, NULL, NULL, NULL, '[\"香玉轻拨琵琶，划出一曲流水。\",\"香玉轻舒纤腰，随音而舞起来。\",\"香玉咯咯一笑，露出两个小酒窝。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 18, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 500, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/girlb', 'city/girlb', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:42:18', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (57, 'girlc', '小真', '小伴娘', '一个漂亮的小伴娘。', 0, NULL, NULL, NULL, NULL, NULL, '[\"小真纤手轻拨琴弦，发出如柳润风般的乐声。\",\"小真玉臂轻晃，随乐而舞。\",\"小真轻音而唱，如雀鸣莺歌。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 18, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 500, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/girlc', 'city/girlc', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:40:19', NULL, 0, 0, 0, NULL);
