INSERT INTO `npcs` VALUES (59, 'gongsun', '公孙大娘', '长安乐坊老板娘', '长安城内稍有名望的，不知道公孙大娘的人恐怕没几个。特别是那些文人骚客，跟公孙大娘不熟简直就是没面子。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"嘻嘻...连老娘我公孙大娘你都不知道...\",\"here\":\"嘿嘿...天下美景不胜数，长安此处最繁华。\",\"妓院\":\"大胆！此乃天子脚下，竟敢出此伤风败俗之言！\",\"妓女\":\"大胆！此乃天子脚下，竟敢出此伤风败俗之言！\",\"嫖妓\":\"大胆！此乃天子脚下，竟敢出此伤风败俗之言！\",\"青楼\":\"大胆！此乃天子脚下，竟敢出此伤风败俗之言！\",\"舞妓\":[\"callable\",\"apply_dancer\"],\"舞女\":[\"callable\",\"apply_dancer\"],\"歌妓\":[\"callable\",\"apply_dancer\"],\"歌女\":[\"callable\",\"apply_dancer\"],\"leave\":[\"callable\",\"answer_leaving\"],\"离开\":[\"callable\",\"answer_leaving\"]}', '[\"公孙大娘四下打量了一番。\",\"公孙大娘沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 32, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 20, 40000, 60000, 0, 0, 0, 400, 400, 5, 100, 100, 0, 0, 0, 200, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/shaizi-room', 'city/shaizi-room', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:10:36', NULL, 0, 0, 0, NULL);
