INSERT INTO `npcs` VALUES (63, 'haoke1', '酒客', NULL, '喝的满面通红，酒糟鼻子象一个西红柿．大概是喝的太多了，眼睛四处瞟着，嘴里嘟嘟囔囔不知说些什么．', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 36, 'heroism', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 10000, 0, 0, 0, 0, 200, 200, 3, 100, 100, 0, 0, 0, 1, 0, 0, 1, 0, NULL, 'gao', 'gao/inn', 'gao/inn', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
