INSERT INTO `npcs` VALUES (85, 'libai', '李白', '诗仙', '大诗人李白，清高飘逸，剑术通神。', 0, NULL, NULL, NULL, NULL, NULL, '[\"李白低声长吟道：危楼高百尺，手可摘星辰。\",\"李白低吟道：而来四万八千岁，不与秦汉通人烟。\",\"李白鼓腹而歌：挥手自兹去，萧萧班马鸣。\",\"李白击节而歌：赵客缦湖缨，吴钩霜雪明。银鞍照白马，飒沓如流星。\",\"李白低吟道：夫天地者，万物之逆旅。光阴者，百代之过客。\",\"李白击节而歌：脚着谢公屐，身登青云梯。半壁见海日，空中闻天鸡。\",\"李白吟道：孤帆远影碧空尽，唯见长江天际流。\",\"李白朗声吟道：蜀道之难，难于上青天，侧身西望长咨嗟。\",\"李白低声长吟：红颜弃轩冕，白首卧松云。\",\"李白醉态毕露，朗声长吟：醉看风落帽，舞爱月流人。\",\"李白长吟道：音尘绝，西风残照，汉家陵阙。\"]', NULL, NULL, 'human', 'scholar', NULL, 'male', 37, 'heroism', 400, 400, 700, 700, 500, 500, 25, 35, 30, 10, 10, 10, 30, 100000, 0, 0, 0, 0, 200, 200, 10, 100, 100, 0, 0, 0, 40, 0, 0, 1, 0, NULL, 'city', 'city/baihu-w1', 'city/baihu-w1', NULL, 20, 0, NULL, 20, 1, '2026-08-16 09:45:14', NULL, 0, 0, 0, NULL);
