INSERT INTO `npcs` VALUES (111, 'tiesuanpan', '铁算盘', '钱庄掌柜', NULL, 0, NULL, NULL, NULL, NULL, NULL, '[\"铁算盘嘿嘿嘿地笑了几声：我这把算盘几十年来可从来没错过。\",\"铁算盘骄傲的说道：提起本钱庄相老板，可以说是无人不晓。连当今皇上都跟他很熟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 54, 'friendly', 100, 100, 800, 800, 200, 200, 10, 10, 10, 10, 10, 10, 10, 50000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 1, 0, 0, 0, 1, 1, NULL, 'city', 'city/bank', 'city/bank', 'bank', 10, 0, NULL, 0, 1, '2026-08-16 09:37:00', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (112, 'weishi', '金甲卫士', NULL, '这是位守护皇城的金甲武士，身披铜甲，手执金瓜。他双目精光炯炯，警惕地巡视着四周的情形。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 25, 'heroism', 100, 100, 750, 750, 600, 600, 25, 10, 10, 10, 10, 10, 10, 160000, 0, 0, 0, 0, 400, 400, 15, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'huanggong', 'huanggong/baiyujie', 'huanggong/baiyujie', NULL, 0, 0, NULL, 20, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (113, 'weizhen', '魏征', '当朝宰相', '他就是当朝丞相魏征，性格刚正不阿，以敢于直谏闻名。', 0, NULL, NULL, NULL, NULL, NULL, '[\"魏征握紧了手中的兵器。\",\"魏征警惕地环顾四周。\"]', NULL, NULL, '人类', 'xian', '', 'male', 55, 'heroism', 100, 100, 100, 100, 100, 100, 20, 10, 10, 10, 100, 100, 10, 60000, 600000, 0, 0, 0, 500, 500, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', '', '', '', NULL, 5, 15, '[\"魏征大喝一声：受死吧！\",\"魏征冷笑道：就凭你也敢与我为敌？\",\"魏征怒喝：不知死活的东西！\"]', 23, 1, NULL, NULL, 0, 0, 0, NULL);
