INSERT INTO `npcs` VALUES (123, 'xiaoxiao', '萧萧', '恶娘子', '老英雄萧振远的小女儿，兵器铺女老板。由于凶蛮狠毒，江湖人称＂恶娘子＂。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'female', 25, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 70000, 0, 0, 0, 0, 200, 200, 5, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 'city', 'city/bingqipu', 'city/bingqipu', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (124, 'xiucai1', '高秀才', NULL, '国子监里的学生，正在吟诗作赋。', 0, NULL, NULL, NULL, NULL, NULL, '[\"高秀才低声吟道：一二三四五，上山打老虎，好诗，好诗呀！\",\"高秀才长叹一声：天生我才必有用，可惜不到有用时！\"]', NULL, NULL, 'human', 'scholar', NULL, 'male', 22, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 22, 8000, 0, 0, 0, 0, 200, 200, 3, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/guozijian', 'city/guozijian', NULL, 4, 0, NULL, 0, 1, '2026-08-16 09:45:14', NULL, 0, 0, 0, NULL);
