INSERT INTO `npcs` VALUES (127, 'xiucai4', '贺知章', '国子监大学士', '贺知章是国子监大学士，统管全国文人考试及升级。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"薄名何足挂齿...老夫贺知章蒙皇上恩赏国子监大学士，实是愧不敢当。\",\"here\":\"这里便是国子监。\",\"读书识字\":[\"callable\",\"ask_scholar\"],\"学习\":[\"callable\",\"ask_scholar\"],\"功名\":[\"callable\",\"apply_gongming\"],\"儒生\":[\"callable\",\"ask_scholar\"],\"申请儒生\":[\"callable\",\"ask_scholar\"]}', '[\"贺知章四下打量了一番。\",\"贺知章沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'scholar', NULL, 'male', 55, 'friendly', 100, 100, 100, 100, 100, 100, 25, 30, 10, 10, 10, 10, 10, 30000, 50000, 0, 0, 0, 500, 500, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/guozi', 'city/guozi', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:10:12', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (128, 'xiushi', '白衣秀士', NULL, '一位风流书生．不过他面色看起来怪怪的，好像有满腹心事。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"关你屁事！\",\"here\":\"长着眼睛你不会看啊。\",\"袁守诚\":\"江湖骗子。只有你们这帮傻瓜才信他。\",\"算命先生\":\"江湖骗子。只有你们这帮傻瓜才信他。\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 25, 'peaceful', 100, 100, 500, 500, 300, 300, 10, 10, 10, 10, 10, 10, 25, 10000, 0, 0, 0, 0, 150, 300, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/caotang', 'city/caotang', NULL, 20, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
