INSERT INTO `npcs` VALUES (132, 'yiren1', '江湖艺人', NULL, '一个打把式卖艺的，正在场中练功夫。', 0, NULL, NULL, NULL, NULL, NULL, '[\"艺人喊道：各位父老乡亲，在下初来贵宝地，多多指教！\",\"艺人拿铜锣敲了敲，喊到：各位有钱的捧个钱场，没钱的捧个人场！\",\"艺人舞了个刀花道：我这趟刀，叫五虎断门刀！\"]', NULL, NULL, 'human', NULL, NULL, 'male', 22, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 10000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/hgs/center', 'dntg/hgs/center', NULL, 8, 0, NULL, 0, 1, '2026-08-16 09:40:35', NULL, 0, 0, 0, NULL);
