INSERT INTO `npcs` VALUES (169, 'qinggui', '青面鬼', NULL, '一个青面鬼，面目狰狞可怕．', 0, NULL, NULL, NULL, NULL, NULL, '[\"青面鬼握紧了手中的兵器。\",\"青面鬼警惕地环顾四周。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 30, 'heroism', 100, 100, 550, 550, 300, 300, 10, 10, 10, 10, 10, 10, 100, 35000, 20000, 0, 0, 0, 200, 200, 10, 100, 100, 30, 30, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'death', 'death/walk7', 'death/walk7', NULL, 0, 0, '[\"青面鬼吼道：看招！\",\"青面鬼大喝：纳命来！\"]', 20, 1, '2026-06-16 06:13:46', NULL, 0, 0, 0, NULL);
