INSERT INTO `npcs` VALUES (174, 'suoming', '索命鬼', NULL, '一个青面獠牙的小鬼，身穿兽皮，手持铁链．他的任务就是从阳间将死人的魂魄带回．', 0, NULL, NULL, NULL, NULL, '{\"here\":\"这就是阴曹地府，哼，等着剥皮抽筋吧你！\"}', '[\"索命鬼的上上下下打量了你几眼。\",\"索命鬼说道：阎王叫你三更死，不敢留你到五更！\"]', NULL, NULL, 'human', NULL, NULL, 'male', 30, 'peaceful', 100, 100, 450, 450, 100, 100, 10, 10, 10, 10, 10, 10, 10, 0, 30000, 0, 0, 0, 300, 300, 15, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'death', 'death/suoming', 'death/suoming', NULL, 8, 0, NULL, 0, 1, '2026-08-07 22:05:31', NULL, 0, 0, 0, NULL);
