INSERT INTO `npcs` VALUES (179, 'wangfangping', '王方平', '轮回司主', '王方平本是山中道士，后在丰都山同阴长生同修炼成仙，御封(「鬼王」。', 1, 'yanluofu', '你好', NULL, '[\"很好，\"]', '{\"name\":\"在下王方平。\",\"here\":\"这里是地府阴司，阴气森森。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"王方平四下打量了一番。\",\"王方平沉思片刻，若有所悟。\",\"王方平叹道：天道苍茫，修行无尽啊。\",\"王方平喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'youling', '阎罗地府', 'male', 30, 'peaceful', 1400, 1400, 1400, 1400, 1400, 1400, 25, 25, 10, 10, 10, 10, 30, 850000, 600000, 0, 400, 0, 2500, 1500, 100, 100, 100, 2500, 1500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'death', 'death/new-lunhui', 'death/new-lunhui', NULL, 0, 40, '[\"sheqi\",\"gouhun\"]', 0, 1, '2026-06-16 05:55:40', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (180, 'wgargoyle', '白无常', '迎魂使者', '白无常伸着长长的舌头瞪着你，死白的脸上看不出任何喜怒哀乐。', 1, 'yanluofu', '你好', NULL, '[\"很好，\"]', NULL, '[\"白无常发出一阵像呻吟的声音，当他发现你正注视着他的时候，瞪了你一眼。\",\"白无常把长长的舌头伸出来，缓缓地舔了舔自己又白又长的手指。\"]', NULL, NULL, '人类', 'warrior', '', 'male', 217, 'peaceful', 600, 100, 700, 100, 600, 100, 20, 10, 10, 10, 100, 100, 10, 100000, 100000, 0, 0, 0, 400, 400, 20, 100, 100, 300, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 15, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
