INSERT INTO `npcs` VALUES (182, 'yanluowang', '阎罗王', '阴间十王之', '身穿大红蟒袍，头戴黑绸软巾．面如锅底，须若钢针，这就是阎罗王．', 1, 'yanluofu', '你好', '{\"combat_exp_min\": 50000, \"family_required\": \"阎罗地府\"}', NULL, '{\"还阳\":[\"callable\",\"expell_me\"],\"leave\":[\"callable\",\"expell_me\"],\"watch\":[\"callable\",\"send_me\"],\"十八层地狱\":[\"callable\",\"work_me\"],\"18\":[\"callable\",\"work_me\"],\"name\":\"哼！连老夫都不认得，想来是活的太久了！\",\"here\":\"这便是阎罗地府，到阳间一谈，嘿嘿，没人不怕！\",\"阳间\":\"人说阴阳殊途，其实不然，阴阳间有五点相交，来去相通！\",\"五点\":\"哈哈，要说知道的人却也不多，那便是年，月，日，时和长安泾水桥！\"}', '[\"阎罗王四下打量了一番。\",\"阎罗王沉思片刻，若有所悟。\",\"阎罗王叹道：天道苍茫，修行无尽啊。\",\"阎罗王喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'youling', '阎罗地府', 'male', 50, 'peaceful', 1800, 1800, 1800, 1800, 1800, 1800, 10, 10, 10, 10, 10, 10, 10, 1000000, 2000000, 800000, 600, 0, 1150, 1000, 60, 100, 100, 1500, 1500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'death', 'death/zhengtang', 'death/zhengtang', NULL, 0, 40, '[\"sheqi\",\"powerup\",\"recover\",\"gouhun\",\"inferno\",\"invocation\"]', 0, 1, '2026-06-16 06:10:08', NULL, 0, 0, 0, NULL);
