INSERT INTO `npcs` VALUES (188, 'zhutawei', '朱瑞', '太尉', '朱太尉是司房的总管，负责管理文件．', 0, NULL, NULL, NULL, NULL, NULL, '[\"朱瑞四下打量了一番。\",\"朱瑞沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 20, 'friendly', 400, 400, 400, 400, 400, 400, 10, 10, 10, 10, 10, 10, 30, 70000, 100000, 0, 0, 0, 250, 300, 10, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'death', 'death/sifang', 'death/sifang', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:10:36', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (189, 'killer1', '杀手', '', '这是一位来自阴界的守护神，专门担任护法之责。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', '', '', 'male', 0, 'friendly', 400, 100, 400, 100, 400, 100, 30, 10, 10, 10, 30, 30, 10, 50000, 100, 0, 0, 0, 200, 200, 10, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 34, '[\"喝道：孽障！随我赴阴司受审吧。\"]', 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (190, 'killer2', '酆都鬼使', '', '这是一位来自阴界的守护神，专门担任护法之责。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', 'warrior', '', 'male', 50, 'friendly', 600, 100, 600, 100, 600, 100, 30, 10, 10, 10, 30, 30, 10, 100000, 100, 0, 0, 0, 400, 400, 20, 100, 100, 400, 400, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 26, '[\"喝道：孽障！随我赴阴司受审吧。\"]', 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (191, 'killer3', '白无常', '迎魂使者', '白无常伸着长长的舌头瞪着你，死白的脸上看不出任何喜怒哀乐。', 1, NULL, NULL, NULL, NULL, NULL, '[\"白无常发出一阵像呻吟的声音，当他发现你正注视着他的时候，瞪了你一眼。\\\",\"白无常把长长的舌头伸出来，缓缓地舔了舔自己又白又长的手指。\\\"]', NULL, NULL, 'human', 'youling', '阎罗地府', 'male', 217, 'peaceful', 600, 600, 700, 700, 600, 600, 20, 20, 10, 10, 10, 10, 100, 100000, 100000, 0, 0, 0, 400, 400, 20, 100, 100, 300, 300, 0, 0, 0, 0, 1, 0, NULL, 'death', 'death/wgargoyle', 'death/wgargoyle', NULL, 15, 0, '[\"喝道：孽障！随我赴阴司受审吧。\"]', 0, 1, '2026-06-16 07:16:35', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (192, 'killer4', '黑无常', '送魂使者', '黑无常伸着长长的舌头瞪着你，黝黑的脸上看不出任何喜怒哀乐。', 1, NULL, NULL, NULL, NULL, NULL, '[\"黑无常发出一阵像呻吟的声音，当他发现你正注视著他的时候，瞪了你一眼。\\\",\"黑无常把长长的舌头伸出来，缓缓地舔了舔自己又黑又长的手指。\\\"]', NULL, NULL, 'human', 'youling', '阎罗地府', 'male', 217, 'peaceful', 400, 400, 800, 800, 800, 800, 25, 20, 10, 10, 10, 10, 100, 120000, 200000, 0, 0, 0, 500, 500, 20, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, NULL, 'death', 'death/gateway', 'death/gateway', NULL, 10, 0, '[\"喝道：孽障！随我赴阴司受审吧。\"]', 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (202, 'guipan', '鬼判', NULL, '看门的鬼判，正恶狠狠地盯着你。', 0, NULL, NULL, NULL, NULL, NULL, '[\"鬼判四下打量了一番。\",\"鬼判沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 10, 'friendly', 200, 200, 100, 100, 200, 200, 10, 10, 10, 10, 10, 10, 15, 2500, 6000, 0, 0, 0, 300, 300, 5, 100, 100, 0, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'erlang', 'erlang/guanjiang', 'erlang/guanjiang', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:09:28', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (203, 'bull', '老牛', NULL, '一头老牛。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', NULL, NULL, 'male', 15, 'friendly', 100, 100, 100, 100, 100, 100, 26, 10, 10, 10, 30, 10, 10, 100, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'gao', 'gao/daotian1', 'gao/daotian1', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (204, 'cunzhang', '吴文', '村长', '一个看起来颇有风度的中年人，背着手闲逛．', 0, NULL, NULL, NULL, NULL, '{\"name\":\"老夫姓吴，单名一个文字．\",\"here\":\"这儿哪您还不清楚吗？嘿嘿．．．\"}', '[\"村长上上下下打量了你几眼。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 46, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 8000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 2, 0, 0, 1, 0, NULL, 'gao', 'gao/cunkou', 'gao/cunkou', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:14:08', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (206, 'gao', '高员外', '庄主', '高家庄的主人，吃的胖乎乎的．按说大财主应该乐呵呵地，他却愁眉苦脸，象是遇到了什么难事．', 0, NULL, NULL, NULL, NULL, '{\"name\":\"老夫姓高，乃是家中的主人．\\n\",\"here\":\"高老庄是也．\\n\",\"女儿\":\"唉...小女翠兰被一伙土匪抢走了，至今下落不明...\\n\",\"小姐\":\"唉...小女翠兰被一伙土匪抢走了，至今下落不明...\\n\",\"闺女\":\"唉...小女翠兰被一伙土匪抢走了，至今下落不明...\\n\",\"翠兰\":\"唉...翠兰她被土匪抢走了，都怪我没用，保护不了女儿...\\n\",\"土匪\":\"那些土匪从后面的小树林进来，光天化日之下就把我女儿抢走了！\\n\",\"强盗\":\"那些强盗从后面的小树林进来，光天化日之下就把我女儿抢走了！\\n\",\"高婆\":\"内人整日以泪洗面，身体都快熬垮了...\\n\",\"夫人\":\"内人整日以泪洗面，身体都快熬垮了...\\n\",\"家丁\":\"家丁们都出去寻找小姐的下落了，可惜至今没有消息...\\n\",\"仆人\":\"家丁们都出去寻找小姐的下落了，可惜至今没有消息...\\n\",\"救\":\"谁若是能救出我的女儿，小老儿感激不尽，愿以重金相谢！\\n\",\"帮忙\":\"谁若是能救出我的女儿，小老儿感激不尽，愿以重金相谢！\\n\"}', '[\"高员外：谁若是能救出我的女儿，小老儿感激不尽！\"]', '高员外：谁若是能救出我的女儿，小老儿感激不尽！', NULL, 'human', NULL, NULL, 'male', 46, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 5000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'gao', 'gao/zhting', 'gao/zhting', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (207, 'gaopo', '高婆', NULL, '高庄主的老婆，虽已四十多岁，看起来还又几分姿色．', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'female', 40, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 20, 7400, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 1, 0, 0, 0, 1, 0, NULL, 'gao', 'gao/pianting', 'gao/pianting', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (210, 'head', '夏鹏展', '清风寨强盗头领', '夏鹏展原是长安城中一名捕头，因贼性难改，落草作了强盗．使一路雁歌刀法，手中雁云刀阴狠无比．', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 37, 'aggressive', 100, 100, 700, 700, 600, 600, 25, 10, 10, 10, 10, 10, 10, 60000, 0, 0, 0, 0, 350, 300, 20, 100, 100, 0, 0, 0, 50, 0, 1, 1, 0, NULL, 'gao', 'gao/room', 'gao/room', NULL, 0, 0, NULL, 50, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (215, 'laoli', '老李头', '铁匠', '铁铺的主人．', 0, NULL, NULL, NULL, NULL, NULL, '[\"一脚踢在小学徒的屁股上，嚷道：不许偷懒！\",\"对小学徒嚷道：教你多少次了！你怎么这么笨！\"]', NULL, NULL, 'human', NULL, NULL, 'male', 56, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 15, 6800, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 'gao', 'gao/tiepu', 'gao/tiepu', 'weapon', 5, 0, NULL, 0, 1, '2026-08-07 22:04:52', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (218, 'pangsao', '胖嫂', '老板娘', '胖嫂原是裁缝，后在长安的儿子发了财，便自家开了布店．', 0, NULL, NULL, NULL, NULL, '', '[\"pang四下打量了一番。\",\"pang沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 46, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 12, 1100, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 'gao', 'gao/budian', 'gao/budian', 'vendor', 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (219, 'teacher', '匡文正', '教书先生', '村里的老教书先生，孩子们的扫盲全靠他了．', 0, NULL, NULL, NULL, NULL, '{\"name\":\"老夫姓匡，字文正．阁下是．．．\",\"here\":\"这儿是老夫办的学堂，教孩子们一些知识．\"}', '[\"匡文正说道：『小心天下去得，莽撞寸步难行』。你要牢牢记得．\",\"匡文正摇头晃脑的念道：子曰：有朋自远方来，不亦乐乎．．无须备饭．\",\"匡文正笑盈盈地跟你打招呼：吃了？！\"]', NULL, NULL, 'human', NULL, NULL, 'male', 66, 'friendly', 100, 100, 100, 100, 100, 100, 10, 30, 10, 10, 10, 10, 10, 10000, 5000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 5, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'gao', 'gao/xuetang', 'gao/xuetang', NULL, 5, 0, NULL, 0, 1, '2026-08-16 09:36:23', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (220, 'tufei', '土匪', '', '一个体型魁悟，看起来孔武有力的大个子．正狠巴巴的瞪着你．', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', '', '', 'male', 0, 'aggressive', 100, 100, 100, 100, 100, 100, 100, 10, 10, 10, 100, 100, 10, 100, 100, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, 'gao', 'gao/xiaolin1', 'gao/xiaolin1', NULL, 0, 0, NULL, 50, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (222, 'washer', '老妈子', NULL, '一个老太婆，正生气的洗着一堆衣服．', 0, NULL, NULL, NULL, NULL, NULL, '[\"老妈子嘟囔着：该杀的土匪，抢了我家小姐！\",\"老妈子低声道：后面有条近道，土匪就是那儿进来的．\"]', NULL, NULL, 'human', NULL, NULL, 'female', 68, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 15, 500, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'gao', 'gao/washing', 'gao/washing', NULL, 4, 0, NULL, 0, 1, '2026-08-16 09:42:18', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (226, 'yahuan1', '丫环', NULL, '一个美丽的丫环。', 0, NULL, NULL, NULL, NULL, '{\"衣服\":\"衣服上的扣子找不到了．．．\\n\",\"剩饭\":\"吃，吃，吃个没完，羞也不羞！\\n\",\"剩菜\":\"吃，吃，吃个没完，羞也不羞！\\n\",\"food\":\"吃，吃，吃个没完，羞也不羞！\\n\"}', NULL, NULL, '[{\"action_name\":\"送扣子\",\"type\":\"accept_object\",\"accepted_items\":[\"kouzi\"],\"response_message\":\"丫环说道：咦，你哪里找到的，真是谢谢你了！\\n丫环从桌上拿了一只烤鸡，递到你的手中。\",\"reward_item\":\"kaoji\"}]', 'human', NULL, NULL, 'female', 14, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 600, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'gao', 'gao/fanting', 'gao/fanting', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
