INSERT INTO `npcs` VALUES (237, 'shinu', '侍女', NULL, '皇宫中的侍女，负责皇宫里的饮食起居等杂务。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'female', 0, 'friendly', 200, 200, 200, 200, 200, 200, 10, 10, 10, 10, 10, 10, 10, 0, 0, 0, 0, 0, 100, 100, 5, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'huanggong', 'huanggong/baihu', 'huanggong/baihu', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (254, 'xuerengui', '薛仁贵', '九门提督', '薛仁贵是长安城九门提督，负责皇宫内外安全。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 35, 'friendly', 600, 600, 850, 850, 100, 100, 35, 10, 10, 10, 10, 10, 25, 350000, 0, 0, 0, 0, 600, 600, 35, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, NULL, 'huanggong', 'huanggong/damen', 'huanggong/damen', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (255, 'baifalaoren', '白发老人', '神仙', '这是一位鹤发童颜的老人。他看起来似乎很老的样子，但偏又是红光满面。看到你打量他，他对你和蔼地笑了一笑。', 1, 'jiangjunfu', '蓝', NULL, '[\"这。。。老夫素来不收无缘之人，\", \"看来\"]', '{\"name\":\"我是谁？我也不记得了。\",\"here\":\"这是一场梦。\",\"rumors\":\"消息？你不专心学艺，又来打听什么消息？\",\"回去\":[\"callable\",\"kick_back\"],\"return\":[\"callable\",\"kick_back\"]}', '[\"白发老人四下打量了一番。\",\"白发老人沉思片刻，若有所悟。\",\"白发老人叹道：天道苍茫，修行无尽啊。\",\"白发老人喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '人类', 'xian', '', 'male', 81, 'peaceful', 100, 100, 3500, 100, 4500, 100, 20, 10, 10, 10, 30, 75, 10, 2000000, 2000000, 0, 0, 0, 1500, 1500, 40, 100, 100, 3000, 3000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'jjf', 'jjf/sleep2', 'jjf/sleep2', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:42:18', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (256, 'chengyaojin', '程咬金', '开国元勋', '程咬金是大唐开国出名的福将，曾从梦中学来一套威猛无匹的宣花三斧，后来又曾拜倒过一面大旗。谈起他的福气，真的是人人羡慕。', 1, 'jiangjunfu', '混世魔王', '{\"con_min\": 28, \"daoxing_min\": 100000}', '{\"con\": \"身子骨太弱，扛不住我一斧。\", \"daoxing\": \"修为不够，再练练。\"}', '{\"name\":\"我就是人称福将的程咬金！\",\"here\":\"这里是大唐国都长安府。\",\"rumors\":\"你看老程象是成天吃饱了撑的打听小道消息的么？\",\"福将\":[\"callable\",\"gloat\"],\"白发仙人\":\"那白发仙人是我恩师，若想见他，需得有缘。\",\"有缘\":[\"callable\",\"ask_me\"]}', '[\"程咬金四下打量了一番。\",\"程咬金沉思片刻，若有所悟。\",\"程咬金叹道：天道苍茫，修行无尽啊。\",\"程咬金喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, '将军府', 'male', 45, 'friendly', 100, 100, 2800, 2800, 300, 300, 30, 10, 10, 10, 70, 15, 10, 800000, 200000, 0, 0, 0, 500, 500, 40, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'jjf', 'jjf/qilin', 'jjf/qilin', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:13:46', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (257, 'fujiang', '福将', '副将', '', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', '', '', 'male', 30, 'peaceful', 100, 100, 700, 100, 400, 100, 100, 10, 10, 10, 100, 100, 10, 100, 100, 0, 0, 0, 1000, 800, 25, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/yingfang', 'jjf/yingfang', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (260, 'hulei', '呼雷豹', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '[\"呼雷豹四下打量了一番。\",\"呼雷豹沉思片刻，若有所悟。\"]', NULL, NULL, '野兽', NULL, NULL, 'male', 20, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 10000, 5000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'jjf', 'jjf/majuan', 'jjf/majuan', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:07:20', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (262, 'lijiancheng', '李建成', '齐王', '李建成乃是唐高祖李渊的大儿子，受封齐王，随高祖南征北战时颇立战功。虽无二弟李世民显赫，但也非老三李元吉一般屡吃败仗。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 36, 'friendly', 100, 100, 600, 600, 200, 200, 25, 25, 10, 10, 10, 10, 25, 250000, 0, 0, 0, 0, 400, 400, 30, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/zuixing2', 'jjf/zuixing2', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (263, 'liyuanji', '李元吉', '建王', '李元吉乃是唐高祖李渊的三子，受封建王。三子中以李元吉最为无用。他空有一身蛮力，但无恶不作，毫不以领地百姓为重。且在作战时屡失重要据点，实在令高祖大为头痛。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 22, 'friendly', 100, 100, 700, 700, 150, 150, 40, 20, 10, 10, 50, 50, 15, 300000, 0, 0, 0, 0, 500, 500, 50, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/zuixing2', 'jjf/zuixing2', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (264, 'luocheng', '罗成', '开国元勋', '罗成是秦琼的表弟，乃是隋唐第七条好汉。传说他早已在保长安时被乱箭射死战死，但不知为何还在这里。听说罗成年幼时曾受过异人传授，学得一身奇异的内功，因此比武极少败过。', 1, 'jiangjunfu', '冷面寒枪', '{\"dex_min\": 30, \"daoxing_min\": 180000}', '{\"dex\": \"身法太慢，学不了我的枪法。\", \"daoxing\": \"道行不足，回去修炼。\"}', NULL, NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 34, 'friendly', 100, 100, 3500, 3500, 3000, 3000, 50, 30, 50, 10, 50, 50, 30, 1800000, 0, 0, 0, 0, 2000, 2000, 100, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/guest_cabinet2', 'jjf/guest_cabinet2', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (265, 'luochun', '罗春', '罗府家将', '罗春是罗府的心腹家将，办事甚是得力。传说他是罗艺的私生子，是罗成的亲哥哥。罗春的一手霸王枪使得纯熟无比，在战场上曾经颇立战功。', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 40, 'friendly', 100, 100, 1200, 1200, 600, 600, 50, 25, 50, 10, 50, 50, 25, 1000000, 0, 0, 0, 0, 2000, 1500, 20, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/guest_cabinet', 'jjf/guest_cabinet', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (266, 'qin', '秦平', '将军府管家', '', 1, 'jiangjunfu', '蓝', NULL, '[\"很好，时下正是用人之际，\"]', '{\"兵器\":[\"callable\",\"try_me\"],\"衣甲\":[\"callable\",\"try_me\"]}', NULL, NULL, NULL, '人类', 'warrior', '', 'male', 63, 'peaceful', 100, 100, 600, 100, 200, 100, 30, 10, 10, 10, 100, 100, 10, 80000, 100, 0, 0, 0, 500, 400, 20, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
