INSERT INTO `npcs` VALUES (268, 'qinbing-jian', '亲兵', '建王府', '', 0, NULL, NULL, NULL, NULL, '{\"name\":\"问什么问？长着眼睛不会看哪？\",\"here\":\"这儿就是醉星楼！造的可比对面那破房子强得多啦！\",\"rumors\":\" 听说有人想来拆房子，哼！\",\"食物\":\"如果是良民，可以领些包子去。\",\"钱财\":\"如果是良民，可以领些银子去。\",\"包子\":[\"callable\",\"ask_me\"],\"baozi\":[\"callable\",\"ask_me\"],\"银子\":[\"callable\",\"ask_me\"],\"silver\":[\"callable\",\"ask_me\"],\"拆房子\":\"哼，除非把老子打发了，否则谁也别想来这儿撒野！\"}', NULL, NULL, NULL, '人类', 'warrior', '', 'male', 25, 'peaceful', 100, 100, 300, 100, 200, 100, 100, 10, 10, 10, 100, 100, 10, 80000, 100, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/zuixing', 'jjf/zuixing', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (269, 'qinbing-qi', '亲兵', '将军府', '这些亲兵都是在沙场上立过无数汗马功劳的强将。他们不原受封为官，宁肯跟随保护旧主。', 1, NULL, NULL, NULL, NULL, '{\"name\":\"问什么问？长着眼睛不会看哪？\",\"here\":\"这儿就是醉星楼！造的可比对面那破房子强得多啦！\",\"rumors\":\" 听说有人想来拆房子，哼！\",\"拆房子\":\"哼，除非把老子打发了，否则谁也别想来这儿撒野！\"}', NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 0, 'friendly', 100, 100, 100, 100, 200, 200, 10, 10, 10, 10, 10, 10, 10, 0, 0, 0, 0, 0, 400, 350, 15, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/qilin', 'jjf/qilin', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (271, 'qinfu', '秦富', '将军府管家', NULL, 1, 'jiangjunfu', '蓝', NULL, '[\"很好，时下正是用人之际\"]', NULL, NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 38, 'friendly', 100, 100, 700, 700, 200, 200, 30, 25, 10, 10, 10, 10, 10, 75000, 0, 0, 0, 0, 550, 500, 30, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/front_yard', 'jjf/front_yard', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (272, 'qinping', '秦平', '将军府管家', NULL, 1, 'jiangjunfu', '蓝', NULL, '[\"很好，时下正是用人之际，\"]', '{\"兵器\":[\"callable\",\"try_me\"],\"衣甲\":[\"callable\",\"try_me\"]}', NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 46, 'friendly', 100, 100, 600, 600, 200, 200, 30, 25, 10, 10, 10, 10, 10, 80000, 0, 0, 0, 0, 500, 400, 20, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/qin', 'jjf/qin', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (273, 'qinqiong', '秦琼', '开国元勋', '秦叔宝是大唐国开国名臣，更是一位出名的武将。', 1, 'jiangjunfu', '蓝', '{\"combat_exp_min\": 100000}', '[\"这位\", \"很好，时下正是用人之际，\"]', '{\"name\":\"在下秦琼，字叔宝。\",\"here\":\"这里就是将军府啊，难道你不知道？\",\"rumors\":\"在下不在江湖行走很久了，江湖上的事情在下可不太清楚。\",\"转业\":[\"callable\",\"expell_me\"],\"leave\":[\"callable\",\"expell_me\"]}', NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 43, 'friendly', 100, 100, 1400, 1400, 800, 800, 30, 30, 10, 10, 10, 10, 26, 1200000, 0, 0, 0, 0, 1000, 800, 80, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'city', 'city/shubao', 'city/shubao', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (274, 'weizheng', '魏徵', '郑国公', '魏徵先仕齐府为太子李建成屡设妙计。但李建成不听其劝告，终为太宗所杀。太宗爱魏徵之才，将其收罗，并封为郑国公。', 1, 'jiangjunfu', '文人', NULL, NULL, NULL, '[\"魏徵四下打量了一番。\",\"魏徵沉思片刻，若有所悟。\",\"魏徵叹道：天道苍茫，修行无尽啊。\",\"魏徵喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, '将军府', 'male', 55, 'friendly', 100, 100, 300, 300, 1000, 1000, 15, 40, 10, 10, 10, 10, 25, 40000, 800000, 0, 0, 0, 200, 200, 10, 100, 100, 700, 700, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'jjf', 'jjf/weizheng', 'jjf/weizheng', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (275, 'xiaotong', '青衣小童', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 10, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 30, 100, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'death', 'death/room1', 'death/room1', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (276, 'yuchigong', '尉迟恭', '开国元勋', '尉迟恭，字敬德，乃是唐太宗手下猛将。排为隋唐时第十二条好汉。起初他是反王刘武州殿前元帅，后因兵败降唐。他惯使一条点钢枪，且喜使一对雌雄竹节钢鞭。', 1, 'jiangjunfu', '门神', '{\"str_min\": 30, \"daoxing_min\": 150000}', '{\"str\": \"力量不足，学不了我的功夫。\", \"daoxing\": \"道行不够，再去历练。\"}', NULL, NULL, NULL, NULL, 'human', NULL, '将军府', 'male', 43, 'friendly', 100, 100, 4000, 4000, 1500, 1500, 45, 20, 10, 10, 50, 40, 15, 1400000, 0, 0, 0, 0, 1000, 2500, 100, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'jjf', 'jjf/qilin2', 'jjf/qilin2', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (295, 'chaniang', '茶娘子', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'female', 38, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 29, 3000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 'kaifeng', 'kaifeng/chunchun', 'kaifeng/chunchun', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (296, 'chen', '陈光蕊', '大阐都纲', '陈光蕊乃玄奘之父，当朝大阐都纲御赐状元。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃禹王台也，水陆大会将不期举行，本状元在此预做法场以祭祖求贤。\",\"name\":\"玄奘之父陈光蕊也，在此做法祭祖求贤。\",\"ask\":[\"callable\",\"test_player\"],\"祭祖\":[\"callable\",\"test_player\"],\"求贤\":[\"callable\",\"test_player\"],\"招贤\":[\"callable\",\"test_player\"],\"贤人\":[\"callable\",\"test_player\"],\"贤士\":[\"callable\",\"test_player\"],\"善哉\":[\"callable\",\"test_player\"],\"招\":[\"callable\",\"test_player\"],\"求\":[\"callable\",\"test_player\"]}', '[\"陈光蕊四下打量了一番。\",\"陈光蕊沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'scholar', NULL, 'male', 50, 'peaceful', 400, 400, 400, 400, 400, 400, 10, 10, 10, 10, 10, 10, 35, 40000, 100000, 0, 0, 0, 0, 400, 20, 100, 100, 0, 400, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'kaifeng', 'kaifeng/jixian', 'kaifeng/jixian', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:37:16', NULL, 0, 0, 0, NULL);
