INSERT INTO `npcs` VALUES (316, 'wei', '魏征', '丞相', NULL, 0, NULL, NULL, NULL, NULL, NULL, '[\"魏征四下打量了一番。\",\"魏征沉思片刻，若有所悟。\",\"魏征叹道：天道苍茫，修行无尽啊。\",\"魏征喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 60, 'friendly', 3000, 3000, 3000, 3000, 3000, 3000, 10, 10, 10, 10, 10, 10, 30, 300000, 800000, 0, 0, 0, 1000, 1000, 80, 100, 100, 1000, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'kaifeng', 'kaifeng/ground', 'kaifeng/ground', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (318, 'xgong', '相公', '御赐', NULL, 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃御赐相府也，老夫被御准在此收集武器。\",\"name\":\"姓相名良也。\",\"weapon\":[\"callable\",\"test_player\"],\"武器\":[\"callable\",\"test_player\"],\"兵器\":[\"callable\",\"test_player\"],\"法宝\":[\"callable\",\"test_player\"],\"收集\":[\"callable\",\"test_player\"],\"征集\":[\"callable\",\"test_player\"],\"宝\":[\"callable\",\"test_player\"]}', '[\"相公喜形于色地说：近来各类武器征集了不少，找个时间派人送到京城。\",\"相公自言自语道：武器精品将不期进贡给皇宫。\",\"相公呐呐地说道：军机大臣派人催问可否弄得武器佳品。\",\"相公说：什么兵器都要，可以改良或仿制也。\",\"相公低声说道：收集的武器该分类处置。\",\"相公自言道：好，各路英雄豪杰都纷纷前来献宝。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 80, 'peaceful', 400, 400, 400, 400, 400, 400, 10, 10, 10, 10, 10, 10, 25, 20000, 100000, 0, 0, 0, 0, 100, 10, 100, 100, 0, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'kaifeng', 'kaifeng/bingqi', 'kaifeng/bingqi', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:40:19', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (319, 'xianglan', '香兰', NULL, NULL, 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃高姓兰亭府也，姑娘在此收集奇珍异宝。\",\"name\":\"高家小姐香兰也。\",\"cloth\":[\"callable\",\"test_player\"],\"异宝\":[\"callable\",\"test_player\"],\"募捐\":[\"callable\",\"test_player\"],\"捐\":[\"callable\",\"test_player\"]}', '[\"香兰咯咯一笑：各类异宝可不少。\",\"香兰宛尔一笑说道：天下善人多也。\",\"香兰说：大开眼界，乐也乐也。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 28, 'peaceful', 400, 400, 400, 400, 400, 400, 10, 10, 10, 10, 10, 10, 28, 5500, 0, 0, 0, 0, 0, 200, 20, 100, 100, 0, 200, 0, 0, 0, 0, 1, 0, NULL, 'kaifeng', 'kaifeng/xianglan', 'kaifeng/xianglan', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:45:14', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (321, 'xpo', '相婆', '御赐', NULL, 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃御赐相府也，妾身在此专门收集盔甲。\",\"name\":\"相良之妻也。\",\"armor\":[\"callable\",\"test_player\"],\"盔甲护具\":[\"callable\",\"test_player\"],\"盔甲\":[\"callable\",\"test_player\"],\"护具\":[\"callable\",\"test_player\"],\"收集\":[\"callable\",\"test_player\"],\"征集\":[\"callable\",\"test_player\"]}', '[\"相婆高兴地说：相公也说啦，奇货征集了不少，可近期派人将盔甲护具送到京城。\",\"相婆说道：皇宫里人说我们相府收集了不少好盔甲护具。\",\"相婆又说道：魏大人也说上次送的盔甲护具里不少上乘品。\",\"相婆说：有些盔甲护具可以加以改良。\",\"相婆说道：相府征集盔甲护具，真是做了好事也。\",\"相婆自言道：个别征来的盔甲残缺不全，还需努力征集。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 75, 'peaceful', 300, 300, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 28, 15000, 50000, 0, 0, 0, 0, 100, 10, 100, 100, 0, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'kaifeng', 'kaifeng/kuijia', 'kaifeng/kuijia', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (322, 'xu', '徐老板', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 45, 'friendly', 100, 100, 700, 700, 700, 700, 10, 10, 10, 10, 10, 10, 10, 40000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 10, 0, 0, 1, 1, NULL, 'kaifeng', 'kaifeng/dangpu', 'kaifeng/dangpu', 'hockshop', 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (325, 'yaomo', '巡山妖', NULL, '一个相貌凶险的盗贼, 你仔细一看, 只见他股后似有一条尾巴。啊！难怪盗贼如此凶狠，原是早已豺狼成精，并非凡胎啊。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 0, 'peaceful', 100, 100, 800, 800, 800, 800, 10, 10, 10, 10, 10, 10, 5, 300000, 150000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 20, 0, 0, 1, 0, NULL, 'qujing', 'qujing/yaomo', 'qujing/yaomo', NULL, 0, 0, NULL, 50, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (326, 'ye', '禹王爷', '天御玉执', NULL, 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃禹王林，妖魔大会在此定期(schedule)举行也。\",\"?\":\"此乃禹王林，妖魔大会在此定期(schedule)举行也。\",\"妖魔大会\":\"妖魔大会乃一迷宫大阵设在禹王林中，雾瘴蔽天妖魔野兽横行，玩家务必尽其全部本领杀尽所有对手，伤亡不损元神，赢者自有重赏也。玩家使init申请大会开始，再使join参加大会，巫师可使join_all让全体玩家参加大会。\",\"ymdh\":\"妖魔大会乃一迷宫大阵设在禹王林中，雾瘴蔽天妖魔野兽横行，\",\"schedule\":[\"callable\",\"check_schedule\"]}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 100, 'friendly', 3000, 3000, 3000, 3000, 3000, 3000, 10, 10, 10, 10, 10, 10, 30, 300000, 0, 0, 0, 0, 1000, 1000, 80, 100, 100, 1000, 1000, 0, 0, 0, 0, 1, 0, NULL, 'kaifeng', 'kaifeng/yuwang5', 'kaifeng/yuwang5', NULL, 100, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (327, 'yin', '殷温娇', '御赐贤夫人', '殷夫人乃是殷开山之女，玄奘之母。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃禹王台也，水陆大会将不期举行，妾身在此预做法场以事天下灾民难民。\",\"name\":\"玄奘之母殷夫人也，在此做法以事天下灾民难民。\",\"give\":[\"callable\",\"test_player\"],\"灾民\":[\"callable\",\"test_player\"],\"难民\":[\"callable\",\"test_player\"],\"穷人\":[\"callable\",\"test_player\"],\"受灾\":[\"callable\",\"test_player\"],\"解难\":[\"callable\",\"test_player\"],\"救灾\":[\"callable\",\"test_player\"],\"救\":[\"callable\",\"test_player\"],\"给\":[\"callable\",\"test_player\"]}', '[\"殷夫人叹道：唉，多灾多难哪。\\\",\"殷夫人自言自语地说道：近闻他乡受灾，令妾身彻夜难眠也。\\\",\"殷夫人说道：乡下水祸成灾，妾身痛心也。\\\",\"殷夫人叹言道：普天之下，有多少民众仍处于水深火热之中也。\\\",\"殷夫人说道：妾身救人之急也。\\\",\"殷夫人说道：亦恨不能妾身亲自赴汤蹈海，以解八方之难也。\\\"]', NULL, NULL, 'human', NULL, NULL, 'female', 50, 'peaceful', 300, 300, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 35, 10000, 0, 0, 0, 0, 0, 300, 5, 100, 100, 0, 300, 0, 0, 0, 0, 1, 0, NULL, 'kaifeng', 'kaifeng/pudu', 'kaifeng/pudu', NULL, 5, 0, NULL, 0, 1, '2026-06-16 07:16:35', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (328, 'zhubajie', '猪八戒', NULL, '嘿嘿，连老猪都不认识啦？', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃天蓬帅府也，老猪西天归来后唐太宗御赐在此开府，专事饮食慈善业。\",\"name\":\"猪八戒，谁人不知也。\",\"food\":[\"callable\",\"test_player\"],\"美食\":[\"callable\",\"test_player\"],\"美酒\":[\"callable\",\"test_player\"],\"美宴\":[\"callable\",\"test_player\"],\"佳肴\":[\"callable\",\"test_player\"],\"食物\":[\"callable\",\"test_player\"],\"饮水\":[\"callable\",\"test_player\"],\"吃\":[\"callable\",\"test_player\"],\"喝\":[\"callable\",\"test_player\"]}', '[\"猪八戒乐呵呵地说道：西天归来，老猪便是天下美食家也。\",\"猪八戒想想说：乡下发大水灾了，老猪该当救济饥民。\",\"猪八戒说道：老猪要寻遍天下美酒佳肴，再请世人来俺帅府品尝品尝。\",\"猪八戒说道：不是老猪贪嘴，俺老猪想凑个美宴，请平民百姓也能尝个新鲜。\",\"猪八戒自言自语地说：俺老猪不是为自己，老猪想收集世上美食，让大唐人都能来尝尝。\",\"猪八戒扭过身去捧起澡盆大的金饭盆吧嗒吧嗒大嚼了起来。\",\"猪八戒弯腰捧起水桶大的银酒壶咕咚咕咚地灌了下去。\"]', NULL, '[{\"action_name\":\"回梦\",\"action_cmd\":\"huimeng\",\"description\":\"施展回梦技能，让对手陷入梦境\",\"required_skill\":\"wudang\\/huimeng\"},{\"action_name\":\"放瞌睡虫\",\"action_cmd\":\"fang_keshuichong\",\"description\":\"放出瞌睡虫，使对手昏昏欲睡\",\"required_item\":\"瞌睡虫\"}]', 'human', NULL, NULL, 'male', 600, 'peaceful', 100, 100, 1500, 1500, 1500, 1500, 50, 10, 10, 10, 10, 10, 10, 1200000, 2000000, 0, 0, 0, 1500, 1500, 150, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'kaifeng', 'kaifeng/shuaifu', 'kaifeng/shuaifu', NULL, 5, 0, NULL, 0, 1, '2026-08-16 09:42:18', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (329, 'zhubing', '猪兵', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '[\"猪兵四下打量了一番。\",\"猪兵沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 28, 'peaceful', 100, 100, 500, 500, 500, 500, 40, 10, 10, 10, 10, 10, 10, 50000, 20000, 0, 0, 0, 500, 500, 50, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'kaifeng', 'kaifeng/tianpeng', 'kaifeng/tianpeng', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (330, 'zu', '禹王卒', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '[\"禹王卒四下打量了一番。\",\"禹王卒沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 0, 'peaceful', 100, 100, 400, 400, 400, 400, 20, 10, 10, 10, 10, 10, 10, 20000, 20000, 0, 0, 0, 200, 200, 10, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'kaifeng', 'kaifeng/shuilu', 'kaifeng/shuilu', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (331, 'bei', '圣悲', '大法师', '一位身披仙袍，面容严肃慈善的大法师。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃禹王台也，水陆大会将不期举行，本法师在此预做法场以事天下灾民难民。\",\"name\":\"圣悲法师，在此做法以事天下灾民难民。\",\"give\":[\"callable\",\"test_player\"],\"灾民\":[\"callable\",\"test_player\"],\"难民\":[\"callable\",\"test_player\"],\"穷人\":[\"callable\",\"test_player\"],\"受灾\":[\"callable\",\"test_player\"],\"解难\":[\"callable\",\"test_player\"],\"救灾\":[\"callable\",\"test_player\"],\"救\":[\"callable\",\"test_player\"],\"给\":[\"callable\",\"test_player\"]}', NULL, NULL, NULL, '人类', 'xian', '', 'male', 100, 'peaceful', 800, 100, 800, 100, 800, 100, 100, 10, 10, 10, 100, 100, 10, 200000, 100, 0, 0, 0, 100, 1000, 100, 100, 100, 100, 1000, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (332, 'shan', '圣善', '大法师', '一位身披仙袍，面容严肃慈善的大法师。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃禹王台也，水陆大会将不期举行，本法师在此预做法场以祭祖求贤。\",\"name\":\"圣善法师，在此做法祭祖求贤。\",\"ask\":[\"callable\",\"test_player\"],\"祭祖\":[\"callable\",\"test_player\"],\"求贤\":[\"callable\",\"test_player\"],\"招贤\":[\"callable\",\"test_player\"],\"贤人\":[\"callable\",\"test_player\"],\"贤士\":[\"callable\",\"test_player\"],\"善哉\":[\"callable\",\"test_player\"],\"招\":[\"callable\",\"test_player\"],\"求\":[\"callable\",\"test_player\"]}', '[\"圣善法师说道：善哉善哉哪。\",\"圣善法师自语道：世上贤人，有求必应哪。\",\"圣善法师说道：祭祖求贤，乃水陆大会前之必需也。\",\"圣善法师叹言道：天下招贤，利国利民之大策也。\",\"圣善法师说道：八方求贤也。\",\"圣善法师说道：焚香祭祖，以招天下招贤士。\"]', NULL, NULL, '人类', 'xian', '', 'male', 40, 'peaceful', 800, 100, 800, 100, 800, 100, 100, 10, 10, 10, 100, 100, 10, 200000, 100, 0, 0, 0, 100, 1000, 100, 100, 100, 100, 1000, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 10, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (333, 'zhi', '圣志', '大法师', '一位身披仙袍，面容严肃慈善的大法师。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃禹王台也，水陆大会将不期举行，本法师在此预做法场，杀尽妖魔鬼怪！\",\"name\":\"圣志法师，在此做法，以杀尽妖魔鬼怪！\",\"kill\":[\"callable\",\"test_player\"],\"妖魔\":[\"callable\",\"test_player\"],\"妖贼\":[\"callable\",\"test_player\"],\"鬼怪\":[\"callable\",\"test_player\"],\"牛鬼\":[\"callable\",\"test_player\"],\"蛇神\":[\"callable\",\"test_player\"],\"杀尽\":[\"callable\",\"test_player\"],\"杀\":[\"callable\",\"test_player\"],\"斩\":[\"callable\",\"test_player\"]}', '[\"圣志法师怒发冲冠，将惊堂木啪地一拍，喝道：杀！\",\"圣志法师怒道：杀尽天下妖魔鬼怪！\",\"圣志法师拍着惊堂木吼道：妖贼！\",\"圣志法师怒不可遏：斩尽杀绝！\",\"圣志法师哼了一声：杀！\",\"圣志法师说道：要扫除一切牛鬼蛇神！\"]', NULL, NULL, '人类', 'xian', '', 'male', 25, 'peaceful', 800, 100, 800, 100, 800, 100, 100, 10, 10, 10, 100, 100, 10, 200000, 100, 0, 0, 0, 100, 1000, 100, 100, 100, 100, 1000, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 10, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (334, 'd', '广筠子', '', '方寸山三星洞第二代弟子中的杰出人物．', 1, 'lingtai', '首徒', '{\"combat_exp_min\": 10000}', '[\"很好，\"]', NULL, '[\"广筠子四下打量了一番。\",\"广筠子沉思片刻，若有所悟。\",\"广筠子叹道：天道苍茫，修行无尽啊。\",\"广筠子喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '人类', 'xian', '', 'male', 45, 'friendly', 400, 100, 500, 100, 400, 100, 100, 10, 10, 10, 100, 100, 10, 160000, 200000, 0, 0, 0, 450, 300, 10, 100, 100, 450, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 11, 0, NULL, 10, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (335, 'guangxi', '广羲子', '经阁总管', '一个看起来慈眉善目的道士，正拿着一本经书读着．', 1, 'lingtai', '弟子', NULL, NULL, '{\"book\":\"这里大多是我们道教经典，也有些平常书籍。\",\"千字文\":[\"callable\",\"borrow_me\"],\"道德经\":[\"callable\",\"borr_me\"]}', '[\"广羲子笑道：我这人最爱吃松果了！\"]', NULL, NULL, 'human', 'toaist', '方寸山三星洞', 'male', 53, 'friendly', 100, 100, 800, 800, 800, 800, 25, 10, 10, 10, 10, 10, 30, 180000, 250000, 60000, 250, 0, 400, 400, 40, 100, 100, 400, 400, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/jingge', 'lingtai/jingge', NULL, 5, 0, NULL, 10, 1, '2026-08-16 09:33:54', NULL, 0, 0, 0, NULL);
