INSERT INTO `npcs` VALUES (337, 'huigang', '慧纲', '道长', '一个相貌堂堂的道士．', 1, NULL, NULL, NULL, NULL, NULL, '[\"慧纲四下打量了一番。\",\"慧纲沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 33, 'peaceful', 200, 200, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 30, 40000, 60000, 0, 0, 0, 450, 300, 5, 100, 100, 200, 200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/inside7', 'lingtai/inside7', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:37:54', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (338, 'huiliu', '慧琉', '道长', '一个相貌堂堂的道士．', 1, NULL, NULL, NULL, NULL, NULL, '[\"慧琉四下打量了一番。\",\"慧琉沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 33, 'peaceful', 100, 100, 500, 500, 300, 300, 10, 10, 10, 10, 10, 10, 30, 45000, 60000, 0, 0, 0, 450, 300, 5, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/inside7', 'lingtai/inside7', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:10:08', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (339, 'kancai', '砍柴道士', NULL, '一位道长，想是山中道观里的。', 0, NULL, NULL, NULL, NULL, NULL, '[\"只听砍柴道士唱道：云际依依认旧林，断崖荒草路难寻。\",\"砍柴道士唱道：西山望见朝来雨，南涧归时渡处深。\",\"砍柴道士唱道：观棋柯烂，伐木丁丁，云边谷口徐行，卖薪沽酒，狂笑自陶情。\",\"砍柴道士低声唱道：相逢处，非仙即道，静坐讲黄庭。\"]', NULL, NULL, 'human', 'taoist', NULL, 'male', 35, 'peaceful', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 30, 10000, 20000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 50, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/lantao', 'lingtai/lantao', NULL, 5, 0, NULL, 0, 1, '2026-08-07 21:56:26', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (341, 'oldwolf', '老狼', NULL, '一只浑身脏兮兮的老狼，一双眼睛正恶狠狠地瞪著你。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', NULL, NULL, 'male', 20, 'aggressive', 100, 100, 300, 300, 200, 200, 20, 10, 10, 10, 30, 10, 10, 10000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 1, 1, 0, NULL, 'lingtai', 'lingtai/cave1', 'lingtai/cave1', NULL, 0, 0, NULL, 50, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (342, 'puti', '菩提祖师', '斜月三星', '大觉金仙没垢姿，西方妙相祖菩提', 1, 'lingtai', '斜月三星', '{\"skills\": {\"dao\": 120}, \"int_min\": 35, \"daoxing_min\": 350000}', '{\"int\": \"资质太钝，再加修行也无法成道为仙。\", \"skill\": \"习我的法术方才初成，火候不到，也非真学问。\", \"daoxing\": \"道行尚浅，好自修为，他日再来。\"}', '{\"name\":\"在下菩提祖师。\",\"here\":\"这里是灵台方寸山，修仙问道之所。\",\"修仙\":\"修行之道，在于持之以恒，切莫急功近利。\",\"妖魔\":\"如今妖魔横行，我辈当以除魔卫道为己任。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"菩提祖师四下打量了一番。\",\"菩提祖师沉思片刻，若有所悟。\",\"菩提祖师叹道：天道苍茫，修行无尽啊。\",\"菩提祖师喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 100, 'friendly', 1000, 1000, 5000, 5000, 5000, 5000, 10, 30, 10, 10, 10, 10, 26, 3000000, 5000000, 0, 0, 0, 5000, 2500, 150, 100, 100, 5000, 2500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/room', 'lingtai/room', NULL, 0, 60, '[\"light\",\"dingshen\",\"thunder\"]', 20, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (344, 'shixong', '皤不分', NULL, '一个胖乎乎的道士，正傻呵呵的不知笑什么．', 0, NULL, NULL, NULL, NULL, '{\"笑什么\":\"师父刚教我一招移行换位，嘻嘻．．．\",\"移行换位\":\"听师父说可以把人传到远处，你想试试看？\",\"试试\":[\"callable\",\"try_me\"]}', '[\"皤不分四下打量了一番。\",\"皤不分沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'taoist', NULL, 'male', 33, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 5000, 10000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/inside6', 'lingtai/inside6', NULL, 10, 50, NULL, 0, 1, '2026-08-16 09:02:07', NULL, 0, 0, 0, NULL);
