INSERT INTO `npcs` VALUES (346, 'xiao', '小道士', '振远镖局总镖头', '一个小道士，正跟着师父练武．', 0, NULL, NULL, NULL, NULL, NULL, '[\"云霄打了个喷嚏．\",\"云霄上上下下打量了你几眼。\",\"云霄哼了一声。\"]', NULL, NULL, '人类', '', '', 'male', 26, 'peaceful', 100, 100, 100, 100, 100, 100, 100, 10, 10, 10, 100, 100, 10, 30, 100, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, NULL, 'lingtai', 'lingtai/inside2', 'lingtai/inside2', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:42:18', NULL, 0, 0, 0, NULL);
