INSERT INTO `npcs` VALUES (350, 'yunjing', '云静', NULL, '方寸山三星洞第三代弟子中的杰出人物．', 1, 'lingtai', '弟子', NULL, '[\"很好，\"]', NULL, '[\"云静四下打量了一番。\",\"云静沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 33, 'peaceful', 500, 500, 500, 500, 500, 500, 10, 25, 10, 10, 10, 10, 30, 70000, 100000, 30000, 200, 0, 450, 300, 10, 100, 100, 450, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/inside3', 'lingtai/inside3', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:03:48', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (351, 'yunqing', '云清', NULL, '方寸山三星洞第三代弟子中的杰出人物．虽不是很聪明，但师祖却很看重他．', 1, 'lingtai', '弟子', NULL, '[\"很好，\"]', NULL, '[\"云清四下打量了一番。\",\"云清沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 33, 'peaceful', 400, 400, 400, 400, 400, 400, 30, 25, 10, 10, 10, 10, 30, 80000, 100000, 30000, 200, 0, 450, 300, 10, 100, 100, 450, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/inside6', 'lingtai/inside6', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:34:28', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (352, 'yunxiao', '云霄', NULL, '方寸山三星洞第三代弟子中的杰出人物。在场边转来转去发些牢骚。', 1, 'lingtai', '弟子', NULL, NULL, NULL, '[\"云霄打了个喷嚏．\",\"云霄上上下下打量了你几眼。\",\"云霄哼了一声。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 33, 'peaceful', 500, 500, 500, 500, 500, 500, 30, 25, 10, 10, 10, 10, 30, 80000, 100000, 0, 0, 0, 450, 300, 20, 100, 100, 450, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/yunxiao', 'lingtai/yunxiao', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:14:08', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (353, 'yunyang', '云阳真人', '小天师', '云阳真人与菩提祖师实是半师半友，也是三星洞内外总管．因其壮年时降魔除妖无数，人称「小天师」．', 1, 'lingtai', '小天师', '{\"daoxing_min\": 100000}', '{\"daoxing\": \"你的道行还不够，多加修炼吧。\"}', '{\"下山\":[\"callable\",\"expell_me\"],\"leave\":[\"callable\",\"expell_me\"]}', '[\"云阳真人四下打量了一番。\",\"云阳真人沉思片刻，若有所悟。\",\"云阳真人叹道：天道苍茫，修行无尽啊。\",\"云阳真人喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'taoist', '方寸山三星洞', 'male', 70, 'friendly', 1100, 1100, 1100, 1100, 1100, 1100, 30, 30, 10, 10, 10, 30, 30, 800000, 1500000, 250000, 400, 0, 2300, 1200, 80, 100, 100, 2300, 1200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'lingtai', 'lingtai/jingtang', 'lingtai/jingtang', NULL, 0, 40, '[\"light\",\"dingshen\",\"thunder\"]', 13, 1, '2026-06-16 06:03:48', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (354, 'zhangdaoling', '张道陵', '天师', '张道陵乃是天上的天师，此刻偷闲在山边观观景色。', 1, 'lingtai', '蓝', '{\"family_required\": \"方寸山三星洞\"}', '[\"RANK_D->query_respect(ob) + 已是身处名门，还需多加努力才是，怎可又投我门下？\\\\n\", \"老夫不收外门弟子，却可指点你一条明路，这山上有个老神仙，法力无边，你投奔他去吧！\\\\n\"]', '{\"name\":\"在下张道陵。\",\"here\":\"这里是灵台方寸山，修仙问道之所。\",\"修仙\":\"修行之道，在于持之以恒，切莫急功近利。\",\"妖魔\":\"如今妖魔横行，我辈当以除魔卫道为己任。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"张道陵四下打量了一番。\",\"张道陵沉思片刻，若有所悟。\",\"张道陵叹道：天道苍茫，修行无尽啊。\",\"张道陵喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'taoist', '逍遥派', 'male', 60, 'peaceful', 1000, 1000, 1000, 1000, 1000, 1000, 25, 30, 10, 10, 10, 10, 30, 800000, 1000000, 250000, 400, 0, 800, 800, 40, 100, 100, 1900, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'lingtai', 'lingtai/guanjin', 'lingtai/guanjin', NULL, 0, 10, NULL, 0, 1, '2026-06-16 06:07:20', NULL, 0, 0, 0, NULL);
