INSERT INTO `npcs` VALUES (375, 'change', '嫦娥', '月宫主人', '西王母的大弟子。早年因帮助丈夫盗取西王母之灵药而与其师势成水火。后得和解并邀西王母出掌月宫一门。', 1, 'moon', '广寒仙子', '{\"gender\": \"女性\", \"per_min\": 20, \"daoxing_min\": 150000}', '{\"per\": \"容貌不够出众，不适合月宫修行。\", \"gender\": \"我们月宫只收女徒，这位还是另请高就吧。\", \"daoxing\": \"道行不足，还需继续修炼。\"}', '{\"name\":\"在下嫦娥。\",\"here\":\"这里是月宫，仙雾缭绕，不同凡间。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"嫦娥四下打量了一番。\",\"嫦娥沉思片刻，若有所悟。\",\"嫦娥叹道：天道苍茫，修行无尽啊。\",\"嫦娥喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 20, 'friendly', 600, 600, 900, 900, 800, 800, 10, 30, 10, 10, 10, 10, 30, 400000, 800000, 200000, 350, 0, 800, 800, 50, 100, 100, 600, 600, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'moon', 'moon/change_room', 'moon/change_room', NULL, 0, 0, NULL, 11, 1, '2026-06-16 06:11:08', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (376, 'chimeng', '痴梦仙姑', '迷津渡者', '此乃迷津痴梦仙姑也；不受金银之谢，但遇有缘者渡之！', 1, 'moon', '痴梦', '{\"special\": \"fate\"}', '{\"special\": \"你我无缘，请回吧。\"}', '{\"name\":\"在下痴梦仙姑。\",\"here\":\"这里是月宫，仙雾缭绕，不同凡间。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"痴梦仙姑四下打量了一番。\",\"痴梦仙姑沉思片刻，若有所悟。\",\"痴梦仙姑叹道：天道苍茫，修行无尽啊。\",\"痴梦仙姑喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 1000, 1000, 1000, 1000, 1000, 1000, 10, 30, 10, 10, 10, 10, 30, 1000000, 500000, 100000, 300, 0, 800, 800, 50, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/lotuspond', 'moon/lotuspond', NULL, 0, 0, NULL, 11, 1, '2026-06-16 06:10:12', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (377, 'fairy', '蝶衣', '月宫舞仙', '其仙袂乍飘兮，闻麝兰之馥郁；荷花欲动兮，听环佩之铿锵。靥笑春桃兮，云髻堆翠；唇绽樱颗兮，榴齿含香。纤腰之楚兮，若风回雪舞', 1, 'moon', '弟子', NULL, NULL, NULL, '[\"蝶衣四下打量了一番。\",\"蝶衣沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 600, 600, 800, 800, 600, 600, 10, 30, 10, 10, 10, 10, 30, 100000, 50000, 0, 0, 0, 600, 600, 40, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/wulang', 'moon/wulang', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:07:20', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (378, 'fairy1', '菊影', '月宫舞仙', '翩若惊鸿，婉若游龙，荣曜秋菊，华茂春松。仿佛兮若轻云之蔽月，飘摇兮若流风之回雪。远而望之，皎若太阳升朝霞。迫而察之，灼若芙渠出绿波。', 1, 'moon', '弟子', NULL, NULL, NULL, '[\"菊影四下打量了一番。\",\"菊影沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 600, 600, 800, 800, 600, 600, 10, 30, 10, 10, 10, 10, 30, 100000, 50000, 0, 0, 0, 600, 600, 40, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/wulang', 'moon/wulang', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:11:08', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (379, 'fairy2', '茗烟', '月宫伺女', '其珠翠之辉辉兮，满额鹅黄。出没花间兮，宜嗔宜喜；徘徊池上兮，若飞若扬。蛾眉颦笑兮，将言而未语；莲步乍移兮，欲止而欲行。', 1, 'moon', '弟子', NULL, NULL, NULL, '[\"茗烟四下打量了一番。\",\"茗烟沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 600, 600, 800, 800, 600, 600, 10, 30, 10, 10, 10, 10, 30, 100000, 50000, 0, 0, 0, 600, 600, 40, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/ghg_zhengdian', 'moon/ghg_zhengdian', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:10:36', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (380, 'fairy3', '抱琴', '月宫伺女', '其仿佛兮若轻云之蔽月，飘摇兮若流风之回雪。远而望之，皎若太阳升朝霞。迫而察之，灼若芙渠出绿波。', 1, 'moon', '弟子', NULL, NULL, NULL, '[\"抱琴四下打量了一番。\",\"抱琴沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 600, 600, 800, 800, 600, 600, 10, 30, 10, 10, 10, 10, 30, 100000, 50000, 0, 0, 0, 600, 600, 40, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/ghg_zhengdian', 'moon/ghg_zhengdian', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:17:06', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (381, 'fairy4', '锄药', '月宫伺女', '其披罗衣之璀粲兮，珥瑶碧之华琚。戴金翠之首饰，缀明珠以耀躯。践远游之文履，曳雾绡之轻裾。微幽兰之芳蔼兮，步踟蹰于山隅。', 1, 'moon', '弟子', NULL, NULL, NULL, '[\"锄药四下打量了一番。\",\"锄药沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 600, 600, 800, 800, 600, 600, 10, 30, 10, 10, 10, 10, 30, 100000, 50000, 0, 0, 0, 600, 600, 40, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/huilang1', 'moon/huilang1', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:05:34', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (382, 'fairy5', '扫红', '月宫伺女', '披罗衣之璀粲兮，珥瑶碧之华琚。戴金翠之首饰，缀明珠以耀躯。践远游之文履，曳雾绡之轻裾。微幽兰之芳蔼兮，步踟蹰于山隅。', 1, 'moon', '弟子', NULL, NULL, NULL, '[\"扫红四下打量了一番。\",\"扫红沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 600, 600, 800, 800, 600, 600, 10, 30, 10, 10, 10, 10, 30, 100000, 50000, 0, 0, 0, 600, 600, 40, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/courtyard', 'moon/courtyard', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:18:44', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (383, 'fairy6', '痴梦仙姑', '迷津渡者', '此乃迷津痴梦仙姑也；不受金银之谢，但遇有缘者渡之！', 1, 'moon', '弟子', '{\"gender\": \"女性\"}', '[\"我们月宫只收女徒，这位\", \"你我无缘，还是另请高就吧。\\\\n\", \"好，希望\"]', NULL, '[\"痴梦仙姑四下打量了一番。\",\"痴梦仙姑沉思片刻，若有所悟。\",\"痴梦仙姑叹道：天道苍茫，修行无尽啊。\",\"痴梦仙姑喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 18, 'friendly', 1000, 1000, 1000, 1000, 1000, 1000, 10, 30, 10, 10, 10, 10, 30, 300000, 150000, 0, 0, 0, 800, 600, 50, 100, 100, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/fairy6', 'moon/fairy6', NULL, 0, 0, NULL, 10, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (385, 'jftou', '轿夫头', NULL, NULL, 0, NULL, NULL, NULL, NULL, '{\"name\":\"小的是这帮人的头儿，生意上的事儿，小的一手负责，您有何吩咐？\",\"here\":\"这儿向东去就是月老亭了，所有的婚姻都在那儿办理，所以这儿的生意好极了。\",\"婚礼\":\"呵呵，小的就负责这个，瞧，花轿，轿夫，吹鼓手，一应俱全，包您满意。您要不要风光风光？\",\"价钱\":\"花轿加轿夫，一百两银子。要是加吹鼓手，另加一百两。现钱交易，先付银子。\"}', NULL, NULL, '[{\"type\":\"accept_object\",\"accepted_items\":[\"coin\"],\"response_message\":\"\\u8f7f\\u592b\\u5934\\u6536\\u4e0b\\u4e86\\u4f60\\u7684\\u94b1\\u3002\"}]', 'human', NULL, NULL, 'male', 30, 'peaceful', 100, 100, 600, 600, 100, 100, 80, 10, 10, 10, 10, 10, 10, 10000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'moon', 'moon/yltw', 'moon/yltw', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (387, 'lgshou', '锣鼓手', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 30, 'peaceful', 100, 100, 500, 500, 100, 100, 50, 10, 10, 10, 10, 10, 10, 10000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'moon', 'moon/yltw', 'moon/yltw', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (389, 'rabbit', '玉兔', '', '玉兔仙原本只是嫦娥的宠物，因吃了嫦娥掉在地上的灵药而成人形。玉兔因灵药之事被王母罚去捣药，久而久之竟颇通药道。', 1, 'moon', '弟子', '{\"gender\": \"女性\"}', '[\"我们月宫只收女徒，这位\", \"好，希望\"]', NULL, '[\"玉兔四下打量了一番。\",\"玉兔沉思片刻，若有所悟。\",\"玉兔叹道：天道苍茫，修行无尽啊。\",\"玉兔喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '人类', 'xian', '', 'female', 20, 'friendly', 500, 100, 500, 100, 800, 100, 100, 10, 10, 10, 100, 100, 10, 200000, 200000, 0, 0, 0, 800, 800, 50, 100, 100, 600, 600, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 10, 4, '[\"玉兔越打越高兴，口中连呼：“好玩，好玩！再打，再打！”\"]', 10, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (390, 'snshou', '唢呐手', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'male', 30, 'peaceful', 100, 100, 500, 500, 100, 100, 50, 10, 10, 10, 10, 10, 10, 10000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'moon', 'moon/yltw', 'moon/yltw', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (391, 'wugang', '吴刚', NULL, '一个气宇不凡的大汉．', 0, NULL, NULL, NULL, NULL, NULL, '[\"吴刚四下打量了一番。\",\"吴刚沉思片刻，若有所悟。\",\"吴刚叹道：天道苍茫，修行无尽啊。\",\"吴刚喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 35, 'peaceful', 200, 200, 500, 500, 300, 300, 10, 10, 10, 10, 10, 10, 27, 100000, 300000, 40000, 200, 0, 450, 300, 15, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/ontop2', 'moon/ontop2', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:11:58', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (392, 'xiwangmu', '西王母', '月宫祖师', '西华至妙生伊川，穆王八骑访昆仑。', 1, 'moon', '瑶池金母', '{\"gender\": \"女性\", \"daoxing_min\": 500000}', '{\"gender\": \"我们月宫只收女徒，这位还是另请高就吧。\", \"daoxing\": \"百年道行方有资格入我月宫，你道行尚浅。\"}', '{\"pantao\":[\"callable\",\"ask_pantao\"],\"蟠桃园\":[\"callable\",\"ask_pantao\"]}', '[\"西王母四下打量了一番。\",\"西王母沉思片刻，若有所悟。\",\"西王母叹道：天道苍茫，修行无尽啊。\",\"西王母喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 100, 'friendly', 800, 800, 4500, 4500, 4500, 4500, 10, 10, 10, 10, 30, 10, 30, 2000000, 5000000, 0, 0, 0, 4000, 2000, 125, 100, 100, 4000, 2000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/wangmu_room', 'moon/wangmu_room', NULL, 0, 50, '[\"arrow\",\"mihun\",\"shiyue\"]', 20, 1, '2026-06-16 05:19:34', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (394, 'yuelao', '月下老人', NULL, '他就是专管天上地下姻缘的月下老人了。他满脸红光，须眉皆白，正坐在那儿翻看一本书，手上黏着一根红绳，口中正自言自语着些什么。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"区区正是月老，在此负责天上地下所有的姻缘，已有不知道多少年了。\",\"here\":\"这儿就是我办公的地方，所有的姻缘都是我在这儿偷偷牵的线，也是在这儿注册完婚的。\",\"结婚\":\"想结婚？你要找到你命中注定的那姻缘，然后一起到这里来登记(jiehun)完婚。\",\"登记\":\"想结婚？你要找到你命中注定的那姻缘，然后一起到这里来登记(register)完婚。\",\"离婚\":\"唉，世道变了，这年头人心不古，离婚率高得可怕。唉，不管怎样，我也负责处理离婚(divorce/lihun)申请。\",\"做媒\":\"媒人是结婚必不可少的证人，做媒(zuomei)的负责给女方做证。\"}', '[\"月下老人四下打量了一番。\",\"月下老人沉思片刻，若有所悟。\",\"月下老人叹道：天道苍茫，修行无尽啊。\",\"月下老人喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 101, 'friendly', 1000, 1000, 1200, 1200, 1200, 1200, 30, 30, 30, 10, 10, 10, 100, 500000, 5000000, 0, 0, 0, 1000, 1000, 0, 100, 100, 1200, 1200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/ylt', 'moon/ylt', NULL, 0, 0, NULL, 20, 1, '2026-06-16 06:07:20', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (395, 'yuenu', '月奴', '桂花仙', '她乃是桂树采天地之精华化成，后拜嫦娥为师．', 1, 'moon', '月宫侍女', '{\"gender\": \"女性\"}', '{\"gender\": \"我们月宫只收女徒，这位还是另请高就吧。\"}', NULL, '[\"月奴四下打量了一番。\",\"月奴沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'xian', '月宫', 'female', 20, 'friendly', 500, 500, 500, 500, 500, 500, 10, 30, 10, 10, 10, 10, 30, 200000, 100000, 70000, 260, 0, 500, 500, 20, 100, 100, 300, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'moon', 'moon/xiaoyuan', 'moon/xiaoyuan', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:13:46', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (396, 'yutu', '玉兔', NULL, '一只活泼可爱的小白兔，红眼睛，三瓣嘴，两只耳朵长乎乎。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', NULL, NULL, 'female', 10, 'friendly', 100, 100, 2000, 2000, 1000, 1000, 10, 10, 10, 10, 40, 30, 999, 300, 300, 0, 0, 0, 0, 0, 0, 100, 100, 0, 500, 0, 0, 0, 0, 1, 0, NULL, 'moon', 'moon/ontop2', 'moon/ontop2', NULL, 3, 4, '[\"玉兔越打越高兴，口中连呼：“好玩，好玩！再打，再打！”\"]', 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (399, 'bonze', '和尚', NULL, NULL, 1, 'nanhai', '弟子', NULL, '[\"很好，贫僧就收下你，希望你多加努力，早成正果。\\\\n\"]', NULL, '[\"和尚四下打量了一番。\",\"和尚沉思片刻，若有所悟。\",\"和尚叹道：天道苍茫，修行无尽啊。\",\"和尚喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'bonze', '南海普陀山', 'male', 30, 'peaceful', 600, 600, 600, 600, 600, 600, 10, 10, 10, 10, 10, 10, 10, 100000, 200000, 35000, 200, 0, 300, 300, 20, 100, 100, 300, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/zhuque-s2', 'city/zhuque-s2', NULL, 5, 0, NULL, 0, 1, '2026-08-16 09:14:08', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (400, 'guanyin', '观音菩萨', '救苦救难大慈大悲', '理圆四德，智满金身。眉如小月，眼似双星。兰心欣紫竹，蕙性爱得藤。她就是落伽山上慈悲主，潮音洞里活观音。', 1, 'nanhai', '大慈大悲', '{\"skills\": {\"buddhism\": 100}, \"spi_min\": 35, \"daoxing_min\": 400000}', '{\"spi\": \"心性不够，需要潜心修行佛法。\", \"skill\": \"佛法修为不够，多诵经念佛再来。\", \"daoxing\": \"你的修为尚浅，还需继续修行。\"}', '{\"name\":\"在下观音菩萨。\",\"here\":\"这里是南海，观世音菩萨的道场。\",\"修仙\":\"修行之道，在于持之以恒，切莫急功近利。\",\"妖魔\":\"如今妖魔横行，我辈当以除魔卫道为己任。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"观音菩萨四下打量了一番。\",\"观音菩萨沉思片刻，若有所悟。\",\"观音菩萨叹道：天道苍茫，修行无尽啊。\",\"观音菩萨喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'bonze', '南海普陀山', 'female', 35, 'peaceful', 5000, 5000, 5000, 5000, 5000, 5000, 24, 10, 10, 10, 10, 10, 100, 2000000, 10000000, 0, 0, 0, 4000, 2000, 145, 100, 100, 6000, 3000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"immortal_pill\",\"name\":\"九转仙丹\",\"chance\":5,\"min\":1,\"max\":2},{\"item_id\":\"heavenly_weapon\",\"name\":\"天兵利器\",\"chance\":3,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":80,\"min\":50,\"max\":200}]', 'nanhai', 'nanhai/chaoyindong', 'nanhai/chaoyindong', NULL, 0, 80, '[\"bighammer\"]', 0, 1, '2026-06-16 06:13:46', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (402, 'huian', '惠岸行者', '观音首徒', '李天王二太子木叉，南海观音大徒弟惠岸行者。', 1, 'nanhai', '弟子', '{\"skills\": {\"buddhism\": 60}, \"class_required\": \"bonze\"}', '[\"很好，贫僧就收下你，希望你多加努力，早成正果。\\\\n\"]', '{\"dadang\":[\"callable\",\"ask_for_partner\"],\"partner\":[\"callable\",\"ask_for_partner\"],\"搭档\":[\"callable\",\"ask_for_partner\"]}', '[\"惠岸行者四下打量了一番。\",\"惠岸行者沉思片刻，若有所悟。\",\"惠岸行者叹道：天道苍茫，修行无尽啊。\",\"惠岸行者喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'bonze', '南海普陀山', 'male', 25, 'peaceful', 600, 600, 1000, 1000, 1000, 1000, 10, 10, 10, 10, 10, 10, 10, 750000, 1000000, 150000, 300, 0, 2000, 1000, 75, 100, 100, 2000, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'nanhai', 'nanhai/guangchang', 'nanhai/guangchang', NULL, 0, 40, '[\"bighammer\",\"jingang\"]', 0, 1, '2026-06-16 06:10:36', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (403, 'master', '玄智和尚', NULL, NULL, 1, 'nanhai', '住持', NULL, '[\"慢著，一个一个来。\", \"老纳今天已经收了十个弟子，不想再收徒了。\"]', '{\"剃度\":[\"callable\",\"ask_for_join\"],\"出家\":[\"callable\",\"ask_for_join\"]}', '[\"玄智和尚四下打量了一番。\",\"玄智和尚沉思片刻，若有所悟。\",\"玄智和尚叹道：天道苍茫，修行无尽啊。\",\"玄智和尚喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'bonze', '山烟寺', 'male', 74, 'peaceful', 100, 100, 100, 100, 100, 100, 17, 30, 30, 10, 20, 30, 10, 1000000, 1000000, 0, 0, 0, 1500, 1500, 5, 2000, 2000, 600, 600, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'nanhai', 'nanhai/master', 'nanhai/master', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
