INSERT INTO `npcs` VALUES (408, 'zhangchan', '掌禅僧', NULL, NULL, 1, NULL, NULL, NULL, NULL, '{\"兵器\":\"你想要什么兵器？\",\"铁杖\":[\"callable\",\"ask_staff\"],\"铁枪\":[\"callable\",\"ask_spear\"]}', '[\"掌禅僧四下打量了一番。\",\"掌禅僧沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'bonze', '南海普陀山', 'male', 35, 'peaceful', 250, 250, 250, 250, 250, 250, 10, 10, 10, 10, 10, 10, 10, 10000, 60000, 0, 0, 0, 200, 200, 20, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'nanhai', 'nanhai/chanfang', 'nanhai/chanfang', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:06:10', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (409, 'zhangchu', '掌厨僧', NULL, NULL, 1, NULL, NULL, NULL, NULL, '{\"云南白药\":[\"callable\",\"ask_yao\"],\"灵丹\":[\"callable\",\"ask_dan\"]}', '[\"掌厨僧四下打量了一番。\",\"掌厨僧沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'bonze', '南海普陀山', 'male', 25, 'peaceful', 200, 200, 200, 200, 200, 200, 10, 10, 10, 10, 10, 10, 10, 5000, 10000, 0, 0, 0, 100, 100, 10, 100, 100, 100, 100, 0, 20, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'nanhai', 'nanhai/zoulang2', 'nanhai/zoulang2', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:37:46', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (411, 'zhike', '知客僧', NULL, '一位年轻的僧人，脸上总是带着热情的笑容。他负责在此迎接前来参禅进香的客人。', 1, NULL, NULL, NULL, NULL, NULL, '[\"知客僧四下打量了一番。\",\"知客僧沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'bonze', '南海普陀山', 'male', 25, 'peaceful', 200, 200, 200, 200, 200, 200, 10, 10, 10, 10, 10, 10, 10, 5000, 10000, 0, 0, 0, 100, 100, 10, 100, 100, 100, 100, 0, 20, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'nanhai', 'nanhai/gate', 'nanhai/gate', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (412, '28star', '二十八星瓢虫小姐', '电信局接待员', '二十八星瓢虫小姐，俗称花大姐，喜欢在害虫们中间穿针引线。', 0, NULL, NULL, NULL, NULL, '{\"电信局\":\"是啊... 这里就是电信局，你要寄信吗？\",\"寄信\":[\"callable\",\"send_mail\"],\"收信\":[\"callable\",\"receive_mail\"],\"mail\":\"您讲的是外国话吧？我听不懂耶~~~~~~~~\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'female', 18, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 800, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 70, 0, 1, 0, NULL, 'ourhome', 'ourhome/postoffice', 'ourhome/postoffice', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (413, 'bigeye', '千里眼', '邮差', '前玉皇大帝亲信。因为偷看玉女出浴而被罚为邮差。他本来是和顺风耳一起呆在花果山仙石处的，后因嫌不够热闹跑到长安来了。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"连我你都不认识？大名鼎鼎的千里眼就是我。\",\"here\":\"鬼知道这是什么地方！我只负责收信发信。\",\"玉女\":\"嘿嘿．．．不错。就算砍头我也划算了。\",\"玉皇大帝\":\"你别提他！一提我就有气．．．只许州官放火，不许百姓点灯。\",\"发信\":[\"callable\",\"send_mail\"],\"收信\":[\"callable\",\"receive_mail\"],\"信件\":[\"callable\",\"receive_mail\"],\"信\":[\"callable\",\"receive_mail\"],\"mail\":[\"callable\",\"receive_mail\"],\"mailbox\":[\"callable\",\"receive_mail\"],\"小喇叭\":[\"callable\",\"send_dianbo\"]}', '[\"千里眼四下打量了一番。\",\"千里眼沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 30, 'friendly', 100, 100, 500, 500, 300, 300, 40, 10, 10, 10, 10, 10, 15, 8000, 100000, 0, 0, 0, 150, 300, 0, 100, 100, 0, 0, 0, 0, 70, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/kezhan', 'city/kezhan', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (417, 'longear', '顺风耳', '邮差', '前玉皇大帝亲信。因为偷听玉皇大帝跟嫦娥调情而被罚为邮差。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"连我你都不认识？大名鼎鼎的顺风耳就是我。\",\"here\":\"鬼知道这是什么地方！我只负责收信发信。\",\"嫦娥\":\"唉...可惜只闻其声未见其人。\",\"玉皇大帝\":\"你别提他！一提我就有气...只许州官放火，不许百姓点灯。\",\"发信\":[\"callable\",\"send_mail\"],\"收信\":[\"callable\",\"receive_mail\"],\"信件\":[\"callable\",\"receive_mail\"],\"信\":[\"callable\",\"receive_mail\"],\"mail\":\"您讲的是外国话吧？我听不懂耶~~~~~~~~\"}', '[\"顺风耳四下打量了一番。\",\"顺风耳沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 30, 'friendly', 100, 100, 500, 500, 300, 300, 10, 10, 10, 10, 10, 10, 15, 8000, 100000, 0, 0, 0, 150, 300, 0, 100, 100, 0, 0, 0, 0, 70, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'dntg', 'dntg/hgs/entrance', 'dntg/hgs/entrance', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
