INSERT INTO `npcs` VALUES (421, 'taibai', '太白金星', '长庚', '西方长庚太白金星。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"此乃瑶池蟠桃园七大天神殿，各路仙人圣贤天神年年聚此切磋神艺列榜封神，王母娘娘岁岁在此设蟠桃胜会宴请众仙神。\",\"?\":[\"callable\",\"execute_help\"],\"help\":[\"callable\",\"execute_help\"],\"蟠桃会\":[\"callable\",\"execute_ask\",\"pantaohui\"],\"封神榜\":[\"callable\",\"execute_ask\",\"fengshenbang\"],\"申请\":[\"callable\",\"execute_ask\",\"apply\"],\"御批\":[\"callable\",\"execute_ask\",\"approval\"],\"挑战\":[\"callable\",\"execute_ask\",\"challenge\"]}', '[\"太白金星四下打量了一番。\",\"太白金星沉思片刻，若有所悟。\",\"太白金星叹道：天道苍茫，修行无尽啊。\",\"太白金星喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 10000, 'friendly', 50000, 50000, 50000, 50000, 50000, 50000, 10, 10, 10, 10, 10, 10, 30, 10000000, 2000000, 0, 0, 0, 15000, 15000, 1000, 100, 100, 15000, 15000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'pantao', 'pantao/fengb', 'pantao/fengb', NULL, 3, 0, NULL, 0, 1, '2026-08-07 21:56:26', NULL, 0, 0, 0, NULL);
