INSERT INTO `npcs` VALUES (436, 'baihe', '白鹤', NULL, '一只黑腿丹顶浑身洁白的白鹤。', 0, NULL, NULL, NULL, NULL, NULL, '[\"白鹤四下打量了一番。\",\"白鹤沉思片刻，若有所悟。\",\"白鹤叹道：天道苍茫，修行无尽啊。\",\"白鹤喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '野兽', NULL, NULL, 'male', 30, 'friendly', 100, 100, 1000, 1000, 1000, 1000, 30, 30, 30, 30, 50, 10, 10, 800000, 800000, 0, 0, 0, 2000, 1000, 120, 100, 100, 2000, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'penglai', 'penglai/yashang', 'penglai/yashang', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (438, 'baiyuan', '白猿', NULL, '一只浑身长着寸许长白毛的老猿。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下白猿。\",\"here\":\"这里是蓬莱仙境，仙家福地。\",\"修仙\":\"修行之道，在于持之以恒，切莫急功近利。\",\"妖魔\":\"如今妖魔横行，我辈当以除魔卫道为己任。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"白猿四下打量了一番。\",\"白猿沉思片刻，若有所悟。\",\"白猿叹道：天道苍茫，修行无尽啊。\",\"白猿喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '野兽', NULL, NULL, 'male', 80, 'friendly', 100, 100, 1600, 1600, 1600, 1600, 30, 30, 30, 30, 50, 10, 10, 999000, 1200000, 0, 0, 0, 2000, 1000, 120, 100, 100, 2000, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'penglai', 'penglai/road1', 'penglai/road1', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:13:46', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (439, 'fuxing', '福星', '蓬莱三老', '霄汉中间一老人，手捧如意飞蔼绣。葫芦藏蓄万年丹，宝篆名书千纪寿。洞里乾坤任自由，壶中日月随成就。遨游四海任清闲，散淡十洲容福胄。曾赴蟠桃醉几遭，醒时名月还依旧。方面玉颜多神俊，三缕长苒飘颌边。', 1, 'wzg', '弟子', '{\"skills\": {\"taiyi\": 80}, \"family_required\": \"五庄观\"}', '[\"不敢当，不敢当。\\\\n\", \"呵呵，是\", \"好，有出息，这个徒弟我收下了。\\\\n\", \"我们仙家最看重仙法，你还得在这方面下苦功。\\\\n\", \"好，不过你还是先找八仙他们练一些入门的功夫吧。\\\\n\"]', '{\"碧藕\":\"我没那玩意，去问问老寿星吧！\",\"交梨\":\"我没那玩意，去问问老禄星吧！\",\"name\":\"老夫福星是也。\",\"here\":\"此乃蓬莱仙岛也。\",\"下棋\":\"你个臭棋篓子，谁要跟你下棋！\",\"围棋\":\"连围棋都不知道？\",\"火枣\":[\"callable\",\"ask_me\"]}', '[\"福星四下打量了一番。\",\"福星沉思片刻，若有所悟。\",\"福星叹道：天道苍茫，修行无尽啊。\",\"福星喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '五庄观', 'male', 70, 'peaceful', 100, 100, 1000, 1000, 1000, 1000, 30, 30, 30, 10, 30, 30, 100, 800000, 1500000, 0, 0, 0, 1000, 1000, 40, 100, 100, 600, 600, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'penglai', 'penglai/undertree', 'penglai/undertree', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:05:34', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (440, 'gm-tianwang', '魔礼红', '广目天王', '广目天王喜动不喜静，不愿在天上守门。玉帝便派他巡游四方，保卫众仙家安全。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '人类', 'xian', '', 'male', 40, 'peaceful', 100, 100, 1500, 100, 1000, 100, 30, 10, 10, 10, 100, 100, 10, 900000, 100, 0, 0, 0, 3000, 1500, 100, 100, 100, 3000, 1500, 0, 0, 0, 0, 1, 0, NULL, '', '', '', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (441, 'guangmu', '魔礼红', '广目天王', '广目天王喜动不喜静，不愿在天上守门。玉帝便派他巡游四方，保卫众仙家安全。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下广目天王魔礼红，奉圣谕把守东天门。\",\"here\":\"这里就是东天门, 入内就是天界了。\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 40, 'friendly', 100, 100, 900, 900, 900, 900, 30, 25, 10, 10, 10, 10, 10, 900000, 0, 0, 0, 0, 800, 800, 60, 100, 100, 600, 600, 0, 0, 0, 0, 1, 0, NULL, 'penglai', 'penglai/guangmu', 'penglai/guangmu', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (442, 'huaxian', '花仙', '', '', 0, NULL, NULL, NULL, NULL, '{\"花\":\"你陪我打架玩(fight)，把我哄高兴了，自然有你的好处。\",\"仙花\":\"你陪我打架玩(fight)，把我哄高兴了，自然有你的好处。\",\"flower\":\"你陪我打架玩(fight)，把我哄高兴了，自然有你的好处。\",\"hua\":\"你陪我打架玩(fight)，把我哄高兴了，自然有你的好处。\"}', '[\"huaxian四下打量了一番。\",\"huaxian沉思片刻，若有所悟。\"]', NULL, NULL, '人类', 'xian', '', 'male', 0, 'peaceful', 100, 100, 1000, 100, 1000, 100, 100, 10, 10, 10, 100, 100, 10, 10000, 10000, 0, 0, 0, 2000, 1000, 100, 100, 100, 4000, 4000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 14, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (443, 'laitou', '癞头和尚', NULL, '一位游方和尚，头上布满大大小小的伤疤。', 0, NULL, NULL, NULL, NULL, '{\"仙境\":\"海中有蓬莱，方丈，瀛洲三座仙岛，果是不凡！\",\"蓬莱\":\"我，我干吗要告诉你！\",\"方丈\":\"我，我干吗要告诉你！\",\"瀛洲\":\"我，我干吗要告诉你！\"}', '[\"癞头和尚不屑的说道：长安也不过如此景色吗，那里比得上仙境！\"]', NULL, NULL, 'human', 'bonze', NULL, 'male', 30, 'peaceful', 100, 100, 800, 800, 800, 800, 25, 30, 25, 10, 10, 10, 15, 20000, 30000, 0, 0, 0, 500, 500, 20, 100, 100, 400, 400, 0, 15, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/zhuque-s4', 'city/zhuque-s4', NULL, 5, 0, NULL, 0, 1, '2026-08-16 09:34:45', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (444, 'luxing', '禄星', '蓬莱三老', '霄汉中间一老人，手捧灵芝飞蔼绣。葫芦藏蓄万年丹，宝篆名书千纪寿。洞里乾坤任自由，壶中日月随成就。遨游四海任清闲，散淡十洲容福胄。曾赴蟠桃醉几遭，醒时名月还依旧。金面青髯胸前拂，荣禄无疆随缘帱。', 1, 'wzg', '弟子', '{\"skills\": {\"taiyi\": 80}, \"family_required\": \"五庄观\"}', '[\"不敢当，不敢当。\\\\n\", \"呵呵，是\", \"好，有出息，这个徒弟我收下了。\\\\n\", \"我们仙家最看重仙法，你还得在这方面下苦左5c。\\\\n\", \"好，不过你还是先找八仙他们练一些入门的功夫吧。\\\\n\"]', '{\"火枣\":\"我没那玩意，去问问老福星吧！\",\"碧藕\":\"我没那玩意，去问问老寿星吧！\",\"name\":\"老夫禄星是也。\",\"here\":\"此乃蓬莱仙岛也。\",\"下棋\":\"你个臭棋篓子，谁要跟你下棋！\",\"围棋\":\"连围棋都不知道？\",\"交梨\":[\"callable\",\"ask_me\"]}', '[\"禄星四下打量了一番。\",\"禄星沉思片刻，若有所悟。\",\"禄星叹道：天道苍茫，修行无尽啊。\",\"禄星喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '五庄观', 'male', 75, 'peaceful', 100, 100, 1000, 1000, 1000, 1000, 30, 30, 30, 10, 30, 30, 100, 820000, 1500000, 0, 0, 0, 800, 800, 40, 100, 100, 800, 800, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'penglai', 'penglai/undertree', 'penglai/undertree', NULL, 0, 0, NULL, 0, 1, '2026-06-16 05:19:34', NULL, 0, 0, 0, NULL);
