INSERT INTO `npcs` VALUES (483, 'longwang', '敖广', '东海龙王', '敖广是东海的龙王，其兄弟分别掌管东，西，南，北四海。由余其水族众多，声势浩大，俨然独霸一方。', 1, 'longgong', '东海龙王', '{\"skills\": {\"water\": 80}, \"con_min\": 30, \"daoxing_min\": 250000}', '{\"con\": \"体质太弱，承受不了海底的压力。\", \"skill\": \"水性太差，在龙宫如何修行？\", \"daoxing\": \"你的道行还不足以承受龙宫的修炼。\"}', '{\"离宫\":[\"callable\",\"expell_me\"],\"leave\":[\"callable\",\"expell_me\"],\"兵器\":[\"callable\",\"donghai_quest\"],\"weapon\":[\"callable\",\"donghai_quest\"]}', '[\"敖广四下打量了一番。\",\"敖广沉思片刻，若有所悟。\",\"敖广叹道：天道苍茫，修行无尽啊。\",\"敖广喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'dragon', '东海龙宫', 'male', 66, 'peaceful', 400, 400, 3000, 3000, 1500, 1500, 30, 10, 10, 10, 10, 10, 20, 1260000, 1500000, 0, 0, 0, 3000, 1500, 120, 100, 100, 1600, 800, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'sea', 'sea/inside3', 'sea/inside3', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
