INSERT INTO `npcs` VALUES (501, 'autumn-gongcao', '日值功曹', NULL, '四值功曹乃是托塔李天王帐前猛将。因经验不足而出战失利，被罚为巡逻官。四人因志同道合而结为金兰兄弟。日值功曹是老三，入天宫前在地府充当勾魂使者，所以他作战经验远在老大和老二之上。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下就是日值功曹，乃托塔天王帐前大将。\",\"here\":\"这里就是天宫。下官奉天王将令，在此巡查。\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 35, 'friendly', 100, 100, 1100, 1100, 800, 800, 28, 28, 10, 10, 10, 10, 10, 650000, 650000, 250000, 350, 0, 1200, 1000, 60, 100, 100, 1500, 1000, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/sky/tgqn8', 'dntg/sky/tgqn8', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (503, 'hg-tianwang', '魔礼寿', '护国天王', '护国天王身担着保护后宫安全的重担，非同小可。他的武功似乎属佛门一派，但除轮回杖法之外，护国天王还有另外的杀手绝招，但没有人知道是什么。也许正因为如此，玉皇才放心让他独担重任。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下就是持国天王，奉圣谕把守北天门。\",\"here\":\"这里就是北天门，里面是后宫禁地。\"}', NULL, NULL, NULL, 'human', 'xian', NULL, 'male', 43, 'friendly', 100, 100, 1200, 1200, 1100, 1100, 30, 37, 10, 10, 10, 10, 10, 1000000, 0, 450000, 450, 0, 2500, 1500, 70, 100, 100, 2500, 1500, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/sky/beitian', 'dntg/sky/beitian', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (510, 'spring-gongcao', '年值功曹', NULL, '四值功曹乃是托塔李天王帐前猛将。因经验不足而出战失利，被罚为巡逻官。四人因志同道合而结为金兰兄弟。年值功曹乃是大哥，一身道家功夫非同小可。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下就是年值功曹，乃托塔天王帐前大将。\",\"here\":\"这里就是天宫。下官奉天王将令，在此巡查。\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 41, 'friendly', 100, 100, 1100, 1100, 1000, 1000, 28, 25, 10, 10, 10, 10, 10, 580000, 580000, 220000, 350, 0, 1500, 1000, 60, 100, 100, 1700, 1000, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/sky/tgqs1', 'dntg/sky/tgqs1', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (511, 'summer-gongcao', '月值功曹', NULL, '四值功曹乃是托塔李天王帐前猛将。因经验不足而出战失利，被罚为巡逻官。四人因为志同道合结为金兰兄弟。月值功曹排行老二。他出师月宫，一手灵活的雪山剑法，且在百花掌上有极深的造旨。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下就是月值功曹，乃托塔天王帐前大将。\",\"here\":\"这里就是天宫。下官奉天王将令，在此巡查。\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 38, 'friendly', 100, 100, 1050, 1050, 900, 900, 20, 30, 10, 10, 10, 10, 10, 550000, 550000, 200000, 340, 0, 1500, 900, 60, 100, 100, 1450, 850, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/sky/tgqn1', 'dntg/sky/tgqn1', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
