INSERT INTO `npcs` VALUES (526, 'xiong', '熊山君', NULL, '雄豪多胆量，轻健夯身躯，涉水唯凶力，跑林逞怒威。向来符吉梦，今独露英姿，绿树能攀折，知寒善御时。准灵惟显处，故此号山君。', 0, NULL, NULL, NULL, NULL, NULL, '[\"熊山君四下打量了一番。\",\"熊山君沉思片刻，若有所悟。\",\"熊山君叹道：天道苍茫，修行无尽啊。\",\"熊山君喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 35, 'peaceful', 100, 100, 1300, 1300, 1300, 1300, 30, 10, 10, 10, 10, 10, 10, 490000, 300000, 0, 0, 0, 600, 600, 30, 100, 100, 600, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'westway', 'westway/lu3', 'westway/lu3', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:03:48', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (529, 'caishen', '赵公明', '财神爷', '财神爷赵公明，天下人无不想见的大名人。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', 'xian', NULL, 'male', 41, 'friendly', 200, 200, 500, 500, 300, 300, 30, 10, 10, 10, 10, 10, 10, 100000, 0, 0, 0, 0, 0, 300, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'wiz', 'wiz/caishen', 'wiz/caishen', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (530, 'dadi', '玉皇大帝', '天宫之主', '玉皇大帝。', 0, NULL, NULL, NULL, NULL, '{\"here\":\"这里就是我的灵霄宝殿\",\"name\":\"哪里来的妖仙，真不懂规矩！\",\"官职\":\"（官职相关的话题，需要深入探讨。）\",\"position\":\"（position相关的话题，需要深入探讨。）\",\"pantao\":\"（pantao相关的话题，需要深入探讨。）\",\"蟠桃园\":\"（蟠桃园相关的话题，需要深入探讨。）\"}', '[\"玉皇大帝四下打量了一番。\",\"玉皇大帝沉思片刻，若有所悟。\",\"玉皇大帝叹道：天道苍茫，修行无尽啊。\",\"玉皇大帝喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, '人类', 'xian', '', 'male', 50, 'friendly', 100, 100, 100, 100, 100, 100, 30, 10, 10, 10, 100, 100, 10, 5000000, 5000000, 0, 0, 0, 100, 100, 100, 100, 100, 100, 100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', '', '', '', NULL, 10, 0, NULL, 20, 1, NULL, NULL, 0, 0, 0, NULL);
