INSERT INTO `npcs` VALUES (537, 'dapeng', '大鹏明王', '雪山之祖', '这位大鹏明王的确大有来历，说起来跟佛祖如来也有点亲戚关系，算是如来的“舅舅”。他不似其兄孔雀明王作恶多端，却也并非善类，且因其兄之故跟佛门结下深仇。生平最讨厌的就是和尚。', 1, 'xueshan', '金翅大鹏', '{\"dex_min\": 30, \"str_min\": 35, \"daoxing_min\": 350000}', '{\"dex\": \"身法太差，跟不上大鹏展翅。\", \"str\": \"力量不够，在雪山活不下去。\", \"daoxing\": \"道行太浅，不配做我的弟子。\"}', NULL, '[\"大鹏明王四下打量了一番。\",\"大鹏明王沉思片刻，若有所悟。\",\"大鹏明王叹道：天道苍茫，修行无尽啊。\",\"大鹏明王喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'yaomo', '大雪山', 'male', 45, 'peaceful', 100, 100, 3500, 3500, 3500, 3500, 30, 10, 10, 10, 10, 10, 30, 1800000, 3000000, 0, 0, 0, 3500, 1800, 120, 100, 100, 4000, 2000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/dixiashi', 'xueshan/dixiashi', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (538, 'hama', '朱睛冰蟾', NULL, '一只大蟾蜍，通体雪白，眼珠却血也般红，模样甚是可爱，却也不见有何珍异之处。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', 'yaomo', NULL, 'male', 33, 'aggressive', 100, 100, 800, 800, 800, 800, 30, 10, 10, 10, 10, 10, 10, 0, 0, 0, 0, 0, 1000, 1000, 30, 100, 100, 1000, 500, 0, 0, 0, 1, 1, 0, NULL, 'xueshan', 'xueshan/hama', 'xueshan/hama', NULL, 0, 40, '[\"jieti\",\"juanbi\",\"tuntian\"]', 50, 1, NULL, NULL, 0, 0, 0, NULL);
