INSERT INTO `npcs` VALUES (548, 'shier', '黄雀侍儿', NULL, '孔雀公主的贴身侍卫头领。', 1, NULL, NULL, NULL, NULL, '{\"here\":\"这就是大雪山啦！\\\"}', '[\"shier四下打量了一番。\",\"shier沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'yaomo', '大雪山', 'female', 22, 'heroism', 100, 100, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 10, 35000, 35000, 0, 0, 0, 300, 300, 15, 100, 100, 300, 300, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/wuchang-w', 'xueshan/wuchang-w', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (550, 'wugong', '百足蜈蚣', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '野兽', NULL, NULL, 'male', 100, 'friendly', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 100, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, NULL, 'xueshan', 'xueshan/wugong', 'xueshan/wugong', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (551, 'wuya-guai', '乌鸦先生', NULL, '这位乌鸦先生来自遥远的大雪山。乃是大鹏明王座下有名的高手之一。他远看还不错，走近了才发现他长着长长的一张乌鸦嘴。', 1, 'xueshan', '弟子', '{\"family_required\": \"大雪山\"}', '[\"不敢，不敢。我该拜\", \"你这个\", \"你这个\", \"好，到我们大雪山来学艺，又找了个好师父，只要能活下来，\"]', '{\"name\":\"问什么问，张着眼睛是看的，长着脑袋是想的。\",\"here\":\"这就是我们大雪山。\",\"怎么去\":\"飞过去最快，走也能到。\",\"怎么走\":\"从这儿往北走。\",\"怎么飞\":[\"callable\",\"help_fly\"],\"大雪山\":[\"callable\",\"give_map\"]}', '[\"乌鸦先生四下打量了一番。\",\"乌鸦先生沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'yaomo', '大雪山', 'male', 43, 'peaceful', 100, 100, 700, 700, 600, 600, 10, 10, 10, 10, 10, 10, 112, 100000, 50000, 0, 150, 0, 700, 700, 35, 100, 100, 700, 700, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/xueshan2', 'xueshan/xueshan2', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (552, 'xiaozuanfeng', '小钻风', '大雪山巡山小妖', '去雪山路上的一个小妖，手里拿着铜锣正边走边吆喝。', 0, NULL, NULL, NULL, NULL, '{\"name\":[\"callable\",\"ask_name\"],\"here\":\"这都不知道？再走两步，就是我们大雪山啦！\",\"雪山\":\"大雪山就是我家，我们三位大王正在招兵买马，要不要去看看？\",\"大大王\":\"我家大大王神通广大，本事高强，曾一口吞了十万天兵。\",\"二大王\":\"我家二大王身高三丈，卧蚕眉，丹凤眼，\",\"三大王\":\"我家三大王非凡间之物，名号云程万里鹏，又叫大鹏名王，\"}', '[\"小钻风敲着铜锣吆喝道：巡山的，放哨的注意了！这几天唐僧就要从这过，大家都留点神！\",\"小钻风喊道：唐僧的大徒弟孙悟空尖嘴猴腮，象个雷公！\",\"小钻风喊道：唐僧的二徒弟猪八戒肥头大耳，象个猪骡！\",\"小钻风喊道：唐僧的三徒弟沙和尚满脸秽气，象个鲶鱼精！\"]', NULL, NULL, 'human', 'yaomo', NULL, 'male', 16, 'peaceful', 100, 100, 150, 150, 100, 100, 10, 10, 10, 10, 10, 10, 11, 5000, 0, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 1, 1, NULL, 'moon', 'moon/xiaolu1', 'moon/xiaolu1', NULL, 25, 0, NULL, 0, 1, '2026-08-16 09:19:12', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (553, 'xiezi', '双尾蝎', NULL, '一只双尾蝎。', 0, NULL, NULL, NULL, NULL, NULL, '[\"双尾蝎握紧了手中的兵器。\",\"双尾蝎警惕地环顾四周。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 26, 'heroism', 1500, 1500, 1500, 1500, 1500, 1500, 10, 10, 10, 10, 10, 10, 10, 450000, 600000, 0, 0, 0, 1200, 1200, 30, 100, 100, 600, 600, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"healing_pill\",\"name\":\"回春丹\",\"chance\":15,\"min\":1,\"max\":2},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":60,\"min\":10,\"max\":50},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":80,\"min\":30,\"max\":100}]', 'xueshan', 'xueshan/no4-wn2', 'xueshan/no4-wn2', NULL, 0, 0, '[\"双尾蝎大喝一声：受死吧！\",\"双尾蝎冷笑道：就凭你也敢与我为敌？\",\"双尾蝎怒喝：不知死活的东西！\"]', 23, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (554, 'xueshanyao', '雪山妖', NULL, '雪山门下有很多巡使。因为外人很少能到这里，在谷内的巡使大多武功不高，至于大雪山的法术则基本上不会。这位巡使身披白袍，腰跨弯刀。白袍当胸绣着一只飞扬欲脱的大鹏鸟。弯刀看起来晶莹透明，好像是以寒冰制成。', 0, NULL, NULL, NULL, NULL, NULL, '[\"雪山妖恶狠狠地盯着过往的行人。\",\"雪山妖发出一声低沉的咆哮。\"]', NULL, NULL, 'human', 'yaomo', NULL, 'male', 33, 'aggressive', 100, 100, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 19, 35000, 30000, 0, 0, 0, 300, 250, 5, 100, 100, 0, 0, 0, 0, 0, 1, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/snowmaze1', 'xueshan/snowmaze1', NULL, 0, 0, '[\"雪山妖吼道：看招！\",\"雪山妖大喝：纳命来！\"]', 50, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (555, 'xunshi-out', '冰谷巡使', NULL, '雪山门下有很多巡使。因为外人很少能到这里，在谷内的巡使大多武功不高，至于大雪山的法术则基本上不会。这位巡使身披白袍，腰跨弯刀。白袍当胸绣着一只飞扬欲脱的大鹏鸟。弯刀看起来晶莹透明，好像是以寒冰制成。', 1, NULL, NULL, NULL, NULL, NULL, '[\"冰谷巡使四下打量了一番。\",\"冰谷巡使沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'yaomo', '大雪山', 'male', 33, 'peaceful', 100, 100, 300, 300, 300, 300, 10, 10, 10, 10, 10, 10, 19, 25000, 20000, 0, 60, 0, 300, 250, 5, 100, 100, 0, 0, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/binggukou', 'xueshan/binggukou', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:10:12', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (557, 'yingwu-guai', '鹦鹉将军', NULL, '雪山门下有名的高手之一鹦鹉将军。他远看还不错，走近了才发现他长着长长的一张鸟嘴。', 1, 'xueshan', '弟子', '{\"family_required\": \"大雪山\"}', '[\"不敢，不敢。我该拜\", \"你这个\", \"你这个\", \"好，到我们大雪山来学艺，又找了个好师父。\"]', NULL, '[\"鹦鹉将军四下打量了一番。\",\"鹦鹉将军沉思片刻，若有所悟。\"]', NULL, NULL, 'human', 'yaomo', '大雪山', 'male', 23, 'peaceful', 100, 100, 700, 700, 600, 600, 10, 10, 10, 10, 10, 10, 112, 100000, 50000, 0, 0, 0, 700, 700, 10, 100, 100, 700, 700, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/boyroom', 'xueshan/boyroom', NULL, 30, 0, NULL, 0, 1, '2026-08-16 09:40:35', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (559, 'zhizhu', '五彩蜘蛛', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, '[\"五彩蜘蛛恶狠狠地盯着过往的行人。\",\"五彩蜘蛛发出一声低沉的咆哮。\"]', NULL, NULL, '野兽', NULL, NULL, 'male', 100, 'aggressive', 100, 100, 100, 100, 100, 100, 10, 10, 10, 10, 10, 10, 10, 300000, 300000, 0, 0, 0, 0, 0, 0, 100, 100, 0, 0, 0, 0, 0, 1, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'xueshan', 'xueshan/zhuwang', 'xueshan/zhuwang', NULL, 0, 0, '[\"五彩蜘蛛吼道：看招！\",\"五彩蜘蛛大喝：纳命来！\"]', 53, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (560, 'zhangguolao', '张果老', NULL, '一位笑嘻嘻的滑稽老头。', 1, 'wzg', '弟子', '{\"gender\": \"男性\", \"family_required\": \"五庄观\"}', '[\"师叔见笑了。\\\\n\", \"师姑见笑了。\\\\n\", \"师兄太客气了。\\\\n\", \"师妹太客气了。\\\\n\", \"是你自己要拜的，你师父打上门来我可得拿你挡。\\\\n\", \"好，好好干，张果老不行，徒弟可不能差了。\\\\n\"]', '{\"name\":\"呵呵！张果老是也。\\\",\"here\":\"今儿个醉了，还真被你问倒了。\\\"}', '[\"张果老嘻嘻嘻地笑了几声。\",\"张果老拿起酒葫芦又灌了一口，满意地咂了咂嘴。\",\"张果老打了个响指：哈哈，我的小毛驴就是听话。\"]', NULL, '[{\"type\":\"accept_object\",\"accepted_items\":[\"guihua-jiudai\"],\"response_message\":\"张果老呵呵一笑，接过酒袋：好酒！好酒！\"}]', 'human', 'xian', '五庄观', 'male', 50, 'peaceful', 100, 100, 500, 500, 500, 500, 10, 10, 10, 10, 10, 10, 20, 120000, 500000, 0, 0, 0, 1000, 800, 40, 1600, 800, 1600, 800, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'city', 'city/center', 'city/center', '', 10, 0, NULL, 0, 1, '2026-08-16 09:45:14', NULL, 0, 0, 0, NULL);
