INSERT INTO `npcs` VALUES (663, 'zhenyuan', '镇元大仙', '五庄观观主', '交游遍三界，桃李漫五行。好一位地仙之祖！', 1, 'wzg', '地仙之祖', '{\"int_min\": 30, \"spi_min\": 30, \"daoxing_min\": 300000}', '{\"int\": \"悟性不够，修不了我的功法。\", \"spi\": \"灵气不足，无法感悟地仙之道。\", \"daoxing\": \"道行不够，还需苦修。\"}', '{\"leave\":[\"callable\",\"expell_me\"],\"离开\":[\"callable\",\"expell_me\"],\"袖里乾坤\":[\"callable\",\"keyword\"],\"秘诀\":[\"callable\",\"keyword\"],\"name\":\"老夫镇元。\",\"here\":\"这里是五庄观，不过住的可不是道士。\",\"人参果\":[\"callable\",\"asked_guo\"]}', '[\"镇元大仙四下打量了一番。\",\"镇元大仙沉思片刻，若有所悟。\",\"镇元大仙叹道：天道苍茫，修行无尽啊。\",\"镇元大仙喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', 'xian', '五庄观', 'male', 65, 'peaceful', 100, 100, 4500, 4500, 4500, 4500, 30, 10, 10, 10, 10, 10, 24, 2800000, 10000000, 0, 0, 0, 5000, 2500, 100, 0, 0, 7000, 5000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"immortal_pill\",\"name\":\"九转仙丹\",\"chance\":5,\"min\":1,\"max\":2},{\"item_id\":\"heavenly_weapon\",\"name\":\"天兵利器\",\"chance\":3,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":80,\"min\":50,\"max\":200}]', 'qujing', 'qujing/wuzhuang/chengyun', 'qujing/wuzhuang/chengyun', NULL, 0, 60, '[\"qiankun\"]', 0, 1, '2026-06-16 05:51:56', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (665, 'jiruhuo', '急如火', '火云洞健将', '一个贼眉鼠眼的小妖精。', 1, 'huoyun', '蓝', '{\"family_required\": \"火云洞\"}', '[\"大家同门中人，不敢当，不敢当！\\\\n\"]', '{\"下山\":[\"callable\",\"expell_me\"],\"leave\":[\"callable\",\"expell_me\"]}', '[\"急如火四下打量了一番。\",\"急如火沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, '火云洞', 'male', 10, 'friendly', 100, 100, 800, 800, 800, 800, 10, 10, 10, 10, 10, 10, 15, 0, 100000, 0, 0, 0, 400, 400, 20, 0, 0, 400, 400, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/jiruhuo', 'qujing/jiruhuo', NULL, 0, 0, NULL, 0, 1, '2026-06-16 04:35:06', NULL, 0, 0, 0, NULL);
