INSERT INTO `npcs` VALUES (668, 'qixiushou', '七修兽', NULL, '一只浑身上下披着银羽的猛虎，一双眼睛正恶狠狠地瞪著你。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下七修兽。\",\"here\":\"这里妖魔出没，险象环生。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"七修兽恶狠狠地盯着过往的行人。\",\"七修兽发出一声低沉的咆哮。\"]', NULL, NULL, '野兽', NULL, NULL, 'male', 50, 'aggressive', 100, 100, 1500, 1500, 1500, 1500, 30, 10, 10, 10, 30, 10, 10, 800000, 500000, 0, 0, 0, 2000, 1000, 80, 0, 0, 2000, 1000, 0, 0, 0, 1, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/kusong/xuanjing', 'qujing/kusong/xuanjing', NULL, 0, 0, '[\"七修兽吼道：看招！\",\"七修兽大喝：纳命来！\"]', 55, 1, '2026-06-16 04:55:06', NULL, 0, 0, 0, NULL);
