INSERT INTO `npcs` VALUES (679, 'cloud', '云里雾', NULL, NULL, 1, 'wudidong', '弟子', NULL, NULL, '{\"princess\":[\"callable\",\"test_player\"],\"铁扇公主\":[\"callable\",\"test_player\"],\"公主\":[\"callable\",\"test_player\"]}', '[\"云里雾握紧了手中的兵器。\",\"云里雾警惕地环顾四周。\"]', NULL, NULL, 'human', NULL, '翠云山芭蕉洞', 'male', 20, 'heroism', 500, 500, 500, 500, 500, 500, 10, 10, 10, 10, 10, 10, 10, 240000, 200000, 0, 0, 0, 500, 500, 20, 0, 0, 500, 500, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/cloud', 'qujing/cloud', NULL, 0, 0, '[\"云里雾吼道：看招！\",\"云里雾大喝：纳命来！\"]', 52, 1, '2026-06-16 06:11:08', NULL, 0, 0, 0, NULL);
