INSERT INTO `npcs` VALUES (690, 'changtuixiabing', '长腿虾兵', '碧波潭九头驸马侍卫', '碧波潭与龙宫和火云洞都有交情,他是来龙宫做客的,顺便也收些徒弟。', 1, 'huoyun', '蓝', '{\"family_required\": \"碧波潭\"}', '[\"大家同门中人，不敢当，不敢当！\\\\n\"]', '{\"下山\":[\"callable\",\"expell_me\"],\"leave\":[\"callable\",\"expell_me\"]}', '[\"长腿虾兵四下打量了一番。\",\"长腿虾兵沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, '碧波潭', 'male', 25, 'friendly', 100, 100, 800, 800, 800, 800, 10, 10, 10, 10, 10, 10, 15, 0, 100000, 0, 0, 0, 400, 400, 20, 0, 0, 400, 400, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/changtuixiabing', 'qujing/changtuixiabing', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:14:38', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (691, 'dadu', '大肚虾婆', NULL, '一个挺着肚子走来走去的老虾婆。', 0, NULL, NULL, NULL, NULL, NULL, '[\"大肚虾婆挺了挺肚子。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 50, 'peaceful', 100, 100, 500, 500, 500, 500, 20, 20, 30, 10, 10, 10, 10, 5000, 10000, 0, 200, 0, 200, 200, 10, 0, 0, 60, 50, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/bibotan/tandi3', 'qujing/bibotan/tandi3', NULL, 10, 0, NULL, 0, 1, '2026-08-16 09:37:00', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (692, 'fuma', '九头驸马', '九头虫', '九头驸马原在北冥大泽中修练，后被招为驸马。', 1, 'huoyun', '碧波潭驸马', '{\"con_min\": 30, \"daoxing_min\": 200000}', '{\"con\": \"体质太差，受不了火云洞的修炼。\", \"daoxing\": \"修为不够。\"}', '{\"name\":\"在下九头驸马。\",\"here\":\"这里妖魔出没，险象环生。\",\"修仙\":\"修行之道，在于持之以恒，切莫急功近利。\",\"妖魔\":\"如今妖魔横行，我辈当以除魔卫道为己任。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"九头驸马握紧了手中的兵器。\",\"九头驸马警惕地环顾四周。\"]', NULL, NULL, 'human', 'yaomo', '火云洞', 'male', 20, 'heroism', 100, 100, 1600, 1600, 1600, 1600, 30, 25, 10, 10, 10, 10, 10, 1200000, 1500000, 0, 500, 0, 2000, 2000, 100, 0, 0, 3000, 1600, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/bibotan/shuangyu', 'qujing/bibotan/shuangyu', NULL, 0, 0, '[\"九头驸马大喝一声：受死吧！\",\"九头驸马冷笑道：就凭你也敢与我为敌？\",\"九头驸马怒喝：不知死活的东西！\"]', 65, 1, '2026-06-16 05:43:46', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (693, 'gongzhu', '公主', '天竺国', NULL, 0, NULL, NULL, NULL, NULL, '{\"宝贝\":\"什么宝贝不宝贝的！\",\"佛宝\":\"佛宝现是我龙宫的镇潭之宝了，谁也拿不到。\",\"方位\":[\"callable\",\"say_position\"]}', '[\"万圣公主四下打量了一番。\",\"万圣公主沉思片刻，若有所悟。\",\"万圣公主叹道：天道苍茫，修行无尽啊。\",\"万圣公主喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'female', 20, 'peaceful', 1200, 1200, 1200, 1200, 1200, 1200, 10, 10, 10, 10, 10, 10, 10, 900000, 800000, 0, 90, 0, 1200, 1200, 120, 0, 0, 1200, 1200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/tianzhu/hou3', 'qujing/tianzhu/hou3', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:14:38', NULL, 0, 0, 0, NULL);
