INSERT INTO `npcs` VALUES (696, 'laohujing', '老虎精', NULL, '一个凶神恶煞般的老虎精，张着血盆大口，要吃人的样子。', 0, NULL, NULL, NULL, NULL, NULL, '[\"老虎精恶狠狠地盯着过往的行人。\",\"老虎精发出一声低沉的咆哮。\"]', NULL, NULL, 'human', 'yaomo', NULL, 'male', 30, 'aggressive', 100, 100, 1000, 1000, 900, 900, 30, 20, 30, 10, 10, 10, 10, 350000, 100000, 0, 400, 0, 500, 500, 40, 0, 0, 100, 100, 0, 0, 0, 1, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/laohujing', 'qujing/laohujing', NULL, 0, 0, '[\"老虎精吼道：看招！\",\"老虎精大喝：纳命来！\"]', 51, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
