INSERT INTO `npcs` VALUES (718, 'king', '国王', '朱紫国', '朱紫国的国王，头戴朱金冠，手执紫金杖。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"朕乃朱紫国国王也，近来身体不适，久医难愈。\",\"王后\":\"朕之后，唯金圣宫后已别三年矣。\",\"金圣宫\":\"金圣宫不在已三年矣。\",\"不适\":[\"callable\",\"test_player\"],\"病\":[\"callable\",\"test_player\"],\"医\":[\"callable\",\"test_player\"],\"医治\":[\"callable\",\"test_player\"],\"医疗\":[\"callable\",\"test_player\"],\"药\":[\"callable\",\"test_player\"],\"吃药\":[\"callable\",\"test_player\"]}', '[\"国王四下打量了一番。\",\"国王沉思片刻，若有所悟。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 46, 'peaceful', 800, 800, 800, 800, 800, 800, 10, 10, 10, 10, 10, 10, 30, 200000, 100000, 15000, 90, 0, 0, 1000, 120, 0, 0, 0, 1000, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":70,\"min\":10,\"max\":50},{\"item_id\":\"copper\",\"name\":\"铜钱\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/zhuzi/nei', 'qujing/zhuzi/nei', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (719, 'langli', '狼力大仙', NULL, NULL, 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下狼力大仙。\",\"here\":\"这里妖魔出没，险象环生。\",\"修仙\":\"修行之道，在于持之以恒，切莫急功近利。\",\"妖魔\":\"如今妖魔横行，我辈当以除魔卫道为己任。\",\"武功\":\"武功修为需日积月累，非一朝一夕之功。\"}', '[\"狼力大仙四下打量了一番。\",\"狼力大仙沉思片刻，若有所悟。\",\"狼力大仙叹道：天道苍茫，修行无尽啊。\",\"狼力大仙喃喃自语：不知何时才能得证大道。\"]', NULL, NULL, 'human', NULL, NULL, 'male', 40, 'peaceful', 3200, 3200, 3200, 3200, 3200, 3200, 10, 70, 70, 10, 70, 70, 70, 0, 3000000, 0, 400, 0, 3200, 3200, 15, 0, 0, 3200, 3200, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"elixir\",\"name\":\"灵丹妙药\",\"chance\":10,\"min\":1,\"max\":3},{\"item_id\":\"rare_weapon\",\"name\":\"精良兵器\",\"chance\":5,\"min\":1,\"max\":1},{\"item_id\":\"gold\",\"name\":\"黄金\",\"chance\":70,\"min\":20,\"max\":100},{\"item_id\":\"silver\",\"name\":\"白银\",\"chance\":90,\"min\":50,\"max\":200}]', 'qujing', 'qujing/chechi/miyuan1', 'qujing/chechi/miyuan1', NULL, 0, 0, NULL, 0, 1, '2026-06-16 06:15:14', NULL, 0, 0, 0, NULL);
