INSERT INTO `npcs` VALUES (782, 'tongtian_huashen', '黄发小童', '', '一个面容清秀的黄发小童，端坐在莲台之上，神态安详，似有仙家气度。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"在下黄发小童。\",\"here\":\"此处竹林清幽，正是修行之所。\",\"通天河\":\"施主问的是通天河么？且去降了那妖怪再说。\",\"金鳞怪\":\"那妖怪么……施主且去降了再说。\"}', '[\"黄发小童微微一笑。\",\"黄发小童闭目凝神。\",\"竹林中传来的阵阵清香。\"]', NULL, NULL, '人类', 'xian', '', 'male', 13, 'peaceful', 700, 700, 700, 700, 700, 700, 10, 90, 10, 10, 90, 90, 90, 150000, 100000, 0, 0, 0, 700, 700, 10, 5000, 5000, 5000, 700, 0, 0, 0, 0, 1, 0, NULL, 'qujing', 'qujing/tongtian/huashen', 'qujing/tongtian/huashen', NULL, 3, 0, NULL, 0, 1, '2026-08-16 09:15:32', NULL, 0, 0, 0, NULL);
