INSERT INTO `npcs` VALUES (1580, 'dianmu', '电母', NULL, '    一端庄秀雅的天神，在天宫中负责闪电。', 0, NULL, NULL, NULL, NULL, '{\"闪电\":\"没到时候。\",\"name\":\"我是电神。\",\"here\":\"这里就是天宫。\"}', NULL, NULL, NULL, 'human', 'xian', NULL, 'female', 45, 'heroism', 100, 100, 700, 700, 750, 750, 10, 10, 10, 10, 10, 10, 17, 70000, 120000, 0, 0, 0, 900, 900, 30, 0, 0, 1100, 1100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"dianlingfu\",\"name\":\"电灵符\",\"chance\":100,\"min\":1,\"max\":1}]', 'dntg', 'dntg/sky/tgqs6', 'dntg/sky/tgqs6', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (1581, 'fengpo', '风婆', NULL, '    天宫中负责起风的天神，想要刮风下雨时，没有她的帮助是不行的。', 0, NULL, NULL, NULL, NULL, '{\"下雨\":\"想求雨，光我一个人可不够。\",\"rain\":\"想求雨，光我一个人可不够。\",\"起风\":[\"callable\",\"fengpo_ask_wind\"],\"刮风\":[\"callable\",\"fengpo_ask_wind\"],\"wind\":[\"callable\",\"fengpo_ask_wind\"],\"name\":\"我就是负责起风的风神。\",\"here\":\"这就是天宫呀。\"}', NULL, NULL, '[{\"action_name\":\"要风灵符\",\"action_cmd\":\"yao\",\"description\":\"向风婆索要一张风灵符\"}]', 'human', 'xian', NULL, 'female', 35, 'heroism', 100, 100, 600, 600, 650, 650, 10, 10, 10, 10, 10, 10, 18, 60000, 100000, 0, 0, 0, 800, 800, 20, 0, 0, 1000, 1000, 0, 10, 0, 0, 1, 0, NULL, 'dntg', 'dntg/sky/tgqs3', 'dntg/sky/tgqs3', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
