INSERT INTO `npcs` VALUES (1583, 'leigong', '雷公', NULL, '    一个尖嘴猴腮的天神，在天宫中负责打雷。', 0, NULL, NULL, NULL, NULL, '{\"打雷\":\"急什么？该下雨时我自然会去打雷。\",\"name\":\"我是雷神。\",\"here\":\"这里就是天宫。\"}', NULL, NULL, NULL, 'human', 'xian', NULL, 'male', 45, 'heroism', 100, 100, 700, 700, 750, 750, 10, 10, 10, 10, 10, 10, 17, 70000, 120000, 0, 0, 0, 900, 900, 30, 0, 0, 1100, 1100, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"leilingfu\",\"name\":\"雷灵符\",\"chance\":100,\"min\":1,\"max\":1}]', 'dntg', 'dntg/sky/tgqs5', 'dntg/sky/tgqs5', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (1584, 'lingguan', '灵官', NULL, '佑圣真君手下灵官，忠心赤胆，骁勇无比。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'human', 'xian', NULL, 'male', 25, 'heroism', 100, 100, 3500, 3500, 2700, 2700, 10, 10, 10, 10, 10, 10, 10, 800000, 1000000, 0, 0, 0, 1800, 1800, 100, 0, 0, 1700, 1700, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/lingguan', 'dntg/lingguan', NULL, 0, 60, '[\"whip\",\"lunhui\"]', 0, 1, NULL, NULL, 0, 0, 0, NULL);
