INSERT INTO `npcs` VALUES (1589, 'yuntong', '云童', NULL, '    天宫中负责起云的天神，他虽看上去年纪轻轻，却掌管着天上所有的云彩。', 0, NULL, NULL, NULL, NULL, '{\"起云\":\"有张灵符可以起云，但我不能给你。\",\"cloud\":\"有张灵符可以起云，但我不能给你。\",\"name\":\"我是云神。\",\"here\":\"这里就是天宫。\"}', NULL, NULL, NULL, 'human', 'xian', NULL, 'male', 15, 'heroism', 100, 100, 500, 500, 550, 550, 10, 10, 10, 10, 10, 10, 22, 800000, 80000, 0, 0, 0, 700, 700, 20, 0, 0, 900, 900, 0, 0, 0, 0, 1, 0, '[{\"item_id\":\"yunlingfu\",\"name\":\"云灵符\",\"chance\":100,\"min\":1,\"max\":1}]', 'dntg', 'dntg/sky/tgqs4', 'dntg/sky/tgqs4', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `npcs` VALUES (1590, 'chijiaodaxian', '赤脚大仙', NULL, '一个懒懒散散的老头儿，正光着脚四处游荡。他看上去忠厚老实，大概一骗(pian)就上当。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"老夫赤脚大仙是也。\",\"here\":\"这就是天界啦。\"}', '[\"赤脚大仙叹道：怎么还没到开蟠桃会的日子？老夫都等不及了。\\\"]', NULL, NULL, 'human', 'xian', NULL, 'male', 50, 'peaceful', 100, 100, 1000, 1000, 1000, 1000, 30, 30, 30, 10, 30, 30, 22, 500000, 800000, 0, 0, 0, 800, 800, 50, 0, 0, 800, 800, 0, 0, 0, 0, 1, 0, NULL, 'dntg', 'dntg/yaochi/wmj1', 'dntg/yaochi/wmj1', NULL, 10, 0, NULL, 0, 1, '2026-06-16 07:43:39', NULL, 0, 0, 0, NULL);
