INSERT INTO `npcs` VALUES (1668, 'shangguanjunzhu', '上官郡主', '凤仙郡', '天竺国凤仙郡的一郡之侯。', 0, NULL, NULL, NULL, NULL, '{\"name\":\"老夫乃凤仙郡侯，上官乃本郡之官姓。\",\"上官\":\"老夫乃凤仙郡侯，上官乃本郡之官姓。\",\"here\":\"此乃天竺国凤仙郡，因久旱无雨急寻法师以祭雨求雨祈雨救吾军民也。\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 50, 'peaceful', 800, 800, 800, 800, 800, 800, 10, 10, 10, 10, 10, 10, 25, 200000, 0, 15000, 90, 0, 0, 1000, 120, 0, 0, 0, 1000, 0, 0, 0, 0, 1, 0, NULL, 'qujing', 'qujing/fengxian/junhou', 'qujing/fengxian/junhou', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
