INSERT INTO `npcs` VALUES (1781, 'tudi-qujing', '白髯土地', NULL, NULL, 0, NULL, NULL, NULL, NULL, '{\"here\":\"这儿是隐雾山，亦有连环洞在此。\\\",\"隐雾山\":\"隐雾山乃有连环洞之去处，多加小心为是。\\\",\"连环洞\":\"连环洞在隐雾山下连环相衔，有两个入口也。\\\",\"name\":\"隐雾山土地也，老夫别无他物，只有一宝。\\\",\"宝\":\"老夫有一法简，乃一锦一禅师所赠。\\\"}', NULL, NULL, NULL, 'human', NULL, NULL, 'male', 100, 'friendly', 600, 600, 100, 100, 600, 600, 10, 10, 10, 10, 10, 10, 25, 250000, 300000, 0, 0, 0, 800, 800, 25, 0, 0, 0, 800, 0, 0, 0, 0, 1, 0, NULL, 'qujing', 'qujing/tudi', 'qujing/tudi', NULL, 0, 0, NULL, 0, 1, NULL, NULL, 0, 0, 0, NULL);
