INSERT INTO `poem_rounds` VALUES (1, 147, '司空曙', '喜外弟卢纶见宿', '[\"静夜四无邻  荒居旧业贫\",\"雨中黄叶树  灯下白头人\",\"以我独沉久  愧君相访频\",\"平生自有分  况是蔡家亲\"]', 3, '平生自有分', '况是蔡家亲', '平生自有分况是蔡家亲', '平生自有蔡况是亲家分', 0, NULL, 0, '2026-08-05 09:09:06');
INSERT INTO `poem_rounds` VALUES (2, 14, '王维', '送綦毋潜落第还乡', '[\"圣代无隐者  英灵尽来归\",\"遂令东山客  不得顾采薇\",\"既至金门远  孰云吾道非\",\"江淮度寒食  京洛缝春衣\",\"置酒长安道  同心与我违\",\"行当浮桂棹  未几拂荆扉\",\"远树带行客  孤城当落晖\",\"吾谋适不用  勿谓知音稀\"]', 1, '遂令东山客', '不得顾采薇', '遂令东山客不得顾采薇', '遂令东客不山得顾采薇', 0, NULL, 0, '2026-08-05 09:10:06');
INSERT INTO `poem_rounds` VALUES (3, 234, '刘长卿', '送灵澈', '[\"苍苍竹林寺  杳杳钟声晚\",\"荷笠带斜阳  青山独归远\"]', 1, '荷笠带斜阳', '青山独归远', '荷笠带斜阳青山独归远', '阳笠带斜荷青独山归远', 0, NULL, 0, '2026-08-05 09:11:07');
INSERT INTO `poem_rounds` VALUES (4, 285, '杜牧', '将赴吴兴登乐游原', '[\"清时有味是无能  闲爱孤云静爱僧\",\"欲把一麾江海去  乐游原上望昭陵\"]', 1, '欲把一麾江海去', '乐游原上望昭陵', '欲把一麾江海去', '欲江一麾把海去', 0, NULL, 0, '2026-08-07 14:57:48');
INSERT INTO `poem_rounds` VALUES (5, 99, '岑参', '寄左省杜拾遗', '[\"联步趋丹陛  分曹限紫微\",\"晓随天仗入  暮惹御香归\",\"白发悲花落  青云羡鸟飞\",\"圣朝无阙事  自觉谏书稀\"]', 0, '联步趋丹陛', '分曹限紫微', '联步趋丹陛分曹限紫微', '联步趋陛限分曹丹紫微', 0, NULL, 0, '2026-08-07 14:58:49');
INSERT INTO `poem_rounds` VALUES (6, 102, '李白', '送友人', '[\"青山横北郭  白水绕东城\",\"此地一为别  孤蓬万里征\",\"浮云游子意  落日故人情\",\"挥手自兹去  萧萧班马鸣\"]', 0, '青山横北郭', '白水绕东城', '青山横北郭白水绕东城', '青山城北绕白水郭东横', 0, NULL, 0, '2026-08-07 14:59:49');
INSERT INTO `poem_rounds` VALUES (7, 121, '王维', '汉江临眺', '[\"楚塞三湘接  荆门九派通\",\"江流天地外  山色有无中\",\"郡邑浮前浦  波澜动远空\",\"襄阳好风日  留醉与山翁\"]', 0, '楚塞三湘接', '荆门九派通', '楚塞三湘接荆门九派通', '湘荆三楚接塞门九派通', 1, '测试员aaa', 0, '2026-08-07 15:01:07');
INSERT INTO `poem_rounds` VALUES (8, 88, '杜甫', '哀江头', '[\"少陵野老吞生哭  春日潜行曲江曲\",\"江头宫殿锁千门  细柳新蒲为谁绿\",\"忆昔霓旌下南苑  苑中景物生颜色\",\"昭阳殿里第一人  同辇随君侍君侧\",\"辇前才人带弓箭  白马嚼啮黄金勒\",\"翻身向天仰射云  一箭正坠双飞翼\",\"明眸皓齿今何在  血污游魂归不得\",\"清渭东流剑阁深  去住彼此无消息\",\"人生有情泪沾臆  江水江花岂终极\",\"黄昏胡骑尘满城  欲往城南望城北\"]', 9, '黄昏胡骑尘满城', '欲往城南望城北', '黄昏胡骑尘满城', '昏黄城骑尘满胡', 0, NULL, 0, '2026-08-07 15:02:07');
INSERT INTO `poem_rounds` VALUES (9, 71, '白居易', '长恨歌', '[\"汉皇重色思倾国  御宇多年求不得\",\"杨家有女初长成  养在深闺人未识\",\"天生丽质难自弃  一朝选在君王侧\",\"回眸一笑百媚生  六宫粉黛无颜色\",\"春寒赐浴华清池  温泉水滑洗凝脂\",\"侍儿扶起娇无力  始是新承恩泽时\",\"云鬓花颜金步摇  芙蓉帐暖度春宵\",\"春宵苦短日高起  从此君王不早朝\",\"承欢侍宴无闲暇  春从春游夜专夜\",\"后宫佳丽三千人  三千宠爱在一身\",\"金星妆成娇侍夜  玉楼宴罢醉和春\",\"姊妹弟兄皆列士  可怜光彩生门户\",\"遂令天下父母心  不重生男重生女\",\"骊宫高处入青云  仙乐风飘处处闻\",\"缓歌慢舞凝丝竹  尽日君王看不足\",\"渔阳鼙鼓动地来  惊破霓裳羽衣曲\",\"九重城阙烟尘生  千乘万骑西南行\",\"翠华摇摇行复止  西出都门百馀里\",\"六军不发无奈何  宛转蛾眉马前死\",\"花钿委地无人收  翠翘金雀玉搔头\",\"君王掩面救不得  回看血泪相和流\",\"黄埃散漫风萧索  云栈萦纡登剑阁\",\"峨嵋山下少人行  旌旗无光日色薄\",\"蜀江水碧蜀山青  圣主朝朝暮暮情\",\"行宫见月伤心色  夜雨闻铃肠断声\",\"天旋地转回龙驭  到此踌躇不能去\",\"马嵬坡下泥土中  不见玉颜空死处\",\"君臣相顾尽沾衣  东望都门信马归\",\"归来池苑皆依旧  太液芙蓉未央柳\",\"芙蓉如面柳如眉  对此如何不泪垂\",\"春风桃李花开日  秋雨梧桐叶落时\",\"西宫南内多秋草  落叶满阶红不扫\",\"梨园子弟白发新  椒房阿监青娥老\",\"夕殿萤飞思悄然  孤灯挑尽未成眠\",\"迟迟钟鼓初长夜  耿耿星河欲曙天\",\"鸳鸯瓦冷霜华重  翡翠衾寒谁与共\",\"悠悠生死别经年  魂魄不曾来入梦\",\"临邛道士鸿都客  能以精诚致魂魄\",\"为感君王辗转思  遂教方士殷勤觅\",\"排空驭气奔如电  升天入地求之遍\",\"上穷碧落下黄泉  两处茫茫皆不见\",\"忽闻海上有仙山  山在虚无缥缈间\",\"楼阁玲珑五云起  其中绰约多仙子\",\"中有一人字太真  雪肤花貌参差是\",\"金阙西厢叩玉扃  转教小玉报双成\",\"闻道汉家天子使  九华帐里梦魂惊\",\"揽衣推枕起徘徊  珠箔银屏迤逦开\",\"云鬓半偏新睡觉  花冠不整下堂来\",\"风吹仙袂飘飘举  犹似霓裳羽衣舞\",\"玉容寂寞泪阑干  梨花一枝春带雨\",\"含情凝睇谢君王  一别音容两渺茫\",\"昭阳殿里恩爱绝  蓬莱宫中日月长\",\"回头下望人寰处  不见长安见尘雾\",\"唯将旧物表深情  钿合金钗寄将去\",\"钗留一股合一扇  钗擘黄金合分钿\",\"但教心似金钿坚  天上人间会相见\",\"临别殷勤重寄词  词中有誓两心知\",\"七月七日长生殿  夜半无人私语时\",\"在天愿作比翼鸟  在地愿为连理枝\",\"天长地久有时尽  此恨绵绵无绝期\"]', 18, '六军不发无奈何', '宛转蛾眉马前死', '宛转蛾眉马前死', '宛转蛾眉马前死', 0, NULL, 0, '2026-08-07 15:03:07');
INSERT INTO `poem_rounds` VALUES (10, 232, '杜甫', '八阵图', '[\"功盖三分国  名成八阵图\",\"江流石不转  遗恨失吞吴\"]', 1, '江流石不转', '遗恨失吞吴', '江流石不转遗恨失吞吴', '江流转不石遗恨失吞吴', 0, NULL, 0, '2026-08-07 15:04:08');
INSERT INTO `poem_rounds` VALUES (11, 243, '张祜', '何满子', '[\"故国三千里  深宫二十年\",\"一声何满子  双泪落君前\"]', 0, '故国三千里', '深宫二十年', '故国三千里深宫二十年', '故国三千里宫深二十年', 0, NULL, 0, '2026-08-07 15:05:08');
INSERT INTO `poem_rounds` VALUES (12, 240, '权德舆', '玉台体', '[\"昨夜裙带解  今朝［虫喜］子飞\",\"铅华不可弃  莫是藁砧归\"]', 1, '铅华不可弃', '莫是藁砧归', '铅华不可弃莫是藁砧归', '华铅不可弃莫是藁砧归', 0, NULL, 0, '2026-08-07 15:06:09');
INSERT INTO `poem_rounds` VALUES (13, 51, '李颀', '听安万善吹筚篥歌', '[\"南山截竹为筚篥  此乐本自龟兹出\",\"流传汉地曲转奇  凉州胡人为我吹\",\"傍邻闻者多叹息  远客思乡皆泪垂\",\"世人解听不解赏  长飙风中自来往\",\"枯桑老柏寒飕［风留］  九雏鸣凤乱啾啾\",\"龙吟虎啸一时发  万籁百泉相与秋\",\"忽然更作渔阳掺  黄云萧条白日暗\",\"变调如闻杨柳春  上林繁花照眼新\",\"岁夜高堂列明烛  美酒一杯声一曲\"]', 7, '变调如闻杨柳春', '上林繁花照眼新', '变调如闻杨柳春上林繁花照眼新', '变调如闻杨柳春上林繁花照新眼', 0, NULL, 0, '2026-08-07 15:07:09');
INSERT INTO `poem_rounds` VALUES (14, 249, '崔颢', '长干行二首之一', '[\"君家何处住  妾住在横塘\",\"停船暂借问  或恐是同乡\"]', 1, '停船暂借问', '或恐是同乡', '停船暂借问或恐是同乡', '停船暂同问或恐是借乡', 0, NULL, 0, '2026-08-07 15:08:10');
INSERT INTO `poem_rounds` VALUES (15, 219, '秦韬玉', '贫女', '[\"蓬门未识绮罗香  拟托良媒益自伤\",\"谁爱风流高格调  共怜时世俭梳妆\",\"敢将十指夸针巧  不把双眉斗画长\",\"苦恨年年压金线  为他人作嫁衣裳\"]', 3, '苦恨年年压金线', '为他人作嫁衣裳', '苦恨年年压金线为他人作嫁衣裳', '衣恨年年作金线为他人压嫁苦裳', 0, NULL, 0, '2026-08-07 15:09:11');
INSERT INTO `poem_rounds` VALUES (16, 269, '张继', '枫桥夜泊', '[\"月落乌啼霜满天  江枫渔火对愁眠\",\"姑苏城外寒山寺  夜半钟声到客船\"]', 1, '姑苏城外寒山寺', '夜半钟声到客船', '姑苏城外寒山寺夜半钟声到客船', '姑城苏声寒山寺夜半钟外到客船', 0, NULL, 0, '2026-08-07 15:10:11');
INSERT INTO `poem_rounds` VALUES (17, 188, '杜甫', '咏怀古迹五首之一', '[\"支离东北风尘际  漂泊西南天地间\",\"三峡楼台淹日月  五溪衣服共云山\",\"羯胡事主终无赖  词客哀时且未还\",\"庾信平生最萧瑟  暮年诗赋动江关\"]', 2, '羯胡事主终无赖', '词客哀时且未还', '词客哀时且未还', '未客哀词且时还', 0, NULL, 0, '2026-08-07 15:11:12');
INSERT INTO `poem_rounds` VALUES (18, 213, '李商隐', '春雨', '[\"怅卧新春白袷衣  白门寥落意多违\",\"红楼隔雨相望冷  珠箔飘灯独自归\",\"远路应悲春［日宛］晚  残宵犹得梦依稀\",\"玉［王当］缄札何由达  万里云罗一雁飞\"]', 0, '怅卧新春白袷衣', '白门寥落意多违', '怅卧新春白袷衣', '怅卧新衣白袷春', 0, NULL, 0, '2026-08-07 15:12:12');
INSERT INTO `poem_rounds` VALUES (19, 176, '王维', '和贾舍人早朝大明宫之作', '[\"绛帻鸡人送晓筹  尚衣方进翠云裘\",\"九天阊阖开宫殿  万国衣冠拜冕旒\",\"日色才临仙掌动  香烟欲傍衮龙浮\",\"朝罢须裁五色诏  佩声归向凤池头\"]', 1, '九天阊阖开宫殿', '万国衣冠拜冕旒', '万国衣冠拜冕旒', '万冠衣国拜旒冕', 0, NULL, 0, '2026-08-07 15:13:13');
INSERT INTO `poem_rounds` VALUES (20, 281, '张祜', '集灵台二首之二', '[\"虢国夫人承主恩  平明骑马入宫门\",\"却嫌脂粉污颜色  淡扫蛾眉朝至尊\"]', 1, '却嫌脂粉污颜色', '淡扫蛾眉朝至尊', '却嫌脂粉污颜色', '色嫌脂粉却颜污', 0, NULL, 0, '2026-08-07 15:14:13');
INSERT INTO `poem_rounds` VALUES (21, 112, '杜甫', '旅夜书怀', '[\"细草微风岸  危樯独夜舟\",\"星垂平野阔  月涌大江流\",\"名岂文章著  官应老病休\",\"飘飘何所似  天地一沙鸥\"]', 0, '细草微风岸', '危樯独夜舟', '细草微风岸危樯独夜舟', '细草微岸风危樯独夜舟', 0, NULL, 0, '2026-08-07 15:15:14');
INSERT INTO `poem_rounds` VALUES (22, 102, '李白', '送友人', '[\"青山横北郭  白水绕东城\",\"此地一为别  孤蓬万里征\",\"浮云游子意  落日故人情\",\"挥手自兹去  萧萧班马鸣\"]', 0, '青山横北郭', '白水绕东城', '青山横北郭白水绕东城', '青绕水北郭白横山东城', 0, NULL, 0, '2026-08-07 15:16:14');
INSERT INTO `poem_rounds` VALUES (23, 18, '孟浩然', '秋登兰山寄张五', '[\"北山白云里  隐者自怡悦\",\"相望始登高  心随雁飞灭\",\"愁因薄暮起  兴是清秋发\",\"时见归村人  沙行渡头歇\",\"天边树若荠  江畔洲如月\",\"何当载酒来  共醉重阳节\"]', 2, '愁因薄暮起', '兴是清秋发', '愁因薄暮起兴是清秋发', '愁因薄秋起兴是清暮发', 0, NULL, 0, '2026-08-07 15:17:15');
INSERT INTO `poem_rounds` VALUES (24, 281, '张祜', '集灵台二首之二', '[\"虢国夫人承主恩  平明骑马入宫门\",\"却嫌脂粉污颜色  淡扫蛾眉朝至尊\"]', 0, '虢国夫人承主恩', '平明骑马入宫门', '虢国夫人承主恩平明骑马入宫门', '虢国主人承夫恩平明骑马入宫门', 0, NULL, 0, '2026-08-07 15:18:15');
INSERT INTO `poem_rounds` VALUES (25, 53, '李白', '庐山谣寄卢侍御虚舟', '[\"我本楚狂人  凤歌笑孔丘\",\"手持绿玉杖  朝别黄鹤楼\",\"五岳寻仙不辞远  一生好入名山游\",\"庐山秀出南斗傍  屏风九叠云锦张\",\"影落明湖青黛光  金阙前开二峰长\",\"银河倒挂三石梁  香炉瀑布遥相望\",\"回崖沓障凌苍苍\",\"翠影红霞映朝日  鸟飞不到吴天长\",\"登高壮观天地间  大江茫茫去不黄\",\"黄云万里动风色  白波九道流雪山\",\"好为庐山谣  兴因庐山发\",\"闲窥石镜清我心  谢公行处苍苔没\",\"早服还丹无世情  琴心三叠道初成\",\"遥见仙人彩云里  手把芙蓉朝玉京\",\"先期汗漫九垓上  愿接卢敖游太清\"]', 14, '先期汗漫九垓上', '愿接卢敖游太清', '愿接卢敖游太清', '接愿敖卢游太清', 0, NULL, 0, '2026-08-07 15:19:16');
INSERT INTO `poem_rounds` VALUES (26, 94, '杜审言', '和晋陵路丞早春游望', '[\"独有宦游人  偏惊物候新\",\"云霞出海曙  梅柳渡江春\",\"淑气催黄鸟  晴光转绿苹\",\"忽闻歌古调  归思欲沾巾\"]', 3, '忽闻歌古调', '归思欲沾巾', '忽闻歌古调归思欲沾巾', '忽闻古歌调归思欲沾巾', 0, NULL, 0, '2026-08-07 15:20:16');
INSERT INTO `poem_rounds` VALUES (27, 88, '杜甫', '哀江头', '[\"少陵野老吞生哭  春日潜行曲江曲\",\"江头宫殿锁千门  细柳新蒲为谁绿\",\"忆昔霓旌下南苑  苑中景物生颜色\",\"昭阳殿里第一人  同辇随君侍君侧\",\"辇前才人带弓箭  白马嚼啮黄金勒\",\"翻身向天仰射云  一箭正坠双飞翼\",\"明眸皓齿今何在  血污游魂归不得\",\"清渭东流剑阁深  去住彼此无消息\",\"人生有情泪沾臆  江水江花岂终极\",\"黄昏胡骑尘满城  欲往城南望城北\"]', 1, '江头宫殿锁千门', '细柳新蒲为谁绿', '江头宫殿锁千门细柳新蒲为谁绿', '江门谁殿锁千头细柳新蒲为宫绿', 0, NULL, 0, '2026-08-07 15:21:17');
INSERT INTO `poem_rounds` VALUES (28, 41, '李白', '子夜四时歌：秋歌', '[\"长安一片月  万户捣衣声\",\"秋风吹不尽  总是玉关情\",\"何日平胡虏  良人罢远征\"]', 0, '长安一片月', '万户捣衣声', '长安一片月万户捣衣声', '长月一片安万户捣衣声', 0, NULL, 0, '2026-08-07 15:22:18');
INSERT INTO `poem_rounds` VALUES (29, 179, '王维', '酬郭给事', '[\"洞门高阁霭馀辉  桃李阴阴柳絮飞\",\"禁里疏钟官舍晚  省中啼鸟吏人稀\",\"晨摇玉佩趋金殿  夕奉天书拜琐闱\",\"强欲从君无那老  将因卧病解朝衣\"]', 2, '晨摇玉佩趋金殿', '夕奉天书拜琐闱', '晨摇玉佩趋金殿夕奉天书拜琐闱', '晨摇玉佩趋金殿夕奉天书闱琐拜', 0, NULL, 0, '2026-08-07 15:23:19');
INSERT INTO `poem_rounds` VALUES (30, 258, '张旭', '桃花溪', '[\"隐隐飞桥隔野烟  石矶西畔问渔船\",\"桃花尽日随流水  洞在清溪何处边\"]', 0, '隐隐飞桥隔野烟', '石矶西畔问渔船', '隐隐飞桥隔野烟石矶西畔问渔船', '隐隔飞隐桥野烟石矶西畔问渔船', 0, NULL, 0, '2026-08-07 15:24:20');
INSERT INTO `poem_rounds` VALUES (31, 309, '王维', '秋夜曲', '[\"桂魄初生秋露微  轻罗已薄未更衣\",\"银筝夜久殷勤弄  心怯空房不忍归\"]', 0, '桂魄初生秋露微', '轻罗已薄未更衣', '桂魄初生秋露微', '桂露初生秋魄微', 0, NULL, 0, '2026-08-07 15:25:21');
INSERT INTO `poem_rounds` VALUES (32, 155, '李商隐', '蝉', '[\"本以高难饱  徒劳恨费声\",\"五更疏欲断  一树碧无情\",\"薄宦梗犹泛  故园芜已平\",\"烦君最相警  我亦举家清\"]', 0, '本以高难饱', '徒劳恨费声', '本以高难饱徒劳恨费声', '本以高难饱徒劳费恨声', 1, '测试员aaa', 0, '2026-08-07 15:26:21');
INSERT INTO `poem_rounds` VALUES (33, 227, '祖咏', '终南望馀雪', '[\"终南阴岭秀  积雪浮云端\",\"林表明霁色  城中增暮寒\"]', 0, '终南阴岭秀', '积雪浮云端', '终南阴岭秀积雪浮云端', '终南阴岭积秀雪浮云端', 0, NULL, 0, '2026-08-07 15:27:21');
INSERT INTO `poem_rounds` VALUES (34, 209, '李商隐', '无题二首之一', '[\"来是空言去绝踪  月斜楼上五更钟\",\"梦为远别啼难唤  书被催成墨未浓\",\"蜡照半笼金翡翠  麝熏微度绣芙蓉\",\"刘郎已恨蓬山远  更隔蓬山一万重\"]', 1, '梦为远别啼难唤', '书被催成墨未浓', '书被催成墨未浓', '书未催成墨被浓', 0, NULL, 0, '2026-08-07 15:28:21');
INSERT INTO `poem_rounds` VALUES (35, 163, '张乔', '书边事', '[\"调角断清秋  征人倚戍楼\",\"春风对青冢  白日落梁州\",\"大漠无兵阻  穷边有客游\",\"蕃情似此水  长愿向南流\"]', 0, '调角断清秋', '征人倚戍楼', '调角断清秋征人倚戍楼', '调角断清征秋人倚戍楼', 0, NULL, 0, '2026-08-07 15:29:22');
INSERT INTO `poem_rounds` VALUES (36, 209, '李商隐', '无题二首之一', '[\"来是空言去绝踪  月斜楼上五更钟\",\"梦为远别啼难唤  书被催成墨未浓\",\"蜡照半笼金翡翠  麝熏微度绣芙蓉\",\"刘郎已恨蓬山远  更隔蓬山一万重\"]', 1, '梦为远别啼难唤', '书被催成墨未浓', '书被催成墨未浓', '书被未成墨催浓', 0, NULL, 0, '2026-08-07 15:30:24');
INSERT INTO `poem_rounds` VALUES (37, 189, '杜甫', '咏怀古迹五首之二', '[\"摇落深知宋玉悲  风流儒雅亦吾师\",\"怅望千秋一洒泪  萧条异代不同时\",\"江山故宅空文藻  云雨荒台岂梦思\",\"最是楚宫俱泯灭  舟人指点到今疑\"]', 1, '怅望千秋一洒泪', '萧条异代不同时', '萧条异代不同时', '萧条代异不同时', 0, NULL, 0, '2026-08-07 15:31:24');
INSERT INTO `poem_rounds` VALUES (38, 183, '杜甫', '闻官军收河南河北', '[\"剑外忽传收蓟北  初闻涕泪满衣裳\",\"却看妻子愁何在  漫卷诗书喜欲狂\",\"白日放歌须纵酒  青春作伴好还乡\",\"即从巴峡穿巫峡  便下襄阳向洛阳\"]', 2, '白日放歌须纵酒', '青春作伴好还乡', '白日放歌须纵酒', '酒日放歌须纵白', 0, NULL, 0, '2026-08-07 15:32:26');
INSERT INTO `poem_rounds` VALUES (39, 127, '孟浩然', '过故人庄', '[\"故人具鸡黍  邀我至田家\",\"绿树村边合  青山郭外斜\",\"开轩面场圃  把酒话桑麻\",\"待到重阳日  还来就菊花\"]', 1, '绿树村边合', '青山郭外斜', '绿树村边合青山郭外斜', '绿树村边外青山郭合斜', 0, NULL, 0, '2026-08-07 15:33:26');
INSERT INTO `poem_rounds` VALUES (40, 283, '朱庆馀', '宫词', '[\"寂寂花时闭院门  美人相并立琼轩\",\"含情欲说宫中事  鹦鹉前头不敢言\"]', 1, '含情欲说宫中事', '鹦鹉前头不敢言', '含情欲说宫中事', '情中欲说宫含事', 0, NULL, 0, '2026-08-07 15:34:26');
INSERT INTO `poem_rounds` VALUES (41, 200, '卢纶', '晚次鄂州', '[\"云开远见汉阳城  犹是孤帆一日程\",\"估客昼眠知浪静  舟人夜语觉潮生\",\"三湘愁鬓逢秋色  万里归心对月明\",\"旧业已随征战尽  更堪江上鼓鼙声\"]', 2, '三湘愁鬓逢秋色', '万里归心对月明', '三湘愁鬓逢秋色', '鬓湘愁三逢秋色', 0, NULL, 0, '2026-08-07 15:35:26');
INSERT INTO `poem_rounds` VALUES (42, 43, '李白', '长干行', '[\"妾发初覆额  折花门前剧\",\"郎骑竹马来  绕床弄青梅\",\"同居长干里  两小无嫌猜\",\"十四为君妇  羞颜未尝开\",\"低头向暗壁  千唤不一回\",\"十五始展眉  愿同尘与灰\",\"常存抱柱信  岂上望夫台\",\"十六君远行  瞿塘滟预堆\",\"五月不可触  猿鸣天上哀\",\"门前迟行迹  一一生绿苔\",\"苔深不能扫  落叶秋风早\",\"八月蝴蝶来  双飞西园草\",\"感此伤妾心  坐愁红颜老\",\"早晚下三巴  预将书报家\",\"相迎不道远  直至长风沙\"]', 10, '苔深不能扫', '落叶秋风早', '苔深不能扫落叶秋风早', '苔落不能扫深叶秋风早', 0, NULL, 0, '2026-08-07 15:36:26');
INSERT INTO `poem_rounds` VALUES (43, 167, '韦庄', '章台夜思', '[\"清瑟怨遥夜  绕弦风雨哀\",\"孤灯闻楚角  残月下章台\",\"芳草已云暮  故人殊未来\",\"乡书不可寄  秋雁又南回\"]', 3, '乡书不可寄', '秋雁又南回', '乡书不可寄秋雁又南回', '乡书不雁寄秋可又南回', 0, NULL, 0, '2026-08-07 15:37:26');
INSERT INTO `poem_rounds` VALUES (44, 117, '王维', '终南山', '[\"太乙近天都  连山接海隅\",\"白云回望合  青霭入看无\",\"分野中峰变  阴晴众壑殊\",\"欲投人处宿  隔水问樵夫\"]', 0, '太乙近天都', '连山接海隅', '太乙近天都连山接海隅', '太乙都天近连山接海隅', 0, NULL, 0, '2026-08-07 15:38:26');
INSERT INTO `poem_rounds` VALUES (45, 277, '刘禹锡', '春词', '[\"新妆宜面下朱楼  深锁春光一院愁\",\"行到中庭数花朵  蜻蜓飞上玉搔头\"]', 0, '新妆宜面下朱楼', '深锁春光一院愁', '新妆宜面下朱楼', '新妆下面宜朱楼', 0, NULL, 0, '2026-08-07 15:39:26');
INSERT INTO `poem_rounds` VALUES (46, 254, '卢纶', '塞下曲四首之三', '[\"月黑雁飞高  单于夜遁逃\",\"欲将轻骑逐  大雪满弓刀\"]', 1, '欲将轻骑逐', '大雪满弓刀', '欲将轻骑逐大雪满弓刀', '欲轻将骑逐大雪满弓刀', 0, NULL, 0, '2026-08-07 15:40:26');
INSERT INTO `poem_rounds` VALUES (47, 300, '李商隐', '贾生', '[\"宣室求贤访逐臣  贾生才调更无伦\",\"可怜夜半虚前席  不问苍生问鬼神\"]', 1, '可怜夜半虚前席', '不问苍生问鬼神', '不问苍生问鬼神', '不问生苍问鬼神', 0, NULL, 0, '2026-08-07 15:41:26');
INSERT INTO `poem_rounds` VALUES (48, 293, '杜牧', '金谷园', '[\"繁华事散逐香尘  流水无情草自春\",\"日暮东风怨啼鸟  落花犹似坠楼人\"]', 0, '繁华事散逐香尘', '流水无情草自春', '繁华事散逐香尘', '事华繁散逐香尘', 0, NULL, 0, '2026-08-07 15:42:26');
INSERT INTO `poem_rounds` VALUES (49, 180, '杜甫', '蜀相', '[\"丞相祠堂何处寻  锦官城外柏森森\",\"映阶碧草自春色  隔叶黄鹂空好音\",\"三顾频烦天下计  两朝开济老臣心\",\"出师未捷身先死  长使英雄泪满襟\"]', 0, '丞相祠堂何处寻', '锦官城外柏森森', '丞相祠堂何处寻', '祠相丞堂寻处何', 0, NULL, 0, '2026-08-07 15:43:26');
INSERT INTO `poem_rounds` VALUES (50, 281, '张祜', '集灵台二首之二', '[\"虢国夫人承主恩  平明骑马入宫门\",\"却嫌脂粉污颜色  淡扫蛾眉朝至尊\"]', 0, '虢国夫人承主恩', '平明骑马入宫门', '虢国夫人承主恩平明骑马入宫门', '虢国夫人入主恩平明门马承宫骑', 0, NULL, 0, '2026-08-07 15:44:26');
INSERT INTO `poem_rounds` VALUES (51, 237, '韦应物', '秋夜寄邱员外', '[\"怀君属秋夜  散步咏凉天\",\"空山松子落  幽人应未眠\"]', 0, '怀君属秋夜', '散步咏凉天', '怀君属秋夜散步咏凉天', '怀君属步夜天秋咏凉散', 0, NULL, 0, '2026-08-07 15:45:28');
INSERT INTO `poem_rounds` VALUES (52, 304, '韦庄', '金陵图', '[\"江雨霏霏江草齐  六朝如梦鸟空啼\",\"无情最是台城柳  依旧烟笼十里堤\"]', 1, '无情最是台城柳', '依旧烟笼十里堤', '无情最是台城柳依旧烟笼十里堤', '旧情最是台城堤依无烟笼十里柳', 0, NULL, 0, '2026-08-07 15:46:28');
INSERT INTO `poem_rounds` VALUES (53, 271, '刘方平', '月夜', '[\"更深月色半人家  北斗阑干南斗斜\",\"今夜偏知春气暖  虫声新透绿窗纱\"]', 1, '今夜偏知春气暖', '虫声新透绿窗纱', '今夜偏知春气暖', '今夜偏知春暖气', 0, NULL, 0, '2026-08-07 15:47:28');
INSERT INTO `poem_rounds` VALUES (54, 125, '孟浩然', '清明日宴梅道士房', '[\"林卧愁春尽  开轩览物华\",\"忽逢青鸟使  邀入赤松家\",\"丹灶初开火  仙桃正发花\",\"童颜若可驻  何惜醉流霞\"]', 3, '童颜若可驻', '何惜醉流霞', '童颜若可驻何惜醉流霞', '驻颜若童可何惜醉流霞', 0, NULL, 0, '2026-08-07 15:48:28');
INSERT INTO `poem_rounds` VALUES (55, 318, '白居易', '无题', '[\"时难年荒世业空  弟兄羁旅各西东\",\"田园寥落干戈后  骨肉流离道路中\",\"吊影分为千里雁  辞根散作九秋蓬\",\"共看明月应垂泪  一夜乡心五处同\"]', 3, '共看明月应垂泪', '一夜乡心五处同', '共看明月应垂泪一夜乡心五处同', '共看垂月应明泪一夜乡心五同处', 0, NULL, 0, '2026-08-07 15:49:28');
INSERT INTO `poem_rounds` VALUES (56, 285, '杜牧', '将赴吴兴登乐游原', '[\"清时有味是无能  闲爱孤云静爱僧\",\"欲把一麾江海去  乐游原上望昭陵\"]', 0, '清时有味是无能', '闲爱孤云静爱僧', '清时有味是无能', '能时无味是有清', 0, NULL, 0, '2026-08-07 15:50:28');
INSERT INTO `poem_rounds` VALUES (57, 87, '杜甫', '丽人行', '[\"三月三日天气新  长安水边多丽人\",\"态浓意远淑且真  肌理细腻骨肉匀\",\"绣罗衣裳照暮春  蹙金孔雀银麒麟\",\"头上何所有  翠微盍叶垂鬓唇\",\"背后何所见  珠压腰［衤及］稳称身\",\"就中云幕椒房亲  赐名大国虢与秦\",\"紫驼之峰出翠釜  水精之盘行素鳞\",\"犀箸餍饫久未下  鸾刀缕切空纷纶\",\"黄门飞［革空］不动尘  御厨络绎送八珍\",\"箫鼓哀吟感鬼神  宾从杂沓实要津\",\"后来鞍马何逡巡  当轩下马入锦茵\",\"杨花雪落覆白苹  青鸟飞去衔红巾\",\"炙手可热势绝伦  慎莫近前丞相嗔\"]', 11, '杨花雪落覆白苹', '青鸟飞去衔红巾', '杨花雪落覆白苹', '杨花覆落雪白苹', 0, NULL, 0, '2026-08-07 15:51:28');
INSERT INTO `poem_rounds` VALUES (58, 12, '杜甫', '梦李白二首之二', '[\"浮云终日行  游子久不至\",\"三夜频梦君  情亲见君意\",\"告归常局促  苦道来不易\",\"江湖多风波  舟楫恐失坠\",\"出门搔白首  若负平生志\",\"冠盖满京华  斯人独憔悴\",\"孰云网恢恢  将老身反累\",\"千秋万岁名  寂寞身后事\"]', 3, '江湖多风波', '舟楫恐失坠', '江湖多风波舟楫恐失坠', '楫湖多风波舟江恐失坠', 0, NULL, 0, '2026-08-07 15:52:28');
INSERT INTO `poem_rounds` VALUES (59, 45, '孟郊', '游子吟', '[\"慈母手中线  游子身上衣\",\"临行密密缝  意恐迟迟归\",\"谁言寸草心  报得三春辉\"]', 0, '慈母手中线', '游子身上衣', '慈母手中线游子身上衣', '子母手中线游慈身上衣', 0, NULL, 0, '2026-08-07 15:53:28');
INSERT INTO `poem_rounds` VALUES (60, 50, '李颀', '听董大弹胡笳声兼寄语弄房给事', '[\"蔡女昔造胡笳声  一弹一十有八拍\",\"胡人落泪沾边草  汉使断肠对归客\",\"古戍苍苍烽火寒  大荒沈沈飞雪白\",\"先拂声弦后角羽  四郊秋叶惊［扌戚］［扌戚］\",\"董夫子，通神明  深山窃听来妖精\",\"言迟更速皆应手  将往复旋如有情\",\"空山百鸟散还合  万里浮云阴且晴\",\"嘶酸雏雁失群夜  断绝胡儿恋母声\",\"川为静其波  鸟亦罢其鸣\",\"乌孙部落家乡远  逻娑沙尘哀怨生\",\"幽音变调忽飘洒  长风吹林雨堕瓦\",\"迸泉飒飒飞木末  野鹿呦呦走堂下\",\"长安城连东掖垣  凤凰池对青琐门\",\"高才脱略名与利  日夕望君抱琴至\"]', 11, '迸泉飒飒飞木末', '野鹿呦呦走堂下', '野鹿呦呦走堂下', '野走呦呦鹿下堂', 0, NULL, 0, '2026-08-07 15:54:28');
INSERT INTO `poem_rounds` VALUES (61, 282, '张祜', '题金陵渡', '[\"金陵津渡小山楼  一宿行人自可愁\",\"潮落夜江斜月里  两三星火是瓜州\"]', 1, '潮落夜江斜月里', '两三星火是瓜州', '潮落夜江斜月里', '潮落夜江斜里月', 0, NULL, 0, '2026-08-07 15:55:28');
INSERT INTO `poem_rounds` VALUES (62, 42, '李白', '子夜四时歌：冬歌', '[\"明朝驿使发  一夜絮征袍\",\"素手抽针冷  那堪把剪刀\",\"裁缝寄远道  几日到临洮\"]', 2, '裁缝寄远道', '几日到临洮', '裁缝寄远道几日到临洮', '裁到寄远道缝日几临洮', 0, NULL, 0, '2026-08-07 15:56:28');
INSERT INTO `poem_rounds` VALUES (63, 119, '王维', '过香积寺', '[\"不知香积寺  数里入云峰\",\"古木无人径  深山何处钟\",\"泉声咽危石  日色冷青松\",\"薄暮空潭曲  安禅制毒龙\"]', 2, '泉声咽危石', '日色冷青松', '泉声咽危石日色冷青松', '泉咽声危石日松冷青色', 0, NULL, 0, '2026-08-07 15:57:28');
INSERT INTO `poem_rounds` VALUES (64, 280, '张祜', '集灵台二首之一', '[\"日光斜照集灵台  红树花迎晓露开\",\"昨夜上皇新授□（“录”加竹头）  太真含笑入帘来\"]', 0, '日光斜照集灵台', '红树花迎晓露开', '日光斜照集灵台', '日斜光照集灵台', 0, NULL, 0, '2026-08-07 15:58:28');
INSERT INTO `poem_rounds` VALUES (65, 280, '张祜', '集灵台二首之一', '[\"日光斜照集灵台  红树花迎晓露开\",\"昨夜上皇新授□（“录”加竹头）  太真含笑入帘来\"]', 0, '日光斜照集灵台', '红树花迎晓露开', '日光斜照集灵台红树花迎晓露开', '集光斜灵日照台红树花迎晓露开', 0, NULL, 0, '2026-08-07 15:59:28');
INSERT INTO `poem_rounds` VALUES (66, 86, '杜甫', '兵车行', '[\"车辚辚，马萧萧  行人弓箭各在腰\",\"耶娘妻子走相送  尘埃不见咸阳桥\",\"牵衣顿足拦道哭  哭声直上干云霄\",\"道旁过者问行人  行人但云点行频\",\"或从十五北防河  便至四十西营田\",\"去时里正与裹头  归来头白还戍边\",\"边亭流血成海水  武皇开边意未已\",\"君不闻\",\"汉家山东二百州  千村万落生荆杞\",\"纵有健妇把锄犁  禾生陇亩无东西\",\"况复秦兵耐苦战  被驱不异犬与鸡\",\"长者虽有问  役夫敢申恨\",\"且如今年冬  未休关西卒\",\"县官急索租  租税从何出\",\"信知生男恶  反是生女好\",\"生女犹得嫁比邻  生男埋没随百草\",\"君不见\",\"青海头  古来白骨无人收\",\"新鬼烦冤旧鬼哭  天阴雨湿声啾啾\"]', 8, '汉家山东二百州', '千村万落生荆杞', '汉家山东二百州千村万落生荆杞', '生家山东杞百州千村万落汉荆二', 0, NULL, 0, '2026-08-07 16:00:28');
INSERT INTO `poem_rounds` VALUES (67, 307, '无名氏', '杂诗', '[\"尽寒食雨草萋萋  著麦苗风柳映堤\",\"等是有家归未得  杜鹃休向耳边啼\"]', 1, '等是有家归未得', '杜鹃休向耳边啼', '等是有家归未得杜鹃休向耳边啼', '是等有未归家得杜鹃休向耳边啼', 0, NULL, 0, '2026-08-07 16:01:28');
INSERT INTO `poem_rounds` VALUES (68, 269, '张继', '枫桥夜泊', '[\"月落乌啼霜满天  江枫渔火对愁眠\",\"姑苏城外寒山寺  夜半钟声到客船\"]', 1, '姑苏城外寒山寺', '夜半钟声到客船', '姑苏城外寒山寺', '姑苏山外寒城寺', 0, NULL, 0, '2026-08-07 16:02:28');
INSERT INTO `poem_rounds` VALUES (69, 199, '皇甫冉', '春思', '[\"莺啼燕语报新年  马邑龙堆路几千\",\"家住层城邻汉苑  心随明月到胡天\",\"机中锦字论长恨  楼上花枝笑独眠\",\"为问天戎窦车骑  何时返旆勒燕然\"]', 2, '机中锦字论长恨', '楼上花枝笑独眠', '机中锦字论长恨楼上花枝笑独眠', '机中锦字论长恨楼独枝花笑上眠', 0, NULL, 0, '2026-08-07 16:03:28');
INSERT INTO `poem_rounds` VALUES (70, 276, '刘禹锡', '乌衣巷', '[\"朱雀桥边野草花  乌衣巷口夕阳斜\",\"旧时王谢堂前燕  飞入寻常百姓家\"]', 1, '旧时王谢堂前燕', '飞入寻常百姓家', '飞入寻常百姓家', '飞入寻常百姓家', 0, NULL, 0, '2026-08-07 16:04:28');
INSERT INTO `poem_rounds` VALUES (71, 200, '卢纶', '晚次鄂州', '[\"云开远见汉阳城  犹是孤帆一日程\",\"估客昼眠知浪静  舟人夜语觉潮生\",\"三湘愁鬓逢秋色  万里归心对月明\",\"旧业已随征战尽  更堪江上鼓鼙声\"]', 1, '估客昼眠知浪静', '舟人夜语觉潮生', '估客昼眠知浪静舟人夜语觉潮生', '估客知浪昼眠静舟人夜语觉潮生', 0, NULL, 0, '2026-08-07 16:05:28');
INSERT INTO `poem_rounds` VALUES (72, 220, '沈全期', '古意呈补阙乔知之', '[\"卢家少妇郁金香  海燕双栖玳瑁梁\",\"九月寒砧催木叶  十年征戍忆辽阳\",\"白狼河北音书断  丹凤城南秋夜长\",\"谁为含愁独不见  更教明月照流黄\"]', 1, '九月寒砧催木叶', '十年征戍忆辽阳', '十年征戍忆辽阳', '十年征戍阳辽忆', 0, NULL, 0, '2026-08-07 16:06:28');
INSERT INTO `poem_rounds` VALUES (73, 287, '杜牧', '泊秦淮', '[\"烟笼寒水月笼沙  夜泊秦淮近酒家\",\"商女不知亡国恨  隔江犹唱后庭花\"]', 1, '商女不知亡国恨', '隔江犹唱后庭花', '商女不知亡国恨隔江犹唱后庭花', '商女不知亡国恨隔江犹花后庭唱', 0, NULL, 0, '2026-08-07 16:07:28');
INSERT INTO `poem_rounds` VALUES (74, 305, '陈陶', '陇西行', '[\"誓扫匈奴不顾身  五千貂锦丧胡尘\",\"可怜无定河边骨  犹是深闺梦里人\"]', 0, '誓扫匈奴不顾身', '五千貂锦丧胡尘', '誓扫匈奴不顾身', '扫誓匈顾不奴身', 0, NULL, 0, '2026-08-07 16:08:28');
INSERT INTO `poem_rounds` VALUES (75, 182, '杜甫', '野望', '[\"西山白雪三城戍  南浦清江万里桥\",\"海内风尘诸弟隔  天涯涕泪一身遥\",\"唯将迟暮供多病  未有涓埃答圣朝\",\"跨马出郊时极目  不堪人事日萧条\"]', 2, '唯将迟暮供多病', '未有涓埃答圣朝', '唯将迟暮供多病', '唯将迟暮供多病', 0, NULL, 0, '2026-08-07 16:09:28');
INSERT INTO `poem_rounds` VALUES (76, 78, '王维', '桃源行', '[\"渔舟逐水爱山春  两岸桃花夹古津\",\"坐看红树不知远  行尽青溪不见人\",\"山口潜行始隈［阝奥］  山开旷望旋平陆\",\"遥看一处攒云树  近入千家散花竹\",\"樵客初传汉姓名  居人未改秦衣服\",\"居人共住武陵源  还从物外起田园\",\"月明松下房栊静  日出云中鸡犬喧\",\"惊闻俗客争来集  竞引还家问都邑\",\"平明闾巷扫花开  薄暮渔樵乘水入\",\"初因避地去人间  及至成仙遂不还\",\"峡里谁知有人事  世中遥望空云山\",\"不疑灵境难闻见  尘心未尽思乡县\",\"出洞无论隔山水  辞家终拟长游衍\",\"自谓经过旧不迷  安知峰壑今来变\",\"当时只记入山深  青溪几曲到云林\",\"春来遍是桃花水  不辨仙源何处寻\"]', 0, '渔舟逐水爱山春', '两岸桃花夹古津', '渔舟逐水爱山春两岸桃花夹古津', '渔舟逐水爱山春花岸桃两夹古津', 0, NULL, 0, '2026-08-07 16:10:28');
INSERT INTO `poem_rounds` VALUES (77, 55, '李白', '金陵酒肆留别', '[\"风吹柳花满店香  吴姬压酒唤客尝\",\"金陵子弟来相送  欲行不行各尽觞\",\"请君试问东流水  别意与之谁短长\"]', 0, '风吹柳花满店香', '吴姬压酒唤客尝', '风吹柳花满店香', '风吹香花柳店满', 0, NULL, 0, '2026-08-07 16:11:28');
INSERT INTO `poem_rounds` VALUES (78, 135, '刘长卿', '寻南溪常山道人隐居', '[\"一路经行处  莓苔见履痕\",\"白云依静渚  春草闭闲门\",\"过雨看松色  随山到水源\",\"溪花与禅意  相对亦忘言\"]', 2, '过雨看松色', '随山到水源', '过雨看松色随山到水源', '过雨随松色看山到水源', 0, NULL, 0, '2026-08-07 16:12:28');
INSERT INTO `poem_rounds` VALUES (79, 77, '王维', '老将行', '[\"少年十五二十时  步行夺得胡马骑\",\"射杀山中白额虎  肯数邺下黄须儿\",\"一身转战三千里  一剑曾当百万师\",\"汉兵奋迅如霹雳  虏骑崩腾畏蒺藜\",\"卫青不败由天幸  李广无功缘数奇\",\"自从弃置便衰朽  世事蹉跎成白首\",\"昔时飞箭无全目  今日垂杨生左肘\",\"路旁时卖故侯瓜  门前学种先生柳\",\"苍茫古木连穷巷  寥落寒山对虚牖\",\"誓令疏勒出飞泉  不似颍川空使酒\",\"贺兰山下阵如云  羽檄交驰日夕闻\",\"节使三河募年少  诏书五道出将军\",\"试拂铁衣如雪色  聊持宝剑动星文\",\"愿得燕弓射大将  耻令越甲鸣吾君\",\"莫嫌旧日云中守  犹堪一战取功勋\"]', 9, '誓令疏勒出飞泉', '不似颍川空使酒', '誓令疏勒出飞泉', '令誓疏勒出泉飞', 0, NULL, 0, '2026-08-07 16:13:28');
INSERT INTO `poem_rounds` VALUES (80, 40, '李白', '子夜四时歌：夏歌', '[\"镜湖三百里  菡萏发荷花\",\"五月西施采  人看隘若耶\",\"回舟不待月  归去越王家\"]', 0, '镜湖三百里', '菡萏发荷花', '镜湖三百里菡萏发荷花', '镜百三湖里菡萏发荷花', 0, NULL, 0, '2026-08-07 16:14:28');
INSERT INTO `poem_rounds` VALUES (81, 174, '高适', '送李少府贬峡中王少府贬长沙', '[\"嗟君此别意何如  驻马衔杯问谪居\",\"巫峡啼猿数行泪  衡阳归雁几封书\",\"青枫江上秋帆远  白帝城边古木疏\",\"圣代即今多雨露  暂时分手莫踌躇\"]', 3, '圣代即今多雨露', '暂时分手莫踌躇', '暂时分手莫踌躇', '暂时踌分莫手躇', 0, NULL, 0, '2026-08-07 16:15:28');
INSERT INTO `poem_rounds` VALUES (82, 183, '杜甫', '闻官军收河南河北', '[\"剑外忽传收蓟北  初闻涕泪满衣裳\",\"却看妻子愁何在  漫卷诗书喜欲狂\",\"白日放歌须纵酒  青春作伴好还乡\",\"即从巴峡穿巫峡  便下襄阳向洛阳\"]', 3, '即从巴峡穿巫峡', '便下襄阳向洛阳', '即从巴峡穿巫峡', '即从巴峡穿巫峡', 0, NULL, 0, '2026-08-07 16:16:28');
INSERT INTO `poem_rounds` VALUES (83, 109, '杜甫', '天末怀李白', '[\"凉风起天末  君子意如何\",\"鸿雁几时到  江湖秋水多\",\"文章憎命达  魑魅喜人过\",\"应共冤魂语  投诗赠汨罗\"]', 3, '应共冤魂语', '投诗赠汨罗', '应共冤魂语投诗赠汨罗', '应共冤诗语投魂赠汨罗', 0, NULL, 0, '2026-08-07 16:17:28');
INSERT INTO `poem_rounds` VALUES (84, 65, '元结', '石鱼湖上醉歌并序', '[\"石鱼湖，似洞庭  夏水欲满君山青\",\"山为樽，水为沼  酒徒历历坐洲鸟\",\"长风连日作大浪  不能废人运酒舫\",\"我持长瓢坐巴丘  酌饮四座以散愁\"]', 2, '长风连日作大浪', '不能废人运酒舫', '不能废人运酒舫', '人能运不废酒舫', 0, NULL, 0, '2026-08-07 16:18:28');
INSERT INTO `poem_rounds` VALUES (85, 1, '张九龄', '感遇四首之一', '[\"孤鸿海上来  池潢不敢顾\",\"侧见双翠鸟  巢在三珠树\",\"矫矫珍木巅  得无金丸惧\",\"美服患人指  高明逼神恶\",\"今我游冥冥  弋者何所慕\"]', 0, '孤鸿海上来', '池潢不敢顾', '孤鸿海上来池潢不敢顾', '孤鸿海上来池潢敢不顾', 0, NULL, 0, '2026-08-07 16:19:28');
INSERT INTO `poem_rounds` VALUES (86, 108, '杜甫', '月夜忆舍弟', '[\"戍鼓断人行  秋边一雁声\",\"露从今夜白  月是故乡明\",\"有弟皆分散  无家问死生\",\"寄书长不达  况乃未休兵\"]', 0, '戍鼓断人行', '秋边一雁声', '戍鼓断人行秋边一雁声', '戍一断人行秋边雁鼓声', 0, NULL, 0, '2026-08-07 16:20:28');
INSERT INTO `poem_rounds` VALUES (87, 268, '韦应物', '滁州西涧', '[\"独怜幽草涧边生  上有黄鹂深树鸣\",\"春潮带雨晚来急  野渡无人舟自横\"]', 0, '独怜幽草涧边生', '上有黄鹂深树鸣', '上有黄鹂深树鸣', '上深黄有鹂树鸣', 0, NULL, 0, '2026-08-07 16:21:28');
INSERT INTO `poem_rounds` VALUES (88, 152, '杜牧', '旅宿', '[\"旅馆无良伴  凝情自悄然\",\"寒灯思旧事  断雁警愁眠\",\"远梦归侵晓  家书到隔年\",\"沧江好烟月  门系钓鱼船\"]', 1, '寒灯思旧事', '断雁警愁眠', '寒灯思旧事断雁警愁眠', '断灯思旧事寒警雁愁眠', 0, NULL, 0, '2026-08-07 16:22:28');
INSERT INTO `poem_rounds` VALUES (89, 241, '柳宗元', '江雪', '[\"千山鸟飞绝  万径人踪灭\",\"孤舟蓑笠翁  独钓寒江雪\"]', 1, '孤舟蓑笠翁', '独钓寒江雪', '孤舟蓑笠翁独钓寒江雪', '孤舟蓑笠寒独钓翁江雪', 0, NULL, 0, '2026-08-07 16:23:28');
INSERT INTO `poem_rounds` VALUES (90, 154, '许浑', '早秋', '[\"遥夜泛清瑟  西风生翠萝\",\"残萤栖玉露  早雁拂银河\",\"高树晓还密  远山晴更多\",\"淮南一叶下  自觉老烟波\"]', 0, '遥夜泛清瑟', '西风生翠萝', '遥夜泛清瑟西风生翠萝', '泛夜遥清瑟西风生翠萝', 0, NULL, 0, '2026-08-07 16:24:28');
INSERT INTO `poem_rounds` VALUES (91, 175, '岑参', '奉和中书舍人贾至早朝大明宫', '[\"鸡鸣紫陌曙光寒  莺啭皇州春色阑\",\"金阙晓钟开万户  玉阶仙仗拥千官\",\"花迎剑佩星初落  柳拂旌旗露未干\",\"独有凤凰池上客  阳春一曲和皆难\"]', 0, '鸡鸣紫陌曙光寒', '莺啭皇州春色阑', '莺啭皇州春色阑', '啭莺皇州春色阑', 0, NULL, 0, '2026-08-07 16:25:28');
INSERT INTO `poem_rounds` VALUES (92, 82, '李白', '行路难三首之一', '[\"金樽清酒斗十千  玉盘珍羞值万钱\",\"停杯投箸不能食  拔剑四顾心茫然\",\"欲渡黄河冰塞川  将登太行雪满山\",\"闲来垂钓碧溪上  忽复乘舟梦日边\",\"行路难，行路难  多歧路，今安在\",\"长风破浪会有时  直挂云帆济沧海\"]', 3, '闲来垂钓碧溪上', '忽复乘舟梦日边', '闲来垂钓碧溪上忽复乘舟梦日边', '闲来垂钓碧边忽上复乘舟梦日溪', 0, NULL, 0, '2026-08-07 16:26:28');
INSERT INTO `poem_rounds` VALUES (93, 224, '王维', '相思', '[\"红豆生南国  春来发几枝\",\"愿君多采撷  此物最相思\"]', 0, '红豆生南国', '春来发几枝', '红豆生南国春来发几枝', '春豆生南国红来发几枝', 0, NULL, 0, '2026-08-07 16:27:28');
INSERT INTO `poem_rounds` VALUES (94, 77, '王维', '老将行', '[\"少年十五二十时  步行夺得胡马骑\",\"射杀山中白额虎  肯数邺下黄须儿\",\"一身转战三千里  一剑曾当百万师\",\"汉兵奋迅如霹雳  虏骑崩腾畏蒺藜\",\"卫青不败由天幸  李广无功缘数奇\",\"自从弃置便衰朽  世事蹉跎成白首\",\"昔时飞箭无全目  今日垂杨生左肘\",\"路旁时卖故侯瓜  门前学种先生柳\",\"苍茫古木连穷巷  寥落寒山对虚牖\",\"誓令疏勒出飞泉  不似颍川空使酒\",\"贺兰山下阵如云  羽檄交驰日夕闻\",\"节使三河募年少  诏书五道出将军\",\"试拂铁衣如雪色  聊持宝剑动星文\",\"愿得燕弓射大将  耻令越甲鸣吾君\",\"莫嫌旧日云中守  犹堪一战取功勋\"]', 10, '贺兰山下阵如云', '羽檄交驰日夕闻', '贺兰山下阵如云羽檄交驰日夕闻', '贺阵山下兰如云交檄羽驰日夕闻', 0, NULL, 0, '2026-08-07 16:28:28');
INSERT INTO `poem_rounds` VALUES (95, 154, '许浑', '早秋', '[\"遥夜泛清瑟  西风生翠萝\",\"残萤栖玉露  早雁拂银河\",\"高树晓还密  远山晴更多\",\"淮南一叶下  自觉老烟波\"]', 1, '残萤栖玉露', '早雁拂银河', '残萤栖玉露早雁拂银河', '残萤栖拂露早玉雁银河', 0, NULL, 0, '2026-08-07 16:29:28');
INSERT INTO `poem_rounds` VALUES (96, 270, '韩□', '寒食', '[\"春城无处不飞花  寒食东风御柳斜\",\"日暮汉宫传蜡烛  轻烟散入五侯家\"]', 0, '春城无处不飞花', '寒食东风御柳斜', '春城无处不飞花寒食东风御柳斜', '春城无处不飞花寒食东柳御风斜', 0, NULL, 0, '2026-08-07 16:30:28');
INSERT INTO `poem_rounds` VALUES (97, 79, '李白', '蜀道难', '[\"噫吁戏  危乎高哉\",\"蜀道之难难于上青天\",\"蚕丛及鱼凫  开国何茫然\",\"尔来四万八千岁  始与秦塞通人烟\",\"西当太白有鸟道  可以横绝峨眉巅\",\"地崩山摧壮士死  然后天梯石栈方钩连\",\"上有六龙回日之高标  下有冲波逆折之回川\",\"黄鹤之飞尚不得  猿猱欲度愁攀援\",\"青泥何盘盘  百步九折萦岩峦\",\"扪参历井仰胁息  以手抚膺坐长叹\",\"问君西游何时还  畏途□（繁体“谗”换山旁）岩不可攀\",\"但见悲鸟号古木  雄飞雌从绕林间\",\"又闻子规啼  夜月愁空山\",\"蜀道之难难于上青天  使人听此凋朱颜\",\"连峰去天不盈尺  枯松倒挂倚绝壁\",\"飞湍瀑流争喧［兀豕］  冰崖转石万壑雷\",\"其险也如此\",\"嗟尔远道之人  胡为乎来哉\",\"剑阁峥嵘而崔嵬\",\"一夫当关  万夫莫开\",\"所守或匪亲  化为狼与豺\",\"朝避猛虎  夕避长蛇\",\"磨牙吮血  杀人如麻\",\"锦城虽云乐  不如早还家\",\"蜀道之难难于上青天  侧身西望常咨嗟\"]', 8, '青泥何盘盘', '百步九折萦岩峦', '青泥何盘盘百步九折萦岩峦', '青泥岩盘盘百步九折萦何峦', 0, NULL, 0, '2026-08-07 16:31:28');
INSERT INTO `poem_rounds` VALUES (98, 248, '西鄙人', '哥舒歌', '[\"北斗七星高  哥舒夜带刀\",\"至今窥牧马  不敢过临洮\"]', 0, '北斗七星高', '哥舒夜带刀', '北斗七星高哥舒夜带刀', '北星七斗高哥舒带夜刀', 0, NULL, 0, '2026-08-07 16:32:28');
INSERT INTO `poem_rounds` VALUES (99, 275, '李益', '夜上受降城闻笛', '[\"回乐峰前沙似雪  受降城外月如霜\",\"不知何处吹芦管  一夜征人尽望乡\"]', 1, '不知何处吹芦管', '一夜征人尽望乡', '不知何处吹芦管一夜征人尽望乡', '尽知何处吹芦管一夜征人不望乡', 0, NULL, 0, '2026-08-07 16:33:28');
INSERT INTO `poem_rounds` VALUES (100, 319, '元稹', '行宫', '[\"寥落古行宫  宫花寂寞红\",\"白头宫女在  闲坐说玄宗\"]', 0, '寥落古行宫', '宫花寂寞红', '寥落古行宫宫花寂寞红', '寥落古行寞宫寂花宫红', 0, NULL, 0, '2026-08-07 16:34:28');
INSERT INTO `poem_rounds` VALUES (101, 66, '韩愈', '山石', '[\"山石荦确行径微  黄昏到寺蝙蝠飞\",\"升堂坐阶新雨足  芭蕉叶大栀子肥\",\"僧言古壁佛画好  以火来照所见稀\",\"铺床拂席置羹饭  疏粝亦足饱我饥\",\"夜深静卧百虫绝  清月出岭光入扉\",\"天明独去无道路  出入高下穷烟霏\",\"山红涧碧纷烂漫  时见松枥皆十围\",\"当流赤足蹋涧石  水声激激风吹衣\",\"人生如此自可乐  岂必局束为人［革几］\",\"嗟哉吾党二三子  安得至老不更归\"]', 7, '当流赤足蹋涧石', '水声激激风吹衣', '当流赤足蹋涧石', '涧流赤足蹋当石', 0, NULL, 0, '2026-08-07 16:35:28');
INSERT INTO `poem_rounds` VALUES (102, 221, '王维', '鹿柴', '[\"空山不见人  但闻人语响\",\"返景入深林  复照青苔上\"]', 1, '返景入深林', '复照青苔上', '返景入深林复照青苔上', '返景苔上林复照青入深', 0, NULL, 0, '2026-08-07 16:36:28');
INSERT INTO `poem_rounds` VALUES (103, 54, '李白', '梦游天姥吟留别', '[\"海客谈瀛洲  烟涛微茫信难求\",\"越人语天姥  云霓明灭或可睹\",\"天姥连天向天横  势拔五岳掩赤城\",\"天台四万八千丈  对此欲倒东南倾\",\"我欲因之梦吴越  一夜飞渡镜湖月\",\"湖月照我影  送我至剡溪\",\"谢公宿处今尚在  渌水荡漾清猿啼\",\"脚著谢公屐  身登青云梯\",\"半壁见海日  空中闻天鸡\",\"千岩万壑路不定  迷花倚石忽已暝\",\"熊咆龙吟殷岩泉  栗深林兮惊层巅\",\"云青青兮欲雨  水澹澹兮生烟\",\"裂缺霹雳  丘峦崩摧\",\"洞天石扇  訇然中开\",\"青冥浩荡不见底  日月照耀金银台\",\"霓为衣兮风为马  云之君兮纷纷而来下\",\"虎鼓瑟兮鸾回车  仙之人兮列如麻\",\"忽魂悸以魄动  恍惊起而长嗟\",\"惟觉时之枕席  失向来之烟霞\",\"世间行乐亦如此  古来万事东流水\",\"别君去兮何时还  且放白鹿青崖间\",\"须行即骑访名山\",\"安能摧眉折腰事权贵  使我不得开心颜\"]', 7, '脚著谢公屐', '身登青云梯', '脚著谢公屐身登青云梯', '梯著谢公屐身登青云脚', 0, NULL, 0, '2026-08-07 16:37:28');
INSERT INTO `poem_rounds` VALUES (104, 191, '杜甫', '咏怀古迹五首之四', '[\"蜀主征吴幸三峡  崩年亦在永安宫\",\"翠华想像空山里  玉殿虚无野寺中\",\"古庙杉松巢水鹤  岁时伏腊走村翁\",\"武侯祠屋常邻近  一体君臣祭祀同\"]', 3, '武侯祠屋常邻近', '一体君臣祭祀同', '武侯祠屋常邻近', '武祠屋侯常邻近', 0, NULL, 0, '2026-08-07 16:38:28');
INSERT INTO `poem_rounds` VALUES (105, 236, '刘长卿', '送上人', '[\"孤云将野鹤  岂向人间\",\"莫买沃洲山  时人已知处\"]', 0, '孤云将野鹤', '岂向人间', '孤云将野鹤岂向人间', '孤云将人鹤岂向野间', 0, NULL, 0, '2026-08-07 16:39:28');
INSERT INTO `poem_rounds` VALUES (106, 66, '韩愈', '山石', '[\"山石荦确行径微  黄昏到寺蝙蝠飞\",\"升堂坐阶新雨足  芭蕉叶大栀子肥\",\"僧言古壁佛画好  以火来照所见稀\",\"铺床拂席置羹饭  疏粝亦足饱我饥\",\"夜深静卧百虫绝  清月出岭光入扉\",\"天明独去无道路  出入高下穷烟霏\",\"山红涧碧纷烂漫  时见松枥皆十围\",\"当流赤足蹋涧石  水声激激风吹衣\",\"人生如此自可乐  岂必局束为人［革几］\",\"嗟哉吾党二三子  安得至老不更归\"]', 0, '山石荦确行径微', '黄昏到寺蝙蝠飞', '山石荦确行径微', '山荦微确行径石', 0, NULL, 0, '2026-08-07 16:40:28');
INSERT INTO `poem_rounds` VALUES (107, 104, '李白', '夜泊牛渚怀古', '[\"牛渚西江夜  青天无片云\",\"登舟望秋月  空忆谢将军\",\"余亦能高咏  斯人不可闻\",\"明朝挂帆席  枫叶落纷纷\"]', 0, '牛渚西江夜', '青天无片云', '牛渚西江夜青天无片云', '青渚西江夜牛天无片云', 0, NULL, 0, '2026-08-07 16:41:28');
INSERT INTO `poem_rounds` VALUES (108, 71, '白居易', '长恨歌', '[\"汉皇重色思倾国  御宇多年求不得\",\"杨家有女初长成  养在深闺人未识\",\"天生丽质难自弃  一朝选在君王侧\",\"回眸一笑百媚生  六宫粉黛无颜色\",\"春寒赐浴华清池  温泉水滑洗凝脂\",\"侍儿扶起娇无力  始是新承恩泽时\",\"云鬓花颜金步摇  芙蓉帐暖度春宵\",\"春宵苦短日高起  从此君王不早朝\",\"承欢侍宴无闲暇  春从春游夜专夜\",\"后宫佳丽三千人  三千宠爱在一身\",\"金星妆成娇侍夜  玉楼宴罢醉和春\",\"姊妹弟兄皆列士  可怜光彩生门户\",\"遂令天下父母心  不重生男重生女\",\"骊宫高处入青云  仙乐风飘处处闻\",\"缓歌慢舞凝丝竹  尽日君王看不足\",\"渔阳鼙鼓动地来  惊破霓裳羽衣曲\",\"九重城阙烟尘生  千乘万骑西南行\",\"翠华摇摇行复止  西出都门百馀里\",\"六军不发无奈何  宛转蛾眉马前死\",\"花钿委地无人收  翠翘金雀玉搔头\",\"君王掩面救不得  回看血泪相和流\",\"黄埃散漫风萧索  云栈萦纡登剑阁\",\"峨嵋山下少人行  旌旗无光日色薄\",\"蜀江水碧蜀山青  圣主朝朝暮暮情\",\"行宫见月伤心色  夜雨闻铃肠断声\",\"天旋地转回龙驭  到此踌躇不能去\",\"马嵬坡下泥土中  不见玉颜空死处\",\"君臣相顾尽沾衣  东望都门信马归\",\"归来池苑皆依旧  太液芙蓉未央柳\",\"芙蓉如面柳如眉  对此如何不泪垂\",\"春风桃李花开日  秋雨梧桐叶落时\",\"西宫南内多秋草  落叶满阶红不扫\",\"梨园子弟白发新  椒房阿监青娥老\",\"夕殿萤飞思悄然  孤灯挑尽未成眠\",\"迟迟钟鼓初长夜  耿耿星河欲曙天\",\"鸳鸯瓦冷霜华重  翡翠衾寒谁与共\",\"悠悠生死别经年  魂魄不曾来入梦\",\"临邛道士鸿都客  能以精诚致魂魄\",\"为感君王辗转思  遂教方士殷勤觅\",\"排空驭气奔如电  升天入地求之遍\",\"上穷碧落下黄泉  两处茫茫皆不见\",\"忽闻海上有仙山  山在虚无缥缈间\",\"楼阁玲珑五云起  其中绰约多仙子\",\"中有一人字太真  雪肤花貌参差是\",\"金阙西厢叩玉扃  转教小玉报双成\",\"闻道汉家天子使  九华帐里梦魂惊\",\"揽衣推枕起徘徊  珠箔银屏迤逦开\",\"云鬓半偏新睡觉  花冠不整下堂来\",\"风吹仙袂飘飘举  犹似霓裳羽衣舞\",\"玉容寂寞泪阑干  梨花一枝春带雨\",\"含情凝睇谢君王  一别音容两渺茫\",\"昭阳殿里恩爱绝  蓬莱宫中日月长\",\"回头下望人寰处  不见长安见尘雾\",\"唯将旧物表深情  钿合金钗寄将去\",\"钗留一股合一扇  钗擘黄金合分钿\",\"但教心似金钿坚  天上人间会相见\",\"临别殷勤重寄词  词中有誓两心知\",\"七月七日长生殿  夜半无人私语时\",\"在天愿作比翼鸟  在地愿为连理枝\",\"天长地久有时尽  此恨绵绵无绝期\"]', 3, '回眸一笑百媚生', '六宫粉黛无颜色', '回眸一笑百媚生六宫粉黛无颜色', '回眸一粉百媚生六宫笑黛无颜色', 0, NULL, 0, '2026-08-07 16:42:28');
INSERT INTO `poem_rounds` VALUES (109, 15, '王维', '青溪', '[\"言入黄花川  每逐青溪水\",\"随山将万转  趣途无百里\",\"声喧乱石中  色静深松里\",\"漾漾泛菱荇  澄澄映葭苇\",\"我心素已闲  清川澹如此\",\"请留盘石上  垂钓将已矣\"]', 3, '漾漾泛菱荇', '澄澄映葭苇', '漾漾泛菱荇澄澄映葭苇', '漾菱泛漾荇澄澄映葭苇', 0, NULL, 0, '2026-08-07 16:43:28');
INSERT INTO `poem_rounds` VALUES (110, 160, '温庭筠', '送人东游', '[\"荒戍落黄叶  浩然离故关\",\"高风汉阳渡  初日郢门山\",\"江上几人在  天涯孤棹还\",\"何当重相见  樽酒慰离颜\"]', 2, '江上几人在', '天涯孤棹还', '江上几人在天涯孤棹还', '上江几人在天孤涯棹还', 0, NULL, 0, '2026-08-07 16:44:28');
INSERT INTO `poem_rounds` VALUES (111, 38, '李白', '关山月', '[\"明月出天山  苍茫云海间\",\"长风几万里  吹度玉门关\",\"汉下白登道  胡窥青海湾\",\"由来征战地  不见有人还\",\"戍客望边色  思归多苦颜\",\"高楼当此夜  叹息未应闲\"]', 0, '明月出天山', '苍茫云海间', '明月出天山苍茫云海间', '茫月出山天苍明云海间', 0, NULL, 0, '2026-08-07 16:45:28');
INSERT INTO `poem_rounds` VALUES (112, 207, '李商隐', '无题', '[\"昨夜星辰昨夜风  画楼西畔桂堂东\",\"身无彩凤双飞翼  心有灵犀一点通\",\"隔座送钩春酒暖  分曹射覆蜡灯红\",\"嗟余听鼓应官去  走马兰台类转蓬\"]', 0, '昨夜星辰昨夜风', '画楼西畔桂堂东', '画楼西畔桂堂东', '东楼西畔桂堂画', 0, NULL, 0, '2026-08-07 16:46:28');
INSERT INTO `poem_rounds` VALUES (113, 139, '韦应物', '淮上喜会梁川故人', '[\"江汉曾为客  相逢每醉还\",\"浮云一别后  流水十年间\",\"欢笑情如旧  萧疏鬓已斑\",\"何因北归去  淮上对秋山\"]', 2, '欢笑情如旧', '萧疏鬓已斑', '欢笑情如旧萧疏鬓已斑', '欢笑情如斑萧疏鬓已旧', 0, NULL, 0, '2026-08-07 16:47:28');
INSERT INTO `poem_rounds` VALUES (114, 147, '司空曙', '喜外弟卢纶见宿', '[\"静夜四无邻  荒居旧业贫\",\"雨中黄叶树  灯下白头人\",\"以我独沉久  愧君相访频\",\"平生自有分  况是蔡家亲\"]', 2, '以我独沉久', '愧君相访频', '以我独沉久愧君相访频', '君沉独我久愧以相访频', 0, NULL, 0, '2026-08-07 16:48:28');
INSERT INTO `poem_rounds` VALUES (115, 316, '杜秋娘', '金缕衣', '[\"劝君莫惜金缕衣  劝君惜取少年时\",\"花开堪折直须折  莫待无花空折枝\"]', 1, '花开堪折直须折', '莫待无花空折枝', '莫待无花空折枝', '莫待枝花空折无', 0, NULL, 0, '2026-08-07 16:49:28');
INSERT INTO `poem_rounds` VALUES (116, 199, '皇甫冉', '春思', '[\"莺啼燕语报新年  马邑龙堆路几千\",\"家住层城邻汉苑  心随明月到胡天\",\"机中锦字论长恨  楼上花枝笑独眠\",\"为问天戎窦车骑  何时返旆勒燕然\"]', 3, '为问天戎窦车骑', '何时返旆勒燕然', '为问天戎窦车骑', '为问骑戎窦车天', 0, NULL, 0, '2026-08-07 16:50:28');
INSERT INTO `poem_rounds` VALUES (117, 50, '李颀', '听董大弹胡笳声兼寄语弄房给事', '[\"蔡女昔造胡笳声  一弹一十有八拍\",\"胡人落泪沾边草  汉使断肠对归客\",\"古戍苍苍烽火寒  大荒沈沈飞雪白\",\"先拂声弦后角羽  四郊秋叶惊［扌戚］［扌戚］\",\"董夫子，通神明  深山窃听来妖精\",\"言迟更速皆应手  将往复旋如有情\",\"空山百鸟散还合  万里浮云阴且晴\",\"嘶酸雏雁失群夜  断绝胡儿恋母声\",\"川为静其波  鸟亦罢其鸣\",\"乌孙部落家乡远  逻娑沙尘哀怨生\",\"幽音变调忽飘洒  长风吹林雨堕瓦\",\"迸泉飒飒飞木末  野鹿呦呦走堂下\",\"长安城连东掖垣  凤凰池对青琐门\",\"高才脱略名与利  日夕望君抱琴至\"]', 8, '川为静其波', '鸟亦罢其鸣', '川为静其波鸟亦罢其鸣', '川为静其波鸟亦罢鸣其', 0, NULL, 0, '2026-08-07 16:51:28');
INSERT INTO `poem_rounds` VALUES (118, 113, '杜甫', '登岳阳楼', '[\"昔闻洞庭水  今上岳阳楼\",\"吴楚东南坼  乾坤日夜浮\",\"亲朋无一字  老病有孤舟\",\"戎马关山北  凭轩涕泗流\"]', 0, '昔闻洞庭水', '今上岳阳楼', '昔闻洞庭水今上岳阳楼', '昔闻岳庭水今上洞楼阳', 0, NULL, 0, '2026-08-07 16:52:28');
INSERT INTO `poem_rounds` VALUES (119, 149, '刘禹锡', '蜀先主庙', '[\"天地英雄气  千秋尚凛然\",\"势分三足鼎  业复五铢钱\",\"得相能开国  生儿不象贤\",\"凄凉蜀故妓  来舞魏宫前\"]', 0, '天地英雄气', '千秋尚凛然', '天地英雄气千秋尚凛然', '雄地英天秋千气尚凛然', 0, NULL, 0, '2026-08-07 16:53:28');
INSERT INTO `poem_rounds` VALUES (120, 14, '王维', '送綦毋潜落第还乡', '[\"圣代无隐者  英灵尽来归\",\"遂令东山客  不得顾采薇\",\"既至金门远  孰云吾道非\",\"江淮度寒食  京洛缝春衣\",\"置酒长安道  同心与我违\",\"行当浮桂棹  未几拂荆扉\",\"远树带行客  孤城当落晖\",\"吾谋适不用  勿谓知音稀\"]', 6, '远树带行客', '孤城当落晖', '远树带行客孤城当落晖', '城树带行客晖远当落孤', 0, NULL, 0, '2026-08-07 16:54:28');
INSERT INTO `poem_rounds` VALUES (121, 63, '杜甫', '古柏行', '[\"孔明庙前有老柏  柯如青铜根如石\",\"双皮溜雨四十围  黛色参天二千尺\",\"君臣已与时际会  树木犹为人爱惜\",\"云来气接巫峡长  月出寒通雪山白\",\"忆昨路绕锦亭东  先主武侯同［门必］宫\",\"崔嵬枝干郊原古  窈窕丹青户牖空\",\"落落盘踞虽得地  冥冥孤高多烈风\",\"扶持自是神明力  正直元因造化功\",\"大厦如倾要梁栋  万牛回首丘山重\",\"不露文章世已惊  未辞剪伐谁能送\",\"苦心岂免容蝼蚁  香叶终经宿鸾凤\",\"志士幽人莫怨嗟  古来材大难为用\"]', 0, '孔明庙前有老柏', '柯如青铜根如石', '孔明庙前有老柏', '孔明前庙有老柏', 0, NULL, 0, '2026-08-07 16:55:28');
INSERT INTO `poem_rounds` VALUES (122, 265, '李白', '下江陵', '[\"朝辞白帝彩云间  千里江陵一日还\",\"两岸猿声啼不住  轻舟已过万重山\"]', 1, '两岸猿声啼不住', '轻舟已过万重山', '两岸猿声啼不住', '两猿岸声啼不住', 0, NULL, 0, '2026-08-07 16:56:28');
INSERT INTO `poem_rounds` VALUES (123, 239, '王建', '新嫁娘', '[\"三日入厨下  洗手作羹汤\",\"未谙姑食性  先遣小姑尝\"]', 0, '三日入厨下', '洗手作羹汤', '三日入厨下洗手作羹汤', '羹日入作下洗手厨三汤', 0, NULL, 0, '2026-08-07 16:57:28');
INSERT INTO `poem_rounds` VALUES (124, 61, '杜甫', '丹青引赠曹霸将军', '[\"将军魏武之子孙  于今为庶为青门\",\"英雄割据虽已矣  文采风流今尚存\",\"学书初学卫夫人  但恨无过王右军\",\"丹青不知老将至  富贵于我如浮云\",\"开元之中常引见  承恩数上南熏殿\",\"凌烟功臣少颜色  将军下笔开生面\",\"良相头上进贤冠  猛将腰间大羽箭\",\"褒公鄂公毛发动  英姿飒爽犹酣战\",\"先帝天马玉花骢  画工如山貌不同\",\"是日牵来赤墀下  迥立阊阖生长风\",\"诏谓将军拂绢素  意匠惨淡经营中\",\"斯须九重真龙出  一洗万古凡马空\",\"玉花却在御榻上  榻上庭前屹相向\",\"至尊含笑催赐金  圉人太仆皆惆怅\",\"弟子韩干早入室  亦能画马穷殊相\",\"干惟画肉不画骨  忍使骅骝气凋丧\",\"将军画善盖有神  偶逢佳士亦写真\",\"即今漂泊干戈际  屡貌寻常行路人\",\"涂穷反遭俗眼白  世上未有如公贫\",\"但看古来盛名下  终日坎［土禀］缠其身\"]', 3, '丹青不知老将至', '富贵于我如浮云', '丹青不知老将至', '不青丹知至将老', 0, NULL, 0, '2026-08-07 16:58:28');
INSERT INTO `poem_rounds` VALUES (125, 7, '李白', '春思', '[\"燕草如碧丝  秦桑低绿枝\",\"当君怀归日  是妾断肠时\",\"春风不相识  何事入罗帏\"]', 0, '燕草如碧丝', '秦桑低绿枝', '燕草如碧丝秦桑低绿枝', '燕如草碧丝秦桑低绿枝', 0, NULL, 0, '2026-08-07 16:59:28');
INSERT INTO `poem_rounds` VALUES (126, 206, '李商隐', '锦瑟', '[\"锦瑟无端五十弦  一弦一柱思华年\",\"庄生晓梦迷蝴蝶  望帝春心托杜鹃\",\"沧海月明珠有泪  蓝田日暖玉生烟\",\"此情可待成追忆  只是当时已惘然\"]', 1, '庄生晓梦迷蝴蝶', '望帝春心托杜鹃', '庄生晓梦迷蝴蝶望帝春心托杜鹃', '庄生晓梦迷春蝶望帝蝴心托杜鹃', 0, NULL, 0, '2026-08-07 17:00:28');
INSERT INTO `poem_rounds` VALUES (127, 123, '孟浩然', '望洞庭湖赠张丞相', '[\"八月湖水平  涵虚混太清\",\"气蒸云梦泽  波撼岳阳城\",\"欲济无舟楫  端居耻圣明\",\"坐观垂钓者  空有羡鱼情\"]', 1, '气蒸云梦泽', '波撼岳阳城', '气蒸云梦泽波撼岳阳城', '岳蒸云梦泽城撼气阳波', 0, NULL, 0, '2026-08-07 17:01:28');
INSERT INTO `poem_rounds` VALUES (128, 304, '韦庄', '金陵图', '[\"江雨霏霏江草齐  六朝如梦鸟空啼\",\"无情最是台城柳  依旧烟笼十里堤\"]', 0, '江雨霏霏江草齐', '六朝如梦鸟空啼', '江雨霏霏江草齐', '江霏霏雨江草齐', 0, NULL, 0, '2026-08-07 17:02:28');
INSERT INTO `poem_rounds` VALUES (129, 181, '杜甫', '客至', '[\"舍南舍北皆春水  但见群鸥日日来\",\"花径不曾缘客扫  蓬门今始为君开\",\"盘飧市远无兼味  樽酒家贫只旧醅\",\"肯与邻翁相对饮  隔篱呼取尽馀杯\"]', 3, '肯与邻翁相对饮', '隔篱呼取尽馀杯', '隔篱呼取尽馀杯', '馀取呼篱尽隔杯', 0, NULL, 0, '2026-08-07 17:03:28');
INSERT INTO `poem_rounds` VALUES (130, 273, '柳中庸', '征人怨', '[\"岁岁金河复玉关  朝朝马策与刀环\",\"三春白雪归青冢  万里黄河绕黑山\"]', 0, '岁岁金河复玉关', '朝朝马策与刀环', '岁岁金河复玉关朝朝马策与刀环', '岁岁金河复关玉朝朝马策与刀环', 0, NULL, 0, '2026-08-07 17:04:28');
INSERT INTO `poem_rounds` VALUES (131, 110, '杜甫', '奉济驿重送严公四韵', '[\"远送从此别  青山空复情\",\"几时杯重把  昨夜月同行\",\"列郡讴歌惜  三朝出入荣\",\"将村独归处  寂寞养残生\"]', 2, '列郡讴歌惜', '三朝出入荣', '列郡讴歌惜三朝出入荣', '列郡讴歌三惜朝出入荣', 0, NULL, 0, '2026-08-07 17:05:28');
INSERT INTO `poem_rounds` VALUES (132, 44, '孟郊', '烈女操', '[\"梧桐相待老  鸳鸯会双死\",\"贞妇贵殉夫  舍生亦如此\",\"波澜誓不起  妾心井中水\"]', 0, '梧桐相待老', '鸳鸯会双死', '梧桐相待老鸳鸯会双死', '梧鸳相桐老待鸯会双死', 0, NULL, 0, '2026-08-07 17:06:28');
INSERT INTO `poem_rounds` VALUES (133, 207, '李商隐', '无题', '[\"昨夜星辰昨夜风  画楼西畔桂堂东\",\"身无彩凤双飞翼  心有灵犀一点通\",\"隔座送钩春酒暖  分曹射覆蜡灯红\",\"嗟余听鼓应官去  走马兰台类转蓬\"]', 2, '隔座送钩春酒暖', '分曹射覆蜡灯红', '分曹射覆蜡灯红', '分曹蜡覆射灯红', 0, NULL, 0, '2026-08-07 17:07:28');
INSERT INTO `poem_rounds` VALUES (134, 317, '杜甫', '无题', '[\"此道昔归顺  西郊胡正繁\",\"至今残破胆  应有未招魂\",\"近得归京邑  移官岂至尊\",\"无才日衰老  驻马望千门\"]', 1, '至今残破胆', '应有未招魂', '至今残破胆应有未招魂', '至今残应胆破有未招魂', 0, NULL, 0, '2026-08-07 17:08:28');
INSERT INTO `poem_rounds` VALUES (135, 271, '刘方平', '月夜', '[\"更深月色半人家  北斗阑干南斗斜\",\"今夜偏知春气暖  虫声新透绿窗纱\"]', 0, '更深月色半人家', '北斗阑干南斗斜', '更深月色半人家北斗阑干南斗斜', '更深月阑半人家北斗色干南斗斜', 0, NULL, 0, '2026-08-07 17:09:28');
INSERT INTO `poem_rounds` VALUES (136, 142, '刘脊虚', '阙题', '[\"道由白云尽  春与青溪长\",\"时有落花至  远隋流水香\",\"闲门向山路  深柳读书堂\",\"幽映每白日  清辉照衣裳\"]', 3, '幽映每白日', '清辉照衣裳', '幽映每白日清辉照衣裳', '幽映裳白日清辉照衣每', 0, NULL, 0, '2026-08-07 17:10:28');
INSERT INTO `poem_rounds` VALUES (137, 146, '司空曙', '云阳馆与韩绅宿别', '[\"故人江海别  几度隔山川\",\"乍见翻疑梦  相悲各问年\",\"孤灯寒照雨  深竹暗浮烟\",\"更有明朝恨  离杯惜共传\"]', 0, '故人江海别', '几度隔山川', '故人江海别几度隔山川', '别人江海故几度隔山川', 0, NULL, 0, '2026-08-07 17:11:28');
INSERT INTO `poem_rounds` VALUES (138, 262, '王昌龄', '春宫曲', '[\"昨夜风开露井桃  未央前殿月轮高\",\"平阳歌舞新承宠  帘外春寒赐锦袍\"]', 1, '平阳歌舞新承宠', '帘外春寒赐锦袍', '平阳歌舞新承宠', '阳平歌舞新承宠', 0, NULL, 0, '2026-08-07 17:12:28');
INSERT INTO `poem_rounds` VALUES (139, 94, '杜审言', '和晋陵路丞早春游望', '[\"独有宦游人  偏惊物候新\",\"云霞出海曙  梅柳渡江春\",\"淑气催黄鸟  晴光转绿苹\",\"忽闻歌古调  归思欲沾巾\"]', 2, '淑气催黄鸟', '晴光转绿苹', '淑气催黄鸟晴光转绿苹', '淑气催黄鸟晴苹转绿光', 0, NULL, 0, '2026-08-07 17:13:28');
INSERT INTO `poem_rounds` VALUES (140, 239, '王建', '新嫁娘', '[\"三日入厨下  洗手作羹汤\",\"未谙姑食性  先遣小姑尝\"]', 1, '未谙姑食性', '先遣小姑尝', '未谙姑食性先遣小姑尝', '未谙姑食性遣先小姑尝', 0, NULL, 0, '2026-08-07 17:14:28');
INSERT INTO `poem_rounds` VALUES (141, 2, '张九龄', '感遇四首之二', '[\"兰叶春葳蕤  桂华秋皎洁\",\"欣欣此生意  自尔为佳节\",\"谁知林栖者  闻风坐相悦\",\"草木有本心  何求美人折\"]', 2, '谁知林栖者', '闻风坐相悦', '谁知林栖者闻风坐相悦', '谁知林者栖闻风坐相悦', 0, NULL, 0, '2026-08-07 17:15:28');
INSERT INTO `poem_rounds` VALUES (142, 180, '杜甫', '蜀相', '[\"丞相祠堂何处寻  锦官城外柏森森\",\"映阶碧草自春色  隔叶黄鹂空好音\",\"三顾频烦天下计  两朝开济老臣心\",\"出师未捷身先死  长使英雄泪满襟\"]', 2, '三顾频烦天下计', '两朝开济老臣心', '三顾频烦天下计', '下顾频烦计三天', 0, NULL, 0, '2026-08-07 17:16:30');
INSERT INTO `poem_rounds` VALUES (143, 11, '杜甫', '梦李白二首之一', '[\"死别已吞声  生别常恻恻\",\"江南瘴疠地  逐客无消息\",\"故人入我梦  明我长相忆\",\"君今在罗网  何以有羽翼\",\"恐非平生魂  路远不可测\",\"魂来枫林青  魂返关塞黑\",\"落月满屋梁  犹疑照颜色\",\"水深波浪阔  无使蛟龙得\"]', 1, '江南瘴疠地', '逐客无消息', '江南瘴疠地逐客无消息', '江南瘴地疠逐客无消息', 0, NULL, 0, '2026-08-07 17:17:30');
INSERT INTO `poem_rounds` VALUES (144, 206, '李商隐', '锦瑟', '[\"锦瑟无端五十弦  一弦一柱思华年\",\"庄生晓梦迷蝴蝶  望帝春心托杜鹃\",\"沧海月明珠有泪  蓝田日暖玉生烟\",\"此情可待成追忆  只是当时已惘然\"]', 2, '沧海月明珠有泪', '蓝田日暖玉生烟', '蓝田日暖玉生烟', '日田蓝暖生玉烟', 0, NULL, 0, '2026-08-07 17:18:30');
INSERT INTO `poem_rounds` VALUES (145, 291, '杜牧', '赠别二首之一', '[\"娉娉袅袅十三馀  豆蔻梢头二月初\",\"春风十里扬州路  卷上珠帘总不如\"]', 0, '娉娉袅袅十三馀', '豆蔻梢头二月初', '娉娉袅袅十三馀', '十娉袅袅娉三馀', 0, NULL, 0, '2026-08-07 17:19:30');
INSERT INTO `poem_rounds` VALUES (146, 96, '宋之问', '题大庾岭北驿', '[\"阳月南飞雁  传闻至此回\",\"我行殊未已  何日复归来\",\"江静潮初落  林昏瘴不开\",\"明朝望乡处  应见陇头梅\"]', 0, '阳月南飞雁', '传闻至此回', '阳月南飞雁传闻至此回', '阳月南飞闻传雁至此回', 0, NULL, 0, '2026-08-07 17:20:30');
INSERT INTO `poem_rounds` VALUES (147, 270, '韩□', '寒食', '[\"春城无处不飞花  寒食东风御柳斜\",\"日暮汉宫传蜡烛  轻烟散入五侯家\"]', 1, '日暮汉宫传蜡烛', '轻烟散入五侯家', '日暮汉宫传蜡烛', '日暮汉蜡传宫烛', 0, NULL, 0, '2026-08-07 17:21:30');
INSERT INTO `poem_rounds` VALUES (148, 96, '宋之问', '题大庾岭北驿', '[\"阳月南飞雁  传闻至此回\",\"我行殊未已  何日复归来\",\"江静潮初落  林昏瘴不开\",\"明朝望乡处  应见陇头梅\"]', 2, '江静潮初落', '林昏瘴不开', '江静潮初落林昏瘴不开', '江静潮初落开昏瘴不林', 0, NULL, 0, '2026-08-07 17:22:30');
INSERT INTO `poem_rounds` VALUES (149, 287, '杜牧', '泊秦淮', '[\"烟笼寒水月笼沙  夜泊秦淮近酒家\",\"商女不知亡国恨  隔江犹唱后庭花\"]', 0, '烟笼寒水月笼沙', '夜泊秦淮近酒家', '夜泊秦淮近酒家', '泊夜秦淮近酒家', 0, NULL, 0, '2026-08-07 17:23:30');
INSERT INTO `poem_rounds` VALUES (150, 143, '戴叔伦', '江乡故人偶集客舍', '[\"天秋月又满  城阙夜千重\",\"还作江南会  翻疑梦里逢\",\"风枝惊暗鹊  露草覆寒虫\",\"羁旅长堪醉  相留畏晓钟\"]', 1, '还作江南会', '翻疑梦里逢', '还作江南会翻疑梦里逢', '翻作江里会还疑梦南逢', 0, NULL, 0, '2026-08-07 17:24:30');
INSERT INTO `poem_rounds` VALUES (151, 67, '韩愈', '八月十五夜赠张功曹', '[\"纤云四卷天无河  清风吹空月舒波\",\"沙平水息声影绝  一杯相属君当歌\",\"君歌声酸辞且苦  不能听终泪如雨\",\"洞庭连天九嶷高  蛟龙出没猩鼯号\",\"十生九死到官所  幽居默默如藏逃\",\"下床畏蛇食畏药  海气湿蛰熏腥臊\",\"昨者州前槌大鼓  嗣皇继圣登夔皋\",\"赦书一日行万里  罪从大辟皆除死\",\"迁者追回流者还  涤瑕荡垢清朝班\",\"州家申名使家抑  坎轲只得移荆蛮\",\"判司卑官不堪说  未免捶楚尘埃间\",\"同时辈流多上道  天路幽险难追攀\",\"君歌且休听我歌  我歌今与君殊科\",\"一年明月今宵多  人生由命非由他\",\"有酒不饮奈明何\"]', 3, '洞庭连天九嶷高', '蛟龙出没猩鼯号', '蛟龙出没猩鼯号', '鼯龙出号猩蛟没', 0, NULL, 0, '2026-08-07 17:25:32');
INSERT INTO `poem_rounds` VALUES (152, 25, '岑参', '与高适薛据登慈恩寺浮图', '[\"塔势如涌出  孤高耸天宫\",\"登临出世界  磴道盘虚空\",\"突兀压神州  峥嵘如鬼工\",\"四角碍白日  七层摩苍穹\",\"下窥指高鸟  俯听闻惊风\",\"连山若波涛  奔凑如朝东\",\"青槐夹驰道  宫馆何玲珑\",\"秋色从西来  苍然满关中\",\"五陵北原上  万古青蒙蒙\",\"净理了可悟  胜因夙所宗\",\"誓将挂冠去  觉道资无穷\"]', 5, '连山若波涛', '奔凑如朝东', '连山若波涛奔凑如朝东', '东山若波涛奔凑如朝连', 0, NULL, 0, '2026-08-07 17:26:32');
INSERT INTO `poem_rounds` VALUES (153, 319, '元稹', '行宫', '[\"寥落古行宫  宫花寂寞红\",\"白头宫女在  闲坐说玄宗\"]', 1, '白头宫女在', '闲坐说玄宗', '白头宫女在闲坐说玄宗', '白头宫女坐闲在宗玄说', 0, NULL, 0, '2026-08-07 17:27:32');
INSERT INTO `poem_rounds` VALUES (154, 31, '韦应物', '夕次盱眙县', '[\"落帆逗淮镇  停舫临孤驿\",\"浩浩风起波  冥冥日沈夕\",\"人归山郭暗  雁下芦洲白\",\"独夜忆秦关  听钟未眠客\"]', 0, '落帆逗淮镇', '停舫临孤驿', '落帆逗淮镇停舫临孤驿', '落帆孤淮镇停舫临逗驿', 0, NULL, 0, '2026-08-07 17:28:32');
INSERT INTO `poem_rounds` VALUES (155, 252, '卢纶', '塞下曲四首之一', '[\"鹫翎金仆姑  燕尾绣蝥弧\",\"独立扬新令  千营共一呼\"]', 0, '鹫翎金仆姑', '燕尾绣蝥弧', '鹫翎金仆姑燕尾绣蝥弧', '鹫翎金绣姑燕尾仆蝥弧', 0, NULL, 0, '2026-08-07 17:29:34');
INSERT INTO `poem_rounds` VALUES (156, 186, '杜甫', '宿府', '[\"清秋幕府井梧寒  独宿江城蜡炬残\",\"永夜角声悲自语  中天月色好谁看\",\"风尘荏苒音书绝  关塞萧条行陆难\",\"已忍伶俜十年事  强移栖息一枝安\"]', 1, '永夜角声悲自语', '中天月色好谁看', '中天月色好谁看', '中天好色月谁看', 0, NULL, 0, '2026-08-07 17:30:34');
INSERT INTO `poem_rounds` VALUES (157, 293, '杜牧', '金谷园', '[\"繁华事散逐香尘  流水无情草自春\",\"日暮东风怨啼鸟  落花犹似坠楼人\"]', 1, '日暮东风怨啼鸟', '落花犹似坠楼人', '日暮东风怨啼鸟', '日暮怨风东啼鸟', 0, NULL, 0, '2026-08-07 17:31:34');
INSERT INTO `poem_rounds` VALUES (158, 96, '宋之问', '题大庾岭北驿', '[\"阳月南飞雁  传闻至此回\",\"我行殊未已  何日复归来\",\"江静潮初落  林昏瘴不开\",\"明朝望乡处  应见陇头梅\"]', 0, '阳月南飞雁', '传闻至此回', '阳月南飞雁传闻至此回', '回月南飞雁传闻至此阳', 0, NULL, 0, '2026-08-07 17:32:34');
INSERT INTO `poem_rounds` VALUES (159, 112, '杜甫', '旅夜书怀', '[\"细草微风岸  危樯独夜舟\",\"星垂平野阔  月涌大江流\",\"名岂文章著  官应老病休\",\"飘飘何所似  天地一沙鸥\"]', 0, '细草微风岸', '危樯独夜舟', '细草微风岸危樯独夜舟', '危草微风岸细樯独夜舟', 0, NULL, 0, '2026-08-07 17:33:34');
INSERT INTO `poem_rounds` VALUES (160, 149, '刘禹锡', '蜀先主庙', '[\"天地英雄气  千秋尚凛然\",\"势分三足鼎  业复五铢钱\",\"得相能开国  生儿不象贤\",\"凄凉蜀故妓  来舞魏宫前\"]', 3, '凄凉蜀故妓', '来舞魏宫前', '凄凉蜀故妓来舞魏宫前', '凉凄蜀故妓来舞魏宫前', 0, NULL, 0, '2026-08-07 17:34:34');
INSERT INTO `poem_rounds` VALUES (161, 208, '李商隐', '隋宫', '[\"紫泉宫殿锁烟霞  欲取芜城作帝家\",\"玉玺不缘归日角  锦帆应是到天涯\",\"於今腐草无萤火  终古垂杨有暮鸦\",\"地下若逢陈后主  岂宜重问后庭花\"]', 3, '地下若逢陈后主', '岂宜重问后庭花', '地下若逢陈后主', '地下陈逢若后主', 0, NULL, 0, '2026-08-07 17:35:34');
INSERT INTO `poem_rounds` VALUES (162, 206, '李商隐', '锦瑟', '[\"锦瑟无端五十弦  一弦一柱思华年\",\"庄生晓梦迷蝴蝶  望帝春心托杜鹃\",\"沧海月明珠有泪  蓝田日暖玉生烟\",\"此情可待成追忆  只是当时已惘然\"]', 0, '锦瑟无端五十弦', '一弦一柱思华年', '锦瑟无端五十弦一弦一柱思华年', '锦瑟无端五弦十一弦一柱思华年', 0, NULL, 0, '2026-08-07 17:36:34');
INSERT INTO `poem_rounds` VALUES (163, 302, '郑畋', '马嵬坡', '[\"玄宗回马杨妃死  云雨难忘日月新\",\"终是圣明天子事  景阳宫井又何人\"]', 0, '玄宗回马杨妃死', '云雨难忘日月新', '玄宗回马杨妃死云雨难忘日月新', '玄宗死马新妃回云雨难忘日月杨', 0, NULL, 0, '2026-08-07 17:37:34');
INSERT INTO `poem_rounds` VALUES (164, 142, '刘脊虚', '阙题', '[\"道由白云尽  春与青溪长\",\"时有落花至  远隋流水香\",\"闲门向山路  深柳读书堂\",\"幽映每白日  清辉照衣裳\"]', 0, '道由白云尽', '春与青溪长', '道由白云尽春与青溪长', '长由白云尽春与青溪道', 0, NULL, 0, '2026-08-07 17:38:34');
INSERT INTO `poem_rounds` VALUES (165, 195, '刘长卿', '自夏口至鹦洲夕望岳阳寄源中丞', '[\"汀洲无浪复无烟  楚客相思益渺然\",\"汉口夕阳斜渡鸟  洞庭秋水远连天\",\"孤城背岭寒吹角  独戍临江夜泊船\",\"贾谊上书忧汉室  长沙谪去古今怜\"]', 0, '汀洲无浪复无烟', '楚客相思益渺然', '汀洲无浪复无烟', '汀烟无浪复无洲', 0, NULL, 0, '2026-08-07 17:39:35');
INSERT INTO `poem_rounds` VALUES (166, 81, '李白', '长相思二首之二', '[\"日色已尽花含烟  月明欲素愁不眠\",\"赵瑟初停凤凰柱  蜀琴欲奏鸳鸯弦\",\"此曲有意无人传  愿随春风寄燕然\",\"忆君迢迢隔青天\",\"昔日横波目  今成流泪泉\",\"不信妾肠断  归来看取明镜前\"]', 2, '此曲有意无人传', '愿随春风寄燕然', '此曲有意无人传愿随春风寄燕然', '此曲随意无人传愿有寄风春燕然', 0, NULL, 0, '2026-08-07 17:40:35');
INSERT INTO `poem_rounds` VALUES (167, 18, '孟浩然', '秋登兰山寄张五', '[\"北山白云里  隐者自怡悦\",\"相望始登高  心随雁飞灭\",\"愁因薄暮起  兴是清秋发\",\"时见归村人  沙行渡头歇\",\"天边树若荠  江畔洲如月\",\"何当载酒来  共醉重阳节\"]', 4, '天边树若荠', '江畔洲如月', '天边树若荠江畔洲如月', '树边天若荠江畔洲如月', 0, NULL, 0, '2026-08-07 17:41:35');
INSERT INTO `poem_rounds` VALUES (168, 159, '李商隐', '北青萝', '[\"残阳西入崦  茅屋访孤僧\",\"落叶人何在  寒云路几层\",\"独敲初夜磬  闲倚一枝藤\",\"世界微尘里  吾宁爱与憎\"]', 0, '残阳西入崦', '茅屋访孤僧', '残阳西入崦茅屋访孤僧', '残阳西入崦茅屋孤访僧', 0, NULL, 0, '2026-08-07 17:42:35');
INSERT INTO `poem_rounds` VALUES (169, 314, '李白', '清平调三首之二', '[\"一枝红艳露凝香  云雨巫山枉断肠\",\"借问汉宫谁得似  可怜飞燕倚新妆\"]', 1, '借问汉宫谁得似', '可怜飞燕倚新妆', '借问汉宫谁得似可怜飞燕倚新妆', '借问汉得似宫谁可怜飞燕倚新妆', 0, NULL, 0, '2026-08-07 17:43:35');
INSERT INTO `poem_rounds` VALUES (170, 270, '韩□', '寒食', '[\"春城无处不飞花  寒食东风御柳斜\",\"日暮汉宫传蜡烛  轻烟散入五侯家\"]', 0, '春城无处不飞花', '寒食东风御柳斜', '寒食东风御柳斜', '寒食东御风斜柳', 0, NULL, 0, '2026-08-07 17:44:35');
INSERT INTO `poem_rounds` VALUES (171, 96, '宋之问', '题大庾岭北驿', '[\"阳月南飞雁  传闻至此回\",\"我行殊未已  何日复归来\",\"江静潮初落  林昏瘴不开\",\"明朝望乡处  应见陇头梅\"]', 3, '明朝望乡处', '应见陇头梅', '明朝望乡处应见陇头梅', '明朝望处乡应见陇头梅', 0, NULL, 0, '2026-08-07 17:45:35');
INSERT INTO `poem_rounds` VALUES (172, 13, '王维', '送别', '[\"下马饮君酒  问君何所之\",\"君言不得意  归卧南山陲\",\"但去莫复闻  白云无尽时\"]', 0, '下马饮君酒', '问君何所之', '下马饮君酒问君何所之', '下君饮君酒问马何所之', 0, NULL, 0, '2026-08-07 17:46:35');
INSERT INTO `poem_rounds` VALUES (173, 89, '杜甫', '哀王孙', '[\"长安城头头白乌  夜飞延秋门上呼\",\"又向人家啄大屋  屋底达官走避胡\",\"金鞭断折九马死  骨肉不待同驰驱\",\"腰下宝［“决”换王旁］青珊瑚  可怜王孙泣路隅\",\"问之不肯道姓名  但道困苦乞为奴\",\"已经百日窜荆棘  身上无有完肌肤\",\"高帝子孙尽隆准  龙种自与常人殊\",\"豺狼在邑龙在野  王孙善保千金躯\",\"不敢长语临交衢  且为王孙立斯须\",\"昨夜东风吹血腥  东来橐驼满旧都\",\"朔方健儿好身手  昔何勇锐今何愚\",\"窃闻天子已传位  圣德北服南单于\",\"花门□（“嫠”下女换刀）面请雪耻  慎勿出口他人狙\",\"哀哉王孙慎勿疏  五陵佳气无时无\"]', 4, '问之不肯道姓名', '但道困苦乞为奴', '但道困苦乞为奴', '但苦困奴乞为道', 0, NULL, 0, '2026-08-07 17:47:35');
INSERT INTO `poem_rounds` VALUES (174, 80, '李白', '长相思二首之一', '[\"长相思  在长安\",\"络纬秋啼金井阑  微霜凄凄簟色寒\",\"孤灯不明思欲绝  卷帷望月空长叹\",\"美人如花隔云端\",\"上有青冥之长天  下有渌水之波澜\",\"天长路远魂飞苦  梦魂不到关山难\",\"长相思  摧心肝\"]', 0, '长相思', '在长安', '长相思在长安', '长长思在相安', 0, NULL, 0, '2026-08-07 17:48:35');
INSERT INTO `poem_rounds` VALUES (175, 201, '柳宗元', '登柳州城楼寄漳汀封连四州刺史', '[\"城上高楼接大荒  海天愁思正茫茫\",\"惊风乱［风占）芙蓉水  密雨斜侵薜荔墙\",\"岭树重遮千里目  江流曲似九回肠\",\"共来百越文身地  犹自音书滞一乡\"]', 2, '岭树重遮千里目', '江流曲似九回肠', '岭树重遮千里目江流曲似九回肠', '岭树重遮流里目江千曲似九回肠', 0, NULL, 0, '2026-08-07 17:49:35');
INSERT INTO `poem_rounds` VALUES (176, 290, '杜牧', '秋夕', '[\"银烛秋光冷画屏  轻罗小扇扑流萤\",\"天阶夜色凉如水  坐看牵牛织女星\"]', 1, '天阶夜色凉如水', '坐看牵牛织女星', '坐看牵牛织女星', '牵看织牛坐女星', 0, NULL, 0, '2026-08-07 17:50:36');
INSERT INTO `poem_rounds` VALUES (177, 289, '杜牧', '遣怀', '[\"落魄江湖载酒行  楚腰纤细掌中轻\",\"十年一觉扬州梦  赢得青楼薄幸名\"]', 0, '落魄江湖载酒行', '楚腰纤细掌中轻', '楚腰纤细掌中轻', '轻腰纤细掌中楚', 0, NULL, 0, '2026-08-07 17:51:37');
INSERT INTO `poem_rounds` VALUES (178, 109, '杜甫', '天末怀李白', '[\"凉风起天末  君子意如何\",\"鸿雁几时到  江湖秋水多\",\"文章憎命达  魑魅喜人过\",\"应共冤魂语  投诗赠汨罗\"]', 1, '鸿雁几时到', '江湖秋水多', '鸿雁几时到江湖秋水多', '鸿雁几时水江湖秋到多', 0, NULL, 1, '2026-08-07 17:52:37');
INSERT INTO `poems` VALUES (1, '张九龄', '感遇四首之一', '[\"孤鸿海上来  池潢不敢顾\",\"侧见双翠鸟  巢在三珠树\",\"矫矫珍木巅  得无金丸惧\",\"美服患人指  高明逼神恶\",\"今我游冥冥  弋者何所慕\"]', 5);
INSERT INTO `poems` VALUES (2, '张九龄', '感遇四首之二', '[\"兰叶春葳蕤  桂华秋皎洁\",\"欣欣此生意  自尔为佳节\",\"谁知林栖者  闻风坐相悦\",\"草木有本心  何求美人折\"]', 4);
INSERT INTO `poems` VALUES (3, '张九龄', '感遇四首之三', '[\"幽人归独卧  滞虑洗孤清\",\"持此谢高鸟  因之传远情\",\"日夕怀空意  人谁感至精\",\"飞沈理自隔  何所慰吾诚\"]', 4);
INSERT INTO `poems` VALUES (4, '张九龄', '感遇四首之四', '[\"江南有丹橘  经冬犹绿林\",\"岂伊地气暖  自有岁寒心\",\"可以荐嘉客  奈何阻重深\",\"运命惟所遇  循环不可寻\",\"徒言树桃李  此木岂无阴\"]', 5);
INSERT INTO `poems` VALUES (5, '李白', '下终南山过斛斯山人宿置酒', '[\"暮从碧山下  山月随人归\",\"却顾所来径  苍苍横翠微\",\"相携及田家  童稚开荆扉\",\"绿竹入幽径  青萝拂行衣\",\"欢言得所憩  美酒聊共挥\",\"长歌吟松风  曲尽河星稀\",\"我醉君复乐  陶然共忘机\"]', 7);
INSERT INTO `poems` VALUES (6, '李白', '月下独酌', '[\"花间一壶酒  独酌无相亲\",\"举杯邀明月  对影成三人\",\"月既不解饮  影徒随我身\",\"暂伴月将影  行乐须及春\",\"我歌月徘徊  我舞影零乱\",\"醒时同交欢  醉后各分散\",\"永结无情游  相期邈云汉\"]', 7);
INSERT INTO `poems` VALUES (7, '李白', '春思', '[\"燕草如碧丝  秦桑低绿枝\",\"当君怀归日  是妾断肠时\",\"春风不相识  何事入罗帏\"]', 3);
INSERT INTO `poems` VALUES (8, '杜甫', '望岳', '[\"岱宗夫如何  齐鲁青未了\",\"造化钟神秀  阴阳割昏晓\",\"汤胸生层云  决眦入归鸟\",\"会当凌绝顶  一览众山小\"]', 4);
INSERT INTO `poems` VALUES (9, '杜甫', '赠卫八处士', '[\"人生不相见  动如参与商\",\"今夕复何夕  共此灯烛光\",\"少壮能几时  鬓发各已苍\",\"访旧半为鬼  惊呼热中肠\",\"焉知二十载  重上君子堂\",\"昔别君未婚  儿女忽成行\",\"怡然敬父执  问我来何方\",\"问答乃未已  驱儿罗酒浆\",\"夜雨剪春韭  新炊间黄粱\",\"主称会面难  一举累十觞\",\"十觞亦不醉  感子故意长\",\"明日隔山岳  世事两茫茫\"]', 12);
INSERT INTO `poems` VALUES (10, '杜甫', '佳人', '[\"绝代有佳人  幽居在空谷\",\"自云良家子  零落依草木\",\"关中昔丧乱  兄弟遭杀戮\",\"官高何足论  不得收骨肉\",\"世情恶衰歇  万事随转烛\",\"夫婿轻薄儿  新人美如玉\",\"合昏尚知时  鸳鸯不独宿\",\"但见新人笑  那闻旧人哭\",\"在山泉水清  出山泉水浊\",\"侍婢卖珠回  牵萝补茅屋\",\"摘花不插发  采柏动盈掬\",\"天寒翠袖薄  日暮倚修竹\"]', 12);
INSERT INTO `poems` VALUES (11, '杜甫', '梦李白二首之一', '[\"死别已吞声  生别常恻恻\",\"江南瘴疠地  逐客无消息\",\"故人入我梦  明我长相忆\",\"君今在罗网  何以有羽翼\",\"恐非平生魂  路远不可测\",\"魂来枫林青  魂返关塞黑\",\"落月满屋梁  犹疑照颜色\",\"水深波浪阔  无使蛟龙得\"]', 8);
INSERT INTO `poems` VALUES (12, '杜甫', '梦李白二首之二', '[\"浮云终日行  游子久不至\",\"三夜频梦君  情亲见君意\",\"告归常局促  苦道来不易\",\"江湖多风波  舟楫恐失坠\",\"出门搔白首  若负平生志\",\"冠盖满京华  斯人独憔悴\",\"孰云网恢恢  将老身反累\",\"千秋万岁名  寂寞身后事\"]', 8);
INSERT INTO `poems` VALUES (13, '王维', '送别', '[\"下马饮君酒  问君何所之\",\"君言不得意  归卧南山陲\",\"但去莫复闻  白云无尽时\"]', 3);
INSERT INTO `poems` VALUES (14, '王维', '送綦毋潜落第还乡', '[\"圣代无隐者  英灵尽来归\",\"遂令东山客  不得顾采薇\",\"既至金门远  孰云吾道非\",\"江淮度寒食  京洛缝春衣\",\"置酒长安道  同心与我违\",\"行当浮桂棹  未几拂荆扉\",\"远树带行客  孤城当落晖\",\"吾谋适不用  勿谓知音稀\"]', 8);
INSERT INTO `poems` VALUES (15, '王维', '青溪', '[\"言入黄花川  每逐青溪水\",\"随山将万转  趣途无百里\",\"声喧乱石中  色静深松里\",\"漾漾泛菱荇  澄澄映葭苇\",\"我心素已闲  清川澹如此\",\"请留盘石上  垂钓将已矣\"]', 6);
INSERT INTO `poems` VALUES (16, '王维', '渭川田家', '[\"斜光照墟落  穷巷牛羊归\",\"野老念牧童  倚杖候荆扉\",\"雉［句隹］麦苗秀  蚕眠桑叶稀\",\"田夫荷锄立  相见语依依\",\"即此羡闲逸  怅然吟式微\"]', 5);
INSERT INTO `poems` VALUES (17, '王维', '西施咏', '[\"艳色天下重  西施宁久微\",\"朝为越溪女  暮作吴宫妃\",\"贱日岂殊众  贵来方悟稀\",\"邀人傅脂粉  不自著罗衣\",\"君宠益娇态  君怜无是非\",\"当时浣纱伴  莫得同车归\",\"持谢邻家子  效颦安可希\"]', 7);
INSERT INTO `poems` VALUES (18, '孟浩然', '秋登兰山寄张五', '[\"北山白云里  隐者自怡悦\",\"相望始登高  心随雁飞灭\",\"愁因薄暮起  兴是清秋发\",\"时见归村人  沙行渡头歇\",\"天边树若荠  江畔洲如月\",\"何当载酒来  共醉重阳节\"]', 6);
INSERT INTO `poems` VALUES (19, '孟浩然', '夏日南亭怀辛大', '[\"山光忽西落  池月渐东上\",\"散发乘夜凉  开轩卧闲敞\",\"荷风送香气  竹露滴清响\",\"欲取鸣琴弹  恨无知音赏\",\"感此怀故人  中宵劳梦想\"]', 5);
INSERT INTO `poems` VALUES (20, '孟浩然', '宿业师山房待丁大不至', '[\"夕阳度西岭  群壑倏已暝\",\"松月生夜凉  风泉满清听\",\"樵人归欲尽  烟鸟栖初定\",\"之子期宿来  孤琴候萝径\"]', 4);
INSERT INTO `poems` VALUES (21, '王昌龄', '同从弟南斋玩月忆山阴崔少府', '[\"高卧南斋时  开帷月初吐\",\"清辉淡水木  演漾在窗户\",\"苒苒几盈虚  澄澄变今古\",\"美人清江畔  是夜越吟苦\",\"千里其如何  微风吹兰杜\"]', 5);
INSERT INTO `poems` VALUES (22, '邱为', '寻西山隐者不遇', '[\"绝顶一茅茨  直上三十里\",\"扣关无僮仆  窥室惟案几\",\"若非巾柴车  应是钓秋水\",\"差池不相见  黾勉空仰止\",\"草色新雨中  松声晚窗里\",\"及兹契幽绝  自足荡心耳\",\"虽无宾主意  颇得清净理\",\"兴尽方下山  何必待之子\"]', 8);
INSERT INTO `poems` VALUES (23, '綦毋潜', '春泛若耶溪', '[\"幽意无断绝  此去随所偶\",\"晚风吹行舟  花路入溪口\",\"际夜转西壑  隔山望南斗\",\"潭烟飞溶溶  林月低向后\",\"生事且弥漫  愿为持竿叟\"]', 5);
INSERT INTO `poems` VALUES (24, '常建', '宿王昌龄隐居', '[\"清溪深不测  隐处唯孤云\",\"松际露微月  清光犹为君\",\"茅亭宿花影  药院滋苔纹\",\"余亦谢时去  西山鸾鹤群\"]', 4);
INSERT INTO `poems` VALUES (25, '岑参', '与高适薛据登慈恩寺浮图', '[\"塔势如涌出  孤高耸天宫\",\"登临出世界  磴道盘虚空\",\"突兀压神州  峥嵘如鬼工\",\"四角碍白日  七层摩苍穹\",\"下窥指高鸟  俯听闻惊风\",\"连山若波涛  奔凑如朝东\",\"青槐夹驰道  宫馆何玲珑\",\"秋色从西来  苍然满关中\",\"五陵北原上  万古青蒙蒙\",\"净理了可悟  胜因夙所宗\",\"誓将挂冠去  觉道资无穷\"]', 11);
INSERT INTO `poems` VALUES (26, '元结', '贼退示官吏并序', '[\"昔岁逢太平  山林二十年\",\"泉源在庭户  洞壑当门前\",\"井税有常期  日晏犹得眠\",\"忽然遭时变  数岁亲戎旃\",\"今来典斯郡  山夷又纷然\",\"城小贼不屠  人贫伤可怜\",\"是以陷邻境  此州独见全\",\"使臣将王命  岂不如贼焉\",\"令彼征敛者  迫之如火煎\",\"谁能绝人命  以作时世贤\",\"思欲委符节  引竿自刺船\",\"将家就鱼麦  归老江湖边\"]', 12);
INSERT INTO `poems` VALUES (27, '韦应物', '郡斋雨中与诸文士燕集', '[\"兵卫森画戟  宴寝凝清香\",\"海上风雨至  逍遥池阁凉\",\"烦疴近消散  嘉宾复满堂\",\"自惭居处崇  未睹斯民康\",\"理会是非遣  性达形迹忘\",\"鲜肥属时禁  蔬果幸见尝\",\"俯饮一杯酒  仰聆金玉章\",\"神欢体自轻  意欲凌风翔\",\"吴中盛文史  群彦今汪洋\",\"方知大蕃地  岂曰财赋强\"]', 10);
INSERT INTO `poems` VALUES (28, '韦应物', '初发扬子寄元大校书', '[\"凄凄去亲爱  泛泛入烟雾\",\"归棹洛阳人  残钟广陵树\",\"今朝为此别  何处还相遇\",\"世事波上舟  沿洄安得住\"]', 4);
INSERT INTO `poems` VALUES (29, '韦应物', '寄全椒山中道士', '[\"今朝郡斋冷  忽念山中客\",\"涧底束荆薪  归来煮白石\",\"欲持一瓢酒  远慰风雨夕\",\"落叶满空山  何处寻行迹\"]', 4);
INSERT INTO `poems` VALUES (30, '韦应物', '长安遇冯著', '[\"客从东方来  衣上灞陵雨\",\"问客何为来  采山因买斧\",\"冥冥花正开  扬扬燕新乳\",\"昨别今已春  鬓丝生几缕\"]', 4);
INSERT INTO `poems` VALUES (31, '韦应物', '夕次盱眙县', '[\"落帆逗淮镇  停舫临孤驿\",\"浩浩风起波  冥冥日沈夕\",\"人归山郭暗  雁下芦洲白\",\"独夜忆秦关  听钟未眠客\"]', 4);
INSERT INTO `poems` VALUES (32, '韦应物', '东郊', '[\"吏舍局终年  出郊旷清曙\",\"杨柳散和风  青山澹吾虑\",\"依丛适自憩  缘涧还复去\",\"微雨霭芳原  春鸠鸣何处\",\"乐幽心屡止  遵事迹犹遽\",\"终罢斯结庐  慕陶真可庶\"]', 6);
INSERT INTO `poems` VALUES (33, '韦应物', '送杨氏女', '[\"永日方戚戚  出行复悠悠\",\"女子今有行  大江溯轻舟\",\"尔辈苦无恃  抚念益慈柔\",\"幼为长所育  两别泣不休\",\"对此结中肠  义往难复留\",\"自小阙内训  事姑贻我忧\",\"赖兹托令门  仁恤庶无尤\",\"贫俭诚所尚  资从岂待周\",\"孝恭遵妇道  容止顺其猷\",\"别离在今晨  见尔当何秋\",\"居闲始自遣  临感忽难收\",\"归来视幼女  零泪缘缨流\"]', 12);
INSERT INTO `poems` VALUES (34, '柳宗元', '晨诣超师院读禅经', '[\"汲井漱寒齿  清心拂尘服\",\"闲持贝叶书  步出东斋读\",\"真源了无取  忘迹世所逐\",\"遗言冀可冥  缮性何由熟\",\"道人庭宇静  苔色连深竹\",\"日出雾露馀  青松如膏沐\",\"澹然离言说  悟悦心自足\"]', 7);
INSERT INTO `poems` VALUES (35, '柳宗元', '溪居', '[\"久为簪组累  幸此南夷谪\",\"闲依农圃邻  偶似山林客\",\"晓耕翻露草  夜榜响溪石\",\"来往不逢人  长歌楚天碧\"]', 4);
INSERT INTO `poems` VALUES (36, '王昌龄', '塞上曲', '[\"蝉鸣空桑林  八月萧关道\",\"出塞复入塞  处处黄芦草\",\"从来幽并客  皆向沙场老\",\"莫学游侠儿  矜夸紫骝好\"]', 4);
INSERT INTO `poems` VALUES (37, '王昌龄', '塞下曲', '[\"饮马渡秋水  水寒风似刀\",\"平沙日未没  黯黯见临洮\",\"昔日长城战  咸言意气高\",\"黄尘足今古  白骨乱蓬蒿\"]', 4);
INSERT INTO `poems` VALUES (38, '李白', '关山月', '[\"明月出天山  苍茫云海间\",\"长风几万里  吹度玉门关\",\"汉下白登道  胡窥青海湾\",\"由来征战地  不见有人还\",\"戍客望边色  思归多苦颜\",\"高楼当此夜  叹息未应闲\"]', 6);
INSERT INTO `poems` VALUES (39, '李白', '子夜四时歌：春歌', '[\"秦地罗敷女  采桑绿水边\",\"素手青条上  红妆白日鲜\",\"蚕饥妾欲去  五马莫留连\"]', 3);
INSERT INTO `poems` VALUES (40, '李白', '子夜四时歌：夏歌', '[\"镜湖三百里  菡萏发荷花\",\"五月西施采  人看隘若耶\",\"回舟不待月  归去越王家\"]', 3);
INSERT INTO `poems` VALUES (41, '李白', '子夜四时歌：秋歌', '[\"长安一片月  万户捣衣声\",\"秋风吹不尽  总是玉关情\",\"何日平胡虏  良人罢远征\"]', 3);
INSERT INTO `poems` VALUES (42, '李白', '子夜四时歌：冬歌', '[\"明朝驿使发  一夜絮征袍\",\"素手抽针冷  那堪把剪刀\",\"裁缝寄远道  几日到临洮\"]', 3);
INSERT INTO `poems` VALUES (43, '李白', '长干行', '[\"妾发初覆额  折花门前剧\",\"郎骑竹马来  绕床弄青梅\",\"同居长干里  两小无嫌猜\",\"十四为君妇  羞颜未尝开\",\"低头向暗壁  千唤不一回\",\"十五始展眉  愿同尘与灰\",\"常存抱柱信  岂上望夫台\",\"十六君远行  瞿塘滟预堆\",\"五月不可触  猿鸣天上哀\",\"门前迟行迹  一一生绿苔\",\"苔深不能扫  落叶秋风早\",\"八月蝴蝶来  双飞西园草\",\"感此伤妾心  坐愁红颜老\",\"早晚下三巴  预将书报家\",\"相迎不道远  直至长风沙\"]', 15);
INSERT INTO `poems` VALUES (44, '孟郊', '烈女操', '[\"梧桐相待老  鸳鸯会双死\",\"贞妇贵殉夫  舍生亦如此\",\"波澜誓不起  妾心井中水\"]', 3);
INSERT INTO `poems` VALUES (45, '孟郊', '游子吟', '[\"慈母手中线  游子身上衣\",\"临行密密缝  意恐迟迟归\",\"谁言寸草心  报得三春辉\"]', 3);
INSERT INTO `poems` VALUES (46, '陈子昂', '登幽州台歌', '[\"前不见古人  后不见来者\",\"念天地之悠悠  独怆然而涕下\"]', 2);
INSERT INTO `poems` VALUES (47, '李颀', '古意', '[\"男儿事长征  少小幽燕客\",\"赌胜马蹄下  由来轻七尺\",\"杀人莫敢前  须如猬毛磔\",\"黄云陇底白雪飞  未得报恩不能归\",\"辽东小妇年十五  惯弹琵琶解歌舞\",\"今为羌笛出塞声  使我三军泪如雨\"]', 6);
INSERT INTO `poems` VALUES (48, '李颀', '送陈章甫', '[\"四月南风大麦黄  枣花未落桐叶长\",\"青山朝别暮还见  嘶马出门思故乡\",\"陈侯立身何坦荡  虬须虎眉仍大颡\",\"腹中贮书一万卷  不肯低头在草莽\",\"东门酤酒饮我曹  心轻万事皆鸿毛\",\"醉卧不知白日暮  有时空望孤云高\",\"长河浪头连天黑  津口停舟渡不得\",\"郑国游人未及家  洛阳行子空叹息\",\"闻道故林相识多  罢官昨日今如何\"]', 9);
INSERT INTO `poems` VALUES (49, '李颀', '琴歌', '[\"主人有酒欢今夕  请奏鸣琴广陵客\",\"月照城头乌半飞  霜凄万树风入衣\",\"铜炉华烛烛增辉  初弹渌水后楚妃\",\"一声已动物皆静  四座无言星欲稀\",\"清淮奉使千馀里  敢告云山从此始\"]', 5);
INSERT INTO `poems` VALUES (50, '李颀', '听董大弹胡笳声兼寄语弄房给事', '[\"蔡女昔造胡笳声  一弹一十有八拍\",\"胡人落泪沾边草  汉使断肠对归客\",\"古戍苍苍烽火寒  大荒沈沈飞雪白\",\"先拂声弦后角羽  四郊秋叶惊［扌戚］［扌戚］\",\"董夫子，通神明  深山窃听来妖精\",\"言迟更速皆应手  将往复旋如有情\",\"空山百鸟散还合  万里浮云阴且晴\",\"嘶酸雏雁失群夜  断绝胡儿恋母声\",\"川为静其波  鸟亦罢其鸣\",\"乌孙部落家乡远  逻娑沙尘哀怨生\",\"幽音变调忽飘洒  长风吹林雨堕瓦\",\"迸泉飒飒飞木末  野鹿呦呦走堂下\",\"长安城连东掖垣  凤凰池对青琐门\",\"高才脱略名与利  日夕望君抱琴至\"]', 14);
INSERT INTO `poems` VALUES (51, '李颀', '听安万善吹筚篥歌', '[\"南山截竹为筚篥  此乐本自龟兹出\",\"流传汉地曲转奇  凉州胡人为我吹\",\"傍邻闻者多叹息  远客思乡皆泪垂\",\"世人解听不解赏  长飙风中自来往\",\"枯桑老柏寒飕［风留］  九雏鸣凤乱啾啾\",\"龙吟虎啸一时发  万籁百泉相与秋\",\"忽然更作渔阳掺  黄云萧条白日暗\",\"变调如闻杨柳春  上林繁花照眼新\",\"岁夜高堂列明烛  美酒一杯声一曲\"]', 9);
INSERT INTO `poems` VALUES (52, '孟浩然', '夜归鹿门山歌', '[\"山寺钟鸣昼已昏  渔梁渡头争渡喧\",\"人随沙路向江村  余亦乘舟归鹿门\",\"鹿门月照开烟树  忽到庞公栖隐处\",\"岩扉松径长寂寥  惟有幽人自来去\"]', 4);
INSERT INTO `poems` VALUES (53, '李白', '庐山谣寄卢侍御虚舟', '[\"我本楚狂人  凤歌笑孔丘\",\"手持绿玉杖  朝别黄鹤楼\",\"五岳寻仙不辞远  一生好入名山游\",\"庐山秀出南斗傍  屏风九叠云锦张\",\"影落明湖青黛光  金阙前开二峰长\",\"银河倒挂三石梁  香炉瀑布遥相望\",\"回崖沓障凌苍苍\",\"翠影红霞映朝日  鸟飞不到吴天长\",\"登高壮观天地间  大江茫茫去不黄\",\"黄云万里动风色  白波九道流雪山\",\"好为庐山谣  兴因庐山发\",\"闲窥石镜清我心  谢公行处苍苔没\",\"早服还丹无世情  琴心三叠道初成\",\"遥见仙人彩云里  手把芙蓉朝玉京\",\"先期汗漫九垓上  愿接卢敖游太清\"]', 15);
INSERT INTO `poems` VALUES (54, '李白', '梦游天姥吟留别', '[\"海客谈瀛洲  烟涛微茫信难求\",\"越人语天姥  云霓明灭或可睹\",\"天姥连天向天横  势拔五岳掩赤城\",\"天台四万八千丈  对此欲倒东南倾\",\"我欲因之梦吴越  一夜飞渡镜湖月\",\"湖月照我影  送我至剡溪\",\"谢公宿处今尚在  渌水荡漾清猿啼\",\"脚著谢公屐  身登青云梯\",\"半壁见海日  空中闻天鸡\",\"千岩万壑路不定  迷花倚石忽已暝\",\"熊咆龙吟殷岩泉  栗深林兮惊层巅\",\"云青青兮欲雨  水澹澹兮生烟\",\"裂缺霹雳  丘峦崩摧\",\"洞天石扇  訇然中开\",\"青冥浩荡不见底  日月照耀金银台\",\"霓为衣兮风为马  云之君兮纷纷而来下\",\"虎鼓瑟兮鸾回车  仙之人兮列如麻\",\"忽魂悸以魄动  恍惊起而长嗟\",\"惟觉时之枕席  失向来之烟霞\",\"世间行乐亦如此  古来万事东流水\",\"别君去兮何时还  且放白鹿青崖间\",\"须行即骑访名山\",\"安能摧眉折腰事权贵  使我不得开心颜\"]', 23);
INSERT INTO `poems` VALUES (55, '李白', '金陵酒肆留别', '[\"风吹柳花满店香  吴姬压酒唤客尝\",\"金陵子弟来相送  欲行不行各尽觞\",\"请君试问东流水  别意与之谁短长\"]', 3);
INSERT INTO `poems` VALUES (56, '李白', '宣州谢［月兆］楼饯别校书叔云', '[\"弃我去者  昨日之日不可留\",\"乱我心者  今日之日多烦忧\",\"长风万里送秋雁  对此可以酣高楼\",\"蓬莱文章建安骨  中间小谢又清发\",\"俱怀逸兴壮思飞  欲上青天览明月\",\"抽刀断水水更流  举杯销愁愁更愁\",\"人生在世不称意  明朝散发弄扁舟\"]', 7);
INSERT INTO `poems` VALUES (57, '岑参', '走马川行奉送封大夫出师西征', '[\"君不见走马川行雪海边  平沙莽莽黄入天\",\"轮台九月风夜吼  一川碎石大如斗\",\"随风满地石乱走  匈奴草黄马正肥\",\"金山西见烟尘飞  汉家大将西出师\",\"将军金甲夜不脱  半夜军行戈相拨\",\"风头如刀面如割  马毛带雪汗气蒸\",\"五花连钱旋作冰  幕中草檄砚水凝\",\"虏骑闻之应胆慑  料知短兵不敢接\",\"车师西门伫献捷\"]', 9);
INSERT INTO `poems` VALUES (58, '岑参', '轮台歌奉送封大夫出师西征', '[\"轮台城头夜吹角  轮台城北旄头落\",\"羽书昨夜过渠黎  单于已在金山西\",\"戍楼西望烟尘黑  汉兵屯在轮台北\",\"上将拥旄西出征  平明吹笛大军行\",\"四边伐鼓雪海涌  三军大呼阴山动\",\"虏塞兵气连云屯  战场白骨缠草根\",\"剑河风急雪片阔  沙口石冻马蹄脱\",\"亚相勤王甘苦辛  誓将报主静边尘\",\"古来青史谁不见  今见功名胜古人\"]', 9);
INSERT INTO `poems` VALUES (59, '岑参', '白雪歌送武判官归京', '[\"北风卷地白草折  胡天八月即飞雪\",\"忽如一夜春风来  千树万树梨花开\",\"散入珠帘湿罗幕  狐裘不暖锦衾薄\",\"将军角弓不得控  都护铁衣冷犹著\",\"瀚海阑干百丈冰  愁云黪淡万里凝\",\"中军置酒饮归客  胡琴琵琶与羌笛\",\"纷纷暮雪下辕门  风掣红旗冻不翻\",\"轮台东门送君去  去时雪满天山路\",\"山回路转不见君  雪上空留马行处\"]', 9);
INSERT INTO `poems` VALUES (60, '杜甫', '韦讽录事宅观曹将军画马图', '[\"国初以来画鞍马  神妙独数江都王\",\"将军得名三十载  人间又见真乘黄\",\"曾貌先帝照夜白  龙池十日飞霹雳\",\"内府殷红玛瑙盘  婕妤传诏才人索\",\"盘赐将军拜舞归  轻纨细绮相追飞\",\"贵戚权门得笔迹  始觉屏障生光辉\",\"昔日太宗拳毛［马呙］  近时郭家狮子花\",\"今之新图有二马  复令识者久叹嗟\",\"此皆骑战一敌万  缟素漠漠开风沙\",\"其余七匹亦殊绝  迥若寒空杂烟雪\",\"霜蹄蹴踏长楸间  马官厮养森成列\",\"可怜九马争神骏  顾视清高气深稳\",\"借问苦心爱者谁  后有韦讽前支盾\",\"忆昔巡幸新丰宫  翠花拂天来向东\",\"腾骧磊落三万匹  皆与此图筋骨同\",\"自从献宝朝河宗  无复射蛟江水中\",\"君不见\",\"金粟堆前松柏里  龙媒去尽鸟呼风\"]', 18);
INSERT INTO `poems` VALUES (61, '杜甫', '丹青引赠曹霸将军', '[\"将军魏武之子孙  于今为庶为青门\",\"英雄割据虽已矣  文采风流今尚存\",\"学书初学卫夫人  但恨无过王右军\",\"丹青不知老将至  富贵于我如浮云\",\"开元之中常引见  承恩数上南熏殿\",\"凌烟功臣少颜色  将军下笔开生面\",\"良相头上进贤冠  猛将腰间大羽箭\",\"褒公鄂公毛发动  英姿飒爽犹酣战\",\"先帝天马玉花骢  画工如山貌不同\",\"是日牵来赤墀下  迥立阊阖生长风\",\"诏谓将军拂绢素  意匠惨淡经营中\",\"斯须九重真龙出  一洗万古凡马空\",\"玉花却在御榻上  榻上庭前屹相向\",\"至尊含笑催赐金  圉人太仆皆惆怅\",\"弟子韩干早入室  亦能画马穷殊相\",\"干惟画肉不画骨  忍使骅骝气凋丧\",\"将军画善盖有神  偶逢佳士亦写真\",\"即今漂泊干戈际  屡貌寻常行路人\",\"涂穷反遭俗眼白  世上未有如公贫\",\"但看古来盛名下  终日坎［土禀］缠其身\"]', 20);
INSERT INTO `poems` VALUES (62, '杜甫', '寄韩谏议', '[\"今我不乐思岳阳  身欲奋飞病在床\",\"美人娟娟隔秋水  濯足洞庭望八荒\",\"鸿飞冥冥日月白  青枫叶赤天雨霜\",\"玉京群帝集北斗  或骑麒麟翳凤凰\",\"芙蓉旌旗烟雾落  影动倒景摇潇湘\",\"星宫之君醉琼浆  羽人稀少不在旁\",\"似闻昨者赤松子  恐是汉代韩张良\",\"昔随刘氏定长安  帷幄未改神惨伤\",\"国家成败吾岂敢  色难腥腐餐枫香\",\"周南留滞古所惜  南极老人应寿昌\",\"美人胡为隔秋水  焉得置之贡玉堂\"]', 11);
INSERT INTO `poems` VALUES (63, '杜甫', '古柏行', '[\"孔明庙前有老柏  柯如青铜根如石\",\"双皮溜雨四十围  黛色参天二千尺\",\"君臣已与时际会  树木犹为人爱惜\",\"云来气接巫峡长  月出寒通雪山白\",\"忆昨路绕锦亭东  先主武侯同［门必］宫\",\"崔嵬枝干郊原古  窈窕丹青户牖空\",\"落落盘踞虽得地  冥冥孤高多烈风\",\"扶持自是神明力  正直元因造化功\",\"大厦如倾要梁栋  万牛回首丘山重\",\"不露文章世已惊  未辞剪伐谁能送\",\"苦心岂免容蝼蚁  香叶终经宿鸾凤\",\"志士幽人莫怨嗟  古来材大难为用\"]', 12);
INSERT INTO `poems` VALUES (64, '杜甫', '观公孙大娘弟子舞剑器行并序', '[\"昔有佳人公孙氏  一舞剑器动四方\",\"观者如山色沮丧  天地为之久低昂\",\"霍如羿射九日落  矫如群帝骖龙翔\",\"来如雷霆收震怒  罢如江海凝清光\",\"绛唇珠袖两寂寞  晚有弟子传芬芳\",\"临颍美人在白帝  妙舞此曲神扬扬\",\"与余问答既有以  感时抚事增惋伤\",\"先帝侍女八千人  公孙剑器初第一\",\"五十年间似反掌  风尘［氵项］洞昏王室\",\"梨园子弟散如烟  女乐馀姿映寒日\",\"金粟堆前木已拱  瞿塘石城草萧瑟\",\"玳筵急管曲复终  乐极哀来月东出\",\"老夫不知其所往  足茧荒山转愁疾\"]', 13);
INSERT INTO `poems` VALUES (65, '元结', '石鱼湖上醉歌并序', '[\"石鱼湖，似洞庭  夏水欲满君山青\",\"山为樽，水为沼  酒徒历历坐洲鸟\",\"长风连日作大浪  不能废人运酒舫\",\"我持长瓢坐巴丘  酌饮四座以散愁\"]', 4);
INSERT INTO `poems` VALUES (66, '韩愈', '山石', '[\"山石荦确行径微  黄昏到寺蝙蝠飞\",\"升堂坐阶新雨足  芭蕉叶大栀子肥\",\"僧言古壁佛画好  以火来照所见稀\",\"铺床拂席置羹饭  疏粝亦足饱我饥\",\"夜深静卧百虫绝  清月出岭光入扉\",\"天明独去无道路  出入高下穷烟霏\",\"山红涧碧纷烂漫  时见松枥皆十围\",\"当流赤足蹋涧石  水声激激风吹衣\",\"人生如此自可乐  岂必局束为人［革几］\",\"嗟哉吾党二三子  安得至老不更归\"]', 10);
INSERT INTO `poems` VALUES (67, '韩愈', '八月十五夜赠张功曹', '[\"纤云四卷天无河  清风吹空月舒波\",\"沙平水息声影绝  一杯相属君当歌\",\"君歌声酸辞且苦  不能听终泪如雨\",\"洞庭连天九嶷高  蛟龙出没猩鼯号\",\"十生九死到官所  幽居默默如藏逃\",\"下床畏蛇食畏药  海气湿蛰熏腥臊\",\"昨者州前槌大鼓  嗣皇继圣登夔皋\",\"赦书一日行万里  罪从大辟皆除死\",\"迁者追回流者还  涤瑕荡垢清朝班\",\"州家申名使家抑  坎轲只得移荆蛮\",\"判司卑官不堪说  未免捶楚尘埃间\",\"同时辈流多上道  天路幽险难追攀\",\"君歌且休听我歌  我歌今与君殊科\",\"一年明月今宵多  人生由命非由他\",\"有酒不饮奈明何\"]', 15);
INSERT INTO `poems` VALUES (68, '韩愈', '谒衡岳庙遂宿岳寺题门楼', '[\"五岳祭秩皆三公  四方环镇嵩当中\",\"火维地荒足妖怪  天假神柄专其雄\",\"喷云泄雾藏半腹  虽有绝顶谁能穷\",\"我来正逢秋雨节  阴气晦昧无清风\",\"潜心默祷若有应  岂非正直能感通\",\"须臾静扫众峰出  仰见突兀撑青空\",\"紫盖连延接天柱  石廪腾掷堆祝融\",\"森然魄动下马拜  松柏一迳趋灵宫\",\"纷墙丹柱动光彩  鬼物图画填青红\",\"升阶伛偻荐脯酒  欲以菲薄明其衷\",\"庙内老人识神意  睢盱侦伺能鞠躬\",\"手持杯［王交］导我掷  云此最吉馀难同\",\"窜逐蛮荒幸不死  衣食才足甘长终\",\"侯王将相望久绝  神纵欲福难为功\",\"夜投佛寺上高阁  星月掩映云［日童］［日龙］\",\"猿鸣钟动不知曙  杲杲寒日生于东\"]', 16);
INSERT INTO `poems` VALUES (69, '韩愈', '石鼓歌', '[\"张生手持石鼓文  劝我识作石鼓歌\",\"少陵无人谪仙死  才薄将奈石鼓何\",\"周纲凌迟四海沸  宣王愤起挥天戈\",\"大开明堂受朝贺  诸侯剑佩鸣相磨\",\"搜于岐阳骋雄俊  万里禽兽皆遮罗\",\"镌功勒成告万世  凿石作鼓隳嵯峨\",\"从臣才艺咸第一  拣选撰刻留山阿\",\"雨淋日炙野火燎  鬼物守护烦［扌为］呵\",\"公从何处得纸本  毫发尽备无差讹\",\"辞严义密读难晓  字体不类隶与蝌\",\"年深岂免有缺画  快剑砍断生蛟鼍\",\"鸾翔凤翥众仙下  珊瑚碧树交枝柯\",\"金绳铁索锁钮壮  古鼎跃水龙腾梭\",\"陋儒编诗不收入  二雅褊迫无委蛇\",\"孔子西行不到秦  掎摭星宿遗羲娥\",\"嗟予好古生苦晚  对此涕泪双滂沱\",\"忆昔初蒙博士征  其年始改称元和\",\"故人从军在右辅  为我度量掘臼科\",\"濯冠沐浴告祭酒  如此至宝存岂多\",\"毡包席裹可立致  十鼓只载数骆驼\",\"荐诸太庙比郜鼎  光价岂止百倍过\",\"圣恩若许留太学  诸生讲解得切磋\",\"观经鸿都尚填咽  坐见举国来奔波\",\"剜苔剔藓露节角  安置妥帖平不颇\",\"大厦深檐与盖覆  经历久远期无佗\",\"中朝大官老于事  讵肯感激徒□（“妍”右上一横改为“合”）婀\",\"牧童敲火牛砺角  谁复著手为摩挲\",\"日销月铄就埋没  六年西顾空吟哦\",\"羲之俗书趁姿媚  数纸尚可博白鹅\",\"继周八代争战罢  无人收拾理则那\",\"方今太平日无事  柄任儒术崇丘轲\",\"安能以此上论列  愿借辩口如悬河\",\"石鼓之歌止于此  呜呼吾意其蹉跎\"]', 33);
INSERT INTO `poems` VALUES (70, '柳宗元', '渔翁', '[\"渔翁夜傍西岩宿  晓汲清湘燃楚烛\",\"烟销日出不见人  ［矣欠］乃一声山水绿\",\"回看天际下中流  岩上无心云相逐\"]', 3);
INSERT INTO `poems` VALUES (71, '白居易', '长恨歌', '[\"汉皇重色思倾国  御宇多年求不得\",\"杨家有女初长成  养在深闺人未识\",\"天生丽质难自弃  一朝选在君王侧\",\"回眸一笑百媚生  六宫粉黛无颜色\",\"春寒赐浴华清池  温泉水滑洗凝脂\",\"侍儿扶起娇无力  始是新承恩泽时\",\"云鬓花颜金步摇  芙蓉帐暖度春宵\",\"春宵苦短日高起  从此君王不早朝\",\"承欢侍宴无闲暇  春从春游夜专夜\",\"后宫佳丽三千人  三千宠爱在一身\",\"金星妆成娇侍夜  玉楼宴罢醉和春\",\"姊妹弟兄皆列士  可怜光彩生门户\",\"遂令天下父母心  不重生男重生女\",\"骊宫高处入青云  仙乐风飘处处闻\",\"缓歌慢舞凝丝竹  尽日君王看不足\",\"渔阳鼙鼓动地来  惊破霓裳羽衣曲\",\"九重城阙烟尘生  千乘万骑西南行\",\"翠华摇摇行复止  西出都门百馀里\",\"六军不发无奈何  宛转蛾眉马前死\",\"花钿委地无人收  翠翘金雀玉搔头\",\"君王掩面救不得  回看血泪相和流\",\"黄埃散漫风萧索  云栈萦纡登剑阁\",\"峨嵋山下少人行  旌旗无光日色薄\",\"蜀江水碧蜀山青  圣主朝朝暮暮情\",\"行宫见月伤心色  夜雨闻铃肠断声\",\"天旋地转回龙驭  到此踌躇不能去\",\"马嵬坡下泥土中  不见玉颜空死处\",\"君臣相顾尽沾衣  东望都门信马归\",\"归来池苑皆依旧  太液芙蓉未央柳\",\"芙蓉如面柳如眉  对此如何不泪垂\",\"春风桃李花开日  秋雨梧桐叶落时\",\"西宫南内多秋草  落叶满阶红不扫\",\"梨园子弟白发新  椒房阿监青娥老\",\"夕殿萤飞思悄然  孤灯挑尽未成眠\",\"迟迟钟鼓初长夜  耿耿星河欲曙天\",\"鸳鸯瓦冷霜华重  翡翠衾寒谁与共\",\"悠悠生死别经年  魂魄不曾来入梦\",\"临邛道士鸿都客  能以精诚致魂魄\",\"为感君王辗转思  遂教方士殷勤觅\",\"排空驭气奔如电  升天入地求之遍\",\"上穷碧落下黄泉  两处茫茫皆不见\",\"忽闻海上有仙山  山在虚无缥缈间\",\"楼阁玲珑五云起  其中绰约多仙子\",\"中有一人字太真  雪肤花貌参差是\",\"金阙西厢叩玉扃  转教小玉报双成\",\"闻道汉家天子使  九华帐里梦魂惊\",\"揽衣推枕起徘徊  珠箔银屏迤逦开\",\"云鬓半偏新睡觉  花冠不整下堂来\",\"风吹仙袂飘飘举  犹似霓裳羽衣舞\",\"玉容寂寞泪阑干  梨花一枝春带雨\",\"含情凝睇谢君王  一别音容两渺茫\",\"昭阳殿里恩爱绝  蓬莱宫中日月长\",\"回头下望人寰处  不见长安见尘雾\",\"唯将旧物表深情  钿合金钗寄将去\",\"钗留一股合一扇  钗擘黄金合分钿\",\"但教心似金钿坚  天上人间会相见\",\"临别殷勤重寄词  词中有誓两心知\",\"七月七日长生殿  夜半无人私语时\",\"在天愿作比翼鸟  在地愿为连理枝\",\"天长地久有时尽  此恨绵绵无绝期\"]', 60);
INSERT INTO `poems` VALUES (72, '白居易', '琵琶行并序', '[\"浔言江头夜送客  枫叶荻花秋瑟瑟\",\"主人下马客在船  举酒欲饮无管弦\",\"醉不成欢惨将别  别时茫茫江浸月\",\"忽闻水上琵琶声  主人忘归客不发\",\"寻声暗问弹者谁  琵琶声停欲语迟\",\"移船相近邀相见  添酒回灯重开宴\",\"千呼万唤始出来  犹抱琵琶半遮面\",\"转轴拨弦三两声  未成曲调先有情\",\"弦弦掩抑声声思  似诉平生不得志\",\"低眉信手续续弹  说尽心中无限事\",\"轻拢慢捻抹复挑  初为霓裳后六么\",\"大弦嘈嘈如急雨  小弦切切如私语\",\"嘈嘈切切错杂弹  大珠小珠落玉盘\",\"间关莺语花底滑  幽咽泉流水下滩\",\"水泉冷涩弦凝绝  凝绝不通声渐歇\",\"别有幽愁暗恨生  此时无声胜有声\",\"银瓶乍破水浆迸  铁骑突出刀枪鸣\",\"曲终收拨当心画  四弦一声如裂帛\",\"东船西舫悄无言  唯见江心秋月白\",\"沈吟放拨插弦中  整顿衣裳起敛容\",\"自言本是京城女  家在虾蟆陵下住\",\"十三学得琵琶成  名属教坊第一部\",\"曲罢曾教善才服  妆成每被秋娘妒\",\"五陵年少争缠头  一曲红绡不知数\",\"钿头银篦击节碎  血色罗裙翻酒污\",\"今年欢笑复明年  秋月春风等闲度\",\"弟走从军阿姨死  暮去朝来颜色故\",\"门前冷落车马稀  老大嫁作商人妇\",\"商人重利轻别离  前月浮梁买茶去\",\"去来江口守空船  绕船月明江水寒\",\"夜深忽梦少年事  梦啼妆泪红阑干\",\"我闻琵琶已叹息  又闻此语重唧唧\",\"同是天涯沦落人  相逢何必曾相识\",\"我从去年辞帝京  谪居卧病浔阳城\",\"浔阳地僻无音乐  终岁不闻丝竹声\",\"住近湓江地低湿  黄芦苦竹绕宅生\",\"其间旦暮闻何物  杜鹃啼血猿哀鸣\",\"春江花朝秋月夜  往往取酒还独倾\",\"岂无山歌与村笛  呕哑嘲哳难为听\",\"今夜闻君琵琶语  如听仙乐耳暂明\",\"莫辞更坐弹一曲  为君翻作琵琶行\",\"感我此言良久立  却坐促弦弦转急\",\"凄凄不似向前声  满座重闻皆掩泣\",\"座中泣下谁最多  江州司马青衫湿\"]', 44);
INSERT INTO `poems` VALUES (73, '李商隐', '韩碑', '[\"元和天子神武姿  彼何人哉轩与羲\",\"誓将上雪列圣耻  坐法宫中朝四夷\",\"淮西有贼五十载  封狼生［豸区］［豸区］生罴\",\"不据山河据平地  长戈利矛日可麾\",\"帝得圣相相曰度  贼斫不死神扶持\",\"腰悬相印作都统  阴风惨澹天王旗\",\"□（上朔下心］武古通作牙爪  仪曹外郎载笔随\",\"行军司马智且勇  十四万众犹虎貔\",\"入蔡缚贼献太庙  功无与让恩不訾\",\"帝曰汝度功第一  汝从事愈宜为辞\",\"愈拜稽首蹈且舞  金石刻画臣能为\",\"古者世称大手笔  此事不系于职司\",\"当仁自古有不让  言讫屡颔天子颐\",\"公退斋戒坐小阁  濡染大笔何淋漓\",\"点窜尧典舜典字  涂改清庙生民诗\",\"文成破体书在纸  清晨再拜铺丹墀\",\"表曰臣愈昧死上  咏神圣功书之碑\",\"碑高三丈字如斗  负以灵鳌蟠以螭\",\"句奇语重喻者少  谗之天子言其私\",\"长绳百尺拽碑倒  粗沙大石相磨治\",\"公之斯文若元气  先时已入人肝脾\",\"汤盘孔鼎有述作  今无其器存其辞\",\"呜呼圣皇及圣相  相与［火亘］赫流淳熙\",\"公之斯文不示后  曷与三五相攀追\",\"愿书万本诵万过  口角流沫右手胝\",\"传之七十有二代  以为封禅玉检明堂基\"]', 26);
INSERT INTO `poems` VALUES (74, '高适', '燕歌行并序', '[\"汉家烟尘在东北  汉将辞家破残贼\",\"男儿本自重横行  天子非常赐颜色\",\"［扌从］金伐鼓下榆关  旌旆逶迤碣石间\",\"校尉羽书飞瀚海  单于猎火照狼山\",\"山川萧条极边土  胡骑凭陵杂风雨\",\"战士军前半死生  美人帐下犹歌舞\",\"大漠穷秋塞草衰  孤城落日斗兵稀\",\"身当恩遇常轻敌  力尽关山未解围\",\"铁衣远戍辛勤久  玉筋应啼别离后\",\"少妇城南欲断肠  征人蓟北空回首\",\"边庭飘摇那可度  绝域苍茫更何有\",\"杀气三时作阵云  寒声一夜传刁斗\",\"相看白刃血纷纷  死节从来岂顾勋\",\"君不见沙场征战苦  至今犹忆李将军\"]', 14);
INSERT INTO `poems` VALUES (75, '李颀', '古从军行', '[\"白日登山望烽火  黄昏饮马傍交河\",\"行人刁斗风沙暗  公主琵琶幽怨多\",\"野云万里无城郭  雨雪纷纷连大漠\",\"胡雁哀鸣夜夜飞  胡儿眼泪双双落\",\"闻道玉门犹被遮  应将性命逐轻车\",\"年年战骨埋荒外  空见葡萄入汉家\"]', 6);
INSERT INTO `poems` VALUES (76, '王维', '洛阳女儿行', '[\"洛阳女儿对门居  才可容颜十五馀\",\"良人玉勒乘骢马  侍女金盘脍鲤鱼\",\"画阁朱楼尽相望  红桃绿柳垂檐向\",\"罗帷送上七香车  宝扇迎归九华帐\",\"狂夫富贵在青春  意气骄奢剧季伦\",\"自怜碧玉亲教舞  不惜珊瑚持与人\",\"春窗曙灭九微火  九微片片飞花琐\",\"戏罢曾无理曲时  妆成只是薰香坐\",\"城中相识尽繁华  日夜经过赵李家\",\"谁怜越女颜如玉  贫贱江头自浣纱\"]', 10);
INSERT INTO `poems` VALUES (77, '王维', '老将行', '[\"少年十五二十时  步行夺得胡马骑\",\"射杀山中白额虎  肯数邺下黄须儿\",\"一身转战三千里  一剑曾当百万师\",\"汉兵奋迅如霹雳  虏骑崩腾畏蒺藜\",\"卫青不败由天幸  李广无功缘数奇\",\"自从弃置便衰朽  世事蹉跎成白首\",\"昔时飞箭无全目  今日垂杨生左肘\",\"路旁时卖故侯瓜  门前学种先生柳\",\"苍茫古木连穷巷  寥落寒山对虚牖\",\"誓令疏勒出飞泉  不似颍川空使酒\",\"贺兰山下阵如云  羽檄交驰日夕闻\",\"节使三河募年少  诏书五道出将军\",\"试拂铁衣如雪色  聊持宝剑动星文\",\"愿得燕弓射大将  耻令越甲鸣吾君\",\"莫嫌旧日云中守  犹堪一战取功勋\"]', 15);
INSERT INTO `poems` VALUES (78, '王维', '桃源行', '[\"渔舟逐水爱山春  两岸桃花夹古津\",\"坐看红树不知远  行尽青溪不见人\",\"山口潜行始隈［阝奥］  山开旷望旋平陆\",\"遥看一处攒云树  近入千家散花竹\",\"樵客初传汉姓名  居人未改秦衣服\",\"居人共住武陵源  还从物外起田园\",\"月明松下房栊静  日出云中鸡犬喧\",\"惊闻俗客争来集  竞引还家问都邑\",\"平明闾巷扫花开  薄暮渔樵乘水入\",\"初因避地去人间  及至成仙遂不还\",\"峡里谁知有人事  世中遥望空云山\",\"不疑灵境难闻见  尘心未尽思乡县\",\"出洞无论隔山水  辞家终拟长游衍\",\"自谓经过旧不迷  安知峰壑今来变\",\"当时只记入山深  青溪几曲到云林\",\"春来遍是桃花水  不辨仙源何处寻\"]', 16);
INSERT INTO `poems` VALUES (79, '李白', '蜀道难', '[\"噫吁戏  危乎高哉\",\"蜀道之难难于上青天\",\"蚕丛及鱼凫  开国何茫然\",\"尔来四万八千岁  始与秦塞通人烟\",\"西当太白有鸟道  可以横绝峨眉巅\",\"地崩山摧壮士死  然后天梯石栈方钩连\",\"上有六龙回日之高标  下有冲波逆折之回川\",\"黄鹤之飞尚不得  猿猱欲度愁攀援\",\"青泥何盘盘  百步九折萦岩峦\",\"扪参历井仰胁息  以手抚膺坐长叹\",\"问君西游何时还  畏途□（繁体“谗”换山旁）岩不可攀\",\"但见悲鸟号古木  雄飞雌从绕林间\",\"又闻子规啼  夜月愁空山\",\"蜀道之难难于上青天  使人听此凋朱颜\",\"连峰去天不盈尺  枯松倒挂倚绝壁\",\"飞湍瀑流争喧［兀豕］  冰崖转石万壑雷\",\"其险也如此\",\"嗟尔远道之人  胡为乎来哉\",\"剑阁峥嵘而崔嵬\",\"一夫当关  万夫莫开\",\"所守或匪亲  化为狼与豺\",\"朝避猛虎  夕避长蛇\",\"磨牙吮血  杀人如麻\",\"锦城虽云乐  不如早还家\",\"蜀道之难难于上青天  侧身西望常咨嗟\"]', 25);
INSERT INTO `poems` VALUES (80, '李白', '长相思二首之一', '[\"长相思  在长安\",\"络纬秋啼金井阑  微霜凄凄簟色寒\",\"孤灯不明思欲绝  卷帷望月空长叹\",\"美人如花隔云端\",\"上有青冥之长天  下有渌水之波澜\",\"天长路远魂飞苦  梦魂不到关山难\",\"长相思  摧心肝\"]', 7);
INSERT INTO `poems` VALUES (81, '李白', '长相思二首之二', '[\"日色已尽花含烟  月明欲素愁不眠\",\"赵瑟初停凤凰柱  蜀琴欲奏鸳鸯弦\",\"此曲有意无人传  愿随春风寄燕然\",\"忆君迢迢隔青天\",\"昔日横波目  今成流泪泉\",\"不信妾肠断  归来看取明镜前\"]', 6);
INSERT INTO `poems` VALUES (82, '李白', '行路难三首之一', '[\"金樽清酒斗十千  玉盘珍羞值万钱\",\"停杯投箸不能食  拔剑四顾心茫然\",\"欲渡黄河冰塞川  将登太行雪满山\",\"闲来垂钓碧溪上  忽复乘舟梦日边\",\"行路难，行路难  多歧路，今安在\",\"长风破浪会有时  直挂云帆济沧海\"]', 6);
INSERT INTO `poems` VALUES (83, '李白', '行路难三首之二', '[\"大道如青天  我独不得出\",\"羞逐长安社中儿  赤鸡白狗赌梨栗\",\"弹剑作歌奏苦声  曳裾王门不称情\",\"淮阴市井笑韩信  汉朝公卿忌贾生\",\"君不见\",\"昔时燕家重郭隗  拥彗折节无嫌猜\",\"剧辛乐毅感恩分  输肝剖胆效英才\",\"昭王白骨萦蔓草  谁人更扫黄金台\",\"行路难  归去来\"]', 9);
INSERT INTO `poems` VALUES (84, '李白', '行路难三首之三', '[\"有耳莫洗颍川水  有口莫食首阳蕨\",\"含光混世贵无名  何用孤高比云月\",\"吾观自古贤达人  功成不退皆殒身\",\"子胥既弃吴江上  屈原终投湘水滨\",\"陆机雄才岂自保  李斯税驾苦不早\",\"华亭鹤唳讵可闻  上蔡苍鹰何足道\",\"君不见\",\"吴中张翰称达生  秋风忽忆江东行\",\"且乐生前一杯酒  何须身后千载名\"]', 9);
INSERT INTO `poems` VALUES (85, '李白', '将进酒', '[\"君不见\",\"黄河之水天上来  奔流到海不复回\",\"君不见\",\"高堂明镜悲白发  朝如青丝暮成雪\",\"人生得意须尽欢  莫使金樽空对月\",\"天生我材必有用  千金散尽还复来\",\"烹羊宰牛且为乐  会须一饮三百杯\",\"岑夫子，丹丘生  将进酒，君莫停\",\"与君歌一曲  请君为我侧耳听\",\"钟鼓馔玉不足贵  但愿长醉不愿醒\",\"古来圣贤皆寂寞  惟有饮者留其名\",\"陈王昔时宴平乐  斗酒十千恣欢谑\",\"主人何为言少钱  径须沽取对君酌\",\"五花马  千金裘\",\"呼儿将出换美酒  与尔同消万古愁\"]', 15);
INSERT INTO `poems` VALUES (86, '杜甫', '兵车行', '[\"车辚辚，马萧萧  行人弓箭各在腰\",\"耶娘妻子走相送  尘埃不见咸阳桥\",\"牵衣顿足拦道哭  哭声直上干云霄\",\"道旁过者问行人  行人但云点行频\",\"或从十五北防河  便至四十西营田\",\"去时里正与裹头  归来头白还戍边\",\"边亭流血成海水  武皇开边意未已\",\"君不闻\",\"汉家山东二百州  千村万落生荆杞\",\"纵有健妇把锄犁  禾生陇亩无东西\",\"况复秦兵耐苦战  被驱不异犬与鸡\",\"长者虽有问  役夫敢申恨\",\"且如今年冬  未休关西卒\",\"县官急索租  租税从何出\",\"信知生男恶  反是生女好\",\"生女犹得嫁比邻  生男埋没随百草\",\"君不见\",\"青海头  古来白骨无人收\",\"新鬼烦冤旧鬼哭  天阴雨湿声啾啾\"]', 19);
INSERT INTO `poems` VALUES (87, '杜甫', '丽人行', '[\"三月三日天气新  长安水边多丽人\",\"态浓意远淑且真  肌理细腻骨肉匀\",\"绣罗衣裳照暮春  蹙金孔雀银麒麟\",\"头上何所有  翠微盍叶垂鬓唇\",\"背后何所见  珠压腰［衤及］稳称身\",\"就中云幕椒房亲  赐名大国虢与秦\",\"紫驼之峰出翠釜  水精之盘行素鳞\",\"犀箸餍饫久未下  鸾刀缕切空纷纶\",\"黄门飞［革空］不动尘  御厨络绎送八珍\",\"箫鼓哀吟感鬼神  宾从杂沓实要津\",\"后来鞍马何逡巡  当轩下马入锦茵\",\"杨花雪落覆白苹  青鸟飞去衔红巾\",\"炙手可热势绝伦  慎莫近前丞相嗔\"]', 13);
INSERT INTO `poems` VALUES (88, '杜甫', '哀江头', '[\"少陵野老吞生哭  春日潜行曲江曲\",\"江头宫殿锁千门  细柳新蒲为谁绿\",\"忆昔霓旌下南苑  苑中景物生颜色\",\"昭阳殿里第一人  同辇随君侍君侧\",\"辇前才人带弓箭  白马嚼啮黄金勒\",\"翻身向天仰射云  一箭正坠双飞翼\",\"明眸皓齿今何在  血污游魂归不得\",\"清渭东流剑阁深  去住彼此无消息\",\"人生有情泪沾臆  江水江花岂终极\",\"黄昏胡骑尘满城  欲往城南望城北\"]', 10);
INSERT INTO `poems` VALUES (89, '杜甫', '哀王孙', '[\"长安城头头白乌  夜飞延秋门上呼\",\"又向人家啄大屋  屋底达官走避胡\",\"金鞭断折九马死  骨肉不待同驰驱\",\"腰下宝［“决”换王旁］青珊瑚  可怜王孙泣路隅\",\"问之不肯道姓名  但道困苦乞为奴\",\"已经百日窜荆棘  身上无有完肌肤\",\"高帝子孙尽隆准  龙种自与常人殊\",\"豺狼在邑龙在野  王孙善保千金躯\",\"不敢长语临交衢  且为王孙立斯须\",\"昨夜东风吹血腥  东来橐驼满旧都\",\"朔方健儿好身手  昔何勇锐今何愚\",\"窃闻天子已传位  圣德北服南单于\",\"花门□（“嫠”下女换刀）面请雪耻  慎勿出口他人狙\",\"哀哉王孙慎勿疏  五陵佳气无时无\"]', 14);
INSERT INTO `poems` VALUES (90, '唐玄宗', '经邹鲁祭孔子而叹之', '[\"夫子何为者  栖栖一代中\",\"地犹鄹氏邑  宅即鲁王宫\",\"叹凤嗟身否  伤麟怨道穷\",\"今看两楹奠  当与梦时同\"]', 4);
INSERT INTO `poems` VALUES (91, '张九龄', '望月怀远', '[\"海上生明月  天涯共此时\",\"情人怨遥夜  竟夕起相思\",\"灭烛怜光满  披衣觉露滋\",\"不堪盈手赠  还寝梦佳期\"]', 4);
INSERT INTO `poems` VALUES (92, '王勃', '送杜少府之任蜀州', '[\"城阙辅三秦  风烟望五津\",\"与君离别意  同是宦游人\",\"海内存知己  天涯若比邻\",\"无为在歧路  儿女共沾巾\"]', 4);
INSERT INTO `poems` VALUES (93, '骆宾王', '在狱咏蝉并序', '[\"西路蝉声唱  南冠客思侵\",\"那堪玄鬓影  来对白头吟\",\"露重飞难进  风多响易沉\",\"无人信高洁  谁为表予心\"]', 4);
INSERT INTO `poems` VALUES (94, '杜审言', '和晋陵路丞早春游望', '[\"独有宦游人  偏惊物候新\",\"云霞出海曙  梅柳渡江春\",\"淑气催黄鸟  晴光转绿苹\",\"忽闻歌古调  归思欲沾巾\"]', 4);
INSERT INTO `poems` VALUES (95, '沈全期', '杂诗', '[\"闻道黄龙戍  频年不解兵\",\"可怜闺里月  长在汉家营\",\"少妇今春意  良人昨夜情\",\"谁能将旗鼓  一为取龙城\"]', 4);
INSERT INTO `poems` VALUES (96, '宋之问', '题大庾岭北驿', '[\"阳月南飞雁  传闻至此回\",\"我行殊未已  何日复归来\",\"江静潮初落  林昏瘴不开\",\"明朝望乡处  应见陇头梅\"]', 4);
INSERT INTO `poems` VALUES (97, '王湾', '次北固山下', '[\"客路青山外  行舟绿水前\",\"潮平两岸阔  风正一帆悬\",\"海日生残夜  江春入旧年\",\"乡书何处达  归雁洛阳边\"]', 4);
INSERT INTO `poems` VALUES (98, '常建', '题破山寺后禅院', '[\"清晨入古寺  初日照高林\",\"曲径通幽处  禅房花木深\",\"山光悦鸟性  潭影空人心\",\"万籁此俱寂  惟馀钟磬音\"]', 4);
INSERT INTO `poems` VALUES (99, '岑参', '寄左省杜拾遗', '[\"联步趋丹陛  分曹限紫微\",\"晓随天仗入  暮惹御香归\",\"白发悲花落  青云羡鸟飞\",\"圣朝无阙事  自觉谏书稀\"]', 4);
INSERT INTO `poems` VALUES (100, '李白', '赠孟浩然', '[\"吾爱孟夫子  风流天下闻\",\"红颜弃轩冕  白首卧松云\",\"醉月频中圣  迷花不事君\",\"高山安可仰  徒此挹清芬\"]', 4);
INSERT INTO `poems` VALUES (101, '李白', '渡荆门送别', '[\"渡远荆门外  来从楚国游\",\"山随平野尽  江入大荒流\",\"月下飞天镜  云生结海楼\",\"仍怜故乡水  万里送行舟\"]', 4);
INSERT INTO `poems` VALUES (102, '李白', '送友人', '[\"青山横北郭  白水绕东城\",\"此地一为别  孤蓬万里征\",\"浮云游子意  落日故人情\",\"挥手自兹去  萧萧班马鸣\"]', 4);
INSERT INTO `poems` VALUES (103, '李白', '听蜀僧浚弹琴', '[\"蜀僧抱绿绮  西下峨眉峰\",\"为我一挥手  如听万壑松\",\"客心洗流水  馀响入霜钟\",\"不觉碧山暮  秋云暗几重\"]', 4);
INSERT INTO `poems` VALUES (104, '李白', '夜泊牛渚怀古', '[\"牛渚西江夜  青天无片云\",\"登舟望秋月  空忆谢将军\",\"余亦能高咏  斯人不可闻\",\"明朝挂帆席  枫叶落纷纷\"]', 4);
INSERT INTO `poems` VALUES (105, '杜甫', '月夜', '[\"今夜［鹿阝］州月  闺中只独看\",\"遥怜小儿女  未解忆长安\",\"香雾云鬟湿  清辉玉臂寒\",\"何时倚虚幌  双照泪痕干\"]', 4);
INSERT INTO `poems` VALUES (106, '杜甫', '春望', '[\"国破山河在  城春草木深\",\"感时花溅泪  恨别鸟惊心\",\"烽火连三月  家书抵万金\",\"白头搔更短  浑欲不胜簪\"]', 4);
INSERT INTO `poems` VALUES (107, '杜甫', '春宿左省', '[\"花隐掖垣暮  啾啾栖鸟过\",\"星临万户动  月傍九霄多\",\"不寝听金钥  因风想玉珂\",\"明朝有封事  数问夜如何\"]', 4);
INSERT INTO `poems` VALUES (108, '杜甫', '月夜忆舍弟', '[\"戍鼓断人行  秋边一雁声\",\"露从今夜白  月是故乡明\",\"有弟皆分散  无家问死生\",\"寄书长不达  况乃未休兵\"]', 4);
INSERT INTO `poems` VALUES (109, '杜甫', '天末怀李白', '[\"凉风起天末  君子意如何\",\"鸿雁几时到  江湖秋水多\",\"文章憎命达  魑魅喜人过\",\"应共冤魂语  投诗赠汨罗\"]', 4);
INSERT INTO `poems` VALUES (110, '杜甫', '奉济驿重送严公四韵', '[\"远送从此别  青山空复情\",\"几时杯重把  昨夜月同行\",\"列郡讴歌惜  三朝出入荣\",\"将村独归处  寂寞养残生\"]', 4);
INSERT INTO `poems` VALUES (111, '杜甫', '别房太尉墓', '[\"他乡复行役  驻马别孤坟\",\"近泪无干土  低空有断云\",\"对棋陪谢傅  把剑觅徐君\",\"唯见林花落  莺啼送客闻\"]', 4);
INSERT INTO `poems` VALUES (112, '杜甫', '旅夜书怀', '[\"细草微风岸  危樯独夜舟\",\"星垂平野阔  月涌大江流\",\"名岂文章著  官应老病休\",\"飘飘何所似  天地一沙鸥\"]', 4);
INSERT INTO `poems` VALUES (113, '杜甫', '登岳阳楼', '[\"昔闻洞庭水  今上岳阳楼\",\"吴楚东南坼  乾坤日夜浮\",\"亲朋无一字  老病有孤舟\",\"戎马关山北  凭轩涕泗流\"]', 4);
INSERT INTO `poems` VALUES (114, '王维', '辋川闲居赠裴秀才迪', '[\"寒山转苍翠  秋水日潺［氵爰］\",\"倚杖柴门外  临风听暮蝉\",\"渡头馀落日  墟里上孤烟\",\"复值接舆醉  狂歌五柳前\"]', 4);
INSERT INTO `poems` VALUES (115, '王维', '山居秋暝', '[\"空山新雨后  天气晚来秋\",\"明月松间照  清泉石上流\",\"竹喧归浣女  莲动下渔舟\",\"随意春芳歇  王孙自可留\"]', 4);
INSERT INTO `poems` VALUES (116, '王维', '归嵩山作', '[\"清川带长薄  车马去闲闲\",\"流水如有意  暮禽相与还\",\"荒城临古渡  落日满秋山\",\"迢递嵩高下  归来且闭关\"]', 4);
INSERT INTO `poems` VALUES (117, '王维', '终南山', '[\"太乙近天都  连山接海隅\",\"白云回望合  青霭入看无\",\"分野中峰变  阴晴众壑殊\",\"欲投人处宿  隔水问樵夫\"]', 4);
INSERT INTO `poems` VALUES (118, '王维', '酬张少府', '[\"晚年惟好静  万事不关心\",\"自顾无长策  空知返旧林\",\"松风吹解带  山月照弹琴\",\"君问穷通理  渔歌入浦深\"]', 4);
INSERT INTO `poems` VALUES (119, '王维', '过香积寺', '[\"不知香积寺  数里入云峰\",\"古木无人径  深山何处钟\",\"泉声咽危石  日色冷青松\",\"薄暮空潭曲  安禅制毒龙\"]', 4);
INSERT INTO `poems` VALUES (120, '王维', '送梓州李使君', '[\"万壑树参天  千山响杜鹃\",\"山中一夜雨  树杪百重泉\",\"汉女输［木童］布  巴人讼芋田\",\"文翁翻教授  不敢倚先贤\"]', 4);
INSERT INTO `poems` VALUES (121, '王维', '汉江临眺', '[\"楚塞三湘接  荆门九派通\",\"江流天地外  山色有无中\",\"郡邑浮前浦  波澜动远空\",\"襄阳好风日  留醉与山翁\"]', 4);
INSERT INTO `poems` VALUES (122, '王维', '终南别业', '[\"中岁颇好道  晚家南山陲\",\"兴来美独往  胜事空自知\",\"行到水穷处  坐看云起时\",\"偶然值林叟  谈笑无还期\"]', 4);
INSERT INTO `poems` VALUES (123, '孟浩然', '望洞庭湖赠张丞相', '[\"八月湖水平  涵虚混太清\",\"气蒸云梦泽  波撼岳阳城\",\"欲济无舟楫  端居耻圣明\",\"坐观垂钓者  空有羡鱼情\"]', 4);
INSERT INTO `poems` VALUES (124, '孟浩然', '与诸子登岘山', '[\"人事有代谢  往来成古今\",\"江山留胜迹  我辈复登临\",\"水落鱼梁浅  天寒梦泽深\",\"羊公碑字在  读罢泪沾襟\"]', 4);
INSERT INTO `poems` VALUES (125, '孟浩然', '清明日宴梅道士房', '[\"林卧愁春尽  开轩览物华\",\"忽逢青鸟使  邀入赤松家\",\"丹灶初开火  仙桃正发花\",\"童颜若可驻  何惜醉流霞\"]', 4);
INSERT INTO `poems` VALUES (126, '孟浩然', '岁暮归南山', '[\"北阙休上书  南山归敝庐\",\"不才明主弃  多病故人疏\",\"白发催年老  青阳逼岁除\",\"永怀愁不寐  松月夜窗墟\"]', 4);
INSERT INTO `poems` VALUES (127, '孟浩然', '过故人庄', '[\"故人具鸡黍  邀我至田家\",\"绿树村边合  青山郭外斜\",\"开轩面场圃  把酒话桑麻\",\"待到重阳日  还来就菊花\"]', 4);
INSERT INTO `poems` VALUES (128, '孟浩然', '秦中感秋寄远上人', '[\"一丘尝欲卧  三径苦无资\",\"北土非吾愿  东林怀我师\",\"黄金燃桂尽  壮志逐年衰\",\"日夕凉风至  闻蝉但益悲\"]', 4);
INSERT INTO `poems` VALUES (129, '孟浩然', '宿桐庐江寄广陵旧游', '[\"山暝听猿愁  沧江急夜流\",\"风鸣两岸叶  月照一孤舟\",\"建德非吾土  维扬忆旧游\",\"还将两行泪  遥寄海西头\"]', 4);
INSERT INTO `poems` VALUES (130, '孟浩然', '留别王侍御维', '[\"寂寂竟何待  朝朝空自归\",\"欲寻芳草去  惜与故人违\",\"当路谁相假  知音世所稀\",\"只应守寂寞  还掩故园扉\"]', 4);
INSERT INTO `poems` VALUES (131, '孟浩然', '早寒江上有怀', '[\"木落雁南渡  北风江上寒\",\"我家襄水曲  遥隔楚云端\",\"乡泪客中尽  孤帆天际看\",\"迷津欲有问  平海夕漫漫\"]', 4);
INSERT INTO `poems` VALUES (132, '刘长卿', '秋日登吴公台上寺远眺', '[\"古台摇落后  秋日望乡心\",\"野寺人来少  云峰水隔深\",\"夕阳依旧垒  寒磬满空林\",\"惆怅南朝事  长江独至今\"]', 4);
INSERT INTO `poems` VALUES (133, '刘常卿', '送李中丞归汉阳别业', '[\"流落征南将  曾驱十万师\",\"罢归无旧业  老去恋明时\",\"独立三边静  轻生一剑知\",\"茫茫江汉上  日暮复何之\"]', 4);
INSERT INTO `poems` VALUES (134, '刘长卿', '饯别王十一南游', '[\"望君烟水阔  挥手泪沾巾\",\"飞鸟没何处  青山空向人\",\"长江一帆远  落日五湖春\",\"谁见汀洲上  相思愁白苹\"]', 4);
INSERT INTO `poems` VALUES (135, '刘长卿', '寻南溪常山道人隐居', '[\"一路经行处  莓苔见履痕\",\"白云依静渚  春草闭闲门\",\"过雨看松色  随山到水源\",\"溪花与禅意  相对亦忘言\"]', 4);
INSERT INTO `poems` VALUES (136, '刘长卿', '新年作', '[\"乡心新岁切  天畔独潸然\",\"老至居人下  春归在客先\",\"岭猿同旦暮  江柳共风烟\",\"已似长沙傅  从今又几年\"]', 4);
INSERT INTO `poems` VALUES (137, '钱起', '送僧归日本', '[\"上国随缘住  来途若梦行\",\"浮天沧海远  去世法舟轻\",\"水月通禅寂  鱼龙听梵声\",\"惟怜一灯影  万里眼中明\"]', 4);
INSERT INTO `poems` VALUES (138, '钱起', '谷口书斋寄杨补阙', '[\"泉壑带茅茨  云霞生薜帷\",\"竹怜新雨后  山爱夕阳时\",\"闲鹭栖常早  秋花落更迟\",\"家童扫萝径  昨与故人期\"]', 4);
INSERT INTO `poems` VALUES (139, '韦应物', '淮上喜会梁川故人', '[\"江汉曾为客  相逢每醉还\",\"浮云一别后  流水十年间\",\"欢笑情如旧  萧疏鬓已斑\",\"何因北归去  淮上对秋山\"]', 4);
INSERT INTO `poems` VALUES (140, '韦应物', '赋得暮雨送李胄', '[\"楚江微雨里  建业暮钟时\",\"漠漠帆来重  冥冥鸟去迟\",\"海门深不见  浦树远含滋\",\"相送情无限  沾襟比散丝\"]', 4);
INSERT INTO `poems` VALUES (141, '韩□（“雄”右半换“羽”）', '酬程延秋夜即事见赠', '[\"长簟迎风早  空城澹月华\",\"星河秋一雁  砧杵夜千家\",\"节候看应晚  心期卧亦赊\",\"向来吟秀句  不觉已鸣鸦\"]', 4);
INSERT INTO `poems` VALUES (142, '刘脊虚', '阙题', '[\"道由白云尽  春与青溪长\",\"时有落花至  远隋流水香\",\"闲门向山路  深柳读书堂\",\"幽映每白日  清辉照衣裳\"]', 4);
INSERT INTO `poems` VALUES (143, '戴叔伦', '江乡故人偶集客舍', '[\"天秋月又满  城阙夜千重\",\"还作江南会  翻疑梦里逢\",\"风枝惊暗鹊  露草覆寒虫\",\"羁旅长堪醉  相留畏晓钟\"]', 4);
INSERT INTO `poems` VALUES (144, '卢纶', '李端公', '[\"故关衰草遍  离别正堪悲\",\"路出寒云外  人归暮雪时\",\"少孤为客早  多难识君迟\",\"掩泪空相向  风尘何处期\"]', 4);
INSERT INTO `poems` VALUES (145, '李益', '喜见外弟又言别', '[\"十年离乱后  长大一相逢\",\"问姓惊初见  称名忆旧容\",\"别来沧海事  语罢暮天钟\",\"明日巴陵道  秋山又几重\"]', 4);
INSERT INTO `poems` VALUES (146, '司空曙', '云阳馆与韩绅宿别', '[\"故人江海别  几度隔山川\",\"乍见翻疑梦  相悲各问年\",\"孤灯寒照雨  深竹暗浮烟\",\"更有明朝恨  离杯惜共传\"]', 4);
INSERT INTO `poems` VALUES (147, '司空曙', '喜外弟卢纶见宿', '[\"静夜四无邻  荒居旧业贫\",\"雨中黄叶树  灯下白头人\",\"以我独沉久  愧君相访频\",\"平生自有分  况是蔡家亲\"]', 4);
INSERT INTO `poems` VALUES (148, '司空曙', '贼平后送人北归', '[\"世乱同南去  时清独北还\",\"他乡生白发  旧国见青山\",\"晓月过残垒  繁星宿故关\",\"寒禽与衰草  处处伴愁颜\"]', 4);
INSERT INTO `poems` VALUES (149, '刘禹锡', '蜀先主庙', '[\"天地英雄气  千秋尚凛然\",\"势分三足鼎  业复五铢钱\",\"得相能开国  生儿不象贤\",\"凄凉蜀故妓  来舞魏宫前\"]', 4);
INSERT INTO `poems` VALUES (150, '张籍', '没蕃故人', '[\"前年伐月支  城下没全师\",\"蕃汉断消息  死生长别离\",\"无人收废帐  归马识残旗\",\"欲祭疑君在  天涯哭此时\"]', 4);
INSERT INTO `poems` VALUES (151, '白居易', '赋得古原草送别', '[\"离离原上草  一岁一枯荣\",\"野火烧不尽  春风吹又生\",\"远芳侵古道  晴翠接荒城\",\"又送王孙去  萋萋满别情\"]', 4);
INSERT INTO `poems` VALUES (152, '杜牧', '旅宿', '[\"旅馆无良伴  凝情自悄然\",\"寒灯思旧事  断雁警愁眠\",\"远梦归侵晓  家书到隔年\",\"沧江好烟月  门系钓鱼船\"]', 4);
INSERT INTO `poems` VALUES (153, '许浑', '秋日赴阙题潼关驿楼', '[\"红叶晚萧萧  长亭酒一瓢\",\"残云归太华  疏雨过中条\",\"树色随山迥  河声入海遥\",\"帝乡明日到  犹自梦渔樵\"]', 4);
INSERT INTO `poems` VALUES (154, '许浑', '早秋', '[\"遥夜泛清瑟  西风生翠萝\",\"残萤栖玉露  早雁拂银河\",\"高树晓还密  远山晴更多\",\"淮南一叶下  自觉老烟波\"]', 4);
INSERT INTO `poems` VALUES (155, '李商隐', '蝉', '[\"本以高难饱  徒劳恨费声\",\"五更疏欲断  一树碧无情\",\"薄宦梗犹泛  故园芜已平\",\"烦君最相警  我亦举家清\"]', 4);
INSERT INTO `poems` VALUES (156, '李商隐', '风雨', '[\"凄凉宝剑篇  羁泊欲穷年\",\"黄叶仍风雨  青楼自管弦\",\"新知遭薄俗  旧好隔良缘\",\"心断新丰酒  销愁斗几千\"]', 4);
INSERT INTO `poems` VALUES (157, '李商隐', '落花', '[\"高阁客竟去  小园花乱飞\",\"参差连曲陌  迢递送斜晖\",\"肠断未忍扫  眼穿仍欲归\",\"芳心向春尽  所得是沾衣\"]', 4);
INSERT INTO `poems` VALUES (158, '李商隐', '凉思', '[\"客去波平槛  蝉休露满枝\",\"永怀当此节  倚立自移时\",\"北斗兼春远  南陵寓使迟\",\"天涯占梦数  疑误有新知\"]', 4);
INSERT INTO `poems` VALUES (159, '李商隐', '北青萝', '[\"残阳西入崦  茅屋访孤僧\",\"落叶人何在  寒云路几层\",\"独敲初夜磬  闲倚一枝藤\",\"世界微尘里  吾宁爱与憎\"]', 4);
INSERT INTO `poems` VALUES (160, '温庭筠', '送人东游', '[\"荒戍落黄叶  浩然离故关\",\"高风汉阳渡  初日郢门山\",\"江上几人在  天涯孤棹还\",\"何当重相见  樽酒慰离颜\"]', 4);
INSERT INTO `poems` VALUES (161, '马戴', '灞上秋居', '[\"灞原风雨定  晚见雁行频\",\"落叶他乡树  寒灯独夜人\",\"空园白露滴  孤壁野僧邻\",\"寄卧郊扉久  何年致此身\"]', 4);
INSERT INTO `poems` VALUES (162, '马戴', '楚江怀古', '[\"露气寒光集  微阳下楚丘\",\"猿啼洞庭树  人在木兰舟\",\"广泽生明月  苍山夹乱流\",\"云中君不见  竟夕自悲秋\"]', 4);
INSERT INTO `poems` VALUES (163, '张乔', '书边事', '[\"调角断清秋  征人倚戍楼\",\"春风对青冢  白日落梁州\",\"大漠无兵阻  穷边有客游\",\"蕃情似此水  长愿向南流\"]', 4);
INSERT INTO `poems` VALUES (164, '崔涂', '巴山道中除夜有怀', '[\"迢递三巴路  羁危万里身\",\"乱山残雪夜  孤独异乡春\",\"渐与骨肉远  转於僮仆亲\",\"那堪正飘泊  明日岁华新\"]', 4);
INSERT INTO `poems` VALUES (165, '崔涂', '孤雁', '[\"几行归塞尽  片影独何之\",\"暮雨相呼失  寒塘欲下迟\",\"渚云低暗渡  关月冷相随\",\"未必逢［矢曾］缴  孤飞自可疑\"]', 4);
INSERT INTO `poems` VALUES (166, '杜荀鹤', '春宫怨', '[\"早被婵娟误  欲妆临镜慵\",\"承恩不在貌  教妾若为容\",\"风暖鸟声碎  日高花影重\",\"年年越溪女  相忆采芙蓉\"]', 4);
INSERT INTO `poems` VALUES (167, '韦庄', '章台夜思', '[\"清瑟怨遥夜  绕弦风雨哀\",\"孤灯闻楚角  残月下章台\",\"芳草已云暮  故人殊未来\",\"乡书不可寄  秋雁又南回\"]', 4);
INSERT INTO `poems` VALUES (168, '僧皎然', '寻陆鸿渐不遇', '[\"移家虽带郭  野径入桑麻\",\"近种篱边菊  秋来未著花\",\"扣门无犬吠  欲去问西家\",\"报到山中去  归来每日斜\"]', 4);
INSERT INTO `poems` VALUES (169, '崔颢', '黄鹤楼', '[\"昔人已乘黄鹤去  此地空馀黄鹤楼\",\"黄鹤一去不复返  白云千载空悠悠\",\"晴川历历汉阳树  芳草萋萋鹦鹉洲\",\"日暮乡关何处是  烟波江上使人愁\"]', 4);
INSERT INTO `poems` VALUES (170, '崔颢', '行经华阴', '[\"迢□（“绕”换山旁）太华俯咸京  天外三峰削不成\",\"武帝祠前云欲散  仙人掌上雨初晴\",\"河山北枕秦关险  驿树西连汉［田寺］平\",\"借问路傍名利客  无如此处学长生\"]', 4);
INSERT INTO `poems` VALUES (171, '祖咏', '望蓟门', '[\"燕台一去客心惊  箫鼓喧喧汉将营\",\"万里寒光生积雪  三边曙色动危旌\",\"沙场烽火侵胡月  海畔云山拥蓟城\",\"少小虽非投笔吏  论功还欲请长缨\"]', 4);
INSERT INTO `poems` VALUES (172, '李颀', '送魏万之京', '[\"朝闻游子唱骊歌  昨夜微霜初度河\",\"鸿雁不堪愁里听  云山况是客中过\",\"关城树色催寒近  御苑砧声向晚多\",\"莫见长安行乐处  空令岁月易蹉跎\"]', 4);
INSERT INTO `poems` VALUES (173, '崔曙', '九日登望仙台呈刘明府', '[\"汉文皇帝有高台  此日登临曙色开\",\"三晋云山皆北向  二陵风雨自东来\",\"关门令尹谁能识  河上仙翁去不回\",\"且欲竟寻彭泽宰  陶然共醉菊花杯\"]', 4);
INSERT INTO `poems` VALUES (174, '高适', '送李少府贬峡中王少府贬长沙', '[\"嗟君此别意何如  驻马衔杯问谪居\",\"巫峡啼猿数行泪  衡阳归雁几封书\",\"青枫江上秋帆远  白帝城边古木疏\",\"圣代即今多雨露  暂时分手莫踌躇\"]', 4);
INSERT INTO `poems` VALUES (175, '岑参', '奉和中书舍人贾至早朝大明宫', '[\"鸡鸣紫陌曙光寒  莺啭皇州春色阑\",\"金阙晓钟开万户  玉阶仙仗拥千官\",\"花迎剑佩星初落  柳拂旌旗露未干\",\"独有凤凰池上客  阳春一曲和皆难\"]', 4);
INSERT INTO `poems` VALUES (176, '王维', '和贾舍人早朝大明宫之作', '[\"绛帻鸡人送晓筹  尚衣方进翠云裘\",\"九天阊阖开宫殿  万国衣冠拜冕旒\",\"日色才临仙掌动  香烟欲傍衮龙浮\",\"朝罢须裁五色诏  佩声归向凤池头\"]', 4);
INSERT INTO `poems` VALUES (177, '王维', '奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制', '[\"渭水自萦秦塞曲  黄山旧绕汉宫斜\",\"銮舆迥出千门柳  阁道回看上苑花\",\"云里帝城双凤阙  雨中春树万人家\",\"为乘阳气行时令  不是宸游玩物华\"]', 4);
INSERT INTO `poems` VALUES (178, '王维', '积雨辋川庄作', '[\"积雨空林烟火迟  蒸藜炊黍饷东□（“淄”去三点水加草头）\",\"漠漠水田飞白鹭  阴阴夏木啭黄鹂\",\"山中习静观朝槿  松下清斋折露葵\",\"野老与人争席罢  海鸥何事更相疑\"]', 4);
INSERT INTO `poems` VALUES (179, '王维', '酬郭给事', '[\"洞门高阁霭馀辉  桃李阴阴柳絮飞\",\"禁里疏钟官舍晚  省中啼鸟吏人稀\",\"晨摇玉佩趋金殿  夕奉天书拜琐闱\",\"强欲从君无那老  将因卧病解朝衣\"]', 4);
INSERT INTO `poems` VALUES (180, '杜甫', '蜀相', '[\"丞相祠堂何处寻  锦官城外柏森森\",\"映阶碧草自春色  隔叶黄鹂空好音\",\"三顾频烦天下计  两朝开济老臣心\",\"出师未捷身先死  长使英雄泪满襟\"]', 4);
INSERT INTO `poems` VALUES (181, '杜甫', '客至', '[\"舍南舍北皆春水  但见群鸥日日来\",\"花径不曾缘客扫  蓬门今始为君开\",\"盘飧市远无兼味  樽酒家贫只旧醅\",\"肯与邻翁相对饮  隔篱呼取尽馀杯\"]', 4);
INSERT INTO `poems` VALUES (182, '杜甫', '野望', '[\"西山白雪三城戍  南浦清江万里桥\",\"海内风尘诸弟隔  天涯涕泪一身遥\",\"唯将迟暮供多病  未有涓埃答圣朝\",\"跨马出郊时极目  不堪人事日萧条\"]', 4);
INSERT INTO `poems` VALUES (183, '杜甫', '闻官军收河南河北', '[\"剑外忽传收蓟北  初闻涕泪满衣裳\",\"却看妻子愁何在  漫卷诗书喜欲狂\",\"白日放歌须纵酒  青春作伴好还乡\",\"即从巴峡穿巫峡  便下襄阳向洛阳\"]', 4);
INSERT INTO `poems` VALUES (184, '杜甫', '登高', '[\"风急天高猿啸哀  渚清沙白鸟飞回\",\"无边落木萧萧下  不尽长江滚滚来\",\"万里悲秋常作客  百年多病独登台\",\"艰难苦恨繁霜鬓  潦倒新停浊酒杯\"]', 4);
INSERT INTO `poems` VALUES (185, '杜甫', '登楼', '[\"花近高楼伤客心  万方多难此登临\",\"锦江春色来天地  玉垒浮云变古今\",\"北极朝庭终不改  西山寇盗莫相侵\",\"可怜后主还祠庙  日暮聊为梁父吟\"]', 4);
INSERT INTO `poems` VALUES (186, '杜甫', '宿府', '[\"清秋幕府井梧寒  独宿江城蜡炬残\",\"永夜角声悲自语  中天月色好谁看\",\"风尘荏苒音书绝  关塞萧条行陆难\",\"已忍伶俜十年事  强移栖息一枝安\"]', 4);
INSERT INTO `poems` VALUES (187, '杜甫', '阁夜', '[\"岁暮阴阳催短景  天涯霜雪霁寒霄\",\"五更鼓角声悲壮  三峡星河影动摇\",\"野哭千家闻战伐  夷歌数处起渔樵\",\"卧龙跃马终黄土  人事音书漫寂寥\"]', 4);
INSERT INTO `poems` VALUES (188, '杜甫', '咏怀古迹五首之一', '[\"支离东北风尘际  漂泊西南天地间\",\"三峡楼台淹日月  五溪衣服共云山\",\"羯胡事主终无赖  词客哀时且未还\",\"庾信平生最萧瑟  暮年诗赋动江关\"]', 4);
INSERT INTO `poems` VALUES (189, '杜甫', '咏怀古迹五首之二', '[\"摇落深知宋玉悲  风流儒雅亦吾师\",\"怅望千秋一洒泪  萧条异代不同时\",\"江山故宅空文藻  云雨荒台岂梦思\",\"最是楚宫俱泯灭  舟人指点到今疑\"]', 4);
INSERT INTO `poems` VALUES (190, '杜甫', '咏怀古迹五首之三', '[\"群山万壑赴荆门  生长明妃尚有村\",\"一去紫台连朔漠  独留青冢向黄昏\",\"画图省识春风面  环佩空归月下魂\",\"千载琵琶作胡语  分明怨恨曲中论\"]', 4);
INSERT INTO `poems` VALUES (191, '杜甫', '咏怀古迹五首之四', '[\"蜀主征吴幸三峡  崩年亦在永安宫\",\"翠华想像空山里  玉殿虚无野寺中\",\"古庙杉松巢水鹤  岁时伏腊走村翁\",\"武侯祠屋常邻近  一体君臣祭祀同\"]', 4);
INSERT INTO `poems` VALUES (192, '杜甫', '咏怀古迹五首之五', '[\"诸葛大名垂宇宙  宗臣遗像肃清高\",\"三分割据纡筹策  万古云霄一羽毛\",\"伯仲之间见伊吕  指挥若定失萧曹\",\"运移汉祚终难复  志决身歼军务劳\"]', 4);
INSERT INTO `poems` VALUES (193, '刘长卿', '江州重别薛六柳八二员外', '[\"生涯岂料承优诏  世事空知学醉歌\",\"江上月明胡雁过  淮南木落楚山多\",\"寄身且喜沧洲近  顾影无如白发何\",\"今日龙钟人共老  愧君犹遣慎风波\"]', 4);
INSERT INTO `poems` VALUES (194, '刘长卿', '长沙过贾谊宅', '[\"三年谪宦此栖迟  万古惟留楚客悲\",\"秋草独寻人去后  寒林空见日斜时\",\"汉文有道恩犹薄  湘水无情吊岂知\",\"寂寂江山摇落处  怜君何事到天涯\"]', 4);
INSERT INTO `poems` VALUES (195, '刘长卿', '自夏口至鹦洲夕望岳阳寄源中丞', '[\"汀洲无浪复无烟  楚客相思益渺然\",\"汉口夕阳斜渡鸟  洞庭秋水远连天\",\"孤城背岭寒吹角  独戍临江夜泊船\",\"贾谊上书忧汉室  长沙谪去古今怜\"]', 4);
INSERT INTO `poems` VALUES (196, '钱起', '赠阙下裴舍人', '[\"二月黄鹂飞上林  春城紫禁晓阴阴\",\"长乐钟声花外尽  龙池柳色雨中深\",\"阳和不散穷途恨  霄汉长怀捧日心\",\"献赋十年犹未遇  羞将白发对华簪\"]', 4);
INSERT INTO `poems` VALUES (197, '韦应物', '寄李儋元锡', '[\"去年花里逢君别  今日花开又一年\",\"世事茫茫难自料  春愁黯黯独成眠\",\"身多疾病思田里  邑有流亡愧俸钱\",\"闻道欲来相问讯  西楼望月几回圆\"]', 4);
INSERT INTO `poems` VALUES (198, '韩□', '同题仙游观', '[\"仙台初见五城楼  风物凄凄宿雨收\",\"山色遥连秦树晚  砧声近报汉宫秋\",\"疏松影落空坛静  细草香闲小洞幽\",\"何用别寻方外去  人间亦自有丹丘\"]', 4);
INSERT INTO `poems` VALUES (199, '皇甫冉', '春思', '[\"莺啼燕语报新年  马邑龙堆路几千\",\"家住层城邻汉苑  心随明月到胡天\",\"机中锦字论长恨  楼上花枝笑独眠\",\"为问天戎窦车骑  何时返旆勒燕然\"]', 4);
INSERT INTO `poems` VALUES (200, '卢纶', '晚次鄂州', '[\"云开远见汉阳城  犹是孤帆一日程\",\"估客昼眠知浪静  舟人夜语觉潮生\",\"三湘愁鬓逢秋色  万里归心对月明\",\"旧业已随征战尽  更堪江上鼓鼙声\"]', 4);
INSERT INTO `poems` VALUES (201, '柳宗元', '登柳州城楼寄漳汀封连四州刺史', '[\"城上高楼接大荒  海天愁思正茫茫\",\"惊风乱［风占）芙蓉水  密雨斜侵薜荔墙\",\"岭树重遮千里目  江流曲似九回肠\",\"共来百越文身地  犹自音书滞一乡\"]', 4);
INSERT INTO `poems` VALUES (202, '刘禹锡', '西塞山怀古', '[\"王浚楼船下益州  金陵王气黯然收\",\"千寻铁锁沈江底  一片降幡出石头\",\"人世几回伤往事  山形依旧枕寒流\",\"从今四海为家日  故垒萧萧芦荻秋\"]', 4);
INSERT INTO `poems` VALUES (203, '元稹', '遣悲怀三首之一', '[\"谢公最小偏怜女  自嫁黔娄百事乖\",\"顾我无衣搜荩箧  泥他沽酒拔金钗\",\"野蔬充膳甘长藿  落叶添薪仰古槐\",\"今日俸钱过十万  与君营奠复营斋\"]', 4);
INSERT INTO `poems` VALUES (204, '元稹', '遣悲怀三首之二', '[\"昔日戏言身后事  今朝都到眼前来\",\"衣裳已施行看尽  针线犹存未忍开\",\"尚想旧情怜婢仆  也曾因梦送钱财\",\"诚知此恨人人有  贫贱夫妻百事哀\"]', 4);
INSERT INTO `poems` VALUES (205, '元稹', '遣悲怀三首之三', '[\"闲坐悲君亦自悲  百年都是几多时\",\"邓攸无子寻知命  潘岳悼亡犹费词\",\"同穴□（上“穴”下“目”）冥何所望  他生缘会更难期\",\"惟将终夜长开眼  报答平生未展眉\"]', 4);
INSERT INTO `poems` VALUES (206, '李商隐', '锦瑟', '[\"锦瑟无端五十弦  一弦一柱思华年\",\"庄生晓梦迷蝴蝶  望帝春心托杜鹃\",\"沧海月明珠有泪  蓝田日暖玉生烟\",\"此情可待成追忆  只是当时已惘然\"]', 4);
INSERT INTO `poems` VALUES (207, '李商隐', '无题', '[\"昨夜星辰昨夜风  画楼西畔桂堂东\",\"身无彩凤双飞翼  心有灵犀一点通\",\"隔座送钩春酒暖  分曹射覆蜡灯红\",\"嗟余听鼓应官去  走马兰台类转蓬\"]', 4);
INSERT INTO `poems` VALUES (208, '李商隐', '隋宫', '[\"紫泉宫殿锁烟霞  欲取芜城作帝家\",\"玉玺不缘归日角  锦帆应是到天涯\",\"於今腐草无萤火  终古垂杨有暮鸦\",\"地下若逢陈后主  岂宜重问后庭花\"]', 4);
INSERT INTO `poems` VALUES (209, '李商隐', '无题二首之一', '[\"来是空言去绝踪  月斜楼上五更钟\",\"梦为远别啼难唤  书被催成墨未浓\",\"蜡照半笼金翡翠  麝熏微度绣芙蓉\",\"刘郎已恨蓬山远  更隔蓬山一万重\"]', 4);
INSERT INTO `poems` VALUES (210, '李商隐', '无题二首之二', '[\"飒飒东风细雨来  芙蓉塘外有轻雷\",\"金蟾啮锁烧香入  玉虎牵丝汲井回\",\"贾氏窥帘韩掾少  宓妃留枕魏王才\",\"春心莫共花争发  一寸相思一寸灰\"]', 4);
INSERT INTO `poems` VALUES (211, '李商隐', '筹笔驿', '[\"猿鸟犹疑畏简书  风云常为护储胥\",\"徒令上将挥神笔  终见降王走传车\",\"管乐有才原不忝  关张无命欲何如\",\"他年锦里经祠庙  梁父吟成恨有馀\"]', 4);
INSERT INTO `poems` VALUES (212, '李商隐', '无题', '[\"相见时难别亦难  东风无力百花残\",\"春蚕到死丝方尽  蜡炬成灰泪始干\",\"晓镜但愁云鬓改  夜吟应觉月光寒\",\"蓬莱此去无多路  青鸟殷勤为探看\"]', 4);
INSERT INTO `poems` VALUES (213, '李商隐', '春雨', '[\"怅卧新春白袷衣  白门寥落意多违\",\"红楼隔雨相望冷  珠箔飘灯独自归\",\"远路应悲春［日宛］晚  残宵犹得梦依稀\",\"玉［王当］缄札何由达  万里云罗一雁飞\"]', 4);
INSERT INTO `poems` VALUES (214, '李商隐', '无题二首之一', '[\"凤尾香罗薄几重  碧文圆顶夜深缝\",\"扇裁月魄羞难掩  车走雷声语未通\",\"曾是寂寥金烬暗  断无消息石榴红\",\"斑骓只系垂杨岸  何处西南任好风\"]', 4);
INSERT INTO `poems` VALUES (215, '李商隐', '无题二首之二', '[\"重帷深下莫愁堂  卧后清宵细细长\",\"神女生涯原是梦  小姑居处本无郎\",\"风波不信菱枝弱  月露谁教桂叶香\",\"直道相思了无益  未妨惆怅是清狂\"]', 4);
INSERT INTO `poems` VALUES (216, '温庭筠', '利洲南渡', '[\"澹然空水对斜晖  曲岛苍茫接翠微\",\"波上马嘶看棹去  柳边人歇待船归\",\"数丛沙草群鸥散  万顷江田一鹭飞\",\"谁解乘舟寻范蠡  五湖烟水独忘机\"]', 4);
INSERT INTO `poems` VALUES (217, '温庭筠', '苏武庙', '[\"苏武魂销汉使前  古祠高树两茫然\",\"云边雁断胡天月  陇上羊归塞草烟\",\"回日楼台非甲帐  去时冠剑是丁年\",\"茂陵不见封侯印  空向秋波哭逝川\"]', 4);
INSERT INTO `poems` VALUES (218, '薛逢', '宫词', '[\"十二楼中尽晓妆  望仙楼上望君王\",\"锁衔金兽连环冷  水滴铜龙昼漏长\",\"云髻罢梳还对镜  罗衣欲换更添香\",\"遥窥正殿帘开处  袍裤宫人扫御床\"]', 4);
INSERT INTO `poems` VALUES (219, '秦韬玉', '贫女', '[\"蓬门未识绮罗香  拟托良媒益自伤\",\"谁爱风流高格调  共怜时世俭梳妆\",\"敢将十指夸针巧  不把双眉斗画长\",\"苦恨年年压金线  为他人作嫁衣裳\"]', 4);
INSERT INTO `poems` VALUES (220, '沈全期', '古意呈补阙乔知之', '[\"卢家少妇郁金香  海燕双栖玳瑁梁\",\"九月寒砧催木叶  十年征戍忆辽阳\",\"白狼河北音书断  丹凤城南秋夜长\",\"谁为含愁独不见  更教明月照流黄\"]', 4);
INSERT INTO `poems` VALUES (221, '王维', '鹿柴', '[\"空山不见人  但闻人语响\",\"返景入深林  复照青苔上\"]', 2);
INSERT INTO `poems` VALUES (222, '王维', '竹里馆', '[\"独坐幽篁里  弹琴复长啸\",\"深林人不知  明月来相照\"]', 2);
INSERT INTO `poems` VALUES (223, '王维', '送别', '[\"山中相送罢  日暮掩柴扉\",\"春草明年绿  王孙归不归\"]', 2);
INSERT INTO `poems` VALUES (224, '王维', '相思', '[\"红豆生南国  春来发几枝\",\"愿君多采撷  此物最相思\"]', 2);
INSERT INTO `poems` VALUES (225, '王维', '杂诗', '[\"君自故乡来  应知故乡事\",\"来日绮窗前  寒梅著花未\"]', 2);
INSERT INTO `poems` VALUES (226, '裴迪', '送崔九', '[\"归山深浅去  须尽丘壑美\",\"莫学武陵人  暂游桃源里\"]', 2);
INSERT INTO `poems` VALUES (227, '祖咏', '终南望馀雪', '[\"终南阴岭秀  积雪浮云端\",\"林表明霁色  城中增暮寒\"]', 2);
INSERT INTO `poems` VALUES (228, '孟浩然', '宿建德江', '[\"移舟泊烟渚  日暮客愁新\",\"野旷天低树  江清月近人\"]', 2);
INSERT INTO `poems` VALUES (229, '孟浩然', '春晓', '[\"春眠不觉晓  处处闻啼鸟\",\"夜来风雨声  花落知多少\"]', 2);
INSERT INTO `poems` VALUES (230, '李白', '夜思', '[\"床前明月光  疑是地上霜\",\"举头望明月  低头思故乡\"]', 2);
INSERT INTO `poems` VALUES (231, '李白', '怨情', '[\"美人卷珠帘  深坐蹙蛾眉\",\"但见泪痕湿  不知心恨谁\"]', 2);
INSERT INTO `poems` VALUES (232, '杜甫', '八阵图', '[\"功盖三分国  名成八阵图\",\"江流石不转  遗恨失吞吴\"]', 2);
INSERT INTO `poems` VALUES (233, '王之涣', '登鹳雀楼', '[\"白日依山尽  黄河入海流\",\"欲穷千里目  更上一层楼\"]', 2);
INSERT INTO `poems` VALUES (234, '刘长卿', '送灵澈', '[\"苍苍竹林寺  杳杳钟声晚\",\"荷笠带斜阳  青山独归远\"]', 2);
INSERT INTO `poems` VALUES (235, '刘长卿', '弹琴', '[\"泠泠七弦上  静听松风寒\",\"古调虽自爱  今人多不弹\"]', 2);
INSERT INTO `poems` VALUES (236, '刘长卿', '送上人', '[\"孤云将野鹤  岂向人间\",\"莫买沃洲山  时人已知处\"]', 2);
INSERT INTO `poems` VALUES (237, '韦应物', '秋夜寄邱员外', '[\"怀君属秋夜  散步咏凉天\",\"空山松子落  幽人应未眠\"]', 2);
INSERT INTO `poems` VALUES (238, '李端', '听筝', '[\"鸣筝金粟柱  素手玉房前\",\"欲得周郎顾  时时误拂弦\"]', 2);
INSERT INTO `poems` VALUES (239, '王建', '新嫁娘', '[\"三日入厨下  洗手作羹汤\",\"未谙姑食性  先遣小姑尝\"]', 2);
INSERT INTO `poems` VALUES (240, '权德舆', '玉台体', '[\"昨夜裙带解  今朝［虫喜］子飞\",\"铅华不可弃  莫是藁砧归\"]', 2);
INSERT INTO `poems` VALUES (241, '柳宗元', '江雪', '[\"千山鸟飞绝  万径人踪灭\",\"孤舟蓑笠翁  独钓寒江雪\"]', 2);
INSERT INTO `poems` VALUES (242, '白居易', '问刘十九', '[\"绿蚁新醅酒  红泥小火炉\",\"晚来天欲雪  能饮一杯无\"]', 2);
INSERT INTO `poems` VALUES (243, '张祜', '何满子', '[\"故国三千里  深宫二十年\",\"一声何满子  双泪落君前\"]', 2);
INSERT INTO `poems` VALUES (244, '李商隐', '登乐游原', '[\"向晚意不适  驱车登古原\",\"夕阳无限好  只是近黄昏\"]', 2);
INSERT INTO `poems` VALUES (245, '贾岛', '寻隐者不遇', '[\"松下问童子  言师采药去\",\"只在此山中  云深不知处\"]', 2);
INSERT INTO `poems` VALUES (246, '李频', '渡汉江', '[\"岭外音书绝  经冬复立春\",\"近乡情更怯  不敢问来人\"]', 2);
INSERT INTO `poems` VALUES (247, '金昌绪', '春怨', '[\"打起黄莺儿  莫教枝上啼\",\"啼时惊妾梦  不得到辽西\"]', 2);
INSERT INTO `poems` VALUES (248, '西鄙人', '哥舒歌', '[\"北斗七星高  哥舒夜带刀\",\"至今窥牧马  不敢过临洮\"]', 2);
INSERT INTO `poems` VALUES (249, '崔颢', '长干行二首之一', '[\"君家何处住  妾住在横塘\",\"停船暂借问  或恐是同乡\"]', 2);
INSERT INTO `poems` VALUES (250, '崔颢', '长干行二首之二', '[\"家临九江水  来去九江侧\",\"同是长干人  生小不相识\"]', 2);
INSERT INTO `poems` VALUES (251, '李白', '玉阶怨', '[\"玉阶生白露  夜久侵罗袜\",\"却下水晶帘  玲珑望秋月\"]', 2);
INSERT INTO `poems` VALUES (252, '卢纶', '塞下曲四首之一', '[\"鹫翎金仆姑  燕尾绣蝥弧\",\"独立扬新令  千营共一呼\"]', 2);
INSERT INTO `poems` VALUES (253, '卢纶', '塞下曲四首之二', '[\"林暗草惊风  将军夜引弓\",\"平明寻白羽  没在石棱中\"]', 2);
INSERT INTO `poems` VALUES (254, '卢纶', '塞下曲四首之三', '[\"月黑雁飞高  单于夜遁逃\",\"欲将轻骑逐  大雪满弓刀\"]', 2);
INSERT INTO `poems` VALUES (255, '卢纶', '塞下曲四首之四', '[\"野幕蔽琼筵  羌戎贺劳旋\",\"醉和金甲舞  雷鼓动山川\"]', 2);
INSERT INTO `poems` VALUES (256, '李益', '江南曲', '[\"嫁得瞿塘贾  朝朝误妾期\",\"早知潮有信  嫁与弄潮儿\"]', 2);
INSERT INTO `poems` VALUES (257, '贺知章', '回乡偶书', '[\"少小离家老大回  乡音无改鬓毛衰\",\"儿童相见不相识  笑问客从何处来\"]', 2);
INSERT INTO `poems` VALUES (258, '张旭', '桃花溪', '[\"隐隐飞桥隔野烟  石矶西畔问渔船\",\"桃花尽日随流水  洞在清溪何处边\"]', 2);
INSERT INTO `poems` VALUES (259, '王维', '九月九日忆山东兄弟', '[\"独在异乡为异客  每逢佳节倍思亲\",\"遥知兄弟登高处  遍插茱萸少一人\"]', 2);
INSERT INTO `poems` VALUES (260, '王昌龄', '芙蓉楼送辛渐', '[\"寒雨连江夜入吴  平明送客楚山孤\",\"洛阳亲友如相问  一片冰心在玉壶\"]', 2);
INSERT INTO `poems` VALUES (261, '王昌龄', '闺怨', '[\"闺中少妇不知愁  春日凝妆上翠楼\",\"忽见陌头杨柳色  悔教夫婿觅封侯\"]', 2);
INSERT INTO `poems` VALUES (262, '王昌龄', '春宫曲', '[\"昨夜风开露井桃  未央前殿月轮高\",\"平阳歌舞新承宠  帘外春寒赐锦袍\"]', 2);
INSERT INTO `poems` VALUES (263, '王翰', '凉州词', '[\"葡萄美酒夜光杯  欲饮琵琶马上催\",\"醉卧沙场君莫笑  古来征战几人回\"]', 2);
INSERT INTO `poems` VALUES (264, '李白', '送孟浩然之广陵', '[\"故人西辞黄鹤楼  烟花三月下扬州\",\"孤帆远影碧空尽  惟见长江天际流\"]', 2);
INSERT INTO `poems` VALUES (265, '李白', '下江陵', '[\"朝辞白帝彩云间  千里江陵一日还\",\"两岸猿声啼不住  轻舟已过万重山\"]', 2);
INSERT INTO `poems` VALUES (266, '岑参', '逢入京使', '[\"故园东望路漫漫  双袖龙钟泪不干\",\"马上相逢无纸笔  凭君传语报平安\"]', 2);
INSERT INTO `poems` VALUES (267, '杜甫', '江南逢李龟年', '[\"岐王宅里寻常见  崔九堂前几度闻\",\"正是江南好风景  落花时节又逢君\"]', 2);
INSERT INTO `poems` VALUES (268, '韦应物', '滁州西涧', '[\"独怜幽草涧边生  上有黄鹂深树鸣\",\"春潮带雨晚来急  野渡无人舟自横\"]', 2);
INSERT INTO `poems` VALUES (269, '张继', '枫桥夜泊', '[\"月落乌啼霜满天  江枫渔火对愁眠\",\"姑苏城外寒山寺  夜半钟声到客船\"]', 2);
INSERT INTO `poems` VALUES (270, '韩□', '寒食', '[\"春城无处不飞花  寒食东风御柳斜\",\"日暮汉宫传蜡烛  轻烟散入五侯家\"]', 2);
INSERT INTO `poems` VALUES (271, '刘方平', '月夜', '[\"更深月色半人家  北斗阑干南斗斜\",\"今夜偏知春气暖  虫声新透绿窗纱\"]', 2);
INSERT INTO `poems` VALUES (272, '刘方平', '春怨', '[\"纱窗日落渐黄昏  金屋无人见泪痕\",\"寂寞空庭春欲晚  梨花满地不开门\"]', 2);
INSERT INTO `poems` VALUES (273, '柳中庸', '征人怨', '[\"岁岁金河复玉关  朝朝马策与刀环\",\"三春白雪归青冢  万里黄河绕黑山\"]', 2);
INSERT INTO `poems` VALUES (274, '顾况', '宫词', '[\"玉楼天半起笙歌  风送宫嫔笑语和\",\"月殿影开闻夜漏  水晶帘卷近秋河\"]', 2);
INSERT INTO `poems` VALUES (275, '李益', '夜上受降城闻笛', '[\"回乐峰前沙似雪  受降城外月如霜\",\"不知何处吹芦管  一夜征人尽望乡\"]', 2);
INSERT INTO `poems` VALUES (276, '刘禹锡', '乌衣巷', '[\"朱雀桥边野草花  乌衣巷口夕阳斜\",\"旧时王谢堂前燕  飞入寻常百姓家\"]', 2);
INSERT INTO `poems` VALUES (277, '刘禹锡', '春词', '[\"新妆宜面下朱楼  深锁春光一院愁\",\"行到中庭数花朵  蜻蜓飞上玉搔头\"]', 2);
INSERT INTO `poems` VALUES (278, '白居易', '后宫词', '[\"泪湿罗巾梦不成  夜深前殿按歌声\",\"红颜未老恩先断  斜倚薰笼坐到明\"]', 2);
INSERT INTO `poems` VALUES (279, '张祜', '赠内人', '[\"禁门宫树月痕过  媚眼惟看宿鹭窠\",\"斜拔玉钗灯影畔  剔开红焰救飞蛾\"]', 2);
INSERT INTO `poems` VALUES (280, '张祜', '集灵台二首之一', '[\"日光斜照集灵台  红树花迎晓露开\",\"昨夜上皇新授□（“录”加竹头）  太真含笑入帘来\"]', 2);
INSERT INTO `poems` VALUES (281, '张祜', '集灵台二首之二', '[\"虢国夫人承主恩  平明骑马入宫门\",\"却嫌脂粉污颜色  淡扫蛾眉朝至尊\"]', 2);
INSERT INTO `poems` VALUES (282, '张祜', '题金陵渡', '[\"金陵津渡小山楼  一宿行人自可愁\",\"潮落夜江斜月里  两三星火是瓜州\"]', 2);
INSERT INTO `poems` VALUES (283, '朱庆馀', '宫词', '[\"寂寂花时闭院门  美人相并立琼轩\",\"含情欲说宫中事  鹦鹉前头不敢言\"]', 2);
INSERT INTO `poems` VALUES (284, '朱庆馀', '近试上张水部', '[\"洞房昨夜停红烛  待晓堂前拜舅姑\",\"妆罢低声问夫婿  画眉深浅入时无\"]', 2);
INSERT INTO `poems` VALUES (285, '杜牧', '将赴吴兴登乐游原', '[\"清时有味是无能  闲爱孤云静爱僧\",\"欲把一麾江海去  乐游原上望昭陵\"]', 2);
INSERT INTO `poems` VALUES (286, '杜牧', '赤壁', '[\"折戟沈沙铁未销  自将磨洗认前朝\",\"东风不与周郎便  铜雀春深销二乔\"]', 2);
INSERT INTO `poems` VALUES (287, '杜牧', '泊秦淮', '[\"烟笼寒水月笼沙  夜泊秦淮近酒家\",\"商女不知亡国恨  隔江犹唱后庭花\"]', 2);
INSERT INTO `poems` VALUES (288, '杜牧', '寄扬州韩绰判官', '[\"青山隐隐水迢迢  秋尽江南草未凋\",\"二十四桥明月夜  玉人何处教吹箫\"]', 2);
INSERT INTO `poems` VALUES (289, '杜牧', '遣怀', '[\"落魄江湖载酒行  楚腰纤细掌中轻\",\"十年一觉扬州梦  赢得青楼薄幸名\"]', 2);
INSERT INTO `poems` VALUES (290, '杜牧', '秋夕', '[\"银烛秋光冷画屏  轻罗小扇扑流萤\",\"天阶夜色凉如水  坐看牵牛织女星\"]', 2);
INSERT INTO `poems` VALUES (291, '杜牧', '赠别二首之一', '[\"娉娉袅袅十三馀  豆蔻梢头二月初\",\"春风十里扬州路  卷上珠帘总不如\"]', 2);
INSERT INTO `poems` VALUES (292, '杜牧', '赠别二首之二', '[\"多情却似总无情  唯觉樽前笑不成\",\"蜡烛有心还惜别  替人垂泪到天明\"]', 2);
INSERT INTO `poems` VALUES (293, '杜牧', '金谷园', '[\"繁华事散逐香尘  流水无情草自春\",\"日暮东风怨啼鸟  落花犹似坠楼人\"]', 2);
INSERT INTO `poems` VALUES (294, '李商隐', '夜雨寄北', '[\"君问归期未有期  巴山夜雨涨秋池\",\"何当共剪西窗烛  却话巴山夜雨时\"]', 2);
INSERT INTO `poems` VALUES (295, '李商隐', '寄令狐郎中', '[\"嵩云秦树久离居  双鲤迢迢一纸笔\",\"休问梁园旧宾客  茂陵秋雨病相如\"]', 2);
INSERT INTO `poems` VALUES (296, '李商隐', '为有', '[\"为有云屏无限娇  凤城寒尽怕春宵\",\"无端嫁得金龟婿  辜负香衾事早朝\"]', 2);
INSERT INTO `poems` VALUES (297, '李商隐', '隋宫', '[\"乘兴南游不戒严  九重谁省谏书函\",\"春风举国裁宫锦  半作障泥半作帆\"]', 2);
INSERT INTO `poems` VALUES (298, '李商隐', '瑶池', '[\"瑶池阿母绮窗开  黄竹歌声动地哀\",\"八骏日行三万里  穆王何事不重来\"]', 2);
INSERT INTO `poems` VALUES (299, '李商隐', '嫦娥', '[\"云母屏风烛影深  长河渐落晓星沈\",\"嫦娥应悔偷灵药  碧海青天夜夜心\"]', 2);
INSERT INTO `poems` VALUES (300, '李商隐', '贾生', '[\"宣室求贤访逐臣  贾生才调更无伦\",\"可怜夜半虚前席  不问苍生问鬼神\"]', 2);
INSERT INTO `poems` VALUES (301, '温庭筠', '瑶瑟怨', '[\"冰簟银床梦不成  碧天如水夜云轻\",\"雁声远过潇湘去  十二楼中月自明\"]', 2);
INSERT INTO `poems` VALUES (302, '郑畋', '马嵬坡', '[\"玄宗回马杨妃死  云雨难忘日月新\",\"终是圣明天子事  景阳宫井又何人\"]', 2);
INSERT INTO `poems` VALUES (303, '韩□', '已凉', '[\"碧阑干外绣帘垂  猩色屏风画折枝\",\"八尺龙须方锦褥  已凉天气未寒时\"]', 2);
INSERT INTO `poems` VALUES (304, '韦庄', '金陵图', '[\"江雨霏霏江草齐  六朝如梦鸟空啼\",\"无情最是台城柳  依旧烟笼十里堤\"]', 2);
INSERT INTO `poems` VALUES (305, '陈陶', '陇西行', '[\"誓扫匈奴不顾身  五千貂锦丧胡尘\",\"可怜无定河边骨  犹是深闺梦里人\"]', 2);
INSERT INTO `poems` VALUES (306, '张泌', '寄人', '[\"别梦依依到谢家  小廊回合曲阑斜\",\"多情只有春庭月  犹为离人照落花\"]', 2);
INSERT INTO `poems` VALUES (307, '无名氏', '杂诗', '[\"尽寒食雨草萋萋  著麦苗风柳映堤\",\"等是有家归未得  杜鹃休向耳边啼\"]', 2);
INSERT INTO `poems` VALUES (308, '王维', '渭城曲', '[\"渭城朝雨［氵邑］轻尘  客舍青青柳色新\",\"劝君更尽一杯酒  西出阳关无故人\"]', 2);
INSERT INTO `poems` VALUES (309, '王维', '秋夜曲', '[\"桂魄初生秋露微  轻罗已薄未更衣\",\"银筝夜久殷勤弄  心怯空房不忍归\"]', 2);
INSERT INTO `poems` VALUES (310, '王昌龄', '长信怨', '[\"奉帚平明金殿开  且将团扇共徘徊\",\"玉颜不及寒鸦色  犹带昭阳日影来\"]', 2);
INSERT INTO `poems` VALUES (311, '王昌龄', '出塞', '[\"秦时明月汉时关  万里长征人未还\",\"但使龙城飞将在  不教胡马渡阴山\"]', 2);
INSERT INTO `poems` VALUES (312, '王之涣', '出塞', '[\"黄河远上白云间  一片孤城万仞山\",\"羌笛何须怨杨柳  春风不度玉门关\"]', 2);
INSERT INTO `poems` VALUES (313, '李白', '清平调三首之一', '[\"云想衣裳花想容  春风拂槛露华浓\",\"若非群玉山头见  会向瑶台月下逢\"]', 2);
INSERT INTO `poems` VALUES (314, '李白', '清平调三首之二', '[\"一枝红艳露凝香  云雨巫山枉断肠\",\"借问汉宫谁得似  可怜飞燕倚新妆\"]', 2);
INSERT INTO `poems` VALUES (315, '李白', '清平调三首之三', '[\"名花倾国两相欢  常得君王带笑看\",\"解释春风无限恨  沈香亭北倚阑干\"]', 2);
INSERT INTO `poems` VALUES (316, '杜秋娘', '金缕衣', '[\"劝君莫惜金缕衣  劝君惜取少年时\",\"花开堪折直须折  莫待无花空折枝\"]', 2);
INSERT INTO `poems` VALUES (317, '杜甫', '无题', '[\"此道昔归顺  西郊胡正繁\",\"至今残破胆  应有未招魂\",\"近得归京邑  移官岂至尊\",\"无才日衰老  驻马望千门\"]', 4);
INSERT INTO `poems` VALUES (318, '白居易', '无题', '[\"时难年荒世业空  弟兄羁旅各西东\",\"田园寥落干戈后  骨肉流离道路中\",\"吊影分为千里雁  辞根散作九秋蓬\",\"共看明月应垂泪  一夜乡心五处同\"]', 4);
INSERT INTO `poems` VALUES (319, '元稹', '行宫', '[\"寥落古行宫  宫花寂寞红\",\"白头宫女在  闲坐说玄宗\"]', 2);
INSERT INTO `posts` VALUES (1, 'query_bbs', '1', 'Yi Ye Zhi Qiu (Vikee)', NULL, 'Administrator identified start_room locations in xyj2000.\nSome are familiar, some are strange. Should be helpful for players here.\n\n---Room Name-----------File Path---------------Description-------------\n             |                              |\n1. Despair Valley  |/d/death/block.c              | Place where criminals are imprisoned infinitely.\n2. Respawn Point    |/d/death/new-walk2.c          | Location after resurrection.\n3. Welcome Room    |/d/wiz/guest.c                | Wizard welcome room, new wizards report here.\n4. Confinement      |/d/wiz/punish.c               | Confinement room. No entry without permission.\n5. Rest Room    |/d/xueshan/restroom.c         | Snow mountain rest room.\n6. Lingtai Fangcun  |/d/lingtai/jingtang.c         | Patriarch Bodhi location.\n7. Moon Palace      |/d/moon/courtyard.c           | Moon Princess residence.\n8. Guanghan Courtyard  |/d/moon/xiaoyuan.c            | Moon Princess BOARD location.\n9. Dragon Palace Front Hall  |/d/sea/yuejie2.c              | Dragon King Princess BOARD location.\n10.Mountain Gate      |/d/nanhai/gate.c              | Nanhai Putuo Mountain gate.\n11.Square      |/d/nanhai/guangchang.c        | Nanhai Guanyin Bodhisattva location.\n12.Wuzhuang Temple    |/d/qujing/wuzhuang/zhengdian.c| Wuzhuang Temple has the sect master.', 1, 1012558676, NULL, 5, 0, 0, '2026-06-28 18:11:29');
INSERT INTO `posts` VALUES (2, 'query_bbs', '2', 'Yi Ye Zhi Qiu (Vikee)', NULL, 'Administrator identified start_room locations in xyj2000.\nstart_room settings are saved in archives, next login will start from there.\nSome are familiar, some are strange. Should be helpful for players here.\n\n---Room Name-----------File Path--------------------------Description-------------\n             |                              |\n1. Despair Valley  |/d/death/block.c              | Place where criminals are imprisoned infinitely.\n2. Respawn Point    |/d/death/new-walk2.c          | Location after resurrection.\n3. Welcome Room    |/d/wiz/guest.c                | Wizard welcome room, new wizards report here.\n4. Confinement      |/d/wiz/punish.c               | Confinement room. No entry without permission.\n5. Rest Room    |/d/xueshan/restroom.c         | Snow mountain rest room.\n6. Lingtai Fangcun  |/d/lingtai/jingtang.c         | Patriarch Bodhi location.\n7. Moon Palace      |/d/moon/courtyard.c           | Moon Princess residence.\n8. Guanghan Courtyard  |/d/moon/xiaoyuan.c            | Moon Princess BOARD location.\n9. Dragon Palace Front Hall  |/d/sea/yuejie2.c              | Dragon King Princess BOARD location.\n10.Mountain Gate      |/d/nanhai/gate.c              | Nanhai Putuo Mountain gate.\n11.Square      |/d/nanhai/guangchang.c        | Nanhai Guanyin Bodhisattva location.\n12.Wuzhuang Temple    |/d/qujing/wuzhuang/zhengdian.c| Wuzhuang Temple has the sect master.\n13.Baoxiang Kingdom    |/d/qujing/baoxiang/mazhan.c   | Baoxiang Kingdom horse station.\n14.Jiting Pavilion    |/d/qujing/biqiu/jinting.c     | Biqiu Kingdom Jiting Pavilion.\n15.Windmill      |/d/qujing/chechi/feng.c       | Chechi Kingdom windmill.\n16.Dragon Tower      |/d/qujing/chechi/long.c       | Chechi Kingdom dragon tower.\n17.Zhaizhan      |/d/qujing/fengxian/zhaizhan.c | Fengxian County Zhaizhan.\n18.Small Shop      |/d/qujing/firemount/xiaodian.c| Huoyanshan small shop.\n19.Guesthouse      |/d/qujing/jinping/kedian.c    | Jinping Prefecture guesthouse.\n20.Yunqi Platform    |/d/qujing/jisaiguo/yunqi.c    | Jisaiguo Yunqi Platform.\n21.Annei      |/d/qujing/nuerguo/annei.c     | Nuerguo Kingdom Bull Demon King cave.\n22.Imperial Garden    |/d/qujing/nuerguo/greenyard.c | Nuerguo Kingdom Imperial Garden.\n23.Small Tavern    |/d/qujing/qinfa/xiaoer.c      | Qinfa Town small tavern.\n24.Guesthouse      |/d/qujing/tianzhu/kedian.c    | Tianzhu Kingdom guesthouse.\n25.Kitchen      |/d/qujing/wudidong/kitchen.c  | Wudidong kitchen.\n26.General Store    |/d/qujing/wudidong/shop.c     | Wudidong general store.\n27.Steamer      |/d/qujing/wudidong/steammer.c | Steamer :D\n28.Kaiyuan Guesthouse  |/d/qujing/wuji/kezhan.c       | Wuji Kingdom Kaiyuan Guesthouse.\n29.Daike Hall    |/d/qujing/yuhua/daike.c       | Yuhuazhou Daike Hall.\n30.Huitong Hall    |/d/qujing/zhuzi/huitong.c     | Zhuzi Kingdom Huitong Hall.\n31.Prison      |/d/qujing/baihuling/jail.c    | Baihuling prison BUG testing.\n32.Living Room      |/d/jjf/keting.c               | Juxianzhuang living room.\n33.Nancheng Guesthouse  |/d/city/kezhan.c              | No need to explain this. :)\n34.Bianliang Guesthouse  |/d/kaifeng/chunchun.c         | Bianliang City Dachun Guesthouse.\n \nNote my HOME is not here.\n*sweat should be very complete. If there are copyright issues, grin please note when reposting.\n                        \n                        Reposted from (Xfile) @byxyj \n                        2002.2.1', 2, 1012559866, NULL, 11, 0, 0, '2026-06-28 18:11:30');
INSERT INTO `posts` VALUES (9, 'menpai_bbs', 'introduction', '蚂蚱', NULL, '方寸山人物简介：\n１．斜月三星 菩提祖师(Puti)■\n\n２．方寸山三星洞第二代首徒 广筠子(Guang yunzi)■\n　　经阁值日 广羲子(Guang xizi)\n\n３．方寸山三星洞第三代弟子 云清(Yun qing)■\n　　方寸山三星洞第三代弟子 云静(Yun jing)■\n\n４．方寸山三星洞第四代弟子 慧琉(Huiliu)\n    方寸山三星洞第四代弟子 慧纲(Huigang)\n\n５．皤不分(Bo bufen)\n　　山门迎客 晨月(Chenyue)\n　　小厨子 晚风(Wanfeng)\n　　扫地小童(Xiaotong)\n　　道士(Daoshi)若干\n　　小道士(Xiao dao)若干\n\n■：表示收徒．\n\n', 1, 1778892406, 0, 3, 0, 0, '2026-06-28 18:03:43');
INSERT INTO `posts` VALUES (10, 'menpai_bbs', 'jingge', '蚂蚱', NULL, '后院有藏经楼，也有几本书借，内部参考，恕不对外．\n藏经楼的书是公共财产，不要搞丢了！后果自负！\n\n', 2, 1778892406, 0, 1, 0, 0, '2026-05-19 03:05:28');
INSERT INTO `posts` VALUES (11, 'query_bbs', 'New commands', '未名', NULL, '设置区块告知功能可屏蔽除巫师外所有玩家向你发送的私信。\n\n备份可以备份您的文件，请参阅帮助文档了解备份详情。\n\n\n工具', 3, 1778892406, 0, 2, 0, 0, '2026-06-28 18:11:31');
INSERT INTO `posts` VALUES (12, 'query_bbs', 'set brief_message', '格格巫', NULL, 'You can: set brief_message\nThis will show fewer fighting messages, which is useful if you want to reduce\nthe messages show on your screen or when the net is slow.\n', 4, 1778892406, 0, 5, 0, 0, '2026-06-28 18:11:31');
INSERT INTO `posts` VALUES (13, 'nancheng_b', '● 扶乩', '明空', NULL, '说明：本文和以下各文为胡海牙前辈所作。\n\n        出于好奇探\"扶乩\"\n   我学习研究道家道教的学问有70余年了,同时涉猎道门中种种法术。道门中\n向有＂三千六百旁门，八万四千左道＂之说，今天让我以过来人身份向大家＂现身\n说法＂，先来说一说至今仍被许多人崇尚为神明显灵的扶乩。扶乩这玩意儿不知\n现在一些人看到过没有，这是一种迷信活动，说明白些是＂请神降谕＂，乩是一个\n沙盘，上面吊着一只笔，以Ｙ形杠棒吊着，两个扶乩手一左一右在盘边用杠棒左右\n扶住这支笔。当＂神光＂降临时，笔自己会动，乩手顺应着笔的动向，沙盘上就会\n现出字迹。旁边有人抄录，这便是神灵给求乩者的答复。当然，实际上笔绝对不会\n自己动，秘密全在左右扶乩手手里，是他们暗中推着杠棒使笔移动的。不用说，这\n要经长期训练，叫外人一点也看不出来才行。\n　　我小时对扶乩感到很神奇，老想弄懂它。有一天在某乩坛内寻到了一本书，是\n专门讲扶乩的，便如获至宝读起来。那书是个手抄本，书作者是这个坛以前得乩手，\n他除了讲这坛的历史外，就是讲扶乩的方法。那本书最后还写了一句话：扶乩很\n容易学，点、划和撇、捺，两手要能倒写字，都得学会它。这本书，我认认真真地\n琢磨了两遍，终于看出了学习扶乩的秘密方法：原来扶乩一点也不神，＂神＂的是\n人－－－扶乩手！我看了书后，就点划撇捺地在沙盘上乱写一气，而且两手轮流\n操作。乩盘有小有大，我上来就用大盘，我这时悟出了要两手都学会的道理，是要\n在自己位置变换的时候，能支配另一个人，当然，你必须要有手劲，又能两手操作，\n这样不管你在乩盘左边还是右边，另一个乩手都能被你指挥了。\n\n--\n※ 来源:·BBS 水木清华站 bbs.net.tsinghua.edu.cn·\n说明：本文和以下各文为胡海牙前辈所作\n\n        无师自通成乩手\n　　不久，日本鬼子打到金华，我则从山前翻到了山后，逃到了蒲江清水塘陈云龙\n家，他是中医，我１６岁也学过中医，为了解决生计，就合伙操起了医道。\n　　年轻医生尚无名望，如何能够招徕患者呢？我突然想到，我已经学会扶乩了，\n就先用它来＂蒙＂一下吧！这样，来了病人，先扶乩假装是神仙开药方，因为疗效\n不错，人们都以为我是神仙的代言人。我这个诊所，借此越做越兴旺。\n　　我这个学乩者借医道而声誉日隆，引起一些老乩手侧目而视，结果一次我受到\n严重考验：某一天，他们为求雨，设了一个罗天大醮，请了许多和尚道士诵经拜忏，\n事先写好了求神仙指教答复的问题，这叫做禀单，然后突然找到陈云龙家，让我们\n两人立刻前去扶乩。到了坛里，才告诉我们，他们不但写好了禀单，还把它烧掉了。\n就是说，我们对于他们摆坛求神的目的完全不知道，这一下子我可犯蒙了。显然，\n人家在故意试验我们，看我是真是假。我怎么办？我先借口他们的乩盘太小，必须\n派人去拿我们自己的乩盘，这样拖延时间，可以探听信息并琢磨对策。他们显然早\n已想到这些了，虽然同意去取乩盘，但对我防范甚严，我一点消息都没有探听出来。\n待乩盘取来，我俩已在乩盘边一左一右的立好了位置，对策还没有想出来，我就慢慢\n地操纵陈云龙在盘上依次写下４个字：＂焚禀已悉＂。这时，我身上有点冒汗了。\n＂焚禀已悉＂，一批出来，表明神仙已经降临，下面神仙该说什么呢？急中生智，\n记得我看过陈樱宁老师办的〈〈扬善半月刊〉〉中有几句诗，其中四句大概是：＂有\n谁剪纸为招魂，种瓜得瓜等句读。避秦难觅桃源洞，焉得沿溪去问津？＂我只好把\n它写出来搪塞（我知道这些乩师水平不高，根本不会看这杂志）。没想到当即轰动，\n摆坛的人都服了。原来他们求神摆坛，一问祈雨年成如何？二问日本人来了，我们\n最终避到哪里去？三问启建此道场有无功德？还有一问我记不清了。而这几句模棱\n两可的诗正好答复了他们。结果歪打正着，他们都以为我真有神法，未卜先知，使\n他们对我极为折服。\n\n--\n※ 来源:·BBS 水木清华站 bbs.net.tsinghua.edu.cn·\n\n        巧做手脚骗信徒\n　　没多久，离我诊所２０里外的香山寺范住持请我来了，要我去他那里扶乩，弄\n一笔钱把香山寺修好。我就离开陈云龙住进寺内。我在寺里扶乩，放开手脚去做，\n发展了几个联手，都很成功。而且我们还有意搞点＂玄妙＂：在固定写禀单的位置\n上面设了一个二层阁楼，楼板上凿了一个小洞，每个求乩的人写了禀单，我的联手\n都能趴在楼板上透过那个小孔洞，把求神的内容看个一清二楚。我就能根据自己\n医道＂仙道＂方面的知识本领，根据自己的智慧，有的放矢答复求乩者了。这当然\n还远远不够，要扶得使人信服膜拜，还要有非常活络的心眼，有贼一般的眼神和\n机敏。比如有一天，寺里住进来一位前来避暑的绅士，我立刻瞄准了他那大堆行李\n中的一个灯笼，那灯笼的半边写了一个小小的＂钱＂字，另半边写了同样大小的３\n个字＂元息子＂。我趁他们不注意，先把那灯笼拿出来毁掉。过几天，他来求乩了，\n我就把自己早已准备好的４句偈语批写在乩盘上，这４句是：＂元元心地，息息归根，\n子道行孝，钱多奚用。＂这４句每一句的头一个字合起来，就是他的姓和号。他看了，\n目瞪口呆，大为折服。\n　　我进寺不久，碰到了两个逃难到此的人，一个叫子文，是个魔术师，一个姓唐：是\n个写小说耍笔杆的。我们就组成了新的联手：姓唐的会出点子，子文能变戏法，这一下，\n我们的扶乩越做越神，花样也越多了。比如，可以用水喷到空白黄表纸上，纸上会出现\n符文，让老百姓看得傻了眼。不过也有一次碰到个不信邪的，要自己拿纸一试。我一笑，\n就让他写好禀单用扶乩告诉他：＂过半个月来。＂半个月，我们有充份的时间做准备。\n先是贿赂好了附近仅有的两家纸店，那人来买纸时，店里卖给他的是我们已事先做好了\n手脚的黄表纸，这手脚说来很简单，就是用白矾或其它药水在纸上写符，晾乾后毫无\n痕迹，一着水，符文就会显形。半个月后，那人来了。他拿着檀香和纸，一直不撒手，\n唯恐让我们钻了空子。直到假善财出场喊：＂拿纸来＂时，他才将纸递上去，眼睛还\n一直死盯着，等到善财一口水喷出来，纸上的符文显形，那人可就脸黄了，真的害怕\n了。其实这都是我们做的手脚，如果他半个月前立马去买纸叫我们试，我们会当场\n＂出彩＂的。\n\n--\n※ 来源:·BBS 水木清华站 bbs.net.tsinghua.edu.cn·\n\n\n', 5, 1778892406, 0, 1, 0, 0, '2026-05-19 01:58:31');
INSERT INTO `posts` VALUES (14, 'nancheng_b', '转载 <<昆仑记>>（１）', '明空', NULL, '原发信站：中国科大BBS站\n\n    一日灵霄殿早朝散罢,玉帝独留下公子云,屏去左右,说道:\"云爱卿近来既是无\n事,替朕走一趟昆仑山如何?\"\n    公子云吓了一跳,忙说:\"陛下,臣闻\'清官难断家务事\',何况古往今来,凡是介\n入宫庭隐事的外臣,通通的没有好下场......\"\n    玉帝道:\"嗨,什么话.咱们俩名为君臣,情同骨肉,我的底细你又不是不清楚.我\n能当上这玉皇大帝,我那老丈人是个关键,不象那西天的佛祖,是以力服人,打得一\n群罗汉服服帖帖,这位置坐得才稳;我自从当上玉皇大帝后,致力于以德服人,所幸\n咱们这里是礼仪之邦,这么多年来靠着坑蒙拐骗,除了那野蛮人孙悟空,倒也把这玉\n皇大帝做得有声有色,象模像样.\"\n    公子道:\"原来如此,我说陛下怎么就这么热衷于管下界的闲事,虽然说由于不太\n了解情况,经过您手的十之八九都成了冤错假案,但没有功劳也有苦劳呀,天上众臣\n对您的勤勉都非常佩服.虽然造成了那么一点损失,搞得下面颇有点怨气,但那些凡\n夫俗子成得了什么气候?牺牲一点下界的名声,换来了上面的赞美,陛下果然英明.\"\n    玉帝道:\"这下界的名声可也不是像你说的那样微不足道,所以朕就派出无数巡\n风夜叉,只要听到谁敢对朕不敬,立马按情节轻重定罪处罚.实在不行,朕就迁罪于那\n些小妖小怪,薨他几个平平民愤.加上下界一帮文人合作,现在可好了,朕在那里的声\n誉至高无上,他们总是用\'青天\'来称呼朕.一有什么委曲,就喊\'天哪\',可是朕除了有\n空到下面去捞点名声外,也还有天上忙不完的事哪.比如现在一不小心把那个老太婆\n给得罪了,那帮无权无力的女权主义者协会整天抗议倒没什么,问题是一来落得个治\n家无方的名声,不免有亏朕的德名;更糟糕的吗,不用说你也知道,那老不死的丈人,\n总让我心惊肉跳.\"\n    公子心想,这还不容易吗,甭做这劳什子的玉皇大帝不就结了吗.这话可不敢说,\n只好正儿八经地道:\"陛下所见极是.既然如此,何不您亲自到昆仑山走一遭,一定夫\n妻感情更增一层.\"\n    玉帝道:\"你怎么不明白呢?这样一来,我的面子何在?尤其一些封建流毒中得比\n较深的大丈夫们岂不认为我丢了男子汉的脸,奇怪的是虽然我们一直致力于清扫封\n流毒,但事实上是,满脑子都是封建思想的人反而总是一个个位高权重,所以这帮人\n也是得罪不得的.我想来想去,还是你替我走一趟比较好.\"\n    公子道:\"陛下,既是如此,我们联合一帮大男子主义者们,发一封休书给那婆娘,\n索性与他们决一死战,也未必就输于他.\"\n    玉帝道:\"怪不得大家总说,别人是把封建流毒运用之妙,存乎一心,唯独你却傻\n乎乎地上那腐朽思想的当.以后我们为下界定的些道德规范,行为准则,你可要少看\n一点了.英雄不是那么好逞的,打仗总不是一件好事,你到我这个年龄就明白了.现在\n你下界走一趟的必要更大了,不去领教领教下界人们的世态炎凉,尔虞我诈,以后你\n是没有什么前途的了.\"\n    公子只好叹了口气,说:\"陛下深谋远虑,微臣不及,既有差遣,敢不效命?只是呆\n会儿我见到了王母娘娘,该跟她说什么呢?\"\n    玉帝道:\"什么呆会儿?你可不能噌地一把就飞过去,说了几句话就等不及地又呼\n啦一声回来了.你得跟当年唐僧一样,脚踏实地地从蓬莱走到昆仑.这样辛辛苦苦地\n走下来,足见我们的诚意了,说什么话都是次要的了.这是现在最流行的了,叫作\'重\n要的是过程,不在结果\'.我那老婆子,最庸俗不过了,是个赶时髦的好手.你只要这样\n踏踏实实地走过去,不用说什么废话,她早已感动得不知天高地厚,以为我也变得跟\n她一般有情趣,还不认我为知音,重归于好?\"\n    公子只听得目瞪口呆,心想:不愧是多年的玉帝了,甭管他那道理对不对,这分析\n能力和嘴皮子的功夫着实了得.呆了半晌,说道:\"臣谨遵旨.只是刚才陛下说我坏主\n意还不够,臣也深恐下界去着了人的道,还请陛下再拨几人来助我才好.\"\n    玉帝道:\"这个容易,就叫赵钱孙李四大将与你同去如何?\"\n    公子沉吟片刻,道:\"启禀陛下,这钱家近来不太兴旺,我听说张姓人丁众多,还请\n陛下改拨一个姓张的.\"\n    玉帝道:\"咦,你怎么还这样顽固不化?居然要人才不要钱?那人才是不顶用的,而\n且不好管.只有钱才是真家伙.\"\n    公子道:\"陛下容禀,臣想那钱虽是好东西,但带在身上一来不便,二来有限,不如\n带个财神爷赵公明,要多少就有多少,而且是个瞎子,也容易整治.陛下尽管放心,既\n奉差遣,臣定不再死守道德,一定会灵活行事的.\"\n    玉帝道:\"那就好,我所以差你去,一来你我交情不同他人,二来也是你为人聪明,\n虽然读书稍多了一点,但相信下去之后,很快就能学乖的.现在我们神仙下凡,是不准\n滥用法术的,除非遇到会妖法的人,都得各凭真实功夫行走,你挑其他的人可要注意.\"\n    公子道:\"多谢陛下提醒,我就点那赵公明作管账的,张无忌专事单挑,孙悟空对\n付幺魔鬼怪,李元霸用来攻城夺寨.\"\n    玉帝道:\"甚好.只是那张无忌并非真有其人,不如换他的太师父张三丰吧?\"\n    公子点头同意.玉帝便传下旨来,唤那四人到南天门集合.\n\n---\n还是单身好呐 :-)\n\n\n', 6, 1778892406, 0, 1, 0, 0, '2026-05-19 01:58:25');
INSERT INTO `posts` VALUES (15, 'nancheng_b', '窥视妖魔化中国的背后', '二郎神', NULL, '　　自《妖魔化中国的背后》（以下简称《妖》书）的几章发在《华夏文摘》上\n后，许多人指出文章逻辑的不严密，描写的情绪化，翻译的歪曲化，论点没有统\n计学数据的支持等等，《妖》书被当成学术论著来批。\n\n　　我以理科学生的眼光粗粗的读了一下那几章和大家的评论，发现我并不认为\n《妖》书是学术论著，只能算杂谈，畅销书嘛，有人爱读有人爱买就行。科学论\n著和杂谈的最起码的区别在于语言的运用。科学论文是要客观的描写任何一种现\n象，而且任何一个论点和结论都要有客观的事实或科学的统计来支持。杂谈则不\n用这些，它可以是一种情绪的发泄，可以主观的描写人或事，也可以片面陈述单\n方面的意见。象《妖》书中对人物长像的描写是绝对不会出现在学术论文中的。\n也有人说这叫“抒情政论文”，算我见识短，死活不能欣赏政论文里的抒情。\n我认为这书之所以惹得许多人出来抓住它的小尾巴咬个没完，主要是名起的太惊\n人，要是叫《美国眼中的中国－－背景介绍》，再去掉那些抒情的句子，不但更合书\n的内容，也看起来客观科学，少了许多人来咬小尾巴。不过这样一来可能就不那\n样惹眼，也可能不那么畅销了。\n\n　　既然是萝卜，我看就不该拿着萝卜当白菜来批，那些夸张的描写也就只能当\n成作者的风趣，而不能当成作者的论据来看。那么就剩下看看《妖》书的中心思\n想是不是迎和读者的口味了，看完《妖》书的几章，我还在问，到底妖魔化中国\n的背后是什么？为什么它能畅销？\n\n　　首先说说我所知道的美国人加拿大人对中国的印象，我想对于没有去过中国\n的人，这些印象多来源于祖上的教导或传媒。记得我老板从北京开会回来，组里\n的人问她对中国的印象。她住的北京奥运村里样样都很先进，在加拿大也算高级\n的地方，她说北京非常摩登，街上的摩登女郎的衣着打扮和发形很令人瞠目，其\n它人的衣着也和加拿大人没啥两样，她很吃惊。别人开玩笑说，你去的是中国吗\n！她赶紧补一句，噢，也见农民进城卖东西的，他们和我想象的差不多，沉默辛\n苦耐劳的样子。\n\n　　老板从此特别爱看有关中国的书，一天她郑重其事地给我看一本叫《Ｗｉｌ\nｄ　Ｓｗａｎ》的当时的一本畅销书，要我看完了告诉她书里写的是不是真的。\n这本书是一高干子女写的她们家的家史和她个人的经历，因她父亲曾是四川省二\n把手，她又亲身参加了文革，所以她们家的家史里尽是党内斗争和她自己在文革\n中如何受苦什么的。老板说她感触最深的是书中说作者的妈妈不让孩子剩饭时说\n，西方世界的孩子连饭都吃不上，你把饭粒剩在碗里是可耻的。老板说她小时候\n也是这样被教的，学校里还有过五分钱买一张中国小孩照片的活动，说是帮助中\n国小孩不挨饿。他们还可以给照片上的中国小孩随便起自己喜欢的名字。老板还\n非常严肃的说一个天主教会学校居然教给学生中国小孩只值五分钱，她还把这作\n啥出入，语句也是汉语式的，看的英文字脑里跳出来的是中文。但作者的经历使\n她对中国有种怨恨的情绪，要是我有那样的经历我可能也会那样。但我们这代人\n没吃着那些苦，所以对党对国没啥特别的情绪。\n\n　　美国在我们中国人的印象中是什么样的呢？我也记得很小时候以为资本主义\n社会的孩子生活在水深火热之中，他们要到工厂做工，挨打还吃不饱饭，我们能\n坐在窗明几静的教室里该多幸福呀！后来改革开放了，去国外看过的人说美国不\n但生活好，美国人也特好心的关心世界人民的疾苦。又记得八九年学运时一在美\n国留学的老兄不远万里赶回北京支持学运，老兄的话我别的没记住就记一句：“\n中国是还有优点的地狱，美国是还有缺点的天堂。”我从此便随着潮流一心想上\n天堂看看。听说北大的学生宿舍里有人的书桌上左边是一落托福指南，右边是一\n落ＧＲＥ复习指导，中间墙上一张美国大地图，不知真假。总之，那时年轻人想\n往西方世界是很十髦很伟大很骄傲的一件事。\n\n　　天堂没去成，我来到了天堂的邻居加拿大。来了不久，和蔼的房东在和我聊\n天的时候说，他见到的第一个中国人是他小时候隔壁一家开洗衣房的中国人，他\n那时常对着那家的小孩唱：“ｃｈｉｎｋｙ　ｃｈｉｎｋｙ　ｃｈｉｎａｍａｎ\n，ｓｉｔ　ｏｎ　ｔｈｅ　ｆｅｎｃｅ，　ｃｏｕｎｔ　ｈｉｓ　ｐｅｎｎｉｅ\nｓ．”我才知道华人孩子在这里象我们小时候常欺负的朝鲜族孩子一样受气。其\n实华人不光有挨欺负的形象，华人还有欺负别人的形象。一次，一个黑人同学半\nｈｉｎａｔｏｗｎ，华人黑帮会专门抓半大黑人小子帮他们贩毒。还有我家隔壁\n的一个长的挺好玩的小女孩，我特喜欢她的小样，所以看她在外边玩耍常逗\n她玩，突然有一天她脱口而出：“我不喜欢中国人。”四五岁的小孩子知道不喜\n欢中国人？我不得不想是她家里大人这样说了，她学了来的。过了一断时间又在\n报上看到加拿大对华人的隔离法在六十年代才被取消，加拿大的Ｃｈｉｎａｔｏ\nｗｎ也不是因为中国人爱生活在一堆而形成的，而是因为华人被明令规定不可以\n到别的地方住。陈冲主演的电影Ｇｏｌｄｅｎ　Ｇａｔｅ里也提到新中国刚成立\n时给大陆家里的老妈寄钱会被当成给共匪捐资而入狱。我对天堂的幻想一天天变\n成客观的认识，也明白了天堂到底是谁的天堂，天堂里的缺点到底是什么，有多\n大。\n\n　　美国媒体“大肆攻击、歪曲中国的不光彩行为”不是一年两年的事了，从我\n们高喊“打倒美帝国主义”的时候就有，到我们把美国拜为天堂的时候也有。不\n管中国是否曾经是妖魔，还是被妖魔化了，这不是个新现象，其实中国的形象在\n世界的眼里，由于中国的开放而一天天的趋于本来面目。当给中国人机会站在事\n实面前，中国人会得出他们自己的结论，美国在中国人的眼里也自然会越来越接\n近原形，政论文里的抒情，免不了让人理解成在为某一政治集团的利益煽情。西\n方世界对中国的认识过份强调苦难深重的一面和中国对西方世界的认识过于强调\n发达民主的一面一样都是偏见。不管是谁把谁看高还是谁把谁看低，妖魔化的中\n国背后是美国对中国的偏见也是中国对美国的偏见。所以我认为《妖》书所迎和\n的读者的情绪是一种失恋的情绪，象小男生小女生自做多情之后突然发现他们想\n象中的十全十美的偶象并没把他们当人看。当中国人能睁开眼平等的看世界，不\n是高人一等，也不是低人一等地看人的时候，这种情绪自然不会再有。\n\n', 7, 1778892406, 0, 1, 0, 0, '2026-05-19 01:57:55');
INSERT INTO `posts` VALUES (16, 'query_bbs', '我的 XYJ 经验谈', '不知道(Jian)', NULL, 'e\n下面是我的一些 XYJ play 经验，希望能对新手有一定的帮助作用。\n这些经验可能会有不同的意见，希望得到更有经验的 player 指正。\n\n在获得这些经验的过程中，感谢无可奈何、代表你、说话罗嗦、酸\n黄瓜等曾多次指导帮助过我的朋友，没有他们的真心帮助我现在恐\n怕还在 papaya 呢 :)\n\n\n一、重要的 Skills\n\n基本上在有了道行之后，就可以先后将基本内功(force)、特殊内功、\n基本法术(spells)、特殊法术学到自己认为可以的最高级别(如果愿意，\n可以学到师傅不能再教你为止)。\n\n找个时间，找个可以睡觉的地点, 买上三字经、千字文、女儿经，开始\n读书，当然最好此时你的内力和法力也比较高，可以提高读书的速度。\n一直把这三本术读完。\n因为读书 Skills 的高低，将会影响你今后读其他武功书的速度。还是\n先把底子打好再说。\n\n\n二、先买后卖的 skills\n\n有关 dodge、parry、unarmed、stick 等几个基本的功夫，只需学到30\n级左右即可，因为这些功夫在今后的作战中会自动增加，而且当你的\npower 达到一定程度时，你可能需要 abandon 这些基本功夫，以恢复\n或加快日益减慢的获得道行的速度。根据我的经验，只要选对 NPC, 这\n样做至少可以提高1倍速度。\n\n为什么要 abandon 这些看来很重要的功夫呢? 我想这恐怕和武侠小说中\n武功的最高境界相似。师傅教了你招式之后，不是要你记住它，而是要你\n把它“忘掉”，只有达到把学会的招式“忘掉”，才真正进入了很高的武\n功境界。\n\n西游记中的境界似乎是无止境的，主要体现在道行和skills的级别上，实\n际上我们只需保留基本和特殊的内功和法术，以及其他能学到的特殊功夫\n就行了，其他基本功夫都可以在实际当中不断在实战中获得。我认为这个\n过程中基本功夫实际上是辅助你成为一代高手的工具，它存在的意义并不\n是为了达到高级别后就放在那里的。\n\n当然，在有些时候，可能反而需要在学一点基本功夫再去和 NPC 打架，打\n到足够强时，再 abandon, 从头来，使速度不受影响。\n\n\n三、买卖中可学的 Skills\n\n当然，在你为了获得潜能和道行的实战中，向师傅不断学习的首先还是基\n本和特殊的内功和法术，学到一定程度后，我认为应该学习特殊武功或兵\n器。因为如果用 practice 的话需要单独耗费时间，而且此时对应特殊功\n夫和兵器 enable 的基本功夫 skills 很低，practice 的速度不会足够\n快。不过，这个说法还是请诸位高手和更有经验的 player 来评论一下吧。\n\n\n四、必须花时间的内力、法力修练\n\n既然已经开始玩 MUD, 那么你就应该准备足够的时间和money来耗在里面 :)\n同时也必须有足够的耐性。我想在长时间的 MUD Play 之后，是不是大家\n的耐性 skills 其实是长的最快的? :D\n耐性中最重要的是舍得花较长时间来修练你的内力和法力。\n\n足够高的内力是今后实战中加快获得道行的必要条件，这样你可以和比自\n己强的多的NPC对打，而且当可以和同样的4个或更多 NPC 对打时，道行\n增长速度就很快(我最快的记录是12d/m)，此时如果你的内力不够，影响气\n血的恢复速度，你就可能会被杀，或者经常被打逃跑反而影响获得道行的速\n度。\n\n足够高的法力在读书、practice时可取很大作用，因为法力可以转变为内\n力，内力又可以转变为精神，加快了读书和练习的速度。\n至于法力在战斗中的使用我没有用过(说实在的，有点不敢用，因为法力一\n旦施出, 自己一段时间内就没有了防护能力，也不能逃跑。只能实实在在\n挨打，实在担心自己的气血够不够 :< )\n\n\n五、20年以后的道行\n\n根据我自己的经验，选对 NPC 是一件最重要的事情，但是对一个新手而言，\n这又是一件摸不着头的事情。当我在17ags的时候，大约才有7年的道行，这\n就是整天只围着 gao/gaopo 转的结果。 :(\n\n20年以前的道行可以参考中文的新手指南，20年-300年我整理了以下的NPC\n\n20年  - 40 年    打衙役\n40年  - 70 年    打天兵\n70年  - 100 年   打守城武将、边关武将、秦琼家将\n100年 - 130 年   打龙宫夜叉、龙婆、龟军师、鲸无敌、金甲卫士\n130年 - 300 年   打百年芭蕉怪, 天丁\n\n需要记住，在打的过程中需要参考前面关于获得道行的技巧。\n\n\n六、最后的重要发现\n\n这个发现就是网络速度可能影响的获得道行的速度! 这是我经过一个通宵的\n鏖战之后发现的，因为我的联网速度一般总是很慢，夜里可能快起来，对比\n之下，觉得是这样。我分析可能服务器要把显示信息传过来的快慢自然也影\n响了在服务器中执行的打架程序的速度。\n\n因此还是建议国内玩家玩 MUD 时选用一只跑的快猫，选择一个出口快的ISP.\n\n', 8, 1778892406, 0, 1, 0, 0, '2026-06-28 18:11:32');
INSERT INTO `posts` VALUES (17, 'nancheng_b', '有完？没完啊！:-)', '花花公子(Playboy)', NULL, ' Re:有完没完啊 咪咪(Mimi) ---\n     ‘说什么完不完的，咱这辈子才不想和你有完有了的,ha...’;)\n----------------------------------------------------------------------\n 前略....\n\nMIMI:一个小游戏也这么多ｐｏｌｉｔｉｃｓ，大家不是要逃脱现实么？\n   对呀，我都说了太认真不行的嘛，我以为MUD是扮演一个角色，玩得好并不一定是\n   你的功夫高，而是大家都认同你扮演的这个角色，如果只是做回自己那还有什么\n   意思？:)\n   象灵儿，调皮爱闹、惹人爱怜，可惜红颜薄命...:~)\n   象小少我，风流盖世，独领风骚，一代天骄，当然看家本领是：\n             说不赢就逃，打不过就跑...;)\n   象DIABLO老好人一个，没脾气，没义气，没口气...$#^(*%#@^$(&*\n     （...什么乱七八糟的,不过只要我及我周围的人都快乐我开心了...)\n\nMIMI:你叹道：世上哪有一片无争无斗的净土呢？\n   来吧，到这里来，小少哥哥的怀抱永远向你敞开，我的胸膛是你永远的避风港。:-)\n\n       PS：什么时候嫁给我？从十四岁开始追你到现在二十六岁已十二个年头了，不\n   敢说青梅竹马至少也算是风吹雨打吧！不过，也许你喜欢听我的甜言蜜语不想太快\n   投降，哪是否准备还要让我再追你个十年八载？:)\n       太久没见你了,真是想你,忍不住给你写了这封信.不敢妄想你收到信后意乱神迷,\n   不过可以想见你轻嗔薄怒的俏模样儿.小少我在此正式宣言，誓要夺得咪咪小姐的芳\n   心。小咪你如有意，不如让我们来玩一场游戏，看看究竟是你能迷得我神魂颠倒呢，\n   还是我使你意乱神迷。:)\n       没有你的日子里我会更加珍惜自己,没有我的日子里你要想着我,念着我,不可以\n   忘记我。\n                                                            小少\n\n...喝一杯小酒，谈一场恋爱。不然人生是多么无趣的一回事....\n', 9, 1778892406, 0, 1, 0, 0, '2026-05-19 01:57:17');
INSERT INTO `posts` VALUES (18, 'nancheng_b', '千面怪', '格格巫(Mon)', NULL, '据传近来有千面怪出没，此怪善于变化，又好行窃。\n不过它也是练功(fight)的好对手，当你用fight时，它\n也会用与你相当的武功和你较量。\n', 10, 1778892406, 0, 1, 0, 0, '2026-05-19 01:57:09');
INSERT INTO `posts` VALUES (19, 'nancheng_b', '打劫', '花花公子(Playboy)', NULL, '打劫：\n    一名墨西哥匪徒抢劫了得州的一所银行.几天后,被一名Ｍ国阿SIR在闹市区抓住.\n这警察不会讲西班牙语,而劫匪也不会讲英语.于是一个过路的墨西哥人被请来当翻译.\n    阿SIR把\"喷子\"顶在劫匪的头上,对翻译说:\"问他是不是叫冈萨雷斯?\"\n    翻译回答说:\"他说,是,他是冈萨雷斯.\"\n    \"问他是不是抢劫了的州第一国家银行?\"\n    翻译回答:\"他说是,他承认他曾抢过这家银行.\"\n    警察把\"喷子\"顶的更紧了,道:\"现在告诉他,如果他不说出来钱藏在哪儿,俺的枪\n就要走火了.\"\n    匪徒不住地流着汗,用西班牙语结结巴巴的话:\"别....别开枪,俺招,俺全招,俺家\n还有俺的内当家和四个小讨债鬼,钱就在俺家后院的那口枯井里头.\"\n    翻译回头对警察说:\"他说你是个混蛋,白痴,二百五,你不敢!来吧,开枪吧.\"\n\n                                                 :) 开心小少 ;)\n...笑一笑,十年少.\n', 11, 1778892406, 0, 1, 0, 0, '2026-05-19 01:57:02');
INSERT INTO `posts` VALUES (20, 'nancheng_b', '笑话二则', '花花公子(Playboy)', NULL, '---------------------------------------------------------------------------------------------------\n    JOKEY是一大近视眼，在河边漫游时，看见河中央竖立一块牌子，可惜中间\n的字看不清。好奇的他，只好脱下鞋子，涉水到河中一探究竟，只见牌子上写著：\n请勿喂食鳄鱼。 :D\n---------------------------------------------------------------------------------------------------\n     一个西班牙人看到朋友穿了一双鳄鱼皮鞋,大为羡慕。一问之下,价钱昂贵非凡,\n他便决定自己去猎杀一只鳄鱼。\n\n     他找到一个沼泽,跳下水去和一一只鳄鱼恶斗许久,好不容易才把鳄鱼拖上岸,却\n大叹一口气道:「 浪费了那麽多时间,这只鳄鱼竟然没穿鞋。」;)\n\n                                                 :) 开心小少 ;)\n\n', 12, 1778892406, 0, 1, 0, 0, '2026-05-19 01:56:55');
INSERT INTO `posts` VALUES (21, 'nancheng_b', '结婚', '花花公子(Playboy)', NULL, '      打算讨老婆的男人，应有如下的觉悟：权利将减半，义务将倍增。:D\n 你觉悟了吗?;)看看下面再说吧!\n\n  关于 三从四德:\n\n                     1.太太命令要服从\n                     2.太太外出要跟从\n                     3.太太说错要盲从\n                     a.太太买东西要舍得\n                     b.太太生日要记得\n                     c.太太发威要忍得\n                     d.太太出门要等得\n\n                                                :) 开心小少 ;)\n...婚姻，是一个男人以最贵的方法洗衣服。\n\n\n', 13, 1778892406, 0, 1, 0, 0, '2026-05-19 01:56:45');
INSERT INTO `posts` VALUES (22, 'nancheng_b', '3.3.4.5.5.4.3.2', '花花公子(Playboy)', NULL, ' 不知小咪喜欢MUSIC吗?让我们听一下刘德华的歌吧.\n=============================================================================\n<<十年>>前\n我<<最爱上海滩>>\n<<我和我追逐的梦>>\n曾在<<昨夜的渡轮上>><<缠绵>>\n<<一起走过的日子>>\n我们<<爱不完>>\n<<愿牵你的手>>\n<<相约到永久>>\n一起<<心声共鸣>>\n直到<<真永远>>\n我为<<爱人皇后>><<神魂颠倒>>\n不敢<<独自去偷欢>>\n\n<<今天>>\n<<小情人>>变成<<旧情人>>\n<<半生爱的女人>>只能是<<来生缘>>\n一切都是<<天意>>\n<<决不放弃>>的誓言\n只能在<<梦中见>>\n\n<<关心>>\n<<多情>>\n<<缠绵>>\n<<缘尽>>\n<<寂寞>>\n<<推不开>>\n<<真情难收>>如<<潮水>>\n在<<每一次醒来>>\n\n一度<<心如止水>>\n一再<<相思成灾>>\n是再闯入你<<情感的禁区>>\n还是该<<谢谢你的爱>>\n临别时多想饮一杯<<忘情水>>\n独对<<夜茫茫>>\n我却流下<<男人的眼泪>>\n那是不是<<真我的风采>>\n\n<<爱是如此神奇>>\n我却<<有心无力>>\n知不知我<<真的爱着你>>\n<<没有人可以象你>>\n在我的生命里\n<<不能没有你>>\n<<我是铁了心的爱你>>\n<<如果天有情>>\n    <<可不可以>>\n        再次<<拥抱你>>\n<<另一半>>\n<<除非......是你>>!!!!!\n                                                花花小少\n...嘿，小咪别那么大眼睛瞪着我，我会脸红的。@(@\n....爱上了爱你的感觉，但我不是爱上了你，只是爱上了这种感觉。\n', 14, 1778892406, 0, 2, 0, 0, '2026-05-19 01:56:19');
INSERT INTO `posts` VALUES (23, 'nancheng_b', '昆明大观楼天下第一长联', '不知道(Jian)', NULL, '五百里滇池，奔来眼底。披襟岸帻，喜茫茫空阔无边。看：东骧神骏，西翥灵仪，\n北走蜿蜒，南翔缟素；高人韵士，何妨选胜登临。趁蟹屿螺洲，梳裹就风鬟雾鬓。\n更苹天苇地，点缀些翠羽丹霞；莫辜负：四周香稻，万顷晴沙，九夏芙蓉，三春\n杨柳。\n\n数千年往事，注到心头。把酒凌虚，叹滚滚英雄谁在。想：汉习楼船，唐标铁柱，\n宋挥玉斧，元跨革囊；伟烈丰功，费尽移山心力。尽珠帘画栋，卷不及暮雨朝云。\n便断碣残碑，都付与苍烟落照；只赢得：几杵疏钟，半江渔火，两行秋雁，一枕\n清霜。\n\n', 15, 1778892406, 0, 1, 0, 0, '2026-05-19 01:56:15');
INSERT INTO `posts` VALUES (24, 'nancheng_b', '也说对联', '无言独上西楼(Lou)', NULL, '乾隆皇微服江南，一晚错过宿头，忽见一村野人家，乃上前\n求宿。屋内止得一妇，夫与子外出未归。妇出一上联说，对上\n下联就让你投宿，对不上就请走路吧。上联是：\n    寂寞守寒窗，寡宿宁容寄客寓？\n\n乾隆说了，帮他对上此联，官封御林大学士。\n', 16, 1778892406, 0, 2, 0, 0, '2026-05-19 01:56:11');
INSERT INTO `posts` VALUES (25, 'nancheng_b', '都是杀人狂', '苗贲皇(Kuff)', NULL, '到这堆泥巴里也有几天了,每日只见各位神情木然,除了杀人不干别的,无可\n奈何只好抄录故人旧作一首,以发牢骚\n    刀客行\n五岁杀一人  十岁杀百人\n至于而立年  见人则举刃\n为人残暴殊  自谓悟其真\n杀尽天下人  不曾知有仁\n西风走马客  绝域胭脂痕\n从来河西路  执刀尽断魂\n相看皆狂夫  托命同飞尘\n杀人如蓬草  行路血纷纷\n仰天弃太玄  快意旧日恩\n五经成粪土  当作万恶人\n', 17, 1778892406, 0, 2, 0, 0, '2026-05-19 01:56:03');
INSERT INTO `posts` VALUES (26, 'nancheng_b', '云南十八怪', 'http://mail1.ntttc.edu.tw:80/~wltseng/eighteen.htm 呆头呆脑(None)', NULL, '云南十八怪\n\n云南第一怪，鸡蛋用草串著卖。\n云南第二怪，米饭饼子烧饵快(心旁应改为食)。\n云南第三怪，三只蚊子炒盘菜。\n云南第四怪，石头长到云天外。\n云南第五怪，摘下草帽当锅盖。\n云南第六怪，四季服装同穿戴。\n云南第七怪，种田能手多老太。\n云南第八怪，竹筒能做水烟袋。\n云南第九怪，袖珍小马有能耐。\n云南第十怪，蚱蜢能作下酒菜。\n云南第十一怪，常年都出好瓜菜。\n云南第十二怪，好烟见抽不见卖。\n云南第十三怪，茅草畅销海内外。\n云南第十四怪，火车没有汽车快。\n云南第十五怪，娃娃出门男人带。\n云南第十六怪，山洞能跟仙境赛。\n云南第十七怪，过桥米线人人爱。\n云南第十八怪，鲜花四季开不败\n', 18, 1778892406, 0, 1, 0, 0, '2026-05-19 01:55:56');
INSERT INTO `posts` VALUES (27, 'nancheng_b', '给珊瑚的情书 I', '苗贲皇', NULL, '珊瑚, my princess, my master, my lord:\n你真的不信我有多爱你吗?我现在每天没日没夜守在计算机前,\n只为了等你出现,常常看见你在网上时我就感到幸福,可你却总不肯\n相信我!没办法时我只好在网上胡说八道以减轻烦恼,但你\n知道这样有多痛苦吗?多少次闭上眼睛,仿佛能感觉到你的呼吸触及\n我的脸,睁开眼又只看见一个傻兮兮的屏幕,于是我只好当即晕倒,在\n屏幕上敲出一堆#$%^&*()_来!所以请你不要再让我这样惨的过下去,无\n论如何给我一个明确的答复!!\n                                苗贲皇草\n', 19, 1778892406, 0, 1, 0, 0, '2026-05-19 01:55:47');
INSERT INTO `posts` VALUES (28, 'nancheng_b', 'about death', '格格巫(Mon)', NULL, '除妖降魔，得道升仙是西游记永恒的主题。在这个过程中，玩家也很有\n可能会出师未捷，杀身成仁：（同现实生活一样，死亡会带来重大的损\n失，不过，玩家通常可以轮回复生，继续游戏。死亡主要有两种原因：\n一是被 NPC(非玩家角色)杀死或因其它自然因素如掉下悬崖而导致，玩\n家会损失部分道行，武功技能水平也可能受到影响；另一种是被其他玩\n家打死，这时没有武技损失，但是对方会因此而得到部分道行奖励，道\n行损失和奖励的多少取决于双方的道行差距，一位道行高深的老手去杀\n死初入道途的新人是毫无意义的。\n\n西游记中设计有很多特定的 NPC妖魔鬼怪，打死它们也可以使玩家得到\n道行奖励。\n\n另有一些玩家出于对佛法的不同理解，不愿杀生。他们向二郎神求得庇\n护(ask erlang about leave)，这样当被其他玩家杀死时，对方不会得\n到道行，而按照被NPC打死计算。同时他们也不能通过打死NPC妖魔鬼怪\n来得到道行。一个严格的限制是，一旦这些玩家杀死了其他玩家，那就\n会自动回复成普通玩家，不能再返回。\n', 20, 1778892406, 0, 1, 0, 0, '2026-05-19 01:55:37');
INSERT INTO `posts` VALUES (29, 'nancheng_b', '伤心人吟伤心词', '山水(Wen)', NULL, '贫道十余年前邂逅蝶舞，一见钟情，无奈造化弄人，苦盼十数载而难觅\n芳踪\n贫道惆怅满怀，一曲“卜算子”，以诉衷肠\n              卜算子---忆蝶舞\n滨水现洛神，绣房巧相逢，莺语传情最销魂，相思刻骨成!\n韶华流水逝，痴情万山凝，解佩竟是为别离，莫若不相识?\n\n*sigh wen\n', 21, 1778892406, 0, 1, 0, 0, '2026-05-19 01:55:32');
INSERT INTO `posts` VALUES (30, 'nancheng_b', '古龙', '花花公子(Playboy)', NULL, ' 人在江湖\n-------------------------------------------------------------------------------\n人在江湖\n（一）\n    看到那些曾经把快乐带给别人，自己也能想法子让自己快乐的女孩，\n就正如看到我的某一些朋友一样，总是会让我有乾一杯的冲动。\n    那些朋友中大多数也跟我一样，少小离家知半解之间，只凭著一时血\n气之勇，也不知做过了多少似对似非的事，只求得一个问心无愧，倒也无\n所怨尤。\n    这些人之中，有一些在壮年时就已故去了，有些固然是因为恩怨难了\n，行走於暗巷之中，溅血於五步之内，可是多数还是因酒而死。\n    这是因为他们多专逞一时之意气，做匹夫之狂态？还是因为他们胸中\n都有些解不开的结，要借他人之杯酒，来浇自己胸中的块磊？\n     不管怎样，我死去的朋友们，我但愿你们都能安息。\n（二）\n    「人在江湖，身不由己」，我相信自古以来，就有很多人有这种感触\n，只不过由我先把他从思想变为黑字，印在白纸上而已。\n    人在江湖，固然是身难由己，其实人不在江湖，又何尝能够由得自己\n呢？如果一时觉得气闷，就放歌纵酒，唯有令亲者痛，仇者快。\n    我也曾是酒徒，我也曾在生死间来去，我又何尝没有一些尖锥般的感\n触刺在心里？如今虽然自甘寂寞，远避山上，但却依然时常会有些身不由\n己的悲哀。\n         可是最近我已经懂了，人生本来就是这样子的。\n                                                     小少\n         \n', 22, 1778892406, 0, 1, 0, 0, '2026-05-19 01:55:29');
INSERT INTO `posts` VALUES (31, 'nancheng_b', '阿波罗13号', '花花公子(Playboy)', NULL, ' 阿波罗13号\n-------------------------------------------------------------------------------\n NASA\n\n  ... 「西雅图,我们有麻烦了...该死的Overclocked Pentium把Windows烧了...」\n\n TO:\n 「收到...这里是西雅图,请使用B系统补救,并且抛弃Windows.....」\n 「西雅图,我们仍然有麻烦,无法脱离...SHIT! 系统B这颗是RE的...」\n\n 西雅图控制中心的某间隔音室内，一群科学家匆匆走入，带头的那位手上抱了一\n□纸箱，顺手往桌上一倒，只见一堆胶带、电子零件、有的没有的散乱满桌。\n 「各位，我们现在的工作是，把这个486 CPU插到这个Pentium主机板上....」\n\nM$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$\n\n 汤姆汉克的视线通过一上一下的大拇指，拇指的後面不是月球，而是印在CPU上\n 的 Pentium字样，嘴里念念有词：「总有一天，我会到那儿去，该死的Intel!」\n\n M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$\n\n  AW:\n  「这里是西雅图中心,我是Bill Gates司令,我们的PC95 13最後倒数,\n  我再确认一次,Beta Tester, 你们确定可以发\"售\"了吗?」\n   (不行！)\n  「应用程式组?」\n   (...不行..)\n  「OS小组?」\n   (..门都没有)\n  「硬碟组?」\n   (免谈!)\n  「CPU 小组?」\n   (不可能)\n  「....呃...虽然大家都说不行,但是我还是宣布进入最後倒数...5,4,3,2,1」\n\n               .........然後是Win95的发售画面.........\n\n M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$\n\n TO:\n 随著Win95的发售带来的强烈震动，三名太空人都胆战心惊地望著\"Abort\"杆....\n  「还是不要犹豫、赶快拉下它吧！」\n  「这是明智的选择。」\n\n M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$ M$\n\n 【西雅图地面管制中心】\n  「现在状况如何？」\n  「很糟。由於使用M$的窗子，所以系统资源严重缺乏....」\n  「按照这种情况下去，他们绝对无法回到大气圈，系统资源一定会被耗光....」\n  「模拟试验进行的如何？」\n  「正在努力想办法中...」\n  「快叫设计小组提供所有设计图，无论如何也要压榨出更多的系统资源！」\n  「那比装OS/2还难....」\n\n 【飞行模拟室】\n  「该死！不管怎麽做总是无法低於临界值，就差5%!!」\n  「.....没办法，再试一次好了....」\n  「等等，在电路设计上，伺服舱的RAM和登月小艇的不是相通的吗？既然开窗子时\n    会降低系统资源，何不把窗子关上，让系统资源从登月小艇逆流回伺服舱上？」\n  「话是这麽说，可是从来都没有人试过.....」\n  「试试看再说！」\n\n  「启动著陆控制系统。」\n   (系统资源还剩70%)\n\n  「启动切离装置。」\n   (系统资源还剩60%)\n\n  「启动主电脑....」\n   (系统资源还剩5%)\n\n  「.....关窗！」\n   (系统资源还剩100%)\n\n  「成功了！成功了！！他们可以回来了！！」\n  「干得好！....但为何关窗後就没有系统资源的问题呢？」\n\n               於是自从那次之後，NASA都不用M$的窗子.....\n\n                                                 :) 开心小少 ;)\n', 23, 1778892406, 0, 1, 0, 0, '2026-05-19 01:55:24');
INSERT INTO `posts` VALUES (32, 'nancheng_b', 'win95 测试', '花花公子(Playboy)', NULL, ' WIN95测试\n-------------------------------------------------------------------------------\n  1. M$宣称连白痴都会使用WIN95,的意思是指?\n   A:使用简单,不用花大脑\n   B:辱骂一般的电脑使用者是白痴\n   C:只有白痴才会去使用WIN95\n   D:以上全对\n\n  2. WIN95是一套完美的32位元作业系统吗?\n   A:对的,倚天上是这样写的\n   B:对的,电视上是这样播的\n   C:对的,Ｍ＄它是这样说的\n   D:以上全错\n\n  3. WIN95只要8MB就可以使用?\n   A:对的,在玩踩地雷时相当的快速且稳定\n   B:错. 还要加上P-150的CPU才可以\n   C:请带着您的抱枕跟WIN95一起遨游\n\n  4. 对於WIN95测式版可以拿来卖钱的事,您的感觉是?\n   A:换个好听的名子,如抢鲜版之类的名称...应该可以吧...\n   B:广告的魔力真大..\n   C:叫白老鼠花钱买老鼠药\n\n  5. 对於WIN95 OFFICE将推出,您抱持的看法是?\n   A:我现在才知道.. 原来我的电脑在OLE2出现以前是有分派别的...\n   B:天生残障的东西,後天的努力只是挣扎\n   C:大概又可以卖个一万多块吧.. 真好赚.. 人家OS/2都是用送的...\n  注:OS/2送的IBM Works能看吗?:p\n\n  6. 世界首富比尔盖兹下一步打算如何?\n   A:救助衣索比亚难民\n   B:推出更新板来骗钱\n   C:先把钱数完在来捞下一票\n  注:我记得婴儿用品业正在密切注意 Bill Gates 的动向\n         因为他有小宝宝啦:)\n\n  7. WIN95喧称不用MPEG卡就可以看VEDIO CD是真的吗?0m\n   A:是真的..不过那张30/S的显示卡还没面市...\n   B:是真的..不过要用到P5-120+32MB RAM+4X CD-ROM...\n   C:是真的..只有一点点停格而以...\n\n  8. WIN95会让你电脑中那一样配件最闲?0m\n   A:1.44磁碟机\n   B:键盘\n   C:CPU\n   D:以上全对\n                                                 :) 开心小少 ;)\n\n', 24, 1778892406, 0, 2, 0, 0, '2026-05-19 02:52:03');
INSERT INTO `posts` VALUES (33, 'nancheng_b', 'bill geates', '花花公子(Playboy)', NULL, ' Bill Gates\n-------------------------------------------------------------------------------\n1\n    据说上帝不满人间丑恶，决定摧毁地球，正式实施之前，召集叶利钦，克林顿和\n盖茨通知此事。\n    叶利钦回到俄罗斯后发表讲话：“议员们，现在有一个坏消息和一个更坏的消息。\n坏消息是我们原来的无神论是错的，确实存在上帝；更坏的消息是三天后地球将玩完。”\n    克林顿回到美国后发表演说：“先生们、女士们，现在有一个好消息和一个坏消\n息。好消息是的确有且只有一个上帝；坏消息是三天后地球就会Game Over！”\n    盖茨回到微软总部召开紧急董事会：“先生们，现在有两个好消息。好消息是我\n是上帝所认定的三个最重要的人物之一；更好的消息是三天后IBM将被完全摧毁，停止\n销售OS/2。”\n\n2\n    Bill Gates死后来到天堂门口。\n    圣彼得：“好吧，你可以选择一下，去天堂，还是下地狱。先考察一下，然后告\n诉我结果。”\n    Bill看了看周围，人们表情严肃地唱着圣歌，赞美上帝(也许还用Ada)。他又来到\n地狱，只见阳光砂滩，美女如云，到处是C和Basic。酒不醉人人自醉！Bill说：“地\n狱，我喜欢!”\n    他回到圣彼得那里。\n    Gates：“瞧！你们这儿搞的挺好，但地狱里似乎更好一些。这个……”\n    圣彼得：“没问题，你去吧。”\n    Bill回到了地狱，在刀山火海和油锅中煎熬，受尽了折磨。实在受不住了，他大\n声呼叫：“圣彼得－－! 怎么这儿的美女琼浆都哪去了？”\n    圣彼得：“对不起, 你说的是DEMO版吧？”\n                                                 :) 开心小少 ;)\n\n', 25, 1778892406, 0, 1, 0, 0, '2026-05-19 01:54:41');
INSERT INTO `posts` VALUES (34, 'nancheng_b', '关于汽车', '花花公子(Playboy)', NULL, ' 价格\n-------------------------------------------------------------------------------\n   在某边境有一加油站,它的招牌上写道:\"注意!前面就是国境线,想要买\n45美分1升的汽油,这里是最后一个机会了!!\"\n   一个开车旅游的人交钱加了油,心想国境线那边的汽油不知会多少钱1升\n     ?????????????\n  不一会儿他就获得了答案:40美分1升!!\n\n 宣言\n-------------------------------------------------------------------------------\n    一辆耀武扬威的大卡车后面背着一个大木牌，上书：“本车与其他车辆\n相撞１７次，其中１５次大胜，１次平局，仅１次失利。请君撞我之前三思！”\n\n 含意\n-------------------------------------------------------------------------------\n    新买的车在路上抛了锚，夫妇二人头顶烈日推了两个钟头，大汗淋漓。\n    丈夫骂曰：“俺现在知道那个奸商说的话是什么意思了。”\n    妻子问：“他说什么？”\n    丈夫：“他说这车非常省油。”:D ;)\n \n                                                 :) 开心小少 ;)\n', 26, 1778892406, 0, 1, 0, 0, '2026-05-19 01:54:33');
INSERT INTO `posts` VALUES (35, 'nancheng_b', '关于恋爱', '花花公子(Playboy)', NULL, '   嗨,小咪:\n       今天看到了这么一句话:\n               \"恋爱不能太认真,太认真就没有资格恋爱了.\"\n   开始一笑置之.对\"资格\"这个字打了个问号.忽然想到了自己说过的一句话:\n       \"千万不要去分析感情,从来没有任何一段感情是经得起分析的.\"\n   仔细一想我的这句话和上面那句话实在是异曲同工.当然.\"资格\"二字不能\n   单从字面意思去理解.我想了很久,还是想不到有一个能更好地代替它的词.\n   久远的岁月,珍贵的感情,何必要太认真?如此生动的生命,如此多情的你我,\n   对爱,应该是义无反顾的.:)\n                                                花花小少\n... 不识情愁枉少年 檐下赐酒结仙缘 情难消受美人恩 仗剑江湖为红颜\n... 许久不再见你 以为可以 把你忘记 却不知道 在我心中 你从不曾稍离\n\n', 27, 1778892406, 0, 1, 0, 0, '2026-05-19 01:54:29');
INSERT INTO `posts` VALUES (36, 'nancheng_b', '小道童', '游手好闲(Windows)', NULL, '\n【闲聊】太白金星(Tai bai)：封神榜演礼：小道童与十二少于天乾殿争榜教量！\n\n小道童慢慢地移动着脚步，伺机出手。\n\n十二少跟在小道童背后，有如影子一般，锏锏不离小道童后心。\n这势「捉影锏」果然把小道童逼得手忙脚乱！\n结果造成极其严重的戳伤！\n 小道童受了几处伤，不过似乎并不碍事。 \n\n小道童使出「饿鬼拦路」，凌空跃起，冷不防在落地前对准十二少头部踢出一脚！\n你听到「喀啦」一声轻响，竟似是骨碎的声音！\n结果只听见「砰」地一声巨响，十二少像一捆稻草般飞了出去！\n 十二少已经一副头重脚轻的模样，正在勉力支撑着不倒下去。 \n\n十二少向后一纵，躬身做揖说道：阁下武艺不凡，果然高明！\n\n【闲聊】太白金星(Tai bai)：小道童天乾殿大战十二少，夺榜获胜！\n【闲聊】太白金星(Tai bai)：老夫诚奉御旨，封小道童为日曜星君！\n\n          ≡≡≡≡≡≡≡封神榜≡≡≡≡≡≡≡\n            日曜星君 小道童 kuer             \n            月曜星君 十二少 twelve           \n            金曜星君 文十五 beng             \n            木曜星君 韩柏 abai               \n            水曜星君 空空 nite               \n            火曜星君 魂断兰桥 miner          \n            土曜星君 东方英雄 hero           \n          ≡≡≡≡≡≡≡≡≡≡≡≡≡≡≡≡≡\n\n嘿嘿，小道童不鸣则已，一鸣惊人。。。解决十二少这样\n的高手居然只用了一招。\n\n', 28, 1778892406, 0, 1, 0, 0, '2026-05-19 01:54:19');
INSERT INTO `posts` VALUES (37, 'nancheng_b', '二人对诗', '苗贲皇', NULL, '无言独上西楼诗兴大发，摇着头晃着脑，“少年不识愁滋味，独上西楼，\n独上西楼，为赋无言上西楼　而今上了小西楼，无言西楼，\n无言西楼，却道无言好个楼。。。”\n\n苗贲皇(Kuff)：少年不识狗肉味, 骑上黑狗, 跨上黄狗, \n 为吃狗肉买条狗, 而今吃了黄狗肉, 白吃狗肉, \n白吃狗肉, 却道不如西楼肉\n', 29, 1778892406, 0, 1, 0, 0, '2026-05-19 01:54:10');
INSERT INTO `posts` VALUES (38, 'nancheng_b', '采葛', '杏话梅(Xine)', NULL, '彼采葛兮，一日不见，如三月兮！\n彼采萧兮，一日不见，如三秋兮！\n彼采艾兮，一日不见，如三岁兮！\n\n我走了，用脚步踩出一阵风，将曾有过的痛苦与欢乐，都散在风中，随风散去。\n', 30, 1778892406, 0, 1, 0, 0, '2026-05-19 01:54:05');
INSERT INTO `posts` VALUES (39, 'nancheng_b', '十二少血战西王母', '游手好闲(Windows)', NULL, '\n\n上回代表你说到小道童勇斗观世音，本章接着讲\n十二少血战西王母。\n\n去得晚了，前面的战况没有看到。据传西王母已经奄奄一息。\n\n十二少走了过来。\n\n十二少对着西王母喝道：「老妖婆！今日不是你死就是我活！」\n\n\n十二少战得兴起，索性挥起虎尾鞭向四面八方各打一锏。\n这招「无情锏」使开来，五尺之内，不论敌友，尽皆笼罩在劲风中！\n结果只听见「轰」地一声巨响，西王母被砸得血肉模糊，惨不忍睹！\n( 西王母伤重之下已经难以支撑，眼看就要倒在地上。 )\n\n西王母浅浅一笑，一招「自在飞花轻似梦」若有若无地拍向十二少的颈部！\n只见十二少脚步散乱，身形乱晃，却是一招「魂飞魄散」，\n西王母眼前顿时只剩一团鬼影，不知如何攻击！\n\n西王母口中念了几句咒文，随着一声“後羿在此！”半空中现出一位身披虎皮的大汉。\n只见他张弓搭箭，“嗖”的一声，一只蓝汪汪的长箭激射十二少！\n结果长箭从十二少身上透体而过，顿时血花飞溅！\n( 十二少已经陷入半昏迷状态，随时都可能摔倒晕去。 )\n十二少用一种异样的眼神扫视着在场的每一个人。\n\n十二少脚下一个不稳，跌在地上一动也不动了。\n\n\n西王母纤腰一摆，陡然滑出数尺，右手顺势一招「黄菊枝头生晓寒」\n往十二少的右臂拍去！\n结果只听见「砰」地一声巨响，十二少像一捆稻草般飞了出去！\n( 十二少已经陷入半昏迷状态，随时都可能摔倒晕去。 )\n\n十二少死了。\n\n【谣言】某人：十二少被西王母杀死了。\n【闲聊】桃话梅口吐白沫，昏倒在地上。\n\n唉。。。西王母濒死一击仍是雷霆万钧，怪只怪十二少命不好。\n\n', 31, 1778892406, 0, 1, 0, 0, '2026-05-19 01:53:17');
INSERT INTO `posts` VALUES (40, 'nancheng_b', '小道童的成绩单', '小道童(Kuer)', NULL, 'hp\n气血： 1228/ 1228 (100%)    内力： 2592 / 2592 (+135)\n精神： 1784/ 1784 (100%)    法力：  969 / 3050 (+153)\n食物： 249/  230           潜能： 51\n饮水： 189/  230           道行： 一千八百七十四年一百三十二天三时辰\n\nscore\n【道德天尊】方寸山三星洞第五代弟子 小道童(Kuer)\n你是一位四十八岁的男性人类，乙卯年四月十三日戌时四刻生。\n你有一千八百七十四年的道行。\n\n膂力：[148] 胆识：[ 30]  悟性：[ 40]  灵性：[ 40]\n定力：[ 77]  容貌：[ 15]  根骨：[ 40]  福缘：[ 14]\n\n你的师父是一个人。\n你目前是光棍儿一条。\n\n<气> ■■■■■■■■■■■■■■■■■■■■■■■■■\n<神> ■■■■■■■■■■■■■■■■■■■■■■■■■\n\n战斗攻击力 146320 (+0)         战斗防御力 163235 (+1)\n\n食物：■■■■■■■■■■■■■■■■■■■■■■■■■\n饮水：■■■■■■■■■■■■■■■■■■■■□□□□□\n\n你到目前为止总共杀了 452 个人，其中有 4 个是其他玩家。\n\n道行增加： 0            道行减少： 0\n\n杀 气： 0\n潜 能： 51 (99%)\n\n\nskills\n□道家仙法 (dao)                           - 一代宗师 179/  621\n基本轻功 (dodge)                         - 登峰造极 150/ 6945\n内功心法 (force)                         - 深不可测 202/    0\n□筋斗云 (jindouyun)                       - 深不可测 264/ 7440\n□惊魂掌 (jinghun-zhang)                   - 深不可测 267/    0\n读书识字 (literate)                      - 深不可测 120/    0\n拆招卸力之法 (parry)                     - 马马虎虎  50/    0\n□千钧棒法 (qianjun-bang)                  - 深不可测 203/    0\n法术 (spells)                            - 出神入化 139/ 1584\n基本棍法 (stick)                         - 豁然贯通 141/    0\n□摄气诀 (tonsillit)                       - 心领神会 118/ 5642\n扑击格斗之技 (unarmed)                   - 豁然贯通 140/    0\n小无相功 (wuxiangforce)                  - 举世无双 169/  199\n\n由于巫师们在法术上的一些临时改动,使到我在不到两秒内命丧菩提之手。。。\n哎，也该休息一下了。。。。有机会再战江湖。。。。3000年经验，300技能等级？嘿嘿.\n', 32, 1778892406, 0, 1, 0, 0, '2026-05-19 01:53:00');
INSERT INTO `posts` VALUES (41, 'nancheng_b', '报仇', '小道童(Kuer)', NULL, '要是最近法术系统的改动是为了保护master的话，那就白费功夫了。\n我用cast/escape,非常轻易就报了仇。。。。嘿嘿。\n你从菩提祖师的尸体身上搜出一把菩提杖。\n你从菩提祖师的尸体身上除下一双踏云靴。\n你从菩提祖师的尸体身上除下一件皂罗袍。\n\nBTW, the following is my enabled skills level, forgot to put it in the previous post\n以下是你目前使用中的特殊技能。\n内功 (force)        ： 小无相功              有效等级：270\n招架 (parry)        ： 千钧棒法              有效等级：228\n法术 (spells)       ： 道家仙法              有效等级：248\n拳脚 (unarmed)      ： 惊魂掌                有效等级：337\n轻功 (dodge)        ： 筋斗云                有效等级：339\n棍法 (stick)        ： 千钧棒法              有效等级：273\n', 33, 1778892406, 0, 1, 0, 0, '2026-05-19 01:52:48');
INSERT INTO `posts` VALUES (44, 'nancheng_b', '光棍帮', '小灵通(Xlt)', NULL, '新创光棍帮, 现广收门徒,热烈欢迎各方人士, 各路神仙加入.\n本帮宗旨:\n逍遥, 互助, 轻松, 自在, 友好,\n漂流四方, 定无居所, 常聚南城客栈,\n提倡神侃, 三教九流, 各显神通,\n不谈婚嫁\n新任帮主 -- 小灵通\n~\n', 36, 1778892406, 0, 1, 0, 0, '2026-05-19 01:51:18');
INSERT INTO `posts` VALUES (45, 'nancheng_b', '这算不算性别歧视？', '珊瑚(Mint)', NULL, '在西游记里，如果你扮演一个女性角色，而你训练的水平又不足以令你在三十岁以前达到不堕轮\n回的境界，那么，从你三十岁生日当天起，你就在别人的嘴里变成了死老太婆，老妖婆，在自己\n的嘴里变成老娘。\n众所周知，在三十岁以前达到不堕轮回是一件多么困难的事，据我所知，目前只有小道童一人做\n到。或者依然也有可能做得到，但对于绝大部分女性角色来说，那是一个可望而不可及的梦想。\n于是，那些同男玩家们一样刻苦练功的女玩家们，就不得不面对年仅三十，却被称为老太婆的痛\n或者在某些男士们的眼中，女孩子超过三十，便算是老了，这本来也算不了什么，浅薄的人到处\n都是。但在西游记里，为什么只对女孩子的年龄这样苛求？男玩家在五十岁以前，通通都是壮士\n或者是道兄，为什么不让男玩家超过三十岁就被称为老爷子？虽说自古美人如英雄，不许人间见\n白头，但总不能对英雄如此放松，对美人如此严格吧？这算不算是性别歧视呢？\n\n希望有同样感想的女玩家们联合起来，改变这种对女性极不公平的现状。\n', 37, 1778892406, 0, 1, 0, 0, '2026-05-19 01:50:45');
INSERT INTO `posts` VALUES (46, 'nancheng_b', 'last suggestion', '小马哥(Coolboy)', NULL, 'i think the 比武mode in xyj is not good,for it is only for highhands.\nnewbie can do nothing on pantaohui,they need fight too!\ni suggest wiz change mode:\nchange it to the mode like football league match,\nthose who r newbie will belong to a group let\'s name it 级外\nthose who r a little stronger than newbie belong to a group 丁级\nthose who r a little stronger than 丁级 belong to a group 丙级\nl\nand so on\n依daoxing分组\nevery year have a 联赛， 三战两胜制\nwho get the winner in his own group will up level to next group \nsure the last one in the group will fall to the lower group\nif it can be made into reality,then everyone will have fight match\nit\'s more interesting.isn\' it?\nwiz can give the winner a cup(rank)for praise\nmore interesting than xkx!!!!!!\nlet\'s make xyj the best mud in the world!\n另：不必取消蟠桃会\nwho would give the name for the 联赛?\n小马哥大赛?\n)\n^_^\n', 38, 1778892406, 0, 1, 0, 0, '2026-05-19 01:50:14');
INSERT INTO `posts` VALUES (47, 'nancheng_b', '席幕蓉散文选章 「燕子」', '无言独上西楼', NULL, '    初中的时候，学会了那一首“送别”的歌，常常爱唱：\n        长亭外，古道边，芳草碧连天。。。。\n    有一个下午，父亲忽然叫住我，要我从头再唱一遍。很少被父\n亲这样主意过的我，心里觉得很兴奋，赶快再从头来好好唱一次：\n        长亭外，古道边。。。\n\n    刚开了头，就被父亲打断了，他问我：\n    “怎麽是长亭外？怎麽不是长城外呢？我一直以为是长城外啊！”\n\n    我把音乐课本拿出来，想要向父亲证明他的错误。可是父亲并\n不要看，他只是很懊丧地对我说：\n\n    “好可惜！我一直以为是长城外，以为写的是我们老家，所以\n第一次听这首歌时就特别感动，且一直没有忘记，想不到这么多\n年竟然是听错了，好可惜！”\n    父亲一连说了两个好可惜，然就走开了，留我一个人站在空\n空的屋子里，不知如何是好。\n    前几年刚搬到石门乡间的时候，我还怀着凯儿，听医生的嘱咐，\n一个人常常在田野间散步。那个时候，山上还种了相思树，苍苍翠\n翠的，走在里面，可以听到各式各样小鸟的鸣声，田里面也总是绿\n意盎然，很多小鸟也会很大胆的从我身边飞掠而过。\n    \n    我就是那个时候看到那一只孤单的小鸟的，在田边的电线杆上，\n在细细的电线上，它安静地站在那里，黑色的羽毛，象煎刀一鸯的\n双尾。\n    “燕子！”我心中象触电一样地呆住了。\n    可不是吗？这不就是燕子吗？这不就是我从来没有见过的燕子\n吗？这不就是书里说的，外婆歌里唱的那一只燕子吗？\n    在南国的温热的阳光里，我心中开始一遍又一遍地唱起外婆爱\n唱的那一首歌来了：\n   \n    燕子啊！燕子啊！你是我温柔可爱的小小燕子啊。。。\n\n    在以的好几年里，我都会常常看到这种相同的小鸟，有的时\n候，我是牵着慈儿，有的时候，我是抱着凯儿，每一次，我都会很\n兴奋地指给孩子看：\n    “快看！宝贝，快看！那就是燕子，那就是妈妈最喜欢的小小\n燕子啊！”\n    怀中的凯儿正咿呀学语，香香软软的唇间也随着我说出一些不\n成腔调的儿语。天好篮，风好柔，我抱着我的孩子，站在南国的阡\n陌上，注视着那一只黑色的安静的飞鸟，心中充满了一种朦胧的欢\n喜和一种朦胧的悲伤。\n\n    一直到了去年的夏天，因为内政部的邀请，我和几位画家朋友\n一起，到南部的国家公园里写生，在一本报导垦丁附近天然资源的\n书里，我看到了我的燕子。图片上的它有着一样的黑色羽毛，一样\n的剪状的双尾，然而，在图片下的解释和说明里，却写着它的名字\n是“乌秋”。\n\n    在那个时候，我的周围有着好多的朋友，我却在忽然之间觉得\n非常的孤单。在我的朋友里，有好多位在这方面很有研究心得的专\n家，我只要提出我的问题，一定可以马上得到解答。可是，我在那\n个时候唯一的反应，却只是把那本书静静地合上，然静静的走了\n出去。\n\n    在那一刹那，我忽然体会出来多年以前的那一个下午，父亲失\n望的心情了。其实，不必向别人提出问题，我自己心里也已经明白\n了自己的错误。但是，我想，虽然有的时候，在人生的道路上，我\n们是应该面对所有的真相，可是，有的时候，我们实在也可以保有\n一些小小的美丽的错误，与人无害，与世无争，却能带给我们深沉\n安慰的小小的错误。\n\n    我实在是舍不得我心中的那一只小小的燕子啊！\n', 39, 1778892406, 0, 1, 0, 0, '2026-05-19 01:50:04');
INSERT INTO `posts` VALUES (48, 'nancheng_b', '无题', '秋风扫落叶', NULL, '巫师们联成了统一阵线，枪口一致对外，鳄鱼就当了一只等着\n加工的皮箱。事实上真相到底怎么样，当事人知道，大多数巫\n师也知道，不过这身份不同，处理的性质也就不同，鳄鱼的现\n行反革命帽子是别指望着揭了，犯错巫师开开党内生活会就好\n了，不管怎么说，到底人家是中央领导吗。最好的情况就是能\n发动大家群众斗群众，是不是刚好就借这事来转移目标来把群\n众的不满转个方向呢？ 三年自然灾害哪前不也正好反苏修麽？\n\n鳄鱼同志为革命作出过杰出贡献，可就象当年张国焘一样，半\n套半推的就给卖了，当然事后也没几个给说话的，各大巫师们\n高举着＂就事论事＂的牌子，一棍子接一棍子的把鳄鱼往死里\nＫ，有无公报私仇的不得而知。ｍｏｎ手里攥了大把证据，就\n生等着公审呢．．．可咋就不能ｐｅｒｖｅｎｔ呢？是不为也，\n非不能也？\n如果真要说就事论事，鳄鱼ｃｕｔ经验，武功，有关巫师该受\n什么处分？开除？降级？停职留薪？　这可是危害系统管理安\n全的严重思想态度路线错误，当然，如果是下了套害人家鳄鱼\n的，以上理论不成立。但是应该不会是人家嘴巴大点，发了些\n声音让人不舒服了就害一把呱，我想不会。人民的眼睛是雪亮\n的。巫师们不是那种人。。。\n\n不久就该有张安民告示出来了，我们要好好的珍惜巫师们花心\n血为我们创造的这么个好环境，少数象鳄鱼那样的害群之马一\n定是会被绳之以法的，到底，真理是在少数人手里的，或者原\n话是：真理是在少数有权人手里的。。。\n\n', 40, 1778892406, 0, 1, 0, 0, '2026-05-19 01:49:48');
INSERT INTO `posts` VALUES (49, 'nancheng_b', '幽默&笑话', '花花公子(Playboy)', NULL, '\n\n     臭JOKEY，竟敢辱骂本少，不怕被本少烤来吃了？:)~ 我POST多还不好吗？\nPOST的不算给你投了稿了，还要怎样才算投稿？\n\n\n 绝妙幽默思语\n\n   舞女的衣服让人想起了铁丝网,保护住里面的东西,却不妨碍你看到它.\n       \n   一天一个苹果,可以把医生赶走,但你若想当隐士,换个洋葱试试看.\n\n   为了节省用电而早早上床是不明智之举----如果制造成双胞胎的话.\n\n   永远不要借钱给朋友,那样会损害他的记忆力.\n\n   知识就是力量----特别是你知道名人的隐私.\n\n   JOKEY一天半夜被CALL机吵醒,起身一看，CALL机显示“姿势不对，起来重睡。PLAYBOY”\n\n   人奶比牛奶好的五个理由是: 快;清洁;安全,猫吃不到;旅行时比较方便;容器美观.\n\n                                                 :) 开心小少 ;)\n', 41, 1778892406, 0, 1, 0, 0, '2026-05-19 01:49:41');
INSERT INTO `posts` VALUES (50, 'nancheng_b', '让我到你家住！:)', '花花公子(Playboy)', NULL, ' 让我住到你家...\n-------------------------------------------------------------------------------\n                          !!! 免费服务 !!!\n\n             亲切可爱的男性,征求好心的美人儿供应食宿,交换条件是\n         昼夜保护你.白天陪你上街闲逛,夜间使你温暖.保证完全忠诚,\n         对你无任何要求.随时可以搬来与你同住.下午二时至四时之间\n         请电6894.周末除外.\n\n             PS:无诚意收养这只六个月大的德国牧羊狗者免问.\n\n                                                 :) 开心小少 ;)\n', 42, 1778892406, 0, 1, 0, 0, '2026-05-19 01:49:32');
INSERT INTO `posts` VALUES (51, 'nancheng_b', '广告', '花花公子(Playboy)', NULL, ' 广告妙语\n-------------------------------------------------------------------------------\n    .   眼药水广告：滴后请将眼球转动数次，\n    以便药水布满全球。\n    .   花店广告：送几朵花给你最爱的人，但\n    不要忘了你的妻子。\n    .   香水广告：本品最能吸引异性，故随本\n    品奉送自卫教材一份。\n    .   餐馆广告：请来本店用餐吧！不然你我\n    都要挨饿了。            \n    .   空调广告：本品在世界各地的维修工是\n    最寂寞的。\n    .   理发店广告：虽为毫发技艺，确是顶上\n    功夫。\n    .   美容院广告：请不要向本店出来的女子\n    调情，她也许就是你的祖母。\n    .   新书广告：本书包括十个短篇小说，我\n    熬了许多个夜晚才写出，现以一元钱奉献给\n    读者，即一个短篇才值一角钱。\n    .   安全广告：假如阁下烟瘾发作，可以在\n    此吸烟，不过请先将地址留下，以便将你的\n    骨灰送交家人。\n                                                 :) 开心小少 ;)\n\n', 43, 1778892406, 0, 1, 0, 0, '2026-05-19 01:49:12');
INSERT INTO `posts` VALUES (52, 'nancheng_b', '电脑幽默', '花花公子(Playboy)', NULL, ' 电脑的幽默\n-------------------------------------------------------------------------------\n\n  Ⅰ COMPAQ公司正准备将“按任意键”这一计算机指命令改为“按回车键”因为公司\n     每天都接到无数顾客打来的电话，询问“任意键”在计算机的什么地方。\n\n  Ⅱ ＡＳＴ公司的一位技术员接到了一位男性顾客的投诉电话，说他的计算机系统读\n     不了他旧磁盘的文字处理文件。查找原因时既未发现他的磁盘受过强磁辐射也未\n     发现受过热。不过这位先生曾经给这张磁盘贴了个标签，然后再一股脑儿卷到打\n     字机的的滚筒上打了几个字，认为是做了“卷标”。\n\n  Ⅲ 一位DELL公司的顾打电话向公司投扩，说他的计算机发不出任何传真。于是公司\n     的技术员花了四十分钟的时间检查了他的传真时，他说，“我先把要发的那张纸\n     举在计算机的荧光屏前，然后敲键盘上的‘发送’这个键。”\n\n  Ⅳ ＡＳＴ公司要求一位顾客把她那些有毛病的磁盘拷贝一份给公司寄来。几天以后\n     公司果然收到了她的来信，信袋中只夹了几张用复印机复印的磁盘复印件。（注\n     ：英文中复制磁盘、复印纸张、转录磁带等都用“拷贝”这个词。）\n\n  Ⅴ 一位DELL公司的顾客打电话向公司投诉，说他的计算机键盘再也不工作了。原来\n     他先把键盘放在灌满肥皂水的桶里泡了一天，再把所有的键拆下来，一个一个地\n     洗了一遍。他原来是一位机械修理工。\n\n  Ⅵ 一位怒气冲天的女士给DELL计算机服务部打电话，说她新买的计算机无论如可也\n     启动不了。技术人员先问她是否已插上了电源插头，又问她按电源开关时计算机\n     有什么反应。这位顾客回答说：“我一遍又一遍踩脚踏板，这个计算机实在没有\n     半点反应。”原来她所谓的“脚踏板”指的是计算机的鼠标。\n\n  Ⅶ 以下是发生在NOVELL网络系统公司的真实故事：\n     顾客：“喂，是技术服务部吗？”\n     技术员：“是的。我能为您做点什么？”\n     顾客：“我计算机上的茶杯架坏了。 这台计算机还没出保修期呢，请问我如何到\n             您那里修一下？”\n     技术员：“对不起，您刚才说是要修茶杯架吗？”\n     顾客：“不错。它原来就安装在计算机的前部。”\n     技术员：“实在对不起。如果我让您觉得糊涂的话，那是因为我自己确实糊涂了。\n             那个茶杯架是不是您在交易会上得到的赠品？上面是否有商标？您是怎\n             么得到的？”\n     顾客：“我不知道有什么赠品。那是计算机本身带的，上面只有一个‘４×’字样\n             。”\n     此时这位技术员不得不把电话挂断，他实在无法再和对方谈下去了。原来这位先生\n     把光盘驱动器（ＣＤ－ＲＯＭ）上的光盘托架拉出来当成了茶杯架。\n\n  Ⅷ 有人买了个电脑,给维修中心打电话,说电源在冒烟, 非说是用软件除掉不可,维修\n     中心的人哭笑不得,就让他和微软联系这个软件,并骗他说这个软件叫:\n     NO SMOKE.EXE过了片刻,这个白痴打回来电话,说微软的人告诉 他,这个软件和他\n     的计算机不兼容.\n                                                 :) 开心小少 ;)\n\n', 44, 1778892406, 0, 1, 0, 0, '2026-05-19 01:48:56');
INSERT INTO `posts` VALUES (53, 'nancheng_b', 'joke(1)', '双儿(Shuanger)', NULL, '从前有个牛皮先生,自以为很会说,他听说邻村有一个种田的比他还会说,当众\n夸下海口,说:哼,说赢他,只要半张嘴就行了.\n第二天,牛皮先生就去找那个种田的,并故意把嘴用纸糊了一半,正好碰到种田\n人的孩子,便问:你爹呢?\n小孩说道:我爹耕田去了.\n到哪里耕田?\n锅沿上.\n那耕什么田啊?\n耕锅巴!\n嘻嘻,牛皮先生感到好笑说:那不怕牛屎掉进锅里去吗?\n小孩说:不要紧,牛屁股用纸糊着呢.\n牛皮先生听后,气昏过去了.\n', 45, 1778892406, 0, 2, 0, 0, '2026-05-19 01:48:51');
INSERT INTO `posts` VALUES (54, 'nancheng_b', '(8)', '双儿(Shuanger)', NULL, '1.也许大家都听说过毛主席诗词:到了黄洋界,险处不需看,以及黄洋界\n\n上炮声隆...在黄洋界这样记载着:红军当时一共有三发炮弹,发射的时候,两发臭\n\n弹,只响了一发. 于是毛主席写下了\"黄洋界上炮声隆\"......\n\n2.井岗上会师的时候,红军人数加起来不足一个军.合编后取名工农红军第\n\n四军.....有人知道为什么叫第四军吗? 答案:让敌人还以为还有第一军,第 二\n\n军,第三军..............\n\n这下,我知道毛主席为什么得天下了....虚虚实实.....\n\n三发响一发------叫炮声隆...\n\n一个军不到--------号称第四军......\n\n怪不得老蒋拿老毛没办法! 明白了..明白了!\n', 46, 1778892407, 0, 1, 0, 0, '2026-05-19 02:04:10');
INSERT INTO `posts` VALUES (55, 'nancheng_b', '(9)', '双儿(Shuanger)', NULL, '有一个中国人到西班牙旅游，就到餐厅吃饭，看到服务生端了一盘菜\n\n看见有二颗很大的东西，就问服务生\n这是什麽东西? 服 务生回答\n\n\n这是早上斗牛时从牛上面割下来的......... 。\n\n这个中国人也叫了这一道菜（ 中国人有一个观念\n吃什麽补什麽 ）\n\n但服务生说\n要下个星期才有，中国人於是等到下个星期，但服务生\n\n端出来的是二颗这麽小的。中国人很生气的对服务生说\n这次的怎麽\n\n那麽小，服务生以很不屑的口气回答他\n你以为每次都是牛死掉啊!!\n', 47, 1778892407, 0, 1, 0, 0, '2026-05-19 02:03:58');
INSERT INTO `posts` VALUES (56, 'nancheng_b', '西游片段---结婚记', '围棋', NULL, '--------------------------------------------------------------------------------\n南城客栈 -\n\n这家客栈紧靠长安南门，所以生意非常兴隆。兼之价钱低廉，更是\n成了外地游客落脚的首选。三教九流人等在此进进出出，络绎不绝，\n把个店小二忙得团团转。\n    这里明显的出口是 west 和 up。\n  方寸山三星洞第二代弟子 不绝(Bujue)\n  阎罗地府第三代弟子「酒囊饭袋」络绎(Luoyi)\n  方寸山三星洞第四代弟子「海枯石烂，天荒地老」双儿(Shuanger)\n  阎罗地府第三代弟子 地平线(Horizon)\n  南城客栈留言板(Board) [ 59 张留言 ]\n  店小二(Xiao er)\n  邮差 千里眼(Bigeye)\n\n【闲聊】双儿长叹一声：酒醒寒夜时，独徘黄昏处。年少伤心事，只恐无人知。\n【闲聊】地平线开始梦想什么时候能够嫁给双儿．．．，兴奋得满脸通红。\n        《这个semote 比较适合于女人用。》\n【闲聊】双儿飞起一脚，正好踢中地平线的屁股！\n【闲聊】络绎毫不留情地耻笑地平线的愚昧。\n【闲聊】烤狮向双儿勇敢的跪了下来：“你愿意嫁给我吗？”---真是勇气可嘉啊！\n【闲聊】双儿(Shuanger)：我答应等guy ...\n        《旧日情人？》\n【闲聊】双儿想到伤心处，忍不住放声大哭。\n\n【闲聊】双儿(Shuanger)：哎呀，我会变心的！\n【闲聊】围棋(Weiqi)：就地处理吧：）\n【闲聊】双儿(Shuanger)：我是天下第一低手，第一美女！\n【闲聊】蟑螂对着双儿凛然道，“嫂嫂休要荏地不知羞耻！你家小爷我的眼里认得\n是嫂嫂，你家小爷我的拳头不认得是嫂嫂！”\n【闲聊】络绎狠狠掴了蟑螂几个大耳光，打得蟑螂眼冒金星。\n【闲聊】络绎看着双儿长叹一声道：当真是回头一笑百媚生，泥潭粉黛无颜色。\n【闲聊】地平线向双儿勇敢的跪了下来：“你愿意嫁给我吗？”---真是勇气可嘉啊！\n【闲聊】不绝向双儿勇敢的跪了下来：“你愿意嫁给我吗？”---真是勇气可嘉啊！\n【闲聊】双儿(Shuanger)：i\'ll marry now!!! who is highhand?!\n        《看样子没有实力是讨不着老婆的。》\n\n【闲聊】不绝对着双儿拍着胸脯说：只要你嫁给我，你叫我做什么我就做什么！\n【闲聊】地平线(Horizon)：读书识字 (literate)                      - 深不可测 141/    0\n【闲聊】双儿(Shuanger)：i\'ll marry horizon of course\n【闲聊】地平线高兴地跳进了双儿的怀里！\n【闲聊】不绝(Bujue)：same as me lah...\n【闲聊】不绝(Bujue)：horizon is too old...\n【闲聊】不绝(Bujue)：i am rich....\n        《此项绝不可忽视。》\n【闲聊】不绝(Bujue)：horizon is over 30, me only 19...\n【闲聊】地平线(Horizon)：你是一位二十四岁的男性人类，戊戌年二月十四日申时二刻生。\n【闲聊】络绎(Luoyi)：yah, horizon already married.. same as me\n【闲聊】地平线(Horizon)：你目前是光棍儿一条。\n【闲聊】地平线突然觉得一股恶气冲上心头，只觉得想杀人....\n\n【闲聊】双儿(Shuanger)：bujue your skills?\n【闲聊】不绝(Bujue)：一百一十年十五天六时辰\n        《道行是衡量强弱的主要指标，看来比地平线的低？》\n【闲聊】双儿对著不绝叹了口气。\n【闲聊】双儿(Shuanger)：then i marry horizon bah\n【闲聊】不绝(Bujue)：marry me bah, horizon is too old...\n【闲聊】双儿(Shuanger)：but horizon\'s skills are higher,,xixi\n【闲聊】不绝(Bujue)：but horizon is much older than me...\n【闲聊】双儿(Shuanger)：fight bah\n【闲聊】不绝(Bujue)：and i also have 141 level ...\n【闲聊】双儿(Shuange