INSERT INTO `room_actions` VALUES (2, 'changan/eside5', '抛竿钓鱼', 'diao', 'special', '老人们正在垂钓', 2, 1, 'FishHandler', '{\"sub_action\": \"diao\", \"fish_variants\": [{\"name\": \"青鱼\", \"item_id\": \"qingyu\", \"category\": \"southern\"}, {\"name\": \"金色鲤鱼\", \"item_id\": \"golden_carp\", \"category\": \"changan\"}, {\"name\": \"草鱼\", \"item_id\": \"caoyu\", \"category\": \"southern\"}], \"stage_duration\": 10, \"trash_variants\": [{\"name\": \"水草\", \"unit\": \"把\", \"item_id\": \"shuicao\"}, {\"name\": \"破靴子\", \"unit\": \"只\", \"item_id\": \"poxuezi\"}, {\"name\": \"烂泥\", \"unit\": \"团\", \"item_id\": \"lanni\"}, {\"name\": \"螃蟹壳\", \"unit\": \"个\", \"item_id\": \"pangxieke\"}], \"fishing_messages\": [\"水面上一点动静也没有。\", \"河水泛起一片涟漪。\", \"一个小水花逐渐靠向浮子。\", \"浮子抖动了两下。\", \"浮子开始颤抖着。\", \"水面又恢复了平静。\"], \"sen_cost_per_stage\": 30, \"stage_advance_chance\": 0.5}');
