INSERT INTO `room_item_descs` VALUES (12, 'dntg/hgs/dongnei', 'bed', '石床', '内堂中有一张石床，上面铺着虎皮，十分舒适。', 1);
INSERT INTO `room_item_descs` VALUES (13, 'changan/ph', 'paizi', '牌子', '牌子上写着几户人家的名字：\r\n张府\r\n李府\r\n王宅\r\n赵园', 1);
INSERT INTO `room_item_descs` VALUES (14, 'moon/fengxue/fdoor', 'gaoshi', '告示', '枫雪天地会告示：\n本会宗旨：团结江湖豪杰，行侠仗义，除暴安良。\n入会条件：需由两名以上会员推荐，通过入会考验。\n日常活动：每周六晚举行例会，讨论江湖大事。\ncontact 联系会长。', 1);
INSERT INTO `room_item_descs` VALUES (15, 'moon/ontop2', 'tree', '桂树', '一株高耸入云的大桂树。上面无数的桂花正散发出阵阵清香，不知道怎样才能采集到。', 1);
INSERT INTO `room_item_descs` VALUES (16, 'city/sanhua-mishi', 'paper', '破纸', '悬赏杀人：\r\n用 pay <amount> gold for <id> 来悬赏追杀名为<id> 的玩家。\r\n\r\n可多次追加赏金，但不能取回。\r\n如果一周内无人追加赏金，本堂将收取总额三成的保管费。\n当前被悬赏名单及金额可用 list 和 list <id>查看。\n\n领取赏金：\r\n任何人可凭被悬赏玩家的尸体来领取赏金。\n只要 drop corpse 即可。', 1);
INSERT INTO `room_item_descs` VALUES (17, 'qujing/firemount/shimen', 'stone', '乱石', '一块有棱角的石头，看起来可以用来砸门。', 1);
INSERT INTO `room_item_descs` VALUES (18, 'city/duchang1', 'paizi', '牌子', '墙上挂着一个大大的「签」字，下面是各种赌注的说明：\n\n大乾签（全部五根皆为乾签）：一赢三十二\n大坤签（全部五根皆为坤签）：一赢三十二\n小乾签（连续四根皆为乾签）：一赢十六\n小坤签（连续四根皆为坤签）：一赢十六\n  乾签（任意三根皆为乾签）：一赢二\n  坤签（任意三根皆为坤签）：一赢二\n\n点击「押签」进入下注页面。', 1);
INSERT INTO `room_item_descs` VALUES (19, 'city/duchang4', 'paizi', '牌子', '龟房的墙上挂着牌子，写着：\n\n押长寿龟： sai cs <数目> <货币>\n押千年龟： sai qn <数目> <货币>\n押不老龟： sai bl <数目> <货币>\n\n赔率：一赢三\n点击「赛龟」进入下注页面。', 1);
INSERT INTO `room_item_descs` VALUES (20, 'city/duchang2', 'paizi', '牌子', '墙上挂有一个匾，上面写着：\n\n    头彩（骰数由每次开盘前确定）      ：一赢三十六\n    双对（两骰号相同，且为偶数）      ：一赢十二\n    七星（两骰之和为七）              ：一赢六\n    散星（两骰之和为三，五，九，十一）：一赢三\n\n押头彩骰： gutou tc <数目> <货币>\n押双对骰： gutou sd <数目> <货币>\n押七星骰： gutou qx <数目> <货币>\n押散星骰： gutou sx <数目> <货币>\n\n点击「押骰」进入下注页面。', 1);
INSERT INTO `room_item_descs` VALUES (21, 'city/duchang3', 'paizi', '牌子', '斗鸡房的墙上挂着牌子，写着：\n\n押红冠鸡： dou hg <数目> <货币>\n押绿尾鸡： dou lw <数目> <货币>\n\n赔率：一赢二\n双败赔本：两鸡同归于尽则全输\n点击「押鸡」进入下注页面。', 1);
INSERT INTO `room_item_descs` VALUES (22, 'city/clubpoem', 'qishi', '启事', '本社新增猜诗游戏，由茶博士将一句诗词的若干字\n颠倒次序，写在墙上。能准确答出(answer)原句者为胜。\n\n例如：茶博士提笔在墙上写道：离离原上草一荣一枯岁\n你应该回答：answer 离离原上草一岁一枯荣', 1);
INSERT INTO `room_item_descs` VALUES (23, 'city/clubpoem', 'poem', '诗', '茶桌上刚刚写好一首诗。\n\n（look poem 可查看当前题目和上一首完整诗词）', 1);
INSERT INTO `room_item_descs` VALUES (24, 'city/shaizi-room', 'paizi', '牌子', '墙上挂有一块匾，上面写着：\n\n赌骰子规则：\n每一轮有个庄家，输赢只跟庄家比。两粒骰子，成对为大。十点最小。\n开赌顺序：\n一，确定庄家(用zz或zuozhuang坐庄，retire或rz, rangzhuang让庄)。\n二，庄家宣布开盘(start <赌注上限>)。\n三，玩家下注(bet或xz, xiazhu)。\n四，庄家下注(bet或xz, xiazhu)，至少要押别的玩家的总和。\n五，庄家下注就开赌了。\n\n注意事项：\n一，赌中不要离开赌场，否则一切损失概不负责。\n二，坐庄时要先拿出五两金子的保证金，让庄时退还。非正常丢庄(如\n　　中途离开等)保证金自动失去。\n三，每一轮从庄家宣布开盘起十分钟之内必须完成，否则取消重来。\n　　非庄家所下之注可被退回，而庄家则可能会有损失。\n四，如果庄家迟迟不宣布开盘，玩家可用坐庄(zz)指令要求换庄。\n　　要求换庄后两分钟内庄家比须宣布开盘，否则丢庄。\n五，在下注过程中可用取消(cancel)指令。庄家用此指令则宣布此局无效，\n　　大家将赌注取回，庄家非正常丢庄。非庄家用此指令则表示退出此\n　　局，赌注可取回。\n\n点击「掷骰」进入游戏页面。', 1);
INSERT INTO `room_item_descs` VALUES (25, 'city/shaizi-room', 'table', '长条桌', '这是一张看起来相当结实的大长条桌，桌面上有着常年累月被骰子砸出的坑坑洼洼。\n桌上放着两粒象牙骰子和一个青花瓷碗。\n\n使用 look table 可以查看当前赌桌状态。', 1);
INSERT INTO `room_item_descs` VALUES (26, 'city/piggy_n', 'table', '石桌', '一张石桌，桌面镶了一块大理石，摸上去极为光滑。桌上刻着四个方位标记：东、北、西、南。\n用 look table 可以查看当前牌局状态。', 1);
INSERT INTO `room_item_descs` VALUES (27, 'city/piggy_n', 'gaoshi', '告示', '┌───────────────────────────────────┐\n│          拱 猪 规 则              │\n├───────────────────────────────────┤\n│ 1. 四人对战，用 sit <方向> 入座   │\n│ 2. 发牌后可 sell [-m] <牌> 卖牌   │\n│    -m 为明卖(分值×4)，无参数暗卖  │\n│ 3. pass 停卖，四人停卖后开拱      │\n│ 4. play <牌> 出牌，必须跟花色     │\n│ 5. 第8轮后可 claim all 要求全收   │\n├───────────────────────────────────┤\n│ 猪(黑桃Q)=-100  羊(方片J)=+100   │\n│ 变压器(草花T)=+50  血(红桃A)      │\n│ 收全红(13张红桃)-> -200变+200    │\n│ 全收(红桃+猪+羊+变压器)->三人猪头│\n│ 入场费：50文铜钱                 │\n└───────────────────────────────────┘\n\n详细规则请看 piggy_rule.php', 1);
