INSERT INTO `rooms` VALUES (1, '33tian', '33tian/33tian', '离恨天', '这里就是天的尽头。抬头望去，上面是白茫茫的一片，白云从你指间流过。你的脚下就是天宫了，隐约能看到雕栏画栋，听到丝竹笙歌，光彩流动，奇丽不可名状。这里没有昼夜之分，只有空气中不时传来缕缕清香，令人感到平静安宁。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2, '33tian', '33tian/doushuai-gate', '殿门', '走近看来，原来这座宫殿并不十分宏伟。殿门上横挂一块匾(bian)，两边有一付对联 (duilian)。里面静悄悄的，也不知有没有人。正殿后面隐隐约约可以看到一片松林，想必是个清修的好地方。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3, '33tian', '33tian/west1', '离恨天', '四处白茫茫一片，你似乎飘在白云之上。东边，南边，和北边都看不远。只有西边，隐隐现出一座宫殿。殿门上横挂着一面闪闪发光的金匾，上写着「兜……」。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4, 'changan', 'changan/aolaiws', '傲来国西海岸', '这里是傲来国西海岸。西面茫茫大海望不到边际。海面上波涛汹涌，几丈高的浪头此起彼伏，象是要吞灭一切敢于到海上的东西。也许这里便是路的尽头，面前的大海对一个凡人来说是不可逾越的。离岸不远处漂着一只木筏(mufa)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (5, 'changan', 'changan/beach', '东海海滩', '夜间的大海，海水如墨，风平浪静。月光在海面上划出一道银光，给安静的海面增加了一丝生机。然而就在这宁寂的表面下，海水深处暗涛汹涌，水声隆隆，似乎要将一切生命吞噬。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (6, 'changan', 'changan/bed', '木床', '一张大木床。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (7, 'changan', 'changan/bridge', '泾水桥', '此桥高跨泾水之上，气势非凡。桥身以汉白玉造就，既美观又坚固。桥下车水马龙，川流不息。桥下泾水清澈见底，时有游鱼跃起。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (8, 'changan', 'changan/broadway1', '大官道', '这是一条宽阔笔直的官道，足可容得下十马并驰。往南通向南部沿海，往北则直达大唐国都长安城。西面有一条崎岖小路，不知通向何处。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (9, 'changan', 'changan/broadway2', '大官道', '这是一条宽阔笔直的官道，足可容得下十马并驰。往南通向南部沿海，往北则直达大唐国都长安城。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (10, 'changan', 'changan/broadway3', '大官道', '这是一条宽阔笔直的官道，足可容得下十马并驰。往南通向南部沿海，往北则直达大唐国都长安城。西面有一条青石路，想来是通往西部边陲。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (11, 'changan', 'changan/broadway4', '大官道', '这是一条宽阔笔直的官道，足可容得下十马并驰。往南通向南部沿海，往北则直达大唐国都长安城。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (12, 'changan', 'changan/broadway5', '大官道', '这是一条宽阔笔直的官道，足可容得下十马并驰。往南通向南部沿海，往北则直达大唐国都长安城。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (13, 'changan', 'changan/eastseashore', '东海之滨', '面前便是东海，茫茫大海望不到边际。海面上波涛汹涌，几丈高的浪头此起彼伏，象是要吞灭一切敢于到海上的东西。也许这里便是路的尽头，面前的大海对一个凡人来说是不可逾越的。离岸不远处漂着一只木筏(mufa)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (14, 'changan', 'changan/eside1', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (15, 'changan', 'changan/eside2', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。北面靠城墙有一座小土丘。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (16, 'changan', 'changan/eside3', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (17, 'changan', 'changan/eside4', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (18, 'changan', 'changan/eside5', '泾水之滨', '　　泾水东去，绿杨城郭。漫步于此，不由得心旷神怡。只见这泾水清澈见底，不时有鱼儿越出水面，旁边一群孩子们正在挖(wa)蚯蚓(qiuyin)，几位老人正在垂钓(diao)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (19, 'changan', 'changan/fendui', '荒坟堆', '这里是长安城南的一片荒地，周围密密麻麻地堆了好几十个坟头。有些坟前还有些祭祀，烧纸的痕迹。四处荒凉，很少有人走动，偶而有几只寻食的野狗跑过。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (20, 'changan', 'changan/inwater', '泾水', '周围是齐腰深的河水，从四周的景色来看大概是在长安城南，泾水之中．流水清澈见底，远处还有几条小船．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (21, 'changan', 'changan/mufa', '海中孤筏', '孤筏在海中漂流，四周是白茫茫的一片汪洋。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (22, 'changan', 'changan/nanchengkou', '南城口', '这里是长安的南城口。往北望去已可看到南城门络绎不绝的人流及城口守卫的官兵。南去一桥高跨泾水，而天际处终南山麓淡淡地横过你的视野，不由人不赞叹这长安城地处天地钟秀之汇冲，不愧是王都之气象。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (23, 'changan', 'changan/nanyue', '南岳', '一路行来，已到衡山地界。衡山古称南岳，雄踞南天，气势磅礴。南以回雁峰为首，北以岳麓山为足，大小七十二峰逶迤盘绕八百余里。然则此地自古民风剽悍，盗匪随处横行，在此行走可得小心为是。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (24, 'changan', 'changan/nbridge', '泾水桥北', '往北穿过城门即可入城，跨过泾水桥往南有一条大官道离城。顺着泾水之滨东西望去，在河边信步闲游的人着实不少。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (25, 'changan', 'changan/office', '房管所', '泾水河边的居民逐渐增多，因此特别在此设立房管所，临时由一个不知名的老头负责。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (26, 'changan', 'changan/officer', 'officer', '泾水河边的居民逐渐增多，因此特别在此设立房管所，临时由一个不知名的老头负责。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (27, 'changan', 'changan/ph', '住宅区', '泾水之滨的一块住宅区，沿河坐落着一栋栋漂亮的小别墅。这里风光旖旎，气息清新，正是住家的绝好所在。几座小楼前挂着牌子(paizi)，写着些人家的名字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (28, 'changan', 'changan/phomes', '住宅区', '泾水之滨的一块住宅区，沿河坐落着一栋栋漂亮的小别墅。这里风光旖旎，气息清新，正是住家的绝好所在。几座小楼前挂着牌子(paizi)，写着些人家的名字。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (29, 'changan', 'changan/pinqiting', '品棋亭', '品棋亭南眺泾水，北靠长安高墙，虽不是四野开阔，却也是手谈休栖的好地方。亭中有一张石桌，上面划着一张围棋盘。桌角摆放着棋子。另外还有两张石凳，颜色一深一浅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (30, 'changan', 'changan/sbridge', '泾水桥南', '已经到了泾水桥南。往南是一条宽阔笔直的官道，足可容得下十马并驰。往北则见宫城巍峨，正是大唐国都长安城。长安乃历代建都之所，素有\"三州花似锦，八水绕城流\"之称。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (31, 'changan', 'changan/seashore1', '海滨', '这里没有明显的大道通往内地。而另一面是一片汪洋大海。你只好沿着海边行走，希望能找出了一条大路来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (32, 'changan', 'changan/seashore2', '海滨', '这里没有明显的大道通往内地。而另一面是一片汪洋大海。你只好沿着海边行走，希望能找出一条大路来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (33, 'changan', 'changan/southgate', '南城门', '大门紧闭。门上有一张安民告示，上书：\n\r\n长安南门暂闭数日。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (34, 'changan', 'changan/southseashore', '南海之滨', '南海之滨。往北是一条宽阔笔直的官道，足可容得下十马并驰。往南则是一片汪洋大海，不知通向何方。西南海面上隐隐可见一小岛。浅海近岸处还有几个游泳的人。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (35, 'changan', 'changan/tmpbank', '相氏钱庄临时办事处', '因为长安城暂闭数日，相老板为顾客方便计，在泾水河边临时开设了一个办事处，并派出他最得力掌柜铁算盘在此坐阵。办事处只是一间简陋的小木棚，门口挂有一块牌子(paizi)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (36, 'changan', 'changan/tmppawn', '三喜当铺临时办事处', '三喜当铺在长安算是最大的当铺了。因长安南门暂闭，所以在泾水河边临时开了个办事处。门口有一块牌子(paizi)。你揭开门帘进来后才发现里面很暗。掌柜的见你进来，象防贼似的赶紧把柜台上的几小块碎银收到柜台底下。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (37, 'changan', 'changan/wroad1', '青石路', '这条路相当好走。往东不远即是贯穿大唐南北的大官道。往西直达西部边陲。路上车马不少，更有一队队的官兵押着一车车的辎重通过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (38, 'changan', 'changan/wroad2', '青石路', '这条路相当好走。这里已经靠近西部边陲了。路上车马不少，更有一队队的官兵押着一车车的辎重通过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (39, 'changan', 'changan/wroad3', '青石路', '往西而去路逐渐难行，青石路已开始变成土路了。前方好象有一个小镇，你不由得加快了步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (40, 'changan', 'changan/wside1', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
