INSERT INTO `rooms` VALUES (43, 'changan', 'changan/wside4', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (44, 'changan', 'changan/wside5', '泾水之滨', '泾水东去，绿杨城郭。漫步于此，你不由得心旷神怡，长长地吸了一口气。而微风中一股清新气息，不知由何处飘来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (45, 'changan', 'changan/xiaoqiu', '小土丘', '泾水河边的一座小土丘，不知因何垒成。微风掠过，坡上垂柳沙沙而动。绿荫中有一小亭，亭上牌匾\"品棋亭\"三个大字写得是意兴盎然。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (46, 'changan', 'changan/zhongnan', '终南山口', '终南山又称太乙山，距长安城八十多里，素有\"锦秀巨屏拱长安\"之说。据传老子曾在山中讲经。这条大官道穿越终南山口，两面秀峰入云，却无明显之路可以上山。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (54, 'changan', 'changan/playerhomes/home', '标准新房', '一切都设置好了，只等一些室内装修。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (55, 'changan', 'changan/playerhomes/h_mes', '小草屋', '一切都设置好了，只等一些室内装修。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (58, 'changan', 'changan/playerhomes/h_none', '呆头呆脑和魂断兰桥的家', '一切都设置好了，只等一些室内装修。墙上(wall)还挂着几张字画．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
