INSERT INTO `rooms` VALUES (63, 'changan', 'changan/playerhomes/stdbed', '床上', '', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (64, 'changan', 'changan/playerhomes/stdhome', '标准新房', '一切都设置好了，只等一些室内装修。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (65, 'city', 'city/baihu-w1', '白虎大街', '你走在一条宽阔的石板大街上，东面就快到城中心了，可以看到钟楼', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (66, 'city', 'city/baihu-w2', '白虎大街', '你走在一条宽阔的石板大街上，东面就快到城中心了，可以看到钟楼', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (67, 'city', 'city/baihu-w3', '白虎大街', '这里已是白虎大街的西段，北面小巷里隐约看到一座大的草堂，堂外', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (68, 'city', 'city/bank', '相记钱庄', '这是一家老字号的钱庄，相老板是山西人，这家钱庄从他的爷爷的爷爷的爷爷的爷爷那辈开始办起，一直传到他手里，声誉非常好，在全国各地都有分店。它发行的银票通行全国。钱庄的门口挂有一块牌子(paizi)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (69, 'city', 'city/baodian', '大雄宝殿', '正中一座金身大佛盘腿坐在莲花宝座之上，左右是四大天王。一十八位金刚分列两旁。佛前的供台上是善男信女带来的香烛供品及写下心愿的香纸，供台下一个小箱，装的是供奉的金银。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (70, 'city', 'city/beiyin1', '背阴巷', '背阴巷位于长安城之西南，住户大多是些贫苦人家。由于官府很少管', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (71, 'city', 'city/beiyin2', '背阴巷', '背阴巷位于长安城之西南，住户大多是些贫苦人家。由于官府很少管', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (72, 'city', 'city/beiyin3', '背阴巷', '背阴巷位于长安城之西南，住户大多是些贫苦人家。由于官府很少管', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (73, 'city', 'city/beiyin4', '背阴巷', '背阴巷位于长安城之西南，住户大多是些贫苦人家。由于官府很少管', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (74, 'city', 'city/beiyin5', '背阴巷', '背阴巷位于长安城之西南，住户大多是些贫苦人家。由于官府很少管', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (75, 'city', 'city/bingqipu', '兵器铺子', '刚一进门就看到兵器架上摆着各种兵器，从上百斤重的大刀到轻如芥子的飞磺石，是应有尽有。女老板是老英雄萧振远的小女儿，也是振远镖局二老板，巾帼不让须眉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (76, 'city', 'city/bookstore', '三联书局', '这是一家新开张不久的书局。书架上整整齐齐地放着一些手抄的卷轴。雕板印刷书到了唐朝已日趋成熟，因此这里的书架上也放着不少印制精美图文并茂的图书。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (77, 'city', 'city/caotang', '袁氏草堂', '这里是袁守诚先生算卦测字的地方。提起袁守诚，长安城中无人不晓，他乃是当朝钦天监台正先生袁天罡的叔父。小屋里整日访客络绎不绝。堂上挂一幅对联，乃是：\r\n\n            知凶定吉，开谈风雨迅\n            断死言生，下笔鬼神惊', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (78, 'city', 'city/center', '十字街头', '这里便是长安城的中心，四条大街交汇于此。一座巍峨高大的钟楼耸立于前，很是有些气势。每到清晨，响亮的钟声便会伴着淡淡雾气传向长安城的大街小巷。路口车水马龙，来往人潮不断。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (79, 'city', 'city/chenghuang', '城隍庙', '城隍庙里香火极盛。大多是来保佑家里平安，生意兴隆之类。正中前方一座白白胖胖，满脸福相的城隍，左边有一位手持帐簿和毛笔的判官。一位庙祝走前走后，和大家打着招呼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (80, 'city', 'city/club', '长安乐坊', '这里是长安城一家有名的娱乐场所。当夜幕降临后，这里就格外热闹。进进出出的客人有达官贵人，南来北往的商旅，浪迹天涯的游子，三五成群的兵士，有时也能看见一些作俗客打扮的僧人或道士。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (81, 'city', 'city/club3', '聚义厅', '这是一间宽敞明亮的大厅，厅的正中间是一根圆形的柱子。柱子上贴满了各种广告：有换房的，有卖家具的，但其中最多的还是找打牌搭档的广告。厅的东南西北各有个门，里面传出\"拱啊！\"\"毙了！\"等的叫声。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (82, 'city', 'city/clubpoem', '乐府诗社', '高楼之上，满城繁华尽收眼底。文人骚客都喜欢在这里品茶吟诗，谈古论今，你瞧，不知谁在茶桌上刚刚写好一首诗(poem)。里边柜台上新贴了张启事(qishi)，你不由得走过去看了几眼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (83, 'city', 'city/clubup', '长安二楼', '乐坊楼上显得格外热闹，走廊里人来人往，几间屋子里人声嘈杂，牌签骨骰钱币落盘的声音不绝。看样子，客人们赌得正欢呢。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (84, 'city', 'city/dangpu', '董记当铺', '这是长安城里最大的一家当铺了。素来以买卖公平着称。门口挂了一块牌子 (paizi)。董老板是个很精明的生意人，见你走了进来，很客气地和你寒暄，但眼睛里却没有什么笑意，很审慎地打量着你。', '0', 'normal', 1, 1, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (85, 'city', 'city/dongmen', '长安城东门', '这里是长安城的东门。西面就到了城中，远望人山人海，往来行人车流不绝。西面一条大路通向远方。城门下有一些执勤的兵士。时下虽已天下太平，但一干兵将还是英姿勃勃，警惕的盯着往来人士。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (86, 'city', 'city/duchang1', '押签房', '一群人围着紫檀木大桌而坐，首席座着一位精瘦的签客，正在一本正经地摇着签筒。旁边站着几个伙计，忙着收钱付钱。墙上挂着一个大大的「签」字，下面是各种赌注的说明。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (87, 'city', 'city/duchang2', '骨骰房', '这里摆着一个八仙桌，中间摆着一个银盘。赌客们正聚精会神地下赌。庄家坐在桌前，手里拿着骰盅，正准备开庄。四周的墙壁上画着各种点数的图案。正席是一位胖子，手里不断玩弄着一对玉骰，他就是这里的庄东。墙上挂有一个匾，上面写着：头彩...双对...七星...散星...匾角有一个牌子(paizi)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (88, 'city', 'city/duchang3', '斗鸡房', '斗鸡房里一左一右放着两个青竹鸡笼，一个鸡笼里关着一群红冠鸡，另一个笼子里则是几只黑羽公鸡。笼子前面围着一圈看客，正兴致勃勃地讨论着哪只鸡能获胜。屋子正中是七尺见方的斗鸡场，由一圈低低的青玉栏杆围成。一位白髯鸡仙正在张罗着斗鸡。在他的后面墙上有一个牌子(paizi)。墙上挂着斗鸡的规则和赔率表。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (89, 'city', 'city/duchang4', '赛龟房', '一排紫色的镂空檀香靠背椅沿着屋子四周放了一圈，坐着聚精会神的赌客。屋子中央是一个长方形的水池，里面有几只乌龟正在缓慢爬行。水池边上站着一个伙计，正在记录各只乌龟的位置。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (90, 'city', 'city/fangzhang', '方丈室', '一间小小的斗室，也没有窗户。房间里只点了一盏小油灯，显的特别昏暗。一榻一几已占去房间的大半，榻上有几个软垫，也是破旧不堪。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (91, 'city', 'city/guozi', '国子监', '这里是国子监的正堂，也就是秀才们平时上课的地方。高高低低的桌子排了两溜。东边的一排窗子都开着，把屋中照的通亮。正面一桌一椅，上有文房四宝。一位老先生正闭目养神。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (92, 'city', 'city/guozijian', '国子监大院', '国子监是国家培养高级人才的地方。唐朝的学风很浓，在这里不时可以看到三三两两的学生模样的人大声争辩着什么问题，还有一些老先生门蹙着眉头匆匆走过，象是在思考着什么问题。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (93, 'city', 'city/huashengsi', '化生寺', '化生寺是长安城里规模最大的一家丛林了。整日里香烟袅绕，颂经声不绝于耳。来这里上香还愿的善男信女也特别多，若到了皇道吉日，更是人山人海。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (94, 'city', 'city/jicundian', '钱庄地下室', '一间戒备森严的地下室，专门提供寄存服务。你可以在这里寄存(jicun)物品，价格公道，不论物品贵贱，一律每小时白银一两。若逾期不取(qu)，物品没收后以每样纹银十两的低价公开出售(pick box)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (95, 'city', 'city/jiuguan', '小酒馆', '小酒馆不大，屋中零乱的摆了几张方桌，几条长凳。小柜台上摆了些酒坛，所卖也不过是些花生米，老白干之类。累了一天的苦力人总爱凑到一起喝几杯，吹吹牛，消磨时光。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (96, 'city', 'city/kezhan', '南城客栈', '这家客栈紧靠长安城中心，所以生意非常兴隆。兼之价钱低廉，更是成了外地游客落脚的首选。露天摆了七八张桌子，三教九流人等在此进进出出，络绎不绝，几个跑堂的小二来来回回招待着四方来客。二楼上是雅厅，后面是客房。', '0', 'normal', 1, 1, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (97, 'city', 'city/liangdian', '粮仓', '这是一家生意兴隆的粮店。丰老板坐在柜台后面笑容可鞠地接待着客人。活计们在一边忙忙碌碌地工作着。如果你身无分文，你还可以在这里向丰老板打一些零工，以赚一些钱。粮店的墙上贴着一张破旧的告示(gaoshi)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (98, 'city', 'city/maohuo', '老孙皮货店', '这是长安的一家皮货店，专卖各式各样的皮货。据说老孙自开店以来很少卖出什么真正的皮货，倒是传闻他总是零星地高价出售一些五颜六色的祖传猴毛。店内正堂挂有一满是尘土的细字长匾(bian)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (99, 'city', 'city/minju1', '民居', '这是一户长安城里普普通通的民宅，小夫妇俩朴实勤劳，因此，家境虽然说不上富裕，但也丰衣足食。屋中并没有什么好的摆设，木桌上的玻璃瓶中插了几朵野花。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (100, 'city', 'city/minju2', '民居', '这户民宅从结构上看还是相当不错的，显示出这户人家先前似乎曾经阔过。不知从哪一辈起家道开始衰落了，这座房子也随之年久失修。现在这户人家的两个儿子更是整日里游手好闲，不务正业。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (101, 'city', 'city/minju3', '民居', '这栋房子里象是很久没有人居住了，墙脚屋檐下到处都是灰。还经常可以看到肥肥的老鼠跑来跑去。院中杂草从生，还可听到几声蛐蛐叫。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (102, 'city', 'city/minju4', '民居', '这户人家在长安城里也算比较富裕的了。男主人常年经商在外，妻子在家主持家务。如同长安城大多数人家一样，屋里供着南海观音和关王爷的神像。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (103, 'city', 'city/piggy-partner', '拱猪房', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (104, 'city', 'city/piggy', '拱猪房', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (105, 'city', 'city/piggy_e', '双人拱猪房（东）', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。一张石桌 (table)周围摆着四个石礅，桌面镶了一块大理石，摸上去极为光滑。四壁挂着长明灯，把屋子照得有如白昼。墙角里烧了一炉不知名的香，似乎颇有提神之效。香炉旁边挂着张告示(gaoshi)，上面写着这里的规矩；桌上有张小纸条(note)，上面草草的记着拱猪成绩。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (106, 'city', 'city/piggy_n', '拱猪北房', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。一张石桌 (table)周围摆着四个石礅，桌面镶了一块大理石，摸上去极为光滑。四壁挂着长明灯，把屋子照得有如白昼。墙角里烧了一炉不知名的香，似乎颇有提神之效。香炉旁边挂着张告示(gaoshi)，上面写着这里的规矩；桌上有张小纸条(note)，上面草草的记着拱猪成绩。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (107, 'city', 'city/piggy_s', '拱猪南房', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。一张石桌 (table)周围摆着四个石礅，桌面镶了一块大理石，摸上去极为光滑。四壁挂着长明灯，把屋子照得有如白昼。墙角里烧了一炉不知名的香，似乎颇有提神之效。香炉旁边挂着张告示(gaoshi)，上面写着这里的规矩；桌上有张小纸条(note)，上面草草的记着拱猪成绩。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (108, 'city', 'city/piggy_two', '拱猪房', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。一张石桌 (table)周围摆着四个石礅，桌面镶了一块大理石，摸上去极为光滑。四壁挂着长明灯，把屋子照得有如白昼。墙角里烧了一炉不知名的香，似乎颇有提神之效。香炉旁边挂着张告示(gaoshi)，上面写着这里的规矩；桌上有张小纸条(note)，上面草草的记着拱猪成绩。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (109, 'city', 'city/piggy_w', '双人拱猪房（西）', '这间房子是专门为了拱猪用而设的，整间屋子都是用不去皮的松树搭成。一张石桌 (table)周围摆着四个石礅，桌面镶了一块大理石，摸上去极为光滑。四壁挂着长明灯，把屋子照得有如白昼。墙角里烧了一炉不知名的香，似乎颇有提神之效。香炉旁边挂着张告示(gaoshi)，上面写着这里的规矩；桌上有张小纸条(note)，上面草草的记着拱猪成绩。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (110, 'city', 'city/qinglong-e1', '青龙大街', '你走在一条宽阔的石板大街上，西面就快到城中心了，可以看到钟楼', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (111, 'city', 'city/qinglong-e2', '青龙大街', '你走在一条宽阔的石板大街上，西面就快到城中心了，可以看到钟楼', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (112, 'city', 'city/qinglong-e3', '青龙大街', '你走在一条宽阔的石板大街上，东边就快要出了城门，远远看到一些', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (113, 'city', 'city/qingxuguan', '清虚观', '清虚观是长安城里着名的一座道观。由于唐朝的皇帝和道教宗祖老子同姓，因此道教被奉为唐朝的国教。但由于佛教的传入，道教的状况已大大不如以前。道观中已没有几个人了，但观内原有的气势还没有变。香案上供着元始天尊、太上老君和灵官道君的神像。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (114, 'city', 'city/recycle', '废品回收中心', '你眼前出现一座硕大的垃圾堆。这里是长安城内最大的废物堆积处，有环保意识的好心玩家，从来不随地乱扔废物，总是把他们扔(drop)到这里来。', '0', 'normal', 1, 1, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (115, 'wiz', 'wiz/rumorcenter', '谣言控制中心', '一间不大的房间，无门无窗，笼罩在一束柔和的灯光下，你却找不到光源在哪里。四周靠墙摆满了各色各样的仪器，上面红红绿绿的指示灯不停的跳动着。正中墙上贴着副对联----若要人不知，除非己莫为，横批是：天网恢恢。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (116, 'city', 'city/sanhua-mishi', '三花堂密室', '一间阴暗的密室，充满了血腥气。三花堂重金招募天下杀手，只要肯出钱，自有人为你效命。不知有多少秘密交易都是在这里完成的。墙上贴了一张破纸(paper)，看得出颇有些时日了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (117, 'city', 'city/sanhua', '三花堂', '三花堂是城中名声恶劣的一个帮会，堂中的人大多是些亡命之徒，烧杀抢劫，欺压百姓，无恶不做。而官府却很难抓到把柄而将其除之。正中有三座虎皮大椅，是三位堂主坐的，旁边立了几个面目凶恶的打手。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (118, 'city', 'city/shaizi-room', '骰子房', '屋中间摆着一张看起来相当结实的大长条桌(table)，四周围了十几把靠背木椅。北面墙上有一块牌子(paizi)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (119, 'city', 'city/sleep', '客店睡房', '客栈的一间睡房，房间干干净净，一排大床，供客人们休息睡觉。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (120, 'city', 'city/tianjiantai', '天监台', '这里便是长安城钦天监台，朝廷每年的祭天仪式都在这里举行。中央广场上画着八卦图形，周围还摆这一些施法时用的器具．天监台的总管是正先生袁天罡，总可在这里看到他的身影。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (121, 'city', 'city/wuguan', '长安武馆', '你现在正站在一个长安武馆的教练场中，地上铺着黄色的细砂，一群弟子正在这里努力地操练着。东边是武馆的内堂，往北则是观礼台。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (122, 'city', 'city/wuguanzhong', '长安武馆', '长安武馆的内堂，一切都安安静静，屋里没有点烛，什么也看不清楚。隐约看到两排长椅，正面墙上挂一大旗(qi)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (123, 'city', 'city/xiemao', '鞋帽店', '这里的东西都相当不错，城里的太太小姐多来这里买衣服。逢年过节来光顾的人就更多了。屋中横放一张七尺多长的柜台，柜台后的架子上是一匹匹的布料和成衣。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (124, 'city', 'city/xifuhui', '喜福会', '这里正在举行一个喜宴，堂内张灯结彩，台上高点红烛，一些歌女舞娘正随乐而舞，四五个小伙计麻利的上菜送酒。周围坐满了前来祝贺的客人，热闹非凡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (125, 'city', 'city/ximen', '长安城西门', '这里是长安城的西门。东面就到了城中，远望人山人海，往来行人车流不绝。西面一条大路通向远方。城门下有一些执勤的兵士。时下虽已天下太平，但一干兵将还是英姿勃勃，警惕的盯着往来人士。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (126, 'city', 'city/xuanwu-n1', '玄武大街', '这里的路相当的宽，能容好几匹马车并行，长长的道路通向北方。远远的能看到皇宫的朝阳门。西面是天监台，东边是国子监。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (127, 'city', 'city/yaopu', '回春药铺', '这是长安城一家老字号的药铺，相传原来的老板是皇宫中的御医，手段可知一二。药铺中的摆设也十分考究，桌椅被勤快的伙计擦的干干净净。墙上挂满了别人送来的谢匾。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (128, 'city', 'city/zahuopu', '吉祥杂货铺', '不知为什么西城虽大，却只有这一间杂货铺。所以每天人来人往，也挺热闹。这里无论是油盐酱醋，还是大米白面，样样齐全。屋里打扫的也十分干净，魏老板在和几位客人说说笑笑。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (129, 'city', 'city/zhuque-s1', '朱雀大街', '朱雀大街上商家众多，大大小小的店铺比邻而立，看起来是相当的豪华富足。宽阔的石板路直通南北，向北通到皇宫的朝阳门，向南可遥望到青青的终南山。路东是家大的客栈，来往旅人不绝，西边是家当铺，出出入入的人有喜有忧。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (130, 'city', 'city/zhuque-s2', '朱雀大街', '朱雀大街上商家众多，大大小小的店铺比邻而立，看起来是相当的豪华富足。宽阔的石板路直通南北，向北通到皇宫的朝阳门，向南可遥望到青青的终南山。西边是长安乐坊，传出阵阵丝竹管乐与欢笑，乃是长安城中第一热闹所在。东边是家老字号的药铺。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (131, 'city', 'city/zhuque-s3', '朱雀大街', '朱雀大街上商家众多，大大小小的店铺比邻而立，看起来是相当的豪华富足。宽阔的石板路直通南北，向北通到皇宫的朝阳门，向南可遥望到青青的终南山。西边是家毛货店，东边是个鞋帽店。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (132, 'city', 'city/zhuque-s4', '朱雀大街', '朱雀大街上商家众多，大大小小的店铺比邻而立，看起来是相当的豪华富足。宽阔的石板路直通南北，向北通到皇宫的朝阳门，向南可遥望到青青的终南山。西边一条小路灰蒙蒙的，东边通向望南街。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (133, 'city', 'city/misc/kantai', '观礼台', '观礼台由平坦宽适的红木一级级搭成，地下铺着花纹虎皮和金钱豹皮。台上放着一排排猩红绒面太师椅，可以让贵宾们比较舒适地观看比赛。参赛选手可以在这里查看自己的战绩、排行榜，或者接受挑战。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (134, 'city', 'city/misc/leitai', '擂台', '		八  仙  过  海\r\n		各  显  神  通\r\n		\r\n		', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (135, 'city', 'city/misc/scorekeeper', 'scorekeeper', '一名威风凛凛的武将，专门负责维持会场秩序。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (136, 'city', 'city/misc/scoresheet', 'scoresheet', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (191, 'cloud', 'cloud/cloud0', '云端', '你站在云端，向四周望去，四面是一望无际的云海，头顶是碧蓝的天空。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
