INSERT INTO `rooms` VALUES (232, 'cloud', 'cloud/cloud6', '云端', '你站在云端，向四周望去，四面是一望无际的云海，头顶是碧蓝的天空。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (233, 'cloud', 'cloud/cloud67', '云端', '你站在云端，向四周望去，四面是一望无际的云海，头顶是碧蓝的天空。向下望去，只见一片青翠的绿色，偶尔有一些细细的白线贯穿其中。一只小黄莺悄悄地从云丛中探出头来，很惊讶地看着你。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (234, 'cloud', 'cloud/cloud7', '云端', '你站在云端，向四周望去，四面是一望无际的云海，头顶是碧蓝的天空。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (235, 'death', 'death/bidouya', '壁斗崖', '北面是奈何桥，桥后一座险峰，吹来阵阵腥风。南边是建在山中一座孤城，传来凄凄哭声。左右俱是深涧万丈，略有闪乎就会沦如万劫不复之地而永无超生之时。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (236, 'death', 'death/block', '鸿蒙之外', '诗曰：\r\n\r\n	混沌未分天地乱，茫茫渺渺无人见。\r\n	自从盘古破鸿蒙，开辟从兹清浊辨。\r\n	\r\n盘古开天，万物纷华。可惜你形神俱灭，已是渺茫鸿蒙之外，无存天地之间了。趁着一点灵光未灭，赶紧投胎(suicide/reborn)吧。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (237, 'death', 'death/cuiyun', '翠云宫', '这里便是主管阴曹地府，天下鬼魂的地藏王菩萨的行宫。堂上并没有什么华贵的装饰，奇怪的是左右各放了八个白色的石环，每个都有半扇门板那么大。正中一个铁桌，桌上摆着文具，一个青竹小筒内装着法牌令箭。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (238, 'death', 'death/emptyroom', '背阴山后', '这里是阴司背阴山下，周围一片荒凉，不见草木，一片寂静中只有阴风呼呼地刮着。山脚下淡发红光鬼焰，传说中的阴司十八层地狱就在那里。从没有人从那里活着出去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (239, 'death', 'death/new-out6', '阴阳界', '隐约北方现出一座黑色城楼，光线太暗，看不大清楚。许多亡魂正哭哭啼啼地列队前进，因为一进鬼门关就无法再回阳间了。周围尺高的野草随风摇摆，草中发出呼呼的风声。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (240, 'death', 'death/gateway', '酆都城门', '你现在来到一座黑色城楼之前，城楼上刻着三个大字：酆都城。往北走进城楼只见一片黑漆漆的，只有少许暗红色的火光若隐若现地闪烁着。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (241, 'death', 'death/guidaomen', '超生贵道门', '这里边是阴间通往阳间的唯一出口－贵道门。若是有冤死鬼投胎，就由此出阴间。南方有一座大牌坊耸立，牌坊的另一面什么也看不到。大概要出去(out)才能看到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (242, 'death', 'death/huang', '荒郊草野', '周围一下什么也看不清了，灰蒙蒙的一片。却能听道一些急匆匆的脚步声擦身而过。隐约脚下有条道路，也不知是通向什么地方。北边一座大山，山后隐隐看到火光。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (243, 'death', 'death/huangwai', '背阴小道', '这里是一条陡峭的小路，向上是背阴山，南边一座小桥，就是令人胆颤的奈何桥。能听到桥下滚滚水声，也能听到鬼狼凄叫。几个桥梁使者手握皮鞭，正驱敢着一些鬼怪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (244, 'death', 'death/inn1', '小店', '你一进来就发现屋里异常的温暖，墙角壁炉里微弱的火光将你的影子投射在对面的墙上。几个人影(shadows)围在炉旁不知在讨论些什么。屋内有几张木桌，椅，墙上挂了几幅字画，一切看来非常的详和宁静，你几乎忘了自己身在何处。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (245, 'death', 'death/inn2', '黑店', '屋里相当冷清，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。墙上(wall)刻着一些潦草的字体，墙角的一盏灯笼挣扎似地发出一阵阵微弱的光芒，也始得那些字看来格外的诡异。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (246, 'death', 'death/naiheqiao', '奈何桥', '这是一座仅数寸之宽，数长之长的石桥。上有寒风滚滚，下是血浪滔滔。桥上左右无扶手，险峻之路如同匹练搭长江，桥下之水阴气逼人，腥风扑鼻。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (247, 'death', 'death/new-jimie', '寂灭司', '寂灭司内寒气森森，堂周是青布围幔，上面用金银丝线绣着些奇怪的图案。堂前两侧阴兵分列，气势汹汹。堂上一张拱木案，上面摆放了些文书。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (248, 'death', 'death/new-lunhui', '轮回司', '轮回司内寒气森森，堂周是青布围幔，上面用金银丝线绣着些奇怪的图案。堂前两侧阴兵分列，气势汹汹。堂上一张拱木案，上面摆放了些文书。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (249, 'death', 'death/new-out1', '荒郊草野', '周围什么也没有，看不到一个人影，听到的只是呜呜的风声，就象有无数的野鬼在你耳边狂啸。尺高的野草随风摇摆，草中发出呼呼的声音，象是有人在里面穿行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (250, 'death', 'death/new-out2', '荒郊草野', '周围什么也没有，看不到一个人影，听到的只是呜呜的风声，就象有无数的野鬼在你耳边狂啸。尺高的野草随风摇摆，草中发出呼呼的声音，象是有人在里面穿行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
