INSERT INTO `rooms` VALUES (253, 'death', 'death/new-out5', '荒郊草野', '周围什么也没有，看不到一个人影，听到的只是呜呜的风声，就象有无数的野鬼在你耳边狂啸。尺高的野草随风摇摆，草中发出呼呼的声音，象是有人在里面穿行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (254, 'death', 'death/gate', '荒郊草野', '隐约北方现出一座黑色城楼，城楼上有一幅金匾，上面刻着“幽冥界”三个大字。城楼下城门紧闭，黑漆漆地什么也看不清楚。路边一个破木牌直直地指向北方，周围只有少许暗红色的火光若隐若现地闪烁着。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (255, 'death', 'death/new-out7', '荒郊草野', '周围什么也没有，看不到一个人影，听到的只是呜呜的风声，就象有无数的野鬼在你耳边狂啸。尺高的野草随风摇摆，草中发出呼呼的声音，象是有人在里面穿行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (256, 'death', 'death/new-out8', '荒郊草野', '周围什么也没有，看不到一个人影，听到的只是呜呜的风声，就象有无数的野鬼在你耳边狂啸。尺高的野草随风摇摆，草中发出呼呼的声音，象是有人在里面穿行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (257, 'death', 'death/new-sifang1', '司房', '房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (258, 'death', 'death/new-sifang2', '司房', '房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (259, 'death', 'death/new-sifang3', '司房', '房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (260, 'death', 'death/new-sifang4', '司房', '房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (261, 'death', 'death/new-walk1', '幽司', '这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (262, 'death', 'death/new-walk2', '奉祭场', '奉祭场中有一四方高台，台上刻有日月星辰，山川大河的图腾。台上的铜鼎里偶有青烟生起，四周但见磷火阵阵，闪冒银光。四周有一座座的楼阁宫殿，看起来也相当的富丽堂皇，间有几个索命鬼，勾司人走来走去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (263, 'death', 'death/new-walk3', '幽司', '这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (264, 'death', 'death/new-walk4', '幽司', '这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (265, 'death', 'death/new-walk5', '幽司', '这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (266, 'death', 'death/new-wayout', '泗鬼门', '泗鬼门外灰蒙蒙的一片，周围一下什么也看不清了，却能听道一些急匆匆的脚步声擦身而过。隐约脚下有条道路，也不知是通向什么地方。北边一座大山，山后隐隐看到火光。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (267, 'death', 'death/new-yinsi1', '阴司', '阴司内寒气森森，黄土小径连向四方。左右分别有座青砖瓦房，偶尔有些勾司人出入。天色一片阴暗，天际现着血色。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (268, 'death', 'death/new-yinsi2', '阴司', '阴司内寒气森森，黄土小径连向四方。左右分别有座青砖瓦房，偶尔有些勾司人出入。天色一片阴暗，天际现着血色。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (269, 'death', 'death/new-yinyangta', '阴阳塔', '阴阳塔内成拱形，上方一片光明。隐约看到有阴阳二气轮回相转不绝。周围墙上按八方画了八卦之象。空中偶有磷火飘飘，又好象隐隐传来和尚道士做法事时的铃响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (270, 'death', 'death/new-zhaopo', '招魂司', '恍惚间，你来到了招魂司。招魂司内寒气森森，堂周是青布围幔，上面用金银丝线绣着些奇怪的图案。堂前两侧阴兵分列，气势汹汹。堂上一张拱木案，上面摆放了些文书。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (271, 'death', 'death/out', '黑暗之中', '也不知是到了那里，只觉得四周异常狭小．上下左右不过寸余．连翻身都是不可能的．什么也看不到，什么也听不到．空气中有一股腐烂的味道．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (272, 'death', 'death/pingyang', '平阳大路', '这里是一条笔直的大路，南方看起来已是一片光亮，那里便是阴阳相交的贵道门。北面却是阴云笼罩，传来阵阵悲歌的枉死城，咫尺相隔，却有天涯之别。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (273, 'death', 'death/road1', '鬼门大道', '你走在一条阴森森的路上，浓浓的雾环绕在你的四周，好像永远都不会散去似的。往南看去你勉强可以分辨出一个城楼的模样，往北隐约可以看到几盏灯笼，在浓雾中显得格外的诡异。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (274, 'death', 'death/road2', '鬼门大道', '你走在一条阴森森的路上, 浓浓的雾环绕在你的四周, 好像永远都不会散去似的. 整条路前后只看到零星的几盏灯笼........', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (275, 'death', 'death/road3', '黑暗之中', '也不知是到了那里，只觉得四周异常狭小．上下左右不过寸余．连翻身都是不可能的．什么也看不到，什么也听不到．空气中有一股腐烂的味道．往北看，似乎有间房子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (276, 'death', 'death/room1', '轮转殿', '这里便是阴间地府十王之轮转王的宫殿．平时若是无事，轮转王便会在殿上处理一些杂务．殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的的青烟，一个青衣童子侍立于后．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (277, 'death', 'death/room2', '卞城殿', '这里便是阴间地府十王之卞城王的宫殿．平时若是无事，卞城王便会在殿上处理一些杂务．殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的的青烟，一个青衣童子侍立于后．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (278, 'death', 'death/room3', '都市殿', '这里便是阴间地府十王之都市王的宫殿．平时若是无事，都市王便会在殿上处理一些杂务．殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的的青烟，一个青衣童子侍立于后．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
