INSERT INTO `rooms` VALUES (285, 'death', 'death/roomout', '幽司', '向东看去是一片荒凉，远处是一座黑山，山上笼着浓浓的黑气。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (286, 'death', 'death/sifang', '司房', '房中摆的是一排排的架子，上面分门别类的摆放着一卷卷的文书。这里便是阴曹地府的司房，天下芸芸众生的生死都在这里记录。偶尔几个小官出入，翻开书卷查着什么。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (287, 'death', 'death/test', '超生贵道门', '这里边是阴间通往阳间的唯一出口－贵道门。若是有冤死鬼投胎，就由此出阴间。南方有一座大牌坊耸立，牌坊的另一面什么也看不到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (288, 'death', 'death/walk', '荒郊草野', '周围什么也没有，看不到一个人影，听到的只是呜呜的风声，', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (289, 'death', 'death/walk1', '幽司', '这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
