INSERT INTO `rooms` VALUES (294, 'death', 'death/walk6', '幽司', '这是一条长长的厢廊，没有什么人走动。周围也没有什么动静，一切都是静悄悄的。北面有一座青紫砖石的宫殿，笼在一股青烟之中。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (295, 'death', 'death/walk7', '阎罗大堂', '这里便是名闻天下，令人提起心惊胆寒的阎罗地府。人死后都会', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (296, 'death', 'death/zhengtang', '阎罗宝殿', '这里便是名闻天下，令人提起心惊胆寒的阎罗地府。人死后都会在这里受到应有的处置。正前一张大桌，后面坐着阎罗王，旁边立着崔判官。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
