INSERT INTO `rooms` VALUES (315, 'dntg', 'dntg/bmw/gate', '御马监大门', '天宫的御马监虽不甚大，却也小有气魄。正中间一块蓝匾(bian)上书几个大字，门前两个监官来回巡游，偶尔可以听到监内天马雄壮的嘶鸣声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (316, 'dntg', 'dntg/bmw/hgj1', '护国街', '在这里有天宫的重兵把守，这条街直通天宫兵营，那里驻扎着几十万天兵。兵营旁边是饲养天马的御马间。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
