INSERT INTO `rooms` VALUES (320, 'dntg', 'dntg/bmw/hgj5', '护国街', '在这里有天宫的重兵把守，这条街直通天宫兵营，那里驻扎着几十万天兵。兵营旁边是饲养天马的御马间。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (321, 'dntg', 'dntg/bmw/hgj6', '护国街', '在这里有天宫的重兵把守，这条街直通天宫兵营，那里驻扎着几十万天兵。兵营旁边是饲养天马的御马间。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (322, 'dntg', 'dntg/bmw/majiu1', '马厩', '厩中养着千匹战马，每匹都是日行千里，渡水登山，如履平地之神驹。一个个，嘶风逐电，攒蹄不息。令有众多小马驹，虽未长成，却也是神骏异常。几个力士昼夜不眠，滋养马匹。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (323, 'dntg', 'dntg/bmw/majiu2', '马厩', '厩中养着千匹战马，每匹都是日行千里，渡水登山，如履平地之神驹。一个个，嘶风逐电，攒蹄不息。令有众多小马驹，虽未长成，却也是神骏异常。几个力士昼夜不眠，滋养马匹。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (324, 'dntg', 'dntg/bmw/yinyanting', '饮宴厅', '一间小屋，众监官常在此安排酒席，饮酒叙话。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (325, 'dntg', 'dntg/bmw/zhanyaotai', '斩妖台', '玉皇封托塔李天王为五界降魔大元帅，给了他先斩后奏的宏愿。四方的斩妖台正中立一五尺多高雕符篆玉柱，四方神兵守护，端地是杀气腾腾。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (326, 'dntg', 'dntg/bmw/zhengting', '正厅', '小小的正厅中大大小小的官员都在繁忙的工作着，中间一张大大的公案。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (327, 'dntg', 'dntg/bmw/zoulang', '走廊', '一条宽敞的走廊，足可供五匹马并排行走。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (329, 'dntg', 'dntg/donghai/haidimigong', '海底迷宫', '这里水色变的浑浊起来，周围已看不大清楚了。偶有暗流袭来，卷起阵阵的泥流。四处长着些高高的海草，密密麻麻把头上遮的一丝光芒也没有了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (330, 'dntg', 'dntg/donghai/maze1', '海底迷宫', '海水又变的清澈了，但你已经很难找到方向了。 四周的景物好象都一样，要是没人引路的话看来很难出去了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
