INSERT INTO `rooms` VALUES (348, 'dntg', 'dntg/hell/hell_sleep', 'hell_sleep', '    查\" . $me->query(\"name\") .\n            \"阳寿已尽，着令黑白无常将其魂魄勾拿归案。\\n\\n\" .\n            \"                            \" . $name[$wang1] . \"  谕\\n\\n\\n', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
