INSERT INTO `rooms` VALUES (351, 'dntg', 'dntg/hgs/aolai', '傲来国', '东胜神洲海边一小国。傲来国西临大海，东靠花果山，只是在其间一块狭窄的平原地带上建有一座城池。一条大路直通南方，路上行人也是匆匆而过。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (352, 'dntg', 'dntg/hgs/aolaifighting', '演武场入口', '在傲来国演武场的入口，站立着几个威武的禁军教头，守卫着这里。里面不时传来雄壮的号角声。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (353, 'dntg', 'dntg/hgs/bank', '张家钱庄', '张家钱庄张万宝乃是城中首富，和许多王孙公子也很有交情。由于其经营有方，门路又广，钱庄的生意也是不错。正中横摆一张七尺柜台，台前有个小牌子(paizi)。后面站着位精明的老先生。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (354, 'dntg', 'dntg/hgs/bingqiku', '兵器库', '这里是傲来国的兵器库，里面各种兵器(bingqi)：刀、枪、剑、戟、斧、钺、毛、镰、鞭、钯、挝、锏、弓、弩、叉、矛，件件俱备。整整齐齐的堆放着，几个威武的武士在这里保守着。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (355, 'dntg', 'dntg/hgs/cave', '水帘洞', '　　乃是一座石房。房内有石窝、石灶、石碗、石盆、石床、石凳。\n中间一块石碣(stone)。但见：\n\n　　刮风有处躲，下雨好存身。霜雪全无惧，雷声永不闻。\n　　烟霞常照耀，祥瑞每蒸熏。松竹年年秀，奇花日日新。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (356, 'dntg', 'dntg/hgs/center', '傲云广场', '这里便是傲来国的城中心傲云广场，几条宽广的大路由此延伸向四面八方。可看到四周有各地的行人来来往往，一派繁华景象。地上是青砖铺就，后有一个高台，台上竖着根旗杆(qigan)。时常有艺人在场间空地上表演。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (357, 'dntg', 'dntg/hgs/cuixiang', '翠香楼', '这里就是傲来国最有名的饭馆，是早年一大唐来的富商所开，出售的都是长安府口味的佳肴。传说当时宰相尝后赞不绝口，乃赠翠香二字。在这可看到各处来的游人，也可打听到天下发生的大事。二楼雅座里正大摆宴席，不知是那家有了喜事。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (358, 'dntg', 'dntg/hgs/dongnei', '水帘洞内', '这里便是花果山水帘洞的内堂，四周锅碗瓢盆样样俱全。正中一张虎皮椅子，正是供水帘洞主休息的。', '0', 'normal', 1, 0, 0, 0, 0, '{\"valid_leave\": {\"west\": {\"message\": \"混世魔王冲着你冷笑：想走？没那么容易！\", \"npc_name\": \"混世魔王\", \"condition\": \"npc_exists\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (359, 'dntg', 'dntg/hgs/east1', '东苑街', '东苑街上没有什么商家，往来行人也不多。北边是一家大的武馆，里面不时传出练武发出的声音。一扇朱红的铜钉门大开，向里也看到几重院落。南边是个书院，看起来十分地干净。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (360, 'dntg', 'dntg/hgs/east2', '东苑街', '这里已没有什么行人了，周围散居着几十家平民。房屋俱是白墙青瓦，看起来十分的爽亮。有些人家还在屋前开地种了些瓜果蔬菜，圈养些小鸡小鸭。几个孩子正相逐游戏。偶尔微风卷起些落叶，似蝴蝶般飘舞。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (361, 'dntg', 'dntg/hgs/entrance', '仙石', '这里是花果山腰的一块平地。一道瀑布从山顶飞流直下，泻入一眼深潭，当真是：\"一派白虹起，千寻雪浪飞\"。瀑布边上有一块大石头，相传为天地灵气所化。不知是谁在上面刻了一首诗：\n\n　　　　混沌未分天地乱，茫茫渺渺无人见。\n　　　　自从盘古破鸿蒙，开辟从兹清浊辨。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (362, 'dntg', 'dntg/hgs/fight_room', '傲来国演武场', '傲来国演武场，文官武将，各穿锦衣；帐下偏裨将校，都披银铠。分两行。左右军士，皆全装惯带，持戈执戟而立。中间一行行兵士威风凛凛的穿行于其中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (363, 'dntg', 'dntg/hgs/flowerfruit', '花果山', '此山乃十洲之祖脉，三岛之来龙，自开清浊而立，鸿蒙判后而成。真个好山！有词赋为证。赋曰：\n\n　　　　势镇汪洋，潮涌银山鱼入穴；\n　　　　威宁瑶海，波翻雪浪蜃离渊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (364, 'dntg', 'dntg/hgs/fuhai', '覆海大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (365, 'dntg', 'dntg/hgs/guchang', '谷场', '这是靠近城边的一个打谷场，场上很平并压的很硬。边上高高低低有几个草堆，几棵大柳树下有几条野狗在打瞌睡。场中有几只老母鸡在啄谷粒吃。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (366, 'dntg', 'dntg/hgs/houshan1', '后山小路', '这是通往后山的一条小路。只能小心翼翼地在树丛中钻行，一个不注意就会碰得头破血流。几只猴子围着你跳来跳去，一边吱吱乱叫，一边冲你扔野果。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (367, 'dntg', 'dntg/hgs/houshan2', '后山树丛', '你顶着满头满脸的野果汁穿行在树丛中，把一群猴子乐得吱吱乱叫。它们显然不太同情你的处境，还在不停地拿各种各样的野果砸你。南面是一条下山的小路，北面透过树丛可以看到一小块平地。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (368, 'dntg', 'dntg/hgs/houshan3', '后山', '花果山后山中的一小块平地。要下山得穿过南面一片树丛。东面面是一片桃树林，黄澄澄的猕猴桃显然已经熟透，一阵果香飘来，你口水都流了出来。不过桃林边上有两只大马猴，满怀敌意地注视着你。', '1', 'normal', 1, 0, 0, 0, 0, '{\"valid_leave\": {\"east\": {\"message\": \"{names}吱吱哇哇乱叫，不让你过去。\", \"npc_list\": [{\"npc_id\": \"liuyuanshuai\", \"npc_name\": \"流元帅\", \"display_name\": \"流元帅\"}, {\"npc_id\": \"mayuanshuai\", \"npc_name\": \"马元帅\", \"display_name\": \"马元帅\"}], \"condition\": \"multi_npc\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (369, 'dntg', 'dntg/hgs/houshan4', '桃树林', '桃树林中。黄澄澄的猕猴桃显然已经熟透，已经有一些从树上掉了下来。一阵果香飘来，你口水都流了出来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (370, 'dntg', 'dntg/hgs/huntian', '混天大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (371, 'dntg', 'dntg/hgs/huofang', '仓库', '这里不知是那家商号的仓库，周围密密麻麻堆放着些箱子。仓库中做工的人很多，大多是光着脚的青年汉子。一趟又一趟的搬运着货物。墙上贴着张大报，大意是缺人手，要请人来工作(work)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (372, 'dntg', 'dntg/hgs/inner_shuiliandong', '水帘洞内部', '这里是水帘洞的深处。洞内一片黑暗，石缝内依稀可以看见什么东西黑乎乎的。你试图将石缝扩大(expand)一些，从中取出那件东西。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (373, 'dntg', 'dntg/hgs/ironbridge', '铁板桥', '　　瀑布泉中原来是座铁板桥。\n　　桥下之水，冲贯于石窍之间，倒挂流出去，遮闭了桥门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (374, 'dntg', 'dntg/hgs/jiaojunchang', '花果山教军场', '一片开阔的草地，被猴子们当作他们的教军场，只见其中一个严肃的通背猿指挥着一列列，一排派走过来的猴子兵。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (375, 'dntg', 'dntg/hgs/north1', '北菀街', '这是傲来国中最大的一条街，宽有数长。城中的富豪商家多聚于此，银庄商号，饭馆客栈不断。南边是城中心，偶见车马驰过。东边则是城中最有名的翠香楼，飘出的香味不禁让人大流口水。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (376, 'dntg', 'dntg/hgs/north2', '北菀街', '这是傲来国中最大的一条街，宽有数丈。城中的富豪商家多聚于此，银庄商号，饭馆客栈不断。往来人流拥挤，其中也不乏奇装怪饰的外人。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (377, 'dntg', 'dntg/hgs/northgate', '傲来国北城门', '一座高大的城墙耸立于前者，城上不断有守城的官兵走过。城中往往来来的人很多，傲来国人风淳朴，民富而知足，到处也都是一幅喜气洋洋的景色。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (378, 'dntg', 'dntg/hgs/pingtian', '平天大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (379, 'dntg', 'dntg/hgs/pownshop', '吴家当铺', '当铺内阴森森的，一股霉味让人想吐。一张长长的柜台后面坐着一个戴着老花镜的老人，恶狠狠地打量着你。柜台上面摆着一块发黄的破木牌，上面写着「公道估价」四个歪歪斜斜的字。柜台后放着几个布满灰尘的大木架，上面堆满了形形色色的杂物。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (380, 'dntg', 'dntg/hgs/pubu', '瀑布前', '只见那股涧水奔流，真个似滚瓜涌溅。顺涧爬山，直至源流之处，乃是一股瀑布飞泉。但见那：\n\n　　一派白虹起，千寻雪浪飞；海风吹不断，江月照还依。\n　　冷气分青嶂，馀流润翠微；潺名瀑布，真似挂帘帷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (381, 'dntg', 'dntg/hgs/pubu1', '瀑布中', '……你似乎什么也看不清楚，只觉得四周涧水奔流，难以探到前方的出路……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (382, 'dntg', 'dntg/hgs/pubu2', '瀑布中', '……你似乎什么也看不清楚，只觉得四周涧水奔流，难以探到前方的出路……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (383, 'dntg', 'dntg/hgs/pubu3', '瀑布中', '……你似乎什么也看不清楚，只觉得四周涧水奔流，难以探到前方的出路……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (384, 'dntg', 'dntg/hgs/pubu4', '瀑布中', '……你似乎什么也看不清楚，只觉得四周涧水奔流，难以探到前方的出路……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (385, 'dntg', 'dntg/hgs/pubu5', '瀑布中', '……你似乎什么也看不清楚，只觉得四周涧水奔流，难以探到前方的出路……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (386, 'dntg', 'dntg/hgs/qitian', '齐天大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (387, 'dntg', 'dntg/hgs/qushen', '驱神大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (388, 'dntg', 'dntg/hgs/room1', '民宅', '这户人家在城里也算比较富裕的了。男主人常年经商在外，妻子在家主持家务。如同大多数人家一样，屋里供着南海观音和关王爷的神像。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (389, 'dntg', 'dntg/hgs/room2', '民宅', '一间小小的民宅，打扫的干干净净。家俱不是很好，最显眼的就只有一长桌，桌上摆着大茶壶。墙边堆着许多竹杆，地下还有些编的半成的竹筐，看来家里人是靠编竹器谋生。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (390, 'dntg', 'dntg/hgs/school1', '东方武馆大门', '你现在正站在一间大宅院的入口，两只巨大的石狮镇守在大门的两侧，一阵阵吆喝与刀剑碰撞的声音从院子中传来，通过大门往东可以望见许多身穿灰衣的汉子正在操练。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (391, 'dntg', 'dntg/hgs/school2', '武馆教练场', '这里是方方正正的一个教练场，地上铺着黄色的细砂，许多弟子正在在这里努力地操练着。东边一间不起眼的小屋，柴门半掩。往北则是武馆师父们休息的大厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (392, 'dntg', 'dntg/hgs/schoolbook', '书房', '书房中整理得相当干净，靠窗摆着一张大的红木书桌，上面还铺着红色的缎布。桌上摆着些书，还有些文房四宝。一个小花瓶里还插着些采来的小花。靠墙一个大书架上摆满了书籍。南边可以看到天井及一些来回走动的家人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (393, 'dntg', 'dntg/hgs/schoolhall', '武馆大厅', '这里就是东方武馆的大厅，左右各摆四张檀木太师椅，是为来客准备的。正中是东方馆主的座位。东边走廊通向内室，里面住的是武馆弟子和家人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (394, 'dntg', 'dntg/hgs/schoolin', '天井', '这里是武馆内院的天井，头顶仅看到一丈见方的天空。西边是武馆的大厅，时常在那里招待客人。北边是几间家人住的房子，南边是招待客人的厢房，天井中种了许多奇花异草。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (395, 'dntg', 'dntg/hgs/schoolrest', '客房', '这里是一间布置得相当雅致的厢房，从窗子可以看到北边的天井跟庭园中各式各样的奇花异草。厢房里有几张大木床，是来客住的，北边就回到天井。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (396, 'dntg', 'dntg/hgs/shanlu1', '山路', '一条不甚宽广的山路，四处芳草鲜美，落英缤纷。周围的树丛中偶尔撺出几只猴子，在这里跳来跳去，路边的小草(grass)随风飘舞。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (397, 'dntg', 'dntg/hgs/shanlu2', '山路', '一条不甚宽广的山路，四处芳草鲜美，落英缤纷。周围的树丛中偶尔撺出几只猴子，在这里跳来跳去，路边的小草(grass)随风飘舞。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (398, 'dntg', 'dntg/hgs/shanya', '山崖', '沿着秀丽的花果山一路走来，只感到这里的一草一木都令人耳目一新。由此，上山的路通向一座瀑布，西面是花果山的猴子们的叫军场，猴子们蹿来跳去，不时传来雄壮的号角声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (399, 'dntg', 'dntg/hgs/shichuang', '石床', '一张长长的石床。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (400, 'dntg', 'dntg/hgs/shifang', '石房', '一座宽大的石房，房内有石窝、石灶、石碗、石盆、石床、石凳，各种家当。好一座天造地设的安身之所。正中间插着一杆大旗(flag)，后面还有一张石床(bed)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (401, 'dntg', 'dntg/hgs/shiwu', '石屋', '屋内光线暗淡，隐隐看到四周墙上画着些八卦之类的图形。家里的是城内有名的阿七婆，凡有求魂告祷，看风水，算黄道吉日的事总少不了她。也听说她会算命，不知灵不灵。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (402, 'dntg', 'dntg/hgs/shuyuan', '西城书院', '这是傲来国中唯一的书院。傲来本是民风淳朴，虽人人礼谦有，于大唐之文彩天下却不可同提。书院是数年前从中原来的一位秀才所开，城中来学的人也是不少。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (403, 'dntg', 'dntg/hgs/storage', '储藏室', '这是间堆满杂物的储藏室，几个架子上货物都是按类排放。有些棉被衣物，也有些刀枪棍棒。屋里倒是很干净，象是有人经常打扫。西边是练武场。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (404, 'dntg', 'dntg/hgs/tiebanqiao', '铁板桥', '你欠身上桥头，再走再看，却似有人家住处一般，真个好所在。但见那：\n\n　　翠藓堆蓝，白云浮玉，光摇片片烟霞。虚窗静室，滑凳板生花。乳窟龙珠倚挂，萦回满地奇葩。又见那一竿两竿修竹，三点五点梅花。几树青松常带雨，浑然相个人家。\n\n看罢多时，跳过桥中间，左右观看，只见正当中有一石碣(shi jie)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (405, 'dntg', 'dntg/hgs/tongfeng', '通风大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (406, 'dntg', 'dntg/hgs/tudi', '土地庙', '一座小小的土地庙，庙里供着土地公公和土地婆婆(statue)。供台上摆着些供品香烛，还有些求告平安的文书。庙里很静，听不到什么响动，供台上两支长烛发出淡淡的光线。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (407, 'dntg', 'dntg/hgs/up1', '林间小路', '花果山中的一条林间小路。这里葛藤纠结，古木参天，绝少人行，只有一些猴子在树间荡来荡去。花果山山势雄伟而不险峻，在山间行走并不吃力。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (408, 'dntg', 'dntg/hgs/up2', '林间小路', '花果山中的一条林间小路。这里葛藤纠结，古木参天，绝少人行，只有一些猴子在树间荡来荡去。花果山山势雄伟而不险峻，在山间行走并不吃力。再往上很快就到山腰了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (409, 'dntg', 'dntg/hgs/west1', '西芫街', '西芫街宽广的街道上铺着石板，偶尔马匹驰过，马蹄在石板上发出清脆地嗒嗒声。东边就通到城中心，远远可见宽阔地广场和广场中的大旗及石台。南边是家斋院，是给穷人舍饭的地方。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (410, 'dntg', 'dntg/hgs/west2', '西芫街', '西芫街宽广的街道上铺着石板，偶尔马匹驰过，马蹄在石板上发出清脆地嗒嗒声。东边就通到城中心，远远可见宽阔地广场和广场中的大旗及石台。北边是个小土地庙，南边是家民宅，门口挂着些红布。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (411, 'dntg', 'dntg/hgs/xiaoxi', '小溪', '一条清澈见底的小溪，水流潺潺，在这玩够了就游(swim)回去吧。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (412, 'dntg', 'dntg/hgs/xiaoxiqian', '小溪前', '延着山路一转，一条清澈的小溪出现在你的面前。灿烂的阳光照耀下，小溪中波光闪闪，不时还有几条鱼儿跳出水面，使你真想到溪中游(swim)一翻。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (413, 'dntg', 'dntg/hgs/yishan', '移山大圣宫', '星光灿烂\n\n   千          五\n   秋          洲\n   万          四\n   载          海\n   美          群\n   名          英\n   扬          会', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (414, 'dntg', 'dntg/hgs/zhaiyuan', '斋院', '一个小小的院落，院中不大，却收拾地干干净净。院中散布几张木桌，桌上摆了些碗筷之类。后面台上坐了个老头，台上摆了口大锅及几个茶壶。你要是饿了的话可以向他要(yao)吃的。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (419, 'dntg', 'dntg/laojun/danfang', '丹房', '这里就是太上老君炼丹的所在。屋子正中是一只一人多高的紫色丹炉，看不出是用什么材料做的。炉下烈火熊熊，然而你却感受不到一丝炎热。墙角焚着一炉檀香，一丝若有若无的幽香满室缭绕。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (420, 'dntg', 'dntg/laojun/gate', '兜率宫大门', '这里就是太上老君的住所——兜率宫了。这兜率宫是三十三天之上，经常有各路神仙来这里与太上老君讲经谈道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (421, 'dntg', 'dntg/laojun/hall', '兜率宫', '一间恬淡古雅，高不见顶的宽大宫殿。正中排着张香案，案上放着朱漆托盘，盘内供着几粒刚炼得的九转金丹。楼上是太上老君讲道的朱陵丹台，隐隐传来老君清亮爽朗的声音，但你却找不到上楼的阶梯。西面有一扇竹门，门上画着一个八卦图案，门内就是老君炼丹的丹房。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (422, 'dntg', 'dntg/laojun/laojunlu', '丹房', '这里就是太上老君炼丹的所在。屋子正中是一只一人多高的紫色丹炉，看不出是用什么材料做的。炉下烈火熊熊，然而你却感受不到一丝炎热。墙角焚着一炉檀香，一丝若有若无的幽香满室缭绕。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
