INSERT INTO `rooms` VALUES (443, 'dntg', 'dntg/lijing/juling', 'juling', '托塔李天王帐下先锋大将，膀阔腰圆，力大无穷。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (444, 'dntg', 'dntg/lijing/lijing', 'lijing', '托塔李天王乃是天界元帅，麾下十万天兵天将，法力无边。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (445, 'dntg', 'dntg/lijing/nezha', 'nezha', '一位唇红齿白的美少年。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (446, 'dntg', 'dntg/lijing/starting_place', 'starting_place', '一片开阔的草地，被猴子们当作他们的教军场，只见其中一个严肃的通背猿指挥着一列列，一排排走过来的猴子兵。草地的北侧竖着一根十丈多高的旗杆，上面挂着一面大旗(flag)，在风中飒飒飘舞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (447, 'dntg', 'dntg/lijing/tianbing', 'tianbing', '托塔李天王帐下天兵，膀阔腰圆，力大无穷。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (448, 'dntg', 'dntg/lijing/troops', 'troops', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (450, 'dntg', 'dntg/pantao/climbtree', 'climbtree', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (451, 'dntg', 'dntg/pantao/gate', '蟠桃园园门', '两扇两丈多高的朱漆描金大门虽设而长开，门内是一片郁郁葱葱的桃树林，种着连天上神仙思之都垂涎三尺的千年蟠桃。门前站着一位白发苍苍的土地公公，正笑容可掬地看着你。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (452, 'dntg', 'dntg/pantao/pan1a', '蟠桃园', '蟠桃园内花红叶绿，夭夭灼灼花盈树，颗颗枝枝果压枝。只见是：时开时结千年熟，无夏无冬万载迟，先熟的，酡颜醉脸，还生的，带蒂青皮。好个凝脂肌带绿，映日显丹姿。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
