INSERT INTO `rooms` VALUES (461, 'dntg', 'dntg/pantao/ting1', '黄霞亭', '只见得霞光耀眼瑞气飘飘，亭内仙花盛开香气缭绕。正中放有一方皎玉镶金供桌，上有紫芝瑶草。霞亭由四根盘龙柱高高擎起，周围层层云雾环绕。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
