INSERT INTO `rooms` VALUES (468, 'dntg', 'dntg/pantao/tree', 'tree', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (469, 'dntg', 'dntg/pantao/tree1', '蟠桃树上', '周围枝叶繁茂，遮天闭日，一片碧绿中你隐隐看到几颗红彤彤的蟠桃若隐若现。这里的蟠桃紫纹缃核，九千年一熟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (470, 'dntg', 'dntg/pantao/tree2', '蟠桃树上', '周围枝叶繁茂，遮天闭日，一片碧绿中你隐隐看到几颗红彤彤的蟠桃若隐若现。这里的蟠桃层花甘实，六千年一熟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (471, 'dntg', 'dntg/pantao/tree3', '蟠桃树上', '周围枝叶繁茂，遮天闭日，一片碧绿中你隐隐看到几颗红彤彤的蟠桃若隐若现。这里的蟠桃花微果小，三千年一熟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (477, 'dntg', 'dntg/sky/angrigong', '昂日宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (478, 'dntg', 'dntg/sky/baihudian', '白虎殿', '天宫的一座偏殿，天神进宫面见玉帝之前常在此歇息，只见这里四壁描龙绣凤，气势非凡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (479, 'dntg', 'dntg/sky/baoguangdian', '宝光殿', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (480, 'dntg', 'dntg/sky/beitian', '北天门', '这里是天宫的北门。由四大天王之一的魔礼寿负责保守。比起南天门来，北边可就冷清多了。虽然如此，东天门造的可丝毫不含糊。鲜红的大门上镶着闪闪发光的铜钉，显得威武非凡。大力天丁和众天兵，一丝不苟的巡逻着。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (481, 'dntg', 'dntg/sky/bihuogong', '觜火宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (482, 'dntg', 'dntg/sky/bishagong', '毗沙宫', '毗沙宫中站立着几个庄严的武士，扫视着没一个来往的人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (483, 'dntg', 'dntg/sky/bishuigong', '壁水宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (484, 'dntg', 'dntg/sky/biyuegong', '毕月宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (485, 'dntg', 'dntg/sky/caifengdian', '彩凤殿', '外厢犹可，入内惊人：里壁厢有几条彩羽凌空丹顶凤。明霞幌幌映天光，碧雾蒙蒙遮斗口。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (486, 'dntg', 'dntg/sky/caihongqiao', '彩虹桥', '又有几座长桥，桥上跨着几道七色彩虹。这天上有三十三座天宫，乃遣云宫、毗沙宫、五明宫、太阳宫、花药宫、……一宫宫脊吞金稳兽；又有七十二重宝殿，乃朝会殿、凌虚殿、宝光殿、天王殿、灵官殿、…… 一殿殿柱列玉麒麟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (487, 'dntg', 'dntg/sky/caihongqiao2', '彩虹桥', '又有几座长桥，桥上跨着几道七色彩虹。这天上有三十三座天宫，乃遣云宫、毗沙宫、五明宫、太阳宫、花药宫、……一宫宫脊吞金稳兽；又有七十二重宝殿，乃朝会殿、凌虚殿、宝光殿、天王殿、灵官殿、…… 一殿殿柱列玉麒麟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (488, 'dntg', 'dntg/sky/dadao1', '天宫大道', '一条大道，笔直的伸展出去，直通南天门。道上不时走过几名巡查的天兵，持刀悬剑，威风凛凛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
