INSERT INTO `rooms` VALUES (501, 'dntg', 'dntg/sky/jiashan', '假山', '天宫后院的假山，四季都盛开着鲜花，这里一草一木都显露出帝王风范。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (502, 'dntg', 'dntg/sky/jieyindian', '接引殿', '进了南天门，已经可以看到一座座天宫放着七彩霞光，忽隐忽现于云遮雾绕之中。里壁厢有几根大柱，柱上缠绕着金鳞耀日赤须龙；一座白玉桥弯弯曲曲地向北延伸，东西两边各有一座大殿，也不知是干什么用的，你可以隐约听到东边殿中有喧哗之声，似乎人不少。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
