INSERT INTO `rooms` VALUES (554, 'dntg', 'dntg/sky/tianhe', '天河', '无数星星汇合成了这条宽广的银河，据说这是当年王母娘娘\n用她头上的银簪划出的，在这美丽的银河之畔，不知发生了\n多少动人的故事。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (555, 'dntg', 'dntg/sky/tonglugong', '疃卢宫', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (556, 'dntg', 'dntg/sky/tongmingdian', '通明殿', '入宫的大道继续向前延伸，走不多远就是灵霄宝殿了。在这里隐隐可以看见宝殿雄伟的殿门，和传说中神采飞扬的天神们。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (557, 'dntg', 'dntg/sky/weihuogong', '尾火宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (558, 'dntg', 'dntg/sky/weitugong', '胃土宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (559, 'dntg', 'dntg/sky/weiyuegong', '危月宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (560, 'dntg', 'dntg/sky/xianwudian', '玄武殿', '长梁雕龙，飞檐画凤。里面殿阁高大雄伟，层层叠叠，琉璃瓦白玉掾富丽堂皇。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (561, 'dntg', 'dntg/sky/xingrigong', '星日宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (562, 'dntg', 'dntg/sky/xinyuegong', '心月宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (563, 'dntg', 'dntg/sky/xitian', '西天门', '这里是天宫的东门。由四大天王之一的魔礼海负责保守。比起南天门来，北边可就冷清多了。虽然如此，东天门造的可丝毫不含糊。鲜红的大门上镶着闪闪发光的铜钉，显得威武非凡。大力天丁和众天兵，一丝不苟的巡逻着。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (564, 'dntg', 'dntg/sky/xuanyuantang', '轩辕堂', '一座宽敞明亮的大堂，四通八达，四壁龙飞凤舞，装饰豪华，一队队持刀悬剑的卫士从这里走来走去好不威风．.', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (565, 'dntg', 'dntg/sky/xurigong', '虚日宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (566, 'dntg', 'dntg/sky/yihuogong', '翼火宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (567, 'dntg', 'dntg/sky/yunlue1', '云路', '踏着这条宽敞的天宫云路，脚下飘过朵朵白云，俯视人间农舍中飘起的袅袅炊烟，另人倍感心旷神怡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (568, 'dntg', 'dntg/sky/yunlue2', '云路', '踏着这条宽敞的天宫云路，脚下飘过朵朵白云，俯视人间农舍中飘起的袅袅炊烟，另人倍感心旷神怡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
