INSERT INTO `rooms` VALUES (575, 'dntg', 'dntg/sky/zhangyuegong', '张月宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实\n则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷\n有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落\n脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (576, 'dntg', 'dntg/sky/zhenshuigong', '轸水宫', '这座大殿是专为二十八宿造的。二十八位星官虽为玉帝钦封，实则来至各名山大川，五湖四海。平时并不受玉帝节制，只是天廷有了重大事情才宣召他们上天。二十八宿殿便是他们上天时的落脚休憩之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (577, 'dntg', 'dntg/sky/zhuquedian', '朱雀殿', '<span style=\"color:lightskyblue;\">走入朱雀殿，只见殿外蹲着两个大石狮子，三间兽头大门，正门五间，上面桶瓦泥鳅脊，那门栏窗棱,皆是描龙飞凤，一色水磨群墙，下面白石台矶，凿成西番草花样.</span>左右一望，皆雪白粉墙,<span style=\"color:lightskyblue;\">下面虎皮石,随势砌去，果然气势非凡。门前列坐着几个威风凛凛的护殿官。</span>', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
