INSERT INTO `rooms` VALUES (616, 'dntg', 'dntg/sky/stars/erica', 'erica', '一切都是短暂得没有结束却又要开始。\r\n\r\n一切又都是漫长得没有停止却也不会完成。\r\n\r\n为了发现这个世界上永恒的也许只有失去，发现失去后也只能挥挥手说声再见却永无聚首的瞬间，你便经常惶惑着感到一种突如其来的悲哀。\r\n\r\n任何道路的选择都只能意味着选择其他道路的不再可能。\r\n\r\n你终将孤独。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
