INSERT INTO `rooms` VALUES (624, 'dntg', 'dntg/sky/stars/hero', 'hero', '纪念日:\r\n\r\n-----------\r\n年龄33 : 道行 303.33.3, 最后一战用时33m, 然后和 green 结婚 :)\r\n\r\n年龄46 : 终于修成不堕轮回, 成了老不死 :D\r\n\r\n年龄53 : 不打算继续陷在险恶的江湖中, 整天学学游手好闲(如果还来的话) :P\r\n\r\n-------------\r\n', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (625, 'dntg', 'dntg/sky/stars/ivan', 'ivan', '爱,认真就好\r\n别急着实现那些别人说的\r\n天荒地老', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
