INSERT INTO `rooms` VALUES (629, 'dntg', 'dntg/sky/stars/lisa', 'lisa', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (630, 'dntg', 'dntg/sky/stars/liz', 'liz', '\r\n本人以为天地皆空，人生皆幻，世情嗜欲，悉伐性之斧斤；富贵功名，皆迷心之鸩毒。\r\n\r\n欲寻清幽之谷，依深穴之岩，垒石为门，拔茅为席，澄心净虑。\r\n\r\n吾愿足以！！！', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (631, 'dntg', 'dntg/sky/stars/louis', 'louis', '他是个很随便的人，有好衣服穿，他就穿着;没有好衣服穿，他就穿破的。有好酒好莱，他就猛吃;没有得吃，就算饿三天三夜，他也不在乎。就算饿了三天三夜后，他还是会笑，很少有人看见过他板着脸的时候。　现在他就在笑。他笑得很随便，有时候会皱起鼻子来笑，有时会眯起眼睛来笑，有时候甚至会象小女孩一样，噘起嘴来笑。他的笑容中，绝对看不出有一点儿恶意，更没有那种尖刻的讥诮。所以无论他怎样笑，样子绝不难看。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (632, 'dntg', 'dntg/sky/stars/lovesky', 'lovesky', '\r\n此三天,乃取自子曰:三人行必有我师之意.', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (633, 'dntg', 'dntg/sky/stars/lwq', 'lwq', '\\n$N和$n\\n', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (634, 'dntg', 'dntg/sky/stars/matthew', 'matthew', '\r\n世事如棋  乾坤莫测  笑尽英雄\r\n', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (635, 'dntg', 'dntg/sky/stars/miner', 'miner', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (636, 'dntg', 'dntg/sky/stars/near', 'near', '小道士(Xiao dao)', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (637, 'dntg', 'dntg/sky/stars/sigh', 'sigh', '为期待而绝望 为绝望而期待\r\n绝望是最完美的期待\r\n期待是最漫长的绝望\r\n期待不一定开始\r\n绝望也未必结束\r\n或许召唤只有一声——\r\n最嘹亮的, 恰恰是寂静', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (638, 'dntg', 'dntg/sky/stars/star', 'star', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (639, 'dntg', 'dntg/sky/stars/taiping', 'taiping', '方寸山三星洞第三代弟子\r\n太平世界(Taiping)', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (640, 'dntg', 'dntg/sky/stars/vovo', 'vovo', '蜗蜗浴朝阳，饮晨曦，傲然而立，仰天长吟：\r\n\r\n神龟虽寿，猷有竟时。腾蛇乘雾，终为土灰。\r\n老骥伏枥，志在千里；烈士暮年，壮心不已。\r\n盈缩之期，不但在天；养怡之福，可得永年。\r\n\r\n他迎风傲立船首，望滚滚江水东逝，只觉得天下英雄舍我其谁。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (641, 'dntg', 'dntg/sky/stars/windf', 'windf', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (642, 'dntg', 'dntg/sky/stars/wugeng', 'wugeng', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (643, 'dntg', 'dntg/sky/stars/xqing', 'xqing', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (644, 'dntg', 'dntg/sky/stars/xuexing', 'xuexing', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (645, 'dntg', 'dntg/sky/stars/yihuo', 'yihuo', '二十八位星官之一，正在殿中四处巡游。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (646, 'dntg', 'dntg/sky/stars/yixue', 'yixue', '风雪剑派掌门大师姐 「楚楚剑 -- 楚楚」\r\n风雨纷纷风中闯江湖风雨心相戚剑\r\n系\r\n荡魔剑--小令狐风\r\n天涯剑--浪迹天涯雪\r\n孤星剑--流星蝴蝶剑情\r\n雪原莽莽雪下忆神州雪原映丹心', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (647, 'dntg', 'dntg/sky/stars/youke', 'youke', '\r\n持国天王  掌紫金龙花狐貂　职顺\r\n', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (648, 'dntg', 'dntg/sky/stars/ywl', 'ywl', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (649, 'dntg', 'dntg/sky/stars/ziling', 'ziling', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (665, 'dntg', 'dntg/yaochi/donglang', '瑶池东廊', '瑶池东廊一列玉桌整齐排开，摆满各类仙酒。廊里酒香扑鼻；有几个造酒的仙官，盘糟的力士，领几个运水的道人，烧火的童子，在此酿造玉液琼浆，香醪佳酿。角落里有扇铁门(door)通向贮酒的地窖。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (666, 'dntg', 'dntg/yaochi/gate', '大门', '你眼前出现了一座汉白玉牌坊，上面龙飞凤舞的写着“瑶池”两个金色大字。里面就是王母娘娘用来宴客的瑶池了。旁边站着一个身材魁武，神态伟岸的金甲卫士，两道目光炯炯地审视着你，看得你一阵心虚。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (667, 'dntg', 'dntg/yaochi/jiujiao', '酒窖', '一间密不透风的地窖，放着了一排排酒坛，里面装的就是令天上诸神思之垂涎不已的王母仙酒了。你一走进来，就觉得酒香扑鼻，果然是好酒。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (668, 'dntg', 'dntg/yaochi/jiutan', 'jiutan', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (669, 'dntg', 'dntg/yaochi/wmj1', '王母街', '一条宽敞的大街，笔直的伸展出去。这条街上住的都是天宫最有权势的人，路的尽头，就是蟠桃园。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (670, 'dntg', 'dntg/yaochi/wmj2', '王母街', '一条宽敞的大街，笔直的伸展出去。这条街上住的都是天宫最有权势的人，路的尽头，就是蟠桃园。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (671, 'dntg', 'dntg/yaochi/wmj3', '王母街', '一条宽敞的大街，笔直的伸展出去。这条街上住的都是天宫最有权势的人，路的尽头，就是蟠桃园。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (672, 'dntg', 'dntg/yaochi/wmj4', '王母街', '一条宽敞的大街，笔直的伸展出去。这条街上住的都是天宫最有权势的人，路的尽头，就是蟠桃园。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (673, 'dntg', 'dntg/yaochi/wmj5', '王母街', '一条宽敞的大街，笔直的伸展出去。这条街上住的都是天宫最有权势的人，路的尽头，就是蟠桃园。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (674, 'dntg', 'dntg/yaochi/wmj6', '王母街', '一条宽敞的大街，笔直的伸展出去。这条街上住的都是天宫最有权势的人，路的尽头，就是蟠桃园。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (675, 'dntg', 'dntg/yunlou/gate', '云楼宫门', '云楼宫乃是托塔李天王的住宅，未近宫门已觉兵气森森。门楼上高悬一龙吞漆金匾，上书“托塔天王府”五个大字。门旁兵将盔明铠亮，警惕有神的护卫着府门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (676, 'dntg', 'dntg/yunlou/taizifu', '三太子府', '府中的主人乃是三太子哪吒，御封的三坛海会大将。当初哪吒年闯祸，天王恐有后患欲杀之，哪吒奋而割肉还母，剔骨还父，一点灵魂飘到西方极乐世界，佛以碧藕为骨，荷叶为衣，念动起死回生真言，哪吒遂又得了性命。后降服九十六洞妖魔，端地是神通广大。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (677, 'dntg', 'dntg/yunlou/yongdao', '甬道', '甬道上是青石碎瓦铺地，道旁有四时不谢之仙花异草，遍地芬芳。翠竹林中风带鸟语，色润飘香。周围见迭迭朱阁画楼，逐逐彩雾烟波。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (678, 'dntg', 'dntg/yunlou/yunlou', '云楼殿', '云楼殿乃是托塔天王之公务堂，托塔天王乃是天界元帅，云楼殿实乃是天界之军事中枢。廊下将军天王两旁列，杀气腾腾，堂前一对金烛燃，指点光明。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (679, 'dntg', 'dntg/yunlou/yunloutai', '云楼台', '此乃宫上一小台，远望仙境，见金光万道滚红霞，瑞气千条喷紫烟。远上长桥碧雾蒙，天宫宝殿映云光。当真是天上自来有仙境，不堕人间点污泥。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (680, 'eastway', 'eastway/beilin1', '碑林', '你走进碑林之中，这里荟萃了举世闻名的碑帖，有王羲之，颜真卿，柳公泉，欧阳询，诸遂良所书的碑刻。也有石经，石台孝经，大秦景教流行中国碑等等。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (681, 'eastway', 'eastway/beilin2', '碑林', '你走进碑林之中，这里荟萃了举世闻名的碑帖，有王羲之，颜真卿，柳公泉，欧阳询，诸遂良所书的碑刻。也有石经，石台孝经，大秦景教流行中国碑等等。另还有些石刻，石雕。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (682, 'eastway', 'eastway/bingma', '兵马俑阵', '你来到一个巨大的兵马俑阵中，天高云阔，成千上万个栩栩如生的兵马俑排列成几十路纵队，仿佛正在从四面八方呼啸而来，你不禁被这个宏伟的场面惊倒。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (683, 'eastway', 'eastway/ciensi', '慈恩寺', '走进慈恩寺，进入眼帘的是雄伟的大雁塔，七层突兀于灵空，甚是壮观。寺内古柏森森，绿阴成片，左右钟鼓楼遥遥相对。院内有两组石碑群，为一些著名进士所题刻。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (684, 'eastway', 'eastway/ciensiw', '慈恩寺外', '你来到慈恩寺外，东面就是著名的慈恩寺，高大的寺门挺立，门两旁还立了两个大石狮子。据说门上的横匾还是出自皇上的御笔。寺院内的大雁塔高高耸立。向北是一条官道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (685, 'eastway', 'eastway/dyt', '大雁塔', '大雁塔为一座七层方形塔，塔身十分雄伟，底座宽大，造型简洁庄严神秘。方塔底座有门，门楣上有石刻画。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (686, 'eastway', 'eastway/dyt1', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (687, 'eastway', 'eastway/dyt2', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (688, 'eastway', 'eastway/dyt3', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (689, 'eastway', 'eastway/dyt4', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (690, 'eastway', 'eastway/dyt5', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (691, 'eastway', 'eastway/dyt6', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (692, 'eastway', 'eastway/dyt7', '大雁塔内', '大雁塔内结构精洁宽敞，塔内布置精美，给人以清静肃穆之感。四周开有龛窗，塔内有楼梯直通上下。这里似乎是非同寻常的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (693, 'eastway', 'eastway/guandao1', '官道', '这是一条长长的官道，官道上马车并行，人流不断。多是去慈恩寺中烧香拜佛的善男信女，其中更以大户人家中的太太小姐为多。南边可看到寺院，隐约一个塔影闪在寺后。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (694, 'eastway', 'eastway/guandao2', '官道', '这是一条长长的官道，官道上马车并行，人来人往。官道的西边远远通向进士场，西边和南边各有一座高塔，东北边通向更远处。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (695, 'eastway', 'eastway/guandao3', '官道', '这是一条长长的官道，官道上马车并行，人来人往。官道一头伸向西南，一头伸向东北，东边有一座丘陵。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (696, 'eastway', 'eastway/huaqing', '曲江池', '这里已到了城边，听人讲这里有一个神秘的温泉，泉水清澈，雾气缭绕，为修补成仙的极佳场所。因此有许多人纷纷远道而来，求得一浴。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (697, 'eastway', 'eastway/huohang', '货行仓库', '这里是家大货行的仓库，里面货架上堆着不少货物，地下还有不少货柜。货行是靠替人送货为生，信用还是不错。不时有马车出入装卸货物，忙坏了一旁的伙计。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (698, 'eastway', 'eastway/jinshi', '进士场', '进士场是一个不大不小的广场，据说新科进士在受赐之后都要在进士场题名刻碑。另外这里也是文人墨客汇集的地方，在这里交流心得体会。北边是碑林，西边可看到一座高塔。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (699, 'eastway', 'eastway/shihuang', '始皇陵', '这是座落在官道以东的一个大丘陵，呈覆斗型。站在丘陵上极目远眺，不禁心旷神怡。旁边有一座高大的石碑：“秦始皇陵”。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (700, 'eastway', 'eastway/wangnan1', '望南街', '东城的望南街道路宽广，周围所住大多是有钱人家，路两旁多是些深宅大院，院墙高立。路上铺着青石，路边栽着成行的柳树，柳枝随风飘摆不定。东边是一个大货行，时有马车出入运货。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (701, 'eastway', 'eastway/wangnan2', '望南街', '东城的望南街道路宽广，周围所住大多是有钱人家，飘摆不定。东边有座草庐，看起来相当的风雅，西边是进士场。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (702, 'eastway', 'eastway/wangnan3', '望南街', '东城的望南街道路宽广，周围所住大多是有钱人家，飘摆不定。街上行人不多，东南一条小路不知通向何方。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (703, 'eastway', 'eastway/wangnan4', '望南街', '东城的望南街道路宽广，周围所住大多是有钱人家，路两旁多是些深宅大院，院墙高立。路上铺着青石，路边栽着成行的柳树，柳枝随风飘摆不定。北边是进士场，也是文人墨客聚集的地方。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (704, 'eastway', 'eastway/wangnan5', '望南街', '东城的望南街道路宽广，周围所住大多是有钱人家，飘摆不定。西边通向朱雀大街，东南有一座大的寺院，前去进香拜佛的人很多。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (705, 'eastway', 'eastway/xianquan', '仙泉', '一股热气腾腾的白雾将你团团围住，你已经来到了仙泉边。泉中清水碧波荡漾，水面雾气缭绕，有许多人正在里面闭目坐浴。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'spring');
INSERT INTO `rooms` VALUES (706, 'eastway', 'eastway/xyt', '小雁塔', '小雁塔是一座通高几十丈的砖塔，从底下向上看去，庄严而玲珑，塔身檐角密布，一共有十五层之高，与东边的大雁塔遥遥相望。塔底有门洞通向塔内，东边有路通向进士场。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (707, 'eastway', 'eastway/xyt1', '小雁塔内', '塔内气氛静而神秘，光线有些昏暗朦胧。四周墙壁上有数盏龛灯，周围绘有彩色壁画。塔内有楼梯供人上下，从龛形门窗可以纵目远眺。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (708, 'eastway', 'eastway/xyt10', '小雁塔内', '塔内气氛静而神秘，光线有些昏暗朦胧。四周墙壁上有数盏龛灯，周围绘有彩色壁画。塔内有楼梯供人上下，从龛形门窗可以纵目远眺。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
