INSERT INTO `rooms` VALUES (720, 'eastway', 'eastway/xyt8', '小雁塔内', '塔内气氛静而神秘，光线有些昏暗朦胧。四周墙壁上有数盏龛灯，周围绘有彩色壁画。塔内有楼梯供人上下，从龛形门窗可以纵目远眺。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (721, 'eastway', 'eastway/xyt9', '小雁塔内', '塔内气氛静而神秘，光线有些昏暗朦胧。四周墙壁上有数盏龛灯，周围绘有彩色壁画。塔内有楼梯供人上下，从龛形门窗可以纵目远眺。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (725, 'erlang', 'erlang/guanjiang', '灌江口', '灌洲灌江口，江水至此，豁然开阔。南面有一坐大庙，气象恢鸿，门口有把门的鬼判，威风凛凛地巡视着四周。北面是一大片丘陵，泾水远远地现于天际。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (726, 'erlang', 'erlang/temple', '二郎庙', '这里是二郎真君的庙宇。想当年齐天大圣孙悟空曾与二郎神在此一场恶斗，如今故人依在，只是冷落了许多。真君正端坐案前，见你进来，似乎早已知道来意，似笑非笑地上下打量着你。右首一根大红柱子，好象刻了些字(zi)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (727, 'gao', 'gao/bed_yashi', '床上', '', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (728, 'gao', 'gao/budian', '刘家布店', '这里的东西虽不高级，却相当符合当地人的口味．一匹匹的布料和成衣．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (729, 'gao', 'gao/cunkou', '村口', '到了村口，向村中望去，稀稀落落也有百十来间瓦房。村里人都忙忙碌碌的，顾不上搭理你，只有几个小童在村旁的池塘中无忧无虑的玩着。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (730, 'gao', 'gao/daotian1', '稻田', '稻田里村民们正在耕种着．一片一片的农田连结成网，小沟小渠密布其中．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (731, 'gao', 'gao/daotian2', '稻田', '稻田里村民们正在耕种着．一片一片的农田连结成网，小沟小渠密布其中．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (732, 'gao', 'gao/fanting', '饭厅', '饭厅中放了一张八仙桌，桌上杯碟狼籍．一伙客人刚吃过走了．小丫环正打扫着剩汤剩饭．说是剩汤剩饭，其实好些还没碰过．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (733, 'gao', 'gao/gate', '高家大门', '这里便是高家的大门口．北面一对黑木做的大门半开着，门上贴着一对门神．门左右摆着一对张牙舞爪的石狮，倒是清源县运来的正品．看门的老余头正打着瞌睡．听人讲高家近来有祸事，整个院子静悄悄的．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (734, 'gao', 'gao/guige', '闺阁', '这里是高小姐的闺楼．室内装饰典雅，家俱全是南方运来的竹器．墙上的一幅字画风骨颇为不俗，字体看起来也相当的漂亮．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (735, 'gao', 'gao/house', '农舍', '一间宽敞的农舍，打扫的干干净净。屋里正中是祖先的牌位，供案上有几乎盘蜡做的水果。墙角堆着各种瓜果蔬菜，让你直流口水。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (736, 'gao', 'gao/houyuan', '后院', '<span style=\"color:lightskyblue;\">后院之中极为宽敞,秋收时就是高家晾晒稻谷的地方.东边靠墙有</span>一口土井,<span style=\"color:lightskyblue;\">旁边放了几只木桶.</span>西边一座小楼,<span style=\"color:lightskyblue;\">是小姐住的地方,北边是高家的后花园.</span>', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (737, 'gao', 'gao/huayuan', '后花园', '后花园中花草甚多，什么凤仙、鸡冠、秋葵、百合、蔷薇、牡丹等等，不可枚举，满目皆是．遇花开之时，后花园中红红紫紫，漫如锦屏．真想多呆一会，好好看看．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (738, 'gao', 'gao/inn', '小酒馆', '镇子里就这么一家小酒馆，累了一天的生意人都会来喝几盅．酒店里的花雕可都是正经从长安运来的，那个醇味没的说．再配上几粒花生米，神仙也不过如此．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (739, 'gao', 'gao/lu1', '土路', '路上人不是很多，偶尔有几个过客．前方是一个小镇，镇上有一户高姓人家，却是这方圆百里土地的主人．附近的农民大多是靠租高家的田度日．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (740, 'gao', 'gao/lu2', '街道', '进到镇中人似乎多了些，也有些做小买卖的．青青的石板铺在路上，延续到镇的另一端．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (741, 'gao', 'gao/neishi', '内室', '房间不大，却是石门石窗．窗上还有铁打的柱子．要是大门不开，看来是没法出去的．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (742, 'gao', 'gao/pianfang', '偏房', '一间小小的偏房，摆设很简单．只有一张桌子和几张椅子而已．高家养了几个庄丁护院．其实都是些三脚猫功夫，只能吓吓人罢了．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (743, 'gao', 'gao/pianting', '偏厅', '靠窗是张火炕，上面垫着皮褥子．整个房子暖洋洋的．高老太太正盘着腿坐在炕上，低头查着旧帐．旁边一个丫环伺候着．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (744, 'gao', 'gao/road1', '街道', '一条石板小路，刚下过雨，路上看起来还满干净的．一些乡下人挑着自己种的蔬菜到镇里卖，人不是很多，吆喝声传出很远，在镇子里回荡．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (745, 'gao', 'gao/road2', '街道', '周围有一些店铺，店家为了抢生意，把东西都摆到了街上．把一条本来就不宽的石街占了大半．这里的人也显的较多，大多是些乡下来的，来买上些日常用品．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (746, 'gao', 'gao/road3', '土路', '周围是一片蹈田，一些农夫在田里赶着牲口耕种．西边望去有一座山，雾气蒙蒙，看不清楚．东边是小镇，也是方圆几十里最为繁华的地方．镇虽不大，但柴米油盐样样不缺．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (747, 'gao', 'gao/road4', '土路', '周围是一片蹈田，一些农夫在田里赶着牲口耕种．还有一些孩子在田地里玩耍．远处的村落隐约而见，炊烟饶饶，一幅天下太平的景象。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (748, 'gao', 'gao/room', '聚义厅', '这里便是清风寨的大堂－聚义厅。厅中一十六张虎皮软椅分列两旁，正面一张香台，供着关公大帝。山寨里的头领要开会的话，多半会选在这里举行。另外也是分赃宴会的地方。', '0', 'normal', 1, 0, 0, 0, 0, '{\"valid_leave\": {\"east\": {\"npc_id\": \"xia pengzhan\", \"message\": \"夏鹏展一个箭步闪到你前面，狞笑道：清风寨可是你想来便来，想走便溜的的地方！\", \"condition\": \"npc_exists\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (749, 'gao', 'gao/shanlu', '山路', '好不容易走出了小林，迈上了一条山间小路。越走树林越密，树缝中洒下来的阳光也变得斑斑点点。茅草渐厚，灌木丛生。从东北方吹来阵阵的冷风，令人毛骨耸然。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (750, 'gao', 'gao/tiepu', '铁铺', '铁铺的主人是老李头，他打的铁器坚固耐用，名气在方圆几十里是没的说．他这里的生意也特别的好．屋里到处是铁器，两个学徒正帮着老李头打造农具．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (751, 'gao', 'gao/tulu', '土路', '一条湿漉漉的小路，路边开着许多野花．路边小渠里溪水缓缓的流着．水田中也偶尔传来青蛙\"呱呱\"的叫声．远远望去，稻田中绿油油的．北边可望到高家镇，南边就到了村里．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (752, 'gao', 'gao/washing', '洗衣房', '地下到处流着脏水，一个老妈子正洗着一堆衣服．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (753, 'gao', 'gao/xiaolin', '小树林', '小林中树木密密麻麻，看不到一个人影，却偶尔能听到有人说着什么。你向前走着，却感到好似有人暗中盯着你。你的心一下悬了起来。。。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (754, 'gao', 'gao/xiaolin1', '小树林', '林中光线暗淡，隐约看到几个人围作一团说着什么。传来一股烤肉的味道，令你不禁咽了口唾沫。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (755, 'gao', 'gao/xiaolu', '小路', '高家后墙外的一条小路，看样子极少有人来．到处是半人多高的杂草，每走一步都会惊起许多小虫子，有些小蚂蚱还蹦到你的身上．．．', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (756, 'gao', 'gao/xuetang', '书堂', '一间小小的房子。正中墙上挂着一幅孔子的画像。一个老先生正教着一群孩子念之乎者也。。。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (757, 'gao', 'gao/yashi', '雅室', '高小姐的卧房便是这里．卧房吗．．当然是休息的地方了．．靠内有一张素净的床铺(bed)，但空荡荡地不见一个人影．．．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (758, 'gao', 'gao/zhangfang', '帐房', '这儿是高家的帐房，里面摆了一排柜子．高家有好几百亩良田，簿．由余柜子经常开关，木把已变的油亮．', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (759, 'gao', 'gao/zhting', '正厅', '正前方是一张八仙桌，左右是两张带皮垫的太师椅。高老爷正坐在椅上正喝着茶水。左右墙上挂着几幅字画，仔细看看好似并没有什么名气。东西是两间偏厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (760, 'gao', 'gao/zhyuan', '正院', '院中一棵巨大的兰花树，开了无数朵白色的小花，发出淡淡的清香，令人有几分陶醉．听说是高庄主的爷爷种下的，至今已有一人合抱粗细．东西是一些仆人住的地方，北边是高家的正庭。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (778, 'huanggong', 'huanggong/baihu', '白虎堂', '这里是武将们上朝前休息的地方，屋中并不是很大，靠墙放了一排软椅，正中有一张八仙桌。上有茶壶茶杯和五色点心。偶尔有几个官员出入，一个宫中侍女一旁伺候。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (779, 'huanggong', 'huanggong/baiyujie', '白玉阶', '一条百余级的石阶联系于朝天场和皇宫大堂之间。玉石全是上好的汉白玉，每块上面还雕着各种飞禽走兽，形象逼真，呼之欲出。阶上两名金甲卫士巍然而立，警惕的盯着过往官员。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (780, 'huanggong', 'huanggong/chaoyangmen', '朝阳门', '高墙巍峨，长梁雕龙，飞檐画凤，这里就是“朝阳门”。往里就是皇宫大门了，一般的百姓到此截然止步，不敢擅自逾越皇家禁地。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (781, 'huanggong', 'huanggong/dadian', '大殿', '皇宫大殿里金光闪烁瑞霭如云紫气环绕，殿中是雕龙绘凤祥云朵朵，殿心有一白玉台阶，正中是金银宝座，唐太宗怡然高坐。两边文武官弁肃然伫立，神态庄严。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (782, 'huanggong', 'huanggong/damen', '皇宫大门', '皇宫大门庄严肃穆，金壁辉煌，宫墙里面殿阁高大雄伟，层层叠叠，琉璃瓦白玉掾富丽堂皇。此刻宫门紧闭，门前守卫着几位金甲武士。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (783, 'huanggong', 'huanggong/dongdian', '东殿', '东殿里庄严肃穆，墙上绘有金龙戏珠，殿顶上画着紫色祥云朵朵缭绕，瑞气朦胧。殿墙边是凤尾屏风，地上铺着银花绣绒毯，殿里一阵阵丝竹乐声轻缓地飘来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (784, 'huanggong', 'huanggong/fst', '封榜堂', '封榜堂里碧灯齐放，笙乐高奏，众官衣冠楚楚威武静坐。更有一群宫女长袖轻飘徐徐而舞，正中是双龙双凤玛瑙台座，供设镶金嵌银缀珠汉白玉精雕御批状元武榜。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (785, 'huanggong', 'huanggong/guangchang', '朝天场', '皇宫前的大广场，长宽俱有二十余长。地下乃是从终南山运来的青砖铺就，与宫殿的红墙黄瓦交相辉映。有重大事件或节日时皇帝便在此会见群臣。北边是一排排的宫圉楼阁，东西是群臣上朝前休息的朝房。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (786, 'huanggong', 'huanggong/houdian', '后殿', '后殿里庄严肃穆，墙上绘有金龙戏珠，殿顶上画着紫色祥云朵朵缭绕，瑞气朦胧。殿墙边是凤尾屏风，地上铺着银花绣绒毯，殿里一阵阵丝竹乐声轻缓地飘来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (787, 'huanggong', 'huanggong/qinglong', '青龙堂', '这里是文官们上朝前休息的地方，屋中并不是很大，靠墙放了一排软椅，正中有一张八仙桌。上有茶壶茶杯和五色点心。偶尔有几个官员出入，一个宫中侍官一旁伺候。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (788, 'huanggong', 'huanggong/xidian', '西殿', '西殿里庄严肃穆，墙上绘有金龙戏珠，殿顶上画着紫色祥云朵朵缭绕，瑞气朦胧。殿墙边是凤尾屏风，地上铺着银花绣绒毯，殿里一阵阵丝竹乐声轻缓地飘来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (789, 'huanggong', 'huanggong/yhy1a', '御花园', '葱翠艳丽的御花园，四周种满五颜六色龙形凤姿的奇花异蕊中间是数条回转的青玉石雕花小径互为交错。煦风吹过，真是葩醇花香无比，令人恍然纷醉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (790, 'huanggong', 'huanggong/yhy1b', '御花园', '葱翠艳丽的御花园，四周种满五颜六色龙形凤姿的奇花异蕊中间是数条回转的青玉石雕花小径互为交错。煦风吹过，真是葩醇花香无比，令人恍然纷醉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
