INSERT INTO `rooms` VALUES (794, 'huanggong', 'huanggong/yhy3b', '御花园', '葱翠艳丽的御花园，四周种满五颜六色龙形凤姿的奇花异蕊中间是数条回转的青玉石雕花小径互为交错。煦风吹过，真是葩醇花香无比，令人恍然纷醉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (795, 'huanggong', 'huanggong/ywc1a', '演武场', '场内四周由磐石环绕，场心设有一八方擂台，中间填有五色净土。每年有无数的武进士前来投状应榜比武，共分金、银、铜、铁、锡五大御榜，每榜可有一甲三名，或曰武状元、武榜眼、武探花。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
