INSERT INTO `rooms` VALUES (801, 'huanggong', 'huanggong/ywc3a', '演武场', '场内四周由磐石环绕，场心设有一八方擂台，中间填有五色净土。每年有无数的武进士前来投状应榜比武，共分金、银、铜、铁、锡五大御榜，每榜可有一甲三名，或曰武状元、武榜眼、武探花。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (802, 'huanggong', 'huanggong/ywc3b', '演武场', '场内四周由磐石环绕，场心设有一八方擂台，中间填有五色净土。每年有无数的武进士前来投状应榜比武，共分金、银、铜、铁、锡五大御榜，每榜可有一甲三名，或曰武状元、武榜眼、武探花。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
