INSERT INTO `rooms` VALUES (1115, 'moon', 'moon/quest/road9', '羊肠小道', '一条蜿蜒曲折的小径，两边都是刀削般的峭壁。路旁长满了一人多高的野草，据说常有妖怪精灵出没。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1116, 'nanhai', 'nanhai/chanfang', '禅房', '这是普陀山门人弟子们练功打坐的地方。只见几个僧人正在一边吆喝着舞拳弄脚，另外几个在练习兵器。屋角摆着几把铁杖铁枪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1117, 'nanhai', 'nanhai/chaoyindong', '潮音洞', '这就是南海普陀山潮音洞，救苦救难大慈大悲观音菩萨宣讲佛法之所在。只见观音菩萨端坐在莲花台上，微开善口，敷演大法，宣扬正果，讲的是三乘妙典，五蕴楞严。但见那天龙围绕，花雨缤纷。正是：禅心朗照千江月，真性清涵万里天。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1118, 'nanhai', 'nanhai/gate', '山门', '这里是南海普陀山的山门，山门上写着：\n\n     净瓶甘露年年盛，斜插垂杨岁岁青。\n     落伽山上慈悲主，潮音洞里活观音。\n\n真个仙山宝地，福岛洞天！', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1119, 'nanhai', 'nanhai/guangchang', '落迦岩', '这是南海普陀山上一快比较平整的土地，普陀山门人弟子们经常在这里切磋武艺，宣讲佛法，交流心得。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1120, 'nanhai', 'nanhai/island', '小岛', '\"万顷风云浮碧玉，孤插苍溟小白华\"，这是南海上的一个小岛。岛虽小却大大有名，据说观音菩萨就在岛上传经说法。极目远眺，隐隐可见大陆的轮廓。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1121, 'nanhai', 'nanhai/pool', '池塘边', '池塘四周紫竹环绕，而塘边的空地上还长着几丛洁白的牡丹。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1122, 'nanhai', 'nanhai/restroom', '休息室', '这里是普陀山的休息室，屋子里空荡荡的什么也没有，不知普陀山门人弟子们是怎么样睡觉的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1123, 'nanhai', 'nanhai/road1', '小路', '这是一条通往后山的小路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1124, 'nanhai', 'nanhai/road11', '小路', '这是一条通往后山的小路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1125, 'nanhai', 'nanhai/road2', '小路', '这是一条通往后山的小路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1126, 'nanhai', 'nanhai/road22', '小路', '这是一条通往后山的小路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1127, 'nanhai', 'nanhai/road3', '小路', '这是一条通往后山的小路，道路至此越来越不好走，分叉也越来越多了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1128, 'nanhai', 'nanhai/road33', '小路', '这是一条通往后山的小路，道路至此越来越不好走，分叉也越来越多了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1129, 'nanhai', 'nanhai/road4', '小路', '这是一条通往后山的小路，道路至此越来越不好走，分叉也越来越多了，就象迷宫一样，一不小心就会迷失方向，而且顺原路都走不回去。你不禁踌躇起来，还要不要继续往前走呢？', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1130, 'nanhai', 'nanhai/shanglu', '山路', '蜿蜒曲折的山路，北上就是普陀山的山门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1131, 'nanhai', 'nanhai/shanglu2', '山路', '蜿蜒曲折的山路，西边通往海边。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1132, 'nanhai', 'nanhai/shuyuan', '书院', '这里就是普陀山书院，书架上摆着无数书籍。普陀山门人弟子中有来提高基本读书识字的，更多的是来钻研佛经修练佛法的，以期早日修得正果。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1133, 'nanhai', 'nanhai/tingjing', '听经石', '这块石头(stone)状似两只并卧的海龟，静静地趴在海滩上。据说东海龙王敖广曾派二海龟去偷听观音念经，并要它们记下经文，好用来给水族讲解。不料，二龟光顾听经，全神贯注下竟错过了返回大海的时间，遂变为石头。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1134, 'nanhai', 'nanhai/xiaoyuan', '小院', '这是一间小院，院中遍布奇花异草，参天大树将院子四周遮得严严实实，好一个修身养性之所在。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1135, 'nanhai', 'nanhai/zhaifang', '斋房', '这里是普陀山门人弟子们吃饭用斋的场所，桌子上摆着一些蔬菜水果。由于来此者大多是僧人，因此斋房只提供素席。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1136, 'nanhai', 'nanhai/zhulin0', '紫竹林', '普陀后山的紫竹林。也是观音菩萨闲憩常到的所在。紫竹细疏，清风微拂。漫步于此，世事之纷扰顿时烟消云散。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
