INSERT INTO `rooms` VALUES (1154, 'nanhai', 'nanhai/zoulang', '走廊', '这里是通往普陀山书院和禅房的走廊。普陀山书院藏有大量佛经，供门人弟子们参禅修行时使用，不过外人一般说来是不允许进入书院的。', '0', 'normal', 1, 0, 0, 0, 0, '{\"valid_leave\": {\"west\": {\"npc_id\": \"bear-monster\", \"message\": \"黑熊怪笑嘻嘻地拦住你，说道：「对不起，这里是我们南海普陀山的书院，只允许本派弟子进入。」\", \"npc_name\": \"黑熊怪\", \"condition\": \"family_check_and_npc\", \"required_family\": \"nanhai\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (1155, 'nanhai', 'nanhai/zoulang2', '走廊', '这里是通往斋房的走廊，普陀山门人弟子们用斋前往往在此小憩片刻，有人乘机寻得一些药品灵丹来疗伤养精。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
