INSERT INTO `rooms` VALUES (1175, 'nanhai', 'nanhai/luohan/luohanw9', '罗汉塔', '佛', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1689, 'ourhome', 'ourhome/bldg', '住宅区', '终於见到人烟了。看起来这是一片没有俊工的住宅区。四周杂草丛生。除了几条脏不啦唧的小狗在这里逛来逛去外，还有个脸上盖着顶破草帽的男人，正靠在一辆老爷车(car)上打瞌睡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1690, 'ourhome', 'ourhome/kedian', '荒郊小店', '这是一家不知名的荒郊小店，四壁早已破败，不知道为什么生意仍然非常兴隆。一帮酒客在此聊得天花乱坠。店小二更是里里外外忙得团团转，接待着南腔北调的客人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1691, 'ourhome', 'ourhome/kedian2', '荒郊野外', '你正走在荒郊野外的一条崎岖小路上，只有一些小虫子绕着你飞来飞去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1692, 'ourhome', 'ourhome/kedian3', '荒郊野外', '你正走在荒郊野外的一条崎岖小路上，只有一些小虫子绕着你飞来飞去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1693, 'ourhome', 'ourhome/kedian4', '路的尽头', '地势稍显开阔，已经到了路的尽头。这里只有一座小亭，亭上牌匾大书：“聚见亭”。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1694, 'ourhome', 'ourhome/postoffice', '害虫电信局', '这里是害虫电信局。(instructions)?', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1695, 'ourhome', 'ourhome/void', '最后乐园', '<span style=\"color:lightskyblue;\">这里就是传说中的 VOID -- 大神和巫师的最后乐园. \r\n你看到四周一片白茫茫的, 不一会从虚无中冒出一只企鹅, 递给你一罐「可口可乐」</span>(tm), <span style=\"color:lightskyblue;\">然后站在一旁很邪恶地笑着. \r\n又过了一会, 一只北极熊走了过来, 一掌拍扁了那只企鹅并从你手上抢走那瓶可乐, 大笑三声后就从你眼前消失了.</span>你摇摇头,<span style=\"color:lightskyblue;\"> 这种地方还是不要待太久的好.</span>', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1696, 'ourhome', 'ourhome/xiaoting', '聚见亭', '--聚 见 亭-- \n\n秋风清，秋风明\n落叶聚还散\n寒鸦栖复惊 \n相思相见知何日\n此时此夜难为情\n\n由此往北可看到一条荒郊小路。而往其它方向则是朦朦胧胧的什么也看不清。你隐隐约约地觉得只要跨出栏杆往外一走(out)也许就永远回不来了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1697, 'ourhome', 'ourhome/honglou/april', '四月谜会', '     黑不是，白不是，红也不是，和狐狼猫狗仿佛，既非家畜，又非野兽　　诗也有，词也有，论语也有，对东西南北模糊，虽为短品，也是妙文', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1698, 'ourhome', 'ourhome/honglou/bridge', '沁芳闸', '    这桥便通外河之闸，引泉而入者。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1699, 'ourhome', 'ourhome/honglou/bula', '红楼旧址', '正门之上有一匾(bian)。正门却不开，只有角门(door)供人出入。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1700, 'ourhome', 'ourhome/honglou/bull', '菩提明镜', '    菩提本非树，明镜亦非台。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1701, 'ourhome', 'ourhome/honglou/cave', '蓼汀花溆', '    水声潺潺泻出，石洞上则萝薜倒垂，下则落花浮荡。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1702, 'ourhome', 'ourhome/honglou/cglaem', '蝉房', '    风定花尤落，虫鸣山更幽', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1703, 'ourhome', 'ourhome/honglou/cool', '云水深处', '    小桥，流水，人家……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1704, 'ourhome', 'ourhome/honglou/cottage', '天然', '    新绿涨添□葛处，好云香护采芥人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1705, 'ourhome', 'ourhome/honglou/dream', '醉梦亭', '穿林海，跨雪原，气冲霄汉。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1706, 'ourhome', 'ourhome/honglou/fairyplace', '太虚幻境', '    问谁幻入华胥境　千古风流造业人', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1707, 'ourhome', 'ourhome/honglou/fisher', '钓鱼台', '    台面上放着一碟清蒸鱼。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1708, 'ourhome', 'ourhome/honglou/kat', '荡悠悠三更梦', '    枯藤，老树，昏鸦……', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1709, 'ourhome', 'ourhome/honglou/lihuashu', '梨花树下', '梨花院落溶溶月，柳絮池塘淡淡风。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1710, 'ourhome', 'ourhome/honglou/main', '大观楼', '    崇阁巍峨，层楼高起，面面琳宫合抱，迢迢复道纡行。青松拂檐，玉兰绕砌；金辉兽面，彩焕螭头。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1711, 'ourhome', 'ourhome/honglou/maineast', '缀锦阁', '大观楼东面飞楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1712, 'ourhome', 'ourhome/honglou/mainwest', '含芳阁', '大观楼西面斜楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (1713, 'ourhome', 'ourhome/honglou/miner', '蓝桥', '    遮不住的青山隐隐，流不断的绿水悠悠。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1714, 'ourhome', 'ourhome/honglou/none', '画楼', '    滴不尽相思血泪抛红豆，开不完春柳春花满画楼(painting)', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1715, 'ourhome', 'ourhome/honglou/path1', '曲径通幽', '迎门一带翠嶂挡在面前。其中微露羊肠小径。山上有镜面白石一块(stone)。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1716, 'ourhome', 'ourhome/honglou/pavilion', '沁芳亭', '绕堤柳借三篙翠，隔岸花分一脉香。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1717, 'ourhome', 'ourhome/honglou/village', '稻香村', '    杏帘招客饮，在望有山庄。菱荇队邬水，桑榆燕子梁。\r\n		一畦春韭熟，十里稻花香。盛世无□馁，何须耕织忙。\r\n		\r\n一个酒幌(sign)用竹竿挑在树梢。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1718, 'ourhome', 'ourhome/honglou/wow', '空房间', '这是一间什么都没有的房间。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1719, 'ourhome', 'ourhome/honglou/wux', '星亭', '    天上星星亮晶晶。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1720, 'ourhome', 'ourhome/honglou/yard1', '潇湘馆', '    秀玉初成实，堪宜待凤凰。竿竿青欲滴，个个绿生凉。\r\n    迸砌防阶水，穿□碍鼎香。莫摇清碎影，好梦昼初长。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1721, 'ourhome', 'ourhome/honglou/yard2', '蘅芜院', '    蘅芜满静苑，萝薜助芬芳。软衬三春草，柔拖一缕香。\r\n		轻烟迷曲径，冷翠滴回廊。谁谓池塘曲？谢家幽梦长。\r\n		\r\n栏杆外另放着两张竹案，一个上头设着茶筅茶盂各色茶具，一个上面摆着笔墨纸砚。当中一张大纸上，墨迹未干，龙飞凤舞地写着些什么(poem)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1722, 'ourhome', 'ourhome/honglou/yard3', '怡红院', '    深庭长日静，两两出婵娟。绿蜡春犹卷，红□夜未眠。\r\n		凭栏垂绛袖，倚石护青烟。对立东风□，主人应解怜。', '/u/hkgroup', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1757, 'pantao', 'pantao/accept', 'accept', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1758, 'pantao', 'pantao/fenga', '彩凤厅', '封神台西侧为彩凤厅。厅内碧雾蒙蒙，盘旋着彩羽凌空丹顶凤。两边天妃仙女玉簪珠履绛纱衣，若星辰灿烂。厅外开满千千年不谢的琪花。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1759, 'pantao', 'pantao/fengb', '封神台', '◇封神台◇\r\n\r\n封神灵台巍峨雄伟，金璧辉煌。只见琉璃碧沉沉，宝玉明幌幌，天神、天圣、天尊、天王、左辅、右弼等两边伫立。龙旗鸾辂祥光蔼，宝节幢幡瑞气飘。更有仙乐玄歌音韵美，凤箫玉管响声高。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1760, 'pantao', 'pantao/fengc', '金龙厅', '封神台东侧为金龙厅。厅内明霞幌幌，缠绕着金鳞耀日赤须龙。两边天将仙卿紫绶金章芙蓉冠，如金璧辉煌。厅外长满万万载常青的绣草。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1761, 'pantao', 'pantao/palace1', '天乾殿', '◇天乾殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1762, 'pantao', 'pantao/palace2', '地坤殿', '◇地坤殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1763, 'pantao', 'pantao/palace3', '云象殿', '◇云象殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1764, 'pantao', 'pantao/palace4', '旦寰殿', '◇旦寰殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1765, 'pantao', 'pantao/palace5', '夕寅殿', '◇夕寅殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1766, 'pantao', 'pantao/palace6', '星冕殿', '◇星冕殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1767, 'pantao', 'pantao/palace7', '辰亘殿', '◇辰亘殿◇\r\n\r\n大殿金光万道红霓朦胧，瑞气千条紫雾缭绕。复道回廊，处处玲珑剔透，三檐四簇，层层龙凤翱翔。两边镇天元帅，员员顶梁靠柱，四下金甲神人，个个执戟悬鞭。殿中碧色琉璃台阶上一座洁琼宝座玉光耀目，天神怡然高坐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1768, 'pantao', 'pantao/yaoa', '瑶池西廊', '瑶池西廊摆满芝兰香蕙，瑶草奇花。仙姬仙子在此备制仙果仙肴。但见金银果盘内金丸珠弹，红绽黄肥。中间供有数枚紫纹娇嫩半红半绿的蟠桃。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1769, 'pantao', 'pantao/yaob', '瑶池', '◇瑶池◇\r\n\r\n琼香缭绕，瑞霭缤纷，瑶台铺彩结，宝阁散氤氲。凤翥鸾腾形缥缈，金花玉萼影浮沉。五彩描金桌，千花碧玉盆。桌上有龙肝凤髓，熊掌猩唇。珍馐百味般般美，异果嘉肴色色新。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
