INSERT INTO `rooms` VALUES (1816, 'penglai', 'penglai/baiyun9', '白云洞', '洞口虽小，洞内却别有天地。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1817, 'penglai', 'penglai/bomingyan', '薄命岩', '一座山崖兀立高耸，佼佼不群。崖边一棵青松，苍劲挺拔，直插白云之间。这里就是百花仙子隐居的所在。崖下是百花谷，遍地是奇花异草，可惜山势陡峭，轻身功夫不佳的如果贸然跃(jump)下(down)，不免摔得骨断筋折。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1818, 'penglai', 'penglai/hongyandong', '红颜洞', '一间占地不大的岩洞，石榻石桌石椅，布置得高雅脱俗。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1819, 'penglai', 'penglai/penglai', '蓬莱仙岛', '蓬莱岛上风光秀丽，当真是好去处！远望海中，碧波如镜，高山之上，巍峨势耸。山间少闻人语声，但听猿啼鹤鸣。几树乔松栖野鹤，数株翠柳语山莺。曲径碧萝垂挂，石梯蓬葛攀笼。远山见白云出釉，近现花色蓉蓉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1820, 'penglai', 'penglai/road1', '山后小路', '蓬莱岛上风光秀丽，当真是好去处！山后的小路两边奇花异草不绝，满目香艳。上有奇松古藤，多有仙鸟停歇。前面一座石崖高耸，南方有一小孔，透出几许明光。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1821, 'penglai', 'penglai/undertree', '白云洞外，松阴之下', '一棵高有数丈的大松树如伞如盖遮住了天空，松树上垂挂着许多荜萝葛藤，中见隐见些小花。松树下有一大石台，上面刻了一个围棋盘，石台旁有三个石凳。数丈外有一石洞，洞前石碑上刻着「白云洞」三个大字。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1822, 'penglai', 'penglai/yashang', '青石崖', '蓬莱岛上风光秀丽，当真是好去处！高崖上视野开阔，远望四周，把蓬莱景色看的清清楚楚。远处大海如明镜般平整。山崖上长有无数异草，飘着淡淡香气。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1823, 'penglai', 'penglai/yaxia', '青石崖下', '蓬莱岛上风光秀丽，当真是好去处！前方一座高崖，崖上有祥云绕绕，隐有红光。崖壁上多是青苔锈葛，看上去异常的滑手。崖上有鹤鸣阵阵，空山回音不绝。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1824, 'penglai', 'penglai/yazhong', '青石台', '蓬莱岛上风光秀丽，当真是好去处！高崖上视野开阔，周围景色看的清清楚楚。石崖不知还有多高，隐在云中不见端倪，下面云雾绕绕，也不知有多高了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1826, 'qujing', 'qujing/baihuling/cave', '枯骨洞', '周围阴森黑暗，只有遍地的白骨丛中间或有一点点幽暗的荧光闪烁。借着这微弱的光亮，你发觉自己置身在一个纵横交错的庞大洞穴之中。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1827, 'qujing', 'qujing/baihuling/entrance', '白虎岭', '峰岩重叠，涧壑湾环。虎狼成阵走，麂鹿作群行。千尺大蟒，万丈长蛇。大蟒喷愁雾，长蛇吐怪风。道旁荆棘浅漫，岭上松楠秀丽。薜萝满目，芳草连天。草丛中似乎隐隐现出一个洞口(enter)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1828, 'qujing', 'qujing/baihuling/jail', '囚洞', '这里是枯骨洞的储藏室，老妖抓来的人都先放在这儿，等着开伙时好选用。你注意到身后的石壁似乎有些松动，轻轻一搬，隐隐现出一个洞口，也许可以钻进去？(zuan)', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1829, 'qujing', 'qujing/baihuling/maze_generator', 'maze', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1830, 'qujing', 'qujing/baihuling/small_cave', '枯骨洞', '周围阴森黑暗，只有遍地的白骨丛中间或有一点点幽暗的荧光闪烁。借着这微弱的光亮，你发觉自己置身在一个纵横交错的庞大洞穴之中。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1831, 'qujing', 'qujing/baihuling/small_exit', '舍利塔', '峰岩重叠，涧壑湾环。虎狼成阵走，麂鹿作群行。千尺大蟒，万丈长蛇。大蟒喷愁雾，长蛇吐怪风。道旁荆棘浅漫，岭上松楠秀丽。薜萝满目，芳草连天。山路边一座古塔，里面供奉着前辈高僧的舍利。后人也不断把寻到的舍利子虔诚地埋在塔下(bury)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1833, 'qujing', 'qujing/baotou/dongwai', '洞外', '山顶上一片广场，但见那狼牙般的岩崖下有一洞口，阴森森不知是什么去处。洞外边山壁上长满了苔衣，四处陡峭，好象看不到路的迹象。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1834, 'qujing', 'qujing/baotou/houdong', '后洞', '后洞里髯着一堆一堆的篝火，洞的东边砌了一个石灶，上有一口大铜锅。西边有一内厅，厅里铺有各式兽皮，正中有一大床铺着绒毛垫。洞壁上有一道裂痕，延伸到洞顶。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1835, 'qujing', 'qujing/baotou/hukou', '虎口', '一个深奥莫测的山洞出现在眼前，洞口有凉嗖嗖的溪水滴嗒下来。洞壁上是苔衣和蔓藤，洞口上写着六个大字：豹头山虎口洞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1836, 'qujing', 'qujing/baotou/midong1', '密洞', '这里光线极为微弱，你勉强地看见洞里隐隐约约的一些东西，却又看得不是十分清楚。你不禁伸出手来扶着洞壁，小心地摸索着行动。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1837, 'qujing', 'qujing/baotou/midong2', '密洞', '这里光线极为微弱，你勉强地看见洞里隐隐约约的一些东西，却又看得不是十分清楚。你不禁伸出手来扶着洞壁，小心地摸索着行动。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
