INSERT INTO `rooms` VALUES (1841, 'qujing', 'qujing/baotou/qiandong', '前洞', '前洞里有天然石桥石亭，溪水从石桥下流过，两边石壁上挂下来无数藤蔓。石亭边长着一些矮小的花草灌木，南边有路通向洞外，东北边有一通道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1842, 'qujing', 'qujing/baotou/shanlu1', '山路', '山路极为崎岖险恶，岩崖狼牙一般突兀而起，石壁陡峭，远处有猛的吼声断断续续地传来，近处野林风吹草动，令人毛骨悚然，不禁放慢了脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1843, 'qujing', 'qujing/baotou/shanlu10', '山路', '山路极为崎岖险恶，岩崖狼牙一般突兀而起，石壁陡峭，远处有猛的吼声断断续续地传来，近处野林风吹草动，令人毛骨悚然，不禁放慢了脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
