INSERT INTO `rooms` VALUES (1851, 'qujing', 'qujing/baotou/shanlu9', '山路', '山路极为崎岖险恶，岩崖狼牙一般突兀而起，石壁陡峭，远处有猛的吼声断断续续地传来，近处野林风吹草动，令人毛骨悚然，不禁放慢了脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1862, 'qujing', 'qujing/baoxiang/bei1', '北城门', '宝象国的北城门，因多次发生妖祸，城门外大道已被堵塞。向西北方向看去可以见到山峦，向南极目看去，远远能看见宝象国的王宫大门。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1863, 'qujing', 'qujing/baoxiang/bei2', '北街', '北街上人来人往，或是渔夫担鱼或是樵夫担柴，城内家的家，户的户，只斗逍遥。熙熙攘攘，日子过得十分爽快。向北是城门，向南是王宫所在。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1864, 'qujing', 'qujing/baoxiang/bei3', '北街', '街上人很多，路两边不时传来异国情调的琴声。东面有一家小作坊，门口放着式样奇特的毯子木器之类手工制品向路人销售，南边通向王宫大门。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1865, 'qujing', 'qujing/baoxiang/bei4', '北街', '这里离城市中心很近，路面宽敞，异国情调的人们走来走去，非常热闹。东面有一马栈，不时有人挑担或牵马进去休息歇脚。往南就是王宫的大门。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1866, 'qujing', 'qujing/baoxiang/chaoxing', '潮星谷', '周围是略隆起的山坡，中心下凹地面柔软，行如谷状。大小岩石呈暗红色，长满绿色苔藓。东边有一些半人高的灌木，爬有粗粗的藤状植物。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1867, 'qujing', 'qujing/baoxiang/dian1', '太极殿', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1868, 'qujing', 'qujing/baoxiang/dian2', '华盖殿', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
