INSERT INTO `rooms` VALUES (1871, 'qujing', 'qujing/baoxiang/dian5', '宣政殿', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1872, 'qujing', 'qujing/baoxiang/dian6', '延英殿', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1873, 'qujing', 'qujing/baoxiang/dong', '波月洞', '洞内湿气环绕，阴森逼人。向外看，洞口苔藓斑斑；向里看，不知深浅，隐约可听见滴水之声。好一个倒木横担，枯藤挂峰，不知是妖境还是仙境。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1874, 'qujing', 'qujing/baoxiang/dongwai', '金塔', '山崖边有一座宝塔，金顶放光，彩气腾腾。青青香草秀，艳艳野花开。远观如三岛天堂，近看似蓬莱仙境，果真是绝好去处。塔前有一白玉石板(shi ban)。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1875, 'qujing', 'qujing/baoxiang/gong1', '大明宫', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1876, 'qujing', 'qujing/baoxiang/gong2', '昭阳宫', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
