INSERT INTO `rooms` VALUES (1878, 'qujing', 'qujing/baoxiang/gong4', '华清宫', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1879, 'qujing', 'qujing/baoxiang/gong5', '建章宫', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1880, 'qujing', 'qujing/baoxiang/gong6', '未央宫', '宫殿里紫霓朦胧，瑞气缭绕。墙上雕有龙凤，玲珑剔透欲飞欲去。地上摆有金盆芝兰香蕙，银桌玉器铺彩结，几位宫女玉簪珠履静然肃立。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1881, 'qujing', 'qujing/baoxiang/gongmen', '王宫门', '宫门呈双月拱形，由山里运来的玉石筑成，上面雕有细腻的金丝银线弧形花纹。向里面看去，宫殿林立阁宇重重，祥云笼罩，气象极度非凡。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1882, 'qujing', 'qujing/baoxiang/longfeng', '龙凤阁', '龙凤阁盘龙舞凤，阁内玉雕云绘层层叠叠富丽堂皇，多用金丝银线攀绕而成。阁中有琼瑶翡翠花座，四周镶嵌玛瑙涟漪纹。这里是宝象国礼待外宾的地方。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1883, 'qujing', 'qujing/baoxiang/luochi1', '漯池', '这里淤积着一片一片被阳光晒得半干的沼泽地。走在硬硬的泥壳上面，感觉脚下的地面软软地往下陷。路不成行，歪歪斜斜地长着一丛丛无名杂草。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1884, 'qujing', 'qujing/baoxiang/luochi2', '漯池', '这里淤积着一片一片被阳光晒得半干的沼泽地。走在硬硬的泥壳上面，感觉脚下的地面软软地往下陷。路不成行，歪歪斜斜地长着一丛丛无名杂草。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1885, 'qujing', 'qujing/baoxiang/mazhan', '马栈', '这里是个简易的客栈，放着一排木板斜靠椅，对面是一排长长的床榻。客人们远道而来可以将车马托交给栈后老板，然后上榻休息一番。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1886, 'qujing', 'qujing/baoxiang/qiao1', '云头桥', '一条河东西方向横在面前，两岸泥泞，沼泽连片。走进去怕是会陷在里面人马无归，河心更是急流滚滚。河面上有一串用船搭成的简易浮桥(qiao)。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1887, 'qujing', 'qujing/baoxiang/qiao2', '云头桥', '一条河东西方向横在面前，两岸泥泞，沼泽连片。走进去怕是会陷在里面人马无归，河心更是急流滚滚。河面上有一串用船搭成的简易浮桥(qiao)。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1888, 'qujing', 'qujing/baoxiang/shan1', '碗子山', '山上黄土龟裂岩石层层，参差不奇地长着一些树林灌木。路从岩石周围绕道铺设盘山而行，迂回曲折。四处风吹草动，空谷回音。令人恍然不知所处。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
