INSERT INTO `rooms` VALUES (1896, 'qujing', 'qujing/baoxiang/shanc', '碗子山', '山上黄土龟裂岩石层层，参差不奇地长着一些树林灌木。路从岩石周围绕道铺设盘山而行，迂回曲折。四处风吹草动，空谷回音。令人恍然不知所处。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1897, 'qujing', 'qujing/baoxiang/shanwan1', '山湾', '山湾地带有一些缓缓急急的水流，溪水哗哗作响。岸边是松松的沼泽地，堆着枯枝烂叶。四处见山峦，路在这里显得宽畅一些，地面较平坦。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1898, 'qujing', 'qujing/baoxiang/shanwan2', '山湾', '山湾地带有一些缓缓急急的水流，溪水哗哗作响。岸边是松松的沼泽地，堆着枯枝烂叶。四处见山峦，路在这里显得宽畅一些，地面较平坦。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1899, 'qujing', 'qujing/baoxiang/shanwan3', '山湾', '山湾地带有一些缓缓急急的水流，溪水哗哗作响。岸边是松松的沼泽地，堆着枯枝烂叶。四处见山峦，路在这里显得宽畅一些，地面较平坦。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1900, 'qujing', 'qujing/baoxiang/songlin', '黑松林', '山路崎岖，松林丛簇藤攀葛绕，边上是一带林丘，柏翠松青。林子内长满野草山花，幽幽暗暗，看起来这里草深路小，不知能通向何处。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1901, 'qujing', 'qujing/baoxiang/tiandi', '天地阁', '天地阁祥云飞舞瑞霭环绕，阁内绘云万道金丝银线缭绕朦胧，阁中是金光闪闪的宝座。四周文官武弁目光炯炯肃然伫立，两边自有洁衣宫女手托金银果盘，内有百味异果香醪佳酿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1902, 'qujing', 'qujing/baoxiang/west', '乾元街', '这里是乾元街中段，路两旁挤满了做生意的小贩。北边有一家裁衣店，南边是一家客店。', '/u/mimi/zhuziguo/', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1903, 'qujing', 'qujing/baoxiang/xi1', '西城门', '城楼高筑，旌旗飘扬。城门西北有条长河弯曲地流过，远远可以看见河上架了座浮桥。往东看是城里闹市区，许多路人正忙着进出城。西边一条小路通到山边。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1904, 'qujing', 'qujing/baoxiang/xi2', '西街', '西街上人流不息，城内家的家，户的户，只斗逍遥。大都是渔夫或樵夫，丰衣足食，日子十分爽快。向西是出城之路，向东可以抵达宝象国王宫。南边有家饭馆，飘出烤羊肉香。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1905, 'qujing', 'qujing/baoxiang/xi3', '西街', '街心由从山里运来的石板条筑成，看上去宽敞。路两边人不少，打扮装饰奇特。向东南方向望去可以见到许多高大的宫殿，那里便是王宫所在地。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1906, 'qujing', 'qujing/baoxiang/xi4', '西街', '这里差不多是市中心了，路面宽敞，人们走来走去，非常热闹。北面有一门面挂着各式各样的锡器，东南方向可以远远地看见王宫的群宫群殿。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1907, 'qujing', 'qujing/baoxiang/xiqi', '锡器铺', '锡器铺里挂着各式各样的器皿，有长嘴锡壶，大小锡碗锡盘锡盆。上面都打印着奇形怪状的花纹。可以听见屋后的一些小学徒正在乒乒乓乓地敲打着锡器。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1908, 'qujing', 'qujing/baoxiang/yangrou', '羊肉馆', '一座沿街搭棚而建的羊肉馆，一群食客盘腿席地而坐，围着一圈陶盆陶盘聚在一起撕着羊肉进餐。从里面的厨房里不断地传出阵阵羊肉香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1909, 'qujing', 'qujing/baoxiang/yedu', '野渡', '这里是城外废弃不用的野渡口，渡口长满野生植物。遍地沼泽，笼罩着黑雾似的瘴气。散发着腥味的风一阵阵吹来，熏得人头重脚轻。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1910, 'qujing', 'qujing/baoxiang/yelu1', '野路', '野路道路细长崎岖，起伏不停。四周远远都是大小山峦，低洼处是一片湿湿的沼泽地带，看不见人间烟火。走在山路上静悄悄，雾气浓郁，不由得让人小心加快步伐。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
