INSERT INTO `rooms` VALUES (1918, 'qujing', 'qujing/baoxiang/yujie1', '白玉阶', '由白玉铺成的台阶，级级缓缓向上铺去。每一级台阶都精工细雕而成，镶嵌有金丝银线。两边各通向一宫一殿，左为大明宫，右为太极殿。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
