INSERT INTO `rooms` VALUES (1923, 'qujing', 'qujing/baoxiang/yujie6', '白玉阶', '由白玉铺成的台阶，级级缓缓向上铺去。每一级台阶都精工细雕而成，镶嵌有金丝银线。两边各通向一宫一殿，左为大明宫，右为太极殿。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1924, 'qujing', 'qujing/baoxiang/zhendong', '镇东场', '镇东场由石墙圈起，场角有一口大石井。场的东面驻有王家卫兵，西南方向更是高墙筑起，里面宫殿林立，阁宇重重，那里便是宝象国王宫。', '/d/qujing/baoxiang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1925, 'qujing', 'qujing/baoxiang/zuofang', '小作坊', '作坊的墙上挂满各式各样手工制品和织毯，一位中年男人脚踩木织机织着毯子。屋角堆满木头块和一些未完工的家俱。透过门帘，可以听见里间有人正在吱呀呀地纺线。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1953, 'qujing', 'qujing/bibotan/furong', '芙蓉亭', '芙蓉亭上有八角，上雕飞龙彩凤，麒麟辟邪，分指向八个方位。亭中一张园形青石桌，上刻有极大的一个太极图案。周围八个石凳，按八卦方位摆置。任何的风吹草动似乎都会引发一些风雨雷电，天动地摇的前兆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1954, 'qujing', 'qujing/bibotan/gudu', '古渡口', '这里乃是碧波潭边一个渡口，后来因潭中闹水怪，附近的百姓纷纷迁到城中，渡口便荒废了下来。靠水边只有零零散散几根木头搭着，似乎一阵风浪就可掀翻。远望湖心有一小岛，倒也树木茂盛。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1955, 'qujing', 'qujing/bibotan/hanyu', '寒玉堂', '殿堂乃是用寒玉沏成，深绿色的寒玉皆取于那北冥雪山之中，玉中透出淡淡荧光，整个大堂内渗着透骨的寒气。宫中的鱼蟹都惧怕寒冷，是以堂中冷冷清清，与大殿形成鲜明的对比。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1956, 'qujing', 'qujing/bibotan/hua_dui', '后花园', '后花园中非常的清雅，看不到什么人。虽说是花园，奇怪的是不见有花朵。种植的大多是些奇怪的草类，五颜六色的。东一堆，西一簇，向是规划的非常仔细。隐见花园正中一座小厅，在草木衬托之下显得非常雅致。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
