INSERT INTO `rooms` VALUES (1964, 'qujing', 'qujing/bibotan/lengxiang', '冷香殿', '冷香殿上的家俱都是昆仑山中特有的冷香木制成，肌肤所触都是冰冷异常。大厅之上弥漫这一丝淡淡的香气，让人不由得神清脑健，精神倍增。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1965, 'qujing', 'qujing/bibotan/longtai1', '龙沙台', '龙沙台约有一丈见方，上面有细沙铺就，整个台面非常的平整。台的东面高悬一口铜钟，象是在水中传讯是用的。有几个小妖在台上舞刀弄枪，比划拳脚。前方就看到水晶宫了。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1966, 'qujing', 'qujing/bibotan/longtai2', '龙沙台', '龙沙台约有一丈见方，上面有细沙铺就，整个台面非常的平整。台的东面高悬一口铜钟，象是在水中传讯是用的。有几个小妖在台上舞刀弄枪，比划拳脚。正北方有一个月洞门，后面便是碧波潭水府的后院了。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1967, 'qujing', 'qujing/bibotan/luhua1', '芦花荡', '走如芦花荡便如走入一个迷宫，前后左右都是一人多高的芦草，密密麻麻的让人辩不清方位，随风而舞的芦花沾了人满身都是。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
