INSERT INTO `rooms` VALUES (1976, 'qujing', 'qujing/bibotan/shigang1', '乱石冈', '乱石坡乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。东边上去是山顶，山后就是碧波潭，微风带来阵阵水声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1977, 'qujing', 'qujing/bibotan/shigang2', '乱石冈', '乱石山上乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。南边向上去是山顶，东边潭水碧绿，如同暖玉般卧在山中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1978, 'qujing', 'qujing/bibotan/shipo1', '乱石坡', '乱石坡乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。向东可看到碧波潭，一汪潭水被四面围在山中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1979, 'qujing', 'qujing/bibotan/shipo2', '乱石坡', '乱石坡乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。向东可看到碧波潭，一汪潭水被四面围在山中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1980, 'qujing', 'qujing/bibotan/shipo3', '乱石坡', '乱石坡乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。向东可看到碧波潭，一汪潭水被四面围在山中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1981, 'qujing', 'qujing/bibotan/shipo4', '乱石坡', '乱石坡乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。向东可看到碧波潭，一汪潭水被四面围在山中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1982, 'qujing', 'qujing/bibotan/shishan', '乱石山', '乱石山上乱石遍地，大的小的到处都是。坡上极干燥，所生草木唯有红柳，如在山上笼了一团红云。远望碧波潭中浪淘滚滚，岸边芦花如雪。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1983, 'qujing', 'qujing/bibotan/shuangyu', '霜雨轩', '轩内装饰典雅，家俱全是玉竹编成，看起来相当地雅致。四周摆着不少古玩玉器，尤其是墙上的一幅字画风骨颇为不俗，上书“霜雨轩”三个大字，字体隽秀，象是出自女子之手。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1984, 'qujing', 'qujing/bibotan/shuijg', '碧波潭水晶宫', '这里便是碧波潭龙王的居所水晶宫。大堂之上高悬数颗明珠，将大厅照的如同白昼。厅内的摆设也是尽其豪华，入目之处无不是人间少有，世上难寻的奇珍异宝。一群彩衣宫嫔正随歌而舞，几个龙子龙孙前后招呼，好不热闹。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1985, 'qujing', 'qujing/bibotan/sleeproom', '睡房', '这里是碧波潭弟子的睡房，角落里躺着几个小妖，正在呼呼大睡。', '0', 'normal', 1, 0, 0, 1, 1, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (1986, 'qujing', 'qujing/bibotan/tandi1', '潭底小径', '这里是碧波潭底细沙铺就的一条小径，左右水草密布，随着水波来回飘摆。潭水成碧绿色，水下光线不是很好，道路难辩。', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1987, 'qujing', 'qujing/bibotan/tandi2', '潭底小径', '这里是碧波潭底细沙铺就的一条小径，左右水草密布，随着水波来回飘摆。潭水成碧绿色，水下光线不是很好，道路难辩。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1988, 'qujing', 'qujing/bibotan/tandi3', '潭底小径', '这里是碧波潭底细沙铺就的一条小径，左右水草密布，随着水波来回飘摆。潭水成碧绿色，水下光线不是很好，道路难辩。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1989, 'qujing', 'qujing/bibotan/xiaolu1', '潭边小路', '小路因为年久无人走动的关系，已被枯黄的树叶覆盖了。路边的荒草几有人高，阵风吹过，卷起一片片的枯叶。草从中也呼呼做响，象是猛兽发出的吼声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1990, 'qujing', 'qujing/bibotan/xiaolu2', '潭边小路', '小路因为年久无人走动的关系，已被枯黄的树叶覆盖了。路边的荒草几有人高，阵风吹过，卷起一片片的枯叶。草从中也呼呼做响，象是猛兽发出的吼声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1991, 'qujing', 'qujing/bibotan/xiaolu3', '潭边小路', '小路因为年久无人走动的关系，已被枯黄的树叶覆盖了。路边的荒草几有人高，阵风吹过，卷起一片片的枯叶。草从中也呼呼做响，象是猛兽发出的吼声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1992, 'qujing', 'qujing/bibotan/xiaolu4', '潭边小路', '小路因为年久无人走动的关系，已被枯黄的树叶覆盖了。路边的荒草几有人高，阵风吹过，卷起一片片的枯叶。草从中也呼呼做响，象是猛兽发出的吼声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1993, 'qujing', 'qujing/bibotan/yangchang1', '羊肠小路', '小路很窄，只能容一人侧身而行。路边荆棘从生，一不小心就会在身上挂出伤口。荆棘中生有红色野果，但很难摘到。远望东北一座城池，南边上去是座石头山。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1994, 'qujing', 'qujing/bibotan/yangchang2', '羊肠小路', '小路很窄，只能容一人侧身而行。路边荆棘从生，一不小心就会在身上挂出伤口。荆棘中生有红色野果，但很难摘到。远望东北一座城池，南边上去是座石头山。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1995, 'qujing', 'qujing/bibotan/yangchang3', '羊肠小路', '小路很窄，只能容一人侧身而行。路边荆棘从生，一不小心就会在身上挂出伤口。荆棘中生有红色野果，但很难摘到。远望东北一座城池，南边上去是座石头山。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1996, 'qujing', 'qujing/bibotan/yuemen', '月门', '月门恰如一轮满月，将前厅和后院隔开。一般的小妖未经允许是不许到后院的，在此并看不到几个人影。从门缝中传出淡淡的香气，夹杂着些风火雷电的声音，平添几丝诡臆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1997, 'qujing', 'qujing/bibotan/yuetai1', '月台小径', '一条碎石铺成的小路通向潭的深处，小径上的碎石摆成了不同图案，有园月，弯月。。。一路看去，竟是各种各样的月亮。小径被清扫的很干净，向东通到公主和驸马的住所。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1998, 'qujing', 'qujing/bibotan/yuetai2', '月台小径', '一条碎石铺成的小路通向潭的深处，小径上的碎石摆成了不同图案，有园月，弯月。。。一路看去，竟是各种各样的月亮。小径被清扫的很干净，向东通到公主和驸马的住所。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (1999, 'qujing', 'qujing/bibotan/yujie', '玉阶', '一条白玉铺成的玉阶将龙沙台和水晶宫连起。阶的左右立有武士把守。一些鱼精水怪出出入入，水晶宫中灯火通明，似乎正在举行大宴，传出阵阵觥酬交错的声音。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2009, 'qujing', 'qujing/biqiu/bao', '宝殿', '宝殿里万盏烛火通明，镀金紫香炉两边排开，股股青烟祥瑞地慢慢缥缈升起。殿中间是狮虎豹狼熊狐狸百兽皮地毯，上面有一琉璃座牙雕绣珠宝座。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2010, 'qujing', 'qujing/biqiu/caipu', '彩铺', '彩铺里放着各类花草盆景，陈列在货架上，兼卖灯笼彩纸笔墨之类的杂物。。这里的手工制作的花篮花瓶很有名气，曾被比丘国王列为贡品。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2011, 'qujing', 'qujing/biqiu/da', '大殿', '大殿里龙柱凤檐富丽堂皇，南边是鹅黄落地绒，上面用珍珠绣有青松逗红梅，北面是一排白玉窗，窗檐上雕着白鹤飞仙图。往西有铺花道通往宝殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2012, 'qujing', 'qujing/biqiu/daochang', '佛道场', '佛道场为一大厅堂，由十二根黄杨木柱子撑起。两面有通光明窗南北向开设，地上一排排铺着蒲团，有一些佛家道客坐在一起讲佛论道。东边有一门通向大街。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2013, 'qujing', 'qujing/biqiu/dong', '清华洞', '一片烟霞幌亮，日月偷明。洞外云雾飞，洞里翠藓乱漫庭，一边是滑凳攀长蔓，另一边有一小平桥挂着青藤，下有泉水潺潺流过。石屏上有几个大字：“清华仙府”。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2014, 'qujing', 'qujing/biqiu/dongmen', '峒门', '一座城门拔地而起，上面有一青铜大匾，书写着“比丘国”几个大字。杨木城门大开，门上镶着无数条五寸宽铜板，钉满尖头六刃铜钉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2015, 'qujing', 'qujing/biqiu/guan', '官场', '官场位于宫殿一侧，场上有八角雨亭一座，亭前百草仙花郁郁葱葱。西边是宫墙，里面殿阁高耸入云。广场的东北方向与朝门相通。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2016, 'qujing', 'qujing/biqiu/jie1', '街坊', '街面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，略有高低上下。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2017, 'qujing', 'qujing/biqiu/jie10', '街坊', '街坊整个路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，路边有一牛肉馆的招牌。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2018, 'qujing', 'qujing/biqiu/jie11', '街坊', '街道自道场东面绕过，路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边上是的平卵石。街道顺着地势而筑，西边的道场里不时传来人声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2019, 'qujing', 'qujing/biqiu/jie12', '街坊', '街道自道场东面绕过，路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边上是的平卵石。街道顺着地势而筑，西边的道场里不时传来人声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2020, 'qujing', 'qujing/biqiu/jie2', '街坊', '此处街道略窄，路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，略有高低上下。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2021, 'qujing', 'qujing/biqiu/jie3', '街坊', '街坊上停着马车，街道的路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，略有高低上下，南边有一招牌。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2022, 'qujing', 'qujing/biqiu/jie4', '街坊', '街道上晃着酒楼的招牌，街面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直，顺地势而筑，略有高低上下。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2023, 'qujing', 'qujing/biqiu/jie5', '街坊', '这里为三岔路口，整个路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，略有高低上下。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2024, 'qujing', 'qujing/biqiu/jie6', '街坊', '一条街连接着城门与城内，整个路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，略有高低上下。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2025, 'qujing', 'qujing/biqiu/jie7', '街坊', '西临城门，这里是青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直，顺地势而筑略有高低上下。两边可见店铺宅院。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2026, 'qujing', 'qujing/biqiu/jie8', '街坊', '街坊整个路面由青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直且顺着地势而筑，略有高低上下。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2027, 'qujing', 'qujing/biqiu/jie9', '街坊', '广场的北面是青石铺就的街坊，中间是五六尺长两尺宽的三条石，路边是拳头大的平卵石。街道不甚直，顺地势而筑略有高低上下，两边可见店铺，向西是一些宅院。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2028, 'qujing', 'qujing/biqiu/jinqi', '金器店', '这是一家专营金器的金器店，在比丘国十分有名。店内各种金器镶金铜器玲琅满目光彩照人，同时也兼卖其它贵重首饰玉器如意古董。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2029, 'qujing', 'qujing/biqiu/jinting', '金亭馆', '金亭馆为远道而来的客人而设，门有一对招牌红灯笼，屋里有杨木茶桌和几把椅子，墙角有软草席纱罩木床。有几位客人正在馆里休息聊天。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2030, 'qujing', 'qujing/biqiu/jiulou', '酒楼', '酒楼里摆着几张桌子，上面有几碟小菜几盘炒豆。柜台上放着几坛老酒，香气扑鼻令人垂涎。屋角有一木炭烤架，架子上的肉熏得紫红紫红。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2031, 'qujing', 'qujing/biqiu/lin1', '林道', '你行进在铺满树叶的道路上，风萧萧，阳光从稀稀松松的树枝间散射下来。光景苍凉，山高水长道更长，只见是纷纷野花盈径，杂树栖鸟鸟更啼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2032, 'qujing', 'qujing/biqiu/lin2', '林道', '你行进在铺满树叶的道路上，风萧萧，阳光从稀稀松松的树枝间散射下来。光景苍凉，山高水长道更长，只见是纷纷野花盈径，杂树栖鸟鸟更啼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
