INSERT INTO `rooms` VALUES (2036, 'qujing', 'qujing/biqiu/lin6', '林道', '你行进在铺满树叶的道路上，风萧萧，阳光从稀稀松松的树枝间散射下来。光景苍凉，山高水长道更长，只见是纷纷野花盈径，杂树栖鸟鸟更啼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2037, 'qujing', 'qujing/biqiu/lin7', '林道', '你行进在铺满树叶的道路上，风萧萧，阳光从稀稀松松的树枝间散射下来。光景苍凉，山高水长道更长，只见是纷纷野花盈径，杂树栖鸟鸟更啼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2038, 'qujing', 'qujing/biqiu/liu1', '柳林坡', '好一个柳林坡，只见柳树坡上坡下，密密成林荫，柳枝随风轻轻缓缓地飘荡着。远处是一片农作物，正是那：万顷野田观不尽，千堤柳烟隐无踪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2039, 'qujing', 'qujing/biqiu/liu2', '柳林坡', '好一个柳林坡，只见柳树坡上坡下，密密成林荫，柳枝随风轻轻缓缓地飘荡着。远处是一片农作物，正是那：万顷野田观不尽，千堤柳烟隐无踪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2040, 'qujing', 'qujing/biqiu/liu3', '柳林坡', '好一个柳林坡，只见柳树坡上坡下，密密成林荫，柳枝随风轻轻缓缓地飘荡着。远处是一片农作物，正是那：万顷野田观不尽，千堤柳烟隐无踪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2041, 'qujing', 'qujing/biqiu/liu4', '柳林坡', '好一个柳林坡，只见柳树坡上坡下，密密成林荫，柳枝随风轻轻缓缓地飘荡着。远处是一片农作物，正是那：万顷野田观不尽，千堤柳烟隐无踪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2042, 'qujing', 'qujing/biqiu/maowu', '茅屋', '茅屋里有点黑暗，靠墙放着一杨木桌子，上有一盏铜油灯。门前有一水缸盛着半缸清溪水，里面有一蒿草垫子床，铺着一块羊毛毯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2043, 'qujing', 'qujing/biqiu/nanmen', '曩门', '一座城门拔地而起，上面有一青铜大匾，书写着“比丘国”几个大字。杨木城门大开，门上镶着无数条五寸宽铜板，钉满尖头六刃铜钉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2044, 'qujing', 'qujing/biqiu/niurou', '牛肉馆', '牛肉馆里热气腾腾，一阵牛汤香味扑鼻而来。地上铺着蒲团和几张矮脚桌，每个桌子上放着一大瓮牛肉清汤，让食客们随意享受。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2045, 'qujing', 'qujing/biqiu/xiaozi', '小子场', '小子场是一方形青石广场，十分宽敞可行车马列队演练。周围是楼阁殿宇，往南更是祥云瑞气腾腾，旌旗飘扬，乃是比丘国王宫所在。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2046, 'qujing', 'qujing/biqiu/xibei', '溪北', '树林外一股清溪在长坡下徐徐流着，溪上飘着无数青枝花瓣。岸边上有无数柳树轻舒长枝，随风而舞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2047, 'qujing', 'qujing/biqiu/ximen', '阋门', '一座城门拔地而起，上面有一青铜大匾，书写着“比丘国”几个大字。杨木城门大开，门上镶着无数条五寸宽铜板，钉满尖头六刃铜钉。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2048, 'qujing', 'qujing/biqiu/xinan', '溪南', '南岸是一片杨树林，清溪在林外徐徐流着，不时可见溪上飘着青树枝和碎花瓣。风吹过，杨树叶哗啦作响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2049, 'qujing', 'qujing/biqiu/yang1', '杨树', '杨树林里，树木茂盛高大，枝叶青绿斑白。许多树(tree)的根根叉叉交缠在一起，看上去十分奇特。风吹在树上，发出有一点异样的声响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2050, 'qujing', 'qujing/biqiu/yang2', '杨树', '杨树林里，树木茂盛高大，枝叶青绿斑白。许多树(tree)的根根叉叉交缠在一起，看上去十分奇特。风吹在树上，发出有一点异样的声响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2051, 'qujing', 'qujing/biqiu/yang3', '杨树', '杨树林里，树木茂盛高大，枝叶青绿斑白。许多树(tree)的根根叉叉交缠在一起，看上去十分奇特。风吹在树上，发出有一点异样的声响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2052, 'qujing', 'qujing/biqiu/yang4', '杨树', '杨树林里，树木茂盛高大，枝叶青绿斑白。许多树(tree)的根根叉叉交缠在一起，看上去十分奇特。风吹在树上，发出有一点异样的声响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2053, 'qujing', 'qujing/biqiu/yang5', '杨树', '杨树林里，树木茂盛高大，枝叶青绿斑白。许多树(tree)的根根叉叉交缠在一起，看上去十分奇特。风吹在树上，发出有一点异样的声响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2054, 'qujing', 'qujing/biqiu/yu', '玉殿', '殿里一面是玉壁光洁如镜，另外一面是香草廊百花争艳。南边放有绒缎镂花椅，旁边打着一排龙凤扇屏。西边有莲花套窗三六共一十八扇。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2055, 'qujing', 'qujing/biqiu/zhai1', '宅院', '宽敞的宅院里住着几户人家，家家门口是木栅门木帘子，院子里有几棵橙子树，上面结满了金黄色的橙子。树上牵着几根绳子，挂着洗净的衣服。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2056, 'qujing', 'qujing/biqiu/zhai2', '宅院', '方方正正的宅院，石矮墙木栅门，院子里种了一些香草葡萄，中间有一口滚碾石磨，上面晒着一些粮食。几只鸟儿从天上飞下来偷吃粮食。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2057, 'qujing', 'qujing/biqiu/zhaomen', '朝门', '宫殿雄伟琼阁入云，一座淡绿色朝天拱门南北向大开，门楼上飘扬着太平旗。里面就是比丘国的王宫，祥云瑞瑞紫气腾腾，歌舞乐声徐徐传来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2058, 'qujing', 'qujing/biqiu/zhuang', '清华庄', '清华庄是一个小小的空场子，座落在杨树林子里。场子的北面传来阵阵溪水流动的声音，东面有一蒿草茅屋，西边有路通入杨树林子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2073, 'qujing', 'qujing/chechi/banlu1', '石板路', '南城的小丘上整整齐齐地铺着一条石板路，路边种有两排矮树，间有奇花异草。矮树绿枝碧叶，清风徐徐，恰是十分宜人。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2074, 'qujing', 'qujing/chechi/banlu2', '石板路', '南城的小丘上整整齐齐地铺着一条石板路，路边种有两排矮树，间有奇花异草。矮树绿枝碧叶，清风徐徐，恰是十分宜人。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2075, 'qujing', 'qujing/chechi/beiyuan', '北院', '北院里空荡荡，靠墙稀稀拉拉种了一些树，半死不活地长着。北边放有一见底的破水缸。再往北是间破门破窗的房子，往南是金刚殿。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2076, 'qujing', 'qujing/chechi/caichang', '西城菜场', '菜场是车迟国平民购买日常瓜果蔬菜肉类的地方。西边是满地一片瓜皮菜叶，东边有一地的碎骨鸡毛。不远处，有几辆破旧的空大车停在路边。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2077, 'qujing', 'qujing/chechi/cangjing', '藏经楼', '藏经楼里古色古香，门边有一落地铜炉，正在冒着袅袅香烟，门后墙头挂着一些铜铃，靠壁放有一排奇怪的檀香书柜。东南方面有长道通向后殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2078, 'qujing', 'qujing/chechi/da', '大相府', '大相府由青垣石砌成。府外灯笼高挂，府内宽敞明亮富丽堂皇。一看就知是朝廷官人的住宅，朝西有两扇包铜厚门紧闭，大概是通向相府的内院。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2079, 'qujing', 'qujing/chechi/damo', '达摩殿', '达摩殿里空空如也，几张供桌零乱地堆在屋角。墙面龟裂，门窗无存。地上胡乱地铺着干草，上面放着一些破旧蒲团。西北方向有一通道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2080, 'qujing', 'qujing/chechi/dianmen', '殿门', '这里是三清观的殿门，殿门红木青檐翻修一新，门口织锦裹柱且绣有二十二个大字：“雨顺风调，愿祝天尊无量法；河清海晏，祈求万岁有余年。”', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2081, 'qujing', 'qujing/chechi/dong', '东场', '东场在皇宫的东南边，由大块石头东西向三排铺成。往西是相邻的中场，向北伸首可以见到高大的殿阁。这里路人不多且行色匆匆，不敢随便久留。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2082, 'qujing', 'qujing/chechi/dongmen', '东城门', '东城门大开，城楼高耸，车迟国旌旗迎风簌簌飘扬。楼两角筑有石墙箭楼，站有两列弓箭手。楼下护墙借备森严，内有一排穿甲戴盔的刀斧手严阵以待。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2083, 'qujing', 'qujing/chechi/fang', '方丈楼', '方丈楼里简朴干净，只有一方木桌，上面有几本佛经，几个木鱼和木鱼锤。边上有一张长长的木床，叠有几方棉布薄被。南边是木梯，往下通向后殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2084, 'qujing', 'qujing/chechi/feng', '凤阁', '凤阁里挤满了小姐少奶奶，阁檐上绘有两个银羽飞凤，展翅欲飞。阁内一排花莲长椅，配有紫花茶几。一些无事小姐少奶奶们饭后在此叽叽喳喳，品茶消食。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2085, 'qujing', 'qujing/chechi/fengyun', '风云殿', '殿里云霞缭绕，烟雾层叠，仙气十足。殿壁上绘满各种风神云神的画像，神态各异。殿心有一八角香桌，上面燃着九柱麝香，香气扑鼻。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2086, 'qujing', 'qujing/chechi/gong1a', '宫墙', '宫墙雄伟，用大石块堆砌而成，顶端飘着皇家旌旗。每隔一丈就设有一个哨楼，上面有哨兵持矛巡逻。墙下是一条石路，沿墙伸向远方。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2087, 'qujing', 'qujing/chechi/gong1b', '宫墙', '宫墙雄伟，用大石块堆砌而成，顶端飘着皇家旌旗。每隔一丈就设有一个哨楼，上面有哨兵持矛巡逻。墙下是一条石路，沿墙伸向远方。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
