INSERT INTO `rooms` VALUES (2100, 'qujing', 'qujing/chechi/gong5e', '宫墙', '宫墙雄伟，用大石块堆砌而成，顶端飘着皇家旌旗。每隔一丈就设有一个哨楼，上面有哨兵持矛巡逻。墙下是一条石路，沿墙伸向远方。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2101, 'qujing', 'qujing/chechi/gongmen', '宫门', '车迟国宫门南开，门边镶有赤金钉，门上嵌着白玉檐。庄严肃穆。门洞里可供皇家马车双行，门楼上雕砌玉麒麟金龙朱雀，祥云缥缈霞光万道。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2102, 'qujing', 'qujing/chechi/hou', '后殿', '后殿里气氛宁静，灵台高筑，依次摆列着八菩萨的佛象。这里香火也是不断，地上铺着一些旧蒲团。西边殿门通向正殿，往北向上通往方丈楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2103, 'qujing', 'qujing/chechi/houdian', '后殿', '后殿里香烟缭绕，笙竽声不绝，殿内设有一台，上放有铜壶玉简若干。此刻烛光闪闪，灯火通明。向南是三清殿，西北方向是藏经楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2104, 'qujing', 'qujing/chechi/hougong1', '后宫', '后宫里四面宝镜高悬，宫殿的地面由赤铜一字铺开，华贵之极。宫内供着仙果仙花，案上的宝烛辉煌，馥郁真香，真是令人心旷神怡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2105, 'qujing', 'qujing/chechi/hougong2', '后宫', '后宫里四面宝镜高悬，宫殿的地面由赤铜一字铺开，华贵之极。宫内供着仙果仙花，案上的宝烛辉煌，馥郁真香，真是令人心旷神怡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
