INSERT INTO `rooms` VALUES (2107, 'qujing', 'qujing/chechi/jieshi1', '街市', '拥挤的车迟国街市，由碎砖石铺成。人声鼎沸，街景秀丽，令人目不暇己。两边有不少行人来回匆匆走过。偶尔有些小贩沿途边走叫边卖着什么。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
