INSERT INTO `rooms` VALUES (2116, 'qujing', 'qujing/chechi/jieshi9', '街市', '拥挤的车迟国街市，由碎砖石铺成。人声鼎沸，街景秀丽，令人目不暇己。两边有不少行人来回匆匆走过。偶尔有些小贩沿途边走叫边卖着什么。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2117, 'qujing', 'qujing/chechi/jingang', '金刚殿', '金刚殿里残破不堪，光线十分阴暗。几个泥胎已经因为年久失修颜色早就脱落了，台上放着旧香鼎，有气无力地燃着佛香。往东是正殿，东南方向有一通道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2118, 'qujing', 'qujing/chechi/jinluan', '金銮殿', '大殿里灯火通明，金莲御座高高在上。御座前后各有一对玉麒麟守候，两边是缀珠紫红绒帘，华贵之极。殿顶龙飞凤舞，碎玉堆金，紫气浩荡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2119, 'qujing', 'qujing/chechi/jishui', '祭水场', '场上供有一玳瑁镶边的石井，泉水自井中潺潺流出，井边翠竹密生。旱季时这里也是祭水的场所，仙香奇异无比。东边的五色拱门直通坛场。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2120, 'qujing', 'qujing/chechi/jiuguan', '酒馆', '小酒馆里边酒柜齐胸高。后面可以看见三个大酒缸。墙上挂着一些酒葫芦酒袋，案桌上放着大块的熟牛肉。酒保一边招待客人，一边切着熟牛肉。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2121, 'qujing', 'qujing/chechi/leiyu', '雷雨殿', '殿里供着石像，分别为雷雨之神。殿心有一张嵌玉桌，上面插有祈牌祈签。桌边放置有四个绣花软面蒲团，以供王室贵族祈祷时使用。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2122, 'qujing', 'qujing/chechi/long', '龙楼', '龙楼是车迟国公子哥们聚合的场所，楼外门柱上雕有金鳞盘龙一对，楼内摆满八仙桌。这里常有衣着考究的公子王孙整日在此逍遥混日，花天酒地谈东道西。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2123, 'qujing', 'qujing/chechi/miyuan1', '秘院', '这里是一座秘密的四方庭院，四周是高墙。院内阴气习习，罂粟盛开。南边是藏经楼的后墙，墙下有一暗通道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
