INSERT INTO `rooms` VALUES (2132, 'qujing', 'qujing/chechi/qiang1a', '城墙', '高大的城墙，有三丈多高，由灰岩夹黄土筑成。城墙上斑斑驳驳，看起来已经有些年代了，沿着长长的墙铺有一条结实的土石路，可以行人走车。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
