INSERT INTO `rooms` VALUES (2152, 'qujing', 'qujing/chechi/qiang7f', '城墙', '高大的城墙，有三丈多高，由灰岩夹黄土筑成。城墙上斑斑驳驳，看起来已经有些年代了，沿着长长的墙铺有一条结实的土石路，可以行人走车。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2153, 'qujing', 'qujing/chechi/qiang7g', '城墙', '高大的城墙，有三丈多高，由灰岩夹黄土筑成。城墙上斑斑驳驳，看起来已经有些年代了，沿着长长的墙铺有一条结实的土石路，可以行人走车。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2154, 'qujing', 'qujing/chechi/qiyu', '祈雨场', '场上有一玉池，水波微荡，金莲朵朵在池里争艳。这里是旱季祈祷龙王降雨的场所，周围彩墙绘有雾峰云海。西边有一五色拱门通向坛场。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2155, 'qujing', 'qujing/chechi/ruizhao', '瑞兆场', '一个以细砖铺就的小广场，场周围种了一圈苦椹树，由于缺水树木已经有些干枯了。这里是车迟国的闹市区之一，行人来来往往络绎不绝。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2156, 'qujing', 'qujing/chechi/sanqing', '三清殿', '殿内左有大鼓右有铜钟，中间是一石案，上面是五色花瓶和青石烛台，供有不少丰盛斋宴。四壁功德悬挂，殿心分别是元始天尊，灵宝道君和太上老君。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2157, 'qujing', 'qujing/chechi/shanlu1', '山路', '城内的小山坡上斜斜地筑了一条土小路，弯弯曲曲盘旋而上。因年久失修的缘故，路面坎坷凸凹不平。路边早已是乱草丛生，杂石竖横。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2158, 'qujing', 'qujing/chechi/shanlu2', '山路', '城内的小山坡上斜斜地筑了一条土小路，弯弯曲曲盘旋而上。因年久失修的缘故，路面坎坷凸凹不平。路边早已是乱草丛生，杂石竖横。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2159, 'qujing', 'qujing/chechi/shanlu3', '山路', '城内的小山坡上斜斜地筑了一条土小路，弯弯曲曲盘旋而上。因年久失修的缘故，路面坎坷凸凹不平。路边早已是乱草丛生，杂石竖横。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2160, 'qujing', 'qujing/chechi/shanlu4', '山路', '城内的小山坡上斜斜地筑了一条土小路，弯弯曲曲盘旋而上。因年久失修的缘故，路面坎坷凸凹不平。路边早已是乱草丛生，杂石竖横。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2161, 'qujing', 'qujing/chechi/shatan1', '沙滩', '这里气候干燥，土地龟裂。中间是一片沙滩，被人踩出一条大路，路上压有几条大车轱辘碾出的深深痕迹，路边零星散有一些残破的砖石木料。这里气候干燥，土地龟裂。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2162, 'qujing', 'qujing/chechi/shatan2', '沙滩', '这里气候干燥，土地龟裂。中间是一片沙滩，被人踩出一条大路，路上压有几条大车轱辘碾出的深深痕迹，路边零星散有一些残破的砖石木料。这里气候干燥，土地龟裂。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2163, 'qujing', 'qujing/chechi/shatan3', '沙滩', '这里气候干燥，土地龟裂。中间是一片沙滩，被人踩出一条大路，路上压有几条大车轱辘碾出的深深痕迹，路边零星散有一些残破的砖石木料。这里气候干燥，土地龟裂。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2164, 'qujing', 'qujing/chechi/shatan4', '沙滩', '这里气候干燥，土地龟裂。中间是一片沙滩，被人踩出一条大路，路上压有几条大车轱辘碾出的深深痕迹，路边零星散有一些残破的砖石木料。这里气候干燥，土地龟裂。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2165, 'qujing', 'qujing/chechi/shatan5', '沙滩', '这里气候干燥，土地龟裂。中间是一片沙滩，被人踩出一条大路，路上压有几条大车轱辘碾出的深深痕迹，路边零星散有一些残破的砖石木料。这里气候干燥，土地龟裂。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2166, 'qujing', 'qujing/chechi/shutang', '书堂', '书堂中间有一方桌，上有两卷摊开的绢书。墙上贴有几幅长长的字画，灯龛里烛光闪闪。四周放满了布面毡底圆蒲团，供客人们闲座。地上隔不远就置一个矮脚几，放有铜壶陶碗。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2167, 'qujing', 'qujing/chechi/simen', '寺门', '山前有一座破旧的寺庙，已经退色的门半掩半开，落满了蛛网灰尘。似乎这里很久已经没有什么香客光临了。门上的大匾隐隐约约可见“智渊寺”几个金字。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2168, 'qujing', 'qujing/chechi/taiping', '太平场', '太平场以碎砖铺成，场子不太大。场心有破旧的泥土祭坛，上面稀稀拉拉地长了一些枯草。这里算是车迟国的比较热闹的地段，穿着朴素的行人在场上走过。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2169, 'qujing', 'qujing/chechi/tan', '坛场', '无数玉坛一线排开，中间有一黄铜大鼎。风摇青树，瑞草齐生，生气勃然。左右各有一五色拱门相通，西边是祭水场，东边是祈雨场。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2170, 'qujing', 'qujing/chechi/tangchi', '汤池', '屋子里散着热腾腾的蒸气，夹杂有柴烟的味道。四周的石墙已被熏得有点发黑，墙角架有一排大铁锅，锅边有木架子供人上下进出，上面搭着一些毛边干浴巾。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2171, 'qujing', 'qujing/chechi/wufeng', '五凤楼', '楼里设有五凤，各为赤橙青绿紫色。神态栩栩如生，欲飞欲留。楼上传来丝竹之声，香云缭绕，气氛极为祥和无比。北面通往金銮殿，南面通向坛场。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2172, 'qujing', 'qujing/chechi/wugu', '五谷轮回', '屋子里光线阴暗，墙壁潮湿，里面似乎什么也看不清。门口有几大柱粗香冒着浓烟，边上有一小凳，上面放有一叠一叠的粗糙草纸。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2173, 'qujing', 'qujing/chechi/xi', '西场', '西场用大块石头东西向三排铺成，位于车迟皇宫的西南边，往西是比较热闹的城区，往东则是中场，从这里往北看，可以见到皇宫的殿阁。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2174, 'qujing', 'qujing/chechi/xiang1', '厢廊', '长长的厢廊，两边是镶花气窗，廊檐上挂有串串铜铃，随风叮当。地上铺有一条素色布毯，厢廊的西南方向是三清殿，东边通往厢房。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2175, 'qujing', 'qujing/chechi/xiang2', '厢房', '厢房里整整齐齐，南北各有一红砖大炕，铺着锦花棉被。炕上有硬木炕桌，放有茶锺瓷碗。墙上有一些字画，写着：“一诚达上，寸敬虔归。”', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2176, 'qujing', 'qujing/chechi/xiang3', '厢房', '厢房里整整齐齐，南北各有一红砖大炕，铺着锦花棉被。炕上有硬木炕桌，放有茶锺瓷碗。墙上有一些字画，写着：“罗天大醮，彻夜看经。”', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2177, 'qujing', 'qujing/chechi/xiao', '小相府', '小相府门口放着一紫檀木武器架，朝南开有一排莲花窗，朝西靠墙设有仙桌仙椅，上面供有时鲜水果。北面是一排白底彩染绸缎面屏风，将堂屋隔开。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2178, 'qujing', 'qujing/chechi/ximen', '西城门', '西城门紧闭，城楼高耸，车迟国旌旗迎风簌簌飘扬。楼两角筑有石墙箭楼，站有两列弓箭手。楼下护墙借备森严，内有一排穿甲戴盔的刀斧手严阵以待。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2179, 'qujing', 'qujing/chechi/xinshi', '新市口', '新市口向北通往富贵人家的住宅区。街口宽敞，路面用石砖铺就，这里相对比较安静干净。路上行人略少一点，有时可以见到一两辆遮棚马车驶过。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2180, 'qujing', 'qujing/chechi/xitai', '戏台', '这里屋深幽暗，屋子西端搭有一座精巧但已有点退色的戏台。戏台两边挂有数盏明亮的灯笼。前几排有些矮凳，后面是一些红油茶桌和宽背扶手椅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2181, 'qujing', 'qujing/chechi/yanhua', '烟花院', '烟花院已有些年头了，院门漆成大彩红色，里面香气扑鼻，各种摆设琳琅满目，桌上放有丝琴竹箫。从关闭的里屋门后隐隐传来女人笑唱的声音。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2182, 'qujing', 'qujing/chechi/zhai', '斋房', '三清观的斋房设在殿前，斋房宽大，设有一大红木斋桌。房内无灶无锅。因车迟国内文武官员爱道成风，大小男女前来拜请奉斋络绎不觉，这里善斋不断。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2183, 'qujing', 'qujing/chechi/zhaifang', '斋房', '斋房里砌了一大泥灶，上面支着一口大铁锅，灶边是两个水桶和一些干柴。木台上放着一些粗瓷碗，还有几只木凳。南边有一门通向院子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2184, 'qujing', 'qujing/chechi/zhaomen', '朝门', '朝门祥光笼罩，东边设有一只金钟，西边设有一面银鼓，门下百种奇花异草怒放。门上是透亮琉璃瓦，门道由黛色罗纹细密石条一路铺平。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2185, 'qujing', 'qujing/chechi/zheng', '正殿', '正殿雕梁画栋，佛祖在中间的宝座上高供，两边是无数阿罗，揭谛。香炉青烟袅袅，殿堂虽是旧了些，倒也打扫一净。往东便是后殿，西边通向金刚殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2186, 'qujing', 'qujing/chechi/zhong', '中场', '中场在皇宫的南面，用大块石头铺成，向北是皇宫的入口，飘着车迟国的旌旗。每天钟鸣时分，有士兵出场演武操练。东面是东场，西面是西场。', '/d/qujing/chechi', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2210, 'qujing', 'qujing/dudi/dongkou', '洞口', '一个藤蔓丛生的山崖深处出现一个洞口，洞里冒着雾气，如袅袅的白烟一般。高高的石崖上刻着六个醒目的大字：“毒敌山琵芭洞”，往东南方向有一入口。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2211, 'qujing', 'qujing/dudi/dongting', '洞厅', '一座空旷的大厅，厅子的中间燃着一堆篝火，几个小妖正在围着篝火大口地吃肉。洞厅的西北面有光亮传来，厅南有一小道通往花亭子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2212, 'qujing', 'qujing/dudi/dudi1', '毒敌山', '毒敌山脉在一望无际的视野里起伏，山峰峻险，不时可见脚下雾气腾起如生云一般。山上，石岩石崖间开辟出一条小路弯曲而上，路的西边是万丈深崖，令人胆寒。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2213, 'qujing', 'qujing/dudi/dudi2', '毒敌山', '毒敌山脉在一望无际的视野里起伏，山峰峻险，不时可见脚下雾气腾起如生云一般。山上，石岩石崖间开辟出一条小路弯曲而上，路的西边是万丈深崖，令人胆寒。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2214, 'qujing', 'qujing/dudi/dudi3', '毒敌山', '毒敌山脉在一望无际的视野里起伏，山峰峻险，不时可见脚下雾气腾起如生云一般。山上，石岩石崖间开辟出一条小路弯曲而上，路的西边是万丈深崖，令人胆寒。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2215, 'qujing', 'qujing/dudi/dudi4', '毒敌山', '毒敌山脉在一望无际的视野里起伏，山峰峻险，不时可见脚下雾气腾起如生云一般。山上，石岩石崖间开辟出一条小路弯曲而上，路的西边是万丈深崖，令人胆寒。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2216, 'qujing', 'qujing/dudi/erdong', '二洞门', '二洞门比一洞门略小一点，洞门里是犬牙交错的怪石，从洞顶上倒垂下来。东北方向有一通道引向一洞门，南边有入口通向洞里。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2217, 'qujing', 'qujing/dudi/huating', '花亭子', '洞里的空厅边有一六角石花亭子，亭柱边种满了各种各样的奇花异草，散发出异香。亭上有一圆石桌，六只圆石凳，花亭子的东面是内宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2218, 'qujing', 'qujing/dudi/neigong', '内宫', '内宫是一方洞，洞里铺满了软花草，宫北的石墙上挂着彩色凤尾帘，墙下放着一香木梳妆台，台上有银面镜。内宫的西面有一出口通往花亭子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2219, 'qujing', 'qujing/dudi/sandong', '三洞门', '三洞门里气氛严肃，戒备森严，一群大小妖精聚在一起守候在门边。门的左边有一高大的石鼓，右边是一面铜花锣。东南边通向里面的洞厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2220, 'qujing', 'qujing/dudi/shanlu1', '山路', '一条山路蜿蜿蜒蜒盘山而上，山路边杂草丛生野花生艳。杂草后面露出奇石岩，爬着青藤绿蔓。远山蒙笼，云雾在远谷里起伏飘散。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
