INSERT INTO `rooms` VALUES (2230, 'qujing', 'qujing/dudi/yidong', '一洞门', '一个天然形成的石头门，门上的石桥上有藤蔓挂下来，门的两边长着奇松怪柏，从里面漫出一股股浓烈的兽妖气，使人有点头昏目眩。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2235, 'qujing', 'qujing/fengxian/dalu1', '大路', '路遥遥，道幽幽，这里的大路又长又远。天边有云山雾海，近处是荒芜的农田，偶尔可见到一些小溪小河，均已干涸见底，路边大树枝枯叶落，草黄土裂。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
