INSERT INTO `rooms` VALUES (2243, 'qujing', 'qujing/fengxian/dalu9', '大路', '路遥遥，道幽幽，这里的大路又长又远。天边有云山雾海，近处是荒芜的农田，偶尔可见到一些小溪小河，均已干涸见底，路边大树枝枯叶落，草黄土裂。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2244, 'qujing', 'qujing/fengxian/daochang', '道场', '道场乃新建的施法布道之处，四周是通明窗，南边有一宽槛门，北面是颂法台。场地为拼花木头，上面铺开素布地毯。场外有一铜钟，每两时辰便鸣钟数响。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2245, 'qujing', 'qujing/fengxian/diaoqiao', '吊桥', '一座城楼耸立，两边是石墙，上有兵士持枪巡逻。墙下有一条宽宽的护城河床，已经见底了，河上架着铁链吊桥。城楼上有一牌子：“凤仙郡”。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2246, 'qujing', 'qujing/fengxian/guanmao', '冠帽店', '冠帽店里红梁白墙，里面有大小货架两对四个。一个大匾上写着：本店出售各类冠帽首饰针线。但见货架上空空如也，挂了一个小牌：店主仗义施财祭雨，已尽家产。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2247, 'qujing', 'qujing/fengxian/jiedao1', '街道', '街道一丈来宽，民事冷落，店铺倒闭，街上走着一些无精打采的官人，以及零零散散的面黄饥瘦的饥民与衣裳褴褛的乞丐。令人有点惨不忍睹。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
