INSERT INTO `rooms` VALUES (2260, 'qujing', 'qujing/fengxian/jiedao9', '街道', '街道一丈来宽，民事冷落，店铺倒闭，街上走着一些无精打采的官人，以及零零散散的面黄饥瘦的饥民与衣裳褴褛的乞丐。令人有点惨不忍睹。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2261, 'qujing', 'qujing/fengxian/jitan', '祭坛', '一座由楠木建筑的坛场，地上铺有青砖，上有无数蒲团。坛台由红砖砌成，分下中上三层坛阶。台上供有紫铜香鼎，烟火不断，青雾袅袅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2262, 'qujing', 'qujing/fengxian/jiuguan', '酒馆', '酒馆为一双檐小木楼，馆门口的酒字招牌已摘掉。里面木桌和木椅擦得干干净净，柜台上竖着一牌子，上有：“戒酒祭雨，免费供茶”八个大字。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2263, 'qujing', 'qujing/fengxian/junhou', '郡侯衙', '郡侯衙气氛庄严，四周是紫红凤仙屏风，中间有一檀香高座，摆了一把玉锦镂花椅。这里原是郡主的内堂，因来客与日俱增，便将前堂移至此，改为郡侯衙。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2264, 'qujing', 'qujing/fengxian/ludian', '履店', '这里是凤仙郡一家颇有名气的鞋店，专售各式各样布履草鞋木屐皮靴，另外代售一些巾帕之类的用品。店里已无货物，据说主人已出任求雨法师，由堂弟暂管铺面。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2265, 'qujing', 'qujing/fengxian/puji', '普济寺', '普济寺门口前挤满了面黄饥瘦的灾民，在等待寺里一天一次的开众施舍。寺里面有几位虔诚的客人在烧香，寺后传来一阵阵木鱼声。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2266, 'qujing', 'qujing/fengxian/shang', '上官府', '上官府位于郡南，府前有双狮护门。府内灯火通明，左右各放了两个临时搭起的祭台，上有新铸银花香炉，香烟缭绕终日不断，以示官府求雨的决心。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2267, 'qujing', 'qujing/fengxian/shantang', '膳堂', '膳堂是两层饭店，装璜布置十分讲究，楼上楼下各有仙桌仙椅无数，门口有一凤仙雕花屏风。但堂内无一食客，传言此家不顾官府禁令，借灾抬价发财已被查封。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2268, 'qujing', 'qujing/fengxian/shien', '施恩堂', '施恩堂里有三对红漆麒麟柱，屋顶上吊下莲花灯，北面和西面有数窗，外有亭有石。这里原是上官郡主读书的地方，现在专门用以接待祈雨法师。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2269, 'qujing', 'qujing/fengxian/shikou', '市口', '凤仙郡的闹市区，此地各色人等来来往往，更有一些人围在街心伸头踮脚读着一帖榜文： “大天竺国凤仙郡郡侯上官，为榜聘明师，招求大法事。 慈因郡土宽弘，军民殷实，连年亢旱，累岁干荒。富 室聊以全生，穷民难以活命。为此出给榜文，仰望十 方贤哲，祷雨救民，恩当重报。须至榜首。”', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2270, 'qujing', 'qujing/fengxian/shuode', '硕德堂', '硕德堂里有六根绿色凤凰柱，四周摆满香草花坛。屋中有一对太师椅，墙边是一溜兽皮靠背椅。此堂乃是郡主休息品茶的专厅，现用作以接待祭雨贤哲的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2271, 'qujing', 'qujing/fengxian/xiang', '香庙', '香庙建在城墙角下，红砖青瓦木檐。庙里面墙壁上挂着雷神，雨神，龙神等各种神龛。靠背墙有一长长的旧彩木仙桌，上面几个香炉正在冒着丝丝香烟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2272, 'qujing', 'qujing/fengxian/zhaishi', '斋室', '这里原为迎客栈的雅室，因客栈主人近来施财求雨，已将此雅室改为供远道而来的客人稍事休息的地方。屋子里有一木桌和一木床。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2273, 'qujing', 'qujing/fengxian/zhaizhan', '斋栈', '斋栈原为凤仙郡迎客栈，因久旱无雨，栈主便将此栈改为斋栈以示皈依之诚心。斋栈里为客免费提供饮用水，里屋为斋室，为路客提供垫饥的小食。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2277, 'qujing', 'qujing/firemount/cuiyun1', '翠云山', '山中林木葱葱，青草郁郁。一派鸟语花香的景象。山势巍峨高耸，山腰白云袅绕，真似那世外桃源，海上蓬莱。林中隐隐传来丁丁丁伐木之声。路边是一堆一堆乱七八糟的树枝，看上去好象曾被人翻动过。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2278, 'qujing', 'qujing/firemount/cuiyun2', '翠云山', '山中林木葱葱，青草郁郁。一派鸟语花香的景象。山势巍峨高耸，山腰白云袅绕，真似那世外桃源，海上蓬莱。林中隐隐传来丁丁丁伐木之声。路边是一堆一堆乱七八糟的树枝，看上去好象曾被人翻动过。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2279, 'qujing', 'qujing/firemount/cuiyun3', '翠云山', '山中林木葱葱，青草郁郁。一派鸟语花香的景象。山势巍峨高耸，山腰白云袅绕，真似那世外桃源，海上蓬莱。林中隐隐传来丁丁丁伐木之声。路边是一堆一堆乱七八糟的树枝，看上去好象曾被人翻动过。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2280, 'qujing', 'qujing/firemount/cuiyun4', '翠云山', '山中林木葱葱，青草郁郁。一派鸟语花香的景象。山势巍峨高耸，山腰白云袅绕，真似那世外桃源，海上蓬莱。林中隐隐传来丁丁丁伐木之声。路边是一堆一堆乱七八糟的树枝，看上去好象曾被人翻动过。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2281, 'qujing', 'qujing/firemount/cuiyun5', '翠云山', '山中林木葱葱，青草郁郁。一派鸟语花香的景象。山势巍峨高耸，山腰白云袅绕，真似那世外桃源，海上蓬莱。林中隐隐传来丁丁丁伐木之声。路边是一堆一堆乱七八糟的树枝，看上去好象曾被人翻动过。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2282, 'qujing', 'qujing/firemount/dongkou', '芭蕉洞口', '你一抬头，见已经来到一个巨大的洞口，洞的形状犹如一个怪兽的大嘴。洞门紧闭牢关，洞外风光秀丽。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2283, 'qujing', 'qujing/firemount/dongnei', '洞内', '洞里一片漆黑，你什么也看不清，似乎觉得有许多眼睛在黑暗中盯着你。你环顾四周，模模糊糊分辨出一个一个的影子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2284, 'qujing', 'qujing/firemount/hongse', '红色庄院', '你一定睛，发现这里一片红色：红瓦盖的房舍，红砖砌的垣墙，红油门扇，红漆板榻，都是红的。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2285, 'qujing', 'qujing/firemount/hongyan', '红岩潭', '一面大大的崖壁将一泓潭水环绕，北面有一个出口通向山外。这里离火焰山顶已经有一段距离了，又是在潭水边，令人精神特别愉快。你禁不住深吸一口气，心旷神怡。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2286, 'qujing', 'qujing/firemount/huoyan', '火焰山', '火，火，火！！！大火绵延八百里，四周寸草不生。据说当年太上老君的炼丹炉被蹬翻，几块炉砖掉在此处，即化为火焰山。人一走进去既成烟灰，更勿提东南西北。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2287, 'qujing', 'qujing/firemount/luzhou', '沙漠绿洲', '这里四季常热，远不似西北边陲的景象。不想依然水草肥美，五谷年年照收。当地百姓安居乐业，倒也怡然自得。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2288, 'qujing', 'qujing/firemount/luzhou2', '沙漠绿洲', '这里四季常热，远不似西北边陲的景象。不想依然水草肥美，五谷年年照收。当地百姓安居乐业，倒也怡然自得。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2289, 'qujing', 'qujing/firemount/luzhou3', '沙漠绿洲', '这里四季常热，远不似西北边陲的景象。不想依然水草肥美，五谷年年照收。当地百姓安居乐业，倒也怡然自得。旁边还有一小井，想是为了取水的。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2290, 'qujing', 'qujing/firemount/nofire', '火焰山', '大火已经被人扑灭了，四处还冒着一丝丝的残烟。曾几何时这里的大火绵延八百里，四周寸草不生。据说当年太上老君的炼丹炉被蹬翻，几块炉砖掉在此处，即化为火焰山。人一走进去既成烟灰，更勿提东南西北。现在一切都很平静了，你走在这里，感叹不已。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2291, 'qujing', 'qujing/firemount/qujinglu', '取经路', '你陷入一大片荒沙漠的世界，环顾四周，四处都是黄沙，高高低低，很难从中找出路来。你心里有点紧张。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2292, 'qujing', 'qujing/firemount/shalu', '砂砾径', '小径至此分岔，往西通向火焰山，西南的小道蜿蜒曲折，不知通向何处。山上的热浪一阵阵的涌来。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2293, 'qujing', 'qujing/firemount/shalu2', '砂砾径', '小径往东是一片绿洲，往西通向山里，站在小径边上，已经可以感觉到山上的热浪一阵阵地涌来。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2294, 'qujing', 'qujing/firemount/shanbian', '山边', '越往西越是燥热难忍，西边便是令人色变的火焰山。四野一片红黄色的荒凉，到处是烤得发红的碎石和砂土。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2295, 'qujing', 'qujing/firemount/shanwai', '山外小路', '你突然到了火焰山的西北面，东南面是红通通的火焰山顶。空气中有一种强烈的糊味，热得让人难以忍受。北方有一条小径，通向山下阴凉处。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2296, 'qujing', 'qujing/firemount/shimen', '石洞门', '洞门由两块大石板依山势修葺而成。旁有一堆乱石(stone)，似是为封严洞门时准备的。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2297, 'qujing', 'qujing/firemount/south1', '小山南坡', '山坡上乱石丛生，零零星星地长着些杂草，不时会有几只野兔从石堆中跃出。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2298, 'qujing', 'qujing/firemount/south2', '小山南坡', '山坡上乱石丛生，零零星星地长着些杂草，不时会有几只野兔从石堆中跃出。东南不远处是一座小庙，似是歇脚的好去处。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2299, 'qujing', 'qujing/firemount/south3', '山脚', '这里是山脚，道路十分泥泞，杂草丛生。南面是翠云山，往北翻过一座小山丘便是火焰山。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2300, 'qujing', 'qujing/firemount/wuming', '无名小山', '山顶上什么也没有，山的南麓是一堆乱石，间或可以见到几只野兔。再往南去便是翠云山了。北面被大火烤得一片通红。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2301, 'qujing', 'qujing/firemount/wuming1', '无名小路', '无名小路蜿蜒曲折，前面可看到一座小光秃秃的山丘，四周不见一点生机，只有红色的砂石。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2302, 'qujing', 'qujing/firemount/wuming2', '无名小路', '无名小路蜿蜒曲折，前面可看到一座小光秃秃的山丘，四周不见一点生机，只有红色的砂石。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2303, 'qujing', 'qujing/firemount/wuming3', '无名小路', '无名小路蜿蜒曲折，前面可看到一座小光秃秃的山丘，四周不见一点生机，只有红色的砂石。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2304, 'qujing', 'qujing/firemount/wuming4', '无名小路', '前面就是山顶了，隐约可见山那边是一座高山。山上白云如烟，别是一番天地。', 'firemount', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2305, 'qujing', 'qujing/firemount/xiaodian', '小店', '这是绿洲上的一家小店，卖的物品和大唐东土不大一样。店主是一少年男子，常推着小车四处叫卖。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2306, 'qujing', 'qujing/firemount/xiaomiao', '土地庙', '土地庙里有两尊泥像，塑像剥落不堪，看来很少有人来这进香上供。西北山坡挡住了火焰山的热浪，这儿便成了行路人歇脚的好去处，几个行人正在这打尖歇脚。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2313, 'qujing', 'qujing/jilei/cangku', '仓库', '石头仓库不是很大，用于堆放武器，工具，肉干肉巴子之类的储备物。现在仓库里空空如也，地上散着一些乱糟糟的干草和不成块的碎兽皮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2314, 'qujing', 'qujing/jilei/canting', '餐厅', '餐厅是一个石洞自然形成的偏厅，厅角支着一口大铁锅，底下烧着大火。铁锅边有一铁架，上面的肉巴子烤得直冒油，散发出诱人的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2315, 'qujing', 'qujing/jilei/dating', '大厅', '一个大如宫殿的大厅，厅的中间摆满了石桌石椅，厅的石壁上挂着兽油铜灯。大厅的西面传来烤肉的香味，东南有一通向里面的通道，往东北方向有一石廊。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2316, 'qujing', 'qujing/jilei/jilei1', '积雷山', '万丈山崖如刀削一般，群峰峦奇形怪状似犬牙交错。山凹里弥漫着一股股浓烈的缥缈雾气，阴风呼啸，空谷回音。野兽的吼叫声已经很近了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2317, 'qujing', 'qujing/jilei/jilei2', '积雷山', '万丈山崖如刀削一般，群峰峦奇形怪状似犬牙交错。山凹里弥漫着一股股浓烈的缥缈雾气，阴风呼啸，空谷回音。野兽的吼叫声已经很近了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2318, 'qujing', 'qujing/jilei/jilei3', '积雷山', '万丈山崖如刀削一般，群峰峦奇形怪状似犬牙交错。山凹里弥漫着一股股浓烈的缥缈雾气，阴风呼啸，空谷回音。野兽的吼叫声已经很近了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2319, 'qujing', 'qujing/jilei/shan1', '山道', '只见山高路险，岭上或是光秃秃奇岩怪峥嵘一片，或是树木成森林，大风呼啸地吹过，又听得野猿虎豺远远地长吼，有点令人胆颤心惊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2320, 'qujing', 'qujing/jilei/shan10', '山道', '只见山高路险，岭上或是光秃秃奇岩怪峥嵘一片，或是树木成森林，大风呼啸地吹过，又听得野猿虎豺远远地长吼，有点令人胆颤心惊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
