INSERT INTO `rooms` VALUES (2327, 'qujing', 'qujing/jilei/shan7', '山道', '只见山高路险，岭上或是光秃秃奇岩怪峥嵘一片，或是树木成森林，大风呼啸地吹过，又听得野猿虎豺远远地长吼，有点令人胆颤心惊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2328, 'qujing', 'qujing/jilei/shan8', '山道', '只见山高路险，岭上或是光秃秃奇岩怪峥嵘一片，或是树木成森林，大风呼啸地吹过，又听得野猿虎豺远远地长吼，有点令人胆颤心惊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2329, 'qujing', 'qujing/jilei/shan9', '山道', '只见山高路险，岭上或是光秃秃奇岩怪峥嵘一片，或是树木成森林，大风呼啸地吹过，又听得野猿虎豺远远地长吼，有点令人胆颤心惊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2330, 'qujing', 'qujing/jilei/shidong', '石洞门', '山崖下青藤高挂，蒿草丛生，自石岩缝隙中间裂开一个大洞，洞口云雾缭绕，上面有一白石大匾，书有：“积雷山摩云洞”六个大字。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2331, 'qujing', 'qujing/jilei/shilang', '石廊', '石廊里极为宽敞，从洞顶上悬下长藤青蔓，石廊两边有大小石块宛如自然而成的桌椅。石廊的西北方向有光线从洞外射进来，石廊的西南面有一个大厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2332, 'qujing', 'qujing/jilei/woshi', '卧室', '卧室里面摆设精美，一个花石案上摆着稀罕的玉玩物，墙边立着一个雕镂紫檀长柜，后面的墙上挂着麒麟皮龙角。西北方面有一门通向外面。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2344, 'qujing', 'qujing/jindou/dongnei1', '洞内', '宽敞的洞内雾气腾腾，洞顶上长着粗长的青藤，从头上挂下来。洞壁插着兽油火把，吱吱地冒着烟，将洞内照亮。洞的地上填得平平整整，铺着一块一块石板。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2345, 'qujing', 'qujing/jindou/dongnei2', '洞内', '宽敞的洞内雾气腾腾，洞顶上长着粗长的青藤，从头上挂下来。洞壁插着兽油火把，吱吱地冒着烟，将洞内照亮。洞的地上填得平平整整，铺着一块一块石板。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2346, 'qujing', 'qujing/jindou/dongnei3', '洞内', '宽敞的洞内雾气腾腾，洞顶上长着粗长的青藤，从头上挂下来。洞壁插着兽油火把，吱吱地冒着烟，将洞内照亮。洞的地上填得平平整整，铺着一块一块石板。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2347, 'qujing', 'qujing/jindou/dongnei4', '洞内', '宽敞的洞内雾气腾腾，洞顶上长着粗长的青藤，从头上挂下来。洞壁插着兽油火把，吱吱地冒着烟，将洞内照亮。洞的地上填得平平整整，铺着一块一块石板。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2348, 'qujing', 'qujing/jindou/jindou1', '金兜山', '万山丛中，脚下的险峰在云海中露峥嵘，山峰之上雾气缭绕彩虹飞舞。森林之中时时有猛兽的怒吼之声震撼山谷，使人不禁迟疑地放慢脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2349, 'qujing', 'qujing/jindou/jindou2', '金兜山', '万山丛中，脚下的险峰在云海中露峥嵘，山峰之上雾气缭绕彩虹飞舞。森林之中时时有猛兽的怒吼之声震撼山谷，使人不禁迟疑地放慢脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2350, 'qujing', 'qujing/jindou/jindou3', '金兜山', '万山丛中，脚下的险峰在云海中露峥嵘，山峰之上雾气缭绕彩虹飞舞。森林之中时时有猛兽的怒吼之声震撼山谷，使人不禁迟疑地放慢脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2351, 'qujing', 'qujing/jindou/jindou4', '金兜山', '万山丛中，脚下的险峰在云海中露峥嵘，山峰之上雾气缭绕彩虹飞舞。森林之中时时有猛兽的怒吼之声震撼山谷，使人不禁迟疑地放慢脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2352, 'qujing', 'qujing/jindou/shanlu1', '山路', '山路弯曲在群山峻岭之中来回起伏绕行，两边是爬满苔藓的山岩，岩石缝里长出苍松翠柏。路上尽是碎石野草，不时有一些枯枝藤蔓绊脚。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
