INSERT INTO `rooms` VALUES (2359, 'qujing', 'qujing/jindou/shanlu8', '山路', '山路弯曲在群山峻岭之中来回起伏绕行，两边是爬满苔藓的山岩，岩石缝里长出苍松翠柏。路上尽是碎石野草，不时有一些枯枝藤蔓绊脚。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2360, 'qujing', 'qujing/jindou/shanshi1', '山石冈', '山石冈四处是碎石块，石块的缝隙里长出一些杂草。路的两边为赫色的山岩，尖锋利刃。石冈远远近近地长着一些古树，在山风中摇曳。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2361, 'qujing', 'qujing/jindou/shanshi2', '山石冈', '山石冈四处是碎石块，石块的缝隙里长出一些杂草。路的两边为赫色的山岩，尖锋利刃。石冈远远近近地长着一些古树，在山风中摇曳。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2362, 'qujing', 'qujing/jindou/shidong', '石洞', '一个巨大的石洞出现在眼前，石洞上有“金兜山”几个大字。洞里烟雾缭绕，有一股股妖气从洞里漫出。石洞的东北面是一开阔地带，南边通向里洞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2380, 'qujing', 'qujing/jingjiling/bolin', '柏林', '柏林之中古柏森森，望去树木皆有百年之龄，挺直修长。树皮上有风霜偶现，枝叶上淡挂绿萝。树木紧列如密密的屏障，林之深处不可一见。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2381, 'qujing', 'qujing/jingjiling/huilin', '桧林', '桧林之中皆是古桧，，望去树木皆有百年之龄，挺直修长。树皮上有风霜偶现，枝叶上淡挂绿萝。树木紧列如密密的屏障，林之深处不可一见。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2382, 'qujing', 'qujing/jingjiling/jingji1', '荆棘岭', '岭上荆棘丫叉，薜箩牵绕。下面虽是有道路的痕迹，左右却都是荆辞棘针，除是蛇虫伏地而游，方可过去。周围人烟稀少，空山但闻鸟语猿啼不绝。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2383, 'qujing', 'qujing/jingjiling/jingji2', '荆棘岭', '岭上荆棘丫叉，薜箩牵绕。下面虽是有道路的痕迹，左右却都是荆辞棘针，除是蛇虫伏地而游，方可过去。周围人烟稀少，空山但闻鸟语猿啼不绝。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
