INSERT INTO `rooms` VALUES (2389, 'qujing', 'qujing/jingjiling/jingji8', '荆棘岭', '岭上荆棘丫叉，薜箩牵绕。下面虽是有道路的痕迹，左右却都是荆辞棘针，除是蛇虫伏地而游，方可过去。周围人烟稀少，空山但闻鸟语猿啼不绝。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2390, 'qujing', 'qujing/jingjiling/ping', '萝藤坪', '这里独有方圆近丈的一片空地，四处结着不少藤萝，箩根在地下盘结勾连，就好象一张大网般笼在石崖上。远望山坡上遍地的荆棘，将道路团团围住。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2391, 'qujing', 'qujing/jingjiling/shiya', '石崖', '石崖上甚是平坦，打扫的也十分干净，没有什么杂物，象是有人常在此走动。崖边有一石桌，旁有四个石凳。后面有一小屋，屋前石碑上刻有“木仙庵”三字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2392, 'qujing', 'qujing/jingjiling/songlin', '松林', '松林皆是古松，望去树木皆有百年之龄，树枝如虬龙般盘扭，树皮上有风霜偶现，枝叶上淡挂绿萝。树木紧列如密密的屏障，林之深处不可一见。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2393, 'qujing', 'qujing/jingjiling/xinglin', '杏林', '杏林中各色杏花怒放，香气扑鼻，几乎要将人醉倒了。望眼遍是碗口大的花朵，且色彩多变，望之如女子之笑脸。树木皆成深色如墨，而无一花瓣凋解。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2394, 'qujing', 'qujing/jingjiling/zhulin', '竹林', '竹林中见各类翠竹环种，偶见有腊梅，丹桂飘香。又见有双瀑泻于石涧中，跳珠溅玉，冷入人骨。上有竹桥一座，望之幽雅。冷风从林中穿过，听之萧然。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2399, 'qujing', 'qujing/jinping/cunlu1', '村路', '烟飘飘，雾漫漫，一眼极目望去只见农田翠幽幽，几幢小房在天边星星点点。脚下是厚实的泥土路，两边是田埂，不时可以听见溪水在埂下流过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2400, 'qujing', 'qujing/jinping/cunlu2', '村路', '烟飘飘，雾漫漫，一眼极目望去只见农田翠幽幽，几幢小房在天边星星点点。脚下是厚实的泥土路，两边是田埂，不时可以听见溪水在埂下流过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
