INSERT INTO `rooms` VALUES (2408, 'qujing', 'qujing/jinping/datang', '大堂', '大堂四周窗明几净，正中有一紫木长寿仙椅，一嵌玉兰石长案。堂的东侧有一高高的青鼎，西边有一排雕花木柜。堂北则通向门外。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2409, 'qujing', 'qujing/jinping/fumen', '府门', '一座高墙飞檐的门楼耸立在眼前，门楼下有一回廊。回廊由青雕石基双彩盘花柱撑起，两边是各种花草仙石，往南有一入口，东边则临街。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2410, 'qujing', 'qujing/jinping/huayuan1', '花园', '花园里有一条小径，小径两边是花圃，种着牡丹芍药海棠腊梅菊花等等。花圃的后面是果实累累的寺内果园，南边有门通向正殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2411, 'qujing', 'qujing/jinping/huayuan2', '花园', '一个花亭在花园中心小巧玲珑地建着，两边有小径，径外是一片又一片的花圃，种着牡丹芍药海棠腊梅菊花等等。花圃的后面可以看见一大片果园，上面果实累累。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2412, 'qujing', 'qujing/jinping/huayuan3', '花园', '花园里有一条小径，小径两边是花圃，种着牡丹芍药海棠腊梅菊花等等。花圃的后面是果实累累的寺内果园，西边有门通向正殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2413, 'qujing', 'qujing/jinping/jimiao', '祭庙', '祭庙里香火不断，里屋放着一个黑木香案，案上有签筒香炉，香炉里点着几柱香，正在飘着一丝丝的青烟。庙的西边临街，时不时有香客进进出出。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2414, 'qujing', 'qujing/jinping/kedian', '客店', '客店里有两张大桌子，八把木椅，墙边还有两条长长的条凳，供行人歇脚。店后面有一柜台，上面摆着一些小吃之类的食品。店北临街，不时有客进出。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2415, 'qujing', 'qujing/jinping/minju1', '民居', '这里是一片民居住房，有松板木楼也有石砖青瓦的平房，家家户户张灯结彩五光十色。有不少大小的五颜六色的彩灯挂在窗口门前，门口有一个油罐，供送油客灌油之用。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2416, 'qujing', 'qujing/jinping/minju2', '民居', '这里是一片民居住房，有松板木楼也有石砖青瓦的平房，家家户户张灯结彩五光十色。有不少大小的五颜六色的彩灯挂在窗口门前，门口有一个油罐，供送油客灌油之用。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2417, 'qujing', 'qujing/jinping/minju3', '民居', '这里是一片民居住房，有松板木楼也有石砖青瓦的平房，家家户户张灯结彩五光十色。有不少大小的五颜六色的彩灯挂在窗口门前，门口有一个油罐，供送油客灌油之用。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2418, 'qujing', 'qujing/jinping/minju4', '民居', '这里是一片民居住房，有松板木楼也有石砖青瓦的平房，家家户户张灯结彩五光十色。有不少大小的五颜六色的彩灯挂在窗口门前，门口有一个油罐，供送油客灌油之用。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2419, 'qujing', 'qujing/jinping/qian', '前殿', '前殿里粉刷一新，四周墙壁洁亮。殿中有一香台，紫铜的小香炉里正点着一些香。西边是慈云寺的大门，东边是寺庙的正殿大堂。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2420, 'qujing', 'qujing/jinping/qiao', '金灯桥', '桥上张灯结彩，各种彩灯纸笼高高挑起，桥上放置着大小瓷盏瓷盆缸，散发着酥香油的醇香味。桥上人来人往气氛非同寻常宛若过节一般。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2421, 'qujing', 'qujing/jinping/qiaobei', '桥北', '金灯桥北十分热闹，有不少镇外的村民也来观灯。西北方是一条小路，往南便是金灯桥头。河水从西而来自桥下潺潺流过，向东流去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2422, 'qujing', 'qujing/jinping/qiaonan', '桥南', '桥南临街，往北可见桥上张灯结彩，一阵阵酥香油味从桥那边顺风飘过来。河水从西而来自桥下潺潺流过，向东流去。往南便是城里。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2423, 'qujing', 'qujing/jinping/shanmen', '山门', '一个不高的山坡上，建着一个寺庙，云雾淡淡，悠哉闲哉。坡边有几只小羊远远地吃着草。寺庙的门口打扫得干干净净，门上有一牌匾：慈云寺。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2424, 'qujing', 'qujing/jinping/xiaojie1', '小街', '这里是街的北尽头。走在青石板条铺成的小街上，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2425, 'qujing', 'qujing/jinping/xiaojie2', '小街', '这里是桥南的街口，往东可见一庙宇。走在青石板条铺成的小街上，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2426, 'qujing', 'qujing/jinping/xiaojie3', '小街', '走在青石板条铺成的小街上，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2427, 'qujing', 'qujing/jinping/xiaojie4', '小街', '这里西边是富丽堂皇的府门，东与北是青石板条铺成的小街，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2428, 'qujing', 'qujing/jinping/xiaojie5', '小街', '你走在青石板条铺成的小街上，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。南边有一客店，打着招牌。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2429, 'qujing', 'qujing/jinping/xiaojie6', '小街', '走在青石板条铺成的小街上，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2430, 'qujing', 'qujing/jinping/xiaojie7', '小街', '这里是三岔路口的小街，由青石板条铺成，令人觉得悠闲宁静，街头有炊烟袅袅飘来青柴的香味。不远处传来家家户户舂米的声音，还有大户人家榨香油的醇香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2431, 'qujing', 'qujing/jinping/xiaolu', '小路', '一条小路自花园里伸出来，小路上铺满了小碎石子。旁边的花圃里飘来阵阵花香，东南边有一去处，搭着一座干净的石泥房子。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2432, 'qujing', 'qujing/jinping/zhai', '斋房', '斋房不是很大，墙角砌了一大灶台，屋外烧火屋里烧饭煮菜，灶里边墙根有一对空木桶，几只空菜箩筐。斋房靠窗处放了张木桌和两条长凳。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2433, 'qujing', 'qujing/jinping/zheng', '正殿', '正殿气势雄伟，佛象高高在台上。殿前有一排香案，下铺有一些灰布蒲团。香案上有木鱼木锤经书等等。北面和东面的殿门大开，外面是花园。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2444, 'qujing', 'qujing/jisaiguo/bamboo', '南湾竹屋', '竹屋中摆满了各种竹制品，堆的到处都是，让人无法下脚。几个小伙计正在一旁编着竹筐，因老板出去逛街，就有些偷懒。竹器在这里还是个新鲜物，来的人还挺多。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2445, 'qujing', 'qujing/jisaiguo/baodian', '大雄宝殿', '宝殿正中的一尊大佛好象已很久没有上金了，身上的金衣大部分脱落，看起来很滑稽。周围的菩萨罗汉竟都拿红布包了起来，上面落着厚厚的灰尘，后面有道小门，象是通向个要紧的地方。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2446, 'qujing', 'qujing/jisaiguo/centermarket', '中市', '祭赛国中非常的繁华，路周的楼台高耸，云雾缤纷。只见那三街六市，货殖通财，来往人等衣冠隆重，足显民富豪华。路南有一家大酒楼，飘出烤肉的香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2447, 'qujing', 'qujing/jisaiguo/cha', '茶室', '房中的摆设虽已破旧，但还干净，好象有人常来常往的样子。屋里墙上还挂着几幅字画，看起来还蛮有情趣。屋后几株绿竹随风摇摆，叶子发出哗哗的声音。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2448, 'qujing', 'qujing/jisaiguo/crosseast', '路口', '祭赛国中非常的繁华，路周的楼台高耸，云雾缤纷。只见那三街六市，货殖通财，来往人等衣冠隆重，足显民富豪华。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2449, 'qujing', 'qujing/jisaiguo/crosswest', '路口', '祭赛国中非常的繁华，路周的楼台高耸，云雾缤纷。只见那三街六市，货殖通财，来往人等衣冠隆重，足显民富豪华。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2450, 'qujing', 'qujing/jisaiguo/east1', '金光寺东街', '路西是赦建金光寺，青色的寺墙高立，向南延伸到城边，寺墙高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2451, 'qujing', 'qujing/jisaiguo/east2', '金光寺东街', '路西是赦建金光寺，青色的寺墙高立，向南延伸到城边，寺墙高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2452, 'qujing', 'qujing/jisaiguo/east3', '金光寺东街', '路西是赦建金光寺，青色的寺墙高立，向南延伸到城边，寺墙高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2453, 'qujing', 'qujing/jisaiguo/east4', '金光寺东街', '路西是赦建金光寺，青色的寺墙高立，高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2454, 'qujing', 'qujing/jisaiguo/eastgate', '祭赛国东门', '这里就到了祭赛国的东门，道路非常的宽广，足可容得下十马并驰。笔直的土路直通向城中，乘马和徒步赶路的人来往不绝，可见城中之繁华。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2455, 'qujing', 'qujing/jisaiguo/eastmarket', '东市', '祭赛国中非常的繁华，路周的楼台高耸，云雾缤纷。只见那三街六市，货殖通财，来往人等衣冠隆重，足显民富豪华。路南有一家小小的竹器铺，各种各样的手工艺品都摆到了街上。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2456, 'qujing', 'qujing/jisaiguo/gate', '金光寺', '门前有一横匾，上书七个镏金大字“赦建护国金光寺”。大门上挂着把生了绣的铜锁，好象很久没有打开了的样子、只有偏门略开一缝供人出入。偶尔几个僧人进出，也是低头快步，不敢略有停留。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2457, 'qujing', 'qujing/jisaiguo/inner1', '大院', '院中地势开阔，墙边的古树参天，枝繁叶密、正中一条青砖铺成的小路直通向后面的大雄宝殿，依稀可以看出往日的兴旺。', '1', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (2458, 'qujing', 'qujing/jisaiguo/inner2', '中院', '院中地势开阔，墙边的古树参天，枝繁叶密、正中一条青砖铺成的小路直通向后面的大雄宝殿，两旁一式的青砖小舍，依稀可以看出往日的兴旺，只是多了几分凄凉。', '1', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (2459, 'qujing', 'qujing/jisaiguo/inner3', '后院', '院中地势开阔，墙边的古树参天，枝繁叶密、正中一条青砖铺成的小路直通向后面的大雄宝殿，两旁一式的青砖小舍，依稀可以看出往日的兴旺，只是多了几分凄凉。', '1', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (2460, 'qujing', 'qujing/jisaiguo/jing', '经堂', '屋中黑漆漆的，顶上的香油灯不知已灭了多少年了。依稀看到周围都是书架，上面也挂满了灰尘，屋中摆着上落满灰尘的木桌，几张木椅零乱的倒在一边。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2461, 'qujing', 'qujing/jisaiguo/pingxi', '平西大路', '这是一条宽阔笔直的大官道，足可容得下十马并驰。往西直通向西域诸国，东边就到了祭赛国。南边一条羊肠小路，不知通向何方，荆棘从生，好像很少有人走过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2462, 'qujing', 'qujing/jisaiguo/pingxi1', '平西大路', '这是一条宽阔笔直的大官道，足可容得下十马并驰。往西直通向西域诸国，东边就到了祭赛国。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2463, 'qujing', 'qujing/jisaiguo/restaurant', '羊肉店', '烤肉点里飘着股浓浓的烤肉香味。店中无椅无桌，人人都是席地而坐，面前的烤炉上放着不同种类，烤的香喷喷的肉食。店中的客人都是大口喝酒，大口吃肉，自得其乐的样子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2464, 'qujing', 'qujing/jisaiguo/silver', '银器铺', '银器铺正前摆了张木柜，里面陈列这各种银器，大多是女人的饰品，也有些其他的小玩艺。柜台后站着位花枝招展的女老板，笑盈盈的看着你。再往后是作坊，几个老匠人正忙着打制。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2465, 'qujing', 'qujing/jisaiguo/south1', '金光寺南街', '路北是赦建金光寺，青色的寺墙高立，高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2466, 'qujing', 'qujing/jisaiguo/south2', '金光寺南街', '路北是赦建金光寺，青色的寺墙高立，高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2467, 'qujing', 'qujing/jisaiguo/to-baoxiang1', '土路', '西边望去有一座大的城池，笔直的土路直通向城中，乘马和徒步赶路的人来往不绝，可见城中之繁华。东边土路向东北方向延伸，渐渐隐在一座小山之后。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2468, 'qujing', 'qujing/jisaiguo/to-baoxiang2', '土路', '西边望去有一座大的城池，笔直的土路直通向城中，乘马和徒步赶路的人来往不绝，可见城中之繁华。东边土路向东北方向延伸，渐渐隐在一座小山之后。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2469, 'qujing', 'qujing/jisaiguo/to-baoxiang3', '山路', '小山不高，山上树木繁多，显得非常有精神。林中鸟尔叽叽喳喳的叫着，时不时路边的草丛中窜出只野兔，惊起几只鸟雀。渐渐隐在一座小山之后。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2470, 'qujing', 'qujing/jisaiguo/to-baoxiang4', '山路', '小山不高，山上树木繁多，显得非常有精神。林中鸟尔叽叽喳喳的叫着，时不时路边的草丛中窜出只野兔，惊起几只鸟雀。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2471, 'qujing', 'qujing/jisaiguo/to-baoxiang5', '山路', '小山不高，山上树木繁多，显得非常有精神。林中鸟尔叽叽喳喳的叫着，时不时路边的草丛中窜出只野兔，惊起几只鸟雀。渐渐隐在一座小山之后。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2472, 'qujing', 'qujing/jisaiguo/tower1', '琉璃塔一层', '峥嵘倚汉，突兀凌空，名唤五色琉璃塔。层层门上琉璃灯，有尘无火，步步檐前白玉栏，积诟飞虫。塔心里，佛座上，香烟尽绝，窗棂外，神面前，蛛网牵蒙。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
