INSERT INTO `rooms` VALUES (2484, 'qujing', 'qujing/jisaiguo/tower9', '琉璃塔九层', '峥嵘倚汉，突兀凌空，名唤五色琉璃塔。层层门上琉璃灯，有尘无火，步步檐前白玉栏，积诟飞虫。塔心里，佛座上，香烟尽绝，窗棂外，神面前，蛛网牵蒙。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2485, 'qujing', 'qujing/jisaiguo/west1', '金光寺西街', '路东是赦建金光寺，青色的寺墙高立，向南延伸到城边，寺墙高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2486, 'qujing', 'qujing/jisaiguo/west2', '金光寺西街', '路东是赦建金光寺，青色的寺墙高立，向南延伸到城边，寺墙高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2487, 'qujing', 'qujing/jisaiguo/west3', '金光寺西街', '路东是赦建金光寺，青色的寺墙高立，向南延伸到城边，寺墙高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2488, 'qujing', 'qujing/jisaiguo/west4', '金光寺西街', '路东是赦建金光寺，青色的寺墙高立，高有丈许，上覆青色瓦片。街道很宽，来往车辆不多，路面很干净，是因为僧人经常打扫的缘故。路边民居错落有序，几个小童在路边玩耍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2489, 'qujing', 'qujing/jisaiguo/westgate', '祭赛国西门', '这里就到了祭赛国的西门，道路非常的宽广，足可容得下十马并驰。笔直的土路直通向城中，乘马和徒步赶路的人来往不绝，可见城中之繁华。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2490, 'qujing', 'qujing/jisaiguo/westmarket', '西市', '祭赛国中非常的繁华，路周的楼台高耸，云雾缤纷。只见那三街六市，货殖通财，来往人等衣冠隆重，足显民富豪华。路南有一家银器店，传出叮叮咚咚的响声。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2491, 'qujing', 'qujing/jisaiguo/wufeng', '五凤楼', '一座小巧的彩楼，每到黄道吉日，国王便在这里大宴群臣，偶尔也会在这里接见外国的使者。地下铺着豪华漂亮的地毯，两边没有桌椅，所有的客人都坐在地下。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2492, 'qujing', 'qujing/jisaiguo/xiang', '香堂', '屋中黑漆漆的，顶上的香油灯不知已灭了多少年了。屋中弥散着股香烛味，却有了太多的土气。地下几个蒲团早已叫老鼠咬的破烂不堪，两旁挂的香帘也如风中飘絮，破烂的不成样子。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2493, 'qujing', 'qujing/jisaiguo/yaopu', '药铺', '祭赛国中人人好武，有个碰破擦伤在所难免，所以药铺的生意也是相当不错。当家的大夫原是宫中的御医，还是有两把刷子的。来看病抓药的人把门槛都踏平了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2494, 'qujing', 'qujing/jisaiguo/yunqi', '云霁台', '祭赛国中非常的繁华，王宫便在那城心。一个高有数丈的高台将王宫和闹市分开。从高台上可以附视全城，只见高楼宫宇不断，街上来往人等衣冠隆重，足显民富豪华。几个黄门官正在台前巡视，防止闲杂人等如内。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2495, 'qujing', 'qujing/jisaiguo/zai', '斋室', '房中的摆设虽已破旧，但还干净，好象有人常来常往的样子。屋里墙上还挂着几幅字画，看起来还蛮有情趣。屋后几株绿竹随风摇摆，叶子发出哗哗的声音。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2512, 'qujing', 'qujing/kusong/anmen', '斜巷', '这里好象已是路的尽头，下方有一条窄窄的斜巷，里面黑黑的望不到底，不知能通到何处。巷口挂着一个木牌，写着“入禁地者死”五个字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2513, 'qujing', 'qujing/kusong/baihu', '白虎潭', '潭中的水晶莹透彻，远望恰如一只白色的虎爪。潭中偶而有大鱼跃出，溅起片片的水花。潭的对面有一幅高崖，崖下隐约看到一个小的山洞。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2514, 'qujing', 'qujing/kusong/guaishiya', '怪石崖', '前方的怪石如一堵高墙挡在路上。崖上挂着一簇簇的乱葛藤萝，大部分已经焦黄枯萎。崖下一扇大石门，门边有个大的石碣，写了“号山枯松涧火云洞”八个大字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2515, 'qujing', 'qujing/kusong/huo', '火丁洞', '一个黑漆漆的小室，象是来储藏东西用的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2516, 'qujing', 'qujing/kusong/huoyun', '火云堂', '这里就是火云洞的中心－火云堂。正前方一把黑虎皮的软椅高高在上，椅后一把玄色大锦旗，上面绣着“圣婴大王”四个金子。两旁小妖林立，头顶几十把松油灯把堂上照的雪亮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2517, 'qujing', 'qujing/kusong/jiandi', '涧底', '这里是涧下一块小的平地。头上有飞泉涉过，恰好将这里遮掩起来，从涧上是看不到的。周围长着密密麻麻的青草，中间隐隐现出一条小路。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2518, 'qujing', 'qujing/kusong/jiandi2', '涧底小路', '耳畔隐隐传来泉水的流声，夹杂着些鸟儿的鸣叫。周围长着密密麻麻的青草，草中现出点点的野花。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2519, 'qujing', 'qujing/kusong/jin', '金甲洞', '一个黑漆漆的小室，象是来储藏东西用的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2520, 'qujing', 'qujing/kusong/kitchen', '厨房', '洞内的厨房相当的大，来回竟有十来个小妖忙活。屋内各种炊具也是应有尽有，东边一排特大的蒸锅冒着水气。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2521, 'qujing', 'qujing/kusong/kusongjian', '枯松涧', '松林边上有一片小的石崖，北面有一条山涧，似乎传来阵阵流水的声音。涧上有一座小的石桥，远望桥后是一座高的怪石崖，崖下人影攒动。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2522, 'qujing', 'qujing/kusong/mu', '木乙洞', '一个黑漆漆的小室，象是来储藏东西用的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2523, 'qujing', 'qujing/kusong/qingcao0', '青草坡', '这里的青草越来越密，眼前已无道路可循。草中偶有野兔类的小兽跑过，发出悉悉嗦嗦的声音。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2524, 'qujing', 'qujing/kusong/qingcao1', '青草坡', '这里的青草越来越密，眼前已无道路可循。草中偶有野兔类的小兽跑过，发出悉悉嗦嗦的声音。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2525, 'qujing', 'qujing/kusong/shui', '水丙洞', '一个黑漆漆的小室，象是来储藏东西用的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2526, 'qujing', 'qujing/kusong/sleep', '卧室', '这里是一间圆圆的石室，室中有一堆炭火，把屋内烘的暖暖的。四周横七竖八的铺着十来张兽皮，时不时有小妖跑来睡觉。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (2527, 'qujing', 'qujing/kusong/songlin1', '黑松林', '松林中一片漆黑，头顶上密密麻麻的松针遮住了光线，让人难辩东西南北。大风吹过，带来阵阵热气，却不禁让人发颤。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2528, 'qujing', 'qujing/kusong/songlin2', '黑松林', '松林中一片漆黑，头顶上密密麻麻的松针遮住了光线，让人难辩东西南北。大风吹过，带来阵阵热气，却不禁让人发颤。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2529, 'qujing', 'qujing/kusong/songlin3', '黑松林', '松林中一片漆黑，头顶上密密麻麻的松针遮住了光线，让人难辩东西南北。大风吹过，带来阵阵热气，却不禁让人发颤。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2530, 'qujing', 'qujing/kusong/songlin4', '黑松林', '松林中一片漆黑，头顶上密密麻麻的松针遮住了光线，让人难辩东西南北。大风吹过，带来阵阵热气，却不禁让人发颤。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2531, 'qujing', 'qujing/kusong/tu', '土戊洞', '一个黑漆漆的小室，象是来储藏东西用的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2532, 'qujing', 'qujing/kusong/wangyue', '望月谷', '两边的小山对立，这里形成了一个弯月状的山谷。谷中开着许多不知名的野花，看起来十分的悠雅安静。谷的北面有一片白汪汪的水泽。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2533, 'qujing', 'qujing/kusong/weapon', '兵器盔甲室', '屋内有几个兵器甲，上面分门别类的放着些常用的兵器，兵器都擦的很亮，看来有人经常保管。墙上挂着写盔甲鞋帽之类。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2534, 'qujing', 'qujing/kusong/xingfang', '刑房', '刑房中特别的昏暗，北边竖着个铁柱子，上面搭着几条带血的铁链。地下扔着几条皮鞭。东边有一扇铁门，上有小口，里面是间囚室。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2535, 'qujing', 'qujing/kusong/xuanjing', '玄晶洞', '洞中的石壁上闪耀耀地嵌着许多水晶，在洞内幻出许多虚象。洞外便是白虎潭，如同一面大的镜子。潭后是大片大片的草原，延绵到天的尽头。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2536, 'qujing', 'qujing/kusong/yongdao1', '甬道', '甬道内发出一股血腥气。墙上挂着油灯，忽明忽暗的灯光隐隐照出了前后的道路。南面是一扇石门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2537, 'qujing', 'qujing/kusong/yongdao2', '甬道', '甬道内发出一股血腥气。墙上挂着油灯，忽明忽暗的灯光隐隐照出了前后的道路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2538, 'qujing', 'qujing/kusong/yongdao3', '甬道', '甬道内发出一股血腥气。墙上挂着油灯，忽明忽暗的灯光隐隐照出了前后的道路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2539, 'qujing', 'qujing/kusong/yongdao4', '前洞', '这里宽敞了许多，洞内一片光亮。来回有很多小妖走动，嘻嘻嚷嚷地也十分热闹，四处的路口深深地不知通向何方。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2540, 'qujing', 'qujing/kusong/yongdao5', '甬道', '甬道内发出一股血腥气。墙上挂着油灯，忽明忽暗的灯光隐隐照出了前后的道路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
