INSERT INTO `rooms` VALUES (2544, 'qujing', 'qujing/kusong/zhongdong', '中洞', '这里宽敞了许多，洞内一片光亮。来回有很多小妖走动，嘻嘻嚷嚷地也十分热闹，四处的路口深深地不知通向何方。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2558, 'qujing', 'qujing/lingshan/baoge1', '宝阁', '阁内有香案无数，每个香案上有金银香炉数只，仙香袅袅，缭缭绕绕，阁北有一玉座落地金莲灯。西边有一殿门通向大雄宝殿，楼上为宝阁藏经处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2559, 'qujing', 'qujing/lingshan/baoge2', '宝阁', '宝阁里霞光瑞气，笼罩千重，彩雾祥云，迷漫万道。正中有一巨大的金钉藏经柜，旁边有一长长的紫木案桌，上有花玉宝匣。都贴着各种红签。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2560, 'qujing', 'qujing/lingshan/dalu1', '大路', '大路两边，有琪花，瑶草，古柏，苍松。果然一个西方佛地，与他处不同。不时可见路边有人或是停在路边修道，或是闭目诵经。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2561, 'qujing', 'qujing/lingshan/dalu2', '大路', '大路两边，有琪花，瑶草，古柏，苍松。果然一个西方佛地，与他处不同。不时可见路边有人或是停在路边修道，或是闭目诵经。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2562, 'qujing', 'qujing/lingshan/dalu3', '大路', '大路两边，有琪花，瑶草，古柏，苍松。果然一个西方佛地，与他处不同。不时可见路边有人或是停在路边修道，或是闭目诵经。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2563, 'qujing', 'qujing/lingshan/daxiong', '大雄宝殿', '大雄宝殿里金碧辉煌紫气瑞瑞，根根玉柱雕麒麟，殿窗是金钉银檐，殿顶亦上是金银鸳鸯双双对对，正中有一白玉玛瑙莲花台。南边有一殿门通往后殿，东西边各有一偏门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2564, 'qujing', 'qujing/lingshan/dumuqiao', '独木桥', '……独木桥摇摇摆摆，木头上长满了滑青苔……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2565, 'qujing', 'qujing/lingshan/ermen', '二门', '第二大殿门也是一对巨大的檀香银皮木门，门边是橙色仙鸾戏水画屏。殿的左右各有一个丈许高白银佛鼎，北面是雷音古寺一门，东西为侧殿，南边是第三道大殿门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2566, 'qujing', 'qujing/lingshan/houdian', '后殿', '后殿里仙气冉冉，东西面是金凤银鹤花屏，南边是一排香木玉窗，窗外有一天院，临窗可见院中翠竹竿竿倒，金莲朵朵摇，北面是一彩绒殿门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2567, 'qujing', 'qujing/lingshan/lingyun1', '凌云渡', '雾气中，一道山涧冲下来，滚浪飞流。山涧下是万丈飞虹，水面宽阔翻滚着千条白练。渡口岸见不到其它的路可走，上面架着一根独木桥。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2568, 'qujing', 'qujing/lingshan/lingyun2', '凌云渡', '雾气中，一道山涧冲下来，滚浪飞流。山涧下是万丈飞虹，水面宽阔翻滚着千条白练。渡口岸见不到其它的路可走，上面架着一根独木桥。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2569, 'qujing', 'qujing/lingshan/sanmen', '三门', '三门金光闪闪，乃是金边檀香木门一对，门两边有赤金丹顶凤一对。大殿左右各摆着雕花金佛鼎。北面通向古寺的二道门，东西为侧殿，南面就是大雄宝殿。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2570, 'qujing', 'qujing/lingshan/shandian', '灵山巅', '灵山巅无数彩霞飞虹万千条，仙气如雾紫光瑞瑞。四面巧峰排列，怪石参差，悬崖下瑶草奇花，曲径旁紫芝香蕙，真是个花草松篁鸾凤鹤鹿之胜地。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2571, 'qujing', 'qujing/lingshan/shanjiao', '灵山脚', '只见山上松临雨过青，花向春来美。远远可见山上祥云瑞瑞，彩霞如练虹。遍野是各种各样紫芝仙果灵草，黄鹤信步，彩鸾成双飞。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2572, 'qujing', 'qujing/lingshan/sidian11', '寺殿', '寺殿里云霞迷漫仙气非凡，殿檐上金铃银铃串串随煦风微晃叮当脆响，殿内一片光明紫气缭绕。殿侧回廊里不时从附近传来阵阵诵经的声音。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2573, 'qujing', 'qujing/lingshan/sidian12', '寺殿', '寺殿里云霞迷漫仙气非凡，殿檐上金铃银铃串串随煦风微晃叮当脆响，殿内一片光明紫气缭绕。殿侧回廊里不时从附近传来阵阵诵经的声音。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
