INSERT INTO `rooms` VALUES (2608, 'qujing', 'qujing/lingshan/siqian', '寺前', '只见万年雷音寺前为一广场，一路铺着明亮的玛瑙花砖，广场的正面可见无数殿宇蕊宫珠阙紫气瑞瑞。东边有仙猿摘果入桃林，西边有白鹤栖松立枝头；场南有彩凤双双，向日一鸣天下瑞，场北是青鸾对对，迎风耀舞世间稀。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2609, 'qujing', 'qujing/lingshan/yang1', '阳明道', '山上祥光五色，瑞蔼千重，灵鹫顶上披彩虹，高峰两边落飞霞，紫气袅袅气吞宇宙。阳明道缥缥缈渺如筑在云中，路边都是仙石仙岩。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2610, 'qujing', 'qujing/lingshan/yang2', '阳明道', '山上祥光五色，瑞蔼千重，灵鹫顶上披彩虹，高峰两边落飞霞，紫气袅袅气吞宇宙。阳明道缥缥缈渺如筑在云中，路边都是仙石仙岩。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
