INSERT INTO `rooms` VALUES (2612, 'qujing', 'qujing/lingshan/yang4', '阳明道', '山上祥光五色，瑞蔼千重，灵鹫顶上披彩虹，高峰两边落飞霞，紫气袅袅气吞宇宙。阳明道缥缥缈渺如筑在云中，路边都是仙石仙岩。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2613, 'qujing', 'qujing/lingshan/yimen', '一门', '大殿门口乃是一对巨大的檀香木门，门边有朱色霓虹双鹤飞天玉台柱。殿两侧各有一个紫雕玉玛瑙纹佛鼎，北面是宽敞的寺前大广场，东西为侧殿，南边又是一道大殿门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2614, 'qujing', 'qujing/lingshan/zhenlou1', '珍楼', '珍楼下有无数奇珍异宝陈列楼中，靠西有一排麒麟皮凤背纹长椅，以供雷音寺贵宾休息。东边是殿门通向大雄宝殿，往上是珍楼的二楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2615, 'qujing', 'qujing/lingshan/zhenlou2', '珍楼', '楼里摆满了各种玉盆香花琼草，中间有一翡翠仙桌，边上摆着檀香嵌玉软椅。桌上摆着一些大小金盘银盘，里面是仙品、仙茶、仙果。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2618, 'qujing', 'qujing/maoying/andao1', '暗道', '……你似乎什么也看不清楚，只觉得暗道里湿气飕飕，但难以探到前方的出路……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
