INSERT INTO `rooms` VALUES (2621, 'qujing', 'qujing/maoying/shanpo1', '山坡', '山坡上长着古树青藤，路上枯枝落叶遍地，坡边高高低低长着灌木蒿草，夹杂着一些大大小小的岩石。坡下幽幽深深，不时可见沟渠洞穴。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
