INSERT INTO `rooms` VALUES (2637, 'qujing', 'qujing/maoying/shilu1', '石路', '山外上一条石子路绕来绕去，沿着地势略有些起伏。石路边荒芜人烟青草丛生古树盘根错节，不知通向何处。远处有风低低的吼叫，古树有野鸦呱呱。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
