INSERT INTO `rooms` VALUES (2642, 'qujing', 'qujing/maoying/tuxue1', '兔穴', '一个深深的山洞，洞里雾汽缈缈，洞的角落铺满了松软的干草。洞的里面似乎有暗道。人说：狡兔有三穴。这是第几穴呢？洞里的暗道又通向什么穴呢？', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2643, 'qujing', 'qujing/maoying/tuxue2', '兔穴', '一个深深的山洞，洞里雾汽缈缈，洞的角落铺满了松软的干草。洞的里面似乎有暗道。人说：狡兔有三穴。这是第几穴呢？洞里的暗道又通向什么穴呢？', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2644, 'qujing', 'qujing/maoying/tuxue3', '兔穴', '一个深深的山洞，洞里雾汽缈缈，洞的角落铺满了松软的干草。洞的里面似乎有暗道。人说：狡兔有三穴。这是第几穴呢？洞里的暗道又通向什么穴呢？', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2645, 'qujing', 'qujing/nuerguo/annei', '庵内', '虽说是道观，聚仙庵内供的既不是太上老君，也不是道家诸仙，而是一口井(well)。井台上刻有三个大字：“落胎泉”。一老道正坐在井台边闭目修炼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2646, 'qujing', 'qujing/nuerguo/backhall', '后宫', '这便是西梁公主接见宾客的后宫了。一帘镶珠紫红大帐将后宫的入口遮严，殿内庄严肃穆，正中玉白台阶上是彩龙金凤双蝶宝座，上面高高地坐着西梁公主。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2647, 'qujing', 'qujing/nuerguo/changbie', '长别亭', '在山腰的平地上，修了一座亭子，向东南方向的西梁城镇眺望。亭上有一小匾写道：长别亭。西北方向有一条小路，通向西域境外。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2648, 'qujing', 'qujing/nuerguo/easthall', '东侧殿', '这里是西梁王宫的东侧殿。一架大屏风将殿分成两半，屏风后放着一些大大小小的漆红嵌金箱子彩盒，看样子给西梁公主送礼进贡的人的确不少。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2649, 'qujing', 'qujing/nuerguo/eastriver1', '子母河东岸', '澄澄清水，湛湛寒波。一条小河(river)横在前面。对面是西梁女国。你看了一看四周没有桥也没有摆渡，河水在此处深而急，直接趟过去有点危险。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2650, 'qujing', 'qujing/nuerguo/eastriver2', '子母河东岸', '子母河在这里显得比较宁静一点。河面较宽，水流平缓。河对岸的西梁女国远远地可以看见一点人烟了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2651, 'qujing', 'qujing/nuerguo/eastriver3', '子母河东岸', '这里河面很宽很浅，河对岸有柳荫垂碧，微露出茅屋几檐。河岸这边地踩得很踏实，好像曾经有不少人在这里走过。河面很宽很浅，看样子徒步涉水也可以走过去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2652, 'qujing', 'qujing/nuerguo/end', '一线天', '你来到一个峡谷底，两壁是高高的山崖，崖顶云雾缭绕，阳光照不进来。左前方有一丈许高的灵石，上刻着三个大字：经纬石。灵石荧荧地发着罕见的霞光。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2653, 'qujing', 'qujing/nuerguo/entry', '王宫大门', '这是西梁王宫高高的大门。门台下挤着一群爱看热闹的女人们伸着脖子探着头看来看去，压低着嗓子在叽叽咕咕小声议论着什么。北边是前宫入口，南边是安乐巷。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2654, 'qujing', 'qujing/nuerguo/fronthall', '前宫', '西梁王宫的前宫。正中一帘镶珠紫红帐，四周雕龙绘凤金碧辉煌。大厅左侧摆了一排长桌，供满了水果糕点让宾客享用，大厅右侧是一队青衣少女在跳着宫庭舞蹈。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2655, 'qujing', 'qujing/nuerguo/greenyard', '绿迷宫', '一座用无数棵绿树修剪成的大迷宫，前后左右都是一片绿色的密树丛，很难辨别方向，也看不到任何出口。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2656, 'qujing', 'qujing/nuerguo/jieyang', '解阳山', '解阳山其实只是一座小土丘。不过这里幽花摆锦，野草铺蓝，景致确是不错。山上有一道观，称为“聚仙庵”。山的西面有一条小路。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2657, 'qujing', 'qujing/nuerguo/juxianan', '聚仙庵', '聚仙庵依山而建，布设甚是精巧。所谓“小桥通活水，茅舍倚青山”，在风水上可称之为宝地。此刻庵门紧闭。有一道士懒洋洋地盘坐在庵前绿茵之上，不知是在打坐修炼还是在晒太阳。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2658, 'qujing', 'qujing/nuerguo/maowu', '茅屋', '这是一间简陋的小茅屋。四壁以芦杆搭成。屋内只有一些简单的生活用具。一位老婆婆倚门而坐。以年龄看来似是摆渡老妇人的姐姐。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2659, 'qujing', 'qujing/nuerguo/map', 'map', '一线天\r\n　　　　＼\r\n　　　　长别亭\r\n　　　　　｜＼\r\n　　　　　｜山坡─迷宫出口…绿迷宫\r\n　　　　　｜\r\n　　　　　｜　　　　　　　　　后宫\r\n　　　　　｜　　　　　　　　　｜\r\n　　　　　｜　　　　　东侧殿─前宫─西侧殿\r\n　　　　　｜　　　　　　　　　｜\r\n　　　　　｜　　　　　　　　王宫大门\r\n　　　　　｜　　　　　　　　　｜\r\n　　　　　｜　　　安乐巷西─安乐巷中─安乐巷东\r\n　　　　　｜　　　　｜　　　　｜　　　　｜\r\n　　　　小路　　　儿女巷西─儿女巷中─儿女巷东　　　　　　　　河东岸─山路\r\n　　　　　｜　　　　｜　　　　｜　　　　｜　　　　　　　　　　　｜        ＼\r\n　　　　　｜　　　桑花巷西─桑花巷中─桑花巷东　　　　茅屋　　河东岸  ※金兜山※\r\n　　　　　｜　　　　　　　　　　　　　　　　　＼　　　　｜　　　｜\r\n　　　　　｜　　　　　　　　　　　　　　　　三岔路口─河西岸…河东岸\r\n　　　　　｜　　　　　　　　　　　　　　　　　　｜\r\n　　　　小路────小路───────────解阳山\r\n　　　　　　　　　　　　　　　　　　　　　　　　｜\r\n　　　　　　　　　　　　　　　　　　　　　　　聚仙庵\r\n　　　　　　　　　　　　　　　　　　　　　　　　｜\r\n　　　　　　　　　　　　　　　　　　　　　　　　庵内', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2660, 'qujing', 'qujing/nuerguo/outlet', '迷宫出口', '突然无数棵绿树丛中出现了一个豁口，外面似乎是一条大路。你心中一喜，总算从迷宫里走出来了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2661, 'qujing', 'qujing/nuerguo/river', '河中', '你小心翼翼地走进河水中……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2662, 'qujing', 'qujing/nuerguo/sanchalu', '三岔路口', '这里是西梁女国地界。西北方隐隐约约可见一座城镇。东行可达子母河边。往南望去则是一座葱翠的小山丘。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2663, 'qujing', 'qujing/nuerguo/shanpo', '山坡', '你爬行在一面斜斜的山坡上，西边的坡上影影约约像是有一座亭子。再朝自己的脚下看一看，远远的是一片绿树丛。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2664, 'qujing', 'qujing/nuerguo/start', '山路', '野润烟光淡，沙暄日色曛。一路行来景色秀丽。再往西行就到子母河了。过了河就是西梁女国地界。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2665, 'qujing', 'qujing/nuerguo/towna1', '安乐巷西', '这里是西梁镇的安乐巷西。北面有一堵长长的城墙，看样子大概是西梁王宫所在地。女人们三三两两围在一起，谈论着西梁公主最新的招驸一事。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2666, 'qujing', 'qujing/nuerguo/towna2', '安乐巷中', '这里是西梁镇的安乐巷中。北面有一高高的大门，是西梁王宫的主要入口。街上女人们三三两两围在一起，谈论着西梁公主最新的招驸一事。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2667, 'qujing', 'qujing/nuerguo/towna3', '安乐巷东', '这里是西梁镇的安乐巷东。北面有一堵长长的城墙，看样子大概是西梁王宫所在地。女人们三三两两围在一起，谈论着西梁公主最新的招驸一事。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2668, 'qujing', 'qujing/nuerguo/townb1', '儿女巷西', '你走在西梁镇的儿女巷西。女人们在街头坐着晒太阳，有的年轻妇女主动迎上来和男游客们笑嘻嘻地打招呼。女人群中不时地爆发出哄笑。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2669, 'qujing', 'qujing/nuerguo/townb2', '儿女巷中', '你走在西梁镇的儿女巷中。女人们在街头坐着晒太阳，有的年轻妇女主动迎上来和男游客们笑嘻嘻地打招呼。女人群中不时地爆发出哄笑。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2670, 'qujing', 'qujing/nuerguo/townb3', '儿女巷东', '你走在西梁镇的儿女巷东。女人们在街头坐着晒太阳，有的年轻妇女主动迎上来和男游客们笑嘻嘻地打招呼。女人群中不时地爆发出哄笑。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2671, 'qujing', 'qujing/nuerguo/townc1', '桑花巷西', '你走在西梁镇的桑花巷西，这是西梁女国的主要城镇。镇子不大，镇子里的老老少少都是女人。见到有外边的游客来，尤其是男游客，女人们都惊喜地拥上街头叽叽喳喳嘻嘻哈哈地议论个不停。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2672, 'qujing', 'qujing/nuerguo/townc2', '桑花巷中', '你走在西梁镇的桑花巷中，这是西梁女国的主要城镇。镇子不大，镇子里的老老少少都是女人。见到有外边的游客来，尤其是男游客，女人们都惊喜地拥上街头叽叽喳喳嘻嘻哈哈地议论个不停。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2673, 'qujing', 'qujing/nuerguo/townc3', '桑花巷东', '你走在西梁镇的桑花巷东，这是西梁女国的主要城镇。镇子不大，镇子里的老老少少都是女人。见到有外边的游客来，尤其是男游客，女人们都惊喜地拥上街头叽叽喳喳嘻嘻哈哈地议论个不停。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2674, 'qujing', 'qujing/nuerguo/westhall', '西侧殿', '这里是西梁王宫的西侧殿。靠墙四周铺设了一圈极为考究的红木桌椅，上面放着香炉，玉如意等玩物。这里主要是供来宾们休息使用的场所。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2675, 'qujing', 'qujing/nuerguo/westriver', '子母河西岸', '河边柳荫垂碧，水面很宽很浅，北面有一座小茅屋。风吹过后，一个小招牌轻轻地晃来晃去。河岸踩得很踏实，有不少人从这里徒步涉水过河。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2676, 'qujing', 'qujing/nuerguo/xiaolu1', '小路', '这是一条又细又长的山间小径，一会儿高，一会儿低。路的两边是不知名的野花野草。你快速地走着，觉得山势有一点陡峭。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2677, 'qujing', 'qujing/nuerguo/xiaolu2', '小路', '这是一条又细又长的山间小径，一会儿高，一会儿低。路的两边是不知名的野花野草。你快速地走着，觉得山势有一点陡峭。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2678, 'qujing', 'qujing/nuerguo/xiaolu3', '小路', '这是一条又细又长的山间小径，一会儿高，一会儿低。路的两边是不知名的野花野草。你快速地走着，觉得山势有一点陡峭。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2679, 'qujing', 'qujing/nuerguo/xiaolu4', '小路', '这是一条又细又长的山间小径，一会儿高，一会儿低。路的两边是不知名的野花野草。你快速地走着，觉得山势有一点陡峭。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2685, 'qujing', 'qujing/pansi/bixi1', '碧溪', '只见香兰沿溪而生，芳草连天。溪水清绿流音潺潺。环绕着石屋。也听见野禽声聒聒，也看见幽鹿步徐徐。真正是个仙家去绝妙处，凡世哪里寻得到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2686, 'qujing', 'qujing/pansi/bixi2', '碧溪', '只见香兰沿溪而生，芳草连天。溪水清绿流音潺潺。环绕着石屋。也听见野禽声聒聒，也看见幽鹿步徐徐。真正是个仙家去绝妙处，凡世哪里寻得到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2687, 'qujing', 'qujing/pansi/bixi3', '碧溪', '只见香兰沿溪而生，芳草连天。溪水清绿流音潺潺。环绕着石屋。也听见野禽声聒聒，也看见幽鹿步徐徐。真正是个仙家去绝妙处，凡世哪里寻得到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2688, 'qujing', 'qujing/pansi/bixi4', '碧溪', '只见香兰沿溪而生，芳草连天。溪水清绿流音潺潺。环绕着石屋。也听见野禽声聒聒，也看见幽鹿步徐徐。真正是个仙家去绝妙处，凡世哪里寻得到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2689, 'qujing', 'qujing/pansi/bixi5', '碧溪', '只见香兰沿溪而生，芳草连天。溪水清绿流音潺潺。环绕着石屋。也听见野禽声聒聒，也看见幽鹿步徐徐。真正是个仙家去绝妙处，凡世哪里寻得到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2690, 'qujing', 'qujing/pansi/bixi6', '碧溪', '只见香兰沿溪而生，芳草连天。溪水清绿流音潺潺。环绕着石屋。也听见野禽声聒聒，也看见幽鹿步徐徐。真正是个仙家去绝妙处，凡世哪里寻得到。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (2691, 'qujing', 'qujing/pansi/cha', '茶房', '茶房宽绰光线明亮。一大茶桌靠墙而放，上面放有一些茶壶茶盏茶盘茶果之类的茶具茶点。一双扇门通向西面的殿堂，东北有一偏门通向厨房，南边有一客房。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2692, 'qujing', 'qujing/pansi/chu', '厨房', '屋子里有一小灶，上有铁锅一口。边上有一菜筐里面堆有一些青菜萝卜之类的蔬菜，地上有一小垛干柴干草。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2693, 'qujing', 'qujing/pansi/chulang', '厨廊', '廊里有一天然石灶，冒着柴烟，上有一口大铜锅炖着什么肉。旁边是方方正正的石桌，上有石碗石盘。两块大石头摆在桌边俨然一对石凳。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2694, 'qujing', 'qujing/pansi/dongnei', '洞内', '洞穴内昏昏暗暗，珠丝如藤条一般盘绕在洞壁，洞顶有水珠渗出，沿洞壁纷纷落下，嘀嗒有声。一丝微弱的光线自东北方向漫射进来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2695, 'qujing', 'qujing/pansi/huajian1', '花涧', '古树连天，瀑布自山岩上长挂下来，两边是涧水潺流，飘满落花朵朵。岸上垂柳煦风绿色满园，路上铺着五彩小石卵，细细碎碎如甘露洒落。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2696, 'qujing', 'qujing/pansi/huajian2', '花涧', '古树连天，瀑布自山岩上长挂下来，两边是涧水潺流，飘满落花朵朵。岸上垂柳煦风绿色满园，路上铺着五彩小石卵，细细碎碎如甘露洒落。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2697, 'qujing', 'qujing/pansi/jiandi', '涧底', '山涧低洼地带，四处是涧水潺潺，几乎无法落脚。两边是高山峻岭，东边涧流水急很难涉过，西边有一陡坡向上。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2698, 'qujing', 'qujing/pansi/jiandi2', '涧底', '山涧低洼地带，四处是涧水潺潺，几乎无法落脚。两边是高山峻岭，东边涧流水急很难涉过，上边有一陡坡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
