INSERT INTO `rooms` VALUES (2701, 'qujing', 'qujing/pansi/jiandi5', '涧底', '山涧低洼地带，四处是涧水潺潺，几乎无法落脚。两边是高山峻岭，东边涧流水急很难涉过，上边有一陡坡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2702, 'qujing', 'qujing/pansi/jiandi6', '涧底', '山涧低洼地带，四处是涧水潺潺，几乎无法落脚。两边是高山峻岭，东边涧流水急很难涉过，上边有一陡坡。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2703, 'qujing', 'qujing/pansi/jiankou1', '涧口', '山岩上一道细瀑蜿蜒而下，流作一溪山涧在脚下碎石中铺开，向东边绕道涧底流去。东边向上是一平台，对面是另一座高山，风景格外秀丽，却是咫尺天涯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2704, 'qujing', 'qujing/pansi/jiankou2', '涧口', '山岩上一道细瀑蜿蜒而下，流作一溪山涧在脚下碎石中铺开，向东边绕道涧底流去。东边向上是一平台，对面是另一座高山，风景格外秀丽，却是咫尺天涯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2705, 'qujing', 'qujing/pansi/ke', '客房', '客房供客人休息，南墙有一排纸窗，山鸟啾啭之声从窗外传进来。窗下有几把宽椅，东墙有一小供桌放着一铜炉，北面通向茶房。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2706, 'qujing', 'qujing/pansi/ling1', '岭道', '高山峻岭曲折盘绕，林原莽莽荒道坎坷。你走在一条荒芜的岭道上，时而有峭壁直立时而又有涧水长流。正是野润烟光淡，石翡山色翠。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2707, 'qujing', 'qujing/pansi/ling2', '岭道', '高山峻岭曲折盘绕，林原莽莽荒道坎坷。你走在一条荒芜的岭道上，时而有峭壁直立时而又有涧水长流。正是野润烟光淡，石翡山色翠。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
