INSERT INTO `rooms` VALUES (2711, 'qujing', 'qujing/pansi/ling6', '岭道', '高山峻岭曲折盘绕，林原莽莽荒道坎坷。你走在一条荒芜的岭道上，时而有峭壁直立时而又有涧水长流。正是野润烟光淡，石翡山色翠。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2712, 'qujing', 'qujing/pansi/ling7', '岭道', '高山峻岭曲折盘绕，林原莽莽荒道坎坷。你走在一条荒芜的岭道上，时而有峭壁直立时而又有涧水长流。正是野润烟光淡，石翡山色翠。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2713, 'qujing', 'qujing/pansi/maowu', '茅屋', '一座如仙庵一般的茅屋在眼前，茅屋前有一拱门。透过拱门可以看见里面如庄园一般，静悄悄。再往里看有一个木亭子。茅屋外东南面是一座石桥。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2714, 'qujing', 'qujing/pansi/menqian', '门前', '一座楼阁在山腰里静卧，只见山环庭院，溪绕亭台，柳间栖白鹭，桃内啭黄莺，好一个庵观寺院。门上嵌着一个石匾，上有“黄花观”三个大字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2715, 'qujing', 'qujing/pansi/menqiang', '门墙', '山岭上斜斜地竖立一座石头门墙，墙上骑着七彩墙头小草。门前遍地野花香艳艳，满旁兰蕙密森森。中间是一竹檐门洞，有一小径向下通去。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2716, 'qujing', 'qujing/pansi/muxiang', '木香亭', '木香亭八角玲珑，花草环绕。风吹铜铃丁当声脆。亭边有一小溪缓缓流过，清清雅雅。亭子的东面是茅草屋，往南可见一石头门洞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2717, 'qujing', 'qujing/pansi/nanpo', '南坡', '天光斜照，南坡下野草丛生乱石奇畸，坡上雾气如蒸熏熏然然令人头晕目眩。风吹过，声音有点凄凄惨惨。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2718, 'qujing', 'qujing/pansi/pian', '偏房', '偏房白墙红梁，有一窗户朝北开设，窗棂上挂有丹药葫芦，窗台上放有几个火罐。房里设有四方桌斜背椅，两扇门大开，通向东面的殿堂。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2719, 'qujing', 'qujing/pansi/qianhua', '千花洞', '你来到一个洞口，但见野花盛开万紫千红芬芳无比，洞边百藤盘缠艳果倒缀。透过洞口可见洞内是另一番奇景，有如世外桃源一般。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2720, 'qujing', 'qujing/pansi/qiaolin1', '乔林', '山原浩瀚秀丽，树木苍青葱翠，高大的乔木树林一望无际复盖着大地。林中歪歪斜斜地横着一条光秃秃的小径，径头不知通向何处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
