INSERT INTO `rooms` VALUES (2726, 'qujing', 'qujing/pansi/qiaolin7', '乔林', '山原浩瀚秀丽，树木苍青葱翠，高大的乔木树林一望无际复盖着大地。林中歪歪斜斜地横着一条光秃秃的小径，径头不知通向何处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2727, 'qujing', 'qujing/pansi/shandao1', '山道', '山道顺山势盘绕上下，峦青涧清景色宜人。道路两边或是绿林或是翠岭，猿啼鹃鸣野鹿踏茵荒无人烟，远远看去，苍松奇柏层层叠叠紫云遮天气象无穷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2728, 'qujing', 'qujing/pansi/shandao2', '山道', '山道顺山势盘绕上下，峦青涧清景色宜人。道路两边或是绿林或是翠岭，猿啼鹃鸣野鹿踏茵荒无人烟，远远看去，苍松奇柏层层叠叠紫云遮天气象无穷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2729, 'qujing', 'qujing/pansi/shandao3', '山道', '山道顺山势盘绕上下，峦青涧清景色宜人。道路两边或是绿林或是翠岭，猿啼鹃鸣野鹿踏茵荒无人烟，远远看去，苍松奇柏层层叠叠紫云遮天气象无穷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2730, 'qujing', 'qujing/pansi/shandao4', '山道', '山道顺山势盘绕上下，峦青涧清景色宜人。道路两边或是绿林或是翠岭，猿啼鹃鸣野鹿踏茵荒无人烟，远远看去，苍松奇柏层层叠叠紫云遮天气象无穷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2731, 'qujing', 'qujing/pansi/shidong', '石洞', '石洞里又是一番天地，但见冷气森森刺骨寒，一层层蜘蛛网叠将着坠下来，密密麻麻铺天盖地。你不禁打了一个寒战，倒吸一口寒气。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2732, 'qujing', 'qujing/pansi/shiqiao', '石桥', '山溪上一座石桥悠悠架起，两边古树森齐，桥下潺潺流水通长溪，桥东面是一望无际的乔木树林，桥西北面是茅草屋，清清雅雅若仙庵。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2733, 'qujing', 'qujing/pansi/shitou', '石头门', '石壁上青苔如云，有一门洞自然而成。门口怪石累累如笋如兽，自门楣上有滴水落下，嗒嗒有声。往北有一木亭，往南可见一逍遥石院。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2734, 'qujing', 'qujing/pansi/shiwu', '石屋', '落花中座立一玲珑石屋，屋边修竹翠绿枝枝秀，屋后红梅叶叶舒。石檐上紫花朵朵盛开，有鸟雀莺燕鸣唱。石屋一边是花涧缓流，另一面是碧溪潺潺。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2735, 'qujing', 'qujing/pansi/shiyuan', '石院', '庭院深深，花草盛茂。院子由山石垒就，中间有一白霜矮松，边上又是三五棵杂青树，藤条倒挂，周围芝兰香散万千花。西边有一厨廊，南边有一石洞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2736, 'qujing', 'qujing/pansi/wunei', '屋内', '石屋里清雅闲静，佛光笼罩，气氛极为祥和安宁。屋子中央有一佛榻，左边有一紫竹供桌放着瓷盘玉盏，右边有一青铜鼎，燃着缭绕香火。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2737, 'qujing', 'qujing/pansi/yuannei', '院内', '院内整整齐齐，碎砖铺路绿草茵荫。东北角堆着一些干茅草，有一石灶上架设一铜丹炉，青烟袅袅。砖路自门口往南铺设过去，通向一个厅门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2738, 'qujing', 'qujing/pansi/yuanwai1', '院外', '院外茅草丛生，阴风朔朔令人不禁有点胆寒。南面是一座高大的墙，墙根下面有一暗洞直通黄花观院内。北面是绝路悬崖峭壁，无路可行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2739, 'qujing', 'qujing/pansi/yuanwai2', '院外', '院外茅草丛生，阴风朔朔令人不禁有点胆寒。南面是一座高大的墙，墙根下面有一暗洞直通黄花观院内。北面是绝路悬崖峭壁，无路可行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2740, 'qujing', 'qujing/pansi/zheng', '正厅', '正厅为一殿堂，窗明几净，设有三清圣象。堂心放有一桃木花心供桌，上面有兽脚铜炉一只，里面有香火燃烟。殿堂的左右各有两扇双推门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2741, 'qujing', 'qujing/pansi/zhuogou', '濯垢泉', '一塘热泉水雾气重重，一座十丈多长，五丈余阔的浴池在这里展开。透过热气但见水清彻底，有四尺多深。池底水似滚珠泛玉，骨都都冒将上来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'spring');
INSERT INTO `rooms` VALUES (2748, 'qujing', 'qujing/pingding/beidong', '北洞', '北洞里面靠墙的地方垒着几块大石头，石头已被熏得漆黑，上面吊着一口大铁锅，石头边放着山柴，干草等。西南方有一出口通向洞门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2749, 'qujing', 'qujing/pingding/dating', '大厅', '环顾四周，可见大厅颇具规模，里面放着木桌木椅之类，大厅的北面悬挂着一口铜钟，由蔓藤牵动着。西边有通道引向莲花洞的前厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2750, 'qujing', 'qujing/pingding/dongmen', '洞门', '洞门里有山涧流过，山涧之上有一石栏曲桥，一头通向洞外，另一头在洞里连向高处。高处有几个大小不同的通道，分别导向洞的纵深地带。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2751, 'qujing', 'qujing/pingding/dongwai', '洞外', '一道山涧从脚下流过，发出潺潺的流水声。山涧的去处有一片绿色林木，林木的后面有一山洞，洞的上沿有一凿平的石壁，上面刻着：平顶山莲花洞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2752, 'qujing', 'qujing/pingding/guatan', 'guatan', '一件挂毯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2753, 'qujing', 'qujing/pingding/nandong', '南洞', '南洞里几块大石上晾着兽皮之类的东西，洞穴里鬼旋风打转，发出呜呜的声响。洞顶低垂，从上挂下钟乳石，洞的北面通向洞的出口。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2754, 'qujing', 'qujing/pingding/neidian', '内殿', '石洞在这里宽敞起来，形成一个殿厅。殿里有半人高的石块，上面搭着长木板，边上有石鼓和石桩子。殿的东边是卧室，东北边通向石廊。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2755, 'qujing', 'qujing/pingding/ping1', '平顶山', '山岭巍峨起伏，峰顶气势缓平，天边泛起一层彩霞，云雾之中遍野林海更加郁郁苍苍。在这里道路平坦，路边有小灌木一丛一丛，古树萧萧。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2756, 'qujing', 'qujing/pingding/ping2', '平顶山', '山岭巍峨起伏，峰顶气势缓平，天边泛起一层彩霞，云雾之中遍野林海更加郁郁苍苍。在这里道路平坦，路边有小灌木一丛一丛，古树萧萧。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2757, 'qujing', 'qujing/pingding/ping3', '平顶山', '山岭巍峨起伏，峰顶气势缓平，天边泛起一层彩霞，云雾之中遍野林海更加郁郁苍苍。在这里道路平坦，路边有小灌木一丛一丛，古树萧萧。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2758, 'qujing', 'qujing/pingding/ping4', '平顶山', '山岭巍峨起伏，峰顶气势缓平，天边泛起一层彩霞，云雾之中遍野林海更加郁郁苍苍。在这里道路平坦，路边有小灌木一丛一丛，古树萧萧。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2759, 'qujing', 'qujing/pingding/qianting', '前厅', '前厅的四周是狰狞的石壁，石壁上渗出一滴滴的水珠，长着青青的苔藓。厅的西边有一个出口，通向洞门，往东是一石门洞，里面燃着篝火。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2760, 'qujing', 'qujing/pingding/shan1', '山道', '崎岖的山道在山坡上蜿蜒，四处是荒山野岭，云雾蒙蒙一片，远看林海郁郁苍苍。路边有不尽的古树和藤葛，西风阵阵，吹得满天的风沙。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2761, 'qujing', 'qujing/pingding/shan10', '山道', '崎岖的山道在山坡上蜿蜒，四处是荒山野岭，云雾蒙蒙一片，远看林海郁郁苍苍。路边有不尽的古树和藤葛，西风阵阵，吹得满天的风沙。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
