INSERT INTO `rooms` VALUES (2772, 'qujing', 'qujing/pingding/shan8', '山道', '崎岖的山道在山坡上蜿蜒，四处是荒山野岭，云雾蒙蒙一片，远看林海郁郁苍苍。路边有不尽的古树和藤葛，西风阵阵，吹得满天的风沙。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2773, 'qujing', 'qujing/pingding/shan9', '山道', '崎岖的山道在山坡上蜿蜒，四处是荒山野岭，云雾蒙蒙一片，远看林海郁郁苍苍。路边有不尽的古树和藤葛，西风阵阵，吹得满天的风沙。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2774, 'qujing', 'qujing/pingding/shilang1', '石廊', '洞在这里略显狭窄，左右都是粗糙的石壁，有滴水缓缓流下，落在地上发出叮咚的声音。东北方有光线从洞外斜照进来，南边仍然有另一个石壁。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2775, 'qujing', 'qujing/pingding/shilang2', '石廊', '石廊在此有一点回转，两边的石壁上长着褐色的地衣，布满整个壁面。地上坑坑洼洼，积着几汪泥水。石廊的西南通向莲花洞的内殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2776, 'qujing', 'qujing/pingding/shimen', '石门', '山岩的下面，有一突出的巨石，宛若门檐一般。石门的一侧竖着刻有一列文字，上面写着：压龙山压龙洞。石门的东南方有一入口通向洞里面。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2777, 'qujing', 'qujing/pingding/wofang1', '卧房', '卧房的地上铺着野草干花，南边的石壁前有一红木桌，上面点着一盏青玉灯，北边的石壁上有一石龛。卧房的西边有一走廊通往内殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2778, 'qujing', 'qujing/pingding/wofang2', '卧房', '一个石卧房，地上铺着各种兽皮，石壁上也挂满了兽皮兽头兽角。靠墙边是一张黛色石桌，一张大木椅。东北方向有一石门通往内殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2779, 'qujing', 'qujing/pingding/wulin1', '乌林子', '黑压压远远一片林子，树木茂密，杂草有齐胸高。乱石丛中有一条弯曲的小路，路上碎石高高低低地铺开。风吹草动，仿佛四周有眼睛在暗处盯着你。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2780, 'qujing', 'qujing/pingding/wulin2', '乌林子', '黑压压远远一片林子，树木茂密，杂草有齐胸高。乱石丛中有一条弯曲的小路，路上碎石高高低低地铺开。风吹草动，仿佛四周有眼睛在暗处盯着你。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2781, 'qujing', 'qujing/pingding/yalong1', '压龙山', '山脊起伏，云雾缥缈一片，在此可见四处森林茂密，一些山岩奇峰从树木中耸立出来，长着青苔地衣，色彩如斑如锈。小路从山脊上蜿蜒地穿过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2782, 'qujing', 'qujing/pingding/yalong2', '压龙山', '山脊起伏，云雾缥缈一片，在此可见四处森林茂密，一些山岩奇峰从树木中耸立出来，长着青苔地衣，色彩如斑如锈。小路从山脊上蜿蜒地穿过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2783, 'qujing', 'qujing/pingding/yalong3', '压龙山', '山脊起伏，云雾缥缈一片，在此可见四处森林茂密，一些山岩奇峰从树木中耸立出来，长着青苔地衣，色彩如斑如锈。小路从山脊上蜿蜒地穿过。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2806, 'qujing', 'qujing/qilin/bopi', '剥皮亭', '剥皮亭里气氛阴森，亭子四处穿风八面明亮。亭上挂着各式大小不一的兽皮兽头，中间放有一把戗金的交椅。两边有一些妖怪喽猡手持兵器分行站立。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2807, 'qujing', 'qujing/qilin/chenglei', '承雷石', '山环路低洼出耸立一座高大的石崖，如石碑一般。崖顶曾被山雷劈开，缺口处长了一棵矮松，云在崖顶缓缓飘过。这里似乎可以听见远远的禽咽兽吼之声从林涛中传来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2808, 'qujing', 'qujing/qilin/dinglu', '鼎炉厅', '大厅里放着一长条石桌，厅堂后是一巨型铜鼎，下面火光闪闪。石桌上放着各色果菜，又摆着獐狸鹿兔之类的野味。大厅的里门通向帅府宫，东边通向偏宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2809, 'qujing', 'qujing/qilin/dongkou', '洞口', '拐弯处一个巨大的洞口，如巨兽一般张开血盆大口。洞里灯火通明沸沸扬扬，洞口旌旗飘闪。洞的正上方有一巨岩凸出，写着“麒麟山獬豸洞”几个大字。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2810, 'qujing', 'qujing/qilin/dongnei', '洞内', '洞内十分宽敞，悬崖石壁霞光升顶，左右有琪花瑶草，前后是古柏乔松，洞壁上燃着盏盏吊油灯，烟熏火燎。两侧站着些大小妖怪森森罗列。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2811, 'qujing', 'qujing/qilin/hougong', '后宫', '后宫门口悬着两排彩灯，宫内绘有金银双凤戏水。内壁处有一玉石屏风，下有玛瑙梳妆台和一张麒麟床褥。西南朝向有一宫门，由几位伺女守候着。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2812, 'qujing', 'qujing/qilin/piangong', '偏宫', '偏宫里明烛高照，洞宽顶阔有如高堂大殿。西南边有一通道导向洞内大厅，东南边有一洞门通往剥皮亭，再往西则又是另一个妖怪们议事的大堂，东北边可见一虹彩门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2813, 'qujing', 'qujing/qilin/polu1', '坡路', '天阳门外一条长路斜斜地向东北方向蜿蜒而去，极目远眺可见山色茫茫云雾渺渺，一座巅峰挡住雾角，不知是何去处。路上行人很少且行色匆匆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2814, 'qujing', 'qujing/qilin/polu2', '坡路', '坡路渐陡渐窄，山色茫茫云雾渺渺，东南方向的巅峰冲天占地，挡住雾角，岭头松郁郁。路旁岩崖石磷磷高耸，往东可以遥遥望见朱紫国城池。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2815, 'qujing', 'qujing/qilin/polu3', '坡路', '坡路渐陡渐窄，山色茫茫云雾渺渺，东南方向的巅峰冲天占地，挡住雾角，岭头松郁郁。路旁岩崖石磷磷高耸，往东可以遥遥望见朱紫国城池。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2816, 'qujing', 'qujing/qilin/polu4', '坡路', '坡路渐陡渐窄，山色茫茫云雾渺渺，东南方向的巅峰冲天占地，挡住雾角，岭头松郁郁。路旁岩崖石磷磷高耸，往南是一道绝壁将道路封死。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2817, 'qujing', 'qujing/qilin/shan11', '山环路', '山环路道险路窄，路外围是悬崖，失足掉下去可能会粉身碎骨，路的内侧是陡峭的石壁。周围长着稀稀拉拉的一些树林，你已分不太清东南西北了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2818, 'qujing', 'qujing/qilin/shan12', '山环路', '山环路道险路窄，路外围是悬崖，失足掉下去可能会粉身碎骨，路的内侧是陡峭的石壁。周围长着稀稀拉拉的一些树林，你已分不太清东南西北了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
