INSERT INTO `rooms` VALUES (2823, 'qujing', 'qujing/qilin/shan23', '山环路', '山环路道险路窄，路外围是悬崖，失足掉下去可能会粉身碎骨，路的内侧是陡峭的石壁。周围长着稀稀拉拉的一些树林，你已分不太清东南西北了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2824, 'qujing', 'qujing/qilin/shan24', '山环路', '山环路道险路窄，路外围是悬崖，失足掉下去可能会粉身碎骨，路的内侧是陡峭的石壁。周围长着稀稀拉拉的一些树林，你已分不太清东南西北了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2825, 'qujing', 'qujing/qilin/shankou', '山口', '好一个麒麟山顶！冲天处尖峰耸立，占地处远脉迢迢。这里是麒麟山口，南边呈谷状，长满山草山花。西北边则光秃秃赭红色一片似火烧过一般。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2826, 'qujing', 'qujing/qilin/shuaifu', '帅府宫', '帅府宫里恶气横生，宫内四周墙上挂满各类兽头兽骨，地上铺开虎皮豹皮，中间一玉石雕纹桌，宫后有一张龙虎巨床。东南方向有一洞门通向鼎炉厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2827, 'qujing', 'qujing/qilin/yading', '崖顶', '这里是山坳处一略凸起的崖坡，四处可听见山禽声咽咽，山兽吼呼呼。然而脚下则如火焚过一般红焦一片，不远处有一小坡，坡上满是流沙。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2828, 'qujing', 'qujing/qilin/yutai', '玉台', '山环路的开阔地带处，立有一块凸出于山外的大石，洁白净光无草无藓样子奇特。大石平滑可并排坐下二人，石头的下侧刻有两个大字：“玉石”。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2837, 'qujing', 'qujing/qinfa/beishi', '北市', '这里市容整洁，路面翻修一新，由六角石镶嵌而铺就。四周种着果子树，散发着淡香气。往南是更为热闹的中市，往北是乾坤场。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2838, 'qujing', 'qujing/qinfa/bupu', '布铺', '铺子里放着一匹匹的彩染布料和粗绳细线，门口挂着一些供出售的衣服绸袍纱裙毡帽。屋子里面挑着一盏油灯，有几条长凳就着墙角放着。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2839, 'qujing', 'qujing/qinfa/dalu1', '大路', '一条烟尘漫漫的大路，其路遥遥，其雾茫茫，前不见古人后不见来者。时而有远方兽吼，时而又有近处鸟鸣。两边荒山野林交替出现，你不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2840, 'qujing', 'qujing/qinfa/dalu10', '大路', '一条烟尘漫漫的大路，其路遥遥，其雾茫茫，前不见古人后不见来者。时而有远方兽吼，时而又有近处鸟鸣。两边荒山野林交替出现，你不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
