INSERT INTO `rooms` VALUES (2852, 'qujing', 'qujing/qinfa/dalu8', '大路', '一条烟尘漫漫的大路，其路遥遥，其雾茫茫，前不见古人后不见来者。时而有远方兽吼，时而又有近处鸟鸣。两边荒山野林交替出现，你不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2853, 'qujing', 'qujing/qinfa/dalu9', '大路', '一条烟尘漫漫的大路，其路遥遥，其雾茫茫，前不见古人后不见来者。时而有远方兽吼，时而又有近处鸟鸣。两边荒山野林交替出现，你不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2854, 'qujing', 'qujing/qinfa/dongmen', '东门', '长长的城墙由石条砌就，城门外的护城河已几乎干涸，正中是一座城楼，设有两扇护铜甲硬木城门，铺有一双行石板大道，通向城内外。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2855, 'qujing', 'qujing/qinfa/fenggong', '凤宫', '凤宫里四周挂着花翎凤羽，四面是贴彩百棂窗。宫殿里插着两面巨型凤尾扇。扇下有一翠绿银竹镂花床，铺着玫瑰红鸳鸯锦丝被褥。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2856, 'qujing', 'qujing/qinfa/gongmen', '宫门', '宫门霞飞虹飘，各色旌旗迎风招扬，门上架着一巨大的飞檐，下面是双曲汇彩回廊，由九根红柱撑住。北面有一栅栏门，东面是殿阁。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2857, 'qujing', 'qujing/qinfa/guafu', '寡妇店', '寡妇店乃是一家客店，门前挑着一招牌，绣着“赵家寡妇店”五个大字。店堂内一尘不染，有一些床铺靠墙而放，床与床之间以布屏隔开。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2858, 'qujing', 'qujing/qinfa/jiedao1', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，东面南面有路通向其他的街道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2859, 'qujing', 'qujing/qinfa/jiedao2', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，东面是乾坤场，北面有一布铺的招牌。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2860, 'qujing', 'qujing/qinfa/jiedao3', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，南北面各有路口，东面飘来阵阵酒香。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2861, 'qujing', 'qujing/qinfa/jiedao4', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，西面的店铺门口晒着一些皮货。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2862, 'qujing', 'qujing/qinfa/jiedao5', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，西面的店铺门口晒着一些皮货。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2863, 'qujing', 'qujing/qinfa/jiedao6', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，西面是五鼓楼，东面通向其它的街道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2864, 'qujing', 'qujing/qinfa/jiedao7', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，西面有一路口，东面通向中市。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2865, 'qujing', 'qujing/qinfa/jiedao8', '街道', '街道宽敞，两边或是商店门铺，或是住宅庭院，墙上爬满藤花蔓草。街上各色行人人来来往往颇为热闹，东面西面均有客店供远途旅客歇脚，南边是一座城门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2866, 'qujing', 'qujing/qinfa/jinluan', '金銮殿', '此殿为国王朝政和会见外宾的场所，大殿里铺设有一级级青玉台阶，每一级台阶上左右各一对金银大鼎燃着香烟袅袅。西面的大门通向殿外，东面有琉璃拱门通向宫内。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2867, 'qujing', 'qujing/qinfa/jiupu', '酒铺', '酒铺外撑着一长棚，几张桌子从屋外一直铺到屋里，上面零乱地放着酒罐子，粗酒碗和点心碟子，地上扔有一些花生皮壳。几位酒客在摇头晃脑地猜着酒拳。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2868, 'qujing', 'qujing/qinfa/junying', '军营', '木制的军营里戒备森严，门廊里有一列士兵盔甲一身贝插彩旗整齐站立，目不斜视。营内隐约可听见战马嘶鸣，不时有铜鼓声传来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2869, 'qujing', 'qujing/qinfa/longgong', '龙宫', '一条长长的回廊环绕，中间是盘龙的宫室，由八面玲珑的金色屏风围起，铺有橙红色云彩绒毯，上面有一细鳞缎绣龙头龙尾望月龙床。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2870, 'qujing', 'qujing/qinfa/mipu', '米铺', '店里面一字排开放着米袋，米袋打开，露出白色的大米和面粉。柜台上有一石磨，供磨香料之类的作料。几只陶罐里放着油盐酱菜。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2871, 'qujing', 'qujing/qinfa/nanmen', '南门', '长长的城墙由石条砌就，城门外的护城河已几乎干涸，正中是一座城楼，设有两扇护铜甲硬木城门，铺有一双行石板大道，通向城内外。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2872, 'qujing', 'qujing/qinfa/nanshi', '南市', '南市是一片住宅区和客店，整个街道被高高低低的石墙土墙围住，有开满花的蔓藤爬满了四面的墙。往南远远望去可见街道上挂满了灯笼招牌，往北可以看见中市。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2873, 'qujing', 'qujing/qinfa/pihuopu', '皮货铺', '门口晒着几张刚硝好的皮革，屋里摆满各式各样的皮货和野兽皮。屋角排着几口大染缸，里面还染着一些皮货。窗子下有货架陈列着待售的皮制品。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2874, 'qujing', 'qujing/qinfa/qiankun', '乾坤场', '场子上设有一旗杆，几面幡旗随风飘荡。往东面看去有殿宇琼楼幢幢，那里是王宫之所在。西面是热闹的街道，不时传来一些嘈杂的人声。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2875, 'qujing', 'qujing/qinfa/qingong1', '寝宫', '寝宫里陈列着百鸟绣花图，四周是常春花卉。窗外滴水潺潺，屋内香火缈缈，放着几只精制紫色香木几，中间是双枕鹅绒软褥宫床。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2876, 'qujing', 'qujing/qinfa/qingong2', '寝宫', '寝宫里陈列着百鸟绣花图，四周是常春花卉。窗外滴水潺潺，屋内香火缈缈，放着几只精制紫色香木几，中间是双枕鹅绒软褥宫床。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2877, 'qujing', 'qujing/qinfa/tianjing', '天井', '小小院子里铺着石条，墙边种着无名花草，墙上爬着藤条结着棘皮葫芦。院子一角架有一木架，架上拉着长绳晒着几件洗净的衣服。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2878, 'qujing', 'qujing/qinfa/wugu', '五鼓楼', '五鼓楼上彩带飞舞，楼下人群熙熙攘攘。日出日落击鼓，星月满天时分则敲梆报夜安。东西两边是街道，南北两端则各有一些铺子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2879, 'qujing', 'qujing/qinfa/xiaoer', '小二店', '小二店是一家平矮的木楼客店，店铺门口挂有几个招牌灯笼，上面写着“王小二店”，门口放着一些鞋物，屋里是一排大通铺，整整齐齐地叠着被褥。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2880, 'qujing', 'qujing/qinfa/yaopu', '药铺', '药铺三面是药柜，柜上是大大小小的铜把抽屉，上面整整齐齐地贴有药签。一张杜松木桌放在屋中间，摆着几只瓷药盅和红泥药罐子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2881, 'qujing', 'qujing/qinfa/zahuopu', '杂货铺', '铺面不大不小，地上摆着零零散散的日用品。低低的天花板上悬下一些挂钩吊篮，篮子里面也放着一些待出售的货物。南面的铺门大开，通向五鼓楼的广场。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2882, 'qujing', 'qujing/qinfa/zhongshi', '中市', '中市为一片开阔地带，附近的楼阁平房已被拆卸一空，东南面原有一红殿庙宇不知何故被推倒，只剩下残砖剩瓦。正东是一座城楼，南北两边各有一广场，西面有长长的街道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2888, 'qujing', 'qujing/qinglong/dongkou', '洞口', '只见山中恍然一个飘着雾气的洞口，洞口向南大开，上有无数青藤自崖顶挂下来，两边的怪石狰狞如兽牙。洞上写着几个大字：青龙山玄英洞。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2889, 'qujing', 'qujing/qinglong/dongshan', '东山凹', '四周一片雾气，有一长练般的瀑布从西山口流下来，冲进东边的山涧里。这里地势平凹，山涧在脚下打着漩涡流过。西边有一天然石梯拾级而上。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2890, 'qujing', 'qujing/qinglong/dongting', '洞厅', '洞厅乃一较大的洞穴，里面洞壁上插着兽油火把，中间有石桌石凳。洞的深处有一排排兵器架，洞的东南方向有一通道，通向洞外。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2891, 'qujing', 'qujing/qinglong/jian1', '山涧', '山路绕过一个轰然作响的山涧，这里地势低平，东边岩石下涧水急速地冲走，腾起一片白白的雾气。西北边有一个山凹，西南有一下山的斜坡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2892, 'qujing', 'qujing/qinglong/jian2', '山涧', '山路绕过一个轰然作响的山涧，这里地势低平，东边岩石下涧水急速地冲走，腾起一片白白的雾气。西北边有一个山凹，西南有一下山的斜坡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2893, 'qujing', 'qujing/qinglong/shanding', '山顶', '站在山顶上望过山脉，一望无际的绿色森林蜿蜒起伏有如一条长长的青龙，山顶上风大雾多，四周的野兽吼叫声似乎更加近了一些了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2894, 'qujing', 'qujing/qinglong/shanjian', '山涧', '山路绕过一个轰然作响的山涧，这里地势低平，东边岩石下涧水急速地冲走，腾起一片白白的雾气。西北边有一个山凹，西南有一下山的斜坡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2895, 'qujing', 'qujing/qinglong/shanlu1', '山路', '山上一望无边的绿色森林，狂风吹过，林涛怒吼，远处的兽吼声阵阵传来。山路盘山而绕，岩崖看上去十分陡峭，路面崎岖且极为狭窄。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2896, 'qujing', 'qujing/qinglong/shanlu2', '山路', '山上一望无边的绿色森林，狂风吹过，林涛怒吼，远处的兽吼声阵阵传来。山路盘山而绕，岩崖看上去十分陡峭，路面崎岖且极为狭窄。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
