INSERT INTO `rooms` VALUES (2900, 'qujing', 'qujing/qinglong/shanlu6', '山路', '山上一望无边的绿色森林，狂风吹过，林涛怒吼，远处的兽吼声阵阵传来。山路盘山而绕，岩崖看上去十分陡峭，路面崎岖且极为狭窄。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2901, 'qujing', 'qujing/qinglong/shanlu7', '山路', '山上一望无边的绿色森林，狂风吹过，林涛怒吼，远处的兽吼声阵阵传来。山路盘山而绕，岩崖看上去十分陡峭，路面崎岖且极为狭窄。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2902, 'qujing', 'qujing/qinglong/shantou', '山头', '奇峰异石边出现一开阔地带，脚下东南边是长长的绿色森林，东边是绝壁，下边是万丈深渊。西边岩石狰狞，似乎无路可言，东北方向比较平坦些。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2903, 'qujing', 'qujing/qinglong/tongdao1', '通道', '通道里面怪石遍地，两边洞壁上爬着无名蔓草。南边有光线射进，那里是玄英洞的洞口，西北方向有一更大的洞穴，通道向东边延伸而去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2904, 'qujing', 'qujing/qinglong/tongdao2', '通道', '通道由东西向延伸开，洞比较狭窄，洞壁上长着绿色的蔓草，怪石遍地。东边有三个洞穴入口，不知通向何处，通道的西边有光线传进。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2905, 'qujing', 'qujing/qinglong/wowang1', '卧王室', '卧王室里十分富丽堂皇，洞壁上点着三盏酥香油灯。地上铺着一层花兽皮褥，室心放着一玉雕长桌，桌上胡乱地堆着几只金盏银盅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2906, 'qujing', 'qujing/qinglong/wowang2', '卧王室', '屋子里几盏酥香油灯照得四周通明，靠里面的洞壁放着一青花木嵌银柜，一张镂花兽腿仙桌，上有透明玉雕大肚坛子，里面盛着酥香油。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2907, 'qujing', 'qujing/qinglong/wowang3', '卧王室', '王室门口放着一白铜大鼎，鼎里散发着酥香油的醇香味。室内有一金边红纹木案，上面点着三盏酥香油灯，将屋子照得一片通亮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2918, 'qujing', 'qujing/qujingren/obstacled', 'obstacled', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2919, 'qujing', 'qujing/qujingren/qujingquest', 'qujingquest', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2920, 'qujing', 'qujing/qujingren/qujingren', 'qujingren', '灵通本讳号金蝉，只为无心听佛讲，转托尘凡苦受磨，降生世俗遭罗网。投胎落地就逢凶，未出之前临恶党。父是海州陈状元，外公总管当朝长。出身命犯落江星，顺水随波逐浪泱。海岛金山有大缘，迁安和尚将他养。年方十八认亲娘，特赴京都求外长，总管开山调大军，洪州剿寇诛凶党。状元光蕊脱天罗，子父相逢堪贺奖。复谒当今受主恩，凌烟阁上贤名响。恩官不受愿为僧，洪福沙门将道访。小字江流古佛儿，法名换做陈玄奘。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2921, 'qujing', 'qujing/qujingren/shengsilunlui', '生死轮回处', '世人都晓神仙好，惟有功名忘不了！\r\n古今将相在何方？荒冢一堆草没了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2922, 'qujing', 'qujing/qujingren/team', 'team', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2923, 'qujing', 'qujing/qujingren/changan/qujingren', 'qujingren', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2927, 'qujing', 'qujing/qujingren/tianmo/miao', '天魔庙', '<span style=\"color:lightskyblue;\">小小的地方却供奉着一尊很大的神像,最上方的条幅上写着“天魔庙”</span>.这天魔不知道是何方神圣，小庙里香火不断，挂满了“有求必应”，”长命百岁“.看来还是很灵验的，让你忍不住也想叩拜。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2928, 'qujing', 'qujing/qujingren/tianmo/zlf', '蒸笼房', '<span style=\"color:lightskyblue;\">一个偌大的蒸笼放在房子中央,四处烟雾弥漫,热气腾腾,奇怪的是竟然没有一丝火星.</span>你只感觉到热,</span>你可以感觉得到隐藏的危机.非常中国风格的走廊,<span style=\"color:lightskyblue;\">习惯性的雕龙刻凤.</span>美和丑,<span style=\"color:lightskyblue;\">善和恶就这样矛盾的交织着。</span>还有一股莫名的香味.</span>', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2929, 'qujing', 'qujing/qujingren/tianmo/zoulang1', '第一走廊', '<span style=\"color:lightskyblue;\">一条长长的走廊被分成了好几个关口,这里是第一关.</span>你可以感觉得到隐藏的危机.非常中国风格的走廊,<span style=\"color:lightskyblue;\">习惯性的雕龙刻凤.</span>美和丑,<span style=\"color:lightskyblue;\">善和恶就这样矛盾的交织着。</span>', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
