INSERT INTO `rooms` VALUES (2938, 'qujing', 'qujing/start/room', '诸天胜境', '山如淡墨飘渺，水似凝脂无波。龙马驾辕车乘来去，飞天伴舞管弦不绝。前有二四金宫，发千道霞光，环绕祥云万朵，现诸天胜境。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
