INSERT INTO `rooms` VALUES (2966, 'qujing', 'qujing/start/tudi/changan', 'changan', '你看到一位身材高大的汉子，正在辛苦地操练着。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2967, 'qujing', 'qujing/start/tudi/city', 'city', '一位白胡子老公公。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2968, 'qujing', 'qujing/tianzhu/baijiao', '百脚山麓', '山林浓密黑压压地起伏，山路沿着山势蜿蜒，坎坎坷坷不平。从浓密的山林里偶然可以听野兽远远的吼叫，路边风吹草动沙沙作响。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2969, 'qujing', 'qujing/tianzhu/baodian', '宝殿', '殿上供着一尊大佛，佛象的周围有香案香炉，香炉里插着几柱香袅袅地冒着烟。殿东地上铺着几块干净的蒲团，佛象后往西有一道门开着，通向里面。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2970, 'qujing', 'qujing/tianzhu/budao', '布道场', '布道场是一个干净的大屋子，道场前排为草蒲团，后排放了一一排一排的木凳子。布道场的台上放着一个乌铁鼎，足有大半个人高。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2971, 'qujing', 'qujing/tianzhu/budian', '布店', '布店里搭起了两排木架子，架子上摆着一些布匹，有素色布染花布织花布粗布细布绸缎锦棉等等。屋子的东面是半人高的黄木柜台。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2972, 'qujing', 'qujing/tianzhu/chanfang', '禅房', '这个禅房已经有一段时间不用了，墙土脱落，地上有一层厚灰，墙角垫着几张破旧的蒲团，蒲团上盖了一件素布长僧袍。禅房的西北边有一门，通向后院的菜园小道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2973, 'qujing', 'qujing/tianzhu/chengyi', '成衣店', '成衣店里挂着五颜六色的衣裳袍裙，衣服多种多样，各种艳丽朴素花色应有尽有。一排排地从屋前的绳子上挂到屋后，有不少人在此挑选合适的衣服。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2974, 'qujing', 'qujing/tianzhu/dalu1', '大路', '一条长长的野外大路，路上铺着碎石子，路边开着无名花草。大路在平坦的原野上弯曲地蜿蜒。远处可见青青群峦起伏于云雾之中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2975, 'qujing', 'qujing/tianzhu/dalu2', '大路', '一条长长的野外大路，路上铺着碎石子，路边开着无名花草。大路在平坦的原野上弯曲地蜿蜒。远处可见青青群峦起伏于云雾之中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2976, 'qujing', 'qujing/tianzhu/dalu3', '大路', '一条长长的野外大路，路上铺着碎石子，路边开着无名花草。大路在平坦的原野上弯曲地蜿蜒。远处可见青青群峦起伏于云雾之中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2977, 'qujing', 'qujing/tianzhu/dalu4', '大路', '一条长长的野外大路，路上铺着碎石子，路边开着无名花草。大路在平坦的原野上弯曲地蜿蜒。远处可见青青群峦起伏于云雾之中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2978, 'qujing', 'qujing/tianzhu/dalu5', '大路', '一条长长的野外大路，路上铺着碎石子，路边开着无名花草。大路在平坦的原野上弯曲地蜿蜒。远处可见青青群峦起伏于云雾之中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2979, 'qujing', 'qujing/tianzhu/dangpu', '当铺', '沿街的铺面挑着当字招牌，当铺里有一个大半人高的柜台，柜台里放着各种各样典当的东西，柜前坐着当铺的老板，满面堆笑地接待着客人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2980, 'qujing', 'qujing/tianzhu/dongmen', '东门', '一条长长的护城河出现在眼前，有两丈多深，上面架着一巨大的铁链木桥。桥头是一高大的城楼，用山石砌成，楼顶上有了望哨。城楼书有三个大字：天竺国。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2981, 'qujing', 'qujing/tianzhu/fang', '方丈', '方丈室明亮宽敞，南边有一斗窗，窗下有一木制经桌，桌上放着经书木鱼木锤之类。北边有一小茶桌，边上几把木椅木凳。东边有一门通向宝殿下。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2982, 'qujing', 'qujing/tianzhu/feng', '凤亭', '这是一座绯色瓦顶的双层凤亭，亭檐上雕着飞凤望月，亭里楣木上是凤翔万里图。凤亭外西边有一十三曲桥廊，通向宫中的御花园。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2983, 'qujing', 'qujing/tianzhu/gongyuan', '宫院', '宫院里鲜花百草丛丛，院心里铺着六色碎石子，一条彩廊自东向西弯弯曲曲通过。彩廊的东边通向华夷阁，彩廊的西边通向昭阳宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2984, 'qujing', 'qujing/tianzhu/guaguo', '瓜果店', '一个青竹棚里，摆了一排排的竹筐，筐子里放着各种新鲜的瓜果正待出售。不时有路人进进出出光顾瓜果店，买下一些水果瓜类。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2985, 'qujing', 'qujing/tianzhu/guanglu', '光禄寺', '光禄寺红墙青瓦，自街上看去十分醒目。寺里从里到外装修一新，朱漆门彩绘塑象亮铜香炉。一个雕花香案上放着一副新的木鱼木锤，地上的铺着绣花葡团。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2986, 'qujing', 'qujing/tianzhu/guaqian', '卦签铺', '卦签铺里摆了一仙桌，上面有几本羊皮书，几只雕花白石签筒里插着大大小小的竹签。铺角有一香案，上有一只细脚香炉，炉里插着几根已经熄了的香。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2987, 'qujing', 'qujing/tianzhu/hou1', '后宫', '后宫装饰艳丽，粉墙上摆着一排排的凤尾屏扇。朝北有一排玉格窗，挂着珍珠帘。南宫墙下放着雾纹桌和云晕椅。桌上的梳妆台散发着迷人的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2988, 'qujing', 'qujing/tianzhu/hou2', '后宫', '后宫装饰艳丽，粉墙上摆着一排排的凤尾屏扇。朝北有一排玉格窗，挂着珍珠帘。南宫墙下放着雾纹桌和云晕椅。桌上的梳妆台散发着迷人的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2989, 'qujing', 'qujing/tianzhu/hou3', '后宫', '后宫装饰艳丽，粉墙上摆着一排排的凤尾屏扇。朝北有一排玉格窗，挂着珍珠帘。南宫墙下放着雾纹桌和云晕椅。桌上的梳妆台散发着迷人的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2990, 'qujing', 'qujing/tianzhu/hou4', '后宫', '后宫装饰艳丽，粉墙上摆着一排排的凤尾屏扇。朝北有一排玉格窗，挂着珍珠帘。南宫墙下放着雾纹桌和云晕椅。桌上的梳妆台散发着迷人的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2991, 'qujing', 'qujing/tianzhu/hou5', '后宫', '后宫装饰艳丽，粉墙上摆着一排排的凤尾屏扇。朝北有一排玉格窗，挂着珍珠帘。南宫墙下放着雾纹桌和云晕椅。桌上的梳妆台散发着迷人的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2992, 'qujing', 'qujing/tianzhu/houyuan', '后院', '一条泥土道穿过月门从北边的寺院通到这里，东边有几片菜地种着一些蔬菜，菜地旁搭了一个瓜架，上面结着绿油油的小翠瓜。南边的屋子有个烟囱，冒着青烟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2993, 'qujing', 'qujing/tianzhu/huapu', '花铺', '花铺里一阵清香扑鼻，沿街的门口种着一些鲜花，铺里面墙头挂着五颜六色的干花草，柜台上则是许多漂亮的花瓶，瓶内插着各式各样的鲜花。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2994, 'qujing', 'qujing/tianzhu/huayi', '华夷阁', '华夷阁有十来丈之高，以精雕木建就，四周绘着彩色图案，西边的阁门通向一条彩廊。阁内色彩鲜艳装璜华丽，风吹过来，有无数檐铃叮咚作响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2995, 'qujing', 'qujing/tianzhu/jiang', '酱房', '酱房里远远就能闻到酱菜的味道，里面放着一溜子大腌缸，缸里泡着各式酱菜腌菜，菜上面用青石板压着出水，上面再用木盖将缸盖严。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (2996, 'qujing', 'qujing/tianzhu/jiedao11', '街道', '街道上人来人往，两边是各式各样的商店铺面酒馆药房等等，应有尽有。五花八门的招牌幡旗临街挑起，不时可听见贩子们的吆喝声从街上传来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
