INSERT INTO `rooms` VALUES (3030, 'qujing', 'qujing/tianzhu/jiedao97', '街道', '街道上人来人往，两边是各式各样的商店铺面酒馆药房等等，应有尽有。五花八门的招牌幡旗临街挑起，不时可听见贩子们的吆喝声从街上传来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3031, 'qujing', 'qujing/tianzhu/jiedao98', '街道', '街道上人来人往，两边是各式各样的商店铺面酒馆药房等等，应有尽有。五花八门的招牌幡旗临街挑起，不时可听见贩子们的吆喝声从街上传来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3032, 'qujing', 'qujing/tianzhu/jiming', '鸡鸣关', '山路在这里变得狭窄，两边是高高的山岩，看上去如一天然的屏障。路的一边长有一片片的灌木丛，另一边长着齐胸高的野蒿草随风摇戈。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3033, 'qujing', 'qujing/tianzhu/jinluan', '金銮殿', '金銮殿里庄严静肃，十二根盘龙柱将大殿擎起。从天花板顶上披下无数金银线珍珠帘，一盏盏大如莲座的翡翠灯放着奇异的光彩。殿的中间有一白玉台阶，上有一高大的龙纹宝座。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3034, 'qujing', 'qujing/tianzhu/jiuguan', '酒馆', '几个大酒缸并排放在屋里靠里墙的地方，散发着浓烈的酒香，正堂摆着六张红木酒桌，每个桌子上放着几碟小菜，给来喝酒的酒客们下酒。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3035, 'qujing', 'qujing/tianzhu/kedian', '客店', '一间十分宽敞的客店，四周的石墙被粉刷得雪白干净，临街的窗台上放着茶具，一张四方大木桌摆在堂中，四边放着长条凳供客人门休息。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3036, 'qujing', 'qujing/tianzhu/long', '龙阁', '整个楼阁为金黄色，阁内的西墙上有巨大的琉璃砖二龙戏珠，楼阁里面的地上铺着暗红色的火方石，上面再铺设一条长长的绣花地毯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3037, 'qujing', 'qujing/tianzhu/mafang', '马店', '这里专供远道而来的马车准备的饭店，前面是客人休息洗刷吃饭的场所，后面有一马棚，可以停放大小不同的马车，让马喝水吃草休息。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3038, 'qujing', 'qujing/tianzhu/maodian', '帽店', '这是一家专门卖帽的店铺，门外挑了一个四方灯笼，灯笼的四面都画了个帽子。店铺里设了一水磨铜镜，顾客在买了帽子之后往往挤在铜镜前戴帽儿照镜子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3039, 'qujing', 'qujing/tianzhu/nanmen', '南门', '一条长长的护城河出现在眼前，有两丈多深，上面架着一巨大的铁链木桥。桥头是一高大的城楼，用山石砌成，楼顶上有了望哨。城楼书有三个大字：天竺国。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3040, 'qujing', 'qujing/tianzhu/pidian', '皮店', '皮店里摆了一个长长的桌子，上面放了各式各样的皮衣皮靴。墙上的木架上也挂了一些兽皮衣兽皮帽，门口有一把椅子，也摆满了皮货。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3041, 'qujing', 'qujing/tianzhu/qian', '钱庄', '钱庄是一个青瓦小楼，门上有一旧匾，一个厚门帘将门遮得死死的。屋里是一个高高的紫色柜台，从柜台里不时传来金银锭铜币落盘的声音。柜台上放着一盏油灯，一闪一闪地照着屋子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3042, 'qujing', 'qujing/tianzhu/roupu', '肉铺', '一个大棚子里放着一个厚木桌，上面有一肉砧板。桌子后面有个木盆，里面大概是大块大块的生肉。棚子一边挂着一只猪头一边挂着一只牛头。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3043, 'qujing', 'qujing/tianzhu/shan1', '山冈', '高高的山冈上，山路顺着山势起伏，道路凸凹不平铺着大大小小的石头块。路边怪石林立形状不可言逾，山路时宽时窄，路边长着长长的荒草。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3044, 'qujing', 'qujing/tianzhu/shan2', '山冈', '高高的山冈上，山路顺着山势起伏，道路凸凹不平铺着大大小小的石头块。路边怪石林立形状不可言逾，山路时宽时窄，路边长着长长的荒草。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3045, 'qujing', 'qujing/tianzhu/shan3', '山冈', '高高的山冈上，山路顺着山势起伏，道路凸凹不平铺着大大小小的石头块。路边怪石林立形状不可言逾，山路时宽时窄，路边长着长长的荒草。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3046, 'qujing', 'qujing/tianzhu/shan4', '山冈', '高高的山冈上，山路顺着山势起伏，道路凸凹不平铺着大大小小的石头块。路边怪石林立形状不可言逾，山路时宽时窄，路边长着长长的荒草。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3047, 'qujing', 'qujing/tianzhu/shan5', '山冈', '高高的山冈上，山路顺着山势起伏，道路凸凹不平铺着大大小小的石头块。路边怪石林立形状不可言逾，山路时宽时窄，路边长着长长的荒草。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3048, 'qujing', 'qujing/tianzhu/shanmen', '山门', '山林开阔地带有一块空场地，场地上有一片寺院，仿佛在云雾之中。寺院前面是一高大的山门，可以看见门里的寺院，门上有一个大匾：布金禅寺。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3049, 'qujing', 'qujing/tianzhu/shizi', '十字街彩楼', '这里是天竺国的城中心十字街口，街上熙熙攘攘十分热闹，街心有一绘红画绿的琉璃彩楼，一大群人挤在彩楼四周，交头接耳兴奋地议论着什么。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3050, 'qujing', 'qujing/tianzhu/shoushi', '首饰店', '一座精巧的青砖红瓦小店，门檐上挑着一个“吴”字灯笼。店里面是几个檀香木桌，几把太师椅。木桌上放着几个打开的玛瑙匣子，陈列着各种首饰。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3051, 'qujing', 'qujing/tianzhu/shucai', '蔬菜市场', '蔬菜市场为一小空场地，地上堆了一些烂菜叶瓜皮之类的垃圾。场地中有不少搭棚售菜的农妇，不时也可见到几位菜农挑着担子来来往往。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3052, 'qujing', 'qujing/tianzhu/shuifang', '水房', '水房上的烟囱冒着淡淡的白烟，房里一个大水灶正在烧着开水，靠墙放着一些水桶和一口大水缸。门口有几把小凳，供路客来打水顺便歇歇脚。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3053, 'qujing', 'qujing/tianzhu/shuju', '书局', '这里是书局，大堂里摆了一排排的书柜，上面有书简线装经书羊皮书。堂后有一个紫花屏风，几个瓷花盆里种着几棵奇花异草，书局的主人不知在何处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3054, 'qujing', 'qujing/tianzhu/sishu', '私塾', '明亮的堂屋里，放着一书案，上面插着一根计时用的燃香。案头堆了一些书简，放了一把铜戒尺。私塾的北墙有一窗口望出去可见幽幽的青山。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3055, 'qujing', 'qujing/tianzhu/siyuan', '寺院', '方方正正的寺院里，种着几棵千年大树，树枝茂密将寺院的一半几乎遮住。寺院南边有一圆拱月门通向寺院深处，西边有个台阶通向一个大殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3056, 'qujing', 'qujing/tianzhu/wumen', '午门', '一道长长的琉璃瓦檐石墙将王宫围起，里面可以看见雄伟的宫殿楼阁。宫门为一巨大的铁钉嵌铜木门，高大的门楼上有两个烫金大字：午门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3057, 'qujing', 'qujing/tianzhu/xiaochi', '小吃店', '店堂里干干净净，放着许多长凳长桌，来小吃店的人都是附近的邻居街坊，一边吃着什么，一边聊天闲谈。店家是位大嫂，正在擦着桌子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3058, 'qujing', 'qujing/tianzhu/xiedian', '鞋店', '一大店铺里放了一排柜台，台子上是各种各样的鞋靴，档次有高有低，既卖皮靴也卖草鞋，生意十分兴隆。柜台前放了一些矮凳以方便顾客试鞋。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3059, 'qujing', 'qujing/tianzhu/ximen', '西门', '一条长长的护城河出现在眼前，有两丈多深，上面架着一巨大的铁链木桥。桥头是一高大的城楼，用山石砌成，楼顶上有了望哨。城楼书有三个大字：天竺国。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3060, 'qujing', 'qujing/tianzhu/yaofang', '药房', '门口挑着一招牌迎风摇晃，药房里面有一个大木柜，上面满是小抽屉儿。西边靠街处有一窗子，窗边摆了一个仙桌，旁边有两把软臂靠椅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3061, 'qujing', 'qujing/tianzhu/yuhua', '御花园', '御花园四周是琉璃墙，园中有大小云纹花坛无数，里面种着罕见的奇花异草，散发着浓郁的清香味。花园的南边是金銮店，东西为龙凤亭阁，北面是一排宫殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3062, 'qujing', 'qujing/tianzhu/zhaifang', '斋房', '斋房靠窗是两口大锅，灶里烧着柴火冒着青烟，锅里热水滚滚。房子的南端有一大木桌，桌上放着一些粗瓷碗盆。北边是门，通向寺院的菜园。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3063, 'qujing', 'qujing/tianzhu/zhaoyang', '昭阳宫', '昭阳宫里紫气袅袅，正面是一绘金玉边彩屏，有数丈之宽光照逼人。宫东西两边是缤纷百花窗，几条绛红色大帘如瀑一般从彩墙壁上披下来，天花板上吊着的华灯齐放。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3064, 'qujing', 'qujing/tianzhu/zhuqi', '竹器店', '店门口放着一些编好的竹器，门檐上挂着一个招牌迎风轻晃着，里面铺面不小，到处堆满着竹制品。西墙有一柜台，上面也堆着正在出售的竹制品。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3128, 'qujing', 'qujing/tongtian/bing1', '冰道', '河面冻得结结实实，厚厚的一层冰已经被人走出一条长长的冰道，也有大冰撬滑过留下的痕迹。风呼呼地打在脸上，刺骨地寒冷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3129, 'qujing', 'qujing/tongtian/bing2', '冰道', '河面冻得结结实实，厚厚的一层冰已经被人走出一条长长的冰道，也有大冰撬滑过留下的痕迹。风呼呼地打在脸上，刺骨地寒冷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3130, 'qujing', 'qujing/tongtian/bing3', '冰道', '河面冻得结结实实，厚厚的一层冰已经被人走出一条长长的冰道，也有大冰撬滑过留下的痕迹。风呼呼地打在脸上，刺骨地寒冷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3131, 'qujing', 'qujing/tongtian/bing4', '冰道', '河面冻得结结实实，厚厚的一层冰已经被人走出一条长长的冰道，也有大冰撬滑过留下的痕迹。风呼呼地打在脸上，刺骨地寒冷。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3132, 'qujing', 'qujing/tongtian/chen1', '陈家庄', '陈家庄里住着大大小小的人家，多姓陈故为陈家庄。庄子里不时可听见热闹的声音，夹杂着鸡鸣狗叫。一些人家的烟囱里冒出淡淡的烟，空气中散发着柴烟香。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3133, 'qujing', 'qujing/tongtian/chen2', '陈家庄', '陈家庄里住着大大小小的人家，多姓陈故为陈家庄。庄子里不时可听见热闹的声音，夹杂着鸡鸣狗叫。一些人家的烟囱里冒出淡淡的烟，空气中散发着柴烟香。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
