INSERT INTO `rooms` VALUES (3135, 'qujing', 'qujing/tongtian/hedi', '河底', '……冰冷的河底……', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3136, 'qujing', 'qujing/tongtian/hedong1', '河东', '一条很宽的大河横在面前，一眼望去，远远可以见到隐约的对岸。河堤的背面就是陈家庄，河面已结了厚厚的一层冰，偶然见到一些人行走在冰上。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
