INSERT INTO `rooms` VALUES (3142, 'qujing', 'qujing/tongtian/hexi1', '河西', '一条大河水面很宽，一眼望去，远远可以见到隐约的对岸。西边是岸上的树林，东面是河面，已结了厚厚的冰层，冷风呼呼地吹着，冰上偶然可见有人或车行走。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
