INSERT INTO `rooms` VALUES (3146, 'qujing', 'qujing/tongtian/hexi5', '河西', '一条大河水面很宽，一眼望去，远远可以见到隐约的对岸。西边是岸上的树林，东面是河面，已结了厚厚的冰层，冷风呼呼地吹着，冰上偶然可见有人或车行走。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3147, 'qujing', 'qujing/tongtian/hexi6', '河西', '一条大河水面很宽，一眼望去，远远可以见到隐约的对岸。西边是岸上的树林，东面是河面，已结了厚厚的冰层，冷风呼呼地吹着，冰上偶然可见有人或车行走。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3148, 'qujing', 'qujing/tongtian/huashen', '竹林深处', '一片幽静的竹林深处，翠竹摇曳，薄雾缭绕。隐约可见一个小小的莲台，上面坐着一个黄发小童，正闭目打禅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3149, 'qujing', 'qujing/tongtian/minju1', '民居', '这是一户陈姓人家，屋子里摆设简单，设有一木桌两木椅，里面是一张床，上面的被褥叠得整整齐齐。北面有一个木窗子，窗外传来鸡叫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3150, 'qujing', 'qujing/tongtian/minju2', '民居', '此户人家也是陈姓，堂屋里光线明亮，摆设颇为讲究，堂心有一八仙桌，上面放着净亮的铜茶具，屋边有几把宽背椅，中间有一小茶几。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3151, 'qujing', 'qujing/tongtian/minju3', '民居', '这也是一户陈姓人家，房子里面布置得非常舒适。屋子东边有一灶台，正烧着火，不知在做什么，散发出一股清香味。南边的门通向屋外。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3152, 'qujing', 'qujing/tongtian/minju4', '民居', '这家陈姓人家屋子里面空空的，一张木长条凳上放着一个空陶盆，长条凳边有几只小木凳。墙角放着一堆柴禾，边上是一个空的水缸。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3153, 'qujing', 'qujing/tongtian/minju5', '民居', '民居里十分热闹，两张大木桌子拼在一起，周围放着椅子凳子，几个近邻凑在一起，围桌而坐，不知在谈什么。屋角的灶上烧着热水发出吱吱的水响。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3154, 'qujing', 'qujing/tongtian/minju6', '民居', '这家人家也是陈姓，屋子里放着大小陶盆瓷罐，里面种着花草之类的东西。南边的两扇窗子大开，从外面飘来一股花草的清香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3155, 'qujing', 'qujing/tongtian/xiaolu1', '小路', '小路长长弯弯，路上铺着碎石，已被过往的车轮压出两道槽印，路边有一棵棵青树，结着各种青果红果不记其数，路的两边是农田种着庄稼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3156, 'qujing', 'qujing/tongtian/xiaolu2', '小路', '小路长长弯弯，路上铺着碎石，已被过往的车轮压出两道槽印，路边有一棵棵青树，结着各种青果红果不记其数，路的两边是农田种着庄稼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3157, 'qujing', 'qujing/tongtian/xiaolu3', '小路', '小路长长弯弯，路上铺着碎石，已被过往的车轮压出两道槽印，路边有一棵棵青树，结着各种青果红果不记其数，路的两边是农田种着庄稼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3158, 'qujing', 'qujing/tongtian/xiaolu4', '小路', '小路长长弯弯，路上铺着碎石，已被过往的车轮压出两道槽印，路边有一棵棵青树，结着各种青果红果不记其数，路的两边是农田种着庄稼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3170, 'qujing', 'qujing/tongtian/opal/chen', 'chen', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3171, 'qujing', 'qujing/tongtian/opal/jinyu', 'jinyu', '一位身着金甲的妖怪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3172, 'qujing', 'qujing/tongtian/opal/taibai', 'taibai', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3173, 'qujing', 'qujing/wudidong/bedroom-gate', '彩楼', '好一间齐楚阁儿！白墙灰瓦，爬满了种种奇花，一扇紧闭的小小朱门，也是藤萝掩映，更显得郁郁葱葱。门口站了两个小妖，打扮得倒也齐整，看来这里正是洞主的绣房。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3174, 'qujing', 'qujing/wudidong/bedroom', '寝室', '整个小庙里，也就这里还干净一些，房顶也不漏水。庙里仅剩的几个和尚就都挤在这里。屋里处了一张长长的竹床，和挂着的几件破僧衣之外，什么都没有。也不知这几个和尚吃什么度日。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3175, 'qujing', 'qujing/wudidong/biyaoshi', '避妖室', '这是一间小石室，收拾得很干净，虽然在地下，却似乎一点儿也不气闷。一张小石桌上放着一盏点着的油灯(light)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3176, 'qujing', 'qujing/wudidong/book-cave1', '洞穴', '这里遍地都是尘土，显然很少有人来往。洞中有些微弱的烛光，更加显得阴森恐怖。角落里似乎有个人影，你不由得一阵紧张。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3177, 'qujing', 'qujing/wudidong/book-cave2', '洞穴', '这里的洞穴突然大了许多。四壁插着几支牛油蜡烛，发出点若明若暗的光。洞穴里空阔的很，除了北边靠墙处一张巨大的石桌外，什么都没有。迎面墙上似乎刻着一排字(zi)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3178, 'qujing', 'qujing/wudidong/cave1', '秘洞', '这里是无底洞的一条秘道，寻常小妖不准进出。正待迈步，突然发现脚下竟是万丈深渊，黑漆漆的，望不见底。黑暗之中你极目远眺，只见模模糊糊的似乎是另一处悬崖。看上去两峰之间不过一纵之遥，但一失足。。。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3179, 'qujing', 'qujing/wudidong/cave2', '绝崖', '这是绝崖的另一面。往西就是玉鼠精的练功房了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3180, 'qujing', 'qujing/wudidong/daxiong-baodian', '大雄宝殿', '八百罗汉，四大天王，如来，观音，应有尽有，很有点杭州灵隐的风味。也许因为最近出了妖，香火并不是很丰盛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3181, 'qujing', 'qujing/wudidong/dibaohouse', '地保家', '张地保手里有几个祖宗传下来的闲钱，因此也不干活，成天坐在家里发呆。少爷脾气倒是从小养起来了，屋子里乱得象猪窝，也不说收拾收拾。吃了饭，桌上还是杯子朝天碗朝地。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3182, 'qujing', 'qujing/wudidong/dong', '山顶', '山顶光秃秃的，一棵花草也无，只有一块平坦的巨石。走近一看，大石正中是一个缸口大小的洞(dong)，已被磨得光滑无比。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3183, 'qujing', 'qujing/wudidong/dong1', '洞门', '下落半晌，方始着地。落脚处甚是窄狭，黑沉沉阴森森也看不甚清楚，只见拱门边上立着块大碑(shibei)，笔迹却颇为娟秀。门那边隐隐传来阵阵笑语，又似有日光透入。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3184, 'qujing', 'qujing/wudidong/dong2', '前洞', '好一个福地洞天！一座二滴水的门楼，团团都是松林。亭台楼阁，门垂翠柏，宅近青山。前洞住的尽是小妖，各自忙忙奔走。西面便是厨房，传出阵阵香气，不时有人出入。前面有条黑乎乎的甬道，直奔后洞而去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3185, 'qujing', 'qujing/wudidong/dragon-room', '龙穴', '挤过石缝一瞧，乖乖不得了。这里原来是条井龙的巢穴。虽然这里没有水，但潮湿无比。四处爬着各种各样你从未见过的虫子，角落里一堆骸骨(bones)发散着阵阵腐臭之气。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3186, 'qujing', 'qujing/wudidong/entrance', '小村口', '举头向西望去，只见一带泥墙，几丛青篱，一条潺潺的小溪围着十几间矮矮的茅屋，正是张家村。满山遍野的都是菜田，蜜蜂在金黄的油菜花间飞舞。极目远望，南面有座高山，几朵白云留连不去。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3187, 'qujing', 'qujing/wudidong/exit', '小村口', '举头向东望去，只见一带泥墙，几丛青篱，一条潺潺的小溪围着十几间矮矮的茅屋，正是张家村。满山遍野的都是菜田，蜜蜂在金黄的油菜花间飞舞。极目远望，南面有座高山，几朵白云留连不去。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3188, 'qujing', 'qujing/wudidong/firemount-wudidong1', '取经路', '离开了比丘国，你又踏上了西行之路。面前是一片一望无际的平野，视野内不见一道炊烟。又不知要度过多少个无人伴随的旅途之夜，又不知要独自面对多少毒虫野兽，妖魔鬼怪了。', '/d/qujing/wudidong', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3189, 'qujing', 'qujing/wudidong/firemount-wudidong2', '小山头', '爬上一个小山头，西边已能看到片片碧绿的稻田。而回首东望，火焰山已经只剩一个模糊的轮廓了。', '/d/qujing/wudidong', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3190, 'qujing', 'qujing/wudidong/firemount-wudidong3', '取经路', '西边地平线上可以看到一个小村庄的轮廓，路两边的稻田里，人们正在耕作。看着田里的水牛，你不由想找个人家小憩一宿，聊解旅途的疲惫。', '/d/qujing/wudidong', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3191, 'qujing', 'qujing/wudidong/gongshi', '供室', '近后壁处铺着一张龙吞口漆雕供桌。桌上有一个大流金香炉，炉内香烟缭绕。香炉后面供着两块牌位。右面书架上散乱地堆着一些东西，书架边墙上有一个小木轮(wheel)，不知有何用处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3192, 'qujing', 'qujing/wudidong/guanjia', '偏洞', '这偏洞虽非金窗玉槛，却也是颇为富丽堂皇，原来无底洞的总管就住在这里。洞深处的梳妆台上红烛高点，台前坐着一个妖娆女子，正在对镜整妆，衣衫上传来阵阵浓香扑鼻，却掩不住这洞中的一股骚臭之气。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3193, 'qujing', 'qujing/wudidong/houdong', '后洞', '出了甬道，你眼前一亮。原来后洞比前洞还要大得多。方圆数百里都种满了奇花异草。苍松迎客，碧柳垂腰，四处鸟语，遍地花香。若非前洞和甬道里处处透出诡异，你真会以为这里是仙境了。北面一座大殿，东边是座彩楼。西北角上有个石洞，洞门却是紧锁的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3194, 'qujing', 'qujing/wudidong/houyuan', '后院', '后院里落叶遍地，也没有人打扫。角落里有一口石井，上面长满了青苔杂草，旁边一根井绳。打水的桶也不知哪去了，看来很久没人用过了。', '/d/qujing/wudidong', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3195, 'qujing', 'qujing/wudidong/inner-bedroom', '寝室', '这里便是玉鼠精的卧室了。掀开水红挑绣的软帘，只见锦笼纱罩，说不尽的精致华丽，连脚下踩的砖都是一色的雪白凿花。当窗一张小小床榻，软纱为帐，轻罗为衾，绣的都是一对一对的五彩鸳鸯。梳妆台上摆着各式胭脂水粉，明镜中映出对面墙上挂的一幅画像(picture)，粉面含嗔，玉容整肃。墙角里有扇石门(men)，不知通向何处。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3196, 'qujing', 'qujing/wudidong/inner-tang', '大殿', '大殿里无数小妖来回奔走，正在准备大开筵席。一个女子正中高坐，云髻低垂，金钗半溜，正笑吟吟地指挥着众小妖，全不顾自己香汗淋漓。你往人群中一混，一时倒也无人发觉。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3197, 'qujing', 'qujing/wudidong/jail', '狱门', '这儿就是无底洞的地牢了。厚重的铁门上开了一个半尺见方的圆孔，仅够传递饭菜水钵。里面传来的呻吟声痛苦万状，动人心魄。门口站着两个膀大腰圆的小喽罗，手中拿着明晃晃的长剑，寸步不离铁门左右。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3198, 'qujing', 'qujing/wudidong/kefang', '客房', '房里干干净净的，供客人休息。一排竹板大床，已经被磨得发黄了。屋角里摆着个炉子，以备冬天取暖。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3199, 'qujing', 'qujing/wudidong/kitchen', '厨房', '厨房里支起了数口大锅，灶下烈火熊熊，整日不息。蒸笼里传出的香气却甚是古怪，看来这包子里大有文章。墙上有张告示(gaoshi)，油渍斑斑，字迹颇为模糊。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3200, 'qujing', 'qujing/wudidong/lock', '石洞', '踏进门来，已无半点光亮，你只得摸索前进。四下阴冷潮湿，阵阵霉臭之气扑面而来。远处突然传来微弱的声响，似是有人在低声呻吟，又似野兽低嗥，令你毛发直竖。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3201, 'qujing', 'qujing/wudidong/mishi', '暗室', '这儿是无底洞的一个支洞，也是玉鼠精的练功房。除了玉鼠之外，很少有其他人进出。房间布置得十分简单，但是屋中央摆着一张十分醒目的玉台(tai)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3202, 'qujing', 'qujing/wudidong/monk', '狱中', '狱里燃着盏极小的油灯，微弱的黄光中只见地上的干草堆里躺着个老和尚，衣衫破烂，全身血迹斑斑，已被折磨得不成人形了，幸喜还没戴手铐脚镣。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3203, 'qujing', 'qujing/wudidong/punish', '黑暗中', '这里是一片黑暗，伸手不见五指。四处死沉沉地毫无声息，越发显得阴森恐怖。突然间一阵冷风吹来，带来一股扑鼻的霉气。渐渐的，你感到呼吸困难起来，看来这里并不透风。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3204, 'qujing', 'qujing/wudidong/road1', '村中小路', '这是一条村中石子小路。村里农民都起早摸黑地下地去了，路上一个大人也没有，只有几个小童在溪边捉鱼嬉戏。路边柳条拂地，时见野花，几只小鸡小鸭踱来踱去。一条野狗摇着尾巴跑了过来，闻了闻，又跑了开去。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3205, 'qujing', 'qujing/wudidong/road2', '村中小路', '这里就是张家村的“繁华地界”了，北面传来叮叮当当的打铁声音，南边随风飘来阵阵饭菜香气。抬头一看，茅屋边大树上挑着个酒幌，屋檐下的匾上写着「张家老店」，门面倒也齐整。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3206, 'qujing', 'qujing/wudidong/road3', '村中小路', '北面传来一阵阵的读书声。人说麻雀虽小，五脏俱全，果然不假。就连这么个小村，都有学堂。你不禁对本地的村民肃然起敬。村里最老的老张就住在南边。你不由想去拜访拜访，问问本地的风土人情。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3207, 'qujing', 'qujing/wudidong/shanlu1', '山腹', '四处黑沉沉的，什么也看不清，只能摸索着前进。地面颇为潮湿，霉气扑鼻。两边壁上都是凹凸不平的尖石，脚下也是时高时低。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3208, 'qujing', 'qujing/wudidong/shanlu2', '山腹', '四处黑沉沉的，什么也看不清，只能摸索着前进。地面颇为潮湿，霉气扑鼻。两边壁上都是凹凸不平的尖石，脚下也是时高时低。南边有一线微弱的亮光，不知是不是快到洞口了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3209, 'qujing', 'qujing/wudidong/shanlu3', '山谷', '出了山腹，你眼前一亮，原来身处一座深山之中，离张家村已远了。东西北三面都是峭壁，只有南边一片黑松林似乎有路可寻。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3210, 'qujing', 'qujing/wudidong/shanlu4', '黑松林', '四下里古松参天，遮天蔽日，林中光线很暗。山风吹过，只听松涛阵阵，如低鸣，似哀哭。这里不仅绝无人迹，连野兽也不见一只，你越走越是毛骨悚然。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3211, 'qujing', 'qujing/wudidong/shop', '张家老店', '张小二天生是个好动不好静的主儿。刚把店从他爹那儿接过来没一个月，就整理过几十上百回了，搞得他自己都找不到东西。村子穷，张小二也拿不出什么好东西卖，无非是些家常酒菜之类。墙上有块牌子(sign)，似乎这里还可以过夜。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3212, 'qujing', 'qujing/wudidong/smithy', '铁匠铺', '这里就是村里的打铁铺了。张铁匠是祖传三代的手艺，手下打出来的铁器往往比人的寿命还长，手艺既好，活儿就多，天天从早忙到晚。屋子一边摆着生铁和折断了的工具，另一边摆满了做好的铁器，都是些村中必需的东西。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3213, 'qujing', 'qujing/wudidong/square2', '甬道', '甬道里潮湿阴暗，两壁挂着手臂粗细的牛油蜡烛，在阵阵阴风吹动下忽明忽暗。前面不远处有两个洞口，不知通向哪里。远处依稀可以看到洞口的亮光。你不由的加快了脚步。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3214, 'qujing', 'qujing/wudidong/steamer', '蒸笼', '好大的一个蒸笼，不知为何你会落在这儿，快点逃(tao)吧！', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3215, 'qujing', 'qujing/wudidong/tang-gate', '殿门', '已到了殿门口，依稀可以听到里面人声喧哗，杯盏叮当。只是守门的这两个小妖看来不好对付。殿里定是这无底洞的洞主了，近在咫尺，难道要缘悭一面？你不禁心痒难搔。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3216, 'qujing', 'qujing/wudidong/temple-gate', '华严寺', '转眼你已来至山顶，云雾缭绕，如似蓬莱仙境。 眼前，一座寺院拔地而起，寺门上一块横匾，上书「华严寺」。但不知为何，寺门紧闭，尘灰遍地，似乎很久没有人出落了。 门前一道小路，继续往西而去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3217, 'qujing', 'qujing/wudidong/temple-houdian', '后殿', '后殿就更加破败了。一面墙壁前还供着一尊菩萨像(statue)，但泥塑上的漆早已剥落，显然经过了无数风风雨雨。村里人都说这里闹鬼，也不知是真是假。仔细看看，四处有不少老鼠出没的痕迹。但除此也没什么别的可疑之处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3218, 'qujing', 'qujing/wudidong/temple-qiandian', '小庙前殿', '小庙依山而造，远看颇为风雅，进来却发现不然。正殿里四壁透风，房顶漏水，几座难以辨认的泥像个个缺胳膊少腿。眼见你走进来，也没有个知客僧来欢迎。南边还有间后殿，也是残破不堪。只有东边一间房子还看的过去。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3219, 'qujing', 'qujing/wudidong/trap', '石洞深处', '断断续续的呻吟变得更加清晰了，前方也透出了一点豆大的灯光，依稀可见黑影幢幢。脚下突然踢到几具横七竖八的骷髅，你不禁捏了一把冷汗。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3220, 'qujing', 'qujing/wudidong/wdd_bedroom', '卧房', '这里是无底洞的卧房，四面地上睡着几个老鼠精。洞中散发着一股令人作呕的臊气，不知道哪个小妖带东西进来吃了。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3221, 'qujing', 'qujing/wudidong/weaponry', '兵器库', '你摸摸索索地走了过来，却发现洞内比你想象的要宽敞的多。四壁挂着些刀剑等兵器，几个小妖正在舞锤弄斧，看上去还真有几手。洞深处有一把宽大的石凳，据说是玉鼠赐给碧鼠的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3222, 'qujing', 'qujing/wudidong/well', '井底', '拨开井水一直游到底，你发现井底其实是干的。东边有一道石缝，里面似乎有两盏红灯，也许有什么神圣住在这里？', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3223, 'qujing', 'qujing/wudidong/xuetang', '学堂', '张秀才胸怀大志，只可惜入京去考状元，名落孙山，白白浪费了若干盘缠。如今只好回家来开个学堂，养家糊口。教的倒都是孔孟之书，念的是之乎者也。一众学生们手攥树枝，正在沙盘里练写「张」字，张秀才背着手，在屋中晃来晃去。墙上挂着一首诗 (poem)，倒写得龙飞凤舞的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3224, 'qujing', 'qujing/wudidong/yadi', '崖底', '白骨皑皑，磷火点点，不知有多少人丧生于此。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3225, 'qujing', 'qujing/wudidong/zhanghome', '老张家', '这里就是老张的家了。显然老张一贫如洗，连把椅子都没有，只得坐在炕上。东边支着个炉子，西边摆着各种耕田的工具，倒还齐全。仔细看去，好像犁头断了，怪不得大白天的老张不去田里干活，坐在家里唉声叹气。房中懒懒的睡着几只猫。你隐隐觉得有些不对：为何村中兴养猫，而不养看家狗呢？', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3235, 'qujing', 'qujing/wuji/backyard', '后院', '后院方方正正，院子里开了一块菜园子，种着各种蔬菜瓜果，绿油油一片。有一个藤架子，一些说不出名字的蔓藤爬在上面，开着黄色的小花。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3236, 'qujing', 'qujing/wuji/bedroom', '寝宫', '这里光线柔和，屋里装饰精美细腻。靠窗放有一长条桌，陈列着一些玉器瓷器。另一面是床，整齐地铺着锦罗花被。往北通向露天的小院子。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3237, 'qujing', 'qujing/wuji/eastgate', '东门', '这是乌鸡国的东门城楼，青石筑成两层楼台坚固异常，巍峨宽阔的拱行城门上方镂着「乌鸡国」三个红漆大字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3238, 'qujing', 'qujing/wuji/eastroom', '东厢房', '这是宝林寺的禅房，以供游方僧人借宿一宿，房内陈设简陋，靠墙设有几张木床。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3239, 'qujing', 'qujing/wuji/estreet', '坤元街', '坤元街是乌鸡国最繁华的一条街。人来人往，好不热闹。北边是一家茶馆，南边是一家水果店。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3240, 'qujing', 'qujing/wuji/estreet2', '坤元街', '这里是坤元街中段，路两旁挤满了做生意的小贩。北边有一家裁衣店，南边是一家客店。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3241, 'qujing', 'qujing/wuji/fruit', '四季水果店', '这家水果店店面虽然不大，但各色瓜果齐全，而且时令瓜果每日由城外运来，尤其新鲜。各色水果鲜红翠绿，十分诱人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3242, 'qujing', 'qujing/wuji/garden', '后院', '后院中心有一个小池塘，养了几只鹤。四围房前种了不少松柏，郁 郁葱葱。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3243, 'qujing', 'qujing/wuji/hilltop', '山顶', '山顶山磐石耸立，旁边有一片稀稀拉拉的树林。南边是陡峭的悬崖直壁，无路可行。此处山高风冷，空谷回音。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3244, 'qujing', 'qujing/wuji/house', '太子府', '此处乃是太子的行宫。三年前，国王认为太子已经成人，故为其另造宫殿，习文练武，没有诏令，不得私自进宫，以免分心。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3245, 'qujing', 'qujing/wuji/huilang', '白玉回廊', '回廊两侧皆由白云石雕成，花鸟虫鱼，莫不维妙维肖。回廊之外花开似锦，春意盎然。往西通往锦香亭，往北则是祈雨坛。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3246, 'qujing', 'qujing/wuji/huilang2', '白玉回廊', '廊两侧皆由白云石雕成，花鸟虫鱼，莫不维妙维肖。回廊之外花开似锦，春意盎然。往北是废弃的御花园。三年前国王与祈雨的道人在御花园玩赏时，道人化风而去，国王思慕那道人，再无心玩赏，遂命人将花园关闭。往西是王后的寝宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3247, 'qujing', 'qujing/wuji/hzm', '后宰门', '这里是王宫的偏门，看上去冷冷清清的，只有几个老太监无所事事地在那儿打瞌睡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3248, 'qujing', 'qujing/wuji/jxt', '锦香亭', '亭畔种着一簇牡丹，红艳欲滴。牡丹原产东土洛阳，乌鸡国王知道皇后爱花，而牡丹又为花中之王，是以不惜代价差人移植到此，真可谓名花倾国两相欢，常得君王带笑看了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3249, 'qujing', 'qujing/wuji/kezhan', '坤元客栈', '这家客栈位与乌鸡国最繁华的坤元街中段，所以生意非常兴隆。南来北往的客人多在此歇脚。几个跑堂的小二来来回回招待着四方来客。楼上是客房。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3250, 'qujing', 'qujing/wuji/nstreet', '乾元街', '乾元街两边多为官宅民房。向北走可直达皇宫。路两旁时有卫兵巡逻。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3251, 'qujing', 'qujing/wuji/nstreet2', '乾元街', '乾元街北段多为国内官员的府邸。东边是太子府，西边是天师府。再往北就是乌鸡国的皇宫了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3252, 'qujing', 'qujing/wuji/palace', '昭泽殿', '这里是乌鸡国王召见臣子，研讨国家大事的地方。四壁琉璃焕彩，流金滴玉。阶下臣子侍卫屏息作声，等候国王的旨意。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3253, 'qujing', 'qujing/wuji/piandian', '前殿', '只见两边红漆栏杆里面高坐这一对金刚，装塑的威依恶丑：一个铁面钢髯，一个燥眉圆眼，金甲连环光灿烂，明盔绣带映飘风。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3254, 'qujing', 'qujing/wuji/qiyutan', '祈雨坛', '此处乃国王祈雨的祭坛。祭坛四角各放着一鼎香炉，中央立着一鼎巨大的石碑，写着一些蝌蚪形的文字。乌鸡国六年前曾招大旱，国王曾在此昼夜焚香祷告，终于感动了圣明，请到一位会呼风唤雨的道士，解除了旱情。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3255, 'qujing', 'qujing/wuji/road1', '山路', '山顶嵯峨摩斗柄，树梢仿佛接云霄。青烟堆里，时闻得谷口啼猿；乱翠荫中，每听得松间鹤唳。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3256, 'qujing', 'qujing/wuji/road2', '山路', '只见此山八面巍峨，四围险峻，古怪乔松盘翠盖，枯摧老树挂藤箩。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3257, 'qujing', 'qujing/wuji/road3', '山路', '高峰入云，清流见底，青林翠竹，四时俱备。猿鸟乱鸣，沉鳞竞跃，实是欲界之仙都。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3258, 'qujing', 'qujing/wuji/road4', '山路', '路两边千株老柏，带雨半空青冉冉；万节修篁，含烟一壑色苍苍。林中隐隐有钟声传来，好象是一座寺庙。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3259, 'qujing', 'qujing/wuji/road5', '山路', '路两边千株老柏，带雨半空青冉冉；万节修篁，含烟一壑色苍苍。北边林中隐隐有钟声传来，好象是一座寺庙。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3260, 'qujing', 'qujing/wuji/road6', '山路', '只见此山八面巍峨，四围险峻，古怪乔松盘翠盖，枯摧老树挂藤箩。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3261, 'qujing', 'qujing/wuji/road7', '山路', '山顶嵯峨摩斗柄，树梢仿佛接云霄。青烟堆里，时闻得谷口啼猿；乱翠荫中，每听得松间鹤唳。远远的可以看见山下楼台叠叠，殿阁重重。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3262, 'qujing', 'qujing/wuji/rxg', '蕊祥宫', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3263, 'qujing', 'qujing/wuji/shandao1', '山道', '山道崎岖不平，沿着山势上下左右盘绕，地形十分险恶。群峦环绕，难辨东西南北。大风吹来，有点令人寒颤。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3264, 'qujing', 'qujing/wuji/shandao2', '山道', '山道崎岖不平，沿着山势上下左右盘绕，地形十分险恶。群峦环绕，难辨东西南北。大风吹来，有点令人寒颤。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3265, 'qujing', 'qujing/wuji/shandao3', '山道', '山道崎岖不平，沿着山势上下左右盘绕，地形十分险恶。群峦环绕，难辨东西南北。大风吹来，有点令人寒颤。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3266, 'qujing', 'qujing/wuji/shandao4', '山道', '山道崎岖不平，沿着山势上下左右盘绕，地形十分险恶。群峦环绕，难辨东西南北。大风吹来，有点令人寒颤。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3267, 'qujing', 'qujing/wuji/shandao5', '山道', '山道崎岖不平，沿着山势上下左右盘绕，地形十分险恶。群峦环绕，难辨东西南北。大风吹来，有点令人寒颤。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3268, 'qujing', 'qujing/wuji/shufang', '书房', '房间三面都是书架，上面摆满了书，大多都是军事与哲学方面的书。房中央有一张红木的书桌，桌后的太师椅上挂着一张白虎皮，一丝杂毛也没有。这张虎皮是太子去年打猎而得，太子为此甚为自豪。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3269, 'qujing', 'qujing/wuji/shuijing', '水晶宫', '黑暗深处一片光明，一座牌楼在水下恍然隐现，你正行走在水晶宫里，四周如明镜一般，方向难辨。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3270, 'qujing', 'qujing/wuji/square', '乾坤广场', '这里是城中心了，路两旁挤满了小贩向你兜售当地的土产。向北可以到达乌鸡国的皇宫。向南则是一片民宅。东西两边的大路上有不少商店，甚是繁华。近几年来乌鸡国风调雨顺，老百性安居乐业，一片欣向荣的景象。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3271, 'qujing', 'qujing/wuji/stable', '马槽', '此间的马都是太子精心挑选的大宛宝马。其中以那匹名为＂绝尘＂的马最为名贵。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3272, 'qujing', 'qujing/wuji/street1', '山脚', '两旁林木茂盛，遮天蔽日。满径落叶，柔软稀松。虫鸟啾啾。凉风习习。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3273, 'qujing', 'qujing/wuji/street2', '官道', '平西望去有一座城池，隐隐被一层黑云罩着。两边的草虫里时有小动物窜出来。东边是一座山，山势巍峨挺拔。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3274, 'qujing', 'qujing/wuji/temple', '宝林寺', '只见八字砖墙泥红粉，两边门上钉金钉，叠叠楼台藏岭畔，城城宫阙隐山中。果然是一座好寺院。正门上红底烫金的写着三个字：＂宝林寺＂。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3275, 'qujing', 'qujing/wuji/up', '二楼客房', '客房里整齐大方，四周放着床铺和雕木小几。临街是一排窗子，挂着薄窗帘，是个歇脚休息的好地方。', '0', 'normal', 1, 0, 0, 1, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3276, 'qujing', 'qujing/wuji/wall', '宫墙外围', '这里是王宫的宫墙外围，高大的墙壁乃是青石垒成，十分结实整齐。宫墙上方有一个哨亭角楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3277, 'qujing', 'qujing/wuji/wall2', '宫墙外围', '这里是王宫的宫墙外围，高大的墙壁乃是青石垒成，十分结实整齐。宫墙上方有一个哨亭角楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3278, 'qujing', 'qujing/wuji/wall3', '宫墙外围', '这里是王宫的宫墙外围，高大的墙壁乃是青石垒成，十分结实整齐。宫墙上方有一个哨亭角楼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3279, 'qujing', 'qujing/wuji/well', '井底', '这是一口深深的井，沿着井壁上下长满了青苔。井里阴森森，光线极其黑暗，下面……', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3280, 'qujing', 'qujing/wuji/westroom', '西厢房', '此间乃寺中主持的禅房，但因近来夜间闹鬼，主持已搬去别处。屋中陈设甚是典雅。两边书架上摆满了经书，朝南的案上有一鼎香炉却好象好久没人上香了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3281, 'qujing', 'qujing/wuji/yuhua', '御花园', '御花园已经被封多年，园中池塘已经干枯，雕栏红漆尽褪。往日的奇花异草久不经修理，已被乱草埋没，惟有墙角的一棵芭蕉树长的茂盛(bajiao)，比众花木不同。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3282, 'qujing', 'qujing/wuji/zheng', '大雄宝殿', '大雄殿正中供着的乃是观音普度南海之相，其态度安详宁静，维妙维肖。两边是其他的一些佛祖塑像，分排站立，神态各异。殿里香烟缭绕，气氛静谧。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3283, 'qujing', 'qujing/wuji/ziyun', '紫云宫', '此乃王后的寝宫。国王王后曾经非常恩爱，所以国王经常在此留宿。这三年来国王不知什么原因慢慢冷落了王后。宫中虽然陈设华丽，但冷冷清清的，一个人也没有。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3284, 'qujing', 'qujing/wuji/zym', '正阳门', '这里是进入皇宫的正门，雕龙塑凤，一眼看去富丽堂皇。门前侍卫盔甲鲜明，威风凛凛，守卫森严。门内琼阁林立，层层叠叠，瑞气纷飘。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3285, 'qujing', 'qujing/wuji/not_used/zixia', '紫霞宫', '国王的后宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3289, 'qujing', 'qujing/wuzhuang/anshi-more1', '亭底秘室', '这是牡丹亭底下的一间秘室，十分狭小，是五庄观用来储藏重要物品的地方。秘室的墙壁上镶着几块幽蓝的宝石，淡淡的蓝光虽然不太明亮，却也足够让人看清秘室的布局了。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3290, 'qujing', 'qujing/wuzhuang/anshi', '亭底暗室', '这是牡丹亭底下的一间暗室。黑咕窿咚的什么也看不清。你试着到处摸了摸(mo)。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3291, 'qujing', 'qujing/wuzhuang/baicaidi', '白菜地', '五庄观做事的多，吃饭的也不少，所以观内雇了附近的一些农家来种蔬菜瓜果。这里是白菜地。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3292, 'qujing', 'qujing/wuzhuang/chengyun', '乘云阁', '乘云阁居观中的最高处，阁上画栋雕梁，丹楹刻柱，显是下了很大的功夫、周围朱栏曲槛，凭栏四望，远处景致俱在眼前。山下村房楼舍，山上奇石怪松历历在目。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3293, 'qujing', 'qujing/wuzhuang/eastway1', '东小廊', '这是大殿东厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。南面有一座高台。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3294, 'qujing', 'qujing/wuzhuang/eastway2', '东小廊', '这是大殿东厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。西边一道木门通到东偏殿。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3295, 'qujing', 'qujing/wuzhuang/eastway3', '东小廊', '这是大殿东厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。东面有一座四方小阁。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3296, 'qujing', 'qujing/wuzhuang/eastway4', '东小廊', '这是大殿东厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。东面的松林中发出阵阵松涛。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3297, 'qujing', 'qujing/wuzhuang/eastway5', '东小廊', '这是大殿东厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。西面是观中的斋房。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3298, 'qujing', 'qujing/wuzhuang/eastway6', '东小廊', '这是大殿东厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。西面通到后殿。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3299, 'qujing', 'qujing/wuzhuang/epiandian', '东偏殿', '东偏殿主要是待客奉茶之用。殿内摆着几对檀木椅。木壁之上挂了几幅字画。中有一幅大书：“清虚人事少，寂静道心生”，写得是灵妙非常，落款袁天罡。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3300, 'qujing', 'qujing/wuzhuang/gate', '观门', '松坡冷淡，竹径清幽。几重转折间忽然现出了一道山门。山门以苔石垒成，青藤缠绕中可以看到一块通碑(bei)。山门之后有楼阁数层。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3301, 'qujing', 'qujing/wuzhuang/guangchang', '殿前广场', '这里是宝殿之前的一个广场。从此纵看宝殿，气象雄浑，威势不俗。檐上有各种明兽祥云的浮雕，向南的窗户乃是太极之形，中部镂空镶以五彩琉璃。场上铺的均是四方青石，向南可看到山门前的往来，东西有小廊通往后殿。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3302, 'qujing', 'qujing/wuzhuang/guge', '鼓阁', '鼓阁内成四方，木架上摆着面大鼓，几乎占满了室内的空间，仅周围有尺许空隙人可通过。西面有小门通到竹林之中。室内四壁洁白，纤尘不染。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3303, 'qujing', 'qujing/wuzhuang/houdian', '后殿', '后殿亦是宽敞素雅，只是空空荡荡地没放什么东西。再往北就是五庄观的后院了。东西各有一条小廊通向正殿。北面门外，隐闻花香鸟语，大概是个花园。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3304, 'qujing', 'qujing/wuzhuang/houyuan', '后院', '来到后院，不觉心情为之一松。好一派鸟语花香。院子虽不大，看得出有一番精心布置。北面一道小门以梨树枝结成，而雪白的梨花居然依旧盛开。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3305, 'qujing', 'qujing/wuzhuang/huangguadi', '黄瓜地', '五庄观做事的多，吃饭的也不少，所以观内雇了附近的一些农家来种蔬菜瓜果。这里是黄瓜地。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3306, 'qujing', 'qujing/wuzhuang/huludi', '葫芦地', '五庄观做事的多，吃饭的也不少，所以观内雇了附近的一些农家来种蔬菜瓜果。这里是葫芦地。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3307, 'qujing', 'qujing/wuzhuang/inpool', '荷塘中', '塘中碧莲相结，荷香扑面而来。你拼命地伸长脖子，想把脑袋从荷叶底下钻出来。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3308, 'qujing', 'qujing/wuzhuang/jiangjing', '讲经堂', '经堂是平时镇元大仙与观中道士讲经时而用，堂上有一宝座，座前放有三四十个锦面软垫。此外堂中没有其它摆设，是镇元大仙为妨分神特意而为。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3309, 'qujing', 'qujing/wuzhuang/juyuan', '菊园', '梨花门外却不是梨园。这里各种各色的菊花争奇斗艳。你不由得放轻了脚步，唯恐一个不小心，惊落了娇艳欲滴的花瓣。东北一亭俏立，隐约可见“牡丹亭”几字。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3310, 'qujing', 'qujing/wuzhuang/linkway', '青砖道', '细长的青砖道从山门连向宝殿。道上俱是一色青砖，摆法中似有太极之意，八卦之象。道左是竹林一片，密密匝匝看之不透，右是松海一片，但闻松涛阵阵不绝。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3311, 'qujing', 'qujing/wuzhuang/linyin1', '林荫小道', '这里树高影长，果熟送香。虽然只是短短的一条林荫道，行来亦是让人清心脱俗。而东面树丛中水光掩映，想来是一片池塘。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, '{\"disabled_exits\": {\"east\": {\"message\": \"还是不要去了吧\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (3312, 'qujing', 'qujing/wuzhuang/linyin2', '林荫小道', '这里树高影长，果熟送香。虽然只是短短的一条林荫道，行来亦是让人清心脱俗。而东面树丛中水光掩映，想来是一片池塘。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, '{\"disabled_exits\": {\"east\": {\"message\": \"还是不要去了吧\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (3313, 'qujing', 'qujing/wuzhuang/luobodi', '萝卜地', '五庄观做事的多，吃饭的也不少，所以观内雇了附近的一些农家来种蔬菜瓜果。这里是萝卜地。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3314, 'qujing', 'qujing/wuzhuang/mudanting', '牡丹亭', '*********************** & 牡丹亭 & *********************** 果然是饮酒赏园的绝妙去处！北面桃林中甜香阵阵，大红蜜桃似乎伸手可及。南面的菊园中蜂飞鸟唱，时有几片金黄的菊瓣随风飘来。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3315, 'qujing', 'qujing/wuzhuang/northpool', '荷塘边', '荷塘北边。塘中碧莲相结，荷香扑面而来。塘面纵横交错架了好几座小木桥，不知哪一座是通往对岸的。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3316, 'qujing', 'qujing/wuzhuang/qiezidi', '茄子地', '五庄观做事的多，吃饭的也不少，所以观内雇了附近的一些农家来种蔬菜瓜果。这里是茄子地。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3317, 'qujing', 'qujing/wuzhuang/renshenguo-yuan', '人参果园', '好大的一遍人参果园！巨大的果树上吊着一枚枚令人垂涎欲滴的人参果。只是不知道怎样才能弄将下来。据说这人参果娇贵无比，要是乱摘一气什么都吃不上。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3318, 'qujing', 'qujing/wuzhuang/secondgate', '二山门', '二山门远看极是高大，牌楼上隐有祥云绕绕。左右石柱上刻口一对春联，乃是“长生不老神仙府，与天同寿道人家”十四个龙飞凤舞的大字。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3319, 'qujing', 'qujing/wuzhuang/shanlu1', '山路', '山路蜿转不定，缓势延往山上。遥望山颠隐见祥云片片，东边闻水声阵阵，乃是一个深涧。前方树林外见一道观，想来定是好人家。', '1', 'normal', 1, 0, 0, 0, 0, '{\"disabled_exits\": {\"east\": {\"message\": \"还是不要去了吧\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (3320, 'qujing', 'qujing/wuzhuang/shanlu2', '山路', '山路蜿转不定，缓势延往山上。遥望山颠隐见祥云片片，东边闻水声阵阵，乃是一个深涧。前方树林外见一道观，想来定是好人家。', '1', 'normal', 1, 0, 0, 0, 0, '{\"disabled_exits\": {\"east\": {\"message\": \"还是不要去了吧\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (3321, 'qujing', 'qujing/wuzhuang/shaoxiang', '烧香坊', '烧香坊尚在万寿山五庄观之外，一般的香客到此上香，磕头求愿后就要回转了。正前有一黑漆香案，上有香烛淡淡而燃。左右是净斋坊和俗客坊，供香客休息进斋。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3322, 'qujing', 'qujing/wuzhuang/shuofa', '说法堂', '说法堂乃是镇元大仙为了门下弟子说法论道而设。比讲经堂略大。中有一四方台，台上两把黑漆椅相对而立，台下软垫环绕。四面墙上挂有些山水字画，乃是经之妙义，法门玄机。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3323, 'qujing', 'qujing/wuzhuang/shuoyaopu', '芍药圃', '圃浅花盛，宛如在地上铺开了一张火红的地毯。几位提着花蓝的少女在此打闹嬉戏，清风拂过，袖带飘香，你不由得醉醉地吸了一口气。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3324, 'qujing', 'qujing/wuzhuang/sleep', '睡房', '睡房中整齐的摆着二三十个软榻，上面铺着玄色的被子。室中非常的安静，偶尔从外面的竹林中传来一两声鸟叫。', 'wuzhuang', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3325, 'qujing', 'qujing/wuzhuang/southpool', '荷塘边', '荷塘南边。塘中碧莲相结，荷香扑面而来。塘面纵横交错架了好几座小木桥，不知哪一座是通往对岸的。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3326, 'qujing', 'qujing/wuzhuang/wangxian', '望仙台', '望仙台上乃是青红板石铺就，布局巧妙，隐有太极之意。台中放一尺高铜炉，炉上小口中淡吐紫烟。台周有尺高护栏，皆雕龙刻凤。远望山下，但见山若伏兽，水若游龙，宛尔有出世之意。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3327, 'qujing', 'qujing/wuzhuang/westway1', '西小廊', '这是大殿西厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。南面有一座高台。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3328, 'qujing', 'qujing/wuzhuang/westway2', '西小廊', '这是大殿西厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。东面有一道小门通向西偏店。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3329, 'qujing', 'qujing/wuzhuang/westway3', '西小廊', '这是大殿西厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。西面有座四方小阁。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3330, 'qujing', 'qujing/wuzhuang/westway4', '西小廊', '这是大殿西厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3331, 'qujing', 'qujing/wuzhuang/westway5', '西小廊', '这是大殿西厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。东面是观中弟子的睡房。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3332, 'qujing', 'qujing/wuzhuang/westway6', '西小廊', '这是大殿西厢的一条长廊，向北连到后院。小廊上是木板铺地，打扫的极为干净，走在上面发出吱吱的响声。走廊两面的木格内雕着一些山水人物。东面通到后殿。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3333, 'qujing', 'qujing/wuzhuang/wpiandian', '西偏殿', '西偏殿主要用来堆放一些布道上香的常用物品。殿北楠木桌上有一对青铜的烛台，上有红烛轻燃。隔着西边的雕花木门是西廊，隐约可听到竹林中的风声。东边就回到宝殿。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3334, 'qujing', 'qujing/wuzhuang/wzgmaze1', '八卦桥', '几座木桥架在静悄悄的荷塘上面，纵横交错，显得甚是精巧。桥到此处，可见桥面上刻了一个大字： ─　─ ─　─ ─　─', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
