INSERT INTO `rooms` VALUES (3340, 'qujing', 'qujing/wuzhuang/wzgmaze7', '八卦桥', '几座木桥架在静悄悄的荷塘上面，纵横交错，显得甚是精巧。桥到此处，可见桥面上刻了一个大字： ─── ─　─ ───', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3341, 'qujing', 'qujing/wuzhuang/wzgmaze8', '八卦桥', '几座木桥架在静悄悄的荷塘上面，纵横交错，显得甚是精巧。桥到此处，可见桥面上刻了一个大字： ─　─ ─── ───', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3342, 'qujing', 'qujing/wuzhuang/xiguadi', '西瓜地', '五庄观做事的多，吃饭的也不少，所以观内雇了附近的一些农家来种蔬菜瓜果。这里是西瓜地。往北是有一道荆棘结成的篱笆，篱笆上开了一道简陋的杏木门，门上挂着一把黄铜锁。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3343, 'qujing', 'qujing/wuzhuang/xunzhen', '寻真台', '寻真台上乃是青红板石铺就，布局巧妙，隐有太极之意。台中放一尺高铜炉，炉上小口中淡吐紫烟。台周有尺高护栏，皆雕龙刻凤。远望山下，但见山若伏兽，水若游龙，宛尔有出世之意。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3344, 'qujing', 'qujing/wuzhuang/yanzhen', '延真楼', '延真楼上乃是镇元大仙的私居。中有一供台，上有一玄色七彩丝的剑鞘。台后挂着幅中堂，上书一个“道”字。小楼三面俱是雕花扇窗，于周围景致看的清清楚楚。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3345, 'qujing', 'qujing/wuzhuang/zaifang', '斋房', '斋房分为两半，北边有斋厨，炉上的大锅里热气腾腾。南边摆了一张木桌，几条木凳，几位道长正在进斋。靠墙的架子上放着各类瓜果，都是观中自己种的。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3346, 'qujing', 'qujing/wuzhuang/zhengdian', '正殿', '这是五庄观的正殿，宽敞素雅。四周有几扇木窗，都是上明下暗的雕花格子。北面正中靠壁挂着五彩装成的“天地”二字，下设一张朱红雕漆的香几，几上有一副黄金炉瓶，炉边摆着几束香。正殿东西各有一座偏殿。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3347, 'qujing', 'qujing/wuzhuang/zongge', '钟阁', '钟阁乃是一四方小室，内悬一口巨种，几乎占满了室内的空间，仅周围有尺许空隙人可通过。东边有小门通到松林中。室内四壁洁白，纤尘不染。', 'wuzhuang', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3349, 'qujing', 'qujing/xiaoxitian/baoge', '宝阁', '宝阁是一偏殿，殿的东墙下有一排木柜子，柜门上贴着红签条，柜台上有一签筒，一木鱼一木棰。另有一个小香炉，插着未烧完的香。宝阁的北面是大雄宝殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3350, 'qujing', 'qujing/xiaoxitian/caiyuan', '菜园', '菜园里的地新翻过，种着各种蔬菜瓜果，菜园的边上种着一片果树，树上垂下青皮果子。菜园的东北是大寺院，南边有一座石房。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3351, 'qujing', 'qujing/xiaoxitian/chanfang', '禅房', '一个半新半旧的禅房，已不再使用，现被用来当作仓库，墙角堆着一些粮袋。南边原有两扇窗子，已被用木板封死。北面是通向菜园的门。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3352, 'qujing', 'qujing/xiaoxitian/daxiong', '大雄宝殿', '大雄宝殿里佛像高坐台上，台前放着一个长长的漆木香案，案上有青铜香炉一对，香炉里面冒出青青的香烟。宝殿的西边是寺院，北边是珍楼，南边是宝阁。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3353, 'qujing', 'qujing/xiaoxitian/houdian', '后殿', '后殿里古色古香，东有一排莲花窗，南有一个宽大的软榻，铺了一床锦花被。北面有一桌子和一张椅子。西边的门直通大雄宝殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3354, 'qujing', 'qujing/xiaoxitian/lindao1', '林道', '古树林立，藤蔓缠绕着树枝倒挂着下来。地上是枯枝残叶，走上去吱吱作响。林道两边树林遮阴，散发着团团水雾气，林子的上空白云飘散霞光彩练万道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3355, 'qujing', 'qujing/xiaoxitian/lindao10', '林道', '古树林立，藤蔓缠绕着树枝倒挂着下来。地上是枯枝残叶，走上去吱吱作响。林道两边树林遮阴，散发着团团水雾气，林子的上空白云飘散霞光彩练万道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
