INSERT INTO `rooms` VALUES (3363, 'qujing', 'qujing/xiaoxitian/lindao8', '林道', '古树林立，藤蔓缠绕着树枝倒挂着下来。地上是枯枝残叶，走上去吱吱作响。林道两边树林遮阴，散发着团团水雾气，林子的上空白云飘散霞光彩练万道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3364, 'qujing', 'qujing/xiaoxitian/lindao9', '林道', '古树林立，藤蔓缠绕着树枝倒挂着下来。地上是枯枝残叶，走上去吱吱作响。林道两边树林遮阴，散发着团团水雾气，林子的上空白云飘散霞光彩练万道。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3365, 'qujing', 'qujing/xiaoxitian/simen', '寺门', '山坡之上树林郁郁，有一片开阔地带，一边是山谷另一边是野林，中间耸立着一座高大的寺院，寺院的门前有一长匾写着：“小雷音寺”几个大字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3366, 'qujing', 'qujing/xiaoxitian/siyuan', '寺院', '寺院里有石山花亭，香草异花朵朵，亭边流水潺潺，水边垂柳悠悠如流苏一般。院里一条石路往东铺向一座大殿，院子的北边通向寺外，西南角有一菜园。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3367, 'qujing', 'qujing/xiaoxitian/zhenlou', '珍楼', '珍楼里摆了几张漆木桌子，桌子上放着一些青瓷盘子，盘子里放着一些斋果。门边有几张虎皮躺椅，边上配有小茶几。珍楼的南边有门通向大雄宝殿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3381, 'qujing', 'qujing/yingchou/shanlu1', '雪山从中', '你信步到了一处高山丛中。但见山势险峻，抬头望不到山顶。待向上攀援时，天候骤寒，铅云低压，北风渐紧，接著天空竟飘下一片片的雪花。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3382, 'qujing', 'qujing/yinwu/bopiting', '剥皮亭', '山洞里一座六角石亭，亭子上爬满蔓草青苔，亭内有石桌石椅石凳。北面有通道引向后园，东面是天井，西面是中堂，东南边有一洞穴入口。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3383, 'qujing', 'qujing/yinwu/caopo1', '草坡', '山坡上荒草一大片，长有齐胸之高，走在里面深深浅浅竟如陷沼泽一般。底下藤萝绊脚，抬头风声呼呼响，听上去象是幽歌阵阵隐隐地传来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3384, 'qujing', 'qujing/yinwu/caopo2', '草坡', '山坡上荒草一大片，长有齐胸之高，走在里面深深浅浅竟如陷沼泽一般。底下藤萝绊脚，抬头风声呼呼响，听上去象是幽歌阵阵隐隐地传来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
