INSERT INTO `rooms` VALUES (3388, 'qujing', 'qujing/yinwu/houyuan', '后园', '一个深深的大园子，有一个用树干搭就的棚子，边上是一些高高低低的枯树，地上是一些乱糟糟的干树叶、树皮、绳索之类的杂物。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3389, 'qujing', 'qujing/yinwu/huangye1', '荒野', '荒野四处辽阔，远方可见群山峻岭峭壁，近处有小路进出大小森林树木。风吹过洒洒之声不断，流水潺潺，时闻苍狼嗥叫，时闻饿虎咆哮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3390, 'qujing', 'qujing/yinwu/huangye2', '荒野', '荒野四处辽阔，远方可见群山峻岭峭壁，近处有小路进出大小森林树木。风吹过洒洒之声不断，流水潺潺，时闻苍狼嗥叫，时闻饿虎咆哮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
