INSERT INTO `rooms` VALUES (3396, 'qujing', 'qujing/yinwu/huangye8', '荒野', '荒野四处辽阔，远方可见群山峻岭峭壁，近处有小路进出大小森林树木。风吹过洒洒之声不断，流水潺潺，时闻苍狼嗥叫，时闻饿虎咆哮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3397, 'qujing', 'qujing/yinwu/jiankou1', '涧口', '山石高耸之处，有斜坡自两岸缓缓而下，底下是潺潺流水之声不断，涧水冲击着流水中的大小石块，发出一阵阵震耳欲聋的轰鸣浪声，近处有几条暗沟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3398, 'qujing', 'qujing/yinwu/jiankou2', '涧口', '山石高耸之处，有斜坡自两岸缓缓而下，底下是潺潺流水之声不断，涧水冲击着流水中的大小石块，发出一阵阵震耳欲聋的轰鸣浪声，近处有几条暗沟。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3399, 'qujing', 'qujing/yinwu/lukou', '路口', '这里险象众生，路势奇恶，上通两岸犬牙一般巨石悬崖，下连三路阴森森草坡。路口边一圈摆开大小岩石，尤如天然的石桌石椅一般。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3400, 'qujing', 'qujing/yinwu/maowu', '茅屋', '一座柴扉大开的茅屋，四周是木墙，上面挂着一些黄花金针木耳地衣之类的干菜，茅屋的顶上是干茅草，门外是一圈矮矮的篱笆墙。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3401, 'qujing', 'qujing/yinwu/pian', '偏堂', '偏堂里阴风嗖嗖，洞穴空荡，岩壁犬牙交错乱石丛生。堂里生着几小堆篝火，烟气层层熏人。东边通向中堂，西北面有一山门通向洞外。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3402, 'qujing', 'qujing/yinwu/rouku', '肉库', '一座由岩洞自然形成的洞穴，里面有些阴暗，地上铺着兽皮干草，还有一些七零八落的骨头。洞壁靠有一长架子，上有不少肉干肉巴子。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3403, 'qujing', 'qujing/yinwu/shanmen', '山门', '山巅之处有一背风低坳，古树连天，岩壁上有一石门。只见那石门紧闭，门上有一个横石板，石板上书有“隐雾山折岳连环洞”几个大字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3404, 'qujing', 'qujing/yinwu/tianjing', '天井', '深深的天井里，几根木头搭着架子，架子上搭着一些兽皮，地上有一些光溜溜的大石块，上面晒着肉巴子。天井的一角堆着一些骨头。', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3405, 'qujing', 'qujing/yinwu/xuanya1', '悬崖', '苍山峻岭，峰势崔巍，只见顶上白云飘飘，崖前树影寒寒，林内松柏千千，峦头翠竹几干。四处怪石嶙嶙，使人心感不安，难以擅自举步。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
