INSERT INTO `rooms` VALUES (3412, 'qujing', 'qujing/yinwu/xuanya8', '悬崖', '苍山峻岭，峰势崔巍，只见顶上白云飘飘，崖前树影寒寒，林内松柏千千，峦头翠竹几干。四处怪石嶙嶙，使人心感不安，难以擅自举步。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3413, 'qujing', 'qujing/yinwu/zhong', '中堂', '堂内放着一把虎纹虎脚交椅，两边有双狮头石雕神龛，点着昏暗的兽油灯。堂后滴水嗒嗒有声，雾气缭绕。东边有一廊道通向剥皮亭，西有一偏堂。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3423, 'qujing', 'qujing/yuhua/changshi', '长史馆', '长史馆门口放着两青铜狮，馆里为一大堂，堂中放有一仙桌上有一套细瓷茶具。左手边有一案桌，上面堆了许多本厚厚的公书文本。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3424, 'qujing', 'qujing/yuhua/da', '大王子府', '大王子府碧灯盏盏，一镶银桌上放着玉如意之类的贵重玩意。桌后一高背太师椅，椅前有狮绒垫脚。南窗外可见一小桥曲曲弯弯有水流过。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3425, 'qujing', 'qujing/yuhua/daike', '待客馆', '这里是接待远方来客和贵宾的地方。雪白的墙上贴着剪纸花，北边的墙头放着一神龛。南边挂有几个细麻帐，分别罩着几张考究的大客床。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3426, 'qujing', 'qujing/yuhua/dayuan', '大院', '大院方方正正，院墙高大用山石砌成。西边靠墙根有一排松树，树前开出一片空地，供演武之用。东边有门通向几位王子的府楼，南边是正府。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3427, 'qujing', 'qujing/yuhua/dianshan', '典膳所', '两扇对开雕木花门将典膳所装饰的极为讲究，让人觉得这里是非常人能够来的地方。临街的贴花窗下放着一虎脚桌，两把宽臂椅放在桌子两侧。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3428, 'qujing', 'qujing/yuhua/er', '二王子府', '二王子府蓝色落地绒罩着北墙，墙角有一雕玉狩猎图花屏，西边有一软躺椅，边上是蚂瑙纹茶几。南窗紧闭，隐约可见窗外杨柳拂栏杆。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3429, 'qujing', 'qujing/yuhua/fumen', '府门', '府门高大雄伟，虹光闪烁。一边是金龙出水，另一边是银凤朝阳，门檐上玉麒麟吞云吐雾。再往里看，楼阁宫殿紫气瑞瑞，祥云缭绕。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3430, 'qujing', 'qujing/yuhua/geguan', '歌馆', '这里是此地有名的歌馆，馆门口悬了一朱红大匾，门两边是朱红麒麟柱。里面彩台高搭，乐声不断。不时有歌女上来唱什么曲儿。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3431, 'qujing', 'qujing/yuhua/jiulou', '酒楼', '酒楼里八仙桌摆了二九一十八张，十分豪华。酒楼临街的窗上扎满了各色彩灯笼，象是有什么喜宴要在这里举办。酒楼的里间厨房里飘来一阵烤乳猪的香味。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3432, 'qujing', 'qujing/yuhua/menlou', '门楼', '一座门楼南北向开设，楼下有一通行马车的门洞。门楼两边东西向建起了高高的石墙，门楼上有旌旗飘扬，墙上有一巨匾：玉华县。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3433, 'qujing', 'qujing/yuhua/shaoying', '哨营', '一座临街而建的营房，离门楼有几步之遥。此乃是护城兵士所居之处，偶尔可见兵士进出换岗。里面有一大通铺，门口有一空空的兵器架。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3434, 'qujing', 'qujing/yuhua/shenli', '审理厅', '厅里灯火通明，两张香木长案面对面排开。靠门处有几张软缎靠背椅，厅后有一素花屏风。看样子屏风后面可能有通道引向内室。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3435, 'qujing', 'qujing/yuhua/shi1', '石墙', '墙的南面，高高的石墙下，有一狭窄的通道如小路一般，被人踩得结结实实。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3436, 'qujing', 'qujing/yuhua/shi2', '石墙', '墙的南面，高高的石墙下，有一狭窄的通道如小路一般，被人踩得结结实实。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3437, 'qujing', 'qujing/yuhua/shi3', '石墙', '墙的南面，高高的石墙下，有一狭窄的通道如小路一般，被人踩得结结实实。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3438, 'qujing', 'qujing/yuhua/shi4', '石墙', '墙的南面，高高的石墙下，有一狭窄的通道如小路一般，被人踩得结结实实。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3439, 'qujing', 'qujing/yuhua/tiejiang', '铁匠铺', '铁匠铺里颇为宽大，靠墙有一排大火炉，呼呼地喷着通红的火焰。屋子后面更是一个大铁熔炉，用以制造专门的特大号铁器和兵器。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3440, 'qujing', 'qujing/yuhua/ting', '暴纱亭', '一座可供十来人休息的绿亭，亭外流水潺潺，有一泉水环绕一假山而过。不远处杨柳轻飘，水面上有一小桥曲曲弯弯，景色极为怡人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3441, 'qujing', 'qujing/yuhua/xiao', '小王子府', '小王子府里挑着金黄色的灯笼，东边的墙边放着一金边香炉，炉里香气缭绕。府上有一紫香木长案，案上有一些经书，还有一个玉石砚台。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3442, 'qujing', 'qujing/yuhua/xiaojie1', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。小街的东面有座营房，北面是门楼通向郊外。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3443, 'qujing', 'qujing/yuhua/xiaojie2', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。小街的西面传来打铁的声音，门口挂一杆招牌。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3444, 'qujing', 'qujing/yuhua/xiaojie3', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。东面传来一阵一阵的歌声，西边飘来饭菜的香味。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3445, 'qujing', 'qujing/yuhua/xiaojie4', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。小街的南面远远可见一府门，北面远远可见一门楼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3446, 'qujing', 'qujing/yuhua/xiaojie5', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。小街的西面是一座楼阁，上面挂一个牌子：长史馆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3447, 'qujing', 'qujing/yuhua/xiaojie6', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。小街的南面是一座砖瓦楼，上书：“审理厅”三个大字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3448, 'qujing', 'qujing/yuhua/xiaojie7', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。街的南面有一群楼阁，那里便是王府所在地。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3449, 'qujing', 'qujing/yuhua/xiaojie8', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。街的南面有一厚木楼阁，门口挂有一长牌：典膳所。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3450, 'qujing', 'qujing/yuhua/xiaojie9', '小街', '一条由碎石夯实的小街。小街有丈许宽，两边走着一些行人，街上不时有马车驶过。小街的东面有马车停靠，里面是一家官方的待客馆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3451, 'qujing', 'qujing/yuhua/xiaolu1', '小路', '在荒野上，一条小路蜿蜿蜒蜒又细又长。路边风吹杨柳，莺啾鹤鸣。远处青青山峦起伏，近处翠林稀稀密密，路两边百草争香艳。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3452, 'qujing', 'qujing/yuhua/xiaolu10', '小路', '在荒野上，一条小路蜿蜿蜒蜒又细又长。路边风吹杨柳，莺啾鹤鸣。远处青青山峦起伏，近处翠林稀稀密密，路两边百草争香艳。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
