INSERT INTO `rooms` VALUES (3461, 'qujing', 'qujing/yuhua/xiaolu9', '小路', '在荒野上，一条小路蜿蜿蜒蜒又细又长。路边风吹杨柳，莺啾鹤鸣。远处青青山峦起伏，近处翠林稀稀密密，路两边百草争香艳。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3462, 'qujing', 'qujing/yuhua/zheng', '正府', '大殿里庄严肃穆，殿窗由名贵香木雕成，墙上有鹅绒绣毯，地上铺的是虎皮地毯。殿心为一汉白玉台阶，上有一盘龙宝座，宝座顶上有双凤彩屏。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3465, 'qujing', 'qujing/zhujie/can', '餐厅', '餐厅里摆了大大小小的石桌石凳，厅角支起了一口大锅，油烟顺着洞壁吹向石门外。东北方向有一小门，那里有一个天然的洞穴仓库。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3466, 'qujing', 'qujing/zhujie/cang', '仓库', '石头的洞穴自然形成了一个仓库，里面有上下两层石壁分开，堆放着不同的东西，主要有兽皮肉干之类的陈货。在东边的墙角下似乎有一个缝隙。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3467, 'qujing', 'qujing/zhujie/da', '大厅', '大厅为洞里最大的地方，靠近洞口光线明亮。洞壁四周上长有一层层的青苔，靠洞口的地方长着无数鲜花仙草。大厅的西边有一走廊，东南边是洞口。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3468, 'qujing', 'qujing/zhujie/guo', '过道', '洞穴在这里显得十分拥挤，两边的石壁上爬着青藤，青藤上插着一些火炬，以提供洞内的照明。过道的西边通向外宫殿，东北边通向走廊。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3469, 'qujing', 'qujing/zhujie/nei', '内宫', '内宫里十分宽敞，洞顶垂下几盏明灯，里面点着兽油。西壁有石案一个，边上铺了厚厚的一层兽皮褥子。靠里面的洞壁有一长寿椅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3470, 'qujing', 'qujing/zhujie/pian', '偏宫', '偏宫为一长方形的空穴，两边长满了石笋，洞顶上吊下一些钟乳石，洞壁上插着几把火炬，以供照明之用。烟将洞壁熏得一片漆黑。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3471, 'qujing', 'qujing/zhujie/shanlu1', '山路', '这里的山路平缓但松散如泥，走在上面深一脚浅一脚，让人不禁有点心虚。路边可以听见林中鸟儿的鸣唱，风不断地吹过，四处开满无名野花。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3472, 'qujing', 'qujing/zhujie/shanlu10', '山路', '这里的山路平缓但松散如泥，走在上面深一脚浅一脚，让人不禁有点心虚。路边可以听见林中鸟儿的鸣唱，风不断地吹过，四处开满无名野花。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
