INSERT INTO `rooms` VALUES (3487, 'qujing', 'qujing/zhujie/shanlu8', '山路', '这里的山路平缓但松散如泥，走在上面深一脚浅一脚，让人不禁有点心虚。路边可以听见林中鸟儿的鸣唱，风不断地吹过，四处开满无名野花。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3488, 'qujing', 'qujing/zhujie/shanlu9', '山路', '这里的山路平缓但松散如泥，走在上面深一脚浅一脚，让人不禁有点心虚。路边可以听见林中鸟儿的鸣唱，风不断地吹过，四处开满无名野花。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3489, 'qujing', 'qujing/zhujie/shi', '石牢', '这里是阴森森的石牢，石牢四周是犬牙交错的怪石，从石壁上突凸出来。地上铺着一些枯草，还有几块破破烂烂的旧兽皮零碎地垫在地上。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3490, 'qujing', 'qujing/zhujie/shimen', '石门', '一个幽幽的门洞，洞顶上挂有一个石牌，上边刻着：九曲盘恒洞五个大字。洞的西北边有一入口通向一个大厅，东边有一通道通向餐厅。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3491, 'qujing', 'qujing/zhujie/wai', '外宫', '外宫里摆设整齐，这里本是接待客人的地方。宫里摆着四方石桌以及石茶几，两边几把太师椅上垫着兽皮相对而放。宫里点几盏兽油灯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3492, 'qujing', 'qujing/zhujie/zhong', '中宫', '一个大厅在黑暗中被四周洞壁上的火炬照亮，大厅为三角形，可容纳数十人。大厅的西边有一石头通道通往偏宫，东南边也一石头通道通往外宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3493, 'qujing', 'qujing/zhujie/zou', '走廊', '这里是长长的走廊，两边的石壁拥挤狭窄，走廊顶上垂下长短不一的钟乳石，地上长着一些石笋。走廊的一头通向里面的过道，另一头通向大厅。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3500, 'qujing', 'qujing/zhuzi/beixia1', '北霞街', '北霞街是城北一条东西向的大道，街面宽敞，相传朱紫老国王托梦神游城北夜见霞光万道，果然金圣娘娘怀胎生下太子，故将此街命名为北霞街以示吉祥。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3501, 'qujing', 'qujing/zhuzi/beixia2', '北霞街', '北霞街是城北一条东西向的大道，街面宽敞，相传朱紫老国王托梦神游城北夜见霞光万道，果然金圣娘娘怀胎生下太子，故将此街命名为北霞街以示吉祥。南边有一茶房的招牌。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3502, 'qujing', 'qujing/zhuzi/beixia3', '北霞街', '北霞街是城北一条东西向的大道，街面宽敞，相传朱紫老国王托梦神游城北夜见霞光万道，果然金圣娘娘怀胎生下太子，故将此街命名为北霞街以示吉祥。东边是繁华热闹的街口。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3503, 'qujing', 'qujing/zhuzi/beixia4', '北霞街', '北霞街是城北一条东西向的大道，街面宽敞，相传朱紫老国王托梦神游城北夜见霞光万道，果然金圣娘娘怀胎生下太子，故将此街命名为北霞街以示吉祥。西边是繁华热闹的街口。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3504, 'qujing', 'qujing/zhuzi/beixia5', '北霞街', '北霞街是城北一条东西向的大道，街面宽敞，相传朱紫老国王托梦神游城北夜见霞光万道，果然金圣娘娘怀胎生下太子，故将此街命名为北霞街以示吉祥。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3505, 'qujing', 'qujing/zhuzi/beixia6', '北霞街', '北霞街是城北一条东西向的大道，街面宽敞，相传朱紫老国王托梦神游城北夜见霞光万道，果然金圣娘娘怀胎生下太子，故将此街命名为北霞街以示吉祥。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3506, 'qujing', 'qujing/zhuzi/bingying', '兵营', '这里是一个大院，驻扎着皇家的兵将。兵营门口有旌旗飘扬，几位校尉来来回回地走动，一些士兵在集队呐喊着操练。院子西南角有一兵器架。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3507, 'qujing', 'qujing/zhuzi/chafang', '茶房', '茶房是朱紫国的闲人杂聚的场所，里面一字排开一些木桌木椅。茶客们一边品茶，一边绘声绘色交头接耳，人声鼎沸。北边的门通向北霞街，南边的门通向夕林街。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3508, 'qujing', 'qujing/zhuzi/chu', '厨房', '一口泥灶砌在墙边，柴禾堆放在灶边。灶上是一大铁锅，两只水桶放在旁边。靠墙有一柜子，放着一些青瓷碗细竹筷。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3509, 'qujing', 'qujing/zhuzi/dalu1', '大路', '一条宽敞的大路，由碎石铺就，可行车马。南北向伸延出去，北面伸向远处，南面通向朱紫国。路两边长着庄稼，偶见农舍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3510, 'qujing', 'qujing/zhuzi/dalu2', '大路', '一条宽敞的大路，由碎石铺就，可行车马。南北向伸延出去，北面伸向远处，南面通向朱紫国。路两边长着庄稼，偶见农舍。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3511, 'qujing', 'qujing/zhuzi/douxi', '斗蟋馆', '斗蟋馆里有一张长方木桌，上面放着一些陶盘陶罐，专供斗蟋蟀之用。一些公子少爷光顾此处，一边摇着鹅毛扇一边聊天，同时观斗蟋蟀。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3512, 'qujing', 'qujing/zhuzi/fanlou', '饭楼', '饭楼靠街有一两个很高很小的窗子，里面灯火通明，客人满席，正在有滋有味地吃饭喝汤。几面屏风将整个屋子分成雅俗几个不同等级的席位，北边是夕林街。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3513, 'qujing', 'qujing/zhuzi/gongmen', '宫门', '一座金壁辉煌的大门，门上有一对朱龙紫凤盘绕。门前左右各有一只玉石精雕麒麟栩栩如生。这便是朱紫国的皇宫大门朝北是朱紫街，东西是护宫河。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3514, 'qujing', 'qujing/zhuzi/gulou', '鼓楼', '鼓楼位于朱紫国的城中心，人多喧哗，经常挤挤挨挨，偶尔可见一些校尉来往行走。往西是夕林街为食品闹市，往东则有一些会馆客栈，南边可见朱紫国皇宫。鼓楼上贴有一皇榜(huang bang)，有人围观。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3515, 'qujing', 'qujing/zhuzi/housan', '后三宫', '后三宫为三宫连通，东边为玉圣，西边为银圣，中间为金圣。宫殿华丽无比金银玉雕嵌四周，地上铺设紫红绣锦绒毯，西边更有阵阵丝竹乐声轻缓飘来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3516, 'qujing', 'qujing/zhuzi/hugong1', '护宫河', '……你站在齐胸深的护宫河水里……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3517, 'qujing', 'qujing/zhuzi/hugong2', '护宫河', '……你站在齐胸深的护宫河水里……', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3518, 'qujing', 'qujing/zhuzi/huitong', '会同馆', '会同馆为天阳街最大的聚集地，远道而来的客人受到邀请可以在这里休息，整个会同馆舒适安静。贵宾到此，会有专门的人夫迎接安排住宿饭食。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3519, 'qujing', 'qujing/zhuzi/jiekou', '街口', '这里北霞街与朱紫街交叉，路口繁华，人来人往不断。往北可以远远看见朱紫门，往南通向朱紫国的城中心鼓楼，东西两边各自通向北霞街。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3520, 'qujing', 'qujing/zhuzi/jiudian', '酒店', '店里酒气熏天，靠窗一是几张方桌，里面是酒柜，上面放着大小不一的酒坛子。墙上写着“不醉不归，醉亦不归”，墙下有些躺椅，一些醉得不醒人事的酒客正躺在上面休息。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3521, 'qujing', 'qujing/zhuzi/lin1', '林中路', '你走在长长的林中路上，两边林深幽幽，狂风吹得叶飞枝舞，时不时传来远处的虎啸猿啼。令人不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3522, 'qujing', 'qujing/zhuzi/lin2', '林中路', '你走在长长的林中路上，两边林深幽幽，狂风吹得叶飞枝舞，时不时传来远处的虎啸猿啼。令人不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
