INSERT INTO `rooms` VALUES (3525, 'qujing', 'qujing/zhuzi/lin5', '林中路', '你走在长长的林中路上，两边林深幽幽，狂风吹得叶飞枝舞，时不时传来远处的虎啸猿啼。令人不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3526, 'qujing', 'qujing/zhuzi/lin6', '林中路', '你走在长长的林中路上，两边林深幽幽，狂风吹得叶飞枝舞，时不时传来远处的虎啸猿啼。令人不由自主地加快步伐。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3527, 'qujing', 'qujing/zhuzi/mazhan', '马栈', '马栈为远道而来的客人准备了休息躺椅，栈里十分宽敞。墙角有一栓马柱，还有一些空空的马槽架在屋子里，专为在此落脚的客人们提供方便。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3528, 'qujing', 'qujing/zhuzi/mianguan', '面馆', '这是位于城中心的一家面馆，地段繁华，生意极为兴隆。店里销售各式各样精美面点，面条，烧饼馍馍。东边有一门通向朱紫街，南边通向夕林街。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3529, 'qujing', 'qujing/zhuzi/mipu', '米铺', '米铺里柜台很高，后面堆着一袋一袋的大米。屋堂里放着一个大木架，上面是一框框的蔬菜和一些装着食盐椒料。柜台后面正坐着米老板，瞪着一双精明的老鼠眼。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3530, 'qujing', 'qujing/zhuzi/nei', '内宫', '内宫庄严肃穆，由檀香木屏将四周隔开，屏上雕有紫金龙戏珠。宫中间是珍珠紫龙床，上有十八床绸缎凤凰绒被，配有四对织锦鸳鸯软心枕。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3531, 'qujing', 'qujing/zhuzi/neiyuan', '内院', '内院里细石如碎玉铺地，东南角几棵梧桐临月台而植，东北君子竹翠绿似画。西边有莲花道通向正宫，东边则是牡丹芍药花圃一路延向内宫，东南处有霜叶松引向后三宫。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3532, 'qujing', 'qujing/zhuzi/qian', '前宫', '前宫为十二柱大殿，柱柱朱红绘有金龙彩凤。柱顶上挂有银铃，叮当随风而鸣音乐声脆回韵不绝。殿顶画着紫色祥云朵朵缭绕，瑞气朦胧彩雾千条。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3533, 'qujing', 'qujing/zhuzi/tian1', '天阳街', '天阳街位于城东，有大小客栈药房会馆，行人来往纷杂。也有一些远道而来的路客在街上寻找休息住所，偶然可见到马车停在路边。北面是一家老字号药铺。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3534, 'qujing', 'qujing/zhuzi/tian2', '天阳街', '天阳街位于城东，有大小客栈药房会馆，行人来往纷杂。也有一些远道而来的路客在街上寻找休息住所，偶然可见到马车停在路边。在南边可以见到一家挂匾的会馆，北面是消遣去处－－斗蟋馆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3535, 'qujing', 'qujing/zhuzi/tian3', '天阳街', '天阳街位于城东，有大小客栈药房会馆，行人来往纷杂。也有一些远道而来的路客在街上寻找休息住所，偶然可见到马车停在路边。北面是一家马栈。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3536, 'qujing', 'qujing/zhuzi/tian4', '天阳门', '这里是朱紫国城门的东门，门上飘着杏黄旗上书“朱紫国”。城门宽敞，西面是天阳街，东北是通向城郊山坡的路。门口有些校尉在盘查行人。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3537, 'qujing', 'qujing/zhuzi/xi1', '夕林门', '夕林门是城西门，城门紧避，楼上飘着一杏黄旗上书“朱紫国”三个大字，一些校尉在门口巡查。东边方向是著名的食市夕林街，飘来阵阵饭菜香。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3538, 'qujing', 'qujing/zhuzi/xi2', '夕林街', '夕林街为朱紫国食品街市，饭馆酒楼林立，香味扑鼻。一群群食客们沿街进出各家。北面是一家写着酒字招牌的酒店，南面是一座经常客满的饭楼。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3539, 'qujing', 'qujing/zhuzi/xi3', '夕林街', '夕林街为朱紫国食品街市，饭馆酒楼林立，香味扑鼻。一群群食客们沿街进出各家。北面是熙熙攘攘的茶房，南边是朱紫国的一家大米铺。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3540, 'qujing', 'qujing/zhuzi/xi4', '夕林街', '夕林街为朱紫国食品街市，饭馆酒楼林立，香味扑鼻。一群群食客们沿街进出各家。南边有一家专营杂货的小店，北边是挂出大招牌的一家面馆。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3541, 'qujing', 'qujing/zhuzi/xiang', '厢房', '厢房干净整齐，房门口有一檀香木太师椅，房里有八仙桌可以备席设宴，上放有紫茶壶。门边有一砖台红泥小炉，极为雅致，情调非常怡人。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3542, 'qujing', 'qujing/zhuzi/yaopu', '药铺', '药铺门口摊开一些正在晒的草药，铺子里有一丈许的大药柜，装着各式草药。墙上贴着一匾，上书“免费号脉”四个字。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3543, 'qujing', 'qujing/zhuzi/yuhua', '御花园', '这里朱栏紫槛，奇花异草满园生长与丽日争艳。园中有一圆池流水潺潺于小桥下穿过，更有一长短亭造型精美，亭外垂柳飘然，修篁依依。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3544, 'qujing', 'qujing/zhuzi/zahuo', '杂货店', '杂货店门面不大，靠墙放有一排长长的货架，上面摆着各式各样的朱紫国杂货。店家是一位大胖子，旁边坐着的，是他的瘦婆娘。两人正倚窗晒着太阳。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3545, 'qujing', 'qujing/zhuzi/zhaoyang', '昭阳宫', '宫中檀香木柱雕有祥云朵朵，墙壁上五彩缤纷虹霞万千，真是个仙境重生。丝竹乐声轻缓如风飘逸，又见宫女托着鲜果山珍佳肴来回走过。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3546, 'qujing', 'qujing/zhuzi/zheng', '正宫', '正宫紫气万千，祥云飞舞红光满殿。只见玛瑙檐白玉砖琉璃瓦，四周的墙上锦龙绣凤欲飞欲舞，正中是金鼎银座，两边文武官员分别排开肃然而立。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3547, 'qujing', 'qujing/zhuzi/zhuzi1', '朱紫门', '城门高耸，城头上飘着一杏黄旗，上书“朱紫国”。城门外有一护城河，架设有一双车对行木悬桥，由粗铁链吊紧。门洞宽大，分里中外三层门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3548, 'qujing', 'qujing/zhuzi/zhuzi2', '朱紫街', '朱紫国的中心大道，由附近山上运来的条石铺成，可通行来往马车。往北通向朱紫国的北门朱紫门，往南通向朱紫国的城中心，再往南就是皇宫所在地。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3549, 'qujing', 'qujing/zhuzi/zhuzi3', '朱紫街', '朱紫国的中心大道，由附近山上运来的条石铺成，可通行来往马车。往北是繁华的街口与北霞街相连，往南是朱紫国的城中心鼓楼，再往南可见朱紫国皇宫。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3550, 'qujing', 'qujing/zhuzi/zhuzi4', '朱紫街', '朱紫国的中心大道，由附近山上运来的条石铺成，可通行来往马车。往北是朱紫国的城中心鼓楼，东南有一飘着旌旗的兵营，再往南可见朱紫国皇宫。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3551, 'qujing', 'qujing/zhuzi/zhuzi5', '朱紫街', '朱紫国的中心大道，由附近山上运来的条石铺成，可通行来往马车。往北可以看见朱紫国的鼓楼，东边是一座兵营，南边就是朱紫国的皇宫大门。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3562, 'sea', 'sea/boy1', '沁玉殿', '这里是龙太子住的宫殿。屋里摆设简单，仅有一桌四椅。太子平时也不在这里，柱上的明珠将屋中照得一片通明。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3563, 'sea', 'sea/boy2', '过道', '一条长长的走廊，联结着前后厅。东边是太子的寝室，传出杯酬交错的声音，几名宫女端着盒子走来走去。北边一间大厅，是太子练武的地方。', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3564, 'sea', 'sea/boy3', '卧龙阁', '当中一个八仙桌，桌上摆的都是些山珍海味。太子正和几个朋友喝酒。宫女们来回上菜，屋中一片酒味。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3565, 'sea', 'sea/boy4', '练功堂', '屋里十分宽敞，墙上画的是一些叉术分解，靠墙的架子上放了十余把长枪。地下铺的是裁剪整齐的木块，踩在上面吱吱做响。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3566, 'sea', 'sea/food', '餐房', '龙宫内的一间餐房，一般只是宫中弟子使用。锅里沽嘟嘟不知煮着什么东西，一个大箩筐里放着好些包子。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3567, 'sea', 'sea/gate', '龙宫大门', '嵌在宫殿各处的珍宝发出的光芒耀得你连眼睛都睁不开了。依稀看　　　到宫门上方挂这一幅方匾，上有＂东海龙宫＂四个大字。几名虾兵　　　蟹将分列两旁，警惕的盯着来往的人。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3568, 'sea', 'sea/girl1', '紫云宫', '紫云宫是公主龙女住的地方，当然这里不许男子出入。屋里的装饰多是人间难得一见的珍宝。正中一块浑玉雕成的香炉苒苒的冒着一股淡紫色的薄烟，整个屋中漫着香气。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3569, 'sea', 'sea/girl2', '花园', '花园虽不大，花儿却极多。五颜六色，姹紫嫣红。看一看却都不认的．几只彩色的小鱼游来游去。向东是公主的寝宫，南边是公主平时练武的地方。', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3570, 'sea', 'sea/girl3', '绣房', '公主龙女就住在这里。房内布置的极其典雅。左一道屏，右一挂帘使屋里显得朦朦胧胧。公主和几个小宫女不知在笑着什么。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3571, 'sea', 'sea/girl4', '云房', '整个房间象是包在一团云中。听说是当年龙王与太上老君打赌赢来的。在这里练武(lianwu)感到轻飘飘的，对练习轻功却是有莫大的好处。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3572, 'sea', 'sea/huayuan', '御花园', '花园之中的草木并不繁盛，但细瞧去都是些在凡间难得一见的珍品　　　异种，花间有些奇异的小鱼游动，为花园添了几分情趣。后宫中来　　　往人较少，远没有前殿的那种喧嚣。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3573, 'sea', 'sea/huayuan1', '御花园', '花园之中的草木并不繁盛，但细瞧去都是些在凡间难得一见的珍品　　　异种，花间有些奇异的小鱼游动，为花园添了几分情趣。后宫中来　　　往人较少，远没有前殿的那种喧嚣。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
