INSERT INTO `rooms` VALUES (3582, 'sea', 'sea/huilang1', '回廊', '细细的回廊环绕着水晶宫，回廊两侧有着淡淡薄雾，看不甚清。栏　　　上雕着各种水兽鱼虫，似乎在随着水波轻轻游动。头顶上有彩色的　　　珊瑚成伞状。前后偶有巡视的兵将走过。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
