INSERT INTO `rooms` VALUES (3590, 'sea', 'sea/inside1', '广场', '在宫门与正宫之间是一个巨大的广场．一些虾兵蟹将正在这里操练', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3591, 'sea', 'sea/inside2', '玉阶', '由此向上是龙宫正殿，东海龙王就住在里面。一级级的台阶都是用　　　玉砌成，阶上两边立着武士，银盔银甲，煞是威风。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3592, 'sea', 'sea/inside3', '龙宫正殿', '正殿之上悬一明珠，把诺大一殿照得通亮。两旁桌椅玉石打造而成，　　当中还嵌着无数珠宝。两边墙上挂了两幅画，看起来相当的陈旧。　　　南北是两座偏殿。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3593, 'sea', 'sea/inside4', '内堂', '后殿中铜炉熏香，又有细廊通向两旁。殿后有一台，台中几个宫女正陪着龙婆观景。台外有一片花园，老梅吐萼，遍地鹿苔。远处平林尽被烟雾笼罩。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3594, 'sea', 'sea/inside5', '慎言堂', '大殿里龙柱凤檐富丽堂皇，南边是鹅黄落地绒，上面用珍珠绣有碧海波涛，北面是一排白玉窗，窗檐上雕着金龟如意图。往北有铺花道通往宝殿。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3595, 'sea', 'sea/inside6', '明察堂', '明察堂是东海龙宫中大将军鲸无敌的办公场所，檀木桌上叉着令旗　　　和令箭。平常的虾兵蟹将是不敢来这里的，出入的人也小心翼翼，　　　不敢大声出气，周围一派肃穆的气氛。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3596, 'sea', 'sea/jiashan1', '假山', '假山上多有尖石玲珑，耸拔瘦削。远观如有山云突涌，夹杂草木嫩绿满山。假山上却有一铜石，中有小孔(hole)。间闻园中笑音阵阵，极是热闹。', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3597, 'sea', 'sea/jiashan2', '假山', '假山上多有尖石玲珑，耸拔瘦削。远观如有山云突涌，夹杂草木嫩绿满山。假山上却有一铜石，中有小孔(hole)。间闻园中笑音阵阵，极是热闹。', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3598, 'sea', 'sea/jingxing', '静性堂', '静性堂四四方方，正面墙上高挂一幅“龙腾四海”的古画。画中的', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3599, 'sea', 'sea/maze0', '海底', '这里水色变的浑浊起来，周围已看不大清楚了。偶有暗流袭来，卷起阵阵的泥流。南部一片黑色，似乎把水也染黑了。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3600, 'sea', 'sea/maze1', '海底莽林', '这里水色变的浑浊起来，周围已看不大清楚了。偶有暗流袭来，卷起阵阵的泥流。四处长着些高高的海草，密密麻麻把头上遮的一丝光芒也没有了。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
