INSERT INTO `rooms` VALUES (3609, 'sea', 'sea/mishi1', '密室', '密室中黑黑的，看不大清楚。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3610, 'sea', 'sea/mishi2', '密室', '密室中黑黑的，看不大清楚。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3611, 'sea', 'sea/mulang1', '幕府', '幕府是龙宫中虾兵蟹将各类水怪休息的地方。厅前挂着又厚又高的　　　帘子，将其于前厅分开。堂中并无华丽的装饰，但打扫的恨干净。　　　有几个宫娥出出入入。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3612, 'sea', 'sea/mulang2', '幕府', '幕府是龙宫中虾兵蟹将各类水怪休息的地方。厅前挂着又厚又高的　　　帘子，将其于前厅分开。堂中并无华丽的装饰，但打扫的恨干净。　　　有几个宫娥出出入入。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3613, 'sea', 'sea/qingxin', '清心堂', '这里是东海龙宫的南侧殿，一架大屏风将殿分成两半，屏风后放着一些大大小小的漆红嵌金箱子彩盒，里面是宫内的文书符篆，每到行雨时都少不了它们。几个文官模样的鱼怪来回出入。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3614, 'sea', 'sea/shanhua', '散华台', '这里是龙宫中的一个露台，一笼轻纱遮住了后面宫室内的珠光宝器。　　露台呈长形，周围摆设似乎有什么玄机，却一时看不出些门道。听　　　说在这里修练能使人很容易脱污去诟而超凡入定。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3615, 'sea', 'sea/shiwu', '石屋', '花园尽头出现一座石屋，屋乃巨石砌成，暗淡光下看起来相当的', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3616, 'sea', 'sea/sleep', '睡房', '这里是龙宫中的睡房。', '0', 'normal', 1, 0, 0, 1, 1, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3617, 'sea', 'sea/under1', '海底', '到了一个水中世界。海面上波浪汹涌，这里却静得出奇。一群群银色的小鱼在蓝色的海水中游来游去，脚下是色彩斑斓的珊湖礁，其中白色的珊瑚连成一线，如一条白云铺成的道路。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3618, 'sea', 'sea/under2', '海底', '到了一个水中世界。海面上波浪汹涌，这里却静的出奇。一群群银色的小鱼在蓝色的海水中游来游去，脚下是色彩斑斓的珊湖礁，其中白色的珊湖连成一线，如一条白云铺成的道路。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3619, 'sea', 'sea/under3', '海底', '到了一个水中世界。海面上波浪汹涌，这里却静的出奇。一群群银', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3620, 'sea', 'sea/under4', '海底', '前方隐约现出一座宫殿，发出一道道五颜六色的光芒。这里的鱼儿也特别多，还有许多奇形怪状的海怪。一行行，一列列，宛如臣子拜见皇帝一般。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3621, 'sea', 'sea/wolongrest', '休息室', '这里是龙的寝宫，空旷的大殿，四周有龙柱支撑。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3622, 'sea', 'sea/wunei', '石屋内', '石屋内黑咚咚的，还散发着一股说不上来的怪味，让人闻之欲呕。周围依稀看到几根铁柱，还残留着几丝血迹。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3623, 'sea', 'sea/xizhen', '吸真台', '这里是龙宫中的一个露台，一笼轻纱遮住了后面宫室内的珠光宝器。　　露台呈长形，周围摆设似乎有什么玄机，却一时看不出些门道。听　　　说在这里修练能使人很容易脱污去诟而超凡入定。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3624, 'sea', 'sea/yidao', '仪道', '这里是花园中的一条小道，看周围的情形并不是经常有人来。路上', '1', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3625, 'sea', 'sea/yujie1', '玉阶', '由此向上是龙宫正殿，东海龙王就住在里面。一级级的台阶都是用', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3626, 'sea', 'sea/yujie2', '龙宫前厅', '四根巨大的盘龙柱子撑出了一个相当大的龙宫前厅，龙宫中若有大', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3627, 'sea', 'sea/yujie3', '玉阶', '由此向上是龙宫正殿，东海龙王就住在里面。一级级的台阶都是用　　　玉砌成，阶上两边立着武士，银盔银甲，煞是威风。', '0', 'normal', 1, 0, 0, 0, 1, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3702, 'southern', 'southern/emei/chunyangdian', '纯阳殿', '殿正中的雕像，就是自称回道人的吕洞宾的像了。枋上有一联曰：「稳睡为何因，遍游天下，未得缘人说妙道；醉眼无别事，厌闻世况，掀开记卷乐长生」。吕纯阳唐朝京兆人。他两举进士不第，浪游江湖，曾隐居终南山等地修道。後游历各地，自称回道人。为八仙之一，道教全真道尊他为北五祖之一。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3703, 'southern', 'southern/emei/daochang', '普贤菩萨道场', '东汉明帝时，一天，有位名叫蒲公的隐士正在山上采药，突然见一头放金光者，坐骑白象，从空中飞驰而过，遂跟踪到顶峰，却又渺无人迹。後蒲公被告知这是普贤菩萨显现全身。於是，蒲公回山舍宅为庙，供奉普贤，以後峨嵋山就成了普贤道场。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3704, 'southern', 'southern/emei/guandao1', '官道', '一条崎岖的东西向小路，通入蜀中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3705, 'southern', 'southern/emei/guandao2', '官道', '一条崎岖的东西向小路，通入蜀中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3706, 'southern', 'southern/emei/guandao3', '官道', '一条崎岖的东西向小路，通入蜀中。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3707, 'southern', 'southern/emei/guangxiangsi', '光相寺', '金顶过去有许多庙宇，其中有座祖殿，为峨嵋山古寺之一。汉时叫普光殿，唐宋间又改为光相寺。明朝蜀藩捐资扩建。殿瓦、柱、门、棂、窗和四壁皆铜质掺金。此殿在阳光照耀下金光闪闪，加上地势高，山下四周可见，故名「金顶」。这就是峨嵋山金顶的由来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3708, 'southern', 'southern/emei/ninding', '金顶', '峨嵋金顶有四大奇观：云海、日出、佛光和佛灯。其中又以佛光最为有名。在云平风静的午後，总会出现在云层的一个虚明若镜、极其艳丽约五彩光环。观看光环时，可见镜中暗影与观者影形一样。但每个人只能看见自己的身影，不能看见他人身影。后人作诗咏赞：「非云非雾起层空，异彩奇辉迥不同。试向岩石高处望，人人都在佛光中。」', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3709, 'southern', 'southern/emei/jiulaodong', '九老洞', '传说黄帝为访天皇真人，来到峨嵋山腰的仙峰寺侧的一山洞，他在洞外见一老者，问道：「仅翁一人乎？」老者答：「九老居此」。後人於是把此洞称为九老洞。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3710, 'southern', 'southern/emei/shanjiao', '峨嵋山脚', '走到这里，我们已经可以看到雄秀壮丽的峨嵋山了，上山进香的人络绎不绝，磨肩接踵。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3711, 'southern', 'southern/emei/shanlu1', '山路', '「蜀国多仙山，峨嵋世难匹。」，名诗人范成大曾在峨嵋山游了十九天。後来他在《叁峨》一诗中赞道：「大峨两山相对开，小峨中峨迤逦来；叁峨秀色甲天下，何须涉海寻蓬莱。」从此，峨嵋天下秀的美名扬名开来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3712, 'southern', 'southern/emei/shanlu2', '山路', '「蜀国多仙山，峨嵋世难匹。」，名诗人范成大曾在峨嵋山游了十九天。後来他在《叁峨》一诗中赞道：「大峨两山相对开，小峨中峨迤逦来；叁峨秀色甲天下，何须涉海寻蓬莱。」从此，峨嵋天下秀的美名扬名开来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3713, 'southern', 'southern/emei/shanlu3', '山路', '「蜀国多仙山，峨嵋世难匹。」，名诗人范成大曾在峨嵋山游了十九天。後来他在《叁峨》一诗中赞道：「大峨两山相对开，小峨中峨迤逦来；叁峨秀色甲天下，何须涉海寻蓬莱。」从此，峨嵋天下秀的美名扬名开来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3714, 'southern', 'southern/emei/shanlu4', '山路', '「蜀国多仙山，峨嵋世难匹。」，名诗人范成大曾在峨嵋山游了十九天。後来他在《叁峨》一诗中赞道：「大峨两山相对开，小峨中峨迤逦来；叁峨秀色甲天下，何须涉海寻蓬莱。」从此，峨嵋天下秀的美名扬名开来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3715, 'southern', 'southern/emei/shanlu5', '山路', '「蜀国多仙山，峨嵋世难匹。」，名诗人范成大曾在峨嵋山游了十九天。後来他在《叁峨》一诗中赞道：「大峨两山相对开，小峨中峨迤逦来；叁峨秀色甲天下，何须涉海寻蓬莱。」从此，峨嵋天下秀的美名扬名开来。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3716, 'southern', 'southern/emei/shanyao', '山腰', '被道家称为「第七洞天」的峨嵋山，满载着各种美丽的传说，向南走去，你就可以找到传说中的九老洞了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3717, 'southern', 'southern/emei/sheshenyan', '舍身岩', '金顶岩下．是一个纵深七百二十米的断岩绝壁。这断岩峭削方棱、嵯峨峥嵘，有人身贴岩石，匍匐下窥，莫不咋舌而回。人们又称它为舍身岩。自古以来，不知有多少轻生者来此纵身一跳了结一生。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3718, 'southern', 'southern/emei/wanniansi', '万年寺', '峨嵋山的众寺庙中，要数万年寺名气最大。这是一座供奉普贤的寺庙。前殿正中一个浑身洁白的大象，驮了一尊菩萨。这就是有名的普贤。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3723, 'southern', 'southern/wutai/chaolongdong', '秘魔岩窟', '传说文殊菩萨当年就将来此滋事的小龙关在这朝龙洞里。文殊菩萨命众龙在此好好修行，并说要派弟子来朝拜和供养他们，因此这个秘魔岩窟又叫＂“朝龙洞”。传说朝拜者各见境界不一，善良人见佛、菩萨；邪恶人见不到欢乐境界。真可谓万人万境。而且有“朝五台山，若不朝拜朝龙洞只算朝拜了半个五台山”的说法。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3724, 'southern', 'southern/wutai/guandao1', '官道', '一条宽阔的大道，贯穿南北，直同边关。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3725, 'southern', 'southern/wutai/guandao2', '官道', '一条宽阔的大道，贯穿南北，直同边关。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3726, 'southern', 'southern/wutai/guandao3', '官道', '一条宽阔的大道，贯穿南北，直同边关。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3727, 'southern', 'southern/wutai/qinglianggu', '清凉谷', '走到谷口，一股清风吹来，令人心情为之一畅。这里就是四季如春的清凉谷了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3728, 'southern', 'southern/wutai/qlsi_gate', '清凉寺门', '那清凉寺在清凉山之巅，和沿途所见寺庙相比，也不见得如何宏伟，山门破旧，显已年久失修。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3729, 'southern', 'southern/wutai/qlsi_shanlu1', '山路', '由此上山就到清凉寺了，前面一大石，便是传说中文殊菩萨从龙宫得来的清凉石(stone)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3730, 'southern', 'southern/wutai/qlsi_shanlu2', '山路', '沿着山路前行，望着那披着青松与白杨的冈峦，那映着鲜花与绿草的山泉，那阵阵松涛和悠悠的钟声，那绿茸茸的草地映衬着古庙琉璃瓦上的夕阳，不禁令人心旷神怡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3731, 'southern', 'southern/wutai/qlsi_shanlu3', '山路', '沿着山路前行，望着那披着青松与白杨的冈峦，那映着鲜花与绿草的山泉，那阵阵松涛和悠悠的钟声，那绿茸茸的草地映衬着古庙琉璃瓦上的夕阳，不禁令人心旷神怡。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3732, 'southern', 'southern/wutai/qlsi_shanlu4', '山路', '走在山中，只见四处鲜花灿烂，四周的岩石都有深深的纹路，据说当年文殊菩萨从龙宫取得歇龙石后，那些外出的小龙王回来时，发现歇龙石不在了，怨气冲天，便追到这里，四处对找。气急败坏的小龙王，用龙尾把五个峰扫成了平台；用利爪把岩石刨得乱七八糟，至今这些石块还遍布满山，人称“龙翻石”。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3733, 'southern', 'southern/wutai/qlsi_tang', '清凉寺内堂', '寺内并没有什么陈设，只是几尊佛像，一口钟而已，正中的蒲团，便是文殊菩萨的位子了。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3734, 'southern', 'southern/wutai/qlsi_yuan', '院内', '那清凉寺在清凉山之巅，和沿途所见寺庙相比，也不见得如何宏伟，山门破旧，显已年久失修。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3735, 'southern', 'southern/wutai/shanjiao', '五台山脚下', '从此以北的方圆五百余里，就都是五台山了，共有五座山峰，五峰拱卫连绵，从山谷吹来的习习凉风使这块小盆地的沟沟洼洼里，到处都有美的色彩与施律。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3736, 'westway', 'westway/dadao', '大道', '这是一条长长的大道，在远远的山脚下绕过。大地苍茫，西北风呼呼地吹着，卷起路上扬起的风沙。这里的行人明显地少了，都在匆匆忙忙地赶着路，往东是金城郡，往西面再赶一赶路就可以到达永靖了。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3737, 'westway', 'westway/fenghuo', '烽火台', '高高的烽火台，从烽火台向西望去，一片茫茫大雾海一般地迷茫，什么也看不清。向东望去，远远地烽火台一个连一个坐在群山峰上一直通向天边极远处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3738, 'westway', 'westway/jiayu', '嘉峪关', '一座雄伟的关口坐落在群山之中，嘉峪关是长城最西的关口，镇守大唐国的西域大门。关外向西便是通向西域各国的艰难道路，只见西面一片茫茫大雾如海一般恍恍惚惚什么也看不见。关内向东通向大唐国各地，南边有一个小小出口与蜂火台相连。', '0', 'normal', 1, 0, 0, 0, 0, '{\"valid_leave\": {\"southup\": {\"npc_id\": \"wujiang-westway\", \"message\": \"边关守将嚷到：那不是你该去的地方！\", \"condition\": \"npc_exists\"}}}', 0, NULL);
INSERT INTO `rooms` VALUES (3739, 'westway', 'westway/jincheng', '金城郡南', '金城郡是西北地区的重要城镇。向西看去，茫茫一片远处隐隐约约有一群山脉。北边是金城郡南门，城门紧闭，城门洞里摆着一小食摊在卖着什么。往东有一条大官道可以通达大唐国都长安城。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3740, 'westway', 'westway/jiuquan', '酒泉郊外', '酒泉郊外是长途车马队歇脚的另一个重要地点。这里比较热闹，尤其以产酒而闻名，\"葡萄美酒夜光杯\"由此而来。东面是一条马道，西面是一条石栈道，北部是座神秘的小山丘。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'spring');
INSERT INTO `rooms` VALUES (3741, 'westway', 'westway/lu1', '山洞内', '山洞里黑乎乎的。南边的洞门口堆着好些杂草，大概从外边是看不来的。北边山洞弯弯地通向深处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3742, 'westway', 'westway/lu2', '山洞内', '山洞里黑乎乎的，到处都发出股腥臭味。北边山洞弯弯地通向深处。洞深处传出几丝铉乐，似乎在开大宴。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3743, 'westway', 'westway/lu3', '大厅', '大厅之上还是非常宽敞，周围墙上点着粗大的油灯，把大厅照的通亮。厅中高台上放着三把太师椅，几个小妖来回走动。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3744, 'westway', 'westway/madao', '马道', '一条车马专用的长道，路上行人匆匆忙忙地赶路，西边快到酒泉了。东南方向有一片林地，路向林地的深处伸去，那便是经常出危险的饮马峪。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3745, 'westway', 'westway/pingyang', '平阳道', '蜿蜒的平阳道细细长长，通进山里。这里安安静静，抬头向西看去，大道的一端在山谷里消失。向东北看去，一队马车正急急地向永靖方向赶去。大道边有一棵巨大的枯树(tree)。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3746, 'westway', 'westway/shandong', '山洞里', '山洞里有点昏暗，从洞外顶上垂下一些藤条。洞内壁上长了一层层的绿苔，洞的左角地上铺了一些干草。草上盘腿坐着一位老人，似乎并没有察觉你的到来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3747, 'westway', 'westway/shizhan', '石栈道', '这是一条极长的用大石块铺成的栈道，远处栈道伸进石坡，不得不在有的地方凿石辟路架路。据说西面再远一点就是著名的嘉峪关了，往东是去酒泉的方向。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3748, 'westway', 'westway/tielong', '铁笼中', '铁笼是由手指粗的钢条圈成，看起来十分的坚固。一般人看来是休想逃出去的，不过你也可以去试试扳开(break)它。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3749, 'westway', 'westway/west1', '大官道', '这是一条宽阔笔直的大官道，足可容得下十马并驰。往西通向金城郡，相当于今天的兰州一带，往东则直达大唐国都长安城。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3750, 'westway', 'westway/west2', '大官道', '这是一条宽阔笔直的大官道，足可容得下十马并驰。往西通向金城郡，相当于今天的兰州一带，往东则直达大唐国都长安城。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3751, 'westway', 'westway/west3', '大官道', '这是一条宽阔笔直的大官道，足可容得下十马并驰。往西通向金城郡，西北地区的重要城镇，往东则直达大唐国都长安城。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3752, 'westway', 'westway/yinma', '饮马峪', '走进饮马峪，光线一下子暗了起来。你隐隐约约看见这是一个两端小中间大的葫芦峪，峪谷底传来潺潺的流水声。西北边出了峪口就能去酒泉，东边的峪口外通向平阳道。风乎乎地吹着你，呜呜作响，你又仿佛觉得听见身后总有点什么动静。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (3753, 'westway', 'westway/yongjing', '永靖', '永靖到了。这里是西北的一个不小的镇子，人口比较密集一些。许多去西方取经或去西域长途贩货的车队马队在这里歇脚，东面是一条大道，西南面是绕进山区的平阳道。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3754, 'westway', 'westway/yunti', '云梯冈', '云梯冈位于酒泉的北部，山冈不是很高。南边一条石头小路将山下和山上连接起来，前面山壁上有一个山洞，洞口全是碎石头。往北山路蜿转不定，遥遥可见山势清奇，不知通往何处。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3763, 'wiz', 'wiz/comment', '档案馆', '一间不大的房间，布置得典雅肃穆，四周的文件橱上堆满了各式各样的卷宗。在这里你可以查看(consult)别人对你或其他人物的评价，也可以写下(comment)你对某人的看法。', '0', 'normal', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3764, 'wiz', 'wiz/courthouse', '法院', '这里是审问机器人的法院，你一定是被人检举或是行为太像机器人，才会来到这里，如果你答不出审判官的三个问题，会被做上记号，超过三次的人将会被处以极刑，好好回答吧。', '0', 'normal', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3765, 'city', 'city/entrance', '二楼雅座', '这里摆设讲究，用的餐具都是从景德镇运来。摆的桌椅都是红木的，在光照之下反射出淡淡的光泽。推窗望去，长安城中心尽收眼底。一群酒客推杯换盏，正喝的热闹。', '0', 'normal', 1, 0, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3766, 'wiz', 'wiz/gongtang', '公堂', '开封府大堂。这里威武堂皇，大堂两侧站着两列手持红木棍的衙役，一个个膀大腰粗，满脸横肉。正面高悬一匾：公正无私。匾下案后定坐一位黑脸官员，一双眼睛严厉无比，直似要看到你心里去了。你不由得双腿发软，浑身嗦嗦直抖。', '0', 'normal', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3767, 'wiz', 'wiz/guest', '迎客厅', '对不起，您的地址在西游记的信誉被别人破坏了，为了保证包括您在内的大多数玩家能够愉快地游戏，我们不得不限制从您的网络ＩＰ地址的连线。请您在客厅稍候或电邮联系巫师(流年_辣椒酱)，西游记巫师会尽快作出相应处理。同时，您可以阅读帮助文件(help)或游戏故事(story)。', '0', 'normal', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3768, 'wiz', 'wiz/init', '欢迎光临西游记！', '', '0', 'normal', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3769, 'wiz', 'wiz/jobroom', '工作进度简报室', '这里是巫师们报告自己工作进度的简报室，同时也是大巫师抓公差的根据，如果你有工作做，最好常常到这里更新你的工作进度，如果太久没有看到你的工作进度报告，大巫师们会以为以没事做而指派工作给，要是你仍然不理，也有可能会被假设成已经放弃巫师的工作而降回玩家身分。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3770, 'wiz', 'wiz/menpai', '招贤馆', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3771, 'wiz', 'wiz/menpai_room', '门派讨论室', '这里是供西游记巫师们讨论门派发展平衡等各种问题的。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3773, 'wiz', 'wiz/punish', '死牢', '进了这里，你活下来的希望已经很小了。', '0', 'normal', 1, 1, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3774, 'wiz', 'wiz/sleeveroom', 'Sleeve Room', '', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3775, 'city', 'city/system', '系统公告室', '这是一间很普通的房间，房内贴着一些有关这个世界的资讯。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3776, 'wiz', 'wiz/wizroom', '巫师会议厅', '这里是巫师聊天讨论的地方，如果巫师们要开会的话，也多半会选在这里举行。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3777, 'xueshan', 'xueshan/bingchuan', '冰川', '等上了冰川，你才觉得世界在你脚下又拔高了一层。放眼望去，一面是延绵不尽的雪峰，但此时都好像到了你的脚下。一面是浩翰无垠的冰原，如大海中的波涛一样起伏在你的面前。而几条巨大的冰缝也在冰原中穿行，深不可测地等待着失足的旅人。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3778, 'xueshan', 'xueshan/binggu', '雪山从中', '你信步到了一处高山丛中。但见山势险峻，抬头望不到山顶。待向上攀援时，天候骤寒，铅云低压，北风渐紧，接著天空竟飘下一片片的雪花。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3779, 'xueshan', 'xueshan/binggukou', '冰谷口', '这里突然出现了一道深谷。向下只能看到一段刀削斧劈似的冰崖，在往下则是雪雾缭绕，什么也看不清了。不故谷底似乎有一股炊烟的香味飘了上来，在冰天雪地中挣扎求生的你不禁有点砰然心动。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3780, 'xueshan', 'xueshan/bingya-up1', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3781, 'xueshan', 'xueshan/bingya-up2', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3782, 'xueshan', 'xueshan/bingya-up3', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3783, 'xueshan', 'xueshan/bingya-up4', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3784, 'xueshan', 'xueshan/bingya-up5', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3785, 'xueshan', 'xueshan/bingya-up6', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3786, 'xueshan', 'xueshan/bingya-up7', '冰崖上', '你趴在冰崖上，当真是小心翼翼。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3787, 'xueshan', 'xueshan/boyroom', '男弟子卧房', '雪山派的男弟子卧房。陈设相当简陋，连张床都没有。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3788, 'xueshan', 'xueshan/chufang', '厨房', '这里是雪山派的厨房。雪山弟子性格凶残者极多，常将所获之物生吞活剥。所以这里经常不开灶，屋子角落处摆着一口大铁锅(guo)，是雪山弟子作汤用的，旁边还有一个白瓷盆(pen)。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3789, 'xueshan', 'xueshan/dixiashi', '地下室', '的确没想到小木屋底下居然还有这么一间布置精巧的地下室。这里也跟上面一样，三面靠墙摆满了大大小小的花盆，里面种着各式各样叫不上名子的花草。另一面则是一张看起来相当舒适的床铺，上面躺着一位看起来三四十岁的中年人。他的脸在壁灯灯光下显得阴晴不定，有些说不出的诡异。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3790, 'xueshan', 'xueshan/eroad1', '冰崖底', '这里是冰崖底下。冰谷中别的地方基本上寸草不生。这里却从冰缝中钻出几株小草(xiaocao)，这种草叶尖圆润，色泽幽蓝，看起来不象能在这绝地酷寒中生长的样子。再往东去可以见到一座不大的小木房。北面则见冰宫在冰雪映照下奕奕生光。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3791, 'xueshan', 'xueshan/eroad2', '小木屋外', '很难想象这些木头是从哪里来的。但是这里的确是一间小木屋。周围是一道冰制的围墙，也不过半人来高。围墙入口出站着一位身披白袍，腰跨弯刀的男子。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3792, 'xueshan', 'xueshan/eroad3', '冰崖底', '冰崖底的拐角处。两段冰崖在此交会，望上看去崖势不是那么险峻了。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3793, 'xueshan', 'xueshan/girlbed', '床上', '床上，睡觉的地方。', 'xueshan', 'normal', 1, 0, 0, 1, 0, NULL, 1, NULL);
INSERT INTO `rooms` VALUES (3794, 'xueshan', 'xueshan/girlroom', '女弟子卧房', '雪山派的女弟子卧房。陈设相当素净。靠墙摆着几张床铺(bed)。', 'xueshan', 'normal', 1, 0, 0, 1, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3795, 'xueshan', 'xueshan/no4-e', '雪岭', '雪岭的尽头有一个小小的洞(cave)，据说里面有一只赤练小蛇，吃了后可以大补，但怎么把它从洞里引出来，可就没几个人知道了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3796, 'xueshan', 'xueshan/no4-enter', '雪岭', '茫茫的山坡上一望无际的白雪，上面落着几对浅浅的足迹，显然能攀援到这一层的雪山弟子，轻功几然十分了得了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3797, 'xueshan', 'xueshan/no4-w1', '雪岭', '茫茫的山坡上一望无际的白雪，上面落着几对浅浅的足迹，显然能攀援到这一层的雪山弟子，轻功几然十分了得了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3798, 'xueshan', 'xueshan/no4-w2', '雪岭', '雪岭上有几处的雪被人翻开了，不知埋(mai)了什么东西进去。传说这附近有百足蜈蚣出没，看来要小心些。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3799, 'xueshan', 'xueshan/no4-wn1', '雪岭', '天空中飘舞的雪花遮住了你的视线，只能隐隐看见前面挂着一张小小的蜘蛛网(net)。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3800, 'xueshan', 'xueshan/no4-wn2', '雪岭', '茫茫的山坡上一望无际的白雪，上面落着几对浅浅的足迹，显然能攀援到这一层的雪山弟子，轻功几然十分了得了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3801, 'xueshan', 'xueshan/restroom', '休息室', '这里是雪山弟子平时休息的地方。屋中央有一张大石桌，上面摆着一些水果点心。边上还有两个里间。其中靠南的一间门上挂着一张牌子(paizi)。而墙上则乱七八糟地写满了字。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3802, 'xueshan', 'xueshan/shanpo', '山坡', '这里便是雪山弟子平日起居的处所了，地上积了厚厚的雪，而往来的雪山弟子从不感到严寒。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3803, 'xueshan', 'xueshan/shanpohou', '山坡后', '大雪山轻功冠绝天下。各代师傅为了让弟子刻苦练习轻功，将冰谷四周的门尽数关闭，弟子须凭非凡轻功才可飞跃出谷，却不知哪个爱偷懒的徒弟在这拴了条绳子(rope)，嘿嘿，看来有捷径了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3804, 'xueshan', 'xueshan/snowmaze1', '雪海孤旅', '北风呼啸，飞雪茫茫，四面望去均是绵延不尽的雪峰。天地之间似已毫无生迹，除了雪还是雪。不过让你惊奇不已的是前面居然还有两串脚印，虽然都快淡得看不出来了，毕竟是人的脚印。你不由得一阵狂喜，不顾一切地追了上去。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3805, 'xueshan', 'xueshan/snowmaze2', '雪海孤旅', '北风呼啸，飞雪茫茫，四面望去均是绵延不尽的雪峰。天地之间似已毫无生迹，除了雪还是雪。不过让你惊奇不已的是前面居然还有两串脚印，虽然都快淡得看不出来了，毕竟是人的脚印。你不由得一阵狂喜，不顾一切地追了上去。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
