INSERT INTO `rooms` VALUES (3813, 'xueshan', 'xueshan/wroad1', '冰崖底', '看样子前面是过不去了。往西的路被一块大牌子堵死。牌子上用醒目的大字写着：“冰谷禁地，擅闯者死！”。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3814, 'xueshan', 'xueshan/wuchang-c', '中心武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。东面的一栋房子顶上一股炊烟冉冉升起，想必是厨房了。西面是雪山弟子的休息处。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3815, 'xueshan', 'xueshan/wuchang-e', '东武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
