INSERT INTO `rooms` VALUES (3818, 'xueshan', 'xueshan/wuchang-nw', '西北武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。东面的一栋房子顶上一股炊烟冉冉升起，想必是厨房了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3819, 'xueshan', 'xueshan/wuchang-s', '南武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3820, 'xueshan', 'xueshan/wuchang-se', '东南武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3821, 'xueshan', 'xueshan/wuchang-sw', '西南武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3822, 'xueshan', 'xueshan/wuchang-w', '西武场', '这是冰宫前的一块平地，供大雪山弟子练功之用。冰面极平，光鉴照人。不过走在上面得小心点，雪山弟子也正是借此锻炼下盘的稳固功夫。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3823, 'xueshan', 'xueshan/xiaomuwu', '小木屋', '走进这间小木屋，你又吃了一惊。这里居然暖烘烘的，跟外面的冰天雪地仿佛是两个世界。屋内靠墙摆着一圈大大小小的花盆，里面种着各式各样叫不上名子的花草。屋里很安静，只有一位绝色女子正对着火炉发呆。看到你进来，惊讶地啊了一声，然后又继续发呆。', 'xuesan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3824, 'xueshan', 'xueshan/xihai', '西海之畔', '见惯了一望无际的雪原，巍峨雄伟的冰山，突然间碧波万顷，浩瀚壮阔的水面展现在面前，你顿时觉得一股柔情蜜意涌上心头。山，湖，草，鸟，仿佛是到了另一个世界。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3825, 'xueshan', 'xueshan/xuejie-2', '雪阶', '路又到了尽头，翻(jump)过前面的石壁(shi bi)就可进入雪山的第三重山了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3826, 'xueshan', 'xueshan/xuejie-3', '雪阶', '路又到了尽头，翻(jump)过前面的石壁(shi bi)就可进入雪山的第三重山了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3827, 'xueshan', 'xueshan/xuejie', '雪阶', '上山的路到这里断了，前面是一座石壁(shi bi)，石壁并不甚高，看来跳(jump)上去并不困难。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3828, 'xueshan', 'xueshan/xuelu', '雪路', '茫茫雪野中，远方凝立着一人，手持利刃，威风凛凛，大概便是雪山派负责迎客的掌门大师兄了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3829, 'xueshan', 'xueshan/xuelu1', '雪路', '前面的路已完全弥漫在满天飞雪之中，雪下得一发大了，足底溜滑，道路更是难於辨认，若是踏一个空，势必掉在万仞深谷中跌得粉身碎骨。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3830, 'xueshan', 'xueshan/xuelu2', '雪路', '前面的路已完全弥漫在满天飞雪之中，雪下得一发大了，足底溜滑，道路更是难於辨认，若是踏一个空，势必掉在万仞深谷中跌得粉身碎骨。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3831, 'xueshan', 'xueshan/xueshan1', '茫茫雪峰', '北风呼啸，飞雪茫茫，四面望去均是绵延不尽的雪峰。天地之间似已毫无生迹，除了雪还是雪。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3832, 'xueshan', 'xueshan/xueshan2', '茫茫雪峰', '北风呼啸，飞雪茫茫。西北两面望去均是绵延不尽的雪峰，再往前走便要将生迹抛在身后了。东南方向亦是群山起伏，只是冰雪已部分消融，要走出大雪山是成功在望了。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3833, 'xueshan', 'xueshan/xueshan3', '茫茫雪峰', '北风呼啸，飞雪茫茫，四面望去均是绵延不尽的雪峰。天地之间似已毫无生迹，除了雪还是雪。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3834, 'xueshan', 'xueshan/xueshan4', '茫茫雪峰', '北风呼啸，飞雪茫茫，四面望去均是绵延不尽的雪峰。天地之间似已毫无生迹，除了雪还是雪。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3835, 'xueshan', 'xueshan/xueshan5', '茫茫雪峰', '绵延的山势在此似乎变得平坦起来，四周仍是白雪茫茫，只是北风已不是那么肆虐。环绕的群山在西面打开了一道缺口，而一股细微的暖意正断断续续地飘来。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3836, 'xueshan', 'xueshan/xueshan6', '茫茫雪峰', '北风呼啸，飞雪茫茫。北面不远一条巨大的冰川横贯东西，阻断了你的视线。天地之间除了你自己似乎再无别的生迹。', 'xueshan', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3837, 'xueshan', 'xueshan/zhuwang', '蜘蛛网内', '密密麻麻的蛛网遮住的你的视线，你只能看见对面一只五彩蜘蛛抡着巨大的八只爪子向你爬来。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3846, 'moon/quest/npc', 'moon/quest/npc/road', '羊肠小道', '一条蜿蜒曲折的小径，两边都是刀削般的峭壁。路旁长满了一人多高的野草，据说常有妖怪精灵出没。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3847, 'fabao', 'hululu_inside', '紫金红葫芦内部', '你被吸入了紫金红葫芦中，四周一片混沌，精气被不断吸食...', NULL, 'fabao_container', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3848, 'fabao', 'pingreal_inside', '羊脂玉净瓶内部', '你被吸入了羊脂玉净瓶中，四周净水流转，意识逐渐模糊...', NULL, 'fabao_container', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3849, 'fabao', 'shengreal_bind', '被幌金绳束缚', '一条金绳将你紧紧缠绕，动弹不得，只能等待绳子松开...', NULL, 'fabao_container', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (3850, 'city', 'city/shaizi-room2', '大唐交易所', '交易所里面非常宽敞，空气中弥漫着沉重的烟雾气味。赌场里除了骰子玩法，还有各种赌场游戏。这里多是精神紧张、眼神炯炯、神情沉重的赌客。有一些比较高档的赌客，他们通常会下更大的赌注。', '0', 'normal', 1, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4039, 'qujing/wudidong', 'qujing/wudidong/wudidong1', '无底洞入口', '幽深的洞口，寒气逼人，不知通向何方。洞壁上刻着古老的符文，隐隐散发着妖气。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4040, 'qujing/tianzhu', 'qujing/tianzhu/jiedao1', '天竺国街道', '天竺国都城繁华的街道，异域风情的建筑鳞次栉比，商旅往来不绝。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4041, 'heifeng', 'heifeng/heifengdong', '黑风洞', '黑风洞内阴暗潮湿，阵阵妖风从洞深处吹来，令人不寒而栗。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4042, 'gao', 'gao/yunzhan', '云栈洞', '云栈洞隐于山间云雾之中，洞口藤萝密布，洞内宽敞明亮。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4043, 'liusha', 'liusha/liushahe', '流沙河', '流沙河波涛汹涌，河中暗流涌动，无人能渡。岸边的石碑上刻着古老的文字。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (4045, 'shuangcha', 'shuangcha/shuangchaling', '双叉岭', '双叉岭山势险峻，岔路纵横，林中时常传来虎狼之声，行人莫不警惕。', '1', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4046, 'huangfeng', 'huangfeng/huangfengdong', '黄风洞', '黄风洞口黄沙弥漫，狂风呼啸，洞内妖气冲天。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4115, 'qujing', 'baihuling/maze', '迷宫', '这是一个阴暗潮湿的洞穴，四周石壁上长满了青苔。', '0', 'normal', 0, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4116, 'wiz', 'wiz/prison', '监禁室', '这是一间阴暗潮湿的监禁室。四壁由厚重的石块砌成，只有一个小小的窗户透进一丝光线。空气中弥漫着霉味，地上铺着发霉的稻草。这里是违反规则的玩家被关押的地方。', '0', 'prison', 0, 1, 1, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4117, 'qujing', 'qujing/wuzhuang/shenjian', '深涧', '深到看不见涧底，怪了?你是怎么过来的？', '0', 'normal', 0, 0, 0, 0, 1, NULL, 0, 'water');
INSERT INTO `rooms` VALUES (4118, 'qujing', 'qujing/wuzhuang/pool', '荷花塘', '塘中碧莲相结，荷香扑面而来。怪了?你是怎么过来的？', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4119, 'qujing', 'qujing/wuzhuang/zhu1', '竹林', '你走进一片竹林，密密匝匝看之不透,还是回去吧。', '0', 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4120, 'qujing', 'qujing/wuzhuang/song1', '松海', '你走进一片松海，但闻松涛阵阵不绝。你看够了风景就走回去吧。', NULL, 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4123, 'xingxiu', 'xingxiu/qinglong', '青龙星宿殿', '东方青龙七宿之殿，星光照耀，气势磅礴。', NULL, 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4124, 'xingxiu', 'xingxiu/xuanwu', '玄武星宿殿', '北方玄武七宿之殿，幽暗深邃，神秘莫测。', NULL, 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4125, 'xingxiu', 'xingxiu/baihu', '白虎星宿殿', '西方白虎七宿之殿，虎啸震天，威严赫赫。', NULL, 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
INSERT INTO `rooms` VALUES (4126, 'xingxiu', 'xingxiu/zhuque', '朱雀星宿殿', '南方朱雀七宿之殿，烈焰环绕，光芒万丈。', NULL, 'normal', 1, 0, 0, 0, 0, NULL, 0, NULL);
