INSERT INTO `shops` VALUES (82, 'hair_shop', '毫毛商店', 'rulaifo', 'qujing', 'qujing/lingshan/daxiong', '出售各种颜色的毫毛，可以用来变化物品。');
INSERT INTO `skill_actions` VALUES (316, 'baihua-zhang', '自在飞花轻似梦', 'baihua-zhang_1', 0, '$N浅浅一笑，一招「自在飞花轻似梦」若有若无地拍向$n的$l', -5, -5, 50, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (317, 'baihua-zhang', '一枝红杏出墙来', 'baihua-zhang_2', 0, '$N身形一顿，似有退意。$n正待反攻，忽见$N纤纤五指，直拂$n双目。正是\"百花掌\"之杀手「一枝红杏出墙来」', -10, -10, 120, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (318, 'baihua-zhang', '人面桃花相映红', 'baihua-zhang_3', 0, '只见$N嫣然一笑，双掌翻飞，一招「人面桃花相映红」当真是妙到毫巅', -20, -20, 70, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (319, 'baihua-zhang', '黄菊枝头生晓寒', 'baihua-zhang_4', 0, '$N纤腰一摆，陡然滑出数尺，右手顺势一招「黄菊枝头生晓寒」往$n的$l拍去', 15, 15, 60, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (320, 'baihua-zhang', '此花开尽更无花', 'baihua-zhang_5', 0, '只见$N双唇紧闭，面色凝重，一招「此花开尽更无花」全力击向$n的$l', 5, 5, 80, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (321, 'bainiao-jian', '春蚕吐丝', 'bainiao-jian_1', 0, '$N将$w展开，每一招都向$n的要害缓缓攻去，仿佛春蚕吐丝一般绵绵不绝', -15, 10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (322, 'bainiao-jian', '迎风掸尘', 'bainiao-jian_2', 0, '只见$N身形轻盈，有若迎风而舞，将$w轻轻扬起，直指$n的$l', -5, -10, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (323, 'bainiao-jian', '老僧揩壁', 'bainiao-jian_3', 0, '$N身形前倾，将$w平推，一招「老僧揩壁」使得极慢，却将$N全身护住', -10, -5, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (324, 'bainiao-jian', '绝弦惊蛇', 'bainiao-jian_4', 0, '$N身形忽转，向后急退，突然间将$w反握，直刺$n的$l。这一招「绝弦惊蛇」完全出乎$n意料', -10, -5, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (325, 'bainiao-jian', '败中求胜', 'bainiao-jian_5', 0, '只见$N身形一晃，使出一招「败中求胜」，将$w倒转，旋转着刺向$n的$l', -5, -5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (326, 'bainiao-jian', '大雪满弓刀', 'bainiao-jian_6', 0, '$N凛然凝立，一式「大雪满弓刀」藏$n的后招无穷变化，让$n无法猜度', -5, -5, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (327, 'bainiao-jian', '鸥鹭忘机', 'bainiao-jian_7', 0, '$N将$w平举，遥遥指向$n，正是雪山派绝学「鸥鹭忘机」的起手式', -15, 5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (328, 'bainiao-jian', '晓风残月', 'bainiao-jian_8', 0, '$N以剑法成名，一招一式皆有出处，一攻一守均有说道。雪山剑法「晓风残月」正是败兵剑法的最后一招', -5, 0, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (329, 'bainiao-jian', '暗影浮动', 'bainiao-jian_9', 0, '只见$N平平挥出$w，动作极缓，突然向$n发难。$w直指$n的$l，一招「暗影浮动」浑然天成', -20, 10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (330, 'bainiao-jian', '梅雪争春', 'bainiao-jian_10', 0, '只见$N以十式攻十一式，第十一式正是败兵剑法的第十一式。雪山派梅雪争春的典故由来已久', -5, -5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (331, 'bainiao-jian', '乱石崩云', 'bainiao-jian_11', 0, '$N忽然变色，忽进忽退，身形极快，而$w却稳稳地缓缓刺出。雪山派乱石崩云正是以柔克刚', -5, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (332, 'bainiao-jian', '壮士洗脸', 'bainiao-jian_12', 0, '$N轻轻一笑，身形游走，忽然一招「壮士洗脸」去势极快，虽然轻柔却暗藏极大的劲力，直击$n的$l', -10, 0, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (333, 'bawang-qiang', '', 'bawang-qiang_1', 0, '$N使一招「迎门三不过」，手中$w连续刺向$n面门，哽嗓，前心', 5, -10, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (334, 'bawang-qiang', '', 'bawang-qiang_2', 0, '$N运足精神，抖起$w，一招「拨草寻蛇」刺向$n$l', 15, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (335, 'bawang-qiang', '', 'bawang-qiang_3', 0, '$N一个跨步，使一招「高山流水」，手中$w势若飞瀑刺向$n的$l', 20, -10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (336, 'bawang-qiang', '', 'bawang-qiang_4', 0, '$N一按枪把，啪！地一声抖出五朵枪花。上下左右，虚虚实实刺向$n全身要害', -10, -5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (337, 'bawang-qiang', '', 'bawang-qiang_5', 0, '只见$N一个斜跨，使个「举火烧天势」，手中$w带出一道寒气，由下而上疾挑$n$l', 20, 0, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (338, 'bawang-qiang', '', 'bawang-qiang_6', 0, '只见$N手腕一翻，手中$w从意想不到的角度刺向$n的$l。这一招「灵蛇出洞」快若闪电，毒辣无比', 5, -25, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (339, 'bawang-qiang', '', 'bawang-qiang_7', 0, '$N使个「飞鸟投林势」，身形斜飞，从侧面突出一枪，径刺$n$l', 15, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (340, 'bawang-qiang', '', 'bawang-qiang_8', 0, '$N似欲退走，可是忽地一个转身，百忙中使出一招「回马枪」，$w一挺刺向$n$l', 10, -20, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (341, 'bingpo-blade', '无', 'bingpo-blade_1', 0, '$N轻抚手中的$w，突然间只见刀光一闪，再闪，又一闪！三道刺骨的寒气已然袭上了$n的$l', -15, 5, 15, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (342, 'bingpo-blade', '无', 'bingpo-blade_2', 0, '只见$N倒提$w，身形急冲，就在与$n错身之际，突然反手一刀从$n后脑斜劈而下', -15, 5, 20, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (343, 'bingpo-blade', '无', 'bingpo-blade_3', 0, '$N斜身飞起，带出一片匹练也似的刀光卷向$n的$l', -15, 5, 15, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (344, 'bingpo-blade', '无', 'bingpo-blade_4', 0, '$N突然一脚踢出，手中的$w划出一道轻妙的圆弧，淡淡的刀光封住了$n的头脸，切断了$n的呼吸', -15, 5, 20, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (345, 'bingpo-blade', '千里冰封', 'bingpo-blade_5', 0, '只见$N脸色一寒，一招「千里冰封」使出，从眉捷到脚跟，$n周身的血液都似被这无尽的刀势冻住，而生命也仿佛要离体而去', -15, 5, 30, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (346, 'bingpo-blade', '无', 'bingpo-blade_6', 0, '$N刀势渐慢，而$w上带出的寒气却越来越浓。就在这时，$n的心头一紧，一道比针尖还要锐利的寒气已刺上了$n$l', -15, 5, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (347, 'bingpo-blade', '无', 'bingpo-blade_7', 0, '$N也不管三七二十一，高举$w呼！地就是一刀向$n迎面斩下！虽然只有一刀，可怕的刀势却似万古不化的寒冰封死了$n的一切退路', -15, 5, 20, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (348, 'changquan', '', 'changquan_1', 0, '只见$N身形一矮，大喝声中一个「冲天炮」对准$n的鼻子呼！地砸了过去', 5, 5, 90, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (349, 'changquan', '', 'changquan_2', 0, '$N左手一分，右拳运气，一招「拔草寻蛇」便往$n的$l招呼过去', 5, 5, 60, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (350, 'changquan', '', 'changquan_3', 0, '$N右拳在$n面门一晃，左掌使了个「叶底偷桃」往$n的$l狠命一抓', 5, 5, 60, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (351, 'changquan', '', 'changquan_4', 0, '$N步履一沉，左拳拉开，右拳带风，一招「黑虎掏心」势不可挡地击向$n$l', 5, 5, 80, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (352, 'changquan', '', 'changquan_5', 0, '只见$N拉开架式，一招「双风贯耳」使得虎虎有风。底下却飞起一脚踢向$n$l', 5, 5, 70, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (353, 'changquan', '', 'changquan_6', 0, '$N打得兴起，大喝一声：看我这招「龙虎相交」！左手往$n身后一抄，右拳便往$n面门砸了过去', 5, 5, 120, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (354, 'changquan', '', 'changquan_7', 0, '$N拉开后弓步，双掌使了个「如封似闭」往$n的$l一推', 5, 5, 50, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (355, 'changquan', '', 'changquan_8', 0, '只见$N运足气力，一连三拳击向$n$l，力道一拳高过一拳！这一招的名字还相当高雅，叫作「阳关三叠」', 5, 5, 80, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (356, 'changquan', '', 'changquan_9', 0, '$N往后一纵，就势使了个「老树盘根」，右腿扫向$n的$l', 5, 5, 50, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (357, 'changquan', '', 'changquan_10', 0, '$N一个转身，左掌护胸，右掌反手使了个「独劈华山」往$n当头一劈', 5, 5, 90, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (358, 'changquan', '', 'changquan_11', 0, '$N飞身跃起，半空中一脚踢向$n面门，却是个虚招。说时迟那时快，只见$N一个倒翻，双掌已到了$n的$l', 5, 5, 100, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (359, 'cloudstaff', '天光乍现', 'cloudstaff_1', 0, '$N使一招「天光乍现」，手中$w扫向$n下盘！', 0, 0, 20, '挫伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (360, 'cloudstaff', '雨后初晴', 'cloudstaff_2', 0, '$N挥起$w，一招「雨后初晴」攻向$n$l！', 0, 0, 20, '挫伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (361, 'cloudstaff', '浮云写意', 'cloudstaff_3', 0, '$N横过手中$w，使出「浮云写意」击向$n$l！', 0, 0, 20, '挫伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (362, 'cloudstaff', '游龙穿云', 'cloudstaff_4', 0, '$N使出一招「游龙穿云」，$w一挺撞向$n$l！', 0, 0, 20, '挫伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (363, 'cuixin-zhang', '', 'cuixin-zhang_1', 0, '只见$N凝神运气，左手护胸，右手掌心呈暗红，带着一股腥热之气拍向$n$l', -5, -5, 80, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (364, 'cuixin-zhang', '', 'cuixin-zhang_2', 0, '$N脚下连换几个方位，双掌一错，右手突然暴涨数尺往$n$l一搭一推', -25, -25, 70, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (365, 'cuixin-zhang', '', 'cuixin-zhang_3', 0, '$N身形一滚，一脚凌空踢出，并不攻敌。左掌却在这一带之下从意想不到的角度拍上了$n的$l', -5, -5, 60, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (366, 'cuixin-zhang', '', 'cuixin-zhang_4', 0, '$N嘿嘿一笑，双掌在空气中划得嗤嗤着响！劲气纵横中突然飞出一掌，悄无声息地拍向$n$l', 5, 5, 100, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (367, 'cuixin-zhang', '', 'cuixin-zhang_5', 0, '$N轻轻一纵，与$n错身而过。便在这时，$N的手臂就象没长骨头似的往外一曲，快若闪电地击上了$n$l', -5, -5, 90, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (368, 'cuixin-zhang', '', 'cuixin-zhang_6', 0, '$N接连几个急转，身形如陀螺般向$n滚去，转一圈击一掌，掌掌不离$n的$l', 5, 5, 60, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (369, 'cuixin-zhang', '', 'cuixin-zhang_7', 0, '只听$N一声清啸，身形如流水，掌势若浮云，暗光流转中延绵不绝地拍向$n周身要害', 5, 5, 80, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (370, 'cuixin-zhang', '', 'cuixin-zhang_8', 0, '$N往后一纵，就势使了扫堂腿，双掌却借机反卷而上，长驱直入地击向$n$l', -5, -5, 60, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (371, 'dali-bang', '六丁开山', 'dali-bang_1', 0, '$N发出一声厉叫，手中$w以一招「六丁开山」，带着呼呼风声向$n的$l砸去', 10, -10, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (372, 'dali-bang', '混沌初破', 'dali-bang_2', 0, '$N身形一转，一招「混沌初破」使出，周围丈内土石乱飞，\n霹雳间$w已砸向$n的$l，躲也躲不开了', 15, -20, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (373, 'dali-bang', '翻江搅海', 'dali-bang_3', 0, '$N舞动$w，一式「翻江搅海」，劈头盖脸的向$n的$l砸去', 15, 0, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (374, 'dali-bang', '八方风雨', 'dali-bang_4', 0, '$N舞动$w，使出「八方风雨」，幻出了无数$w向$n砸去', 0, -10, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (375, 'dragonfight', '飞龙在天', 'dragonfight_1', 0, '$N纵身跃起，一招「飞龙在天」，双掌以排山倒海之势击向$n的$l', -10, -10, 100, '瘀伤', '只听见「锵」一声，被$N劈手格开', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (376, 'dragonfight', '无', 'dragonfight_2', 0, '$N似退反进，突然欺身向前，五指如钩，对准$n的$l一把抓了过去', 10, -20, 100, '抓伤', '只听见「锵」一声，被$N劈手格开', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (377, 'dragonfight', '神龙摆尾', 'dragonfight_3', 0, '只见$N一旋身，双腿如铁棍一般扫向$n。这一招「神龙摆尾」当真是防不胜防', -10, -20, 120, '砸伤', '只听见「锵」一声，被$N劈手格开', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (378, 'dragonfight', '龙战于野', 'dragonfight_4', 0, '$N忽发龙吟，使出一招「龙战于野」，啸声中和身而上，向$n直撞而来', 10, -10, 100, '撞伤', '只听见「锵」一声，被$N劈手格开', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (379, 'dragonfight', '龙腾四海', 'dragonfight_5', 0, '只见$N一个筋斗翻在半空，一招「龙腾四海」将发未发，但是全身劲气疾卷$n', 0, -20, 120, '内伤', '只听见「锵」一声，被$N劈手格开', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (380, 'dragonfight', '苍龙出海', 'dragonfight_6', 0, '$N身形一长，朝$n劈面就是一拳。这招「苍龙出海」势若奔雷，锐利无比', 10, -30, 180, '瘀伤', '只听见「锵」一声，被$N劈手格开', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (381, 'fengbo-cha', '「昔人已乘黄鹤去」', 'fengbo-cha_1', 0, '$N似乎在寻找些什么，手中$w在身前试探了数叉。叉尖所指之处，正是$n的$l，原来是「昔人已乘黄鹤去」', 0, 0, 25, '戳伤', '$n挥动$W，在身前画了个半圆，正好挡开$N的攻势。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (382, 'fengbo-cha', '「此地空余黄鹤楼」', 'fengbo-cha_2', 0, '$N身形不动，手中$w用一招「此地空余黄鹤楼」，拍向$n的$l。这招似乎颇为窒滞生硬，但毫不拖泥带水，攻势甚是凌厉', 0, 0, 25, '瘀伤', '$n丝毫不为所动，轻描淡写地挥叉一刺，逼得$N回手自防。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (383, 'fengbo-cha', '「黄鹤一去不复返」', 'fengbo-cha_3', 0, '$N接连几个起落，作势欲走，$n忙疾追不迭。正在这时，$N于空中突然回身，一式「黄鹤一去不复返」直指$n的$l', -10, -10, 25, '刺伤', '$n一抖手中$W，在$N兵器上一按，借势纵开数丈。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (384, 'fengbo-cha', '「白云千载空悠悠」', 'fengbo-cha_4', 0, '$N一声清啸，但见漫天叉影，化作朵朵白云，扰得$n眼花缭乱这招「白云千载空悠悠」颇为传神', -10, -10, 25, '瘀伤', '$n将$W舞得风雨不透，$N无奈之下只好换招。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (385, 'fengbo-cha', '「晴川沥沥汉阳树」', 'fengbo-cha_5', 0, '$N手中$w一颤，用一招「晴川沥沥汉阳树」，迅捷无比地在$n上下左右各刺一叉', 0, -10, 25, '刺伤', '$n以手中$W画了个圆弧，将周身破绽都封死了。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (386, 'fengbo-cha', '「芳草凄凄鹦鹉洲」', 'fengbo-cha_6', 0, '$N施出一招「芳草凄凄鹦鹉洲」，只见$w若有若无地一探，去向势似乎刺向$n左侧数寸处，但不知怎的，转瞬间叉尖已到了$l', 0, -10, 25, '戳伤', '$n怯生生地举叉一挡，似乎力不从心。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (387, 'fengbo-cha', '「日暮乡关何处去」', 'fengbo-cha_7', 0, '$N朗笑一声，手中$w泛出重重暗影，好似一阵阵浓雾，推向$n。$n看不透这招「日暮乡关何处去」的来路', 0, -10, 25, '刺伤', '$n不避不让，挺$W在身前空处连次数叉。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (388, 'fengbo-cha', '「烟波江上使人愁」', 'fengbo-cha_8', 0, '$n刚喘得一喘，却见$N身形一闪，已经踪影全无。$n还未来得及转身，$N的$w已到背后了。这招「烟波江上使人愁」轻快无比', -10, -10, 25, '戳伤', '$n眼见$N攻势凌厉，忙用一招「烟波江上使人愁」，连转数圈。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (389, 'fengbo-cha', '「江上往来人」', 'fengbo-cha_9', 0, '$N怒叱一声，手中$w齐快无比地在$n身前来来回回连划七划。这招「江上往来人」变幻无方', 5, -15, 30, '戳伤', '$n连挥手中$W，只听叮叮当当一阵密响。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (390, 'fengbo-cha', '「但爱鲈鱼美」', 'fengbo-cha_10', 0, '$N手中$w缓缓画了个圆圈，用一招「但爱鲈鱼美」慢慢向$n的$l套去', 5, -5, 35, '戳伤', '$n似乎胸有成竹，挺叉连划数个圆圈。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (391, 'fengbo-cha', '「君看一叶舟」', 'fengbo-cha_11', 0, '$N身形一旋，冲天而起。手中$w借着下冲之势，一招「君看一叶舟」直插$n的$l', 10, -10, 35, '戳伤', '$n看准来势，以$W向$N的兵刃猛点。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (392, 'fengbo-cha', '「出没风波里」', 'fengbo-cha_12', 0, '$N突然脸上青气一显，叉上嗡嗡之声大做，正当$n惊诧时，$N狂风骤雨般连攻五叉。这招「出没风波里」是整套叉法的精髓', -5, -5, 40, '戳伤', '$n不顾自身，手中$W连连刺向$N。这围魏救赵之计果然奏效。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (393, 'fonxansword', '峰回路转', 'fonxansword_1', 0, '$N使一招「峰回路转」，手中$w如一条银蛇般刺向$n的$l', 0, 0, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (394, 'fonxansword', '空山鸟语', 'fonxansword_2', 0, '$N使出封山剑法中的「空山鸟语」，剑光霍霍斩向$n的$l', 0, 0, 30, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (395, 'fonxansword', '御风而行', 'fonxansword_3', 0, '$N使出一招「御风而行」，身形陡然滑出数尺，手中$w斩向$n的$l', 0, 0, 20, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (396, 'fonxansword', '旭日东升', 'fonxansword_4', 0, '$N手中$w中宫直进，一式「旭日东升」对准$n的$l刺出一剑', 0, 0, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (397, 'fonxansword', '金光泻地', 'fonxansword_5', 0, '$N纵身一跃，手中$w一招「金光泻地」对准$n的$l斜斜刺出一剑', 0, 0, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (398, 'fonxansword', '童子引路', 'fonxansword_6', 0, '$N的$w凭空一指，一招「童子引路」刺向$n的$l', 0, 0, 40, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (399, 'fonxansword', '柳暗花明', 'fonxansword_7', 0, '$N手中$w向外一分，使一招「柳暗花明」反手对准$n$l一剑刺去', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (400, 'fonxansword', '空谷秋虹', 'fonxansword_8', 0, '$N横剑上前，身形一转手中$w使一招「空谷秋虹」画出一道光弧斩向$n的$l', 0, 0, 10, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (401, 'fumo-zhang', '', 'fumo-zhang_1', 0, '$N运足力气将$w抡了几个大圆，呼！地一声向$n当头砸下', 15, -5, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (402, 'fumo-zhang', '', 'fumo-zhang_2', 0, '只听$N一声高叫：还不缚手就擒！手中的$w一绞，扫向$n$l', 0, -15, 15, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (403, 'fumo-zhang', '群魔伏首', 'fumo-zhang_3', 0, '$N使出一招「群魔伏首」，手中的$w带出飞沙走石般的杖风压向$n的$l', 5, -5, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (404, 'fumo-zhang', '', 'fumo-zhang_4', 0, '只见$N略略一退，旋即一个跨步，$w划出一道弧光刺向$n$l', 5, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (405, 'fumo-zhang', '', 'fumo-zhang_5', 0, '$N横持$w，暗运真气，忽然间只见杖头一跳，灵蛇般钻向$n的$l', -5, 0, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (406, 'fumo-zhang', '', 'fumo-zhang_6', 0, '$N的$w望上一挑，中途却使了个巧劲，杖尾嗖！地一翻，砸向$n$l', -5, -10, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (407, 'hellfire-whip', '地狱烈火', 'hellfire-whip_1', 0, '$N手腕一翻，$w抖得笔直，带出一股锐啸猛刺$n$l', 0, -5, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (408, 'hellfire-whip', '地狱烈火', 'hellfire-whip_2', 0, '$N大喝一声，手中$w宛若矫龙飞在半空，大有「横空出世」的气概。$n只觉得全身俱在$w笼罩之下', -20, -20, 30, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (409, 'hellfire-whip', '地狱烈火', 'hellfire-whip_3', 0, '$N右手一引，$w贴地而飞，再疾卷而上，仿佛带出了地狱中的烈火，夹头夹脑地扑向$n', -5, -15, 25, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (410, 'hellfire-whip', '地狱烈火', 'hellfire-whip_4', 0, '也不知$N如何动了一动，但见长空中青光一闪，$n只觉$w已击上了$l', -15, -5, 15, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (411, 'hellfire-whip', '地狱烈火', 'hellfire-whip_5', 0, '$N身形往前滑出，手中$w霹啪有声，一圈套一圈地卷向$n', -5, 0, 15, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (412, 'hellfire-whip', '地狱烈火', 'hellfire-whip_6', 0, '长笑声中$N一个倒翻，手中$w急绞，但见方圆丈许飞沙走石，劲气纵横！$n不知如何才能脱困而出，脸都绿了', -15, -20, 25, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (413, 'hellfire-whip', '小楼夜哭', 'hellfire-whip_7', 0, '$N喉咙里发出几声嚎叫，高举$w，不顾一切地冲向$n，几乎与$n贴脸而立！手中$w却悄无声息地刺向$n的$l，好厉害的「小楼夜哭」', -15, -15, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (414, 'hellfire-whip', '饿鬼拦路', 'hellfire-whip_8', 0, '$N手中$w一抖，幻出几许银光，就在一恍惚间，$w已斜斜地点上了$n的$l', -10, -10, 30, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (415, 'huaxue-blade', '', 'huaxue-blade_1', 0, '$N斜步飞身向上，手中$w迎风一晃，闪电般劈向$n的后脑', 0, -20, 25, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (416, 'huaxue-blade', '', 'huaxue-blade_2', 0, '$N缩身一个滚翻，$w随身而走，悄无声息地劈向$n的双脚', -10, 0, 25, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (417, 'huaxue-blade', '', 'huaxue-blade_3', 0, '$N双手一振，$w突发血光，「哗，哗，哗」一连三刀向$n刺去', 5, -15, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (418, 'huaxue-blade', '', 'huaxue-blade_4', 0, '$N脸上突然紫气大做，手中$w挟着一股血腥劈向$n的$l', 5, -5, 30, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (419, 'huntian-hammer', '', 'huntian-hammer_1', 0, '$N手中$w一转，卷着一股强劲的风力挥向$n的$l，这一下又急又猛，势大力狠，眼见就到了$n身前', 10, -10, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (420, 'huntian-hammer', '', 'huntian-hammer_2', 0, '$N双手一震，手中$w夹带着闷雷般的响声，劈头盖脸地就向$n砸了过去', 15, -15, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (421, 'huntian-hammer', '', 'huntian-hammer_3', 0, '$N将$w高举过肩，蓄紧力发，对准$n的$l发出雷霆一击', 20, -20, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (422, 'huntian-hammer', '', 'huntian-hammer_4', 0, '$N身走轻灵，手中$w忽上忽下，令人捉摸不清去路，就在$n一恍惚间，\"唰\"地砸向$n的$l', 0, -10, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (423, 'huntian-hammer', '', 'huntian-hammer_5', 0, '$N趁与$n错身之机，倒转$w，锤把戳向了$n，这一下如白蛇吐芯，悄无声息的点上了$n的$l', 10, -10, 20, '戳伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (424, 'huntian-hammer', '', 'huntian-hammer_6', 0, '$N紧握$w猛挥了个大圆，卷的周身长内沙土尘扬，趁$n不能辨物之时，手中$w斜斜地砸向$n的$l', 20, -25, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (425, 'huoyun-qiang', '', 'huoyun-qiang_1', 0, '$N大吼一声，手中$w微扬，一招「风起云涌」，霎时枪影如封墙，有若旎转钢刀般挟以万钧之势封向$n', 5, -10, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (426, 'huoyun-qiang', '', 'huoyun-qiang_2', 0, '$N反身一弹，重重枪影先将敌人身形罩住，而后一招「覆雨翻云」，只见寒芒一闪，$w己闪电般射向$n', 15, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (427, 'huoyun-qiang', '', 'huoyun-qiang_3', 0, '$N使出「火龙腾云」，七道红芒一经泛出有若苍鹰猎兔以雷霆万钧之势，快愈飘风的刺向$n', 20, -10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (428, 'huoyun-qiang', '', 'huoyun-qiang_4', 0, '$N$w指地，身形半曲，使出一招「浴火凤凰」，往前射去，只见一道红芒掠过，人枪如流星似的划过空间，冲向$n', -10, -5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (429, 'huoyun-qiang', '', 'huoyun-qiang_5', 0, '$N微一反身，己使出「天火燎原」，舞出万朵火花，只见红光闪闪，$n被罩入一片红光之中', 20, 0, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (430, 'huoyun-qiang', '', 'huoyun-qiang_6', 0, '$N狂喝一声，$w己泛起一道红芒，只见狂风大作，$N枪势一带，这招「火云敝日」摧枯拉朽，击向$n', 5, -25, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (431, 'huoyun-qiang', '', 'huoyun-qiang_7', 0, '$N$w一抖，枪影满天，$n顿时被罩在这招「晚霞满天」的一片火光之中', 15, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (432, 'huoyun-qiang', '', 'huoyun-qiang_8', 0, '$N$w一抖，向$n脚下磋来，搅起一片尘土，这招「火烧连营」逼得$n连连后退，无处落脚', 10, -20, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (433, 'jadesword', '「五马分尸」', 'jadesword_1', 0, '$N手腕一抖，$w剑尖化为五道白光，分别向$n的咽喉、左右肩、和左右脚腕疾刺', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (434, 'jadesword', '「六亲不认」', 'jadesword_2', 0, '$N关节僵硬，手中$w如一根树干一般横竖乱扫。\\n\n$n识得这招「六亲不认」的威力，连忙躲避不迭', 10, -20, 30, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (435, 'jadesword', '「七窍生烟」', 'jadesword_3', 0, '$N纵身跃起，手中$w带起万道银光，向$n的面门点去。\\n\n这招「七窍生烟」果然把$n逼得手忙脚乱', 5, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (436, 'jadesword', '「八方风雨」', 'jadesword_4', 0, '$N奋不顾身，手中$w如狂风暴雨般向$n乱劈！\\n\n这招「八方风雨」虽然露出若干空门，但$n也不敢不顾自身安危而贸然进攻', 5, -5, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (437, 'jadesword', '「九死一生」', 'jadesword_5', 0, '$N连人带剑猛扑向$n的$l。若是这招「九死一生」\n击不中$n，$N本人就空门大开，任人宰割了', 10, -10, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (438, 'jadesword', '「十面埋伏」', 'jadesword_6', 0, '$N身随剑走，迅速无伦地在$n周围兜圈。\\n\n$n只见周围无数人影，随时都有可能有一柄$w从意想不到的\\n\n位置刺来，实在是危机重重', 0, -15, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (439, 'jienan-zhi', '', 'jienan-zhi_1', 0, '$N右手食指和中指并拢，一前一后戳向$n的$l', -5, -5, 70, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (440, 'jienan-zhi', '', 'jienan-zhi_2', 0, '$N左掌虚托，右指穿腋疾出，指向$n的$l', -5, -5, 80, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (441, 'jienan-zhi', '', 'jienan-zhi_3', 0, '只见$N侧身抬臂，右指划了个半圈，击向$n的$l', -5, -5, 60, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (442, 'jienan-zhi', '', 'jienan-zhi_4', 0, '$N身形微侧，右手便拿$n手腕，跟着左手后发先至，攻向$n的$l', -5, -5, 120, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (443, 'jienan-zhi', '', 'jienan-zhi_5', 0, '只见$N身形不动，只是稍稍抬起右手食指，等着$n的$l自行撞上来', -5, -5, 60, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (444, 'jienan-zhi', '', 'jienan-zhi_6', 0, '忽见$N一纵身欺近$n身旁，伸出左手拇指和食指朝$n的$l扣来', -5, -5, 50, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (445, 'jinghun-zhang', '小鬼讨债', 'jinghun-zhang_1', 0, '$N左掌微分，右手一长使出一招「小鬼讨债」，一只惨白的利爪探向$n的$l', 15, 15, 120, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (446, 'jinghun-zhang', '青面缭牙', 'jinghun-zhang_2', 0, '$N倏地一个转身，双手往脸上一抹，现出「青面缭牙」，张口一吹，一股阴风直扑$n', -35, -35, 60, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (447, 'jinghun-zhang', '群魔乱舞', 'jinghun-zhang_3', 0, '$N身子微斜，随即跨出一步，左手忽掌忽爪使出「群魔乱舞」，拍向$n的$l', 5, 5, 80, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (448, 'jinghun-zhang', '鬼影幢幢', 'jinghun-zhang_4', 0, '$N使出「鬼影幢幢」，双手滑溜异常对准$n的$l抓去', -5, -10, 80, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (449, 'jinghun-zhang', '秋坟鬼唱', 'jinghun-zhang_5', 0, '$N左手虚晃，右掌飘飘，掌心呈碧绿，一招「秋坟鬼唱」击向$n$l', 15, 15, 60, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (450, 'jinghun-zhang', '饿鬼拦路', 'jinghun-zhang_6', 0, '$N使出「饿鬼拦路」，凌空跃起，冷不防在落地前对准$n$l踢出一脚', -5, -5, 90, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (451, 'jinghun-zhang', '厉鬼缠身', 'jinghun-zhang_7', 0, '$N右手在$n$l划过，随后一招「厉鬼缠身」左爪又向同一方位抓到', 15, 15, 70, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (452, 'jinglei-mace', '海阔天空', 'jinglei-mace_1', 0, '$N身形促进，手中$w带起一阵劲风，朝$n当头扫去', -5, 5, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (453, 'jinglei-mace', '顶天立地', 'jinglei-mace_2', 0, '$N猛吸一口真气，身形暴长，似乎瞬息间长高了一个头。借此威猛之势，$N手中$w一招「顶天立地」，向$n兜头盖脑地砸去', -5, -15, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (454, 'jinglei-mace', '舌绽春雷', 'jinglei-mace_3', 0, '$N气运丹田，一声怒吼，好似平地起了个焦雷，震得$n耳中嗡嗡直响。趁此良机，$N抡起手中$w，砸向$n的$l', -15, -5, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (455, 'jinglei-mace', '乌云密布', 'jinglei-mace_4', 0, '$N把$w舞得风雨不透，慢慢向$n逼去。$n只见一团黑影向自己滚来，实在不知如何招架', 10, -10, 20, '震伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (456, 'jinglei-mace', '电闪雷鸣', 'jinglei-mace_5', 0, '$N将$w抡了个圆圈，隐隐带起风雷之声，好似在找落锏之处。突然间，只见一道寒光闪过，$w已到$n咽喉。好一招「电闪雷鸣」', -10, 0, 25, '戳伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (457, 'jinglei-mace', '八方风雨', 'jinglei-mace_6', 0, '$N用一招「八方风雨」，弓身围$n四周疾转。混乱中只见四面八方都是锏影，似乎已将$n逼入死路', -5, -5, 15, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (458, 'jinglei-mace', '狂风骤雨', 'jinglei-mace_7', 0, '$N有如中了邪，丝毫不顾自身安危，手中$w好似狂风骤雨般击向$n', -10, 5, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (459, 'jinglei-mace', '天公洒泪', 'jinglei-mace_8', 0, '激战中只见一条黑影冲逃邙去。$n一愣，已有无数锏影朝当头砸到。$N的「天公洒泪」用的恰到好处，端地是鬼神莫测', 0, -15, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (460, 'jinglei-mace', '暴雨滂沱', 'jinglei-mace_9', 0, '$N挺起$w向$n的$l缓缓戳去，显然锏上灌入了内力。突然间，$w一分为三，向$n身上三个不同的部位飞刺！$n被这招「暴雨滂沱」逼得连连后退', -5, -5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (461, 'kaishan-chui', '', 'kaishan-chui_1', 0, '$N哪管三七二十一，举起$w朝着$n当头就是一家伙', 15, -10, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (462, 'kaishan-chui', '', 'kaishan-chui_2', 0, '只见$N眼冒凶光，青筋凸起，抄起$w就朝$n的$l狠命扫了过去', 10, -15, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (463, 'kaishan-chui', '', 'kaishan-chui_3', 0, '只听轰！地一声$N的$w在地上砸得尘土飞扬！紧接着$N就势翻了个跟头，又是一下向$n砸了过去', 5, -10, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (464, 'kaishan-chui', '', 'kaishan-chui_4', 0, '只见$N稍一运气，手中的$w上中下连扫三圈，逼得$n连退不迭', 5, 0, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (465, 'kaishan-chui', '五丁开山', 'kaishan-chui_5', 0, '$N使出了一招「五丁开山」，手中的$w举重若轻，势若疯虎地向$n$l连连砸去', 5, 0, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (466, 'kaishan-chui', '', 'kaishan-chui_6', 0, '但见$N一个转身，手中$w由下而上一荡，$n只听一阵风声擦耳而过！\\n$n正在暗叫侥幸之时，$N的$w就势一转，又砸了回来', 5, -10, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (467, 'kugu-blade', '尸横遍野', 'kugu-blade_1', 0, '$N在$n四周滚来滚去，手中$w招招不离$n的下盘，这招「尸横遍野」果然奏效，逼得$n手忙脚乱', -10, -15, 20, '砍伤', '$n眼见来势凌厉，忙翻身倒下，顺手以$W将$N向上荡开。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (468, 'kugu-blade', '借尸还魂', 'kugu-blade_2', 0, '激战中，$N忽然将$w收在身旁，直挺挺的倒下。正在$n不知所措之时，$N的$w如毒蛇一般突然向$n的$l飞去，正是一招「借尸还魂」', -15, -10, 20, '戳伤', '$n连忙使一招「借尸还魂」，举$W一挡，借势疾退开去。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (469, 'kugu-blade', '尸山血海', 'kugu-blade_3', 0, '$N左手运起排山倒海的掌力，右手$w舞出夺目的寒光，笼罩住$n的全身', 0, -10, 25, '劈伤', '$n展开$W疾挥，但见漫天刀影，这招「尸山血海」果然将$N的攻势挡了回去。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (470, 'kugu-blade', '毁尸灭迹', 'kugu-blade_4', 0, '$N忽然间脸色苍白，身体软软的消失在黑暗中。$n在激战中突然不见了敌人，惊慌失措间，$N运起了「毁尸灭迹」的半招进攻，一刀向$n的后脑砍去', -10, -10, 25, '砍伤', '$n看准来势，举$W迎去。只听「噗」地一声闷响，$n的人影已不见了。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (471, 'kugu-blade', '马革裹尸', 'kugu-blade_5', 0, '只见$N运起轻功，好似一堵无形的墙壁，向$n徐徐推近。急转中$N忽然一刀砍向$n的$l，好一招「马革裹尸」', -10, 0, 25, '砍伤', '$n原地不动，身子如陀螺般疾转。$N虽然命中，却被$n卸去劲力。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (472, 'kugu-blade', '行尸走肉', 'kugu-blade_6', 0, '$N门户大开，就象丧失了神志一般，自身跟着手中的$w向$n扑去。这招「行尸走肉」虽然凶险，但威力奇大，逼的$n连连倒退', 10, 10, 40, '砍伤', '$n眼见招来，竟然不避不让，以身相迎。只听「噗」地一声，$N的进攻如中败竹，居然对$n毫无影响。', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (473, 'kusang-bang', '凄风长号', 'kusang-bang_1', 0, '$N发出一声厉叫，手中$w以一招「凄风长号」狂风骤雨般地向$n的$l连连扫去', 15, -10, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (474, 'kusang-bang', '怨妇伤情', 'kusang-bang_2', 0, '$N身形一转，面带戚色，一招「怨妇伤情」使出，\\n手中$w好像沾上了$n，甩也甩不开', -15, -20, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (475, 'kusang-bang', '寒夜祭灵', 'kusang-bang_3', 0, '$N舞动$w，咯咯一笑，一招「寒夜祭灵」夹着点点磷光砸向$n的$l', 10, 0, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (476, 'kusang-bang', '荒野求食', 'kusang-bang_4', 0, '$N面露乞怜之色，手中$w却轻轻一抖，一招「荒野求食」阴毒无比地刺向$n$l', -10, -10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (477, 'kusang-bang', '月下独行', 'kusang-bang_5', 0, '$N身形往后一缩，手中$w突然暴长数尺，发出青绿之光，\\n一招「月下独行」带着森森鬼气砸向$n$l', -5, 0, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (478, 'kusang-bang', '小楼夜哭', 'kusang-bang_6', 0, '$N喉咙里发出几声嚎叫，高举$w，不顾一切地冲向$n，几乎与$n贴脸而立！\\n手中$w却悄无声息地刺向$n的$l，好厉害的「小楼夜哭」', -20, -20, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (479, 'kusang-bang', '地狱烈火', 'kusang-bang_7', 0, '$N大喝一声，手中$w宛若矫龙飞在半空，大有「横空出世」的气概。\\n$n只觉得全身俱在$w笼罩之下', -15, -15, 30, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (480, 'kusang-bang', '饿鬼拦路', 'kusang-bang_8', 0, '$N手中$w一抖，幻出几许银光，就在一恍惚间，$w已斜斜地点上了$n的$l', -10, -10, 30, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (481, 'liangyi-sword', '幻', 'liangyi-sword_1', 0, '$N一抖手中的$w，瞬间刺出三十六剑，$n顿时手忙脚乱，分不清虚实', -10, -20, 5, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (482, 'liangyi-sword', '绕', 'liangyi-sword_2', 0, '$N一剑刺向$n，$n急忙向旁边一闪，不料$N一运劲儿，手中的$w突然弯了过来，转而刺向$n的$l', -20, -10, 10, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (483, 'liangyi-sword', '缠', 'liangyi-sword_3', 0, '$N手中$w连续划出几个光环，一阵吸力带得$n向前踏出一步，$N左手剑指已刺向$n的$l', -20, -20, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (484, 'liangyi-sword', '点', 'liangyi-sword_4', 0, '$N一转身，背向$n，手中$w从腋下反手刺向$n的$l', -10, -10, 10, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (485, 'liangyi-sword', '劈', 'liangyi-sword_5', 0, '$N举起手中的$w，自上而下，劈向$n的$l', 0, -10, 25, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (486, 'liangyi-sword', '砍', 'liangyi-sword_6', 0, '$N身子一侧，手中的$w平着挥出，砍向$n的$l', -5, -5, 15, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (487, 'liangyi-sword', '刺', 'liangyi-sword_7', 0, '$N向前踏出半步，手中$w中宫直进，刺向$n的前心', -10, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (488, 'liangyi-sword', '扑', 'liangyi-sword_8', 0, '$N双脚一顿，身子凌空，头下脚上，手中$w刺向$n的头顶', -5, -5, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (489, 'lunhui-zhang', '报应不爽', 'lunhui-zhang_1', 0, '$N口宣佛号，面色庄严，一招「报应不爽」手中$w长驱直入，迳刺$n$l', -10, -5, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (490, 'lunhui-zhang', '大限将至', 'lunhui-zhang_2', 0, '$N手中$w一荡，使出「大限将至」，但见一道杖影隐隐约约，若有若无地向$n压下', 15, -15, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (491, 'lunhui-zhang', '回头是岸', 'lunhui-zhang_3', 0, '只见$N手中$w疾横，斗地点出！这招「回头是岸」轻灵飘逸，\\n$n眼见杖风袭来，竟不知如何是好', 20, -20, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (492, 'lunhui-zhang', '在劫难逃', 'lunhui-zhang_4', 0, '$N大喝一声，手中$w向$n兜头击落，兵器未至，已将$n各处退路封死，好一招「在劫难逃」', -5, 0, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (493, 'lunhui-zhang', '天网恢恢', 'lunhui-zhang_5', 0, '$N倒提$w，轻轻一纵，一招「天网恢恢」从$n意想不到的地方刺出，$n顿时手足无措，狼狈万分', -10, -5, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (494, 'lunhui-zhang', '再堕轮回', 'lunhui-zhang_6', 0, '$N脸上突现煞气，举起手中$w，猛向$n$l击落，这招「再堕轮回」出手又快又狠', 20, -15, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (495, 'moyun-shou', '螳螂捕蝉式', 'moyun-shou_1', 0, '$N一招「螳螂捕蝉式」，左手抓向$n的丹田，就在$n回身自防的一瞬间，右手却已掐上了$n的$l', 10, 10, 160, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (496, 'moyun-shou', '梅花五朵', 'moyun-shou_2', 0, '$N双手一翻，出「梅花五朵」，双手如穿花蝴蝶一般上下翻飞。\\n$n看花了眼，刹那间$N已欺身到了眼前', 5, -15, 180, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (497, 'moyun-shou', '穿针引线', 'moyun-shou_3', 0, '只见$N一转身，一指由胁下穿出，疾刺$n的$l，却正是一招「穿针引线」', 5, 10, 100, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (498, 'moyun-shou', '力士推山', 'moyun-shou_4', 0, '$N双掌一错，掌心向外横推而出，这一招「力士推山」带着一股罡风扑向$n的$l', 20, 20, 140, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (499, 'moyun-shou', '乌龙翻江', 'moyun-shou_5', 0, '$N一招「乌龙翻江」，左手在空中虚划了个半弧，拍向$n的$l', 30, 10, 70, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (500, 'moyun-shou', '力劈华山', 'moyun-shou_6', 0, '忽听$N一声怒吼，右手高高举起，一式「力劈华山」，砍向$n的$l', 10, -10, 220, '砍伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (501, 'moyun-shou', '雷霆一击', 'moyun-shou_7', 0, '$N双掌一错，左右手突发青红之光，随着一声霹雳，青红两色火球电般地射向了$n', -50, -50, 500, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (502, 'puti-zhi', '', 'puti-zhi_1', 0, '$N“呼”地一指点出，这一招由中宫直进，\\n指未到，指风已把$n压得揣不过气来', -5, -5, 60, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (503, 'puti-zhi', '', 'puti-zhi_2', 0, '$N身形不动，右手作「佛祖拈花」状。$n稍一犹豫，$N的中指指节已敲向$n的$l', 10, -10, 120, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (504, 'puti-zhi', '', 'puti-zhi_3', 0, '只见$N一转身，一指由胁下穿出，疾刺$n的$l', -5, 10, 80, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (505, 'puti-zhi', '', 'puti-zhi_4', 0, '$N双掌一错，十指如穿花蝴蝶一般上下翻飞。$n只觉得全身都在$N指力笼罩之下', -15, 10, 60, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (506, 'puti-zhi', '', 'puti-zhi_5', 0, '只见$N面带微笑，负手而立。但是$n觉得有一道指力直扑$l而来', 15, -5, 60, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (507, 'puti-zhi', '', 'puti-zhi_6', 0, '忽听$N一声轻叱，左手划了个半弧，右手食指闪电般点向$n的$l', -5, -5, 70, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (508, 'qianjun-bang', '大闹阎罗府', 'qianjun-bang_1', 0, '$N身形稍退，手中$w迎风一抖，朝着$n劈头盖脸地砸将下来', 5, -10, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (509, 'qianjun-bang', '谈笑退天兵', 'qianjun-bang_2', 0, '$N仰天长笑，看也不看，一招「谈笑退天兵」，随手一棒向$n当头砸下', 0, 0, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (510, 'qianjun-bang', '勇斗二郎神', 'qianjun-bang_3', 0, '$N一个虎跳，越过$n头顶，手中$w抡个大圆，呼！地一声砸向$n$l', 10, -20, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (511, 'qianjun-bang', '脱困老君炉', 'qianjun-bang_4', 0, '$N一声巨喝，好一个「脱困老君炉」！\\n就在$n一愣之间，$N手中$w已是呼啸而至，扫向$n的$l', 10, -15, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (512, 'qianjun-bang', '醉闹蟠桃会', 'qianjun-bang_5', 0, '$N使出「醉闹蟠桃会」，脚步跄踉，左一棒，右一棒，\\n打得$n手忙脚乱，招架不迭', -5, -5, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (513, 'qianjun-bang', '三打白骨精', 'qianjun-bang_6', 0, '$N连翻几个筋斗云，手中$w转得如风车一般，\\n一连三棒从半空中击向$n顶门', 5, -10, 20, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (514, 'qianjun-bang', '千钧澄玉宇', 'qianjun-bang_7', 0, '$N手中$w一抖，化为千万道霞光，\\n就在$n目眩神摇之时，再一抖，霞光顿收，\\n$w已到了$n的$l！这一招有个名堂，叫作「千钧澄玉宇」', 0, -20, 40, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (515, 'qianjun-bang', '乾坤一棒', 'qianjun-bang_8', 0, '$N将手中$w迎风一挥，幻出万千虚影，蓄力劲发，高举过顶，\n$w对准$n的脑门就砸了下去。这一下要是打中，恐怕连大罗金仙也难逃一命', -50, -50, 200, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (516, 'qixiu-jian', '五马分尸', 'qixiu-jian_1', 0, '$N手腕一抖，$w剑尖化为五道白光，分别向$n的咽喉、左右肩、和左右脚腕疾刺', 0, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (517, 'qixiu-jian', '六亲不认', 'qixiu-jian_2', 0, '$N关节僵硬，手中$w如一根树干一般横竖乱扫。$n识得这招「六亲不认」的威力，连忙躲避不迭', 10, -20, 30, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (518, 'qixiu-jian', '七窍生烟', 'qixiu-jian_3', 0, '$N纵身跃起，手中$w带起万道银光，向$n的面门点去。这招「七窍生烟」果然把$n逼得手忙脚乱', 5, -10, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (519, 'qixiu-jian', '八方风雨', 'qixiu-jian_4', 0, '$N奋不顾身，手中$w如狂风暴雨般向$n乱劈！这招「八方风雨」虽然露出若干空门，但$n也不敢不顾自身安危而贸然进攻', 5, -15, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (520, 'qixiu-jian', '九死一生', 'qixiu-jian_5', 0, '$N连人带剑猛扑向$n的$l。若是这招「九死一生」击不中$n，$N本人就空门大开，任人宰割了', 10, -10, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (521, 'qixiu-jian', '十面埋伏', 'qixiu-jian_6', 0, '$N身随剑走，迅速无伦地在$n周围兜圈。$n只见周围无数人影，随时都有可能有一柄$w从意想不到的位置刺来，实在是危机重重', 0, -15, 40, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (522, 'sanban-axe', '开瓜', 'sanban-axe_1', 0, '$N大喊一声「开瓜」，手中$w带着这一吼的威猛之势，朝$n当头劈下', 20, -15, 45, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (523, 'sanban-axe', '剔牙', 'sanban-axe_2', 0, '$N大喊一声「剔牙」，顺势带过大斧，趁$n一愣之际，以斧尾护手刀向$n面门疾戳', 20, -15, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (524, 'sanban-axe', '掏耳朵', 'sanban-axe_3', 0, '$N大喊一声「掏耳朵」，翻转斧头，手中$w划出一道银弧，奔着$n的脑袋横劈', 20, -15, 40, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (525, 'sanban-axe', '捅', 'sanban-axe_4', 0, '$N大喊一声「捅」，趁$n换招中的空隙，以斧尾护手刀向$n的$l狠狠戳了下去', -20, 15, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (526, 'sanqing-jian', '', 'sanqing-jian_1', 0, '$N使出一招「星河影动」，剑光闪烁不定，若有若无地刺向$n$l', 0, 15, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (527, 'sanqing-jian', '', 'sanqing-jian_2', 0, '$N身形转个不停，突然一招「一点灵犀」使出，手中$w划出一道银弧，径刺$n$l', -10, 15, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (528, 'sanqing-jian', '', 'sanqing-jian_3', 0, '$N脚下踏了个七星步，一招「古道西风」手中$w势若飞瀑向$n拦腰一斩', -5, 15, 20, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (529, 'sanqing-jian', '', 'sanqing-jian_4', 0, '但见$N连退几步，忽然间纵身跃起，手中$w一式「沧海月明」对准$n的$l凌空一斩', -15, 5, 30, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (530, 'sanqing-jian', '', 'sanqing-jian_5', 0, '$N轻轻一跃，使了个「乘风归去」，却在转身之际对准$n$l斜斜挥出一剑', 5, 25, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (531, 'sanqing-jian', '', 'sanqing-jian_6', 0, '$N神态悠闲，手中$w凭空一指，一招「白云千载」轻妙地划向$n的$l', -10, 10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (532, 'sanqing-jian', '', 'sanqing-jian_7', 0, '$N手中$w向外一分，使一招「曲径通幽」反手对准$n$l一剑刺去', 0, 20, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (533, 'six-chaos-sword', '群魔乱舞', 'six-chaos-sword_1', 0, '$N使一招「群魔乱舞」，手中$w狂风骤雨般地向$n的$l连攻数剑', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (534, 'six-chaos-sword', '厉鬼缠身', 'six-chaos-sword_2', 0, '$N身形一转，一招「厉鬼缠身」$w斩向$n的$l', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (535, 'six-chaos-sword', '百鬼夜行', 'six-chaos-sword_3', 0, '$N舞动$w，一招「百鬼夜行」挟着闪闪剑光刺向$n的$l', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (536, 'six-chaos-sword', '饿鬼拦路', 'six-chaos-sword_4', 0, '$N手中$w一抖，使出「饿鬼拦路」往$n的$l刺出一剑', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (537, 'six-chaos-sword', '鬼影幢幢', 'six-chaos-sword_5', 0, '$N手中$w剑光暴长，一招「鬼影幢幢」往$n$l刺去', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (538, 'six-chaos-sword', '秋坟鬼唱', 'six-chaos-sword_6', 0, '$N手中$w直指$n$l，一招「秋坟鬼唱」发出逼人剑气刺去', 0, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (539, 'skyriver-rake', '三花聚顶', 'skyriver-rake_1', 0, '$N哼一声使出「三花聚顶」，凌空跃起飞身自上而下$w往$n的$l只一筑', -45, -15, 15, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (540, 'skyriver-rake', '五气朝元', 'skyriver-rake_2', 0, '突然$N倒退几步反身收回丹田，一招「五气朝元」，$w半空划出一阵旋风身砸向$n的$l', -15, -10, 35, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (541, 'skyriver-rake', '意闲性拙', 'skyriver-rake_3', 0, '$N恍恍惚惚身子一晃丢下$w，却冷不防一个「意闲性拙」双臂斜向大回转扫将过来，$n顿时慌了手脚', -20, -20, 25, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (542, 'skyriver-rake', '混沌迷心', 'skyriver-rake_4', 0, '$N将手中$w收起飞步跳到$n身外，劈头一个「混沌迷心」，$n连忙急转身，只见$w离$l竟只有三分之毫厘', -40, -5, 15, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (543, 'skyriver-rake', '酒醉意沉', 'skyriver-rake_5', 0, '$N两眼惺忪紧握$w一个踉跄，$n尚未醒悟，早已有一招「酒醉意沉」直逼向$n的$l', -35, -25, 35, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (544, 'skyriver-rake', '东撒西泼', 'skyriver-rake_6', 0, '$n忽然不见$N，猛一抬头只见$N轮园了$w一式「东撒西泼」，急风骤雨一般径直扫向$n$l', -25, -10, 20, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (545, 'skyriver-rake', '逞雄广寒', 'skyriver-rake_7', 0, '$N拿出一招「逞雄广寒」，跳出圈外复又俯身撞入圈内，只见$w上下翻飞以迅雷不及掩耳之势砸向$n的$l', -25, -20, 30, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (546, 'skyriver-rake', '戏耍嫦娥', 'skyriver-rake_8', 0, '$N大笑一声，眯起双眼一招「戏耍嫦娥」，耍出手中$w又反手一捞，$w已劈头筑向$n', -35, -15, 25, '筑伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (547, 'snowsword', '', 'snowsword_1', 0, '$N使一招「寒芳留照魂应驻」，手中$w化为一道疾光刺向$n的$l', -5, -10, 10, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (548, 'snowsword', '', 'snowsword_2', 0, '只见$N几个急转，使出「晚凝深翠拂平沙」，一声娇喝中剑光冲天而起，扫向$n的$l', -35, -5, 20, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (549, 'snowsword', '', 'snowsword_3', 0, '$N淡淡一笑，一式「攒花染出几霜痕」舞出无数幻影，$n只觉得阵阵幽香四面袭来，却不知该如何闪躲', -10, -15, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (550, 'snowsword', '', 'snowsword_4', 0, '$N手中$w轻轻一抖，一式「霜印传神梦也空」幻出一遍寒光罩向$n。$n只觉得连呼吸都被冻住了', -30, -5, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (551, 'snowsword', '', 'snowsword_5', 0, '$N手中$w再一抖，只见寒光点点，飘浮不定。\\n这一招「篱筛破月锁玲珑」只看得$n眼花缭乱，哪里还能招架', -20, -20, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (552, 'snowsword', '', 'snowsword_6', 0, '$n只觉得一缕冷香掠过，$N已悄然间飘至$n身后，剑心直指$n的后胸，正是一式「暗香浮动月黄昏」', -35, -5, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (553, 'snowsword', '', 'snowsword_7', 0, '$N不闪不避，一式「风波不信菱枝弱」，神色娴雅，蓄势待发，一道澄如秋水、寒似玄冰的剑光直指$n破绽所在', -5, -10, 10, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (554, 'snowwhip', '寒风起兮', 'snowwhip_1', 0, '$N使一招「寒风起兮」，手中$w抖得笔直向$n的$l连刺数鞭', -10, 0, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (555, 'snowwhip', '芦花满天', 'snowwhip_2', 0, '$N身形一转，一招「芦花满天」$w幻出满天鞭影，虚虚实实地袭向$n的$l', -20, 0, 20, '瘀伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (556, 'snowwhip', '芦花飘香', 'snowwhip_3', 0, '$N力贯$w，一招「芦花飘香」点点鞭影飘浮不定地点向$n的$l', -20, 0, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (557, 'wuhu-blade', '饿虎扑食', 'wuhu-blade_1', 0, '$N纵身跃在空中，有如饿虎扑食一般，手中$w借着下落之势，向$n当头劈下', 0, 0, 15, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (558, 'wuhu-blade', '三人成虎', 'wuhu-blade_2', 0, '$N展开轻功在$n周围飞奔，疾跑中向$n砍去数刀。$n只见三个人影，从三个不同的方向砍来，不由惊慌失措', 0, 0, 20, '砍伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (559, 'wuhu-blade', '狐假虎威', 'wuhu-blade_3', 0, '$N一声巨吼，震得$n耳中回声不止。趁此机会，$N一刀削向$n的$l。原来是五虎断门刀中的杀手「狐假虎威」', 0, 0, 25, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (560, 'wuhu-blade', '虎落平阳', 'wuhu-blade_4', 0, '$N左掌护身，滚倒在地上，右手$w连连向$n的双脚削去', 0, 0, 10, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (561, 'wuhu-blade', '骑虎难下', 'wuhu-blade_5', 0, '$N站稳马步，运起浑身之力，逼入$w中，向$n发出雷霆一击！这招「骑虎难下」名字虽然难听，招数果然有效', 0, 0, 30, '劈伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (562, 'wusi-mace', '呕心锏', 'wusi-mace_1', 0, '$N挺起手中$w，朝$n的前心猛插下去。这招「呕心锏」毫无花巧，但威力惊人', 5, -5, 35, '戳伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (563, 'wusi-mace', '沥血锏', 'wusi-mace_2', 0, '$N挥起$w，朝$n的后心猛砸。这招「沥血锏」若是打中了，$n定会呕血数升', 15, -10, 30, '震伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (564, 'wusi-mace', '捕风锏', 'wusi-mace_3', 0, '$N运起轻功在$n周围疾速转圈，身上的衣服带起阵阵轻风。正当$n眼花缭乱之际，$N挺起手中$w向$n的$l打去', -10, 0, 15, '震伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (565, 'wusi-mace', '捉影锏', 'wusi-mace_4', 0, '$N跟在$n背后，有如影子一般，锏锏不离$n后心。这势「捉影锏」果然把$n逼得手忙脚乱', 5, -5, 20, '戳伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (566, 'wusi-mace', '追魂锏', 'wusi-mace_5', 0, '$N运足内力一声巨吼，惊得$n魂飞魄散。趁此良机，$N挥起$w向$n的$l猛砸', 10, -5, 25, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (567, 'wusi-mace', '夺命锏', 'wusi-mace_6', 0, '$N以左手掌力牵制住$n，右手$w猛地向$n的头部横扫！若是这势「夺命锏」打实了，$n定无幸免之理', 5, -5, 25, '撞伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (568, 'wusi-mace', '无情锏', 'wusi-mace_7', 0, '$N战得兴起，索性挥起$w向四面八方各打一锏。这招「无情锏」使开来，五尺之内，不论敌友，尽皆笼罩在劲风中', 5, 5, 15, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (569, 'wusi-mace', '杀手锏', 'wusi-mace_8', 0, '$N跃起数尺，居高临下，一锏向$n当头砸下。这招「杀手锏」乃是秦家无私锏中的绝招，果然气势威猛', 5, -15, 35, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (570, 'wuxing-quan', '金字诀', 'wuxing-quan_1', 0, '$N使出五行拳中的\"金字诀\"，提气沉马，双拳对合，\\n居然嗡！地一声发出金器交鸣之声。便在各人心神一震之间，\\n$N的两只拳头已经砸到了$n的$l', 5, 5, 110, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (571, 'wuxing-quan', '水字诀', 'wuxing-quan_2', 0, '只见$N脚步变幻不定，身形一晃再晃，双拳径破$n之防守，痛击$n$l！\\n人传五行拳中的\"水字诀\"无孔不入，确是名不虚传', 5, 5, 80, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (572, 'wuxing-quan', '木字诀', 'wuxing-quan_3', 0, '$N使出\"木字诀\"，一时间似是脚步沉滞，身法僵硬。旋即大喝一声，\\n带着一副刀枪不入的神态和身扑向$n，双手成爪一前一后抓向$n$l', 5, 5, 60, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (573, 'wuxing-quan', '火字诀', 'wuxing-quan_4', 0, '$N双拳交击，身形连转，虽无一拳直接击向$n，五行拳中的\"火字诀\"\\n却把$N的拳势发挥得淋漓尽致，带出的劲气便如烈火般一道又一道地扑面而来', 5, 5, 60, '内伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (574, 'wuxing-quan', '土字诀', 'wuxing-quan_5', 0, '$N暗运真气，双腿便似钉在地上一般，接连五六个直拳一气打向$n$l！\\n五行拳中的\"土字诀\"既不高妙，亦不凶险，却有一股务求必中的狠气', 5, 5, 80, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (575, 'xiaofeng-sword', '皓月当空', 'xiaofeng-sword_1', 0, '$N轻飘飘地纵身跃起，手中$w划出一个白色光环，向$n的$l圈去', -15, 10, 20, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (576, 'xiaofeng-sword', '水银泄地', 'xiaofeng-sword_2', 0, '$N双脚一顿，笔直跃起，手中$w不停地颤抖着，笼罩住$n全身。这势「水银泄地」果然防不胜防', -5, -10, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (577, 'xiaofeng-sword', '花明月暗', 'xiaofeng-sword_3', 0, '$N手中$w带起点点银光，指向$n前胸穴道。$n正专心致志地对付着剑招，不料$N左手运力拍向$n的$l。这势「花明月暗」亦真亦幻，实是难防', -5, -5, 25, '震伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (578, 'xiaofeng-sword', '清雨朦胧', 'xiaofeng-sword_4', 0, '$N在$n四周游走，手中$w去势飘忽不定，只看得$n眼花缭乱。趁此良机，$N于朦朦胧胧中一抖$w，向$n的$l疾挑', -15, 5, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (579, 'xiaofeng-sword', '飞花似梦', 'xiaofeng-sword_5', 0, '激战中，$N从$n面前斜斜跃过，手中$w划出五朵桃花，点向$n的$l', -5, 0, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (580, 'xiaofeng-sword', '丝雨如愁', 'xiaofeng-sword_6', 0, '$N展开身形，身随剑走，剑身绵绵不绝地缠向$n的$l。诗云：无边丝雨细如愁。$N的这招剑果然深得诗中三味', -20, 10, 20, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (581, 'xiaofeng-sword', '潇湘夜雨', 'xiaofeng-sword_7', 0, '$N仗起手中$w，剑尖带起点点白光，罩住$n的胸腹，只等$n的破绽。这招「潇湘夜雨」果然象细雨般紧密，$n实在不知长剑将要指向自己身上何处', -5, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (582, 'xiaofeng-sword', '月白风清', 'xiaofeng-sword_8', 0, '$N手中$w中宫直进，疾速刺向$n的前心。这招「月白风清」令人耳目一新。$n只见白光一闪，剑尖已到心口', -15, 15, 15, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (583, 'xiaofeng-sword', '金波低转', 'xiaofeng-sword_9', 0, '$N手中$w向$n的右手疾刺，但正当$n要招架时，$N剑尖转向$n的左足！这招「金波低转」确实神鬼莫测', -5, -15, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (584, 'xuanhu-blade', '「马嵬坡下泥土中，不见玉颜空死处」', 'xuanhu-blade_1', 0, '$N一式「马嵬坡下泥土中，不见玉颜空死处」，脚踏「巽」位，\n身形一晃，从$n眼前消失，闪现在$n身后，\n以刀当剑，手中$w毫无声息地刺向$n的$l', -10, 0, 20, '', '$N一式「马嵬坡下泥土中，不见玉颜空死处」，脚踏「巽」位，\n身形一晃，从$n眼前消失，闪现在$n身后', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (585, 'xuanhu-blade', '「迟迟钟鼓初长夜，耿耿星河欲曙天」', 'xuanhu-blade_2', 0, '$N一式「迟迟钟鼓初长夜，耿耿星河欲曙天」，抢占「坎」位，\n手中$w化做一道刀光, 似银河倒泻般挥向$n$l', -10, 0, 25, '砍伤', '$N一式「迟迟钟鼓初长夜，耿耿星河欲曙天」，抢占「坎」位，\n手中$w化做一道刀光, 磕开$n的攻势', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (586, 'xuanhu-blade', '「上穷碧落下黄泉，两处茫茫皆不见」', 'xuanhu-blade_3', 0, '$N一式「上穷碧落下黄泉，两处茫茫皆不见」，闪向「震」位，\n手中$w化为漫天刀影，夹着隐隐雷声，攻向$n全身各处', -10, -10, 25, '劈伤', '$N一式「上穷碧落下黄泉，两处茫茫皆不见」，闪向「震」位，\n手中$w化为漫天刀影，夹着隐隐雷声，护住$N全身各处', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (587, 'xuanhu-blade', '「楼阁玲珑五云起，其中绰约多仙子」', 'xuanhu-blade_4', 0, '$N一式「楼阁玲珑五云起，其中绰约多仙子」，绕$n急速旋转，\n化为一圈幻影，在「艮」位突发一刀，以泰山压顶之式劈向$n$l', -15, 0, 30, '砍伤', '$N一式「楼阁玲珑五云起，其中绰约多仙子」，绕$n急速旋转，\n化为一圈幻影，躲开$n的攻势', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (588, 'xuanhu-blade', '「风吹仙袂飘飘举，犹似霓裳羽衣舞」', 'xuanhu-blade_5', 0, '$N一式「风吹仙袂飘飘举，犹似霓裳羽衣舞」，身体急速旋转，\n在「离」位如一团旋风，手中$w唰地砍向$n的$l', -10, 0, 20, '砍伤', '$N一式「风吹仙袂飘飘举，犹似霓裳羽衣舞」，身体急速旋转，\n在「离」位如一团旋风，化去$n的攻势', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (589, 'xuanhu-blade', '「玉容寂寞泪阑干，梨花一枝春带雨」', 'xuanhu-blade_6', 0, '$N一式「玉容寂寞泪阑干，梨花一枝春带雨」，占住「兑」位，\n将手中$w化做点点星光，洒向$n全身', -20, -10, 30, '劈伤', '$N一式「玉容寂寞泪阑干，梨花一枝春带雨」，占住「兑」位，\n将手中$w化做点点星光，击在$n的$l，化去$n的攻势', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (590, 'xuanhu-blade', '「在天愿作比翼鸟，在地愿为连理枝」', 'xuanhu-blade_7', 0, '$N一式「在天愿作比翼鸟，在地愿为连理枝」，连踏「乾」「坤」二位，\n手中$w从两个方向向$n的$l击去', -10, 0, 20, '割伤', '$N一式「在天愿作比翼鸟，在地愿为连理枝」，连踏「乾」「坤」二位，\n从$n的攻势中闪了出去', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (591, 'xuanhu-blade', '「天长地久有时尽，此恨绵绵无绝期」', 'xuanhu-blade_8', 0, '$N一式「天长地久有时尽，此恨绵绵无绝期」，由「坤」向「乾」疾退，\n手中$w化做一道长虹向$n$l击去', -20, -20, 30, '割伤', '$N一式「天长地久有时尽，此恨绵绵无绝期」，由「坤」向「乾」疾退，\n手中$w化做一道长虹荡开了$n的锋芒', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (592, 'xuanyuan-archery', '声东击西', 'xuanyuan-archery_1', 0, '$N忽然纵声长啸，横跃于空，取箭上弦。\\n\n只听弓弦响处，$w已到$n左肩，眼看就要对穿而过！\\n\n这招「李广射石」果然有穿石之力', -20, 10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (593, 'xuanyuan-archery', '廉颇负荆', 'xuanyuan-archery_2', 0, '$N弓交背后，俯身一招「廉颇负荆」，$w已带呼啸声向$n前胸飞去', 20, 20, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (594, 'xuanyuan-archery', '百步穿杨', 'xuanyuan-archery_3', 0, '突然间，$N几个筋斗倒翻而去，已在$n数丈之外。\\n\n$n正待追击，$N忽然转身，好一个「百步穿杨」，\\n\n$w已带着破空之声，直射$n面门', -10, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (595, 'xuanyuan-archery', '声东击西', 'xuanyuan-archery_4', 0, '$N力开长弓，瞄准$n的左臂虚晃一箭。\\n\n$n纵起闪避，突然发现并无羽箭射来。正在无处可去时，\\n\n$N弯弓搭箭，只见一支$w向$n的$l疾飞而至', -20, 10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (596, 'xuanyuan-archery', '后翌落日', 'xuanyuan-archery_5', 0, '$N手指微动，$n只听到「嗖」地一声，$w已到$l前数寸。\\n\n$n没放到这招「后翌落日」来势如此之快，不禁手足无措', 10, -10, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (597, 'xuanyuan-archery', '流星赶月', 'xuanyuan-archery_6', 0, '$N马步站稳，劲力透背，拉的弓如满月，$w飞一般冲向$n的$l', 20, 20, 40, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (598, 'xuanyuan-archery', '犀牛望月', 'xuanyuan-archery_7', 0, '$n纵身而起，正待凌空一击。$N作势似要逃跑，突然扭腰回身，\\n\n一招「犀牛望月」，手中$w如同长眼一般，直刺向$n的$l', -10, -10, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (599, 'yange-blade', '', 'yange-blade_1', 0, '$N一招「山川萧条」，手中$w卷起一股狂风，挥向$n的$l', -10, 0, 20, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (600, 'yange-blade', '', 'yange-blade_2', 0, '$N手中$w一晃，由下至上撩向$n的$l，一招「孤城落日」使得恰到好处', -10, -10, 20, '划伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (601, 'yange-blade', '', 'yange-blade_3', 0, '$N眼神恍惚，手中$w飘摇不定，一招「大漠穷秋」斜斜的砍向$n的$l', -10, 10, 20, '砍伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (602, 'yange-blade', '', 'yange-blade_4', 0, '$N左手执着$w，右手扶着刀背用力推出，一招「力尽关山」扫向$n的$l', -10, 0, 20, '砍伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (603, 'yange-blade', '', 'yange-blade_5', 0, '$N冷笑一声，一招「边风飘摇」，手中$w带者丝丝冷风由下至上划向$n的$l', -10, 10, 20, '划伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (604, 'yange-blade', '', 'yange-blade_6', 0, '$N狂喝一声，使出一招「绝域苍茫」，双手紧握$w\n带着逼人的杀气，刺向$n的$l', -10, -10, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (605, 'yinfeng-zhua', '「霉气扑鼻」', 'yinfeng-zhua_1', 0, '$n只觉隐隐传来一阵霉气，正奇怪间，$N的左爪已到$l', -10, -10, 50, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (606, 'yinfeng-zhua', '「千疮百孔」', 'yinfeng-zhua_2', 0, '$N笨拙无比地伸爪向$n的$l抓去。这招看似千疮百孔，\\n\n破绽无数，但等$n招架时，却被逼得手忙脚乱，叫苦不迭', 10, -10, 100, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (607, 'yinfeng-zhua', '「残缺不全」', 'yinfeng-zhua_3', 0, '$N左爪不动，右爪迅捷无比地向$n连施五抓。当$n全神贯注地对付\\n\n这五抓时，$N的右爪已神不知鬼不觉地到了$n的$l', 10, 10, 70, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (608, 'yinfeng-zhua', '「摇摇欲坠」', 'yinfeng-zhua_4', 0, '$N突然间跃起数尺，居高临下向$n抓来。$n虽然看出\\n\n$N胸腹间空门大开，却被这「摇摇欲坠」的凌厉攻势逼得回手自救', -10, 10, 70, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (609, 'yingzhaogong', '', 'yingzhaogong_1', 0, '只见$N耸身提气，全身骨骼一阵爆响！左手沉腰，右爪呼！地一声抓向$n的$l', 5, 5, 120, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (610, 'yingzhaogong', '', 'yingzhaogong_2', 0, '$N双腿连连踢出，身形亦节节拔高，半空中一个转折，双爪已向$n$l抓到', 5, 5, 60, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (611, 'yingzhaogong', '', 'yingzhaogong_3', 0, '$N左爪在$n眼前一划，右爪带风，由下而上往$n的$l狠命一抓', 5, 5, 80, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (612, 'yingzhaogong', '', 'yingzhaogong_4', 0, '$N单足点地，双臂一振使了个「鹰击长空」势不可挡地扑向$n', 5, 5, 100, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (613, 'yingzhaogong', '', 'yingzhaogong_5', 0, '只见$N连退几步，突然一个矮身贴地而飞，双爪刁钻异常地抓向$n$l', 5, 5, 70, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (614, 'yingzhaogong', '', 'yingzhaogong_6', 0, '$N大喝一声，双爪青筋凸起，前后一抄，似乎要把$n撕得粉身碎骨而后快', 5, 5, 80, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (615, 'yingzhaogong', '', 'yingzhaogong_7', 0, '$N往前一个轻纵，几乎与$n贴面而立，一声阴笑中右爪往$n的$l恶狠狠地一抓', 5, 5, 60, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (616, 'yingzhaogong', '', 'yingzhaogong_8', 0, '$N一个倒翻，背后就象长了眼睛似的，一爪又一爪延绵不绝地抓向$n的$l', 5, 5, 60, '抓伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (617, 'yueya-chan', '', 'yueya-chan_1', 0, '$N一按$w后把，只见一道寒光闪过，$w便如灵蛇一般钻向$n的$l', 0, -20, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (618, 'yueya-chan', '', 'yueya-chan_2', 0, '$N手中$w一荡，使出一招「晓风残月」，$w带着森森冷气划向$n$l', 0, 0, 25, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (619, 'yueya-chan', '', 'yueya-chan_3', 0, '$N手中的$w往地下一顿一弹，就在$n微一分神之时，$w已划出一道闪亮的弧光挑向$n$l', 5, -15, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (620, 'yueya-chan', '', 'yueya-chan_4', 0, '$N身形一转，手中$w往后一拖，就在这将退未退之际，$w一个转折呼！地一声向$n当头砸下', 5, -5, 30, '砸伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (621, 'yueya-chan', '', 'yueya-chan_5', 0, '$N怪叫一声，$w一气乱舞势若疯虎地朝$n冲了过去，手中$w看似不成章法，实则暗藏凶险', 0, -15, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (622, 'yueya-chan', '', 'yueya-chan_6', 0, '$N一抖$w，使了个「月黑风高」，手中的$w就象追魂的恶鬼一样缠上了$n的$l', 0, -15, 35, '割伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (623, 'zhuihun-sword', '群魔乱舞', 'zhuihun-sword_1', 0, '$N手中$w一抖，晃出几个虚影，狂风骤雨般地向$n的$l连攻数剑', -10, 0, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (624, 'zhuihun-sword', '厉鬼缠身', 'zhuihun-sword_2', 0, '$N身形一转，暴喝一声，手中$w如一条银蛇般刺向$n的$l', -10, -10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (625, 'zhuihun-sword', '百鬼夜行', 'zhuihun-sword_3', 0, '$N舞动$w，突然一个疾冲，$w挟着闪闪剑光刺向$n的$l', -15, 0, 20, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (626, 'zhuihun-sword', '饿鬼拦路', 'zhuihun-sword_4', 0, '$N手中$w一抖，幻出几许银光，就在一恍惚间，$w已斜斜地点上了$n的$l', -20, -20, 35, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (627, 'zhuihun-sword', '鬼影幢幢', 'zhuihun-sword_5', 0, '$N手中$w剑光暴长，又急又快地往$n$l刺去', -20, -10, 25, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (628, 'zhuihun-sword', '秋坟鬼唱', 'zhuihun-sword_6', 0, '$N猛然间身形一展，手中$w突发几尺剑芒，唰地刺向了$n的$l', -10, -10, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (629, 'zhuihun-sword', '地狱烈火', 'zhuihun-sword_7', 0, '$N大喝一声，手中$w宛若矫龙飞在半空，大有「横空出世」的气概。\\n$n只觉得全身俱在$w笼罩之下', -15, -15, 30, '抽伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (630, 'zhuihun-sword', '小楼夜哭', 'zhuihun-sword_8', 0, '$N喉咙里发出几声嚎叫，高举$w，不顾一切地冲向$n，几乎与$n贴脸而立！\\n手中$w却悄无声息地刺向$n的$l，好厉害的「小楼夜哭」', -10, -10, 30, '刺伤', '', 0, 0, 0);
INSERT INTO `skill_actions` VALUES (10001, 'baihua-zhang', '天女散花', 'baihua-zhang_6', 80, '$N嫣然一笑，双手扬起，无数花瓣纷纷飘落，将$n笼罩其中', -30, -30, 300, '瘀伤', '', 0, 125, 0);
INSERT INTO `skill_actions` VALUES (10002, 'snowsword', '叠嶂', 'snowsword_8', 80, '$N身形一顿，剑光连绵，如山峦叠嶂般向$n压去', -20, -20, 200, '刺伤', '', 0, 30, 0);
INSERT INTO `skill_actions` VALUES (10003, 'snowsword', '回风', 'snowsword_9', 120, '$N剑势一转，漫天剑影如回风舞雪，向$n席卷而去', -40, -40, 400, '刺伤', '', 0, 50, 0);
INSERT INTO `skill_actions` VALUES (10004, 'snowsword', '舞雪', 'snowsword_10', 100, '$N轻舞长剑，剑光如雪花纷飞，将$n困于剑阵之中', -25, -25, 250, '刺伤', '', 0, 50, 0);
INSERT INTO `skill_actions` VALUES (10005, 'huoyun-qiang', '火焰', 'huoyun-qiang_9', 100, '$N枪势如火，带起一片火焰向$n烧去', -30, -30, 350, '刺伤', '', 0, 0, 50);
INSERT INTO `skill_actions` VALUES (10006, 'qianjun-bang', '霹雳', 'qianjun-bang_9', 100, '$N大喝一声，千钧棒带起霹雳之声向$n砸去', -30, -30, 400, '砸伤', '', 0, 100, 0);
INSERT INTO `skill_actions` VALUES (10007, 'qianjun-bang', '乾坤', 'qianjun-bang_10', 150, '$N将棒高举过顶，乾坤一棒，天地为之变色', -50, -50, 600, '砸伤', '', 0, 200, 0);
INSERT INTO `skill_actions` VALUES (10008, 'moyun-shou', '掌心雷', 'moyun-shou_8', 100, '$N双手一错，一道掌心雷向$n轰去', -35, -35, 350, '内伤', '', 0, 0, 50);
INSERT INTO `skill_actions` VALUES (10009, 'dragonfight', '舍身', 'dragonfight_7', 120, '$N身形暴起，如龙出海，舍身向$n扑去', -40, -40, 450, '瘀伤', '', 0, 50, 0);
INSERT INTO `skill_actions` VALUES (10010, 'hellfire-whip', '三连', 'hellfire-whip_9', 100, '$N鞭影重重，连续三击向$n抽去', -25, -25, 300, '抽伤', '', 0, 0, 60);
INSERT INTO `skills` VALUES (1, 'archery', '基本弓术', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/archery.c');
INSERT INTO `skills` VALUES (2, 'axe', '基本斧法', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/axe.c');
INSERT INTO `skills` VALUES (3, 'baguazhen', '八卦阵法', 'weapon', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的内力不够，没有办法学八卦阵法。\", \"max_force\": 0}', '{\"message\": \"你现在脚下虚浮，先休息一阵吧。\", \"kee_cost\": 30, \"force_cost\": 3}', '[\"dodge\", \"move\"]', NULL, 1, 'daemon/skill/baguazhen.c');
INSERT INTO `skills` VALUES (4, 'baguazhou', '八卦咒', 'spell', 'fighter', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的法术修为还不够高深，无法学习八卦咒．\", \"spells_base\": 20, \"prerequisite_skill\": \"spells\"}', NULL, '[\"spells\"]', NULL, 1, 'daemon/skill/baguazhou.c');
INSERT INTO `skills` VALUES (5, 'baihua-zhang', '百花掌', 'weapon', 'moon', '', '女儿门的独特掌法，以轻盈曼妙著称。', 100, 1, 0, 0, NULL, NULL, '', -5, -5, 20, '', '{\"gender\": \"女性\", \"no_weapon\": true, \"fail_message\": \"百花掌是只有女子才能练的武功。\"}', '{\"kee_cost\": 30, \"sen_cost\": 30, \"force_cost\": 10}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/baihua-zhang.c');
INSERT INTO `skills` VALUES (6, 'bainiao-jian', '败兵剑法', 'weapon', 'yaomo', '', '雪山派的入门剑法，以败中求胜著称。', 100, 1, 0, 0, NULL, NULL, '', -5, -5, 20, '', '{\"max_force\": 50, \"weapon_type\": \"sword\", \"fail_message\": \"你的内力不够，没有办法学习败兵剑法。\", \"weapon_required\": {\"skill_type\": \"sword\"}}', '{\"message\": \"败兵剑法注重身法，轻功不够可能被别人击中要害。\", \"kee_cost\": 30, \"force_cost\": 5, \"dodge_required\": {\"ratio\": 0.5, \"skill\": \"bainiao-jian\"}}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/bainiao-jian.c');
INSERT INTO `skills` VALUES (7, 'bawang-qiang', '霸王枪', 'weapon', 'fighter', '', '枪为百兵之王，霸王枪威力尤猛，善于突破敌手的严密防守', 100, 1, 0, 0, NULL, NULL, '', 10, -10, 25, '', '{\"max_force\": 100, \"weapon_type\": \"spear\"}', '{\"kee\": 30, \"force\": 5, \"kee_cost\": 30, \"force_cost\": 5, \"weapon_type\": \"spear\"}', '[\"spear\", \"parry\"]', NULL, 1, 'daemon/skill/bawang-qiang.c');
INSERT INTO `skills` VALUES (8, 'bingpo-blade', '冰魄寒刀', 'weapon', '', '', '冰魄寒刀的特点是快，往往是刀光一闪，人头落地。但只要不惊不慌，严密防守，虽为刀势缠绕亦无大碍，冰魄寒刀不以力取胜，故伤害力不强。', 100, 1, 0, 0, NULL, NULL, '', -15, 5, 20, '', '{\"max_force\": 100, \"weapon_type\": \"blade\", \"fail_message\": \"你的内力不够，没有办法练冰魄寒刀，多练些内力再来吧。\", \"weapon_required\": {\"message\": \"你必须先找一把冰做的刀才能练冰魄寒刀。\", \"material\": \"ice\", \"skill_type\": \"blade\"}}', '{\"message\": \"你按着所学练了一遍冰魄寒刀。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"blade\"]', NULL, 1, 'daemon/skill/bingpo-blade.c');
INSERT INTO `skills` VALUES (9, 'blade', '基本刀法', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/blade.c');
INSERT INTO `skills` VALUES (10, 'buddhism', '大乘佛法', 'spell', 'bonze', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": {\"bellicosity\": \"你的杀气太重，无法修炼大乘佛法。\", \"skill_limit\": \"你的法术修为还不够高深，无法学习大乘佛法。\"}, \"bellicosity_max\": 100, \"max_bellicosity\": 100, \"prerequisite_skill\": \"spells\", \"spells_level_limit\": true}', NULL, '[\"spells\", \"buddhism\"]', NULL, 1, 'daemon/skill/buddhism.c');
INSERT INTO `skills` VALUES (11, 'changquan', '长拳', 'weapon', '', '', '最基础的拳法招式，简单实用，适合初学者。', 100, 1, 0, 0, NULL, NULL, '', 5, 5, 20, '', '{\"no_weapon\": true, \"fail_message\": \"练长拳必须空手。\"}', '{\"kee_cost\": 30, \"sen_cost\": 30, \"force_cost\": 10}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/changquan.c');
INSERT INTO `skills` VALUES (12, 'chaos-steps', '倒乱七星步', 'movement', '', '', '模仿北斗七星的步法，诡异难测。', 100, 1, 0, 0, NULL, NULL, '', 20, 0, 0, '', '{\"max_force\": 50, \"fail_message\": \"你的内力不够，没有办法练倒乱七星步。\"}', '{\"kee_cost\": 30, \"force_cost\": 3, \"fail_message\": \"你的气或内力不够，不能练倒乱七星步法。\"}', '[\"dodge\"]', NULL, 1, 'daemon/skill/chaos-steps.c');
INSERT INTO `skills` VALUES (13, 'cloudstaff', '青云杖法', 'weapon', '', '', '古朴的杖法。', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 20, '', '{\"fail_message\": \"你的膂力还不够，也许该练一练内力来增强力量。\", \"str_required\": {\"formula\": \"+ max_force / 10 >= 50\"}}', '{\"kee_cost\": 60, \"weapon_type\": \"staff\", \"fail_message\": \"你必须先找一根木杖或者是类似的武器，才能练杖法。\", \"weapon_required\": {\"skill_type\": \"staff\"}}', '[\"staff\", \"parry\"]', NULL, 1, 'daemon/skill/cloudstaff.c');
INSERT INTO `skills` VALUES (14, 'cuixin-zhang', '摧心掌', 'weapon', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"练摧心掌必须空手。\", \"no_weapon\": true, \"weapon_required\": false}', '{\"message\": {\"kee\": \"你现在手足酸软，休息一下再练吧。\", \"sen\": \"你的精神无法集中了，休息一下再练吧。\", \"force\": \"你的内力不够了。\"}, \"kee_cost\": 30, \"sen_cost\": 30, \"force_cost\": 10}', '[\"unarmed\", \"parry\"]', NULL, 1, 'daemon/skill/cuixin-zhang.c');
INSERT INTO `skills` VALUES (15, 'dagger', '短兵', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/dagger.c');
INSERT INTO `skills` VALUES (16, 'dali-bang', '哭丧棒', 'weapon', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 10, -10, 30, '', '{\"max_force\": 100, \"weapon_type\": \"stick\"}', '{\"kee_cost\": 30, \"force_cost\": 5}', '[\"stick\", \"parry\"]', NULL, 1, 'daemon/skill/dali-bang.c');
