INSERT INTO `skills` VALUES (18, 'dengxian-dafa', '登仙大法', 'spell', 'yaomo', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的法术修为还不够高深，无法学习登仙大法。\", \"spells_base\": 10}', NULL, '[\"spells\"]', NULL, 1, 'daemon/skill/dengxian-dafa.c');
