INSERT INTO `skills` VALUES (20, 'dodge', '闪避', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"dodge\"]', '[\"笨手笨脚\", \"步伐轻盈\", \"身形灵动\", \"身轻如燕\", \"疾若飞鸿\", \"踏雪无痕\", \"登萍渡水\", \"来去如风\", \"一泻千里\", \"移形换影\", \"凌空渡虚\"]', 1, 'daemon/skill/dodge.c');
INSERT INTO `skills` VALUES (21, 'dragonfight', '龙形搏击', 'weapon', 'dragon', '', '东海龙宫的绝学，模仿龙形的搏斗技巧。', 100, 1, 0, 0, NULL, NULL, '', 0, -10, 20, '', '{\"no_weapon\": true, \"fail_message\": \"练龙形博击必须空手。\", \"required_skills\": {\"dragonforce\": {\"formula\": \">= dragonfight / 2\"}}}', '{\"kee_cost\": 30, \"sen_cost\": 50, \"force_cost\": 20, \"required_skills\": {\"dragonforce\": {\"formula\": \">= dragonfight / 2\"}}}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/dragonfight.c');
INSERT INTO `skills` VALUES (22, 'dragonforce', '龙神心法', 'force', 'dragon', '东海龙宫', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"family_message\": \"你非龙族，再练有害无益。\", \"practice_limit\": {\"field\": \"dragonforce_practice\", \"min_value\": 1, \"fail_message\": \"你试着练功，可毫无进展，需要驯服更多的海兽以增进龙神心法。\"}, \"family_required\": \"东海龙宫\", \"environment_required\": {\"field\": \"dragonforce_practice\", \"fail_message\": \"龙神心法只能在特殊的法台上才可练。\"}}', '{\"kee_cost\": {\"formula\": \"skill >= 200 ? 60 : 30\"}, \"sen_cost\": {\"formula\": \"skill >= 200 ? 60 : 30\"}, \"force_cost\": {\"formula\": \"skill >= 200 ? 30 : 10\"}, \"family_required\": \"东海龙宫\", \"practice_decrease\": {\"field\": \"dragonforce_practice\", \"value\": 1}, \"environment_required\": \"dragonforce_practice\"}', '[\"force\"]', NULL, 1, 'daemon/skill/dragonforce.c');
INSERT INTO `skills` VALUES (23, 'dragonstep', '龙神身法', 'movement', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"kee_min\": 30, \"message\": \"你非龙族怎能练龙神身法？\", \"force_min\": 3, \"class_required\": \"dragon\"}', '{\"kee_cost\": 30, \"force_cost\": 3, \"class_required\": \"dragon\"}', '[\"dodge\"]', NULL, 1, 'daemon/skill/dragonstep.c');
INSERT INTO `skills` VALUES (24, 'fengbo-cha', '风波十二叉', 'weapon', 'dragon', 'dragon', '龙族水中出没的叉法，有特别之处', 100, 1, 0, 0, NULL, NULL, '', 0, -5, 25, '', '{\"max_force\": 100, \"weapon_type\": \"fork\", \"class_required\": \"dragon\", \"skill_required\": {\"dragonforce\": {\"min\": 0, \"ratio\": 2}}}', '{\"kee\": 50, \"sen\": 50, \"force\": 20, \"kee_cost\": 50, \"force_cost\": 3, \"force_skill\": \"dragonforce\", \"class_required\": \"dragon\"}', '[\"fork\", \"parry\"]', NULL, 1, 'daemon/skill/fengbo-cha.c');
INSERT INTO `skills` VALUES (25, 'fofa', '小乘佛法', 'spell', 'bonze', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": {\"bellicosity\": \"你的杀气太重，无法修炼小乘佛法。\", \"skill_limit\": \"你的法术修为还不够高深，无法学习小乘佛法。\"}, \"bellicosity_max\": 100, \"max_bellicosity\": 100, \"prerequisite_skill\": \"spells\", \"spells_level_limit\": true}', NULL, '[\"spells\"]', NULL, 1, 'daemon/skill/fofa.c');
INSERT INTO `skills` VALUES (26, 'fonxansword', '封山剑法', 'weapon', 'swordsman', '', '封山派的剑法绝学。', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 30, '', '{\"max_force\": 50, \"weapon_type\": \"sword\", \"fail_message\": \"你的内力不够，没有办法练封山剑法。\", \"force_message\": \"封山剑法必须配合封山派内功才能练。\", \"required_force\": \"fonxanforce\", \"weapon_required\": {\"message\": \"你必须先找一把剑才能练剑法。\", \"skill_type\": \"sword\"}}', '{\"message\": \"你按着所学练了一遍封山剑法。\", \"kee_cost\": 30, \"force_cost\": 3}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/fonxansword.c');
INSERT INTO `skills` VALUES (27, 'force', '基本内功', 'basic', 'force', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"的内功修为不足以学习更深的内容。\"}', NULL, '[\"force\"]', '[\"若有若无\", \"初窥门径\", \"渐入佳境\", \"气息悠长\", \"生生不绝\", \"英华内敛\", \"通关在即\", \"豁然贯通\", \"举世无双\", \"震古铄今\", \"深不可测\"]', 1, 'daemon/skill/force.c');
INSERT INTO `skills` VALUES (28, 'fork', '基本叉法', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/fork.c');
INSERT INTO `skills` VALUES (29, 'fumo-zhang', '伏魔杖', 'weapon', '', '', '五庄观的功夫。', 100, 1, 0, 0, NULL, NULL, '', 2, -6, 23, '', '{\"max_force\": 100, \"weapon_type\": \"staff\", \"fail_message\": \"你的内力不够，没有办法学伏魔杖。\", \"weapon_required\": {\"message\": \"你必须先找一条禅杖才能学伏魔杖。\", \"skill_type\": \"staff\"}}', '{\"message\": \"你按着所学练了一遍伏魔杖。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"staff\", \"parry\"]', NULL, 1, 'daemon/skill/fumo-zhang.c');
INSERT INTO `skills` VALUES (30, 'fuqin', '琴技', 'spell', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"knowledge\"]', '[\"初领妙道\", \"略通乐理\", \"精通音律\", \"高情雅致\", \"妙曲通神\", \"琴技无双\"]', 1, 'daemon/skill/fuqin.c');
INSERT INTO `skills` VALUES (31, 'ghost-steps', '鬼影迷踪步法', 'movement', '', '', '诡异飘忽的步法，如鬼魅般难以捉摸。', 100, 1, 0, 0, NULL, NULL, '', 20, 0, 0, '', '{\"always_learn\": true}', '{\"kee_cost\": 30, \"fail_message\": \"你的体力太差了，不能练鬼影迷踪。\"}', '[\"dodge\", \"move\"]', NULL, 1, 'daemon/skill/ghost-steps.c');
INSERT INTO `skills` VALUES (32, 'gouhunshu', '勾魂术', 'spell', 'ghost', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的法术修为还不够高深，无法学习勾魂术．\", \"spells_base\": 10}', NULL, '[\"spells\"]', NULL, 1, 'daemon/skill/gouhunshu.c');
INSERT INTO `skills` VALUES (33, 'hammer', '基本锤法', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/hammer.c');
INSERT INTO `skills` VALUES (34, 'hellfire-whip', '烈火鞭', 'weapon', 'ghost', '', '烈火鞭善缠绕攻敌，一旦被卷入其攻击范围则极难幸免', 100, 1, 0, 0, NULL, NULL, '', -10, -10, 20, '', '{\"max_force\": 150, \"weapon_type\": \"whip\"}', '{\"kee\": 25, \"force\": 5, \"kee_cost\": 25, \"force_cost\": 5, \"weapon_type\": \"whip\"}', '[\"whip\", \"parry\"]', NULL, 1, 'daemon/skill/hellfire-whip.c');
INSERT INTO `skills` VALUES (35, 'huaxue-blade', '化血刀法', 'weapon', 'yaomo', '', '化血刀法使动开来甚为凶险，亦善于击破敌手防卫。缺点是笨重异常。', 100, 1, 0, 0, NULL, NULL, '', 5, -10, 25, '', '{\"weapon_type\": \"blade\", \"fail_message\": \"你必须先找一把刀才能学化血刀法。\", \"required_skills\": {\"huaxue-force\": {\"formula\": \">= huaxue-blade\"}}, \"weapon_required\": {\"skill_type\": \"blade\"}}', '{\"message\": \"你按着所学练了一遍化血刀法。\", \"kee_cost\": 30, \"force_cost\": 5, \"required_skills\": {\"huaxue-force\": {\"formula\": \">= huaxue-blade\"}}, \"environment_message\": \"此地不够阴冷，再练有害无益。\", \"environment_required\": \"cold\"}', '[\"parry\", \"blade\"]', NULL, 1, 'daemon/skill/huaxue-blade.c');
INSERT INTO `skills` VALUES (36, 'huaxue-dafa', '化血大法', 'force', 'yaomo', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的法术修为还不够高深，无法学习化血大法。\", \"spells_base\": 20}', NULL, '[\"spells\"]', NULL, 1, 'daemon/skill/huaxue-dafa.c');
INSERT INTO `skills` VALUES (37, 'huaxue-force', '化血神功', 'force', 'yaomo', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"化血神功只能向师父学，或是从运用(exert)中增加熟练度。\"}', NULL, '[\"force\"]', NULL, 1, 'daemon/skill/huaxue-force.c');
INSERT INTO `skills` VALUES (38, 'huntian-hammer', '混天锤', 'weapon', 'dragon', '', '其锤法直来直去，招招为实，势大力猛，招架抵挡甚为不易', 100, 1, 0, 0, NULL, NULL, '', 15, -15, 30, '', '{\"max_force\": 50, \"weapon_type\": \"hammer\"}', '{\"kee\": 50, \"force\": 50, \"kee_cost\": 30, \"force_cost\": 5, \"weapon_type\": \"hammer\"}', '[\"hammer\", \"parry\"]', NULL, 1, 'daemon/skill/huntian-hammer.c');
INSERT INTO `skills` VALUES (39, 'huntian-qigong', '混天气功', 'force', 'yaomo', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"混天气功只能用学的，或是从运用(exert)中增加熟练度。\"}', NULL, '[\"force\"]', NULL, 1, 'daemon/skill/huntian-qigong.c');
INSERT INTO `skills` VALUES (40, 'huomoforce', '火魔心法', 'force', 'yaomo', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的杀气太低，领会不到更深层的火魔心法。\", \"bellicosity_formula\": \"skill * 10\"}', NULL, '[\"force\"]', NULL, 1, 'daemon/skill/huomoforce.c');
INSERT INTO `skills` VALUES (41, 'huoyun-qiang', '火云枪', 'movement', 'bonze', '', '火云翻滚，枪影如封墙，有若旎转钢刀般挟以万钧之势', 100, 1, 0, 0, NULL, NULL, '', 5, -10, 25, '', '{\"max_force\": 100, \"weapon_type\": \"spear\"}', '{\"kee\": 30, \"force\": 5, \"kee_cost\": 30, \"force_cost\": 5, \"weapon_type\": \"spear\"}', '[\"spear\", \"parry\"]', NULL, 1, 'daemon/skill/huoyun-qiang.c');
INSERT INTO `skills` VALUES (42, 'jadesword', '玉魔剑法', 'weapon', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 5, -10, 25, '', '{\"message\": {\"force\": \"你的真气不足，难以领悟剑法的精妙之处。\", \"weapon\": \"你必须先找一把剑才能练剑法。\"}, \"max_force\": 100, \"weapon_type\": \"sword\"}', '{\"message\": {\"kee\": \"你的气太低，再练下去会有危险的！\", \"force\": \"你的内力不够，没有办法运用玉魔剑法。\"}, \"kee_cost\": 30, \"force_cost\": 5}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/jadesword.c');
INSERT INTO `skills` VALUES (43, 'jienan-zhi', '劫难指', 'weapon', 'bonze', '', '门派绝学，指法精妙。', 100, 1, 0, 0, NULL, NULL, '', -5, -5, 20, '', '{\"no_weapon\": true, \"fail_message\": \"练劫难指必须空手。\"}', '{\"kee_cost\": 20, \"sen_cost\": 20, \"force_cost\": 10}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/jienan-zhi.c');
INSERT INTO `skills` VALUES (44, 'jindouyun', '筋斗云', 'movement', '', '', '腾云驾雾的轻功。', 100, 1, 0, 0, NULL, NULL, '', 20, 0, 0, '', '{\"max_force\": 50, \"fail_message\": \"你的内力不够，没有办法练筋斗云。\"}', '{\"kee_cost\": 30, \"force_cost\": 2, \"fail_message\": \"你的气或内力不够，不能练筋斗云。\"}', '[\"dodge\", \"move\"]', NULL, 1, 'daemon/skill/jindouyun.c');
INSERT INTO `skills` VALUES (45, 'jinghun-zhang', '惊魂掌', 'weapon', '', '', '阴森诡异的掌法，令人惊魂。', 100, 1, 0, 0, NULL, NULL, '', 5, 5, 20, '', '{\"max_force\": 50, \"no_weapon\": true, \"fail_message\": \"练惊魂掌必须空手。\"}', '{\"kee_cost\": 40, \"sen_cost\": 40, \"force_cost\": 10}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/jinghun-zhang.c');
INSERT INTO `skills` VALUES (46, 'jinglei-mace', '惊雷鞭法', 'weapon', '', '', '此鞭法讲究气势力度，为名将尉迟恭之拿手绝技，使动开来威风凛凛，势难近人。', 100, 1, 0, 0, NULL, NULL, '', -5, -5, 25, '', '{\"max_force\": 100, \"weapon_type\": \"mace\", \"fail_message\": \"手里没有兵器怎么练？\", \"weapon_required\": {\"skill_type\": \"mace\"}}', '{\"message\": \"只见一团黑影中走出$N，原来刚练完惊雷鞭法。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"mace\", \"parry\"]', NULL, 1, 'daemon/skill/jinglei-mace.c');
INSERT INTO `skills` VALUES (47, 'jueqingbian', '绝情鞭法', 'weapon', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, '{\"kee_cost\": 30}', '[\"whip\", \"parry\"]', NULL, 1, 'daemon/skill/jueqingbian.c');
INSERT INTO `skills` VALUES (48, 'kaishan-chui', '开山锤', 'weapon', '', '', '五庄观的功夫，威力巨大。', 100, 1, 0, 0, NULL, NULL, '', 7, -7, 27, '', '{\"str\": 25, \"max_force\": 100, \"str_message\": \"开山锤要身强力壮才能发挥作用。\", \"weapon_type\": \"hammer\", \"fail_message\": \"你必须先找一把锤子才能学开山锤。\", \"weapon_required\": {\"skill_type\": \"hammer\"}}', '{\"message\": \"你按着所学练了一遍开山锤。\", \"kee_cost\": 30, \"force_cost\": 5, \"str_required\": 25}', '[\"hammer\", \"parry\"]', NULL, 1, 'daemon/skill/kaishan-chui.c');
INSERT INTO `skills` VALUES (49, 'kugu-blade', '枯骨刀', 'weapon', 'wudidong', '陷空山无底洞', '无底洞之杀手绝学，刀法专注进攻，使用枯骨刀才能发挥威力', 100, 1, 0, 0, NULL, NULL, '', -5, -5, 20, '', '{\"max_force\": 350, \"weapon_type\": \"blade\", \"family_required\": \"陷空山无底洞\"}', '{\"kee\": 50, \"force\": 50, \"kee_cost\": 50, \"master_id\": \"yu shu\", \"skill_min\": 180, \"force_cost\": 30}', '[\"dodge\", \"blade\", \"parry\"]', NULL, 1, 'daemon/skill/kugu-blade.c');
INSERT INTO `skills` VALUES (50, 'kusang-bang', '哭丧棒', 'weapon', 'ghost', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, -10, 25, '', '{\"max_force\": 50, \"weapon_type\": \"stick\"}', '{\"kee_cost\": 30, \"force_cost\": 5}', '[\"stick\", \"parry\"]', NULL, 1, 'daemon/skill/kusang-bang.c');
INSERT INTO `skills` VALUES (51, 'lengquan-force', '冷泉神功', 'force', 'fighter', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"冷泉神功只能向师父学，或是从运用(exert)中增加熟练度。\"}', NULL, '[\"force\"]', NULL, 1, 'daemon/skill/lengquan-force.c');
INSERT INTO `skills` VALUES (52, 'liangyi-sword', '两仪剑法', 'weapon', '', '', '两仪剑法共八式，分为阴阳二部，威力不算强，但于内功修为颇有益处。', 100, 1, 0, 0, NULL, NULL, '', -10, -10, 15, '', '{\"max_force\": 50, \"weapon_type\": \"sword\", \"fail_message\": \"你必须先找一把剑才能练剑法。\", \"weapon_required\": {\"skill_type\": \"sword\"}}', '{\"message\": \"你按著所学练了一遍两仪剑法。\", \"kee_cost\": 30, \"force_cost\": 3, \"skill_bonus\": {\"force\": {\"chance\": {\"skill_ratio\": \"sword > force\"}}}}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/liangyi-sword.c');
INSERT INTO `skills` VALUES (53, 'lingfu-steps', '灵蝠五式', 'movement', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的内力不够，不能学习灵蝠五式的绝招。\", \"max_force\": 100}', '{\"message\": {\"kee\": \"你的气太低，再练下去太危险了！\", \"force\": \"你的内力不足，强练灵蝠五式会走火入魔。\"}, \"kee_cost\": 30, \"force_cost\": 3}', '[\"dodge\", \"move\"]', NULL, 1, 'daemon/skill/lingfu-steps.c');
INSERT INTO `skills` VALUES (54, 'literate', '读书写字', 'spell', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"literate\"]', '[\"初通文理\", \"略知一二\", \"知书达理\", \"文采斐然\", \"博学多才\", \"高才硕望\", \"饱学鸿儒\", \"学贯古今\"]', 1, 'daemon/skill/literate.c');
INSERT INTO `skills` VALUES (55, 'lotusforce', '莲花心法', 'force', 'bonze', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"莲花心法只能用学的，或是从运用(exert)中增加熟练度。\"}', NULL, '[\"force\"]', NULL, 1, 'daemon/skill/lotusforce.c');
INSERT INTO `skills` VALUES (56, 'lotusmove', '莲花步', 'movement', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的内力不够，不能够学习莲花步。\", \"max_force\": 0}', '{\"message\": \"你的气或内力不够，不能练莲花步。\", \"kee_cost\": 30, \"force_cost\": 3}', '[\"dodge\", \"move\"]', NULL, 1, 'daemon/skill/lotusmove.c');
INSERT INTO `skills` VALUES (57, 'lunhui-zhang', '轮回杖', 'weapon', 'bonze', '', '佛门看家武功，用意于以杀止杀，杖沉力猛，杀伤不弱。', 100, 1, 0, 0, NULL, NULL, '', 5, -10, 25, '', '{\"max_force\": 100, \"weapon_type\": \"staff\", \"fail_message\": \"你必须先找一条禅杖才能学轮回杖。\", \"weapon_required\": {\"skill_type\": \"staff\"}}', '{\"message\": \"你按着所学练了一遍轮回杖。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"staff\", \"parry\"]', NULL, 1, 'daemon/skill/lunhui-zhang.c');
