INSERT INTO `skills` VALUES (61, 'moondance', '冷月凝香舞', 'movement', '', '', '女儿门派的独特轻功，如月下舞蹈般轻盈。', 100, 1, 0, 0, NULL, NULL, '', 20, 0, 0, '', '{\"spi\": 10, \"gender\": \"女性\", \"spi_message\": \"你的灵性不够，没有办法练冷月凝香舞。\", \"gender_message\": \"冷月凝香舞只有女性才能练。\"}', '{\"sen_cost\": 30}', '[\"dodge\"]', NULL, 1, 'daemon/skill/moondance.c');
INSERT INTO `skills` VALUES (62, 'moonforce', '圆月心法', 'force', 'moon', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"圆月心法只能向师父学，或是从运用(exert)中增加熟练度。\"}', NULL, '[\"force\"]', NULL, 1, 'daemon/skill/moonforce.c');
