INSERT INTO `skills` VALUES (64, 'moshenbu', '魔神步法', 'movement', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的内力不够，没有办法练魔神步法。\", \"max_force\": 50}', '{\"message\": \"你的气或内力不够，不能练魔神步法。\", \"kee_cost\": 30, \"force_cost\": 2}', '[\"dodge\"]', NULL, 1, 'daemon/skill/moshenbu.c');
