INSERT INTO `skills` VALUES (66, 'moyun-shou', '摩云手', 'movement', 'yaomo', '', '快如闪电的擒拿手法。', 100, 1, 0, 0, NULL, NULL, '', 10, 10, 20, '', '{\"no_weapon\": true, \"fail_message\": \"练摩云手必须空手。\"}', '{\"message\": \"你按着所学练了一遍摩云手。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/moyun-shou.c');
