INSERT INTO `skills` VALUES (69, 'pingtian-dafa', '平天大法', 'force', 'yaomo', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"你的法术修为还不够高深，无法学习平天大法。\", \"spells_base\": 20}', NULL, '[\"spells\"]', NULL, 1, 'daemon/skill/pingtian-dafa.c');
INSERT INTO `skills` VALUES (70, 'puti-zhi', '菩提指', 'weapon', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"message\": \"练菩提指必须空手。\", \"no_weapon\": true, \"weapon_required\": false}', '{\"message\": {\"kee\": \"你现在手足酸软，休息一下再练吧。\", \"sen\": \"你的精神无法集中了，休息一下再练吧。\", \"force\": \"你的内力不够了。\"}, \"kee_cost\": 20, \"sen_cost\": 20, \"force_cost\": 10}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/puti-zhi.c');
INSERT INTO `skills` VALUES (71, 'qianjun-bang', '千钧棒法', 'weapon', 'puti', '', '', 100, 1, 0, 0, NULL, NULL, '', 10, -10, 30, '', '{\"message\": {\"force\": \"你的内力不够，没有办法练千钧棒法，多练些内力再来吧。\", \"weapon\": \"你必须先找一根棒子才能练棒法。\"}, \"max_force\": 150, \"weapon_type\": \"stick\"}', '{\"message\": \"你的内力或气不够，没有办法练习千钧棒法。\", \"kee_cost\": 30, \"force_cost\": 10}', '[\"stick\", \"parry\"]', NULL, 1, 'daemon/skill/qianjun-bang.c');
INSERT INTO `skills` VALUES (72, 'qixiu-jian', '七修剑', 'weapon', '', '陷空山无底洞', '七修剑法为拼命剑法，只求伤敌，不顾自身安危，故其突防之力颇强。', 100, 1, 0, 0, NULL, NULL, '', 5, -10, 25, '', '{\"max_force\": 100, \"weapon_type\": \"sword\", \"fail_message\": \"你必须先找一把剑才能练剑法。\", \"family_message\": \"你还未习惯血腥，无法学七修剑。\", \"family_required\": \"陷空山无底洞\", \"weapon_required\": {\"skill_type\": \"sword\"}}', '{\"message\": \"你按著所学练了一遍七修剑。\", \"kee_cost\": 30, \"force_cost\": 5, \"family_message\": \"你还未习惯血腥，无法练七修剑。\", \"family_required\": \"陷空山无底洞\"}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/qixiu-jian.c');
INSERT INTO `skills` VALUES (73, 'rake', '基本耙法', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"weapon\"]', NULL, 1, 'daemon/skill/rake.c');
INSERT INTO `skills` VALUES (74, 'sanban-axe', '宣花三斧', 'weapon', 'fighter', '将军府', '三板斧以奇见长，令人防不胜防，每斧用力甚巨，一旦砍中，杀伤巨大。', 100, 1, 0, 0, NULL, NULL, '', 20, -15, 35, '', '{\"max_force\": 200, \"axe_message\": \"手里没有斧头怎么能领悟师父所教的奥妙呢？\", \"weapon_type\": \"axe\", \"betray_check\": false, \"force_message\": \"宣花三斧需配合冷泉神功才可发挥威力。\", \"betray_message\": \"你求学之心不专，无缘学宣花三斧。\", \"family_message\": \"宣花三斧乃将军府不传之密！\", \"required_force\": \"lengquan-force\", \"family_required\": \"将军府\", \"weapon_required\": {\"skill_type\": \"axe\"}}', '{\"message\": \"你按着所学练了一遍宣花三斧。\", \"kee_cost\": 50, \"force_cost\": 30, \"weapon_type\": \"axe\", \"master_message\": \"你虽会使用宣花三斧，却不知如何练习。\", \"required_force\": \"lengquan-force\", \"family_required\": \"将军府\", \"master_required\": \"lao ren\", \"weapon_required\": {\"skill_type\": \"axe\"}}', '[\"axe\", \"parry\"]', NULL, 1, 'daemon/skill/sanban-axe.c');
INSERT INTO `skills` VALUES (75, 'sanqing-jian', '三清剑法', 'weapon', 'zhenyuan', '', '', 100, 1, 0, 0, NULL, NULL, '', -5, 15, 20, '', '{\"message\": {\"force\": \"你的内力不够，没有办法练三清剑法。\", \"weapon\": \"你必须先找一把剑才能练剑法。\"}, \"max_force\": 50, \"weapon_type\": \"sword\"}', '{\"message\": \"你的内力或气不够，没有办法练习三清剑法。\", \"kee_cost\": 30, \"force_cost\": 3}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/sanqing-jian.c');
