INSERT INTO `skills` VALUES (79, 'skyriver-rake', '天河钯法', 'weapon', '', '', '此钯为天蓬水神——猪八戒所创，与其攻守之术相比，其招架之力略胜一筹。', 100, 1, 0, 0, NULL, NULL, '', -30, -15, 25, '', '{\"max_force\": 40, \"weapon_type\": \"rake\", \"fail_message\": \"你必须先找一根钯才能练钯法。\", \"weapon_required\": {\"skill_type\": \"rake\"}}', '{\"message\": \"你按照所学练了一遍天河钯法。\", \"kee_cost\": 30, \"force_cost\": 3}', '[\"rake\", \"parry\"]', NULL, 1, 'daemon/skill/skyriver-rake.c');
INSERT INTO `skills` VALUES (80, 'snowsword', '风回雪舞剑法', 'weapon', 'moon', '', '', 100, 1, 0, 0, NULL, NULL, '', -20, -10, 15, '', '{\"message\": {\"force\": \"你的内力不够，没有办法练风回雪舞剑法。\", \"weapon\": \"你必须先找一把剑才能练剑法。\", \"force_skill\": \"风回雪舞剑法必须配合昆仑山玉女峰的圆月心法才能练。\"}, \"max_force\": 50, \"weapon_type\": \"sword\", \"force_required\": \"moonforce\"}', '{\"message\": \"你的内力或气不够，没有办法练习风回雪舞剑法。\", \"kee_cost\": 30, \"force_cost\": 3}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/snowsword.c');
INSERT INTO `skills` VALUES (81, 'snowwhip', '寒雪鞭法', 'weapon', '', '', '寒雪鞭法，以寒雪命名，凌厉狠辣。', 100, 1, 0, 0, NULL, NULL, '', -15, 0, 25, '', '{\"max_force\": 150, \"weapon_type\": \"whip\", \"fail_message\": \"你必须先找一条鞭子才能练鞭法。\", \"weapon_required\": {\"skill_type\": \"whip\"}}', '{\"message\": \"你按著所学练了一遍寒雪鞭法。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"whip\"]', NULL, 1, 'daemon/skill/snowwhip.c');
