INSERT INTO `skills` VALUES (95, 'wudi-mace', 'wudi-mace', 'basic', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, NULL, NULL, 1, 'daemon/skill/wudi-mace.c');
INSERT INTO `skills` VALUES (96, 'wuhu-blade', '五虎断门刀', 'weapon', '', '', '江湖中常见之功夫，但大多使得花梢，当非真传。其实这门功夫是相当实用的。', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 20, '', '{\"max_force\": 50, \"weapon_type\": \"blade\", \"fail_message\": \"你必须先找一把刀才能练刀法。\", \"weapon_required\": {\"skill_type\": \"blade\"}}', '{\"message\": \"$N按着所学练了一遍五虎断门刀。\", \"kee_cost\": 20, \"force_cost\": 3}', '[\"blade\", \"parry\"]', NULL, 1, 'daemon/skill/wuhu-blade.c');
INSERT INTO `skills` VALUES (97, 'wusi-mace', '无私锏法', 'weapon', '', '', '原名秦家无敌锏，为秦家祖传秘技，皇上感其无私，赐名无私锏法。相当实用，上阵杀敌，势如破竹。', 100, 1, 0, 0, NULL, NULL, '', 5, -5, 25, '', '{\"max_force\": 150, \"weapon_type\": \"mace\", \"fail_message\": \"你必须先找一柄锏才能练锏法。\", \"weapon_required\": {\"skill_type\": \"mace\"}}', '{\"message\": \"$N运起内力练了一套无私锏法。\", \"kee_cost\": 30, \"force_cost\": 5, \"force_message\": \"无私锏需配合将军府冷泉神功才可发挥威力。\", \"required_force\": \"lengquan-force\"}', '[\"mace\", \"parry\"]', NULL, 1, 'daemon/skill/wusi-mace.c');
INSERT INTO `skills` VALUES (98, 'wuxiangforce', '小无相功', 'force', 'puti', '', '小无相功是道家上乘内功，以柔克刚，变化无穷', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', NULL, NULL, '[\"force\"]', NULL, 1, 'daemon/skill/wuxiangforce.c');
INSERT INTO `skills` VALUES (99, 'wuxing-quan', '五行拳', 'weapon', '', '', '模仿五行之理的拳法。', 100, 1, 0, 0, NULL, NULL, '', 5, 5, 20, '', '{\"no_weapon\": true, \"fail_message\": \"练五行拳必须空手。\"}', '{\"kee_cost\": 30, \"sen_cost\": 30, \"force_cost\": 10}', '[\"unarmed\"]', NULL, 1, 'daemon/skill/wuxing-quan.c');
INSERT INTO `skills` VALUES (100, 'xiaofeng-sword', '晓风残月剑', 'weapon', 'zhenyuan', '将军府', '此剑法用意高妙，轻巧潇洒，剑中颇含诗意，多为江湖年少所喜。', 100, 1, 0, 0, NULL, NULL, '', -10, 0, 20, '', '{\"max_force\": 100, \"weapon_type\": \"sword\", \"fail_message\": \"你的内力修为不够深，不能学晓风残月剑。\", \"weapon_required\": {\"message\": \"你必须先找一柄长剑才能练习剑法。\", \"skill_type\": \"sword\"}}', '{\"message\": \"$N默默回忆了一会儿，然后练了一遍晓风残月剑。\", \"kee_cost\": 30, \"force_cost\": 5}', '[\"sword\", \"parry\"]', NULL, 1, 'daemon/skill/xiaofeng-sword.c');
INSERT INTO `skills` VALUES (101, 'xiaoyaoyou', '逍遥游', 'movement', '', '', '', 100, 1, 0, 0, NULL, NULL, '', 0, 0, 0, '', '{\"max_force\": 0}', '{\"kee_cost\": 30, \"force_cost\": 3}', '[\"dodge\", \"move\"]', NULL, 1, 'daemon/skill/xiaoyaoyou.c');
